COLLDATA("abudawud","ur",[[2215,"اس سند سے بھی ابن اسحاق سے اسی طرح کی روایت منقول ہے لیکن اس میں ہے کہ «عرق» ایسی زنبیل ہے جس میں تیس صاع کے بقدر کھجور آتی ہے۔ ابوداؤد کہتے ہیں: یہ حدیث یحیی بن آدم کی روایت کے مقابلے میں زیادہ صحیح ہے۔","حسن",{"u2":"ابن اسحاق نے اسی سند سے مذکورہ روایت کی مانند روایت کیا مگر کہا کہ «العرق» وہ ٹوکرا ہوتا ہے جس میں تیس صاع کھجور آتی ہے۔ امام ابوداؤد رضی اللہ عنہ فرماتے ہیں: یہ روایت یحییٰ بن آدم کی (مذکورہ بالا) روایت سے زیادہ صحیح ہے۔","f2":"(العرق) ٹوکرے کی مقدار ان روایات میں ساٹھ صاع یا تیس صاع راجح نہیں ہے۔جیسے کہ علامہ البانی رحمہ اللہ نے لکھا ہے۔صحیح مقدار اگلی روایت میں مذکور ہے یعنی پندرہ صاع۔اسی طرح حدیث:2393میں بھی مروی ہے۔"}],[2216,"ابوسلمہ بن عبدالرحمٰن بن عوف زہری کہتے ہیں کہ «عرق» سے مراد ایسی زنبیل ہے جس میں پندرہ صاع کھجوریں آ جائیں ۔","صحیح",{"u2":"ابوسلمہ بن عبدالرحمٰن نے کہا: «العرق» سے مراد ایسا ٹوکرا ہوتا ہے جس میں پندرہ صاع کھجور آتی ہے۔"}],[2217,"سلیمان بن یسار سے یہی حدیث مروی ہے اس میں ہے: آپ صلی اللہ علیہ وسلم کے پاس کھجوریں آئیں تو آپ نے وہ انہیں دے دیں، وہ تقریباً پندرہ صاع تھیں، آپ صلی اللہ علیہ وسلم نے فرمایا: \"انہیں صدقہ کر دو\"، انہوں نے کہا: اللہ کے رسول! مجھ سے اور میرے گھر والوں سے زیادہ کوئی ضرورت مند نہیں، آپ صلی اللہ علیہ وسلم نے فرمایا: \"تم اور تمہارے گھر والے ہی انہیں کھا لو\"۔","حسن",{"u2":"سلیمان بن یسار نے یہ خبر بیان کی اور کہا کہ رسول اللہ صلی اللہ علیہ وسلم کے پاس کھجور لائی گئی، آپ نے یہ اسے دے دی جو پندرہ صاع کے قریب تھی اور فرمایا ” اسے صدقہ کر دو۔ “ تو اس نے کہا: اے اللہ کے رسول! کیا اپنے اور اپنے گھر والوں سے زیادہ فقیر لوگوں پر صدقہ کروں؟ آپ صلی اللہ علیہ وسلم نے فرمایا ” تم کھا لو اور تمہارے گھر والے۔ “","f2":"ان کا یہ مطلب تھا کہ غربت کے لحاظ سے ہم سے زیادہ اس صدقے کا مستحق اور کوئی نہیں۔"}],[2218,"عبادہ بن صامت رضی اللہ عنہ کے بھائی اوس رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے انہیں پندرہ صاع جو دی تاکہ ساٹھ مسکینوں کو کھلا دیں۔ ابوداؤد کہتے ہیں: عطا نے اوس کو نہیں پایا ہے اور وہ بدری صحابی ہیں ان کا انتقال بہت پہلے ہو گیا تھا، لہٰذا یہ حدیث مرسل ہے، اور لوگوں نے اسے اوزاعی سے اوزاعی نے عطاء سے روایت کیا اس میں «عن أوس» کے بجائے «أوسا» ہے۔","صحیح",{"u2":"جناب عطاء، سیدنا عبادہ بن صامت رضی اللہ عنہ کے بھائی اوس رضی اللہ عنہ سے روایت کرتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم نے ان کو پندرہ صاع ” جَو “ عنایت کیے تھے، یعنی ساٹھ مسکینوں کا کھانا۔ امام ابوداؤد رضی اللہ عنہ بیان کرتے ہیں کہ عطاء کی اوس سے ملاقات نہیں ہے۔ اور یہ (اوس) اہل بدر میں سے تھے، ان کی وفات بہت پہلے ہو گئی تھی۔ اور یہ حدیث مرسل ہے۔ محدثین اسے اوزاعی سے بواسطہ عطاء اور وہ اوس سے روایت کرتے ہیں۔","f2":"گویایہ روایت جس میں جو کا ذکر ہے صحیح نہیں ہےبلکہ منقطع ہے۔محدثین کے نزدیک مرسل اور منقطع ہم معنی ہیں۔(عون المعبود)"}],[2219,"ہشام بن عروہ سے روایت ہے کہ جمیلہ رضی اللہ عنہا اوس بن صامت رضی اللہ عنہ کے نکاح میں تھیں، اور وہ عورتوں کے دیوانے تھے جب ان کی دیوانگی بڑھ جاتی تو وہ اپنی عورت سے ظہار کر لیتے، اللہ تعالی نے انہیں کے متعلق ظہار کے کفارے کا حکم نازل فرمایا۔","صحیح",{"u2":"ہشام بن عروہ سے روایت ہے کہ جمیلہ، سیدنا اوس بن صامت کی زوجیت میں تھی اور اوس میں جنسی شہوت کا مادہ زیادہ تھا، جب ان پر اس کا غلبہ ہوتا تو وہ اپنی بیوی سے ظہار کر لیا کرتے تھے۔ تو اللہ تعالیٰ نے ان کے مسئلے میں ظہار کے کفارہ کا حکم نازل فرمایا تھا۔","f2":"یہ جمیلہ وہی خاتون ہیں جن کا ذکر پہلے خویلہ کے نام سےآیا ہے۔یاتوان کے دوہی نام تھےیاجمیلہ انہیں ان کی خوبصورتی کی وجہ سے کہا گیا ہے۔(عون المعبود) واللہ اعلم۔"}],[2220,"ام المؤمنین عائشہ رضی اللہ عنہا سے بھی اسی کے مثل مروی ہے۔","صحیح",{"u2":"حماد بن سلمہ نے ہشام بن عروہ سے، انہوں نے عروہ سے، انہوں نے سیدہ عائشہ رضی اللہ عنہا ا سے۔ اسی کے مثل روایت کی ہے۔"}],[2221,"عکرمہ سے روایت ہے کہ ایک شخص نے اپنی بیوی سے ظہار کر لیا، پھر کفارہ ادا کرنے سے پہلے ہی وہ اس سے صحبت کر بیٹھا چنانچہ وہ نبی اکرم صلی اللہ علیہ وسلم کے پاس آیا اور آپ کو اس کی خبر دی، تو آپ صلی اللہ علیہ وسلم نے فرمایا: \"تمہیں اس فعل پر کس چیز نے آمادہ کیا؟\" اس نے کہا: چاندنی رات میں میں نے اس کی پنڈلی کی سفیدی دیکھی، آپ صلی اللہ علیہ وسلم نے فرمایا: \"پھر تم اس سے اس وقت تک الگ رہو جب تک کہ تم اپنی طرف سے کفارہ ادا نہ کر دو\"۔","صحیح",{"u2":"جناب عکرمہ (مولیٰ ابن عباس رضی اللہ عنہ) سے منقول ہے کہ ایک شخص نے اپنی بیوی سے ظہار کر لیا، پھر کفارہ ادا کرنے سے پہلے اس کے ساتھ ہمبستر بھی ہو گیا، اس کے بعد نبی کریم صلی اللہ علیہ وسلم کے پاس آیا اور اپنا واقعہ بیان کیا۔ آپ صلی اللہ علیہ وسلم نے پوچھا ” تو نے ایسا کیوں کیا؟ “ کہنے لگا: میں نے چاندنی میں اس کی پنڈلیوں کی سفیدی دیکھ لی تھی۔ آپ صلی اللہ علیہ وسلم نے فرمایا ” تو پھر اب اس سے دور رہنا حتیٰ کہ اپنا کفارہ دے لے۔ “","f2":"ظہار میں کفارہ ادا کرنے سے پہلے قربت جائز نہیں ہے۔"}],[2222,"عکرمہ سے روایت ہے کہ ایک شخص نے اپنی بیوی سے ظہار کر لیا، پھر اس نے چاندنی میں اس کی پنڈلی کی چمک دیکھی، تو اس سے صحبت کر بیٹھا، پھر وہ نبی اکرم صلی اللہ علیہ وسلم کے پاس آیا تو آپ نے اسے کفارہ ادا کرنے کا حکم فرمایا۔","صحیح",{"u2":"جناب عکرمہ رضی اللہ عنہ سے مروی ہے کہ ایک شخص نے اپنی بیوی سے ظہار کر لیا، پھر چاند کی چاندنی میں اس کی پنڈلی کی سفیدی دیکھی تو اس سے مجامعت کر بیٹھا، تب نبی کریم صلی اللہ علیہ وسلم کی خدمت میں آیا، تو آپ صلی اللہ علیہ وسلم نے اس کو کفارہ ادا کرنے کا حکم دیا۔"}],[2223,"اس سند سے ابن عباس رضی اللہ عنہما سے مرفوعاً اسی طرح روایت ہے لیکن اس میں پنڈلی کا ذکر نہیں ہے۔","صحیح",{"u2":"جناب عکرمہ رضی اللہ عنہ سیدنا ابن عباس رضی اللہ عنہ سے وہ نبی کریم صلی اللہ علیہ وسلم سے، اسی کی مثل بیان کرتے ہیں، مگر اس میں (اسماعیل راوی نے) ” پنڈلی “ کا ذکر نہیں کیا۔"}],[2224,"اس سند سے بھی عکرمہ سے سفیان کی حدیث (نمبر: ۲۲۲۱) کی طرح روایت ہے۔","صحیح",{"u2":"جناب عکرمہ رضی اللہ عنہ، نبی کریم صلی اللہ علیہ وسلم سے بیان کرتے ہیں جیسے کہ سفیان (بن عیینہ) کی روایت میں ذکر ہوا ہے۔"}],[2225,"ابوداؤد کہتے ہیں: میں نے محمد بن عیسی کو اسے بیان کرتے سنا ہے، وہ کہتے ہیں ہم سے معتمر نے بیان کیا وہ کہتے ہیں: میں نے حکم بن ابان کو یہی حدیث بیان کرتے ہوئے سنا ہے وہ اسے عکرمہ سے روایت کر رہے تھے اس میں انہوں نے ابن عباس رضی اللہ عنہما کا ذکر نہیں کیا ہے۔ ابوداؤد کہتے ہیں: مجھے حسین بن حریث نے لکھا وہ کہتے ہیں کہ مجھے فضل بن موسی نے خبر دی ہے وہ معمر سے وہ حکم بن ابان سے وہ عکرمہ سے وہ ابن عباس رضی اللہ عنہما سے وہ نبی اکرم صلی اللہ علیہ وسلم سے اسی مفہوم کی حدیث روایت کرتے ہیں۔","صحیح",{"u2":"امام ابوداؤد رضی اللہ عنہ فرماتے ہیں کہ میں نے محمد بن عیسیٰ کو یہ روایت بیان کرتے سنا، وہ اسے بواسطہ معتمر، حکم بن ابان سے روایت کرتے تھے اور اس میں ابن عباس رضی اللہ عنہ کا ذکر نہیں کیا۔ (بلکہ عکرمہ سے روایت کی ہے، یعنی سند مرسل ہے۔)۔\nامام ابوداؤد رضی اللہ عنہ فرماتے ہیں حسین بن حریث نے مجھے اس روایت کی یہ سند لکھ بھیجی (جو کہ مسند ہے) ہمیں فضل بن موسیٰ نے خبر دی معمر سے، وہ حکم بن ابان سے، وہ عکرمہ سے، وہ ابن عباس رضی اللہ عنہ سے۔ انہوں نے (مذکورہ بالا حدیث کے ہم معنی) نبی کریم صلی اللہ علیہ وسلم سے بیان کیا۔"}],[2226,"ثوبان رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جس عورت نے اپنے شوہر سے بغیر کسی ایسی تکلیف کے جو اسے طلاق لینے پر مجبور کرے طلاق کا مطالبہ کیا تو اس پر جنت کی خوشبو حرام ہے\"۔","صحیح",{"u2":"سیدنا ثوبان بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” جو عورت بغیر کسی وجہ کے اپنے شوہر سے طلاق مانگتی ہے اس پر جنت کی خوشبو حرام ہے۔ “","f2":"اگر زوجین میں ہم آہنگی نہ رہےاور شوہراپنی بیوی کو طلاق دینے پر راضی نہ ہو جب کہ عورت اس کے پاس رہنے کے لیے تیار نہ ہو بلکہ علیحدگی پر مصر ہوتو اپنا معاملہ قاضی کے سامنے پیش کرے۔وہ احوال واقعی کے پیش نظر عورت کے مطالبہء علیحدگی کی بناء پر عورت سے کہے کہ اپنا حق مہر واپس کرے اور پھر وہ انکے مابین عقد نکاح کو فسخ کردے۔تو علیحدگی کی اس کیفیت کو خلع کہتے ہیں۔طلاق شوہر کی طرف سے ہوتی ہے اور خلع میں مطالبہ بیوی کی طرف سے ہوتا ہے۔اور قاضی اپنے فیصلہ تنسیخ کی تنفیذ کراتا ہے۔خلع میں عدت صرف ایک حیض ہے۔کیونکہ یہ فسخ نکاح ہے۔"}],[2227,"حبیبہ بنت سہل انصاریہ رضی اللہ عنہا سے روایت ہے کہ وہ ثابت بن قیس بن شماس رضی اللہ عنہ کے نکاح میں تھیں، ایک بار کیا ہوا کہ رسول اللہ صلی اللہ علیہ وسلم فجر پڑھنے کے لیے نکلے تو آپ نے حبیبہ بنت سہل کو اندھیرے میں اپنے دروازے پر پایا، آپ صلی اللہ علیہ وسلم نے پوچھا: \"کون ہے؟\" بولیں: میں حبیبہ بنت سہل ہوں، آپ صلی اللہ علیہ وسلم نے فرمایا: \"کیا بات ہے؟\" وہ اپنے شوہر ثابت بن قیس کے متعلق بولیں کہ میرا ان کے ساتھ گزارا نہیں ہو سکتا، پھر جب ثابت بن قیس آئے تو رسول اللہ صلی اللہ علیہ وسلم نے ان سے فرمایا: \"یہ حبیبہ بنت سہل ہیں انہوں نے مجھ سے بہت سی باتیں جنہیں اللہ نے چاہا ذکر کی ہیں\"، حبیبہ کہنے لگیں: اللہ کے رسول! انہوں نے جو کچھ مجھے (مہر وغیرہ) دیا تھا وہ سب میرے پاس ہے، چنانچہ آپ صلی اللہ علیہ وسلم نے ثابت بن قیس سے کہا: \"اس (مال) میں سے لے لو\"، تو انہوں نے اس میں سے لے لیا اور وہ اپنے گھر والوں کے پاس بیٹھی رہیں ۱؎۔\n§وضاحت\n۱؎ : یہی اسلام میں پہلا خلع تھا ، خلع سے نکاح منسوخ ہو جاتا ہے، خلع کی عدت ایک حیض ہے، بعض علماء کے نزدیک خلع سے ایک طلاق پڑ جاتی ہے، اس لئے ان لوگوں کے نزدیک اس کی عدت طلاق کی عدت کی طرح ہے ، یعنی تین حیض ہے ، پہلا قول راجح ہے۔","صحیح",{"u2":"عمرہ بنت عبدالرحمٰن، حبیبہ بنت سہل انصاریہ رضی اللہ عنہا ا کے متعلق بیان کرتی ہیں کہ یہ سیدنا ثابت بن قیس بن شماس رضی اللہ عنہ کی زوجیت میں تھی۔ رسول اللہ صلی اللہ علیہ وسلم فجر کی نماز کے لیے جانے لگے تو آپ نے حبیبہ بنت سہل کو اندھیرے میں اپنے دروازے کے پاس کھڑے پایا۔ رسول اللہ صلی اللہ علیہ وسلم نے پوچھا ” یہ کون ہے؟ “ اس نے کہا: میں حبیبہ بنت سہل ہوں۔ آپ نے پوچھا ” کیا بات ہے؟ “ کہنے لگی میں نہیں اور ثابت بن قیس نہیں! یعنی اپنے شوہر کے متعلق کہا۔ (مطلب یہ تھا کہ ہم دونوں کا اکٹھا رہنا ممکن نہیں) پھر جب سیدنا ثابت بن قیس آئے تو رسول اللہ صلی اللہ علیہ وسلم نے ان سے کہا: ” حبیبہ بنت سہل آئی ہے اور اللہ تعالیٰ کو جو کچھ منظور تھا اس نے مجھ سے بیان کیا۔ “ حبیبہ نے کہا: اے اللہ کے رسول! جو کچھ انہوں نے مجھے دیا ہے وہ سب میرے پاس ہے۔ تو رسول اللہ صلی اللہ علیہ وسلم نے ثابت بن قیس سے فرمایا ” اس سے وصول کر لو۔ “ چنانچہ انہوں نے مال لے لیا اور پھر وہ اپنے گھر والوں کے ہاں بیٹھ رہی۔"}],[2228,"ام المؤمنین عائشہ رضی اللہ عنہا سے روایت ہے کہ حبیبہ بنت سہل رضی اللہ عنہا ثابت بن قیس بن شماس رضی اللہ عنہ کے نکاح میں تھیں تو ان کو ان کے شوہر نے اتنا مارا کہ کوئی عضو ٹوٹ گیا، وہ فجر کے بعد رسول اللہ صلی اللہ علیہ وسلم کے پاس آئیں اور آپ سے ان کی شکایت کی تو نبی اکرم صلی اللہ علیہ وسلم نے ثابت کو بلوایا، اور کہا کہ تم اس سے کچھ مال لے کر اس سے الگ ہو جاؤ، ثابت نے کہا: اللہ کے رسول! کیا ایسا کرنا درست ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا: \"ہاں\"، وہ بولے، میں نے اسے دو باغ مہر میں دیئے ہیں یہ ابھی بھی اس کے پاس موجود ہیں، آپ صلی اللہ علیہ وسلم نے فرمایا: \"انہیں لے لو اور اس سے جدا ہو جاؤ\"، چنانچہ انہوں نے ایسا ہی کیا۔","صحیح",{"u2":"ام المؤمنین سیدہ عائشہ رضی اللہ عنہا ا سے مروی ہے کہ حبیبہ بنت سہل، سیدنا ثابت بن قیس بن شماس کی زوجیت میں تھی تو ثابت نے اس کو مارا اور اس کا کچھ توڑ بھی دیا، تب وہ فجر کے بعد رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں آئی اور شوہر کی شکایت کی۔ پس نبی کریم صلی اللہ علیہ وسلم نے ثابت کو بلایا اور فرمایا ” اس سے کچھ مال لے لو اور اس کو علیحدہ کر دو۔ “ انہوں نے کہا: اے اللہ کے رسول! کیا یہ صحیح ہے؟ آپ نے فرمایا ” ہاں۔ “ انہوں نے کہا: میں نے اس کو مہر میں دو باغ دیے ہیں اور وہ اسی کے قبضے میں ہیں۔ نبی کریم صلی اللہ علیہ وسلم نے فرمایا ” وہ دونوں لے لو اور اسے علیحدہ کر دو۔“ چنانچہ انہوں نے ایسے ہی کیا۔"}],[2229,"عبداللہ بن عباس رضی اللہ عنہما سے روایت ہے کہ ثابت بن قیس رضی اللہ عنہ کی بیوی نے ان سے خلع کر لیا تو نبی اکرم صلی اللہ علیہ وسلم نے اس کی عدت ایک حیض مقرر فرمائی۔ ابوداؤد کہتے ہیں: اس حدیث کو عبدالرزاق نے معمر سے معمر نے عمرو بن مسلم سے عمرو نے عکرمہ سے اور عکرمہ نے نبی اکرم صلی اللہ علیہ وسلم سے مرسلاً روایت کیا۔","صحیح",{"u2":"سیدنا ابن عباس رضی اللہ عنہ کا بیان ہے کہ ثابت بن قیس رضی اللہ عنہ کی بیوی نے ان سے خلع لیا تو نبی کریم صلی اللہ علیہ وسلم نے اس کی عدت ایک حیض مقرر فرمائی تھی۔ امام ابوداؤد رضی اللہ عنہ کہتے ہیں کہ اس حدیث کو عبدالرزاق نے معمر سے، انہوں نے عمرو بن مسلم سے، انہوں نے عکرمہ سے، انہوں نے نبی کریم صلی اللہ علیہ وسلم سے مرسل بیان کیا ہے۔"}],[2230,"عبداللہ بن عمر رضی اللہ عنہما سے مروی ہے کہ خلع کرانے والی عورت کی عدت ایک حیض ہے۔","صحیح",{"u2":"سیدنا ابن عمر رضی اللہ عنہ سے مروی ہے کہ خلع والی عورت کی عدت ایک حیض ہے۔"}],[2231,"عبداللہ بن عباس رضی اللہ عنہما سے روایت ہے کہ مغیث رضی اللہ عنہ ایک غلام تھے وہ کہنے لگے: اللہ کے رسول! اس سے میری سفارش کر دیجئیے، آپ صلی اللہ علیہ وسلم نے فرمایا: \"بریرہ! اللہ سے ڈرو، وہ تمہارا شوہر ہے اور تمہارے لڑکے کا باپ ہے\" کہنے لگیں: اللہ کے رسول! کیا آپ مجھے ایسا کرنے کا حکم فرما رہے ہیں؟ آپ صلی اللہ علیہ وسلم نے فرمایا: \"نہیں بلکہ میں تو سفارشی ہوں\" مغیث کے آنسو گالوں پر بہہ رہے تھے تو رسول اللہ صلی اللہ علیہ وسلم نے عباس رضی اللہ عنہ سے کہا: \"کیا آپ کو مغیث کی بریرہ کے تئیں محبت اور بریرہ کی مغیث کے تئیں نفرت سے تعجب نہیں ہو رہا ہے؟\"۔","صحیح",{"u2":"سیدنا ابن عباس رضی اللہ عنہ سے مروی ہے کہ مغیث غلام تھے۔ کہنے لگے: اے اللہ کے رسول! میرے بارے میں اس کو سفارش فر دیجئیے تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” اے بریرہ! اللہ سے ڈر، بلاشبہ وہ تیرا شوہر ہے اور تیرے بچے کا باپ بھی ہے۔ “ وہ کہنے لگی: اے اللہ کے رسول! کیا آپ اس کے بارے میں مجھے حکماً ارشاد فرماتے ہیں؟ آپ صلی اللہ علیہ وسلم نے فرمایا ” نہیں، میں صرف سفارشی ہوں۔ “ چنانچہ اس (مغیث) کے آنسو اس کے رخساروں پر بہتے تھے۔ (وہ روتا پھرتا تھا) تو رسول اللہ صلی اللہ علیہ وسلم نے عباس رضی اللہ عنہ سے فرمایا ” کس قدر تعجب کی بات ہے کہ مغیث کو بریرہ سے کتنی محبت ہے اور اس کو اس سے کتنا بغض ہے۔ “","f2":"1۔غلام اور لونڈی اگر عقد زوجیت میں منسلک ہوں لیکن لونڈی کو پہلے آزادیمل جائےتو اسے اپنے (غلام) شوہر کی زوجیت میں رہنے یانہ رہنے کا اختیار حاصل ہے۔اگر شوہر پہلے آزاد ہوجائےتو بیوی کو کوئی اختیار نہیں ہوتا۔درج ذیل احادیث میں مذکورہواقعہ بریرہ (لونڈی)اور اس کے شوہر مغیث(غلام)کا ہے۔\nبریرہ رضی اللہ عنہ کو حضرت عائشہ رضی اللہ عنہ نے پہلے آزاد کردیا تھاجبکہ مغیث رضی اللہ عنہ غلام ہی رہے تھے۔\n2۔بریرہ رضی اللہ عنہ جیسی عورت جسے ایک صحیح حدیث میں ناقص العلقل کہا گیا ہے دین کے معاملے میں کس قدر دانا تھیں۔وہ جانتی تھیں کہ رسول اللہ صلی اللہ علیہ وسلم کا حکم ٹال دینادین ودنیا کا خسارا ہےمگر جب آپ صلی اللہ علیہ وسلم نے وضاحت فرمائی کہ میری یہ بات حکم نہیں محض سفارش ہے تو انہوں نے شرعاً حاصل شدہ اختیار کو ترجیح دی۔اس واقعہ میں حریت فکر کا درس ہے اور اور یہ بھی کہ یہ آزادی اللہ کے دین اور رسول اللہ صلی اللہ علیہ وسلم کی اطاعت سے مشروط ہے کیونکہ اللہ تعالی انسان کا خالق ہے اور رسول اللہ صلی اللہ علیہ وسلم اللہ کے پیامبر ہیں۔"}],[2232,"عبداللہ بن عباس رضی اللہ عنہما سے روایت ہے کہ بریرہ رضی اللہ عنہا کے شوہر ایک کالے کلوٹے غلام تھے جن کا نام مغیث رضی اللہ عنہ تھا، تو نبی اکرم صلی اللہ علیہ وسلم نے انہیں (مغیث کے ساتھ رہنے یا نہ رہنے کا) اختیار دیا اور (نہ رہنے کی صورت میں) انہیں عدت گزارنے کا حکم فرمایا۔","صحیح",{"u2":"سیدنا ابن عباس رضی اللہ عنہ سے منقول ہے کہ بریرہ رضی اللہ عنہا ا کا خاوند کالے رنگ کا غلام تھا، جس کا نام مغیث تھا۔ رسول اللہ صلی اللہ علیہ وسلم نے بریرہ کو اختیار دیا تھا۔ (اپنے شوہر کی زوجیت میں رہے یا اس سے آزاد ہو جائے) اور اسے حکم دیا تھا کہ عدت گزارے۔","f2":"صحیح حدیث میں ہے کہ اسے تین حیض عدت گزارنے کا حکم دیا گیا تھا۔(سنن ابن ماجہ الطلاق حدیث2077) کیونکہ وہ آزاد ہوچکی تھی۔"}],[2233,"ام المؤمنین عائشہ رضی اللہ عنہا سے بریرہ کے قصہ میں روایت ہے کہ اس کا شوہر غلام تھا، رسول اللہ صلی اللہ علیہ وسلم نے بریرہ کو(آزاد ہونے کے بعد) اختیار دے دیا تو انہوں نے اپنے آپ کو اختیار کیا، اگر وہ آزاد ہوتا تو آپ اسے (بریرہ کو) اختیار نہ دیتے۔","صحیح",{"u2":"ام المؤمنین سیدہ عائشہ رضی اللہ عنہا ا بریرہ کے قصے میں بیان کرتی ہیں کہ اس کا شوہر غلام تھا۔ رسول اللہ صلی اللہ علیہ وسلم نے بریرہ کو اختیار دیا تو اس نے اپنے آپ کو اختیار کر لیا۔ اگر شوہر آزاد ہوتا تو اس کو اختیار نہ دیتے۔","f2":"شیخ البانی رحمہ اللہ کہتے ہیں کہ حدیث میں آخری جملہ: اگر شوہر آزاد ہوتا۔۔۔۔ مدرج ہے جو کہ عروہ کا قول ہے۔(صحیح سنن ابی داود للالبانی حدیث:2233) تاہم مسئلے کی نوعیت یہی ہے کہ اگر شوہر آزاد ہو تو پھر لونڈی کو اختیار حاصل نہیں ہوگا۔"}],[2234,"ام المؤمنین عائشہ رضی اللہ عنہا سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے بریرہ کو اختیار دیا اس کا شوہر غلام تھا۔","صحیح",{"u2":"ام المؤمنین سیدہ عائشہ رضی اللہ عنہا ا سے مروی ہے کہ بریرہ کو رسول اللہ صلی اللہ علیہ وسلم نے اختیار دیا تھا، جبکہ اس کا شوہر غلام تھا۔"}],[2235,"ام المؤمنین عائشہ رضی اللہ عنہا سے روایت ہے کہ جس وقت بریرہ رضی اللہ عنہا آزاد ہوئی اس وقت اس کا شوہر آزاد ۱؎ تھا، اسے اختیار دیا گیا، تو اس نے کہا کہ اگر مجھے اتنا اتنا مال بھی مل جائے تب بھی میں اس کے ساتھ رہنا پسند نہ کروں گی۔\n§وضاحت\n۱؎ : صحیح یہ ہے کہ وہ اس وقت غلام تھے جیسا کہ متعدد صحیح روایتیں اوپر گزریں۔","صحیح",{"u2":"اسود بن یزید، سیدہ عائشہ رضی اللہ عنہا ا سے بیان کرتے ہیں کہ بریرہ کو جب آزاد کیا گیا تو اس کا شوہر بھی آزاد تھا۔ اور بریرہ کو اختیار دیا گیا تو وہ کہنے لگی: میں اس کے ساتھ رہنا پسند نہیں کرتی خواہ مجھے اس اس قدر (مال) بھی کیوں نہ دے دیا جائے۔","f2":"شیخ البانی رحمہ اللہ کے نزدیک (کان حرا) وہ آزاد تھا کا جملہ اسود بن یزید کا کلام ہے اور بقول امام بخاری منقطع ہے جبکہ حضرت ابن عباس رضی اللہ عنہ کا بیان ہے کہ اس کا شوہر گلام تھا:صحیح تر ہے۔دیکھیے (صحیح البخاری الطلاق حدیث:5282)"}],[2236,"ام المؤمنین عائشہ رضی اللہ عنہا سے روایت ہے کہ بریرہ رضی اللہ عنہا آزاد کی گئی اس وقت وہ آل ابواحمد کے غلام مغیث رضی اللہ عنہ کے نکاح میں تھی تو رسول اللہ صلی اللہ علیہ وسلم نے اسے اختیار دیا اور اس سے کہا: \"اگر اس نے تجھ سے صحبت کر لی تو پھر تجھے اختیار حاصل نہیں رہے گا\"۔","حسن",{"u2":"ام المؤمنین سیدہ عائشہ رضی اللہ عنہا ا سے مروی ہے کہ بریرہ کو آزاد کیا گیا تو وہ مغیث کی زوجیت میں تھی جو کہ آل ابی احمد کا غلام تھا، تو رسول اللہ صلی اللہ علیہ وسلم نے اس کو اختیار دے دیا اور فرمایا ” اگر وہ تم سے قریب ہو گیا تو تمہارا اختیار باقی نہیں رہے گا۔ “","f2":"یہ روایت ضعیف ہے اس سے یہ مسئلہ ثابت نہیں ہوتاکہ آزاد ہونے والی لونڈی نے آزاد ہونے کے بعد اپنے خاوند سے تعلق زوجیت قائم کرلیا تو اس کا اختیار ختم ہوجائے گا۔"}],[2237,"ام المؤمنین عائشہ رضی اللہ عنہا سے روایت ہے کہ انہوں نے اپنے لونڈی غلام کے ایک جوڑے کو آزاد کرنا چاہا تو نبی اکرم صلی اللہ علیہ وسلم سے اس کے متعلق دریافت کیا تو آپ نے حکم دیا کہ وہ عورت سے پہلے مرد کو آزاد کریں۔","ضعیف",{"u2":"ام المؤمنین سیدہ عائشہ رضی اللہ عنہا ا سے مروی ہے کہ انہوں نے اپنے ایک مملوک جوڑے کو آزاد کرنے کا ارادہ کیا تو انہوں نے نبی کریم صلی اللہ علیہ وسلم سے اس بارے میں پوچھا، آپ نے حکم دیا ” عورت سے پہلے مرد کو آزاد کرنے سے ابتداء کرنا۔ “ نصر بن علی کی سند اس طرح ہے «أخبرني أبو علي الحنفي، عن عبيد الله»۔"}],[2238,"عبداللہ بن عباس رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم کے زمانے میں ایک شخص مسلمان ہو کر آیا پھر اس کے بعد اس کی بیوی بھی مسلمان ہو کر آ گئی، تو اس نے کہا: اللہ کے رسول! یہ میرے ساتھ ہی مسلمان ہوئی ہے تو آپ اسے میرے پاس لوٹا دیجئیے۔","ضعیف",{"u2":"سیدنا ابن عباس رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم کے دور میں ایک شخص مسلمان ہو کر آیا۔ پھر اس کے بعد اس کی بیوی بھی مسلمان ہو کر آ گئی تو اس شخص نے کہا: اے اللہ کے رسول! یہ عورت بھی میرے ساتھ ہی مسلمان ہوئی ہے۔ تو آپ صلی اللہ علیہ وسلم نے اس کو اس (کے شوہر) کی طرف لوٹا دیا۔","f2":"ایام کفر وشرک کے نکاح بعد از اسلام بھی صحیح سمجھے جاتے ہیں۔تجدید کی قطعاً کوئی ضرورت نہیں الا یہ کہ کسی واضح حرمت کا ارتکاب ہواہو۔مثلاً کسی محرم نسبی یا رضاعی سے نکاح کیا ہوتو فسخ ہوجائے گاورنہ نہیں۔جیسے کہ آگے تفصیل آرہی ہے۔تاہم باعتبار سند یہ روایت ضعیف ہے۔(ارواء الغلیل حدیث:1918)"}],[2239,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم کے زمانے میں ایک عورت مسلمان ہو گئی اور اس نے نکاح بھی کر لیا، اس کے بعد اس کا شوہر رسول اللہ صلی اللہ علیہ وسلم کے پاس آیا، اور کہنے لگا: اللہ کے رسول! میں اسلام لے آیا تھا اور اسے میرے اسلام لانے کا علم تھا چنانچہ رسول اللہ صلی اللہ علیہ وسلم نے دوسرے شوہر سے اسے چھین کر اس کے پہلے شوہر کو لوٹا دیا۔","ضعیف",{"u2":"سیدنا ابن عباس رضی اللہ عنہ سے مروی ہے کہ رسول صلی اللہ علیہ وسلم کے زمانے میں ایک عورت مسلمان ہو گئی اور پھر نکاح کر لیا۔ بعد ازاں اس کا شوہر بھی نبی کریم صلی اللہ علیہ وسلم کے پاس آ گیا۔ اس نے کہا: اے اللہ کے رسول! میں بھی مسلمان ہو چکا تھا اور اسے میرے اسلام قبول کرنے کا علم تھا۔ چنانچہ رسول صلی اللہ علیہ وسلم نے اس کو دوسرے شوہر سے چھین کر (اس کا نکاح فسخ کرا کے) پہلے شوہر کی طرف لوٹا دیا۔","f2":"1۔روایت سنداًضعیف ہے تاہم مسئلہ یہی ہے کہ زوجین میں سے کسی ایک کے اسلام قبول کرنے سے تفریق ہوجاتی ہے۔لیکن اگر عدت کے دوران میں شوہر بھی مسلمان ہوجائےتو وہ عورت اسی خاوند کی زوجیت میں رہے گی۔بعدازاںاگر وہ اپنے سابقہ شوہر کا انتظار نہ کرے تو کسی مسلمان سے نکاح کرلینے میں حق بجانب ہے۔لیکن اگر وہ انتظار کرےحتی کہ وہ مسلمان ہوجائےخواہ مدت طویل ہی ہوجائےتوکوئی حرج نہیں۔جیسے کہ درج ذیل باب اور حدیث میں آرہا ہے۔"}],[2240,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے اپنی صاحبزادی زینب رضی اللہ عنہا کو ابوالعاص کے پاس پہلے نکاح پر واپس بھیج دیا اور نئے سرے سے کوئی نکاح نہیں پڑھایا۔ محمد بن عمرو کی روایت میں ہے چھ سال کے بعد ایسا کیا اور حسن بن علی نے کہا: دو سال کے بعد۔","صحیح",{"u2":"سیدنا ابن عباس رضی اللہ عنہ نے بیان کیا کہ رسول اللہ صلی اللہ علیہ وسلم نے اپنی صاحبزادی زینب کو (ان کے شوہر) ابوالعاص رضی اللہ عنہ پر پہلے نکاح ہی سے لوٹا دیا تھا، اور کوئی نیا (نکاح وغیرہ) نہ کیا تھا۔ محمد بن عمرو نے اپنی روایت میں کہا کہ آپ نے چھ سال بعد (لوٹایا تھا) اور حسن بن علی نے کہا: دو سال بعد۔","f2":"یہ روایت شیخ البانی رحمہ اللہ کے نزدیک سنین کے ذکر کے بغیرصحیح ہے اور حافظ ابن حجر نے چھ سال یا دو سال کے ذکر کو صحیح سمجھتے ہوئے ان کے درمیان یہ تطبیق لکھی ہےکہ حضرت زینب رضی اللہ عنہ کی ہجرت اور ابو العاص رضی اللہ عنہ کے اسلام اور ہجرت میں چھ سال کا وقفہ تھا مگر آیت کریمہ:(لا هن حل لهم) الممتحنه:10) مسلمان عورتیں کافروں کے لیے حلال نہیں۔ کے نزول اور ابو العاص کے اسلام وہجرت کرکے آنے میں دوسال اور کچھ ماہ کا وقفہ تھا۔(شرح حدیث:5288)\nصحیح یہ ہے کہ ابو العاص نے مذکورہ آیت کے نزول سے پہلے اسلام قبول کیا تھا اور ہجرت کی تھی۔زادالمعاد میں حافظ ابن القیم رحمہ اللہ رقم طراز ہیں کہ ہمیں کسی شخص کے متعلق معلوم نہیں کہ قبول اسلام کے بعد رسول اللہ صلی اللہ علیہ وسلم نے اس کے نکاح کی تجدید کی ہو۔ اس قسم کی صورت میں دو کیفیتیں ہوتی تھیں۔یا تو افتراق ہوجاتا تھااور عورت کسی اور سے نکاح کرلیتی تھییا سابقہ نکاح قائم رہتاحتی کہ شوہر مسلمان ہوجاتا۔محض اسلام قبول کرلینے سے کامل تفریق ہونایا عدت کا اعتبار کرنا کرانا کسی کے متعلق معلوم نہیں کہ نبی صلی اللہ علیہ وسلم نے ایسا کیا ہو حالانکہ آپ کے زمانے میں ایک کثیر تعداد میں لوگ مسلمان ہوئے تھے۔(زاد المعاد جلد چہارم حکمہ دی الزوجین یسلم احدھما قبل الاخر)\nعلاوہ ازیں حضرت زینب اور ان کے خاوند کے بارے میں ایک دوسری روایت نکاح جدید کے ساتھ لوٹانے کی بھی آتی ہے۔بعض علماء نے ان میں پہلی حدیث کو اور دیگر بعض علماء نے دوسری حدیث کو صحیح قرار دیا ہے اور بعض نے ان کے درمیا ن تطبیق دی ہے۔(تفصیل کے لیے فتح الباری کا محولہ مقام فرمایا جائے)"}],[2241,"حارث بن قیس اسدی رضی اللہ عنہ کہتے ہیں میں نے اسلام قبول کیا، میرے پاس آٹھ بیویاں تھیں تو میں نے اس کا ذکر نبی اکرم صلی اللہ علیہ وسلم سے کیا، آپ صلی اللہ علیہ وسلم نے فرمایا: \"ان میں سے چار کا انتخاب کر لو (اور باقی کو طلاق دے دو)\"۔","صحیح",{"u2":"سیدنا حارث بن قیس بن عمیرہ الاسدی رضی اللہ عنہ بیان کرتے ہیں کہ جب میں نے اسلام قبول کیا تو میرے ہاں آٹھ عورتیں تھیں۔ میں نے نبی کریم صلی اللہ علیہ وسلم سے اس کا ذکر کیا تو آپ نے فرمایا &rdquo; ان میں سے چار کو منتخب کر لو۔ &ldquo;\nامام ابوداؤد رضی اللہ عنہ کہتے ہیں کہ ہمیں یہ حدیث احمد بن ابراہیم نے ہشیم کے واسطہ سے بیان کی تو (صحابی کا نام) حارث بن قیس کے بجائے قیس بن حارث ذکر کیا۔ احمد بن ابراہیم نے کہا کہ یہی قیس بن حارث ہی صحیح ہے۔"}],[2242,"اس سند سے بھی قیس بن حارث رضی اللہ عنہ سے اسی مفہوم کی حدیث مروی ہے۔","صحیح",{"u2":"احمد بن ابراہیم نے بیان کیا کہ ہم سے بکر بن عبدالرحمٰن، قاضی کوفہ نے بیان کیا، انہوں نے عیسیٰ بن مختار سے، انہوں نے ابن ابی لیلیٰ سے، انہوں نے حمیضہ بن شمرذل سے، انہوں نے سیدنا قیس بن حارث رضی اللہ عنہ سے مذکورہ بالا حدیث کے ہم معنی بیان کیا۔","f2":"یہ سند مزکورہ بالا قول امام ابو داود کی دلیل اور احمد بن ابراہیم کے شیخ ہیشم کی متابع ہے کہ صحابی کا نام قیس بن حارث ہی ہے۔(دونوں روایات شیخ البانی رحمہ اللہ کے نزدیک صحیح ہیں۔)"}],[2243,"فیروز رضی اللہ عنہ کہتے ہیں کہ میں نے عرض کیا: اللہ کے رسول! میں نے اسلام قبول کر لیا ہے اور میرے نکاح میں دو بہنیں ہیں؟ آپ صلی اللہ علیہ وسلم نے فرمایا: \"ان دونوں میں سے جس کو چاہو طلاق دے دو\"۔","حسن",{"u2":"سیدنا فیروز (دیلمی) رضی اللہ عنہ سے مروی ہے، وہ کہتے ہیں کہ میں نے کہا: اے اللہ کے رسول! میں نے اسلام قبول کیا ہے اور میری زوجیت میں دو بہنیں ہیں۔ آپ صلی اللہ علیہ وسلم نے فرمایا ” ان میں سے کسی ایک کو طلاق دے دو۔ “","f2":"1۔اسلام سے پہلے کے نکاح اسلام میں صحیح تسلیم کیے جاتے ہیں۔الا یہ کہ اس میں کوئی اسلامی حرمت موجود ہو۔مثلاً چار سے زیادہ بیویاں ہوں یا دو بہنیں نکاح میں ہوں۔\n2۔آخری حدیث کر راوی فیروز دیلمی رضی اللہ عنہ صحابی ہیں اور انہوں ہی نے عہد نبوی میں مدعی نبوت اسود کو قتل کیا تھا۔(تقریب التھذیب)\n3۔اسلام قبول کرتے ہی انسان پر شرعی احکام نافذ ہوجاتے ہیں اور جب ہوجاتا ہے کہ کسی پس وپیش کے بلاتاخیر ان پر عمل کیا جائے جیسے کہ ان واقعات سے واضح ہے۔"}],[2244,"رافع بن سنان رضی اللہ عنہ سے روایت ہے کہ انہوں نے اسلام قبول کر لیا، لیکن ان کی بیوی نے اسلام قبول کرنے سے انکار کر دیا، اور آپ کے پاس آ کر کہنے لگی: بیٹی میری ہے (اسے میں اپنے پاس رکھوں گی) اس کا دودھ چھوٹ چکا تھا، یا چھوٹنے والا تھا، اور رافع نے کہا کہ بیٹی میری ہے (اسے میں اپنے پاس رکھوں گا) تو رسول اللہ صلی اللہ علیہ وسلم نے رافع کو ایک طرف اور عورت کو دوسری طرف بیٹھنے کے لیے فرمایا، اور بچی کو درمیان میں بٹھا دیا، پھر دونوں کو اپنی اپنی جانب بلانے کے لیے کہا بچی ماں کی طرف مائل ہوئی، تو نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"اللہ اسے ہدایت دے\"، چنانچہ بچی اپنے باپ کی طرف مائل ہو گئی تو انہوں نے اسے لے لیا ۱؎۔\n§وضاحت\n۱؎ : اس حدیث سے یہ مستنبط ہوتا ہے کہ باشعور بچے کو اختیار دیا جائیگا کہ ماں باپ میں سے جس کو چاہے اختیار کر لے ، اور دودھ پیتا بچہ ماں کے تابع ہو گا۔","صحیح",{"u2":"سیدنا رافع بن سنان رضی اللہ عنہ سے روایت ہے کہ انہوں نے اسلام قبول کر لیا مگر ان کی بیوی نے اسلام قبول کرنے سے انکار کر دیا، (جس کی وجہ سے ان دونوں کے درمیان علیحدگی ہو گئی) پس وہ نبی کریم صلی اللہ علیہ وسلم کے پاس آئی اور کہا: میری بیٹی نے ابھی ابھی دودھ چھوڑا ہے یا چھوڑنے کے قریب ہے۔ رافع نے کہا: بیٹی میری ہے۔ نبی کریم صلی اللہ علیہ وسلم نے رافع سے کہا: ” ایک طرف بیٹھ جاؤ “ اور عورت سے کہا: ” دوسری طرف بیٹھ جاؤ “ اور بچی کو ان دونوں کے درمیان بٹھا دیا۔ پھر ماں باپ سے کہا: ” تم دونوں اسے بلاؤ۔ “ (انہوں نے بلایا) تو بچی اپنی ماں کی طرف جھک گئی۔ پس نبی کریم صلی اللہ علیہ وسلم نے کہا: ” اے ا اللہ! اس بچی کو ہدایت دے۔ “ چنانچہ بچی باپ کی طرف مائل ہو گئی تو اسی نے اس کو لے لیا۔","f2":"ماں باپ میں تفریق ہوجائے اور بچہ یا بچی سمجھدار ہو تو اسے اختیار دیا جائے گاکہ کسی ایک کو منتخب کرلے۔اور اس صلاحیت سے پہلے کے بارے میں فقہاء کے مختلف اقوال ہیں۔مثلاً بچہ سات سال تک ماں کی تحویل میں رہے اور بچی نو سال تک اس کے بعد باپ کو دیا جائے وغیرہ۔(زادالمعاد جلد چہارم حکمہ صلی اللہ علیہ وسلم فی الحضانہ۔نیل الوطار کتاب النفقات)"}],[2245,"سہل بن سعد ساعدی رضی اللہ عنہما سے روایت ہے کہ عویمر بن اشقر عجلانی، عاصم بن عدی رضی اللہ عنہ سے آ کر کہنے لگے: عاصم! ذرا بتاؤ، اگر کوئی شخص اپنی بیوی کے پاس کسی (اجنبی) شخص کو پا لے تو کیا وہ اسے قتل کر دے پھر اس کے بدلے میں تم اسے بھی قتل کر دو گے، یا وہ کیا کرے؟ میرے لیے رسول اللہ صلی اللہ علیہ وسلم سے یہ مسئلہ پوچھو، چنانچہ عاصم رضی اللہ عنہ نے رسول اللہ صلی اللہ علیہ وسلم سے اس سلسلہ میں سوال کیا تو آپ صلی اللہ علیہ وسلم نے (بغیر ضرورت) اس طرح کے سوالات کو ناپسند فرمایا اور اس کی اس قدر برائی کی کہ عاصم رضی اللہ عنہ پر رسول اللہ صلی اللہ علیہ وسلم کی بات گراں گزری، جب عاصم رضی اللہ عنہ گھر لوٹے تو عویمر رضی اللہ عنہ نے ان کے پاس آ کر پوچھا کہ رسول اللہ صلی اللہ علیہ وسلم نے تم سے کیا فرمایا؟ تو عاصم رضی اللہ عنہ نے کہا: مجھے تم سے کوئی بھلائی نہیں ملی جس مسئلہ کے بارے میں، میں نے سوال کیا اسے رسول صلی اللہ علیہ وسلم نے ناپسند فرمایا۔ عویمر رضی اللہ عنہ نے کہا: اللہ کی قسم میں نبی اکرم صلی اللہ علیہ وسلم سے یہ مسئلہ پوچھ کر رہوں گا، وہ سیدھے آپ کے پاس پہنچ گئے اس وقت آپ لوگوں کے بیچ تشریف فرما تھے، عویمر رضی اللہ عنہ نے کہا: اللہ کے رسول! بتائیے اگر کوئی شخص اپنی بیوی کے ساتھ (اجنبی) آدمی کو پا لے تو کیا وہ اسے قتل کر دے پھر آپ لوگ اسے اس کے بدلے میں قتل کر دیں گے، یا وہ کیا کرے؟ آپ صلی اللہ علیہ وسلم نے فرمایا: \"تمہارے اور تمہاری بیوی کے متعلق قرآن نازل ہوا ہے لہٰذا اسے لے کر آؤ\"، سہل کا بیان ہے کہ ان دونوں نے لعان ۱؎ کیا، اس وقت میں لوگوں کے ساتھ رسول اللہ صلی اللہ علیہ وسلم کے پاس موجود تھا، جب وہ (لعان سے) فارغ ہو گئے تو عویمر رضی اللہ عنہ نے کہا: اگر میں اسے اپنے پاس رکھوں تو (گویا) میں نے جھوٹ کہا ہے چنانچہ عویمر رضی اللہ عنہ نے رسول اللہ صلی اللہ علیہ وسلم کے حکم سے پہلے ہی اسے تین طلاق دے دی۔ ابن شہاب زہری کہتے ہیں: تو یہی (ان دونوں) لعان کرنے والوں کا طریقہ بن گیا۔\n§وضاحت\n۱؎ : لعان کا مطلب کسی عدالت میں یا کسی حاکم مجاز کے سامنے چار مرتبہ اللہ کی قسم کھا کر یہ کہنا ہے کہ وہ اپنی بیوی پر زنا کی تہمت لگانے میں سچا ہے یا یہ بچہ یا حمل اس کا نہیں ہے اور پانچویں مرتبہ کہے کہ اگر وہ جھوٹا ہو تو اللہ کی اس پر لعنت ہو، اب خاوند کے جواب میں بیوی بھی چار مرتبہ قسم کھا کر یہ کہے کہ وہ جھوٹا ہے اور پانچویں مرتبہ یہ کہے کہ اگر اس کا خاوند سچا ہے اور میں جھوٹی ہوں تو مجھ پر اللہ کا غضب نازل ہو، ایسا کہنے سے خاوند حد قذف سے بچ جائے گا اور بیوی زنا کی سزا سے بچ جائے گی اور دونوں کے درمیان ہمیشہ کے لئے جدائی ہو جائے گی۔","صحیح",{"u2":"سیدنا سہل بن سعد ساعدی رضی اللہ عنہ کا بیان ہے کہ عویمر بن اشقر عجلانی رضی اللہ عنہ، عاصم بن عدی کے پاس آئے اور کہا: اے عاصم! بتلاؤ! اگر کوئی شخص کسی اجنبی کو اپنی بیوی کے ساتھ پائے تو کیا اسے قتل کر دے؟ پھر تو تم اسے بھی قتل کر دو گے یا کیا کرے؟ عاصم! میرے متعلق اس مسئلے میں رسول اللہ صلی اللہ علیہ وسلم سے معلوم کرو۔ چنانچہ عاصم رضی اللہ عنہ نے رسول اللہ صلی اللہ علیہ وسلم سے سوال کیا تو آپ صلی اللہ علیہ وسلم نے اس کے سوال کو ناپسند کیا اور اس پر عیب لگایا، حتیٰ کہ عاصم کو، جو اس نے رسول اللہ صلی اللہ علیہ وسلم سے سنا بہت ہی گراں گزرا۔ عاصم جب گھر لوٹا تو عویمر اس کے پاس آیا اور پوچھا: اے عاصم! رسول اللہ صلی اللہ علیہ وسلم نے تمہیں کیا کہا ہے؟ عاصم نے کہا: تم میرے لیے کوئی خیر کا باعث نہیں بنے ہو، رسول اللہ صلی اللہ علیہ وسلم نے اس سوال کو جو میں نے آپ صلی اللہ علیہ وسلم سے پوچھا بہت ناپسند کیا ہے۔ عویمر نے کہا: قسم اللہ کی! میں اس سے خاموش نہیں رہ سکتا۔ میں خود آپ صلی اللہ علیہ وسلم سے دریافت کروں گا۔ چنانچہ عویمر رضی اللہ عنہ، رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوئے جبکہ آپ صلی اللہ علیہ وسلم لوگوں میں بیٹھے ہوئے تھے۔ اس نے کہا: اے اللہ کے رسول! فرمائیے کہ اگر کوئی شخص اپنی بیوی کے ساتھ کسی اجنبی کو پائے تو کیا اسے قتل کر دے، تب تو آپ صلی اللہ علیہ وسلم اسے بھی قتل کر ڈالیں گے یا کیسے کرے؟ رسول اللہ صلی اللہ علیہ وسلم نے جواب دیا ” بلاشبہ اللہ تعالیٰ نے تیرے اور تیری بیوی کے معاملے میں قرآن نازل فر دیا ہے۔ پس جا اور اسے لے آ۔ “ سہل نے بیان کیا: چنانچہ ان دونوں نے لعان کیا تو میں لوگوں کے ساتھ رسول اللہ صلی اللہ علیہ وسلم کے ہاں بیٹھا ہوا تھا۔ جب وہ دونوں فارغ ہو گئے تو عویمر نے کہا: اے اللہ کے رسول! اگر میں اس کو اپنے پاس رکھوں تو (اس کا مطلب ہو گا کہ میں نے) اس کی بابت جھوٹ بولا ہے۔ (میں نے اس پر جھوٹ نہیں بولا ہے)۔ پھر نبی کریم صلی اللہ علیہ وسلم کے حکم دینے سے پہلے ہی عویمر رضی اللہ عنہ نے اس کو تین طلاقیں دے دیں۔ ابن شہاب نے کہا: چنانچہ لعان کرنے والوں کا یہی طریقہ ہو گیا۔ (کہ لعان کے ساتھ ہی جدائی ہو جائے گی)۔","f2":"حضرت عويمر رضي الله عنه کا طلاق دینا گیرت اور غضب کی بناء پر تھا نہ کہ رسول اللہ صلی اللہ علیہ وسلم کے فرمان سے۔(اس مسئلے کی وضاحت آگے حدیث نمبر 2250کے فائدے میں آرہی ہے۔)"}],[2246,"سہل رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے عاصم بن عدی رضی اللہ عنہ سے فرمایا: \"بچے کی ولادت تک عورت کو اپنے پاس روکے رکھو\"۔","حسن",{"u2":"سیدنا سہل بن سعد ساعدی رضی اللہ عنہ سے مروی ہے کہ نبی کریم صلی اللہ علیہ وسلم نے عاصم بن عدی سے فرمایا ” عورت کو اپنے ہاں روکے رکھو حتیٰ کہ بچہ جن لے۔ “","f2":"معلوم ہوا کہ وہ عورت حاملہ تھی۔گویا حاملہ کے ساتھ بھی لعان کیا جاسکتا ہے۔"}],[2247,"سہل بن سعد ساعدی رضی اللہ عنہ کہتے ہیں کہ میں ان دونوں کے لعان میں نبی اکرم صلی اللہ علیہ وسلم کے پاس موجود رہا اور میں پندرہ سال کا تھا، پھر انہوں نے پوری حدیث بیان کی لیکن اس میں اتنا اضافہ کیا کہ \"پھر وہ عورت حاملہ نکلی چنانچہ لڑکے کو اس کی ماں کی جانب منسوب کر کے پکارا جاتا تھا\"۔","صحیح",{"u2":"سیدنا سہل بن سعد ساعدی رضی اللہ عنہ کہتے ہیں کہ میں ان کے لعان کے موقع پر رسول اللہ صلی اللہ علیہ وسلم کے ہاں حاضر تھا۔ میری عمر اس وقت پندرہ سال تھی۔ اور حدیث بیان کی۔ اس میں ذکر کیا کہ پھر وہ حاملہ نکلی اور بچہ اپنی ماں کی طرف منسوب کیا جاتا تھا۔"}],[2248,"لعان والی حدیث میں سہل بن سعد رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اس عورت پر نظر رکھو اگر بچہ سیاہ آنکھوں والا، بڑی سرینوں والا ہو تو میں یہی سمجھتا ہوں کہ اس (شوہر) نے سچ کہا ہے، اور اگر سرخ رنگ گیرو کی طرح ہو تو میں سمجھتا ہوں کی وہ جھوٹا ہے\"، چنانچہ اس کا بچہ ناپسندیدہ صفت پر پیدا ہوا۔","صحیح",{"u2":"سیدنا سہیل بن سعد رضی اللہ عنہ لعان کرنے والوں کے اس واقعہ میں بیان کرتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا ” اس عورت کا خیال رکھو، اگر اس نے ایسا بچہ جنا کہ آنکھیں اس کی سیاہ ہوئیں، سرین بھاری ہوئے تو میرا خیال ہے کہ اس (عویمر) نے سچ ہی کہا ہے۔ اور اگر اس نے ایسا بچہ جنا جو گورا ہوا جیسے کہ وحرہ ہو (چھپکلی کی طرح کا ایک زہریلا کیڑا، جس کے دائیں بائیں پہلو سرخ دھاریاں ہوتی ہیں، یعنی بامنی) تو میرا خیال ہے کہ اس نے جھوٹ کہا ہے۔ ” چنانچہ بچہ پیدا ہوا تو اسی ناپسندیدہ کیفیت والا تھا۔"}],[2249,"اس سند سے بھی سہل بن سعد ساعدی رضی اللہ عنہ سے یہی حدیث مروی ہے اس میں ہے: تو اسے یعنی لڑکے کو اس کی ماں کی جانب منسوب کر کے پکارا جاتا تھا۔","صحیح",{"u2":"سیدنا سہل بن سعد ساعدی رضی اللہ عنہ نے یہ خبر بیان کی تو کہا کہ پس بچے کو اپنی ماں کی طرف نسبت کر کے پکارا جاتا تھا۔","f2":"ولد الزناء کی نسبت ان کی ماؤں کی طرف ہوتی ہے تاہم ان کی تربیت صحیح اسلامی انداز میں کی جانی چاہیے۔تاکہ با وقار اسلامی زندگی گزاریںز"}],[2250,"اس سند سے بھی سہل بن سعد رضی اللہ عنہما سے یہی حدیث مروی ہے اس میں ہے: انہوں (عاصم بن عدی) نے رسول اللہ صلی اللہ علیہ وسلم کی موجودگی میں اسے تین طلاق دے دی تو رسول صلی اللہ علیہ وسلم نے اسے نافذ فرما دیا، اور جو کام آپ کی موجودگی میں کیا گیا ہو وہ سنت ہے۔ سہل رضی اللہ عنہ کا بیان ہے کہ رسول اللہ صلی اللہ علیہ وسلم کے پاس اس وقت میں موجود تھا، اس کے بعد لعان کرنے والے مرد اور عورت کے سلسلہ میں طریقہ ہی یہ ہو گیا کہ انہیں جدا کر دیا جائے، اور وہ دونوں پھر کبھی اکٹھے نہ ہوں۔","صحیح",{"u2":"سیدنا سہیل بن سعد رضی اللہ عنہ نے اس واقعہ میں بیان کیا کہ اس (عویمر رضی اللہ عنہ) نے عورت کو رسول اللہ صلی اللہ علیہ وسلم کے سامنے ہی تین طلاقیں دے دیں۔ اور رسول اللہ صلی اللہ علیہ وسلم نے اس کو نافذ کر دیا اور جو کچھ نبی کریم صلی اللہ علیہ وسلم کے ہاں کیا گیا سنت بن گیا۔ سہل کہتے ہیں کہ میں اس واقعہ میں رسول اللہ صلی اللہ علیہ وسلم کے ہاں حاضر تھا۔ چنانچہ بعد میں لعان کرنے والوں کے مابین یہی طریقہ جاری رہا کہ ان میں علیحدگی کرا دی جاتی تھی اور وہ پھر کبھی اکٹھے نہیں ہو سکتے تھے۔","f2":"لعان کرنے والوں میں ہمیشہ کے لیے علیحدگی کس طرح ہوگی؟ نفس لعان سے یا خاوند کے طلاق دینے سے یا حاکم کی ان کے درمیان تفریق کرانے سے؟آئمہ کے درمیان اس کے درمیان اختلاف ہے۔اور تینوں ہی مسلک آئمہ نے الگ الگ آئمہ نے اختیار کیے ہیں۔لیکن راجح مسلک پہلا ہے کیونکہ لعان کرنے کے بعد نہ خاوند کو طلاق دینے کی ضرورت رہتی ہے اور نہ حاکم کو تفریق کرانے کی۔اور یہ جو بعض روایات میں آتا ہے کہ خاوند نے لعان کے بعد تین طلاقیں دےدیں تو اس کی وجہ خاوند کا یہ سمجھنا تھا کہ جب تک میں طلاق نہیں دوں گا وہ میری ہی رہے گی۔حا لانکہ ایسا نہیں تھا لیکن اپنی سمجھ کی وجہ سے اس نے فوراً تین طلاقیں دے دیں اور بعض روایات میں جو آتا ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے ان کے درمیان تفریق کرادی حا لانکہ ان کے درمیان تفریق کرانے کی بھی ضرورت نہیں تھی۔راوی کا یہ بیان کرنے سے مقصود بھی یہ تھاکہ اس عمل لعان کا حکم اور نتیجہ یہ ہے کہ ان کے درمیان ہمیشہ کے لیے تفریق ہوگئی۔اس توجیہ سے بیان واقعہ کی تعبیر میں جو اختلاف ہے ان کے درمیان بھی تطبیق ہوجاتی ہے۔"}],[2251,"سہل بن سعد رضی اللہ عنہما کہتے ہیں کہ میں رسول اللہ صلی اللہ علیہ وسلم کے عہد میں دونوں لعان کرنے والوں کے پاس موجود تھا، اور میں پندرہ سال کا تھا، آپ صلی اللہ علیہ وسلم نے ان دونوں کے درمیان لعان کے بعد جدائی کرا دی، یہاں مسدد کی روایت پوری ہو گئی، دیگر لوگوں کی روایت میں ہے کہ: \"وہ نبی اکرم صلی اللہ علیہ وسلم کے پاس موجود تھے آپ نے دونوں لعان کرنے والے مرد اور عورت کے درمیان جدائی کرا دی تو مرد کہنے لگا: اللہ کے رسول! اگر میں اسے رکھوں تو میں نے اس پر بہتان لگایا\"۔ ابوداؤد کہتے ہیں کہ سفیان ابن عیینہ کی کسی نے اس بات پر متابعت نہیں کی کہ: \"آپ صلی اللہ علیہ وسلم نے دونوں لعان کرنے والوں کے درمیان تفریق کرا دی\"۔","صحیح",{"u2":"سیدنا سہیل بن سعد رضی اللہ عنہ نے بیان کیا کہ میں رسول اللہ صلی اللہ علیہ وسلم کے دور میں اس وقت حاضر تھا جب دونوں میاں بیوی نے لعان کیا تھا، میری عمر اس وقت پندرہ سال تھی۔ جب انہوں نے لعان کیا تو رسول اللہ صلی اللہ علیہ وسلم نے ان میں تفریق کرا دی۔ یہاں تک مسدد کی روایت مکمل ہو گئی۔ مگر دوسروں (وہب بن بیان، احمد بن عمرو بن سرخ اور عمرو بن عثمان) نے کہا کہ وہ نبی کریم صلی اللہ علیہ وسلم کے پاس حاضر تھا اور آپ نے لعان کرنے والے میاں بیوی کے درمیان تفریق کرا دی تو شوہر نے کہا: اے ا اللہ کے رسول! اگر میں اسے اپنے پاس رکھوں تو (گویا) میں نے اس پر جھوٹ بولا ہے۔ امام ابوداؤد رضی اللہ عنہ نے کہا: کچھ راویوں نے «عليها» کا لفظ ذکر نہیں کیا۔ (صرف «كذبت» کہا) امام ابوداؤد رضی اللہ عنہ کہتے ہیں کہ ” لعان کرنے والوں میں تفریق “ کے بیان میں سفیان بن عیینہ کا کوئی متابع (مؤید) نہیں ہے۔","f2":"ان زوجین میں تفریق فسخ کی بناء پر تھی نہ کہ طلاق کی بناء پر کیونکہ یہ طلاق رسول اللہ صلی اللہ علیہ وسلم کے فرمان سے نہ تھی جیسے کہ پیچھے گزرا ہے۔اور تفریق کا مطلب یہاں یہ ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے لعان کا یہ حکم بیان کیا کہ اس کے بعد دونوں میاں بیوی اکٹھے نہیں رہ سکتے۔ان کے درمیان ہمیشہ کے لیے جدائی (تفریق) ہوگئی ہے۔"}],[2252,"اس سند سے سہل بن سعد رضی اللہ عنہما سے یہی حدیث مروی ہے اس میں ہے کہ: \"وہ عورت حاملہ تھی اور اس نے اس کے حمل کا انکار کیا، چنانچہ اس عورت کا بیٹا اسی طرف منسوب کر کے پکارا جاتا تھا، اس کے بعد میراث میں بھی یہی طریقہ رہا کہ اللہ تعالی کے مقرر کردہ حصہ میں ماں لڑکے کی وارث ہوتی اور لڑکا ماں کا وارث ہوتا\"۔","صحیح",{"u2":"سیدنا سہل بن سعد رضی اللہ عنہ اس حدیث میں بیان کرتے ہیں کہ وہ عورت حاملہ تھی تو شوہر نے اس کے حمل کا انکار کیا۔ چنانچہ لڑکے کو ماں کی نسبت سے پکارا جاتا تھا۔ اور پھر وراثت میں بھی یہی طریقہ چل پڑا کہ بچہ اپنی ماں کا وارث بنتا اور ماں اپنے بچے کی وارث بنتی جتنا کہ اللہ عزوجل نے اس کا حصہ مقرر کیا ہے۔","f2":"معلوم ہو ا کہ اگر کوئی اپنی بیوی کے حمل کا انکار کردےتو قاضی ان کے مابین لعان کرادے اور بچہ اپنی ماں کی طرف منسوب ہوگا۔"}],[2253,"عبداللہ بن مسعود رضی اللہ عنہ کہتے ہیں کہ میں (ایک دفعہ) جمعہ کی رات مسجد میں تھا کہ اچانک انصار کا ایک شخص مسجد میں آیا، اور کہنے لگا: اگر کوئی شخص اپنی بیوی کے ساتھ کسی (اجنبی) آدمی کو پا لے اور (حقیقت حال) بیان کرے تو تم لوگ اسے کوڑے لگاؤ گے، یا وہ قتل کر دے تو اس کے بدلے میں تم لوگ اسے قتل کر دو گے، اور اگر وہ چپ رہے تو اندر ہی اندر غصہ میں جلے بھنے، اللہ کی قسم، میں اس سلسلہ میں رسول اللہ صلی اللہ علیہ وسلم سے ضرور دریافت کروں گا، چنانچہ جب دوسرا دن ہوا تو وہ رسول اللہ صلی اللہ علیہ وسلم کے پاس آیا اور اس نے عرض کیا کہ اگر کوئی شخص اپنی بیوی کے ساتھ کسی (اجنبی) آدمی کو پا لے اور حقیقت حال بیان کرے تو (تہمت کی حد کے طور پر) آپ اسے کوڑے لگائیں گے، یا وہ قتل کر دے تو اسے قتل کر دیں گے، یا وہ خاموشی اختیار کر کے اندر ہی غصہ سے جلے بھنے، یہ سن کر آپ صلی اللہ علیہ وسلم دعا کرنے لگے: \"اے اللہ! معاملے کی وضاحت فرما دے\"، چنانچہ لعان کی آیت «والذين يرمون أزواجهم ولم يكن لهم شهداء إلا أنفسهم» \"اور جو لوگ اپنی بیویوں کو تہمت لگاتے ہیں اور ان کے پاس گواہ نہ ہوں\"(سورۃ النور: ۶) آخر تک نازل ہوئی تو لوگوں میں یہی شخص اس مصیبت میں مبتلا ہوا چنانچہ وہ دونوں میاں بیوی رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوئے اور ان دونوں نے لعان کیا، اس آدمی نے چار بار اللہ کا نام لے کر اپنے سچے ہونے کی گواہی دی، اور پانچویں بار کہا کہ اگر وہ جھوٹا ہو تو اس پر اللہ کی لعنت ہو، پھر عورت لعان کرنے چلی تو آپ صلی اللہ علیہ وسلم نے فرمایا: \"ٹھہرو\"، لیکن وہ نہیں مانی اور لعان کر ہی لیا، تو جب وہ دونوں جانے لگے، تو آپ صلی اللہ علیہ وسلم نے فرمایا: \"شاید یہ عورت کالا گھنگرالے بالوں والا بچہ جنم دے\" چنانچہ اس نے وہ کالا اور گھنگرالے بالوں والا بچہ ہی جنم دیا۔","صحیح",{"u2":"سیدنا عبداللہ بن مسعود رضی اللہ عنہ سے روایت ہے، کہتے ہیں کہ ایک جمعے کی رات ہم مسجد میں تھے کہ ایک انصاری شخص مسجد میں داخل ہوا اور کہنے لگا: اگر کوئی اپنی بیوی کے ساتھ کسی اجنبی کو پائے اور اس کا اظہار کرے اور بولے تو تم لوگ (تہمت کی وجہ سے) اس کو کوڑے مارو گے یا اگر قتل کر دے تو تم اس کو بھی قتل کر ڈالو گے، (قصاص میں) اور اگر وہ خاموش رہے تو انتہائی غیظ و غضب کی بات پر خاموش رہتا ہے۔ قسم اللہ کی! میں اس بارے میں رسول اللہ صلی اللہ علیہ وسلم سے ضرور دریافت کروں گا۔ چنانچہ اگلا دن ہوا تو وہ رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوا اور آپ صلی اللہ علیہ وسلم سے پوچھا اور کہنے لگا: اگر کوئی شخص اپنی بیوی کے ساتھ کسی اجنبی کو پائے اور پھر بولے تو آپ اسے کوڑے ماریں گے (تہمت کی وجہ سے) یا اگر قتل کر دے تو آپ اسے کوڑے ماریں گے (قصاص میں) اور اگر خاموش رہے تو انتہائی غیظ و غضب کی بات پر خاموش رہتا ہے۔ تو آپ صلی اللہ علیہ وسلم نے فرمایا ” اے اللہ! معاملہ واضح فر دے۔ “ اور دعا کرنے لگے حتیٰ کہ لعان کی آیت نازل ہوئی «والذين يرمون أزواجهم ولم يكن لهم شهداء» ” اور جو لوگ اپنی بیویوں کو الزام لگائیں اور ان کے پاس اپنے سوا اور کوئی گواہ نہ ہوں “ چنانچہ یہی آدمی اس آفت میں مبتلا کر دیا گیا، پھر وہ اور اس کی بیوی رسول اللہ صلی اللہ علیہ وسلم کے پاس آئے، دونوں نے لعان کیا۔ مرد نے چار شہادتیں دیں کہ اللہ کی قسم! میں سچا ہوں اور پانچویں بار کہا: اگر میں جھوٹا ہوں تو مجھ پر اللہ کی لعنت ہو۔ پھر جب وہ عورت بھی اسی طرح لعنت کے لیے تیار ہوئی تو نبی کریم صلی اللہ علیہ وسلم نے اس سے فرمایا ” رک جاؤ (خیال کرو) مگر اس نے انکار کر دیا اور لعنت کی بد دعا کر دی۔ جب وہ دونوں چلے گئے تو آپ صلی اللہ علیہ وسلم نے فرمایا ” شاید یہ بچہ جنے گی جو کالے رنگ اور گھنگریالے بالوں والا ہو گا۔ “ چنانچہ وہ پیدا ہوا تو کالے رنگ اور گھنگریالے بالوں والا ہی تھا۔"}],[2254,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ ہلال بن امیہ رضی اللہ عنہ نے رسول اللہ صلی اللہ علیہ وسلم کے پاس اپنی بیوی پر شریک بن سحماء کے ساتھ (زنا کی) تہمت لگائی تو آپ صلی اللہ علیہ وسلم نے فرمایا: \"ثبوت لاؤ ورنہ پیٹھ پر کوڑے لگیں گے\"، تو ہلال نے کہا کہ: اللہ کے رسول! جب ہم میں سے کوئی شخص کسی آدمی کو اپنی بیوی کے ساتھ دیکھے تو وہ گواہ ڈھونڈنے جائے؟ اس پر بھی نبی اکرم صلی اللہ علیہ وسلم یہی فرمائے جا رہے تھے کہ: \"گواہ لاؤ، ورنہ تمہاری پیٹھ پر کوڑے پڑیں گے\"، تو ہلال نے کہا: اس ذات کی قسم جس نے آپ کو حق کے ساتھ نبی بنا کر بھیجا ہے میں بالکل سچا ہوں اور اللہ تعالی ضرور میرے بارے میں وحی نازل کر کے میری پیٹھ کو حد سے بری کرے گا، چنانچہ «والذين يرمون أزواجهم ولم يكن لهم شهداء إلا أنفسهم» کی آیت نازل ہوئی، آپ صلی اللہ علیہ وسلم نے اسے پڑھا یہاں تک کہ آپ پڑھتے پڑھتے «من الصادقين» ۱؎ تک پہنچے، پھر آپ صلی اللہ علیہ وسلم پلٹے اور آپ نے ان دونوں کو بلوایا، وہ دونوں آئے، پہلے ہلال بن امیہ کھڑے ہوئے اور گواہی دینے لگے، نبی اکرم صلی اللہ علیہ وسلم فرما رہے تھے: \"اللہ خوب جانتا ہے کہ تم میں سے ایک جھوٹا ہے، تو کیا تم دونوں میں سے کوئی توبہ کرنے والا ہے؟\" پھر عورت کھڑی ہوئی اور گواہی دینے لگی، پانچویں بار میں جب ان الفاظ کے کہنے کی باری آئی کہ \"اگر وہ سچا ہے تو مجھ پر اللہ کا غضب نازل ہو\" تو لوگ اس سے کہنے لگے: یہ عذاب کو واجب کر دینے والا ہے۔ عبداللہ بن عباس رضی اللہ عنہما کا بیان ہے: تو وہ ہچکچائی اور ہٹ گئی اور ہمیں یہ گمان ہوا کہ وہ باز آ جائے گی، لیکن پھر کہنے لگی: ہمیشہ کے لیے میں اپنی قوم پر رسوائی کا داغ نہ لگاؤں گی (یہ کہہ کر) اس نے آخری جملہ کو بھی ادا کر دیا۔ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"دیکھو اس کا ہونے والا بچہ اگر سرمگیں آنکھوں، بڑی سرینوں اور موٹی پنڈلیوں والا ہوا تو وہ شریک بن سحماء کا ہے\"، چنانچہ انہیں صفات کا بچہ پیدا ہوا تو آپ صلی اللہ علیہ وسلم نے فرمایا: \"اگر اللہ کی کتاب کا فیصلہ نہ آ گیا ہوتا تو میرا اور اس کا معاملہ کچھ اور ہوتا\"، یعنی میں اس پر حد جاری کرتا۔\n§وضاحت\nوضاحت ۱؎ : سورة النور: (۹-۶)","صحیح",{"u2":"سیدنا ابن عباس رضی اللہ عنہ سے مروی ہے کہ ہلال بن امیہ رضی اللہ عنہ نے اپنی بیوی کو شریک بن سحماء کے ساتھ متہم کیا۔ تو نبی کریم صلی اللہ علیہ وسلم نے فرمایا ” گواہ لاؤ، ورنہ تمہاری کمر پر حد ہے۔ “ اس نے کہا: اے اللہ کے رسول! جب ہم میں سے کوئی شخص کسی کو اپنی بیوی پر دیکھے تو بھلا وہ گواہ ڈھونڈنے جائے گا؟ مگر نبی کریم صلی اللہ علیہ وسلم فرماتے رہے ” گواہ لاؤ، ورنہ تمہاری کمر پر حد ہے۔ “ تو ہلال کہنے لگا: قسم اس ذات کی جس نے آپ صلی اللہ علیہ وسلم کو حق کے ساتھ نبی مبعوث فرمایا ہے! میں یقیناً سچا ہوں اور اللہ عزوجل بالضرور میرے بارے میں کچھ نازل فرمائے گا جو میری کمر کو حد سے بری کر دے گا۔ چنانچہ یہ آیات نازل ہوئیں «والذين يرمون أزواجهم ولم يكن لهم شهداء إلا أنفسهم» حتیٰ کہ «من الصادقين» تک پہنچے۔ پھر نبی کریم صلی اللہ علیہ وسلم چلے گئے اور ان دونوں کو بلا بھیجا اور وہ دونوں آ گئے۔ ہلال بن امیہ کھڑے ہوئے اور گواہی دی اور نبی کریم صلی اللہ علیہ وسلم فر رہے تھے ” اللہ جانتا ہے کہ تم میں سے ایک جھوٹا ہے، تو کیا تم میں سے کوئی توبہ کرتا ہے؟ “ پھر وہ عورت کھڑی ہوئی اور گواہی دی اور جب پانچویں بار کہنے لگی ” مجھ پر اللہ کا غضب ہو اگر یہ سچا ہے۔ “ تو لوگوں نے اس سے کہا: یہ قسم (اللہ کی لعنت اور غضب کو) واجب اور لازم کر دینے والی ہے۔ ابن عباس رضی اللہ عنہ نے کہا: عورت قدرے ٹھٹکی (بولنے میں جھجکی) اور پیچھے ہٹی، ہم سمجھے کہ شاید رجوع کر لے گی مگر اس نے کہا: میں اپنی قوم کو ہمیشہ کے لیے رسوا نہیں کر سکتی۔ اور پانچویں قسم کے الفاظ کہہ ڈالے۔ نبی کریم صلی اللہ علیہ وسلم نے فرمایا ” اسے دیکھنا، اگر اس نے بچہ جنا سرمگین آنکھوں والا، بھری بھری سرینوں اور موٹی موٹی پنڈلیوں والا، تو یہ شریک بن سحماء کا ہو گا (جس کے ساتھ اس کو متہم کیا گیا ہے) “ چنانچہ اس نے اسی طرح کا بچہ جنا۔ نبی کریم صلی اللہ علیہ وسلم نے فرمایا ” اگر کتاب اللہ کا فیصلہ نہ ہوتا تو میں اسے نشان عبرت بنا ڈالتا (اس پر حد جاری کرتا)۔ “ امام ابوداؤد رضی اللہ عنہ فرماتے ہیں کہ محمد بن بشار کی یہ روایت یعنی حدیث ہلال بیان کرنے میں اہل مدینہ متفرد ہیں۔","f2":"انسان کتنا ظاہر بین ہے کہ آخرت کے معاملے کو بعید اور پوشیدہ سمجھتا ہے لیکن نور ایمان ہی سے یہ فاصلے پاٹے جاتے ہیں۔"}],[2255,"عبداللہ بن عباس رضی اللہ عنہما سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے جس وقت دونوں کو لعان کا حکم فرمایا تو ایک شخص کو حکم دیا کہ پانچویں بار میں اپنا ہاتھ مرد کے منہ پر رکھ دے اور کہے: یہ (عذاب کو) واجب کرنے والا ہے۔","صحیح",{"u2":"سیدنا ابن عباس رضی اللہ عنہ سے مروی ہے کہ نبی کریم صلی اللہ علیہ وسلم نے جب لعان کرنے والوں سے قسمیں کھانے کو کہا تو پانچویں قسم کے وقت آپ نے ایک شخص سے فرمایا ” اس مرد کے منہ پر ہاتھ رکھو۔ اسے کہو یہ واجب کرنے والی ہے (ا اللہ کے غضب، لعنت اور عذاب کو)۔","f2":"قاضی کو چاہیے کہ موقع بموقع فریقین کو قسم کے اقدام سے باز رہنے کی تلقین کرےکیونکہ دنیا کی عار اور یہاں کی سزا تو عارضی ہے مگر اللہ کی لعنت اور غضب دائمی ہے۔لاحول ولا قوه الا باالله۔"}],[2256,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ ہلال بن امیہ رضی اللہ عنہ (جو کہ ان تین اشخاص میں سے ایک تھے جن کی اللہ تعالی نے(ایک غزوہ میں پچھڑ جانے کی وجہ سے سرزنش کے بعد) توبہ قبول فرمائی تھی، وہ) اپنی زمین سے رات کو آئے تو اپنی بیوی کے پاس ایک آدمی کو پایا، اپنی آنکھوں سے سارا منظر دیکھا، اور کانوں سے پوری گفتگو سنی، لیکن صبح تک اس معاملہ کو دبا کر رکھا، صبح ہوئی تو رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوئے، اور عرض کیا: اللہ کے رسول! رات کو میں گھر آیا تو اپنی بیوی کے پاس ایک مرد کو پایا، اپنی آنکھوں سے (سب کچھ) دیکھا، اور کانوں سے (سب) سنا، ان کی ان باتوں کو آپ نے ناپسند کیا اور ان پر ناگواری کا اظہار فرمایا، تو یہ دونوں آیتیں نازل ہوئیں «والذين يرمون أزواجهم ولم يكن لهم شهداء إلا أنفسهم فشهادة أحدهم» \"اور جو لوگ اپنی بیویوں پر بدکاری کی تہمت لگائیں اور ان کے پاس کوئی گواہ بجز ان کی ذات کے نہ ہو تو ایسے لوگوں میں سے ہر ایک کا ثبوت یہ ہے کہ چار مرتبہ اللہ کی قسم کھا کر کہیں کہ وہ سچوں میں سے ہیں اور پانچویں مرتبہ کہے کہ اس پر اللہ تعالی کی لعنت ہو اگر وہ جھوٹوں میں سے ہو\"(سورۃ النور: ۷، ۶) پھر رسول اللہ صلی اللہ علیہ وسلم سے جب وحی کی کیفیت دور ہوئی تو آپ نے فرمایا: \"ہلال! خوش ہو جاؤ، اللہ تعالی نے تمہارے لیے کشادگی کا راستہ نکال دیا ہے\"، ہلال رضی اللہ عنہ نے کہا: مجھے اپنے پروردگار سے اسی کی امید تھی۔ اس کے بعد رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اسے بلواؤ\"، تو وہ آئی تو آپ نے دونوں پر یہ آیتیں تلاوت فرمائیں، اور نصیحت کی نیز بتایا کہ: \"آخرت کا عذاب دنیا کے عذاب سے بہت سخت ہے\"۔ ہلال رضی اللہ عنہ نے کہا: قسم اللہ کی میں نے اس کے متعلق جو کہا ہے سچ کہا ہے، وہ کہنے لگی: یہ جھوٹے ہیں، تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"ان کے درمیان لعان کراؤ\"، چنانچہ ہلال رضی اللہ عنہ سے کہا گیا کہ وہ گواہی دیں تو انہوں نے چار بار اللہ کا نام لے کر گواہی دی کہ وہ سچے ہیں، پانچویں کے وقت کہا گیا: ہلال! اللہ سے ڈرو کیونکہ دنیا کا عذاب آخرت کے عذاب کے مقابلے میں بہت آسان ہے، اور اس بار کی گواہی تمہارے لیے عذاب کو واجب کر دے گی، وہ بولے: اللہ کی قسم! جس طرح اللہ تعالی نے مجھے کوڑوں سے بچایا ہے اسی طرح عذاب سے بھی بچائے گا، چنانچہ پانچویں گواہی بھی دے دی کہ اگر وہ جھوٹے ہوں تو ان پر اللہ کی لعنت ہو۔ پھر عورت سے گواہی دینے کے لیے کہا گیا، تو اس نے بھی چار بار گواہی دی کہ وہ جھوٹے ہیں، پانچویں بار اس سے بھی کہا گیا کہ اللہ سے ڈر جا کیونکہ دنیا کا عذاب آخرت کے عذاب کے مقابلے میں بہت آسان ہے، اور اس دفعہ کی گواہی عذاب کو واجب کر دے گی، یہ سن کر وہ ایک لمحہ کے لیے ہچکچائی پھر بولی: اللہ کی قسم میں اپنی قوم کو رسوا نہ کروں گی، چنانچہ پانچویں بار بھی گواہی دے دی کہ اگر وہ سچے ہوں تو مجھ پر اللہ کی لعنت ہو۔ اس کے بعد رسول اللہ صلی اللہ علیہ وسلم نے ان کے درمیان تفریق کرا دی، اور فیصلہ فرمایا کہ اس کا لڑکا باپ کی طرف نہ منسوب کیا جائے، اور لڑکے اور عورت کو تہمت نہ لگائی جائے جو اس پر یا اس کے لڑکے پر اب تہمت لگائے گا تو اس پر تہمت کی حد جاری کی جائے گی، نیز آپ صلی اللہ علیہ وسلم نے فیصلہ فرمایا کہ اسے نان نفقہ اور رہائش نہیں ملے گی، کیونکہ ان کی جدائی نہ تو طلاق کی بنا پر ہوئی ہے اور نہ شوہر کے انتقال کی وجہ سے، اور آپ صلی اللہ علیہ وسلم نے فرمایا: \"اگر وہ بھورے بالوں والا، پتلی سرین والا، چوڑی پیٹھ والا اور پتلی پنڈلیوں والا بچہ جنے تو وہ ہلال کا (نطفہ) ہے، اور اگر مٹیالے رنگ والا، گھنگرالے بالوں والا، موٹی پنڈلیوں والا، اور بھاری سرین والا جنے تو اس کا جس کے نام کی تہمت لگائی گئی ہے\"، چنانچہ اس عورت کا بچہ مٹیالے رنگ کا گھنگرالے بالوں والا، موٹی پنڈلیوں والا اور بھاری سرین والا پیدا ہوا تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اگر قسمیں نہ ہوتیں تو میرا اور اس کا معاملہ کچھ اور ہوتا\"۔ عکرمہ کہتے ہیں: یہی بچہ آگے چل کر مضر کا امیر بنا، اسے باپ کی جانب منسوب نہیں کیا جاتا تھا۔","ضعیف",{"u2":"سیدنا ابن عباس رضی اللہ عنہ بیان کرتے ہیں کہ ہلال بن امیہ رضی اللہ عنہ (اپنے گھر میں) آئے اور یہ ان افراد میں سے ایک ہیں (جو جنگ تبوک میں پیچھے رہ گئے تھے اور) جن کی توبہ اللہ تعالیٰ نے قبول فرمائی تھی۔ یہ اپنی زمین پر سے رات کو گھر آئے تو اپنی اہلیہ کے پاس ایک آدمی کو پایا۔ اس کو اپنی آنکھوں سے دیکھا اور اپنے کانوں سے سنا مگر اس کو دوڑایا نہیں حتیٰ کہ صبح ہو گئی۔ پھر رسول اللہ صلی اللہ علیہ وسلم کے پاس آئے اور کہا: اے اللہ کے رسول! میں عشاء کے وقت اپنے گھر والوں کے پاس آیا تو میں نے ان کے پاس ایک آدمی کو پایا۔ میں نے اپنی آنکھوں سے دیکھا اور اپنے کانوں سے سنا۔ رسول اللہ صلی اللہ علیہ وسلم نے اس خبر کو ناپسند کیا اور آپ پر یہ بہت گراں گزری۔ پھر یہ آیتیں نازل ہوئیں «والذين يرمون أزواجهم ولم يكن لهم شهداء إلا أنفسهم فشهادة أحدهم» آپ سے وحی کی کیفیت دور ہوئی تو آپ صلی اللہ علیہ وسلم نے فرمایا ” ہلال خوش ہو جاؤ! اللہ تعالیٰ نے تمہارے لیے آسانی فر دی ہے اور اس الجھن سے نکلنے کی سبیل پیدا کر دی ہے۔ “ ہلال کہنے لگے: تحقیق مجھے اپنے رب سے اسی کی امید تھی۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” عورت کو بلواؤ۔ “ وہ آ گئی تو آپ صلی اللہ علیہ وسلم نے ان دونوں پر یہ آیتیں تلاوت فرمائیں، آپ نے ان دونوں کو نصیحت فرمائی اور انہیں بتایا کہ آخرت کا عذاب دنیا کے عذاب کے مقابلے میں انتہائی سخت ہے۔ ہلال نے کہا: اللہ کی قسم! میں نے اس کے بارے میں سچ کہا ہے۔ وہ کہنے لگی: یقیناً جھوٹ کہتا ہے۔ تب رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” ان کے مابین لعان کراؤ۔ “ تو ہلال سے کہا گیا: شہادت دو تو اس نے چار دفعہ کہا: اللہ کی قسم! میں البتہ سچا ہوں۔ جب پانچویں قسم کی باری آئی تو اسے کہا گیا: اے ہلال! اللہ سے ڈر، بلاشبہ دنیا کی سزا آخرت کے مقابلے میں بہت ہلکی ہے۔ اور یہ (پانچویں) قسم تجھ پر اللہ کے عذاب کو واجب کر دینے والی ہے۔ اس نے کہا: اللہ کی قسم! اللہ مجھے اس پر عذاب نہیں دے گا جیسے کہ اس نے مجھے اس پر (جھٹلایا نہیں اور) کوئی سزا نہیں دی ہے۔ چنانچہ اس نے پانچویں قسم اٹھائی اور کہا: مجھ پر اللہ کی لعنت ہو اگر میں جھوٹا ہوں۔ پھر عورت سے کہا گیا کہ قسمیں اٹھاؤ تو اس نے چار قسمیں اٹھائیں کہ اللہ کی قسم! یہ آدمی یقیناً جھوٹا ہے۔ جب پانچویں کی باری آئی تو اسے کہا گیا: اللہ سے ڈر جا۔ بلاشبہ دنیا کی سزا آخرت کے مقابلے میں بہت ہلکی ہے۔ اور یہ (پانچویں) قسم واجب کرنے والی ہے جو تجھ پر عذاب کو لازم کر دے گی۔ تو وہ ایک لمحے کے لیے ٹھٹکی اور توقف کیا، پھر بولی: اللہ کی قسم! میں اپنی قوم کو رسوا نہیں کر سکتی اور پانچویں قسم بھی اٹھا گئی کہ اللہ کا غضب ہو مجھ پر اگر یہ شخص سچا ہو۔ تب رسول اللہ صلی اللہ علیہ وسلم نے ان دونوں کے درمیان تفریق کرا دی اور فیصلہ فر دیا کہ بچہ باپ کی طرف منسوب نہیں ہو گا، نہ اس عورت کو تہمت لگائی جائے اور نہ اس کے بچے کو کوئی طعنہ دیا جائے۔ جس کسی نے اس عورت کو تہمت لگائی یا بچے کو طعنہ دیا تو اس پر حد ہے۔ آپ صلی اللہ علیہ وسلم نے فیصلہ فرمایا کہ اس عورت کے لیے خاوند پر نہ سکنی (رہائش) لازم ہے نہ نفقہ (خرچہ) کیونکہ یہ دونوں طلاق کے بغیر علیحدہ ہو رہے تھے اور نہ خاوند فوت ہوا تھا۔ آپ صلی اللہ علیہ وسلم نے فرمایا ” اگر اس کا بچہ قدرے سرخ بالوں والا، ہلکے سرینوں والا، ابھری کمر والا اور باریک پنڈلیوں والا ہوا تو یہ ہلال کا ہو گا اور اگر وہ گندم گوں، گھونگھریالے بالوں والا، کھلے اور بڑے اعضاء والا، بھاری پنڈلیوں اور سرینوں والا ہوا تو یہ اس کا ہو گا جس کے ساتھ اس پر الزام لگایا گیا ہے۔ “ چنانچہ اس نے بچہ جنا تو وہ گندمی رنگ، گھونگھریالے بالوں والا، کھلے اور بڑے اعضاء والا اور بھاری پنڈلیوں اور سرینوں والا تھا۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” اگر قسمیں نہ اٹھائی گئی ہوتیں تو میں اسے حد لگاتا۔ (یا نشان عبرت بنا دیتا)۔ “ عکرمہ نے کہا: یہ بچہ بعد میں قبیلہ مضر کا سردار بنا تھا مگر باپ کی طرف نسبت نہ کیا جاتا تھا۔","f2":"1۔یہ روایت ضعیف ہے۔مضر (جو ہمارے نسخے میں ہے) صاحب عون اور صاحب بذل نے اسے مضر مراد لیا ہے۔ترجمے میں اس مفہوم کو اختیار کیا گیا ہے۔لیکن ابوداؤدکے بعض نسکون میں یہ مصر ٍ ہے جس کا مطلب یہ ہے کہ یہ بچہ برا ہوکر کسی شہر کا حاکم بنا۔دیکھے؛سنن ابی داود بتحقیق محمد عوامہ:1003 دارالقبلہ لثقافۃ الاسالامیہ جدہ)\n2۔آیت لعان کی بابت اختلاف ہے کہ یہ آیت ہلال بن امیہ کے لیے اترییا عویمر عجلانی کے لیے جمہور علماء کے نزدیک یہ ایت ہلال بن امیہ کے لیےنازک ہوئی کیونکہ ہلال بن امیہ کا لعان اسلام میں سب سےپہلے ہوا جبکہ علماء نے کہا کہ شاید دونوں ہی اس مسئلہ کو پوچھ چکےہوں پھر یہ آیت نازل ہوئی ہو۔والله اعلمّ"}],[2257,"سعید بن جبیر کہتے ہیں: میں نے ابن عمر رضی اللہ عنہما کو کہتے سنا کہ رسول اللہ صلی اللہ علیہ وسلم نے دونوں لعان کرنے والوں سے فرمایا: \"تم دونوں کا حساب اللہ پر ہے، تم میں سے ایک تو جھوٹا ہے ہی (مرد سے فرمایا) اب تجھے اس پر کچھ اختیار نہیں\"، اس پر اس نے کہا: اللہ کے رسول! میرے مال کا کیا ہو گا؟ آپ صلی اللہ علیہ وسلم نے فرمایا: \"تمہارا کوئی مال نہیں، اگر تم اس پر تہمت لگانے میں سچے ہو تو مال کے بدلے اس کی شرمگاہ حلال کر چکے ہو اور اگر تم نے اس پر جھوٹ بولا ہے تب تو کسی طرح بھی تم مال کے مستحق نہیں\"۔","صحیح",{"u2":"سیدنا عبداللہ بن عمر رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے لعان کرنے والوں کو کہا ” تمہارا حساب ا اللہ کے پاس ہے۔ تم دونوں میں سے ایک تو جھوٹا ہے۔ اور (شوہر سے کہا کہ) تجھے اس پر کوئی حق حاصل نہیں رہا۔ “ اس نے کہا: اے ا اللہ کے رسول! میرا مال؟ آپ صلی اللہ علیہ وسلم نے فرمایا ” تیرے لیے کوئی مال نہیں۔ اگر تو سچا ہے تو وہ اس کا بدل ہے جو تو نے اس کی عصمت کو حلال کیا۔ اور اگر اس پر جھوٹ بولا ہے تو وہ تیرے لیے اور بھی بعید تر ہے۔ “ (ایک طرف تہمت لگائے اور اس پر مزید یہ کہ مال بھی مانگے)۔","f2":"لعان کی صورت میں شوہرکوحق سے کچھ نہیں ملے گا۔"}],[2258,"سعید بن جبیر کہتے ہیں کہ میں نے ابن عمر رضی اللہ عنہما سے جو کہا کہ ایک شخص اپنی عورت کو تہمت لگائے تو اس کا کیا حکم ہے؟ تو انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے بنو عجلان کے دونوں بھائی بہنوں ۱؎ کو (اس صورت میں) جدا کرا دیا تھا اور فرمایا تھا: \"اللہ تعالی جانتا ہے کہ تم میں ایک ضرور جھوٹا ہے، تو کیا تم دونوں میں کوئی توبہ کرنے والا ہے؟\" آپ صلی اللہ علیہ وسلم نے ان الفاظ کو تین بار دہرایا لیکن ان دونوں نے انکار کیا تو آپ نے ان کے درمیان علیحدگی کرا دی۔\n§وضاحت\n۱؎ : مراد عویمر اور ان کی بیوی ہیں، اور دونوں کو «تغلیبا اخوین» کہا گیا ہے، اور ان دونوں پر «اخوة» کا اطلاق «إنما المؤمنون اخوة» کے اعتبار سے کیا گیا ہے۔","صحیح",{"u2":"جناب سعید بن جبیر کہتے ہیں کہ میں نے سیدنا عبداللہ بن عمر رضی اللہ عنہ سے پوچھا کہ کوئی شخص اپنی بیوی پر تہمت لگائے تو؟ انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے بنی عجلان کے ایک جوڑے میں تفریق کرا دی تھی (عویمر اور اس کی بیوی میں) اور فرمایا تھا ” ا اللہ ہی خوب جانتا ہے، تم دونوں میں سے ایک جھوٹا ہے، تو کیا تم میں سے کوئی توبہ کر رہا ہے؟ “ آپ نے اپنی یہ بات تین بار دہرائی مگر انہوں نے انکار کر دیا۔ چنانچہ آپ نے ان میں تفریق کرا دی۔"}],[2259,"عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم کے زمانے میں ایک شخص نے اپنی عورت سے لعان کیا اور اس کے بچے کا باپ ہونے سے انکار کر دیا چنانچہ رسول اللہ صلی اللہ علیہ وسلم نے ان کے درمیان علیحدگی کرا دی، اور بچے کو عورت سے ملا دیا۱؎۔ ابوداؤد کہتے ہیں: جس کی روایت میں مالک منفرد ہیں وہ «وألحق الولد بالمرأة» کا جملہ ہے، اور یونس نے زہری سے انہوں نے سہل بن سعد رضی اللہ عنہ سے لعان کی حدیث روایت کی ہے اس میں ہے: اس نے اس کے حمل کا انکار کیا تو اس (عورت) کا بیٹا اسی(عورت) کی طرف منسوب کیا جاتا تھا۔\n§وضاحت\n۱؎ : یعنی اسے نسب اور وراثت میں ماں سے ملا دیا لہٰذا وہ ماں ہی کی طرف منسوب کیا جائے گا اور ماں اور بیٹا دونوں ایک دوسرے کے وارث ہوں گے برخلاف باپ کے نہ تو اس کی طرف وہ منسوب ہو گا اور نہ وہ دونوں ایک دوسرے کے وارث ہو سکتے ہیں۔","صحیح",{"u2":"سیدنا ابن عمر رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم کے زمانے میں ایک شخص نے اپنی بیوی سے لعان کیا اور بچے کا انکار کیا تو آپ نے ان کے مابین علیحدگی کرا دی اور بچے کو عورت کی طرف منسوب کر دیا۔ امام ابوداؤد رضی اللہ عنہ فرماتے ہیں کہ امام مالک رضی اللہ عنہ یہ جملہ روایت کرنے میں متفرد ہیں یعنی «وألحق الولد بالمرأة» اور یونس بواسطہ زہری، سہل بن سعد سے روایت کرتے ہیں کہ شوہر نے اس کے حمل کا انکار کر دیا تو بچے کو عورت کی طرف منسوب کیا جاتا تھا۔"}],[2260,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم کے پاس بنی فزارہ کا ایک شخص آیا اور کہنے لگا: میری عورت نے ایک کالا بچہ جنا ہے، تو آپ صلی اللہ علیہ وسلم نے فرمایا: \"کیا تمہارے پاس اونٹ ہیں؟\" اس نے جواب دیا: ہاں، پوچھا: \"کون سے رنگ کے ہیں؟\" جواب دیا: سرخ ہیں، آپ صلی اللہ علیہ وسلم نے پوچھا: \"کیا کوئی خاکستری بھی ہے؟\" جواب دیا: ہاں، خاکی رنگ کا بھی ہے، آپ صلی اللہ علیہ وسلم نے پوچھا: \"پھر یہ کہاں سے آ گیا؟\"، بولا: شاید کسی رگ نے یہ رنگ کھینچ لیا ہو، آپ صلی اللہ علیہ وسلم نے فرمایا:\"یہاں بھی ہو سکتا ہے (تمہارے لڑکے میں بھی) کسی رگ نے یہ رنگ کھینچ لیا ہو ۱؎\"۔\n§وضاحت\n۱؎ : یعنی اس وقت کسی رگ میں سے جس میں کالا پن زیادہ تھا نطفہ میں سواد (کالا رنگ) زیادہ مل گیا ہو، اور اس کی وجہ سے لڑکا کالا اور سیاہ رنگ ہو تو اس قسم کے اختلاف سے اس کے نسب سے متعلق دل میں شبہ کرنا صحیح نہیں ہے۔","صحیح",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ بنو فزارہ کا ایک شخص رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں آیا اور کہنے لگا کہ میری بیوی نے بچے کو جنم دیا ہے جو کالے رنگ کا ہے تو آپ صلی اللہ علیہ وسلم نے فرمایا ” کیا تیرے پاس اونٹ ہیں؟ “ کہا: ہاں۔ آپ نے پوچھا ” ان کے رنگ کیسے ہیں؟ “ کہا: سرخ ہیں۔ آپ صلی اللہ علیہ وسلم نے پوچھا ” کیا ان میں کوئی گندم گوں (یا سیاہی مائل) بھی ہے؟ “ اس نے کہا: ہاں، ان میں سیاہی مائل بھی ہیں۔ آپ نے فرمایا ” تیرا کیا خیال ہے وہ کہاں سے آئے؟ “ اس نے کہا: شاید ان کو کسی رگ نے کھینچا ہو۔ آپ نے فرمایا ” اس بچے کو بھی شاید کسی رگ نے کھینچا ہو۔ “","f2":"1۔محض رنگ وروپ کی بناءپر اپنے بچے سے انکار کردینا حرام ہے۔ہاںکوئی اور واضح دلیل ہو تو اور بات ہے۔مثلاًشوہر کے غائب رہنے کی صورت میں حمل اور ولادت ہو یابعد ازنکاح چھ ماہ سے کم میں ولادت ہو وغیرہ۔اس حدیث میں مذکور شخص کے متعلق بیان کیا جاتا ہے کہ اس کا نام ضمضم بن قتادہ تھا۔(کتاب الغوا مض عبد الغنی بن سعید)\n2۔قاضی مفتی اور داعی حضرات کو چاہیے لہ شرعی مسائل سے حسب ضرورت واقعاتی مثالوں سے واضح فرمایا کریں۔"}],[2261,"اس سند سے بھی زہری سے اسی مفہوم کی حدیث مروی ہے لیکن اس میں یہ ہے کہ یہ کہہ کر اس کا مقصد اپنے سے بچہ کی نفی کرنی تھی۔","صحیح",{"u2":"زہری نے اپنی سند سے مذکورہ بالا حدیث کے ہم معنی روایت کیا اور کہا کہ وہ شخص اپنی بات کہتے ہوئے بچے سے انکار کا اشارہ کر رہا تھا۔"}],[2262,"اس سند سے بھی ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ ایک دیہاتی رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوا اور کہنے لگا: میری عورت نے ایک کالا لڑکا جنا ہے اور میں اس کا انکار کرتا ہوں، پھر راوی نے اسی مفہوم کی حدیث بیان کی۔","صحیح",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ سے مروی ہے کہ ایک اعرابی نبی کریم صلی اللہ علیہ وسلم کی خدمت میں آیا اور کہا: میری بیوی نے بچے کو جنم دیا ہے جو کالے رنگ کا ہے اور مجھے اس پر تعجب ہے۔ اور مذکورہ بالا حدیث کے ہم معنی بیان کیا۔","f2":"اس روایت میں(انکرہ) کے معنی (استكبرته)ہیں۔یعنی میرادل نہیں مانتا۔اس میں گمان کی بات ہے یقین کی نہیں۔"}],[2263,"ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ جس وقت آیت لعان نازل ہوئی انہوں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: \"جس عورت نے کسی قوم میں ایسے فرد کو شامل کر دیا جو حقیقت میں اس قوم کا فرد نہیں ہے، تو وہ اللہ کی رحمت سے دور رہے گی، اسے اللہ تعالی جنت میں ہرگز داخل نہ کرے گا، اسی طرح جس شخص نے اپنے بچے کا انکار کیا حالانکہ اسے معلوم ہے کہ وہ اس کا بچہ ہے، اسے اللہ تعالی کا دیدار نصیب نہ ہو گا، اور وہ اگلی پچھلی ساری مخلوق کے سامنے اسے رسوا کرے گا ۱؎\"۔\n§وضاحت\n۱؎ : حاصل یہ ہے کہ نہ عورت کو چاہئے کہ حرام کا بچہ کسی غیر سے جن کر اس کو اپنے خاوند کی طرف منسوب کرے اور نہ مرد کو چاہئے کہ دیدہ و دانستہ اپنے بچے کا انکار کرے اور عورت پر زنا کی تہمت لگائے۔","ضعیف",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ جب لعان کے متعلق آیت اتری تو میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا: ” جو عورت کسی قوم میں کسی غیر کو داخل کر دے، جو ان میں سے نہ ہو تو وہ ا اللہ کے ہاں کوئی مقام نہیں رکھتی، اور ا اللہ تعالیٰ اسے اپنی جنت میں ہرگز داخل نہیں کرے گا۔ اور جس شخص نے اپنے بچے کا انکار کیا جبکہ بچہ اس کی طرف دیکھ رہا ہو، تو ا اللہ تعالیٰ اس سے حجاب فر لے گا اور اولین و آخرین کے روبرو اسے رسوا کرے گا۔ “","f2":"کوئی عورت کہیں بدکاری کرےاور حاملہ ہوجائے اور پھر بچے کو شوہر اور اس کی قوم سے ملادےیا کوئی باپ بلاوجہ معقول ومشروع بچے سے انکار کردےتویہ انتہائی مکروہ اور غلیظ کام ہے۔اور یہ دونوں عمل کبائر میں سےہیں۔"}],[2264,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اسلام میں اجرت پر بدکاری اور زنا نہیں ہے، جس نے زمانہ جاہلیت میں بدکاری اور زنا سے کمائی کی، تو زنا سے پیدا ہونے والا بچہ اپنے عصبہ (مالک) سے مل جائے گا اور جس نے بغیر نکاح یا ملک کے کسی بچے کا دعوی کیا تو نہ تو (بچہ) اس کا وارث ہو گا اور نہ وہ بچے کا\"۔","ضعیف",{"u2":"سیدنا ابن عباس رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” اسلام میں زناکاری کا کوئی تصور اور مقام نہیں، جس کسی نے ایام جاہلیت میں یہ عمل بد کیا ہو تو بچہ اس کے عصبہ ہی سے ملحق ہو گا۔ اور جو کوئی نکاح صحیح کے بغیر کسی بچے کا دعوہ کرے (زنا کی وجہ سے) تو نہ وہ باپ اس بچے کا وارث ہو گا اور نہ وہ بیٹا اس باپ کا۔ “"}],[2265,"عبداللہ بن عمرو بن العاص رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فیصلہ فرمایا کہ جس لڑکے کو اس کے باپ کے مرنے کے بعد اس باپ سے ملایا جائے جس کے نام سے اسے پکارا جاتا ہے اور باپ کے وارث اسے اپنے سے ملانے کا دعوی کریں تو اگر اس کی پیدائش ایسی لونڈی سے ہوئی ہے جو صحبت کے دن اس کے ملکیت میں رہی ہو تو ملانے والے سے اس کا نسب مل جائے گا اور جو ترکہ اس کے ملائے جانے سے پہلے تقسیم ہو گیا ہے اس میں اس کو حصہ نہ ملے گا، البتہ جو ترکہ تقسیم نہیں ہوا ہے اس میں اسے حصہ دیا جائے گا، لیکن جس باپ سے اس کا نسب ملایا جاتا ہے اس نے (اپنی زندگی میں اس کے بیٹا ہونے سے) انکار کیا ہو تو وارثوں کے ملانے سے وہ نہیں ملے گا، اگر وہ لڑکا ایسی لونڈی سے ہو جس کا مالک اس کا باپ نہ تھا یا آزاد عورت سے ہو جس سے اس کے باپ نے زنا کیا تو اس کا نسب نہ ملے گا اور نہ اس کا وارث ہو گا گرچہ جس کے نام سے اسے پکارا جاتا ہے اسی نے (اپنی زندگی میں) اس کے بیٹا ہونے کا دعوی کیا ہو کیونکہ وہ زنا کی اولاد ہے آزاد عورت سے ہو یا لونڈی سے۔","حسن",{"u2":"جناب عمرو بن شعیب اپنے والد (شعیب) سے اور وہ اپنے دادا (عبداللہ بن عمرو رضی اللہ عنہ) سے روایت کرتے ہیں کہ انہوں نے کہا: نبی کریم صلی اللہ علیہ وسلم نے فیصلہ فرمایا کہ ایسا بچہ جس کے متعلق باپ کی وفات کے بعد دعویٰ کیا گیا ہو جبکہ باپ اپنی زندگی میں اس کا مدعی رہا ہو اور بعد میں اس کے وارثوں نے بھی اس کا دعویٰ کیا ہو تو اگر بچہ ایسی لونڈی کے بطن سے ہو، کہ مباشرت کے روز وہ اس مدعی کی ملکیت میں تھی تو یہ بچہ اس کے ساتھ ملحق ہو گا، جس کے ساتھ الحاق کا دعویٰ کیا گیا ہے۔ اور مال وراثت جو الحاق سے پہلے تقسیم ہو چکا اس میں اس بچے کا حق نہ ہو گا مگر باقی ماندہ میں اپنا حصہ پائے گا۔ لیکن اگر اس باپ نے، جس کی طرف لاحق کیے جانے کا دعویٰ کیا جا رہا ہو، اس کا انکار کیا ہو تو اس کے ساتھ ملحق نہ ہو گا۔ اور اگر بچہ کسی ایسی لونڈی سے ہو جو اس مدعی باپ کی ملکیت نہ تھی یا کسی آزاد عورت سے ہو، جس کے ساتھ اس نے زنا کیا تھا تو بھی اس کے ساتھ اس بچے کو ملحق نہ کیا جائے گا اور نہ وارث ہو گا۔ اگرچہ جس کی طرف اس کی نسبت کی جاتی ہے وہ اس کا مدعی بھی ہو۔ ایسا بچہ ولد الزنا ہو گا، کسی آزاد عورت سے ہو یا لونڈی سے۔"}],[2266,"اس سند سے بھی محمد بن راشد سے اسی مفہوم کی روایت منقول ہے لیکن اس میں یہ الفاظ زائد ہیں کہ وہ ولد الزنا ہے اور اپنی ماں کے خاندان سے ملے گا چاہے وہ آزاد ہوں یا غلام، یہ شروع اسلام میں پیش آمدہ معاملہ کا حکم ہے، رہا جو مال قبل از اسلام تقسیم ہو چکا اس سے کچھ سروکار نہیں۔","حسن",{"u2":"محمد بن راشد نے اپنی سند سےاس مذکور حدیث کے ہم معنی بیان کیا اور مزید کہا: یہ ولد الزنا ہو گا اور اپنی ماں کے اہل کی ملکیت ہو گا خواہ کوئی ہوں، آزاد عورت ہو یا کوئی لونڈی۔ اور یہ فیصلے اسلام کے اولین دور میں ہوئے تھے۔ اور جو مال قبل از اسلام تقسیم ہو چکے وہ ہو چکے۔","f2":"دور جاہلیت میں لوگوں کے پاس لونڈیاں ہوتی تھی جو بعض اوقات بدکاری کے عمل سے مال بھی کماتی تھیں اور کئی مالک ان سے مباشرت کرنے سے پہلے پرہیز نہیں کرتے تھے۔تو اگر کسی کے ہاں کوئی بچہ پیدا ہوتا تو کبھی وہ زانی اس کی ملکیت کا دعوی کرتا اور ساتھ مالک بھی اس کا دعوی کرلیتا تھا۔اسلام میں ان کا فیصلہ یہ ہوا کہ بچہ لونڈی کے مالک کا ہے نہ کہ زانی کا۔کیونکہ لونڈی مالک کا بستر ہوتی ہے جیسے کہ آزاد عورت۔اور اگر یہ صورت ہوئی ہوتی کہ بچے کو زانی کی طرف منسوب کیا گیا مالک نے جین حیات نہ دعوی کیااور نہ انکار اور پھر وہ مرگیا۔مگر اس کی موت کے بعد وارثوں نے بچے کے متعلق دعوی کیا کہ یہ مرنے والے مالک کا ہے توان کا یہ دعوی تسلیم کیا جائے گا۔اور قبل ازوقت تقسیم شدہ مال وراثت میں اس کا کوئی حق نہ ہوگا۔مگر باقی ماندہ مال میں اس کاحصہ ہوگا جو بنتا ہو۔لیکن اگر لونڈی کے مالک نے حمل کا انکار کیا ہو اور اس بچے کا مدعی نہ رہا ہو تو بچے کو اس کے ساتھ ملحق نہ کیا جائےگااور نہ وارثوں کو حق ہوگاکہ مالک کی موت کے بعد اس بچے کو اس کی اولاد کے ساتھ لاحق کرنے کا دعوی کریں۔(معالم السنن للخطابی) اس قسم کا ایک واقعہ آگے حدیث (2273) میں آرہاہے۔"}],[2267,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم میرے پاس (مسدد اور ابن سرح کی روایت میں ہے) ایک دن خوش و خرم تشریف لائے (اور عثمان کی روایت میں ہے آپ کے چہرے پر خوشی کی لکیریں ۱؎ محسوس کی جا رہی تھیں) تو آپ صلی اللہ علیہ وسلم نے فرمایا: \"عائشہ! کیا تو نے دیکھا نہیں کہ مجزز مدلجی نے زید بن حارثہ اور اسامہ بن زید کو اس حال میں دیکھا کہ وہ دونوں اپنے سر چادر سے ڈھانکے ہوئے تھے اور پیر کھلے ہوئے تھے تو کہا کہ یہ پاؤں ایک دوسرے سے ملتے جلتے ہیں\"۔ ابوداؤد کہتے ہیں: اسامہ کالے تھے اور زید گورے تھے۔\n§وضاحت\n۱؎ : خوشی کی وجہ یہ تھی کہ لوگ زید بن حارثہ رضی اللہ عنہ اور ان کے بیٹے اسامہ رضی اللہ عنہ کے سلسلہ میں ایسی باتیں کہتے تھے جنہیں سن کر رسول اللہ صلی اللہ علیہ وسلم کو بڑی تکلیف ہوتی تھی، زید گورے چٹے آدمی تھے اور اسامہ کا رنگ کالا تھا اس لئے لوگ شک کرتے تھے کہ اسامہ زید کے بیٹے ہیں یا کسی اور کے جب اس قیافہ شناس مجزز مدلجی نے اس بات کی تصدیق کر دی کہ ان دونوں کے پیر ملتے جلتے ہیں تو آپ کو اس سے بے حد خوشی ہوئی۔","صحیح",{"u2":"ام المؤمنین سیدہ عائشہ رضی اللہ عنہا ا بیان کرتی ہیں کہرسول اللہ صلی اللہ علیہ وسلم ایک دن بڑے خوش خوش میرے ہاں تشریف لائے۔ عثمان بن ابی شیبہ کے الفاظ ہیں کہ آپ صلی اللہ علیہ وسلم کے چہرہ کے خطوط چمک رہے تھے۔ آپ صلی اللہ علیہ وسلم نے فرمایا ” عائشہ! کیا کچھ معلوم ہوا کہ مجزز مدلجی نے زید اور اسامہ کو دیکھا جبکہ وہ دونوں ایک چادر سے اپنے سر ڈھانپے (لیٹے) ہوئے تھے اور ان کے پاؤں ننگے تھے تو مجزز نے کہا: بلاشبہ یہ قدم ایک دوسرے سے ہیں۔ (باپ بیٹے کے ہیں) امام ابوداؤد رضی اللہ عنہ نے کہا: سیدنا اسامہ سیاہ رنگ کے تھے اور سیدنا زید سفید رنگ کے۔","f2":"انسان کے اعضاء اور شکل و مشابہت دیکھ کر اس کے نسب وعادات کا اندازہ لگانا قیافہ کہلاتا ہے۔(ابجد العلوم)"}],[2268,"اس سند سے بھی زہری نے اسی طریق سے اسی مفہوم کی روایت بیان کی ہے اس میں ہے کہ ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں: آپ صلی اللہ علیہ وسلم میرے پاس خوش و خرم تشریف لائے آپ کے چہرے کی لکیریں چمک رہی تھیں۔ ابوداؤد کہتے ہیں: «أسارير وجهه» کے الفاظ کو ابن عیینہ یاد نہیں رکھ سکے، ابوداؤد کہتے ہیں: «أسارير وجهه» ابن عیینہ کی جانب سے تدلیس ہے انہوں نے اسے زہری سے نہیں سنا ہے انہوں نے «أسارير وجهه» کے بجائے «لأسارير من غير» کے الفاظ سنے ہیں اور «أسارير» کا ذکر لیث وغیرہ کی حدیث میں ہے۔ ابوداؤد کہتے ہیں: میں نے احمد بن صالح کو یہ کہتے ہوئے سنا کہ اسامہ رضی اللہ عنہ تارکول کی طرح بہت زیادہ کالے تھے ۱؎ اور زید رضی اللہ عنہ روئی کی طرح سفید۔\n§وضاحت\n۱؎ : کیونکہ ان کی والدہ جن کا نام برکۃ تھا اور کنیت ام ایمن تھی بہت کالی اور حبشی خاتون تھیں۔","صحیح",{"u2":"ابن شہاب نے اپنی سند سے مذکورہ بالا کے ہم معنی بیان کیا سیدہ عائشہ رضی اللہ عنہا ا نے کہا: آپ صلی اللہ علیہ وسلم بڑے خوش خوش میرے پاس تشریف لائے۔ آپ صلی اللہ علیہ وسلم کے چہرے کی دھاریاں چمک رہی تھیں۔ ¤ امام ابوداؤد رضی اللہ عنہ فرماتے ہیں کہ اسامہ سیاہ اور زید رضی اللہ عنہ سفید رنگ کے تھے۔ ¤ امام ابوداؤد رضی اللہ عنہ فرماتے ہیں «أسارير وجهه» کا لفظ ابن عیینہ نے یاد نہیں رکھا۔ ¤ امام ابوداؤد رضی اللہ عنہ فرماتے ہیں «أسارير وجهه» کے الفاظ ابن عیینہ کی تدلیس ہے، جو کہ انہوں نے زہری سے نہیں سنے بلکہ کسی اور سے سنے ہیں۔ یہ الفاظ لیث وغیرہ کی روایت میں آئے ہیں۔ ¤ امام ابوداؤد رضی اللہ عنہ نے کہا: احمد بن صالح کہا کرتے تھے کہ سیدنا اسامہ رضی اللہ عنہ انتہائی کالے رنگ کے تھے جیسے کہ تارکول ہو اور زید رضی اللہ عنہ سفید رنگ کے تھے جیسے کہ روئی۔","f2":"حضرت زیدبن حارثہ رجی اللہ عنہ رسول اللہ صلی اللہ علیہ وسلم کے مولی (آزاد کردہ غلام)تھےاور شرع ایام اسلام میں آپ کے متنبہی (لےپالک)بھی کہلاتے رہتے تھے۔ان صاحبزادے حضرت اسامہ رضی اللہ عنہ رسول اللہ صلی اللہ علیہ وسلم کو انتہائی محبوب تھے۔ان کا لقب ہی حب رسول الله (رسول اللہ صلی اللہ علیہ وسلم کے لاڈلے اور چہیتے) پڑگیا تھا۔باپ بیٹے میں رنگ کا فرق تھا کیونکہ اسامہ ماں ام ایمن تھی جو حبشن تھیں۔انہیں رنگ پر ان کا رنگ آیا تو کئی جاہل ان کے نسب پر طعن کرتے تھے جوکہ رسول اللہ صلی اللہ علیہ وسلم اور مسلمانوں کے لیے اذیت کا باعث تھا۔مجزز مدلحجی قبیلہ بنو اسد کا معروف قیافہ شناس تھااور مشرکین اس کی بات قبول کرتے تھے۔کہیں گزرتے ہوئے اس نے ان دونوں باپ بیٹے کو دیکھ لیا جبکہ ان کے چہرے ڈھنپے ہوئے تھےاور پاؤں ننگے تھے۔تو اس نے غالباً اپنے علمی رعب کا اظہار کرنےکے لیے یہ جملہ کہ دیا کہ یہ پاؤں باپ بیٹے کے ہیں۔ یہ جملہ مسلمانوں کے لیے حق کی تائید وتقویت اور شبہات کے ازالے کا باعث ثابت ہوا۔اس سے رسول اللہ صلی اللہ علیہ وسلم اور مسلمانوں کو خوشی ہوئی کہ کفار کا معتقدان کے اپنے طعن کی تردید کر رہا ہے۔۔۔۔اس واقعہ میں فقہی استدلال یہ ہے کہ اگر کہیں کسی بچے کے بارے میں کئی لوگ مدعی ہوں یا کسی عورت سے کسی شبہے کی وجہ سے دو تین افراد نے مباشرت کرلی ہو اور بچے کے بارے میں واضح نہ ہوکہ کس کا ہے؟تو کسی ماہر اور عادل قیافہ شناس کے رائے سے فیصلہ کیا جاسکتا ہے۔اگر یہ علم سراسر باطل ہوتا تو رسول اللہ صلی اللہ علیہ وسلم اس کے قول پر خوشی کا اظہار نہ فرماتے۔گزشتہ حدیث لعان(حدیث:2252)میں رسول اللہ صلی اللہ علیہ وسلم کا بیان گزرا ہےکہ بچہ اگر اس اس طرح کا ہوا تو فلاں کا ہوگا۔ اس میں علم قیافہ کی اصلیت کی دلیل ہے۔نیز حدیث ام سلیم رضی اللہ عنہ میں آتا ہے کہاگر عورت کو احتلام نہیں ہوتا تو بچے کی اس کے ساتھ مشابہت کیونکر ہوتی ہے؟(صحیح بخاری العلم حدیث:130 و صحیح مسلم الحیض حدیث:313)"}],[2269,"زید بن ارقم رضی اللہ عنہ کہتے ہیں کہ میں نبی اکرم صلی اللہ علیہ وسلم کے پاس بیٹھا ہوا تھا اتنے میں یمن کا ایک آدمی آیا اور کہنے لگا: اہل یمن میں سے تین آدمی علی رضی اللہ عنہ کے پاس ایک لڑکے کے لیے جھگڑتے ہوئے آئے، ان تینوں نے ایک عورت سے ایک ہی طہر (پاکی) میں جماع کیا تھا، تو علی رضی اللہ عنہ نے ان میں سے دو سے کہا کہ تم دونوں خوشی سے یہ لڑکا اسے (تیسرے کو) دے دو، یہ سن کر وہ دونوں بھڑک گئے، پھر دو سے یہی بات کہی، وہ بھی بھڑک اٹھے، پھر دو سے اسی طرح گفتگو کی لیکن وہ بھی بھڑک اٹھے، چنانچہ علی رضی اللہ عنہ نے کہا کہ: \"تم تو باہم ضد کرنے والے ساجھی دار ہو لہٰذا میں تمہارے درمیان قرعہ اندازی کرتا ہوں، جس کے نام کا قرعہ نکلے گا، لڑکا اسی کو ملے گا اور وہ اپنے ساتھیوں کو ایک ایک تہائی دیت ادا کرے گا\"، آپ نے قرعہ ڈالا اور جس کا نام نکلا اس کو لڑکا دے دیا، یہ سن کر رسول اللہ صلی اللہ علیہ وسلم ہنسے یہاں تک کہ آپ کی ڈاڑھیں یا کچلیاں نظر آنے لگیں۔","صحیح",{"u2":"سیدنا زید بن ارقم رضی اللہ عنہ بیان کرتے ہیں کہ میں نبی کریم صلی اللہ علیہ وسلم کی خدمت میں بیٹھا ہوا تھا کہ یمن کا ایک آدمی آیا اور اس نے بتایا کہ تین یمنی سیدنا علی رضی اللہ عنہ کے پاس آئے۔ ان کا ایک بچے کے بارے میں تنازع تھا۔ وہ تینوں کسی عورت پر ایک ہی طہر میں واقع ہوئے تھے۔ سیدنا علی رضی اللہ عنہ نے ان میں سے دو کہ کہا: اپنی خوشی سے اس تیسرے کے حق میں دست بردار ہو جاؤ، تو وہ دونوں چیخ پڑے (اور راضی نہ ہوئے۔) پھر انہوں نے دوسرے دو آدمیوں سے کہا: اپنی خوشی سے اس تیسرے کے حق میں دست بردار ہو جاؤ۔ تو وہ راضی نہ ہوئے۔ پھر انہوں نے دوسرے دو آدمیوں سے کہا کہ اپنی خوشی سے اس تیسرے کے حق میں دست بردار ہو جاؤ، تو انہوں نے بھی انکار کر دیا تو سیدنا علی رضی اللہ عنہ نے کہا: تم باہم ضد رکھنے والے شریک ہو۔ میں تمہارے درمیان قرعہ ڈالتا ہوں، جس کے نام کا قرعہ نکل آیا بچہ اسی کا ہو گا اور اس پر واجب ہو گا کہ اپنے دوسرے ساتھیوں کو دیت کا تیسرا تیسرا حصہ ادا کرے۔ چنانچہ انہوں نے ان میں قرعہ ڈالا اور بچہ اس کو دے دیا جس کے نام کا قرعہ نکلا۔ اس پر رسول اللہ صلی اللہ علیہ وسلم (بہت) ہنسے حتیٰ کہ آپ صلی اللہ علیہ وسلم کی داڑھیں نمایاں ہو گئیں۔","f2":"کسی شکل کے حروف لکھ کر ان سے کسی مطلوبہ امر کے ہونے نہ ہونے پر استدلال کرنا قرعہ کہلاتا ہے۔(ابجد العلوم)"}],[2270,"زید بن ارقم رضی اللہ عنہ کہتے ہیں کہ علی رضی اللہ عنہ کے پاس یمن میں تین آدمی (ایک لڑکے کے لیے جھگڑا لے کر) آئے جنہوں نے ایک عورت سے ایک ہی طہر میں صحبت کی تھی، تو آپ نے ان میں سے دو سے پوچھا: کیا تم دونوں یہ لڑکا اسے (تیسرے کو) دے سکتے ہو؟ انہوں نے کہا: نہیں، اس طرح آپ نے سب سے دریافت کیا، اور سب نے نفی میں جواب دیا، چنانچہ ان کے درمیان قرعہ اندازی کی، اور جس کا نام نکلا اسی کو لڑکا دے دیا، نیز اس کے ذمہ (دونوں ساتھیوں کے لیے) دو تہائی دیت مقرر فرمائی، رسول اللہ صلی اللہ علیہ وسلم کے سامنے جب اس کا تذکرہ آیا تو آپ ہنسے یہاں تک کہ آپ کی کچلیاں ظاہر ہو گئیں۔","صحیح",{"u2":"سیدنا زید بن ارقم رضی اللہ عنہ بیان کرتے ہیں کہ سیدنا علی رضی اللہ عنہ کے پاس تین آدمیوں کا معاملہ لایا گیا جبکہ وہ یمن میں عامل تھے، وہ تینوں ایک عورت پر ایک طہر میں واقع ہوئے تھے۔ انہوں نے دو سے پوچھا کیا تم اس تیسرے کے لیے بچے کا اقرار کرتے ہو؟ انہوں نے کہا: نہیں! حتیٰ کہ انہوں نے سب سے پوچھا۔ جب بھی دو سے پوچھتے، وہ نفی میں جواب دیتے تو انہوں نے ان میں قرعہ ڈالا اور بچہ اس کو دے دیا جس کے نام کا قرعہ نکلا اور اس پر دو تہائی دیت بھی لازم کر دی۔ چنانچہ یہ واقعہ نبی کریم صلی اللہ علیہ وسلم کے سامنے ذکر کیا گیا تو آپ اس پر ہنسے حتیٰ کہ آپ کی داڑھیں نظر آنے لگیں۔","f2":"جہاں کہیں کسی معاملے کے دو پہلوبرابر ہوںاور کوئی جانب واضح طور پر راجح معلوم نہ ہوتی ہو تو قرعہ سے فیصلہ کرنا جائز ہے جیسے کہ حضرت علی رضی اللہ عنہ نے کیا یا جیسے کہ رسول اللہ صلی اللہ علیہ وسلم سفر میں رفاقت کے لیے ازواج مطہرات رضی اللہ عنہ میں قرعہ ڈال لیا کرتے تھے۔"}],[2271,"خلیل یا ابن خلیل کہتے ہیں کہ علی بن ابی طالب رضی اللہ عنہ کے پاس ایک عورت کا مقدمہ لایا گیا جس نے تین آدمیوں سے صحبت کے بعد ایک لڑکا جنا تھا، آگے اسی طرح کی روایت ہے اس میں نہ تو انہوں نے یمن کا ذکر کیا ہے، نہ ہی نبی اکرم صلی اللہ علیہ وسلم کا، اور نہ (علی رضی اللہ عنہ کے) اس قول کا کہ خوشی سے تم دونوں لڑکے کو اسے (تیسرے کو) دے دو۔","ضعیف",{"u2":"خلیل یا ابن خلیل سے مروی ہے کہ سیدنا علی رضی اللہ عنہ سے اس عورت کے بارے میں پوچھا گیا جس نے تین مردوں سے بچہ جنم دیا۔ (تینوں نے اس سے صحبت کی تھی) اور مذکورہ بالا کی مانند بیان کیا۔ اس روایت میں یمن کا یا نبی کریم صلی اللہ علیہ وسلم کا ذکر نہیں اور نہ یہ ہے کو خوشی خوشی بچے سے دست بردار ہو جاؤ۔"}],[2272,"محمد بن مسلم بن شہاب کہتے ہیں کہ عروہ بن زبیر نے مجھے خبر دی ہے کہ ام المؤمنین عائشہ رضی اللہ عنہا نے انہیں بتایا کہ زمانہ جاہلیت میں چار قسم کے نکاح ہوتے تھے: ایک تو ایسے ہی جیسے اس زمانے میں ہوتا ہے کہ ایک شخص دوسرے شخص کے پاس اس کی بہن یا بیٹی وغیرہ کے لیے نکاح کا پیغام دیتا ہے وہ مہر ادا کرتا ہے اور نکاح کر لیتا ہے۔ نکاح کی دوسری قسم یہ تھی کہ آدمی اپنی بیوی سے حیض سے پاک ہونے کے بعد کہہ دیتا کہ فلاں شخص کو بلوا لے، اور اس کا نطفہ حاصل کر لے پھر وہ شخص تب تک اپنی بیوی سے صحبت نہ کرتا جب تک کہ مطلوبہ شخص سے حمل نہ قرار پا جاتا، حمل ظاہر ہونے کے بعد ہی وہ چاہتا تو اس سے جماع کرتا، ایسا اس لیے کیا جاتا تھا تاکہ لڑکا نجیب (عمدہ نسب کا) ہو، اس نکاح کو نکاح استبضاع (نطفہ حاصل کرنے کا نکاح) کہا جاتا تھا۔ نکاح کی تیسری قسم یہ تھی کہ نو افراد تک کا ایک گروہ بن جاتا پھر وہ سب اس سے صحبت کرتے رہتے، جب وہ حاملہ ہو جاتی اور بچے کی ولادت ہوتی تو ولادت کے کچھ دن بعد وہ عورت ان سب لوگوں کو بلوا لیتی، کوئی آنے سے انکار نہ کرتا، جب سب جمع ہو جاتے تو کہتی: تمہیں اپنا حال معلوم ہی ہے، اور میں نے بچہ جنا ہے، پھر وہ جسے چاہتی اس کا نام لے کر کہتی کہ اے فلاں! یہ تیرا بچہ ہے، اور اس بچے کو اس کے ساتھ ملا دیا جاتا۔ نکاح کی چوتھی قسم یہ تھی کہ بہت سے لوگ جمع ہو جاتے اور ایک عورت سے صحبت کرتے، وہ کسی بھی آنے والے کو منع نہ کرتی، یہ بدکار عورتیں ہوتیں، ان کے دروازوں پر بطور نشانی جھنڈے لگے ہوتے، جو شخص بھی چاہتا ان سے صحبت کرتا، جب وہ حاملہ ہو جاتی اور بچہ جن دیتی تو سب جمع ہو جاتے، اور قیافہ شناس کو بلاتے، وہ جس کا بھی نام لیتا اس کے ساتھ ملا دیا جاتا، وہ بچہ اس کا ہو جاتا اور وہ کچھ نہ کہہ پاتا، تو جب اللہ تعالی نے محمد صلی اللہ علیہ وسلم کو نبی بنا کر بھیجا تو زمانہ جاہلیت کے سارے نکاحوں کو باطل قرار دے دیا سوائے اہل اسلام کے نکاح کے جو آج رائج ہے۔","صحیح",{"u2":"عروہ بن زبیر نے بیان کیا کہ ام المؤمنین سیدہ عائشہ رضی اللہ عنہا ا نے ان (عروہ) کو خبر دی کہ جاہلیت میں چار طرح کے نکاح ہوتے تھے۔ ایک یہ جو آج (اہل اسلام میں) معروف ہے کہ ایک انسان دوسرے کو اس کی زیر تولیت لڑکی کے لیے پیغام بھیجتا ہے، اسے حق مہر ادا کرتا اور پھر اس سے نکاح کر لیتا ہے۔ دوسری قسم یہ تھی کہ آدمی اپنی بیوی سے کہتا، جبکہ وہ حیض سے پاک ہوتی کہ فلاں کو پیغام بھیج دو اور اس سے جا کر ہمبستر ہو۔ پھر اس کا شوہر اس سے علیحدہ رہتا اور اسے ہاتھ نہ لگاتا حتیٰ کہ اس کا حمل ظاہر ہو جاتا جس سے جا کر یہ عورت ہمبستر ہوئی ہوتی۔ جب حمل نمایاں ہو جاتا تو پھر شوہر بھی اگر چاہتا تو اس سے مباشرت کر لیتا۔ اور یہ اس لیے کیا جاتا تھا کہ بچہ شجاع، زکی اور ہونہار پیدا ہو۔ اس نکاح کو «نكاح الاستبضاع» کہا جاتا تھا۔ تیسری قسم یہ تھی کہ ایک جماعت، دس افراد سے کم، اکٹھے ہوتے اور ایک عورت کے پاس جاتے، ہر ایک اس سے صحبت کرتا، جب وہ حاملہ ہو جاتی اور بچہ جنتی اور بچہ جننے کے بعد چند راتیں گزر جاتیں تو وہ ان سب کو بلواتی، اور ان میں سے کوئی بھی آنے سے انکار نہ کر سکتا تھا۔ جب وہ اس کے پاس جمع ہو جاتے تو وہ کہتی تمہیں اپنے معاملے کا علم ہی ہے اور میں نے بچے کو جنم دیا ہے تو یہ بچہ اے فلاں! تیرا ہے۔ وہ ان میں سے جس کا چاہتی نام لے دیتی اور پھر بچہ اس مرد کے ساتھ منسوب ہو جاتا۔ چوتھی قسم یہ تھی کہ بہت سے لوگ اکٹھے ہوتے اور عورت پر داخل ہوتے، وہ کسی کو بھی انکار نہ کرتی اور یہ طوائفیں ہوتی تھیں، انہوں نے اپنے خواہش مندوں کے لیے بطور علامت اپنے دروازوں پر جھنڈے لگائے ہوتے تھے جو بھی ان کا خواہشمند ہوتا ان کے پاس چلا جاتا تھا، جب کوئی حاملہ ہوتی اور بچہ جنتی تو ان لوگوں کو اکٹھا کیا جاتا اور وہ لوگ اپنے لیے کسی قیافہ شناس کو طلب کرتے، پھر وہ اس بچے کو جس کے (مشابہ) دیکھتا، ملحق کر دیتا اور وہ اس کے ساتھ منسوب و ملحق ہو جاتا اور اس کا بیٹا پکارا جاتا، وہ اس کا انکار نہ کر سکتا تھا۔ پھر جب اللہ تعالیٰ نے محمد صلی اللہ علیہ وسلم کو مبعوث فرمایا تو اہل جاہلیت کے تمام نکاحوں کو باطل کر دیا، صرف اہل اسلام کا موجودہ انداز نکاح باقی رکھا۔","f2":"اہل اسلام کے معروف نکاح اور ملک یمن کے علاوہ (متعہ وغیرہ)جتنے بھی انداز ہیں سب حرام ہیں نیز ولی کے بغیر کسی عورت کا نکاح جائز نہیں۔"}],[2273,"ام المؤمنین عائشہ رضی اللہ عنہا سے روایت ہے کہ سعد بن ابی وقاص اور عبد بن زمعہ رضی اللہ عنہما دونوں رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں زمعہ کی لونڈی کے بیٹے کا جھگڑا لے آئے، سعد رضی اللہ عنہ کہنے لگے: میرے بھائی عتبہ نے مجھے وصیت کی تھی کہ جب میں مکہ جاؤں تو زمعہ کی لونڈی کے بچے کو دیکھوں تو اس کو لے لوں کیونکہ وہ انہیں کا بیٹا ہے، اور عبد بن زمعہ رضی اللہ عنہ کہنے لگے: یہ میرا بھائی ہے کیونکہ میرے والد کی لونڈی کا بیٹا ہے، اور میرے والد کے بستر پر اس کی ولادت ہوئی ہے، چنانچہ رسول اللہ صلی اللہ علیہ وسلم نے عتبہ کے ساتھ کھلی مشابہت دیکھی (اس کے باوجود) آپ صلی اللہ علیہ وسلم نے فرمایا: \"بچہ بستر والے کا ہے، اور زانی کے لیے سنگساری ہے، اور سودہ! تم اس سے پردہ کرو\"۔ مسدد نے اپنی روایت میں یہ الفاظ زیادہ کئے ہیں کہ \"آپ نے فرمایا: عبد! یہ تیرا بھائی ہے\"۔","صحیح",{"u2":"ام المؤمنین سیدہ عائشہ رضی اللہ عنہا ا سے مروی ہے کہ سیدنا سعد بن ابی وقاص اور عبد بن زمعہ (یہ ام المؤمنین سودہ رضی اللہ عنہا ا کے بھائی ہیں) اپنا ایک تنازعہ رسول اللہ صلی اللہ علیہ وسلم کے پاس لے کر آئے جو کہ زمعہ کی لونڈی کے بیٹے (کی تولیت) سے متعلق تھا۔ سعد نے کہا: میرے بھائی عتبہ نے مجھے وصیت کی تھی کہ میں (سعد) جب مکے جاؤں تو زمعہ کی لونڈی کے بیٹے کو دیکھوں اور اسے اپنی تولیت میں لے لوں، بلاشبہ وہ میرا ہی بیٹا ہے۔ جبکہ عبد بن زمعہ نے کہا: وہ میرا بھائی ہے، میرے باپ کی لونڈی کا بیٹا ہے، میرے باپ کے بستر پر پیدا ہوا ہے۔ چنانچہ رسول اللہ صلی اللہ علیہ وسلم نے دیکھا کہ بچے اور عتبہ کے مابین واضح مشابہت ہے مگر آپ نے فرمایا ” بچہ بستر والے کا ہے، اور زانی کے لیے پتھر ہیں اور اے سودہ! (ام المؤمنین رضی اللہ عنہا) اس سے پردہ کر۔ “ مسدد نے اپنی روایت میں کہا: ” اے عبد! یہ تیرا ہی بھائی ہے۔ “","f2":"1۔چونکہ یہ معاملات جاہلیت کے تھے اور وہ لوگ اس انداز کے اعمال میں ملوث تھےتو ان بچوں سے بھی کوئی عار نہ سمجھتے تھے مگر اسلام نے یہ قائدہ قانون دیا ہے۔کہ بچہ بستر والے کا ہوتا ہے۔مذکورہ واقعہ میں بچے کی شکل سے نمایاں تھاکہ یہ ولد الزنا ہےاور عتبہ کا لڑکا ہے مگر قاعدہ اور اصول کو ترجیح دی گئی اور اسے صاحب فراش کے ساتھ ملحق کردیا گیا۔قانونئ اعتبار سے یہ اگرچہ حضرت سودہ کا بھائی بنا مگر دعوی اور شکل وصورت زانی کے ساتھ ملتی تھی اس لیے اس کا نسب مشتبہ ٹھرا۔تو نبی صلی اللہ علیہ وسلم نے حضرت سودہ رضی اللہ عنہ کو پردے کا حکم دیا کیونکہ اس کا بھائی ہونا مشکوک تھا۔اگرچہ قاعدے کی رو سے ان کے خاندان کا فرد بنادیا گیا تھا۔\n2۔ (وللعاهر الحجر) کا ایک ترجمہ زانی کے لیے محرومی ہے اس صورت میں جیم پر زبر کے بجائے سکون یعنی جزم آئے گی۔مطلب دونوں صورتوں میں یہی ہوگاکہ اولاد کا مستحق زانی نہیں ہوگا بلکہ اس کے حصے میں سزا آئے گی۔حد رجم یا سو کوڑے اور بچے سےوہ محروم ہی رہے گا۔"}],[2274,"عبداللہ بن عمرو رضی اللہ عنہما کہتے ہیں کہ ایک شخص کھڑا ہوا اور کہنے لگا: اللہ کے رسول! فلاں میرا بیٹا ہے میں نے زمانہ جاہلیت میں اس کی ماں سے زنا کیا تھا، تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اسلام میں اس طرح کا مطالبہ صحیح نہیں، زمانہ جاہلیت کی بات ختم ہوئی، بچہ صاحب بستر کا ہے اور زانی کے لیے سنگساری ہے\"۔","حسن صحیح",{"u2":"عمرو بن شعیب اپنے والد سے اور وہ اپنے دادا سے بیان کرتے ہیں کہ ایک شخص کھڑا ہوا اور کہنے لگا کہ اے اللہ کے رسول! فلاں بچہ میرا بیٹا ہے۔ میں نے جاہلیت میں اس کی ماں سے بدکاری کی تھی تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” اسلام میں اس قسم کا کوئی دعویٰ نہیں چلتا۔ جاہلیت کے امور سب ختم ہیں۔ بچہ بستر والے کا ہے اور اور زانی کے لیے پتھر ہیں۔ (یا محرومی ہے۔) “"}],[2275,"رباح کہتے ہیں کہ میرے گھر والوں نے اپنی ایک رومی لونڈی سے میرا نکاح کر دیا، میں نے اس سے جماع کیا تو اس نے میری ہی طرح کالا لڑکا جنا جس کا نام میں نے عبداللہ رکھا، میں نے پھر جماع کیا تو اس نے میری ہی طرح ایک اور کالے لڑکے کو جنم دیا جس کا نام میں نے عبیداللہ رکھا، اس کے بعد میرے خاندان کے یوحنا نامی ایک رومی غلام نے اسے پھانس لیا اور اس نے اس سے اپنی زبان میں بات کی چنانچہ گرگٹ جیسا (سرخ) رنگ کا بچہ اس سے پیدا ہوا، میں نے پوچھا: یہ کیا ہے؟ کہنے لگی: یہ یوحنا کا بچہ ہے تو ہم نے یہ معاملہ عثمان رضی اللہ عنہ کی عدالت میں پیش کیا، تو انہوں نے ان سے بازپرس کی تو دونوں نے اعتراف کر لیا، پھر انہوں نے ان دونوں سے کہا: کیا تم دونوں اس بات پر رضامند ہو کہ میں تمہارا فیصلہ اس طرح کر دوں جس طرح کہ رسول اللہ صلی اللہ علیہ وسلم نے فیصلہ فرمایا تھا؟ آپ نے فیصلہ فرمایا کہ \"بچہ بستر والے کا ہے\"۔ راوی کا خیال ہے کہ پھر ان دونوں کو کوڑے لگائے، (سنگسار نہیں کیا) کیونکہ وہ دونوں لونڈی و غلام تھے۔","ضعیف",{"u2":"رباح کا بیان ہے کہ میرے گھر والوں نے اپنی ایک رومی لونڈی سے میری شادی کر دی۔ میں اس سے ہمبستر ہوا تو اس نے بچہ جنا، سیاہ رنگ کا، میری طرح۔ میں نے اس کا نام عبداللہ رکھا۔ میں پھر اس کے ساتھ ہمبستر ہوا تو اس نے کالے رنگ کا بچہ جنم دیا، جیسے کہ میں ہوں۔ میں نے اس کا نام عبیداللہ رکھا۔ پھر میرے گھر والوں کے ایک غلام یوحنہ نامی نے اس کے ساتھ خرابی کی، اس کے ساتھ اپنی رومی زبان میں باتیں کیں۔ چنانچہ اس نے بچہ جنا جیسے کہ کوئی سام ابرص (گرگٹ) ہو میں نے لونڈی سے پوچھا: یہ کیا ہے؟ اس نے کہا: یہ یوحنہ سے ہے۔ ہم نے اس کا مقدمہ سیدنا عثمان رضی اللہ عنہ کے سامنے پیش کیا۔ انہوں نے ان دونوں سے پوچھا تو انہوں نے اعتراف کر لیا۔ انہوں نے کہا: کیا تم راضی ہو کہ میں تم میں رسول اللہ صلی اللہ علیہ وسلم والا فیصلہ کروں؟ رسول اللہ صلی اللہ علیہ وسلم نے فیصلہ فرمایا ہے کہ بچہ بستر والے کا ہے۔ راوی نے کہا: میرا خیال ہے پھر آپ نے ان دونوں کو درے لگائے اور وہ دونوں مملوک اور غلام تھے۔"}],[2276,"عبداللہ بن عمرو رضی اللہ عنہما سے روایت ہے کہ ایک عورت نے رسول اللہ صلی اللہ علیہ وسلم سے عرض کیا: اللہ کے رسول! یہ میرا بیٹا ہے، میرا پیٹ اس کا گھر رہا، میری چھاتی اس کے پینے کا برتن بنی، میری گود اس کا ٹھکانہ بنی، اب اس کے باپ نے مجھے طلاق دے دی ہے، اور اسے مجھ سے چھیننا چاہتا ہے، تو آپ صلی اللہ علیہ وسلم نے فرمایا: \"جب تک تو (دوسرا) نکاح نہیں کر لیتی اس کی تو ہی زیادہ حقدار ہے\"۔","حسن",{"u2":"سیدنا عبداللہ بن عمرو رضی اللہ عنہ بیان کرتے ہیں کہ ایک عورت نے کہا: اے اللہ کے رسول! میرا یہ بیٹا، میرا پیٹ اس کے لیے برتن! میرا سینہ اس کے لیے مشکیزہ اور میرا دامن اس کے لیے پناہ گاہ رہا ہے۔ اس کے باپ نے مجھے طلاق دے دی ہے اور چاہتا ہے کہ اس کو مجھ سے چھین لے۔ رسول اللہ صلی اللہ علیہ وسلم نے اس سے فرمایا ” تو اس کی زیادہ حقدار ہے جب تک کہ نکاح نہ کرے۔ “","f2":"یہ صحیح دلیل ہے کہ ماں جب تک نکاح نہ کرے وہ باپ کی نسبت بچے کی زیادہ حقدار ہے اور بعد ازنکاح بھی اگر شوہر راضی ہو تو اپنے پاس رکھ سکتی ہے۔لیکن اگر وہ راضی نہ ہوتو باپ کو دیا جائے گا۔"}],[2277,"ہلال بن اسامہ سے روایت ہے کہ ابومیمونہ سلمی جو اہل مدینہ کے مولی اور ایک سچے آدمی ہیں کا بیان ہے کہ میں ایک بار ابوہریرہ رضی اللہ عنہ کے پاس بیٹھا تھا کہ اسی دوران ان کے پاس ایک فارسی عورت آئی جس کے ساتھ اس کا لڑکا بھی تھا، اس کے شوہر نے اسے طلاق دے دی تھی اور وہ دونوں ہی اس کے دعویدار تھے، عورت کہنے لگی: ابوہریرہ! (پھر اس نے فارسی زبان میں گفتگو کی) میرا شوہر مجھ سے میرے بیٹے کو لے لینا چاہتا ہے۔ ابوہریرہ رضی اللہ عنہ نے کہا: تم دونوں اس کے لیے قرعہ اندازی کرو، ابوہریرہ رضی اللہ عنہ نے بھی فارسی زبان ہی میں اس سے گفتگو کی، اتنے میں اس کا شوہر آیا اور کہنے لگا: میرے لڑکے کے بارے میں مجھ سے کون جھگڑا کر سکتا ہے؟ ابوہریرہ رضی اللہ عنہ نے کہا: یا اللہ! میں نے تو یہ فیصلہ صرف اس وجہ سے کیا ہے کہ میں نے ایک عورت کو کہتے سنا تھا وہ رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں آئی میں آپ کے پاس بیٹھا تھا، وہ کہنے لگی: اللہ کے رسول! میرا شوہر میرے بیٹے کو مجھ سے لے لینا چاہتا ہے، حالانکہ وہ ابوعنبہ کے کنویں سے مجھے پانی لا کر پلاتا ہے اور وہ مجھے فائدہ پہنچاتا ہے، تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"تم دونوں اس کے لیے قرعہ اندازی کرو\"، اس کا شوہر بولا: میرے لڑکے کے متعلق مجھ سے کون جھگڑا کر سکتا ہے تو نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"یہ تیرا باپ ہے، اور یہ تیری ماں ہے، ان میں سے تو جس کا بھی چاہے ہاتھ تھام لے\"، چنانچہ اس نے اپنی ماں کا ہاتھ پکڑ لیا، اور وہ اسے لے کر چلی گئی ۱؎۔\n§وضاحت\n۱؎ : امام شافعی کی یہی دلیل ہے، ان کے نزدیک لڑکے کو اختیار ہو گا کہ وہ جس کو چاہے اختیار کرلے، اور امام ابوحنیفہ کے نزدیک جب تک کم سن ہے ماں کے ساتھ رہے گا، اور جب خود کھانے، پینے، پہنے اور استنجا کرنے لگے تو باپ کے ساتھ ہو جائے گا، یہ قول زیادہ قوی ہے۔","صحیح",{"u2":"ابو میمونہ سلمی، اہل مدینہ میں سے کسی کا مولیٰ تھا اور وہ سچا آدمی تھا۔ اس کا بیان ہے کہ میں سیدنا ابوہریرہ رضی اللہ عنہ کے پاس بیٹھا ہوا تھا کہ ان کے پاس ایک فارسی عورت آئی، اس کے ساتھ اس کا بیٹا بھی تھا۔ شوہر اور بیوی دونوں اس بچے کے دعویدار تھے، اور شوہر نے عورت کو طلاق دے دی تھی۔ عورت نے کہا: اور فارسی زبان میں بولی: اے ابوہریرہ! میرا شوہر میرے بیٹے کو مجھ سے لے لینا چاہتا ہے۔ ابوہریرہ رضی اللہ عنہ نے کہا: اس پر قرعہ ڈال لو، اور اس کو یہ فارسی میں کہا۔ پھر اس کا شوہر آیا تو اس نے کہا: کون ہے جو مجھ سے میرا بیٹا چھینے؟ ابوہریرہ رضی اللہ عنہ نے کہا: «اللهم» (یہ لفظ بطور تبرک بولا جاتا تھا) میرا یہ کہنا اس بنا پر ہے کہ میں نے ایک عورت کو سنا تھا جو رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں آئی تھی اور میں بھی آپ کے پاس بیٹھا ہوا تھا، اس نے کہا: اے اللہ کے رسول! میرا شوہر میرے بچے کو لے لینا چاہتا ہے۔ حالانکہ یہ مجھے ابوعنبہ کے کنویں سے پانی لا کے دیتا ہے اور میری خدمت کرتا ہو۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا اس پر قرعہ ڈال لو۔ تو شوہر نے کہا: مجھ سے میرا بیٹا کون چھین سکتا ہے؟ تو نبی کریم صلی اللہ علیہ وسلم نے فرمایا ” (لڑکے!) یہ تیرا باپ ہے اور یہ تیری ماں ہے، جس کا چاہے ہاتھ پکڑ لے۔ “ چنانچہ اس نے اپنی ماں کا ہاتھ پکڑ لیا، اور وہ اسے لے کر چل دی۔","f2":"بچہ بچی جب خوب سمجھدارہوں تو مذکورہ بالا احوال میں انہیں اختیار دیا جاسکتا ہے۔"}],[2278,"علی رضی اللہ عنہ کہتے ہیں کہ زید بن حارثہ رضی اللہ عنہ مکہ گئے تو حمزہ رضی اللہ عنہ کی صاحبزادی کو لے آئے، جعفر رضی اللہ عنہ کہنے لگے: اسے میں لوں گا، میں اس کا زیادہ حقدار ہوں، یہ میری چچا زاد بہن ہے، نیز اس کی خالہ میرے پاس ہے، اور خالہ ماں کے درجے میں ہوتی ہے، اور علی رضی اللہ عنہ کہنے لگے: اس کا زیادہ حقدار میں ہوں کیونکہ یہ میری چچا زاد بہن ہے، نیز رسول اللہ صلی اللہ علیہ وسلم کی بیٹی میرے نکاح میں ہے، وہ بھی اس کی زیادہ حقدار ہیں اور زید رضی اللہ عنہ نے کہا: سب سے زیادہ اس کا حقدار میں ہوں کیونکہ میں اس کے پاس گیا، اور سفر کر کے اسے لے کر آیا ہوں، اتنے میں نبی اکرم صلی اللہ علیہ وسلم تشریف لے آئے تو علی رضی اللہ عنہ نے آپ سے اس کا ذکر کیا تو آپ صلی اللہ علیہ وسلم نے فرمایا: \"لڑکی کا فیصلہ میں جعفر کے حق میں کرتا ہوں وہ اپنی خالہ کے پاس رہے گی اور خالہ ماں کے درجے میں ہے\"۔","صحیح",{"u2":"سیدنا علی رضی اللہ عنہ نے بیان کیا کہ سیدنا زید بن حارثہ مکہ آئے اور حمزہ کی بیٹی کو ساتھ لے آئے۔ تو جعفر نے کہا: میں اسے (اپنی تولیت میں) لیتا ہوں، میں اس کا زیادہ حقدار ہوں۔ یہ میرے چچا کی بیٹی ہے اور اس کی خالہ میری زوجیت میں ہے، اور خالہ بمنزلہ ماں کے ہوتی ہے۔ اور علی رضی اللہ عنہ نے کہا: میں اس کا زیادہ حقدار ہوں۔ یہ میرے چچا کی بیٹی ہے اور میرے گھر میں رسول اللہ صلی اللہ علیہ وسلم کی صاحبزادی ہے اور وہ اس کی زیادہ حقدار ہے۔ اور زید نے کہا: میں اس کا زیادہ حقدار ہوں۔ میں ہی اس کے پاس گیا، سفر کیا اور اس کو لے کر آیا ہوں۔ پھر نبی کریم صلی اللہ علیہ وسلم تشریف لائے اور بات کی اور فرمایا ” لڑکی کا فیصلہ میں جعفر کے حق میں کرتا ہوں کہ اپنی خالہ کے پاس رہے گی اور خالہ بمنزلہ ماں کے ہوتی ہے۔ “","f2":"بچے کی نگہداشت اور تربیت میں اولویت واولیت ماں کو حاصل ہے جیسے کہ اوپر کی حدیث میں گزرا ہے اس کے بعد خالہ ہے پھر باپ کی جانب کے رشتہ دار ہیں(عصبات)۔امام ابن تیمیہ اور ابن قیم رحمہ اللہ فرماتے ہیں کہ اس تقدیم وترتیب میں بچے کے ھال اور مستقبل کی مصلھت کا خیال رکھنا انتہائی ضروری ہے۔اگر اس میں کسی واضح فتنے کا اندیشہ ہوتو ترتیب کو بدلنا لازمی ہوگا کیونکہ مثلاً بچے کو اختیار دینے کی صورت میں عین ممکن ہےکہ ناقص العقل ہونے کی وجہ صحیح فیصلہ نہ کرسکے۔اور حق حق میراث کی مانند نہیں کہ اس میں محض قرابت داری ہی بنیاد ہو بلکہ یہ حق ولایت ہے جیسے کہ نکاح اور مالی معاملات میں ہوتا ہے اور ان میں مصالح کو ترجیح دی جاتی ہےنہ کہ محض قرابت داری کو۔اسی طرح بچے کی نگہداشت وتربیت میں ایک جانب واضح ظلم ہو اس کے عقیدے تعلیم و تربیت اور اخلاق وعمل کی حفاظت کا اہتمام نہ ہو اور دوسری جانب ان امور کا اہتمام ہو تو دوسری جانب کو ترجیح ہوگی۔(تیسیر العلام شرح عمدہ الاحکام جلد دوم حدیث:332۔نیل الاوطار جلد ششم باب من احق بکفالۃ الطفل)"}],[2279,"عبدالرحمٰن بن ابی لیلی سے یہی حدیث مروی ہے لیکن پوری نہیں ہے اس میں ہے کہ: \"آپ صلی اللہ علیہ وسلم نے فیصلہ فرمایا کہ لڑکی جعفر رضی اللہ عنہ کے پاس رہے گی، کیونکہ ان کے نکاح میں اس کی خالہ ہے\"۔","صحیح",{"u2":"عبدالرحمٰن بن ابی لیلیٰ نے یہ روایت بیان کی مگر کامل بیان نہیں کی اور کہا کہ آپ نے بچی جعفر کو دے دی کیونکہ اس کی خالہ اس کے ہاں ہے۔"}],[2280,"علی رضی اللہ عنہ کہتے ہیں کہ جب ہم مکہ سے نکلے تو ہمارے پیچھے پیچھے حمزہ کی لڑکی چچا چچا پکارتی آ گئی، علی رضی اللہ عنہ ہاتھ پکڑ کر اسے اپنے ساتھ لے آئے اور (فاطمہ رضی اللہ عنہا سے) کہا: اپنے چچا کی لڑکی کو لو، انہوں نے اسے اٹھا لیا، راوی نے پھر پورا قصہ بیان کیا اور کہا کہ: جعفر رضی اللہ عنہ کہنے لگے: یہ میرے چچا کی بیٹی ہے، اور اس کی خالہ میرے نکاح میں ہے چنانچہ رسول اللہ صلی اللہ علیہ وسلم نے خالہ کے حق میں فیصلہ دیا اور فرمایا: \"خالہ ماں کے درجے میں ہے\"۔","صحیح",{"u2":"سیدنا علی رضی اللہ عنہ سے مروی ہے کہ جب ہم مکہ سے نکلے تو حمزہ کی بیٹی ہمارے پیچھے آ گئی، وہ چچا چچا پکار رہی تھی۔ پس سیدنا علی رضی اللہ عنہ نے اس کو لیا اور اس کا ہاتھ پکڑا اور (سیدہ فاطمہ رضی اللہ عنہا ا سے) کہا: اپنی چچا زاد کو لے لو۔ چنانچہ سیدہ فاطمہ رضی اللہ عنہا ا نے اس کو اٹھا لیا۔ اور خبر بیان کی۔ سیدنا جعفر رضی اللہ عنہ نے کہا: یہ میرے چچا کی بیٹی ہے اور اس کی خالہ میری زوجیت میں ہے۔ چنانچہ رسول اللہ صلی اللہ علیہ وسلم نے اس کا فیصلہ خالہ کے حق میں کر دیا اور فرمایا ” خالہ ماں کی طرح ہوتی ہے۔ “"}],[2281,"اسماء بنت یزید بن سکن انصاریہ رضی اللہ عنہا سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم کے زمانے میں انہیں طلاق دے دی گئی، اس وقت مطلقہ کی کوئی عدت نہیں تھی تو اللہ تعالی نے طلاق کی عدت کا حکم نازل فرمایا چنانچہ یہی پہلی خاتون ہیں جن کے متعلق مطلقہ عورتوں کی عدت کا حکم نازل ہوا۔","حسن",{"u2":"سیدہ اسماء بنت یزید بن سکن انصاریہ رضی اللہ عنہا ا سے مروی ہے کہ انہیں رسول اللہ صلی اللہ علیہ وسلم کے زمانے میں طلاق ہو گئی۔ اور (اس سے پہلے) مطلقہ کے لیے کوئی عدت نہ ہوتی تھی (یعنی ایام انتظار) تو اللہ تعالیٰ نے اس اسماء کی طلاق کے موقع پر عدت کا حکم نازل فرمایا۔ اور یہ پہلی عورت تھی جس کے سلسلے میں طلاق یافتہ عورت کی عدت کا حکم اترا۔","f2":"حضرت اسماء بنت یزید رضی اللہ کے متعلق آتاہے کہ یہ حضرت معاذبن جبل رضی اللہ کی پھوپھی زاد تھیں۔ رسول اللہ صلی اللہ علیہ وسلم سے بیعت کی تھی۔ عورتوں کی طرف سے رسول اللہ صلی اللہ علیہ وسلم کے ہا ں پیغام بھی لے جایا کرتی تھیں انہوں نے غزوہ یرموک کے موقع پر اپنے خیمے کے بانس سے نو عددرومیوں کو قتل کیا تھا.(افادات از.علامہ احمدمحمدشاکر)"}],[2282,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ اللہ تعالی نے ارشاد فرمایا: «والمطلقات يتربصن بأنفسهن ثلاثة قروء» \"اور طلاق دی ہوئی عورتیں اپنے آپ کو تین طہر تک روکے رکھیں\" (سورۃ البقرہ: ۲۲۸) اور فرمایا: «واللائي يئسن من المحيض من نسائكم إن ارتبتم فعدتهن ثلاثة أشهر» \"اور تمہاری وہ عورتیں جو حیض سے ناامید ہو گئی ہوں اگر تمہیں شبہ ہو تو ان کی عدت تین مہینے ہے\"(سورۃ الطلاق: ۴) تو یہ عورتیں پہلی آیت کے حکم سے نکال لی گئیں ہیں، اسی طرح اللہ تعالی نے فرمایا: «وإن طلقتموهن من قبل أن تمسوهن» \"اگر تم انہیں چھونے سے پہلے ہی طلاق دے دو تو انہیں کوئی عدت گزارنے کی ضرورت نہیں\" (سورۃ الاحزاب: ۴۹) اس آیت میں مذکور عورتوں کو بھی پہلی آیت کے حکم سے نکال دیا گیا ہے۔","حسن",{"u2":"سیدنا ابن عباس رضی اللہ عنہ سے مروی ہے کہ (اللہ کا جو فرمان ہے) ” طلاق والی عورتیں تین حیض انتظار کریں۔ “ (تو اس سے وہ عورتیں نکال دی گئیں جو حیض سے مایوس ہو جائیں) اور ان کے لیے کہا کہ ” تمہاری جو عورتیں حیض سے مایوس ہوں، اگر تمہیں کوئی شبہ ہو تو ان کی عدت تین ماہ ہے۔ “ پھر ان میں سے مزید یہ استثنا فرمایا ” اگر تم انہیں مساس سے قبل ہی طلاق دے دو تو ان پر کوئی عدت نہیں۔ “ (الاحزاب 49)","f2":"حضرت ابن عباس نے اسے نسخ یا استثنا سے تعبیر فرمایا ہے،لیکن دراصل مختف صورتوں کے مختلف احکام ہیں۔ عام مطلقہ عورت کی عدت تین حیض (یا تین طہر)ہیں۔ لیکن جس کو حیض آنا بند ہو گیا ہو یا جیسے حیض آنا شروع ہی نہیں ہوا تو ان کی عدت تین مہینے ہو گی اور جس عورت کو خلوت اور مساس سے پہلے طلاق دے دی جائے تو اسکے لئے کوئی عدت ہی نہیں ہے۔ اسی طرح جو عورت حاملہ ہو اسے طلاق مل جائے یا اس کا خاوند فوت ہو جائے تو اس کی عدت وضع حمل ہے جبکہ بیوہ عورت کی عدت چار مہینے دس دن ہے۔"}],[2283,"عمر رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے ام المؤمنین حفصہ رضی اللہ عنہا کو طلاق دی پھر آپ نے ان سے رجعت کر لی۔","صحیح",{"u2":"سیدنا عمر رضی اللہ عنہ سے مروی ہے کہ نبی کریم صلی اللہ علیہ وسلم نے سیدہ حفصہ رضی اللہ عنہا ا کو طلاق دے دی، مگر پھر آپ صلی اللہ علیہ وسلم نے ان سے رجوع کر لیا۔","f2":"1:پہلی اور دوسری طلاق کے بعد عدت کے دوران میں رجوع کیا جا سکتا ہے اور چاہیے کہ دوگوارہ ضرور بنائے جائیں\n2: حضرت حفصہ رضی اللہ سے رجوع کے بارے میں جناب قیس بن زید (تابعی صغیر) کی مرسل روایت میں ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: جبرئیل میرے پاس آئے اور کہا کہ حفصہ سے رجوع فرمالیں۔ یہ بہت روزے رکھنے والی اور بہت قیام کرنے والی خاتون ہیں اور جنت میں آپ کی بیوی ہیں .ارواء الغلیل‘حدیث نمبر2077)"}],[2284,"ابوسلمہ بن عبدالرحمٰن فاطمہ بنت قیس رضی اللہ عنہا کے بارے میں روایت کرتے ہیں کہ ابوعمرو بن حفص رضی اللہ عنہ نے انہیں طلاق بتہ دے دی ۱؎ ابوعمرو موجود نہیں تھے تو ان کے وکیل نے فاطمہ کے پاس کچھ جو بھیجے، اس پر وہ برہم ہوئیں، تو اس نے کہا: اللہ کی قسم! تمہارا ہم پر کوئی حق نہیں بنتا، تو وہ رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوئیں اور ماجرا بیان کیا تو آپ صلی اللہ علیہ وسلم نے فاطمہ سے فرمایا: \"اس کے ذمہ تمہارا نفقہ نہیں ہے\" پھر آپ صلی اللہ علیہ وسلم نے انہیں ام شریک کے گھر میں عدت گزارنے کا حکم دیا، پھر آپ صلی اللہ علیہ وسلم نے فرمایا: \"یہ ایک ایسی عورت ہے کہ اس کے پاس میرے صحابہ کا اکثر آنا جانا لگا رہتا ہے، لہٰذا تم ابن ام مکتوم کے گھر میں عدت گزارو کیونکہ وہ نابینا ہیں، پردے کی دقت نہ ہو گی، تم اپنے کپڑے اتار سکو گی، اور جب عدت مکمل ہو جائے تو مجھے اطلاع دینا\"۔ فاطمہ رضی اللہ عنہا کا بیان ہے کہ جب عدت گزر گئی تو میں نے رسول اللہ صلی اللہ علیہ وسلم کے سامنے معاویہ بن ابی سفیان اور ابوجہم رضی اللہ عنہما کے پیغام کا ذکر کیا، آپ صلی اللہ علیہ وسلم نے فرمایا: \"رہے ابوجہم تو وہ کندھے سے لاٹھی ہی نہیں اتارتے (یعنی بہت زدو کوب کرنے والے شخص ہیں) اور جہاں تک معاویہ کا سوال ہے تو وہ کنگال ہیں، ان کے پاس مال نہیں ہے۲؎، لہٰذا تم اسامہ بن زید سے نکاح کر لو\"، فاطمہ رضی اللہ عنہا کا بیان ہے کہ وہ مجھے پسند نہیں آئے، آپ صلی اللہ علیہ وسلم نے پھر فرمایا کہ اسامہ بن زید سے نکاح کر لو، چنانچہ میں نے اسامہ سے نکاح کر لیا تو اللہ تعالی نے اس میں اس قدر بھلائی رکھی کہ لوگ مجھ پر رشک کرنے لگے۔\n§وضاحت\n۱؎ : بعض روایتوں میں ہے ’’انہیں تین طلاق دی‘‘ اور بعض میں ہے ’’انہیں تین طلاق میں سے آخری طلاق دی‘‘ اور بعض میں ہے ’’انہیں ایک طلاق بھیجی جو باقی رہ گئی تھی‘‘ ان روایات میں تطبیق اس طرح دی جاتی ہے کہ وہ انہیں اس سے پہلے دو طلاق دے چکے تھے اور اس بار تیسری طلاق دی، تو جس نے یہ روایت کیا ہے کہ انہوں نے تین طلاق میں سے آخری طلاق دی یا وہ طلاق دی جو باقی رہ گئی تھی تو وہ اصل صورت حال کے مطابق ہے اور جس نے روایت کی ہے کہ طلاق بتہ دی تو اس کی مراد یہ ہے کہ ایسی طلاق دی جس سے وہ مبتوتہ ہو گی اور جس نے روایت کی ہے کہ تین طلاق دی تو اس کی مراد یہ ہے کہ تین میں جو کمی رہ گئی تھی اسے پورا کر دیا۔ ۲؎ : صلاح و مشورہ دینے میں کسی کا حقیقی اور واقعی عیب بیان کرنا درست ہے تاکہ مشورہ لینے والا دھوکہ نہ کھائے، یہ غیبت میں داخل نہیں۔","صحیح",{"u2":"سیدہ فاطمہ بنت قیس رضی اللہ عنہا ا سے مروی ہے کہ (ان کے شوہر) ابوعمرو بن حفص نے ان کو طلاق بتہ دے دی تھی (مختلف اوقات میں تین طلاقیں) اور وہ خود (گھر میں) موجود نہیں تھے۔ تو ان کے وکیل نے فاطمہ کی طرف کچھ ” جَو “ بھیجے تو انہوں نے ان کو کم سمجھا اور اس پر راضی نہ ہوئیں۔ تو وکیل نے کہا: قسم اللہ کی! (اخراجات کے سلسلے میں) تیرے لیے ہم پر کوئی چیز واجب ہی نہیں ہے۔ تو وہ رسول اللہ صلی اللہ علیہ وسلم کے پاس آئیں اور آپ سے اس کا ذکر کیا، آپ نے اس سے فرمایا ” اس کے ذمے تمہارا کوئی خرچ نہیں ہے۔ “ اور اسے حکم دیا کہ ام شریک کے گھر میں عدت گزارے۔ پھر فرمایا ” اس عورت کے ہاں میرے صحابہ آتے رہتے ہیں، تو ابن ام مکتوم کے گھر میں عدت گزارو۔ وہ نابینا آدمی ہے، تمہیں اپنے کپڑے اتارنے میں بھی آسانی رہے گی اور جب تم حلال ہو جاؤ (تمہارے ایام عدت گزر جائیں) تو مجھے اطلاع دینا۔ “ کہتی ہیں کہ جب میں حلال ہو گئی تو میں نے آپ صلی اللہ علیہ وسلم کو بتایا کہ معاویہ بن ابی سفیان اور ابوجہم نے مجھے نکاح کا پیغام بھیجا ہے۔ تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” ابوجہم تو اپنے کندھے سے لٹھ ہی نہیں اتارتا ہے۔ اور معاویہ، تو وہ فقیر آدمی ہے، اس کے پاس کوئی مال نہیں ہے۔ تم اسامہ بن زید سے نکاح کر لو۔ “ کہتی ہیں کہ میں نے اس کو ناپسند کیا۔ آپ نے پھر فرمایا ” اسامہ بن زید سے نکاح کر لو۔ “ چنانچہ میں نے ان سے نکاح کر لیا۔ اللہ تعالیٰ نے اس میں بہت خیر (اور برکت) فرمائی اور اس وجہ سے مجھ پر رشک کیا جاتا تھا۔","f2":"شوہر جب اپنی بیوی کو مختلف اوقات میں تین طلاقیں دے دے،تو اسے رجوع کاحق حاصل نہیں رہتا۔ ایسی طلاق کو بتہ کہتے ہیں، لغت میں بت کے معنی ہیں کاٹ دینا کسی امرکو نافذکردینا۔ اردومیں مستعمل لفظ البتہ بمعنی یقین کا ماخذبھی یہی ہے۔"}],[2285,"یحیی بن ابی کثیر کہتے ہیں کہ ابوسلمہ بن عبدالرحمٰن نے مجھ سے بیان کیا کہ فاطمہ بنت قیس رضی اللہ عنہا نے ان سے بیان کیا کہ ابو حفص بن مغیرہ رضی اللہ عنہ نے انہیں تینوں طلاقیں دے دیں، پھر راوی نے پوری حدیث بیان کی، اس میں ہے کہ خالد بن ولید رضی اللہ عنہ اور بنی مخزوم کے کچھ لوگ رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں آئے اور انہوں نے عرض کیا: اللہ کے نبی! ابو حفص بن مغیرہ نے اپنی بیوی کو تینوں طلاقیں دے دی ہیں، اور اسے معمولی نفقہ (خرچ) دیا ہے، تو آپ صلی اللہ علیہ وسلم نے فرمایا: \"اس کے لیے نفقہ نہیں ہے\"، پھر راوی نے پوری حدیث بیان کی، یہ مالک کی روایت زیادہ کامل ہے ۱؎۔\n§وضاحت\n۱؎ : اس حدیث سے واضح طور پر ثابت ہوا کہ تین طلاق دی ہوئی عورت کے لئے نہ نفقہ ہے، اور نہ سکنی (رہائش)، نفقہ و سکنی رجعی طلاق میں ہے، اس امید میں کہ شاید شوہر کے دل کے اندر رجوع کی بات پیدا ہو جائے، اور رجوع کر لے۔","صحیح",{"u2":"سیدہ فاطمہ بنت قیس رضی اللہ عنہا ا نے بیان کیا کہ ابوحفص بن مغیرہ نے مجھے تین طلاقیں دیں۔ اور پوری حدیث بیان کی، اس میں ہے کہ خالد بن ولید اور بنو مخزوم کے اور بھی لوگ نبی کریم صلی اللہ علیہ وسلم کی خدمت میں آئے اور کہا: یا رسول اللہ! ابو حفص بن مغیرہ نے اپنی بیوی کو تین طلاقیں دے دی ہیں اور بہت تھوڑا سا خرچ اس کے لیے چھوڑ گیا ہے۔ تو آپ صلی اللہ علیہ وسلم نے فرمایا ” اس کے لیے کوئی خرچہ نہیں ہے۔ “ اور حدیث بیان کی۔ اور مالک کی (مذکورہ بالا) روایت اس سے زیادہ کامل ہے۔","f2":"1: حضرت فاطمہ کو یہ طلاقیں وقفے وقفے سے دی گئی تھیں نہ کہ اکٹھی جیسے کہ اگلی حدیث 6689 میں آرہا ہے۔\n2: مطلقہ کو ہدیہ وتحفہ دینا ایک مستحب کا م ہے جس کی تاکید آئی ہے (الاحزاب:29)اور تین طلاق والی کے لئے کوئی نفقہ وسکنی واجب نہیں ہے الا یہ کہ حاملہ ہو۔\n3:عورت کے لئے مرد کو دیکھنا ممنوع نہیں ہے (بشرطیکہ شہوت سے نہ ہو)اسی لیے نبی صلی اللہ علیہ وسلم نے حضرت فاطمہ ابن ام مکتوم کے پاس عدت گزارنے کا حکم دیا تا کہ وہ مردوں کی نظروں سے محفوظ رہے کیو نکہ مردوں کے لئے عورت کو دیکھنا ممنوع ہے اور ابن ام مکتوم بینائی ہی سے محروم تھے۔\n4:نکاح کا پیغام دینے والے کے لئے دینی،دنیاوی اور اخلاقی احوال کا جائزہ لے کر ہی اسے قبول کیا جا ناچاہیے۔\n5:شرعی ضرورت سے کسی کا عیب بیان کرنا ایسی غیبت نہیں جوحرام ہو،\n6: دین دار رشتوں میں اللہ کی طرف سے بہت برکت ہوتی ہے۔"}],[2286,"ابوسلمہ بن عبدالرحمٰن بن عوف الزہری کہتے ہیں کہ مجھ سے فاطمہ بنت قیس رضی اللہ عنہا نے بیان کیا کہ ابوعمرو بن حفص مخزومی رضی اللہ عنہ نے انہیں تینوں طلاقیں دے دیں، پھر راوی نے پوری حدیث ذکر کی اور خالد بن ولید رضی اللہ عنہ والا قصہ بیان کیا کہ انہوں نے کہا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ہے: \"نہ تو اس کے لیے نفقہ ہے اور نہ رہائش\"، نیز نبی اکرم صلی اللہ علیہ وسلم نے اسے یہ خبر بھیجی کہ تو اپنے بارے میں مجھ سے سبقت نہ کرنا ۱؎۔\n§وضاحت\n۱؎ : یعنی مجھ سے پوچھے بغیر شادی نہ کر لینا۔","صحیح",{"u2":"سیدہ فاطمہ بنت قیس رضی اللہ عنہا ا نے بیان کیا کہ ابوعمرو بن حفص مخزومی نے اس کو تین طلاقیں دے دیں۔ اور حدیث بیان کی اور خالد بن ولید کی بات بھی۔ کہا کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا ” اس کے لیے خرچہ نہیں ہے اور نہ کوئی سکنی ہے۔ “ (شوہر کے ذمے نہیں ہے۔) اس روایت میں ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فاطمہ کی طرف پیغام بھیجا کہ اپنے بارے میں میرے مشورے کے بغیر جلدی میں کوئی فیصلہ نہ کر لینا۔","f2":"1:نکاح اور دیگر اہم معاملات میں صالح اور مخلص اہل نظر سے مشورہ ضرور کرلینا چاہیے۔ ایسے ہی استخارہ بھی لازماکرنا چاہیے۔\n2: فاطمہ بنت قیس رضی اللہ کے شوہر کا نام اکثر روایات میں ابو حفصبن مغیرہ آیا ہے اور کچھ میں یوں ابو عمروبن حفص بن مغیرہ۔"}],[2287,"فاطمہ بنت قیس رضی اللہ عنہا کہتی ہیں کہ میں قبیلہ بنی مخروم کے ایک شخص کے نکاح میں تھی اس نے مجھے طلاق بتہ دے دی، پھر راوی نے مالک کی حدیث کے مثل حدیث بیان کی اس میں «ولا تفوتيني بنفسك» ہے۔ ابوداؤد کہتے ہیں: اسی طرح اسے شعبی اور بہی نے اور عطاء نے بواسطہ عبدالرحمٰن بن عاصم اور ابوبکر بن جہم اور سبھوں نے فاطمہ بنت قیس رضی اللہ عنہا سے روایت کیا ہے کہ \"انہیں ان کے شوہر نے تین طلاق دی\" (نہ کہ طلاق بتہ) ۔","صحیح",{"u2":"سیدہ فاطمہ بنت قیس رضی اللہ عنہا ا نے بیان کیا کہ میں بنی مخزوم کے ایک شخص کی زوجیت میں تھی تو اس نے مجھے طلاق بتہ دے دی (تین طلاقیں) اور (اس باب کی پہلی حدیث) مالک کی روایت کی مانند بیان کیا۔ اس روایت میں کہا کہ مجھے بتائے بغیر اپنے بارے میں کوئی فیصلہ نہ کر لینا۔ امام ابوداؤد رضی اللہ عنہ فرماتے ہیں کہ شعبی «بهي» اور عطاء نے بواسطہ عبدالرحمٰن بن عاصم اور اسی طرح ابوبکر بن ابی جہم ان سب نے فاطمہ بنت قیس سے روایت کی ہے کہ اس کے شوہر نے اس کو تین طلاقیں دی تھیں۔ (ان حضرات کی روایت میں بتہ کا ذکر نہیں ہے۔)"}],[2288,"فاطمہ بنت قیس رضی اللہ عنہا سے روایت ہے کہ ان کے شوہر نے انہیں تین طلاق دے دی تو رسول اللہ صلی اللہ علیہ وسلم نے نہ تو انہیں نفقہ دلایا، اور نہ ہی رہائش دلائی۔","صحیح",{"u2":"شعبی سیدہ فاطمہ بنت قیس رضی اللہ عنہا ا سے بیان کرتے ہیں کہ ان کے شوہر نے ان کو تین طلاقیں دی تھیں تو نبی کریم صلی اللہ علیہ وسلم نے اس کے لیے کوئی خرچہ اور رہائش (شوہر پر) لازم نہیں کی تھی۔"}],[2289,"ابوسلمہ بن عبدالرحمٰن بن عوف الزہری کہتے ہیں کہ فاطمہ بنت قیس رضی اللہ عنہا نے انہیں خبر دی کہ وہ ابوحفص بن مغیرہ رضی اللہ عنہ کے عقد میں تھیں، اور ابوحفص نے انہیں تین طلاق میں سے آخری طلاق بھی دے دی تو وہ رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوئیں اور اپنے گھر نکلنے کے متعلق آپ صلی اللہ علیہ وسلم سے فتوی پوچھا تو آپ نے انہیں نابینا ابن ام مکتوم رضی اللہ عنہ کے گھر منتقل ہو جانے کا حکم دیا ۱؎۔ مروان نے یہ حدیث سنی تو مطلقہ کے گھر سے نکلنے کے سلسلہ میں فاطمہ رضی اللہ عنہا کی حدیث کی تصدیق کرنے سے انکار کیا، عروہ کہتے ہیں: ام المؤمنین عائشہ رضی اللہ عنہا نے بھی فاطمہ بنت قیس رضی اللہ عنہا کی بات کا انکار کیا۔\n§وضاحت\n۱؎ : مطلقہ کا عدت گزارنے کے لئے گھر سے نکل کر کسی اور جگہ رہنا درست نہیں ہے، الا یہ کہ کوئی سخت ضرورت لاحق ہو جائے مثلا کرائے کا مکان ہو، اور کرایہ دینے کی طاقت نہ ہو، یا مکان گر پڑے، یا مالک مکان جبرا نکال دے، یا علاج و معالجہ کی ضرورت ہو، یا کوئی دیکھ بھال کرنے والا نہ ہو۔","صحیح",{"u2":"سیدہ فاطمہ بنت قیس رضی اللہ عنہا ا نے خبر دی کہ وہ ابو حفص بن مغیرہ کی زوجیت میں تھی تو اس نے اسے آخری تیسری طلاق دے دی۔ پھر وہ کہتی ہے کہ وہ رسول اللہ صلی اللہ علیہ وسلم کے پاس آئی اور آپ صلی اللہ علیہ وسلم سے پوچھا کہ کیا وہ اپنے گھر سے چلی جائے (شوہر کے گھر سے) تو آپ صلی اللہ علیہ وسلم نے حکم دیا کہ ابن ام مکتوم نابینا کے گھر منتقل ہو جائے۔ مگر مروان نے فاطمہ کی اس بات کی، کہ مطلقہ اپنے گھر سے نکل سکتی ہے، تصدیق کرنے سے انکار کیا ہے۔ ¤ عروہ کہتے ہیں کہ سیدہ عائشہ رضی اللہ عنہا ا نے بھی فاطمہ بنت قیس پر انکار کیا ہے۔ ¤ امام ابوداؤد رضی اللہ عنہ نے کہا: صالح بن کیسان، ابن جریج اور شعیب بن ابی حمزہ سب زہری سے اسی طرح روایت کرتے ہیں (جیسے عقیل نے کی ہے) امام ابوداؤد رضی اللہ عنہ نے کہا: شعیب کے والد ابوحمزہ کا نام دینار ہے جو زیاد کا مولیٰ تھا۔","f2":"اس روایت میں اختصار ہے جبکہ آگے آنے والی روایت میں وضاحت ہے مروا ن نے قبیصہ بن ذویب کو بھیج کر یہ تفصیل معلوم کی تھی۔"}],[2290,"عبیداللہ بن عبداللہ بن عتبہ کہتے ہیں کہ مروان نے فاطمہ بنت قیس رضی اللہ عنہا کو بلوایا، اور ان سے پوچھا تو انہوں نے بتایا کہ وہ ابوحفص رضی اللہ عنہ کے عقد میں تھیں، اور نبی اکرم صلی اللہ علیہ وسلم نے علی رضی اللہ عنہ کو یمن کا یعنی یمن کے بعض علاقے کا امیر بنا کر بھیجا تو ان کے شوہر بھی علی رضی اللہ عنہ کے ساتھ گئے اور وہیں سے انہیں بقیہ ایک طلاق بھیج دی، اور عیاش بن ابی ربیعہ اور حارث بن ہشام کو انہیں نفقہ دینے کے لیے کہہ دیا تو وہ دونوں کہنے لگے: اللہ کی قسم حاملہ ہونے کی صورت ہی میں وہ نفقہ کی حقدار ہو سکتی ہیں، چنانچہ وہ رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوئیں (اور آپ سے دریافت کیا) آپ صلی اللہ علیہ وسلم نے فرمایا: \"تمہارے لیے نفقہ صرف اس صورت میں ہے کہ تم حاملہ ہو\"، پھر فاطمہ نے گھر سے منتقل ہونے کی اجازت مانگی تو آپ صلی اللہ علیہ وسلم نے اجازت دے دی، پھر فاطمہ نے کہا: اللہ کے رسول! میں کہاں جاؤں؟ آپ صلی اللہ علیہ وسلم نے فرمایا: \"ابن ام مکتوم کے گھر میں جا کر رہو، وہ نابینا ہیں، سو وہ ان کے پاس کپڑے بھی اتارتی تھیں تو وہ اسے دیکھ نہیں پاتے تھے\"، چنانچہ وہ وہیں رہیں یہاں تک کہ ان کی عدت پوری ہو گئی پھر رسول اللہ صلی اللہ علیہ وسلم نے ان کا نکاح اسامہ رضی اللہ عنہ سے کر دیا۔ تو قبیصہ ۱؎ مروان کے پاس واپس آئے اور انہیں اس کی خبر دی تو مروان نے کہا: ہم نے یہ حدیث صرف ایک عورت کے منہ سے سنی ہے ہم تو اسی مضبوط اور صحیح بات کو اپنائیں گے جس پر ہم نے لوگوں کو پایا ہے، فاطمہ رضی اللہ عنہا کو اس کا علم ہوا تو کہنے لگیں: میرے اور تمہارے درمیان اللہ کی کتاب فیصلہ کرے گی، اللہ کا فرمان ہے «فطلقوهن لعدتهن» ، «لا تدري لعل الله يحدث بعد ذلك أمرا» ۲؎ تک\"یعنی خاوند کا دل مائل ہو جائے اور رجوع کر لے\" فاطمہ رضی اللہ عنہا نے کہا: تین طلاق کے بعد کیا نئی بات ہو گی؟ ۳؎۔ ابوداؤد کہتے ہیں: اور اسی طرح اسے یونس نے زہری سے روایت کیا ہے، رہے زبیدی تو انہوں نے دونوں حدیثوں کو ملا کر ایک ساتھ روایت کیا ہے یعنی عبیداللہ کی حدیث کو معمر کی حدیث کے ہم معنی اور ابوسلمہ کی حدیث کو عقیل کی حدیث کے ہم معنی روایت کیا ہے۔ اور اسے محمد بن اسحاق نے زہری سے روایت کیا ہے اس میں ہے کہ قبیصہ بن ذویب نے ان سے اس معنی کی حدیث بیان کی ہے جس میں عبیداللہ بن عبداللہ کی حدیث پر دلالت ہے جس وقت انہوں نے یہ کہا کہ قبیصہ مروان کے پاس لوٹے اور انہیں اس واقعہ کی خبر دی۔\n§وضاحت\n۱؎ : جیسا کہ آگے اس کی تصریح آ رہی ہے۔ ۲؎ : انہیں ان کی عدت میں یعنی طہر کے شروع میں طلاق دو، اور مدت کا حساب رکھو، اور اللہ سے جو تمہارا پروردگار ہے ڈرتے رہو نہ تم انہیں ان کے گھروں سے نکالو اور نہ خود نکلیں، ہاں یہ اور بات ہے کہ وہ کھلی برائی کر بیٹھیں یہ اللہ کی مقرر کردہ حدیں ہیں جو شخص اللہ کی حدوں سے آگے بڑھ جائے، اس نے یقینا اپنے اوپر ظلم کیا، تم نہیں جانتے، شاید اس کے بعد اللہ تعالی کوئی نئی بات پیدا کر دے۔ ۳؎ : اس سے معلوم ہوا کہ گھر سے نہ نکلنا یا نہ نکالنا صرف پہلی اور دوسری طلاق کے بعد ہے۔","صحیح",{"u2":"عبیداللہ (بن عبداللہ بن عتبہ) سے مروی ہے کہ مروان نے فاطمہ (بنت قیس) کو پیغام بھیجا اور ان سے پچھوایا، تو اس نے بتایا کہ وہ ابوحفص کی زوجیت میں تھی اور نبی کریم صلی اللہ علیہ وسلم نے سیدنا علی رضی اللہ عنہ کو یمن کے کچھ حصے کا عامل بنایا، تو اس کا شوہر بھی ان کے ساتھ روانہ ہو گیا اور اس کو طلاق کا پیغام دے گیا، وہ طلاق جو اس کی باقی تھی (تیسری طلاق) اور عیاش بن ابی ربیعہ اور حارث بن ہشام کو کہہ گیا کہ اس کو خرچ دینا، تو ان دونوں نے کہا: اللہ کی قسم! اس کے لیے کوئی خرچہ نہیں الا یہ کہ حاملہ ہو۔ تو یہ نبی کریم صلی اللہ علیہ وسلم کے پاس چلی آئی، تو آپ صلی اللہ علیہ وسلم نے فرمایا ” تیرے لیے کوئی خرچہ نہیں الا یہ کہ تو حاملہ ہو۔ “ پھر اس نے اجازت چاہی کہ (اس گھر سے) منتقل ہو جائے تو آپ صلی اللہ علیہ وسلم نے اس کو اجازت دے دی۔ کہنے لگی: اے اللہ کے رسول! میں کہاں رہوں؟ آپ صلی اللہ علیہ وسلم نے فرمایا ” ابن ام مکتوم کے ہاں۔ “ اور وہ نابینا تھے (کسی وقت) یہ اپنے کپڑے اتار بھی دیتی تو دیکھ نہ سکتے تھے۔ پھر وہ ان کے ہاں رہی حتیٰ کہ اس کی عدت پوری ہو گئی۔ تب نبی کریم صلی اللہ علیہ وسلم نے اسامہ رضی اللہ عنہ سے اس کا نکاح کر دیا۔ قبیصہ، مروان کے پاس واپس آیا اور یہ ساری خبر بتائی۔ تو مروان نے کہا: ہم ایک عورت سے یہ حدیث سن رہے ہیں اور ہم وہی محفوظ اور قابل اعتماد بات قبول کریں گے جس پر لوگوں کا عمل ہے۔ فاطمہ کو جب یہ بات پہنچی تو اس نے کہا: میرے اور تمہارے درمیان کتاب اللہ فیصل ہے۔ اللہ تعالیٰ نے فرمایا ہے«فطلقوهن لعدتهن حتى لا تدري لعل الله يحدث بعد ذلك أمرا» فاطمہ نے کہا: بھلا تیسری طلاق کے بعد کون سا نیا معاملہ ہو گا؟ (رجوع کا موقع ہی نہیں رہا تو نیا معاملہ کیسے ہو سکتا ہے) امام ابوداؤد رضی اللہ عنہ کہتے ہیں کہ یہ روایت یونس نے بھی زہری سے اسی طرح بیان کی ہے۔ اور (محمد بن ولید) زبیدی نے دونوں روایتیں بیان کی ہیں۔ عبیداللہ کی روایت معمر کے ہم معنی اور ابوسلمہ کی عقیل کے ہم معنی۔ امام ابوداؤد رضی اللہ عنہ نے کہا: محمد بن اسحٰق نے زہری سے روایت کی ہے مگر اس میں قبیصہ بن ذویب نے اس کو بالمعنی نقل کیا ہے۔ اس کی دلیل عبیداللہ بن عبداللہ کی روایت ہے جس میں ہے کہ ” پھر قبیصہ، مروان کے پاس واپس آیا اور یہ ساری خبر بتائی۔ “","f2":"1: اس حدیث کا پس منظر آئندہ حدیث 2294 میں آرہا ہے۔\n2: حضرت مروان بن حکم کا،جو اس دور میں حاکم مدینہ تھے،حضرت عائشہ رضی اللہ اور ایسے ہی عمربن خطاب رضی اللہ کا موقف یہ تھا کہ مطلقہ کے لئے ایام عدت میں سکنی شوہر کے ذمے ہے (اور بعض لوگ ا ب بھی اسی کے قائل ہیں۔)ان حضرات کا استدلال سورۃ طلاق کی آیات سے ہے اس میں ہے (لا تخرجو ھن من بیوتھن ولا یخرجن)(الطلاق 1) تم انہیں ان کے گھروں سے مت نکالواور نہ وہ از خود نکلیں۔ ایک اور آیت میں ہے(اسکنوھن من حیث سکنتم من وجدکم)(الطلاق 2) اپنی حیثیت کے مطابق انہیں سکونت مہیا کرو مگراس مناقشے میں حضرت فاطمہ بنت قیس رضی اللہ کی بات واضح اور راجح ہے کہ رسول صلی اللہ علیہ وسلم نے تین طلاق والی کے لئے کوئی نفقہ وسکنی نہیں فرمایا اورچونکہ یہ خود صاحب واقعہ ہیں تو انہی کی بات قابل قبول ہو گی۔ قرآن مجید کی مذکور ہ آیات کا مفہوم ان عورتوں کے متعلق ہے جنہیں رجعی طلاق ہوئی ہو۔\n3: حضرت مروان نے جو یہ کہا کہ:ہم ایک عورت سے یہ حدیث سن رہے ہیں تو یہ جرح قابل سماع نہیں ہے امام ابن قیم رحمہ اللہ نے زاد المعاد میں اور علامہ شوکانی رحمہ اللہ نے کیا خوب لکھا ہےکہ یہ جرح یا جماع مسلمین باطل ہے،کیونکہ کسی بھی عالم سے یہ منقول نہیں کہ کوئی حدیث کسی عورت کی روایت ہونے کی بناپر مرد قرار پاتی ہے کتنی ہی مقبول ومعمول سنتیں ہیں جن کی رادی صحابیات ہیں اور وہ ان کی روایت میں اکیلی ہیں علم حدیث سے ادنی واقفیت رکھنے والایہ انکار نہیں کرسکتااور مسلمانوں میں سے کسی نے بھی کوئی حدیث محض اس بنا پر رد نہیں کی ممکن ہے اس کا راوی بھول گیا ہو اگر یہ نقد قابل اعتنا سمجھاجائے تو احادیث نبویہ میں سے کوئی حدیث بھی مقبول نہ رہے گی کیو نکہ بھول سکنے سے کون سا انسان مبرا ہے اس طرح تو تما م سنن نبویہ سے معطل قرار دینا پڑے گا اور زیربحث حدیث کی راویہ حضرت فاطمہ بنت قیس رضی اللہ ان جلیل القدرصحابیات میں سے ہیں جہنوں نے ابتدا ہی میں ہجرت کرلی تھی اور وہ اپنے حفظ ودانش میں مشہورتھیں۔ وجال کے متعلق طویل حدیث ان ہی کی روایت کردہ ہے جو انہوں نے رسول صلی اللہ علیہ وسلم سے اثنائے خطبہ میں ایک ہی بار سنی اور یاد کر لی تھی اور کس طرح باور کیا جا سکتا ہے کہ طلاق اور نان ونفقہ اور سکنی جیسا جو ان کی زندگی کا اپنا اہم واقعہ تھا وہ بھول گئی ہوں۔ بھول جانے کا اعتراض خود اعتراض کرنے والے پر واردکیا جا سکتا ہے۔\n4: اور جو بیان کیا جاتا ہے کہ حضرت عمر رضی اللہ نے بیان کیا تھا کہ عورت مطلقہ کے لئے سکنی اور نفقہ ہے یہ حدیث قطعاباطل اور غیر صحیح ہے۔\n5:حضرت فاطمہ رضی اللہ پر زبان کی تیز ہونے کا کو عیب لگایا جاتاہے (جیسے کی اگلے باب میں آرہا ہے)وہ بھی محل نظر ہے ایک طرف تو نبی صلی اللہ علیہ وسلم نفقہ وسکنی کے بارے میں حکم زبانی بتا رہے ہیں مگراسے زبان پر کنٹرول کرنے کی نصیحت نہیں فرماتے جس کا تعلق اس کے اپنے دین واخلاق کے ساتھ ساتھ تکمیل عدت میں بھی معاون ہے۔ ذخیرہ احادیث میں اس قسم کی کوئی بات ثابت نہیں۔"}],[2291,"ابواسحاق کہتے ہیں کہ میں اسود کے ساتھ جامع مسجد میں تھا تو انہوں نے کہا: فاطمہ بنت قیس رضی اللہ عنہا عمر بن خطاب رضی اللہ عنہ کے پاس آئیں انہوں نے کہا کہ ہم اپنے رب کی کتاب اور اپنے نبی کی سنت کو ایک عورت کے کہنے پر نہیں چھوڑ سکتے، پتا نہیں اسے یہ(اصل بات) یاد بھی ہے یا بھول گئی ۱؎۔\n§وضاحت\n۱؎ : کتاب اللہ سے مراد سورہ طلاق کی آیت «لعل الله يحدث بعد ذلك أمرا» ، اور سنت سے مراد عمر رضی اللہ عنہ والی روایت ہے جس میں ہے کہ میں نے رسول اکرم صلی اللہ علیہ وسلم سے سنا کہ مطلقہ ثلاثہ کو نفقہ اور سکنی ملے گا، لیکن یہ روایت محفوظ نہیں ہے۔","صحیح موقوف",{"u2":"ابواسحاق کہتے ہیں کہ میں اسود بن یزید کے ساتھ (کوفہ کی) جامع مسجد میں بیٹھا ہوا تھا انہوں نے بیان کیا کہ فاطمہ بنت قیس، سیدنا عمر بن خطاب رضی اللہ عنہ کے پاس آئی تو سیدنا عمر رضی اللہ عنہ نے کہا: ” ہم اپنے رب کی کتاب اور اپنے نبی کریم صلی اللہ علیہ وسلم کی سنت کو ایک عورت کے بیان پر نہیں چھوڑ سکتے، نہ معلوم اس نے یاد بھی رکھا ہے یا نہیں۔ “","f2":"اس کی تفصیل مذکورہ بالا فائدہ میں گزر چکی ہے۔"}],[2292,"عروہ کہتے ہیں کہ ام المؤمنین عائشہ رضی اللہ عنہا فاطمہ بنت قیس رضی اللہ عنہا کی حدیث پر سخت نکیر کرتی تھیں اور کہتی تھیں: چونکہ فاطمہ ایک ویران مکان میں رہتی تھیں جس کی وجہ سے ان کے بارے میں خدشہ لاحق ہوا اسی لیے رسول اللہ صلی اللہ علیہ وسلم نے انہیں (مکان بدلنے کی) رخصت دی تھی۔","حسن",{"u2":"ہشام بن عروہ اپنے والد سے بیان کرتے ہیں کہ سیدہ عائشہ رضی اللہ عنہا ا نے اس روایت پر بہت سخت عیب لگایا ہے (انکار کیا ہے) یعنی فاطمہ بنت قیس کی حدیث پر۔ اور کہا کہ فاطمہ بنت قیس ایک خالی مکان میں رہائش پذیر تھی اور اس طرف سے کوئی خطرہ سا بھی تھا اس لیے رسول اللہ صلی اللہ علیہ وسلم نے اس کو (گھر تبدیل کرنے کی) رخصت عنایت فرمائی تھی۔"}],[2293,"عروہ بن زبیر سے روایت ہے کہ ام المؤمنین عائشہ رضی اللہ عنہا سے فاطمہ (فاطمہ بنت قیس) رضی اللہ عنہا کے بیان پر اظہار خیال کرنے کے لیے کہا گیا تو انہوں نے کہا اس میں اس کے لیے کوئی فائدہ نہیں۔","صحیح",{"u2":"عروہ بن زبیر سے مروی ہے کہ سیدہ عائشہ رضی اللہ عنہا ا سے کہا گیا کہ کیا آپ کو فاطمہ کی بات معلوم نہیں ہوئی؟ تو انہوں نے کہا: اس بات کو ذکر کرنے میں اس کے لیے خیر نہیں ہے۔"}],[2294,"سلیمان بن یسار سے بھی فاطمہ رضی اللہ عنہا کے گھر سے نکلنے کا قصہ مروی ہے وہ کہتے ہیں: یہ بد خلقی کی بنا پر ہوا تھا۔","ضعیف",{"u2":"فاطمہ بنت قیس رضی اللہ عنہا ا کے گھر تبدیل کرنے کے سلسلے میں سلیمان بن یسار سے مروی ہے کہ ” یہ اس کی بدخلقی کی وجہ سے تھا۔ “ (زبان کی تیز تھیں)۔","f2":"یہ قول ضعیف ہے اس کی تفصیل گزشتہ باب کے فائدہ میں گزر چکی ہے،مکمل بحث زاد لمعاد۔جلد چہارم میں ملاحظہ فرمالی جائے۔ (بحث.ّحکمۃ صلی اللہ علیہ وسلم فی انہ لا نفقۃولاسکنی للنبّوۃ)"}],[2295,"یحیی بن سعید قاسم بن محمد اور سلیمان بن یسار سے روایت کرتے ہیں کہ انہوں نے ان دونوں کو ذکر کرتے ہوئے سنا کہ یحیی بن سعید بن عاص نے عبدالرحمٰن بن حکم کی بیٹی کو تین طلاق دے دی تو عبدالرحمٰن نے انہیں اس گھر سے منتقل کر لیا تو ام المؤمنین عائشہ رضی اللہ عنہا نے اس وقت مدینہ کے امیر مروان بن حکم کو کہلا بھیجا کہ اللہ کا خوف کھاؤ اور عورت کو اس کے گھر واپس بھیج دو، بروایت سلیمان: مروان نے کہا: عبدالرحمٰن مجھ پر غالب آ گئے یعنی انہوں نے میری بات نہیں مانی، اور بروایت قاسم: کیا آپ کو فاطمہ بنت قیس رضی اللہ عنہا کا قصہ معلوم نہیں؟ تو ام المؤمنین عائشہ رضی اللہ عنہا نے کہا: فاطمہ والی حدیث نہ بیان کرو تو تمہارا کوئی نقصان نہیں ہے، تو مروان نے کہا: اگر آپ نزدیک وہاں برائی کا اندیشہ تھا تو سمجھ لو یہاں ان دونوں (عمرہ اور ان کے شوہر یحیی) کے درمیان بھی اسی برائی کا اندیشہ ہے۔","صحیح",{"u2":"قاسم بن محمد اور سلیمان بن یسار کا بیان ہے کہ یحییٰ بن سعید بن العاص نے (اپنی بیوی عمرہ) بنت عبدالرحمٰن بن حکم کو طلاق دے دی، طلاق بتہ (تین طلاقیں) تو عبدالرحمٰن نے اپنی بیٹی کو (اپنے گھر) منتقل کر لیا۔ سیدہ عائشہ رضی اللہ عنہا ا نے مروان بن حکم کو پیغام بھیجا اور وہ ان دنوں مدینہ کا حاکم تھا، کہ اللہ سے ڈرو اور عورت کو اس کے (خاوند کے) گھر لوٹا دو۔ مروان نے کہا: (بالفاظ سلیمان) عبدالرحمٰن مجھ پر غالب آ گیا ہے۔ اور (بالفاظ قاسم) مروان نے کہا: کیا آپ کو فاطمہ بنت قیس کا احوال نہیں پہنچا؟ سیدہ عائشہ رضی اللہ عنہا ا نے کہا: اگر آپ فاطمہ کی حدیث بیان نہ کریں تو آپ کو کوئی نقصان نہ ہو گا۔ (اس کو ایک خاص وجہ سے اجازت دی گئی تھی) مروان نے کہا: اگر آپ ایک شر کو انتقال کی وجہ جواز سمجھتی ہیں تو ان زوجین کے درمیان موجود شر بھی اس کی وجہ جواز ہے۔"}],[2296,"میمون بن مہران کہتے ہیں کہ میں مدینہ آیا تو سعید بن مسیب کے پاس گیا اور میں نے کہا کہ فاطمہ بنت قیس رضی اللہ عنہا کو طلاق دی گئی تو وہ اپنے گھر سے چلی گئی (ایسا کیوں ہوا؟) تو سعید نے جواب دیا: اس عورت نے لوگوں کو فتنے میں مبتلا کر دیا تھا کیونکہ وہ زبان دراز تھی لہٰذا اسے ابن ام مکتوم رضی اللہ عنہ کے پاس رکھا گیا جو نابینا تھے۔","صحیح",{"u2":"میمون بن مہران کہتے ہیں کہ میں مدینہ آیا تو سعید بن مسیب کے ہاں پہنچا میں نے کہا: فاطمہ بنت قیس کو طلاق ہوئی تو وہ اپنے گھر سے منتقل ہو گئی تھی، تو سعید نے کہا: اس عورت نے لوگوں کو فتنے میں ڈالا ہوا تھا، بہت زبان دراز تھی تو اسے ابن مکتوم نابینا کے ہاں رہائش دی گئی۔","f2":"یہ روایت ضعیف ہے گویا اس میں ابن ام مکتوم کے گھر منتقل ہونے کی جو وجہ بیان کی گئی ہے،وہ صحیح نہیں ہے اس کی وجہ وہی ہے جو صحیح احادیث میں بیان ہوئی ہے کہ ابن ام مکتوم بصارت سے محروم تھے تو وہاں اس کے لئے پردے کی پابندی ضروری نہیں تھی۔"}],[2297,"جابر رضی اللہ عنہ کہتے ہیں کہ میری خالہ کو تین طلاقیں دی گئیں، وہ اپنی کھجوریں توڑنے نکلیں، راستے میں ایک شخص ملا تو اس نے انہیں نکلنے سے منع کیا چنانچہ وہ نبی اکرم صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوئیں، اور آپ سے اس واقعہ کا ذکر کیا، آپ صلی اللہ علیہ وسلم نے فرمایا: \"جاؤ اور اپنی کھجوریں توڑو، ہو سکتا ہے تم اس میں سے صدقہ کرو یا اور کوئی بھلائی کا کام کرو\"۔","صحیح",{"u2":"سیدنا جابر رضی اللہ عنہ بیان کرتے ہیں کہ میری خالہ کو تین طلاقیں دے دی گئیں تو وہ اپنی کھجوریں کاٹنے کے لیے نکل گئیں تو اسے ایک آدمی ملا جس نے اس کو منع کیا۔ تو وہ نبی کریم صلی اللہ علیہ وسلم کے پاس آئی اور آپ صلی اللہ علیہ وسلم کو یہ بات بتلائی۔ آپ صلی اللہ علیہ وسلم نے فرمایا ” چلی جایا کرو اور اپنی کھجوریں کاٹا کرو، تم اس سے صدقہ یا کوئی خیر کا کام ہی کرو گی۔ “","f2":"مطلقہ عورت اپنے ایام عدت میں کسی لازمی اور مناسب کا م کے لئے گھر سے باہر جاسکتی ہے مگر ضروری ہے کہ رات کو اپنے گھر واپس آجائے۔"}],[2298,"عبداللہ بن عباس رضی اللہ عنہما سے روایت ہے کہ اللہ کا فرمان «والذين يتوفون منكم ويذرون أزواجا وصية لأزواجهم متاعا إلى الحول غير إخراج» \"اور تم میں سے جو لوگ فوت ہو جائیں اور بیویاں چھوڑ جائیں تو وہ وصیت کر جائیں کہ ان کی بیویاں سال بھر تک فائدہ اٹھائیں انہیں کوئی نہ نکالے\" (سورۃ البقرہ: ۲۴۰) میراث کی آیت نازل ہو جانے کے بعد منسوخ ہو گیا کیونکہ اس میں ان کے لیے چوتھائی اور آٹھواں حصہ مقرر کر دیا گیا ہے اسی طرح ایک سال تک نہ نکلنے کا حکم چار مہینے دس دن کی عدت کا حکم آ جانے کے بعد منسوخ ہو گیا۔","حسن",{"u2":"آیت کریمہ «والذين يتوفون منكم ويذرون أزواجا وصية لأزواجهم متاعا إلى الحول غير إخراج» ” اور تم میں سے جو لوگ فوت ہو جائیں اور اپنے پیچھے اپنی بیویاں چھوڑ جائیں تو (انہیں چاہیئے کہ) اپنی بیویوں کے لیے وصیت کر جائیں کہ ایک سال تک انہیں خرچ دینا ہے اور گھر سے نہیں نکالنا ہے۔ “ کی تفسیر میں سیدنا ابن عباس رضی اللہ عنہ سے مروی ہے کہ یہ حکم آیت میراث سے منسوخ ہے اور انہیں چوتھا یا آٹھواں حصہ ملے گا۔ اور ایک سال کی مدت بھی منسوخ ہے اور اب اس کی مدت (عدت صرف) چار ماہ دس دن ہے۔","f2":"خاوند کی اگر اولاد ہو تو بیوی کو آٹھواں حصہ ملتا ہے ورنہ چوتھا۔"}],[2299,"حمید بن نافع کہتے ہیں کہ زینب بنت ابی سلمہ رضی اللہ عنہما نے انہیں ان تینوں حدیثوں کی خبر دی کہ جب ام المؤمنین ام حبیبہ رضی اللہ عنہا کے والد ابوسفیان رضی اللہ عنہ کا انتقال ہوا تو میں ان کے پاس گئی، انہوں نے زرد رنگ کی خوشبو منگا کر ایک لڑکی کو لگائی پھر اپنے دونوں رخساروں پر بھی مل لی اس کے بعد کہنے لگیں: اللہ کی قسم! مجھے خوشبو لگانے کی قطعاً حاجت نہ تھی، میں نے تو ایسا صرف اس بنا پر کیا کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا تھا: \"کسی عورت کے لیے جو اللہ تعالی اور آخرت کے دن پر ایمان رکھتی ہو یہ حلال نہیں کہ وہ کسی میت پر تین دن سے زیادہ سوگ منائے، ہاں خاوند پر چار مہینے دس دن تک سوگ منانا ہے\"۔ زینب رضی اللہ عنہا کہتی ہیں: میں ام المؤمنین زینب بنت جحش رضی اللہ عنہا کے پاس گئی جس وقت کہ ان کے بھائی کا انتقال ہو گیا تھا، انہوں نے (بھی) خوشبو منگا کر لگائی اس کے بعد کہنے لگیں: اللہ کی قسم! مجھے خوشبو لگانے کی کوئی ضرورت نہیں تھی، میں نے ایسا صرف اس بنا پر کیا ہے کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو منبر پر فرماتے سنا: \"کسی بھی عورت کے لیے جو اللہ اور آخرت کے دن پر ایمان رکھتی ہو یہ حلال نہیں کہ وہ کسی میت پر تین دن سے زیادہ سوگ منائے ہاں شوہر کی وفات پر سوگ چار مہینے دس دن ہے\"۔ زینب رضی اللہ عنہا کہتی ہیں: میں نے اپنی والدہ ام سلمہ رضی اللہ عنہا کو کہتے ہوئے سنا: ایک عورت نے رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہو کر عرض کیا: اللہ کے رسول! میری بیٹی کے شوہر کی وفات ہو گئی ہے اور اس کی آنکھیں دکھ رہی ہیں، کیا ہم اسے سرمہ لگا دیں؟ آپ صلی اللہ علیہ وسلم نے فرمایا: \"نہیں\"، اس نے دو بار یا تین بار پوچھا، آپ صلی اللہ علیہ وسلم نے ہر بار فرمایا:\"نہیں\"، پھر فرمایا: \"تم چار مہینے دس دن صبر نہیں کر سکتی، حالانکہ زمانہ جاہلیت میں جب تم میں سے کسی عورت کا شوہر مر جاتا تھا تو ایک سال پورے ہونے پر اسے مینگنی پھینکنی پڑتی تھی\"۔ حمید راوی کہتے ہیں میں نے زینب رضی اللہ عنہا سے پوچھا: مینگنی پھینکنے سے کیا مراد ہے؟ تو انہوں نے بتایا کہ جاہلیت کے زمانہ میں جب کسی عورت کا شوہر مر جاتا تو وہ ایک معمولی سی جھونپڑی میں رہائش اختیار کرتی، پھٹے پرانے اور میلے کچیلے کپڑے پہنتی، نہ خوشبو استعمال کر سکتی اور نہ ہی کوئی زینت و آرائش کر سکتی تھی، جب سال پورا ہو جاتا تو اسے گدھا یا کوئی پرندہ یا بکری دی جاتی جسے وہ اپنے بدن سے رگڑتی، وہ جانور کم ہی زندہ رہ پاتا، پھر اس کو مینگنی دی جاتی جسے وہ سر پر گھما کر اپنے پیچھے پھینک دیتی، اس کے بعد وہ عدت سے باہر آتی اور زیب و زینت کرتی اور خوشبو استعمال کرتی۔ ابوداؤد کہتے ہیں:«حفش» چھوٹے گھر (تنگ کوٹھری) کو کہتے ہیں۔","صحیح",{"u2":"سیدہ زینب بنت ابی سلمہ رضی اللہ عنہا ا (یہ رسول اللہ صلی اللہ علیہ وسلم کی ربیبہ تھیں) نے یہ درج ذیل تین حدیثیں بیان کیں۔ (پہلی حدیث) زینب رضی اللہ عنہا ا کہتی ہیں کہ میں ام المؤمنین سیدہ ام حبیبہ رضی اللہ عنہا ا کے ہاں گئی جبکہ ان کے والد ابوسفیان کی وفات ہو گئی تھی تو انہوں نے خوشبو منگوائی جس میں زردی تھی، وہ خلوق تھی یا کوئی اور، انہوں نے یہ لونڈی کو لگائی پھر اپنے ہاتھوں کو اپنے رخساروں پر مل لیا اور کہا: قسم اللہ کی! مجھے خوشبو کی کوئی طلب اور ضرورت نہیں ہے مگر میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا ہے، فرماتے تھے ” کسی خاتون کے لیے حلال نہیں، جو اللہ اور روز آخرت پر ایمان رکھتی ہو، کہ وہ کسی میت پر تین دن سے زیادہ سوگ کا اظہار کرے (اور زیب و زینت چھوڑے رہے) سوائے شوہر کے (کہ اس کے لیے) چار مہینے اور دس دن ہیں۔\n’’ زینب رضی اللہ عنہا ا نے کہا: میں ام المؤمنین سیدہ زینب بنت حجش رضی اللہ عنہا ا کے پاس آئی جبکہ ان کا بھائی فوت ہو گیا تھا۔ تو انہوں نے خوشبو منگوا کر لگائی اور پھر کہا: قسم اللہ کی! مجھے خوشبو کی کوئی طلب اور ضرورت نہیں مگر میں نے رسول اللہ صلی اللہ علیہ وسلم کو سنا، آپ صلی اللہ علیہ وسلم منبر پر کھڑے فر رہے تھے ” کسی عورت کے لیے حلال نہیں، جو اللہ اور روز آخرت پر ایمان رکھتی ہو، کہ وہ کسی میت پر تین دن سے زیادہ سوگ کرے الا یہ کہ شوہر ہو تو اس کے لیے (سوگ کے) چار ماہ دس دن ہیں۔\nزینب رضی اللہ عنہا ا نے کہا: میں نے اپنی والدہ ام المؤمنین سیدہ ام سلمہ رضی اللہ عنہا ا کو سنا، بیان کرتی تھیں کہ ایک عورت رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں آئی اور کہا: اے اللہ کے رسول! میری بیٹی کا شوہر فوت ہو گیا ہے اور اب اس کی آنکھ خراب ہے، کیا ہم اس کو سرمہ لگا دیں؟ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” نہیں “ اس نے یہ دو یا تین مرتبہ پوچھا آپ صلی اللہ علیہ وسلم نے ہر بار فرمایا ” نہیں “ پھر رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” یہ تو صرف چار ماہ دس دن ہیں جب کہ جاہلیت میں عورت ایک سال گزرنے کے بعد مینگنی پھینکا کرتی تھی۔ “ حمید نے کہا: میں نے زینب رضی اللہ عنہا ا سے پوچھا: مینگنی پھینکنے سے کیا مراد ہے؟ تو انہوں نے بتایا کہ جب کسی عورت کا شوہر فوت ہو جاتا تھا تو وہ ایک چھوٹے سے گھروندے میں رہتی، بہت ہی خراب کپڑے پہنتی اور خوشبو تو کیا کسی چیز کو بھی ہاتھ نہ لگاتی تھی (طہارت کے لیے) حتیٰ کہ اس کیفیت میں سال گزر جاتا، پھر کوئی جانور لایا جاتا گدھا، بکری یا کوئی اور پرندہ تو وہ اسے اپنے شرمگاہ کے ساتھ مس کرتی اور پھر اکثر ایسے ہوتا کہ وہ جس چیز کو بھی شرمگاہ کے ساتھ مس کرتی تو وہ مر جاتی۔ پھر وہ باہر نکلتی اور اسے مینگنی دی جاتی تو وہ اسے پھینکتی تھی۔ اس کے بعد جو وہ چاہتی، خوشبو وغیرہ استعمال کرتی۔ ابوداؤد رضی اللہ عنہ نے کہ «حفش» کا معنی گھروندا ہے۔"}],[2300,"زینب بنت کعب بن عجرۃ سے روایت ہے کہ فریعہ بنت مالک بن سنان رضی اللہ عنہا (ابو سعید خدری رضی اللہ عنہ کی بہن) نے انہیں خبر دی ہے کہ وہ رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں آئیں، وہ آپ سے پوچھ رہی تھیں کہ کیا وہ قبیلہ بنی خدرہ میں اپنے گھر والوں کے پاس جا کر رہ سکتی ہیں؟ کیونکہ ان کے شوہر جب اپنے فرار ہو جانے والے غلاموں کا پیچھا کرتے ہوئے طرف القدوم نامی مقام پر پہنچے اور ان سے جا ملے تو ان غلاموں نے انہیں قتل کر دیا، میں نے رسول اللہ صلی اللہ علیہ وسلم سے پوچھا: کیا میں اپنے گھر والوں کے پاس لوٹ جاؤں؟ کیونکہ انہوں نے مجھے جس مکان میں چھوڑا تھا وہ ان کی ملکیت میں نہ تھا اور نہ ہی خرچ کے لیے کچھ تھا، تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"ہاں (وہاں چلی جاؤ)\" فریعہ رضی اللہ عنہا کہتی ہیں: (یہ سن کر) میں نکل پڑی لیکن حجرے یا مسجد تک ہی پہنچ پائی تھی کہ آپ صلی اللہ علیہ وسلم نے مجھے بلا لیا، یا بلانے کے لیے آپ صلی اللہ علیہ وسلم نے کسی سے کہا، (میں آئی) تو پوچھا: \"تم نے کیسے کہا؟\" میں نے وہی قصہ دہرا دیا جو میں نے اپنے شوہر کے متعلق ذکر کیا تھا، آپ صلی اللہ علیہ وسلم نے فرمایا: \"اپنے اسی گھر میں رہو یہاں تک کہ قرآن کی بتائی ہوئی مدت (عدت) پوری ہو جائے\" فریعہ رضی اللہ عنہا کہتی ہیں: پھر میں نے عدت کے چار مہینے دس دن اسی گھر میں پورے کئے، جب عثمان بن عفان رضی اللہ عنہ کا دور خلافت آیا تو انہوں نے مجھے بلوایا اور اس مسئلہ سے متعلق مجھ سے دریافت کیا، میں نے انہیں بتایا تو انہوں نے اسی کی پیروی کی اور اسی کے مطابق فیصلہ دیا۔","صحیح",{"u2":"سیدہ فریعہ بنت مالک بن سنان رضی اللہ عنہ ا سے مروی ہے اور یہ سیدنا ابو سعید خدری رضی اللہ عنہ کی بہن ہیں، بیان کرتی ہیں کہ میں رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوئی کہ آپ سے اجازت لے کر اپنے خاندان بنی خدرہ میں چلی جاؤں کیونکہ میرا شوہر اپنے ان غلاموں کی تلاش میں گیا تھا جو بھاگ گئے تھے۔ وہ مقام قدوم کے اطراف میں تھے کہ میرے شوہر نے ان کو جا لیا مگر انہوں نے اس کو قتل کر ڈالا، چنانچہ میں رسول اللہ صلی اللہ علیہ وسلم سے اجازت لینے کے لیے آئی تھی کہ مجھے اپنے اہل میں لوٹ جانے کی اجازت دیں۔ کیونکہ اس نے مجھے اپنے مملوکہ مکان میں نہیں چھوڑا تھا اور نہ کوئی خرچ ہی بچا گیا تھا۔ بیان کرتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے سن کر (پہلے تو) اجازت دے دی۔ پس میں آپ کے پاس سے نکلی حتیٰ کہ جب میں حجرے یا مسجد نبوی میں تھی، آپ صلی اللہ علیہ وسلم نے مجھے بلایا یا بلوایا اور فرمایا ” تو نے کیسے کہا ہے؟ “ تو میں نے اپنا قصہ یعنی شوہر کا واقعہ دوبارہ دوہرایا، تو آپ صلی اللہ علیہ وسلم نے فرمایا ” اپنے (شوہر کے) مکان میں اقامت رکھ، حتیٰ کہ کتاب اللہ کی (بیان کی ہوئی) مدت پوری ہو جائے۔ “ کہتی ہیں: پھر میں نے اسی مکان میں اپنی عدت پوری کی، یعنی چار ماہ دس دن۔ بیان کرتی ہیں کہ جب سیدنا عثمان بن عفان رضی اللہ عنہ کا دور خلافت آیا تو انہوں نے میری طرف پیغام بھیجا اور مجھ سے اس مسئلہ کی تفصیل دریافت کی اور میں نے انہیں (تفصیل سے) خبر دی۔ چنانچہ انہوں نے اسی پر عمل کیا اور اسی کے مطابق فیصلہ کیا۔","f2":"واجب ہے کہ عورت اپنی عدت اسی مکان میں گزارے جہاں شوہر کی وفات ہو ئی ہو الا یہ کہ کوئی انتہائی اضطراری صورت مانع ہو مثلا اس مکان میں رہنا ممکن نہ ہو۔"}],[2301,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں «غير إخراج» (سورة البقرہ: ۲۴۰) والی آیت جس میں عورت کو شوہر کے گھر والوں کے پاس عدت گزارنے کا حکم ہے منسوخ کر دی گئی ہے، اب وہ جہاں چاہے عدت گزار سکتی ہے، عطاء کہتے ہیں: اگر چاہے تو شوہر کے گھر والوں کے پاس عدت گزارے اور شوہر کی وصیت سے فائدہ اٹھا کر وہیں سکونت اختیار کرے، اور اگر چاہے تو اللہ کے فرمان «فإن خرجن فلا جناح عليكم فيما فعلن» \"اگر وہ خود نکل جائیں تو ان کے کئے ہوئے کا تم پر کوئی گناہ نہیں\" کے مطابق نکل جائے، عطاء کہتے ہیں کہ پھر جب میراث کا حکم آ گیا، تو شوہر کے مکان میں رہائش کا حکم منسوخ ہو گیا اب وہ جہاں چاہے عدت گزارے۔","صحیح",{"u2":"جناب عطاء بن ابی رباح بیان کرتے ہیں کہ سیدنا ابن عباس رضی اللہ عنہ نے فرمایا ” آیت کریمہ «غير إخراج» نے عورت کے لیے شوہر کے اہل میں عدت گزارنے کو منسوخ کر دیا ہے۔ سو جہاں چاہے عدت گزارے۔ “ عطاء نے (اس قول کی وضاحت میں) کہا: چاہے تو شوہر کے اہل میں عدت گزارے جیسے کہ اس کے لیے وصیت ہے اور چاہے تو وہاں سے رخصت ہو جائے۔ کیونکہ اللہ تعالیٰ نے فرمایا ہے «فإن خرجن فلا جناح عليكم في فعلن» عطاء کہتے ہیں کہ پھر آیت میراث نازل ہوئی، پس وہ سکنی منسوخ ہو گیا تو جہاں چاہے عدت گزارے۔","f2":"خاوند کی وفات پر عورت کے لئے عدت کا مسئلہ سورۃ بقرہ کی دوآیات میں ذکر ہواہے،پہلی آیت ٢٣٤ میں ہے (والذین یتوفون منکم۔۔۔۔۔۔۔۔۔اربعۃ اشھر وعشر) اور جو لوگ تم میں سے فوت ہو جائیں اور چھوڑ جائیں اپنی بیویاں،تو چاہے کہ وہ عورتیں اپنے آپ کو چار ماہ دس دن تک روکے رکھیں۔ اور اس کے بعد آیت 240 میں ہے (والذین یتوفون منکم۔۔۔۔۔۔۔۔۔۔انفسھن من معروف) اور جو لوگ تم میں سے فوت ہو جائیں اپنی بیویاں،تو ان پر ہے کہ اپنی بیویوں کے لئے وصیت گر جائیں کہ انہیں ایک سال تک خرچ دینا ہے اور گھر سے نکالنابھی نہیں اگر وہ ازخود نکل جائیں اور اپنے حق میں جو بھلی بات کریں تو اس کا تم پر گناہ نہیں ہے ان دونوں آیاتکی تفسیر میں اصحاب ابن عباس رضی اللہ کا اختلاف ہے۔ جمہور کہتے ہیں کہ ایک سال تک تفقہ وسکنی کا حکم پہلے کا ہے۔ پھر اسے منسوخ کرکے چار ماہ دس دن کر دیا گیا۔ لیکن مجاہد اور عطاء حضرت ابن عباس سے بیان کرتے ہیں کہ چار ماہ دس دن عدت کا حکم شروع ہی سے تھا۔ اسے منسوخ کرکے ایک سال تک بڑھا دیا گیا۔ اب عورت پر لازم نہیں ہے کہ شوہر کے اہل میں عدتگ گزارے جیسے کہ (فان خرجن) سے معلوم ہو رہا ہے ایسے ہی شوہر کے وارثوں پر جو پابندی تھی کہ ایک سال تک خرچ دیں اورسکنی بھی،تو وراثت کے احکام نازل ہونے پر یہ بھی منسوخ ہے۔ امام ابو داود رحمہ اللہ نے یہ باب ذکر کرکے ان حضرات کا موقف بیان کیا ہے مگر یہ موقف گزشتہ حدیث فریعہ بنت مالک کی روشنی میں راجح نہیں ہے الا یہ کہ یہ سمجھاجائے کہ چار ماہ دس دن کی عدت اور ان دنوں میں شوہر کے اہل میں رہنا واجب ہے۔ بعدازاں سات ماہ بیس دن میں عورت کو منتقل ہوجانے کی رخصت ہے، درج ذیل حدیث اسی تفصیل کی روشنی میں پڑھی جائے۔"}],[2302,"ام عطیہ رضی اللہ عنہا سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"عورت کسی پر بھی تین دن سے زیادہ سوگ نہ منائے سوائے شوہر کے، وہ اس پر چار مہینے دس دن سوگ منائے گی (اس عرصہ میں) وہ سفید سیاہ دھاری دار کپڑے کے علاوہ کوئی رنگین کپڑا نہ پہنے، نہ سرمہ لگائے، اور نہ خوشبو استعمال کرے، ہاں حیض سے فارغ ہونے کے بعد تھوڑی سی قسط یا اظفار کی خوشبو (حیض کے مقام پر) استعمال کرے\"۔ راوی یعقوب نے: \"سفید سیاہ دھاری دار کپڑے\" کے بجائے: \"دھلے ہوئے کپڑے\" کا ذکر کیا، انہوں نے یہ بھی اضافہ کیا کہ اور نہ خضاب لگائے۔","صحیح",{"u2":"سیدہ ام عطیہ رضی اللہ عنہا ا سے مروی ہے کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا ” عورت کسی (میت) پر تین دن سے زیادہ سوگ نہ کرے، سوائے شوہر کے۔ اس کے لیے چار ماہ دس دن سوگ کرے، کوئی رنگین کپڑا نہ پہنے مگر وہ کپڑا جس کی بنائی ہی رنگین دھاگوں سے ہو (یمنی دھاری دار چادر وغیرہ) نہ سرمہ لگائے نہ خوشبو استعمال کرے مگر حیض سے طہارت کے وقت معمولی قسط یا اظفار کی خوشبو استعمال کر سکتی ہے۔ “ یعقوب نے «عصب» کی بجائے «مغسولا» کا لفظ استعمال کیا اور «ولا تختضب» کا اضافہ بھی کیا (مہندی نہ لگائے)","f2":"عورت خواہ مدخولہ ہو یا غیر مدخولہ،چھوٹی ہو یا بڑی،شوہر کی وفات پر اس کے لئے واجب ہے کہ چار ماہ دس دن تک مذکورہ امور کی پابندی کرے اور اس طرح سے سادگی اپنائے۔"}],[2303,"ام عطیہ رضی اللہ عنہا سے یہی حدیث مرفوعاً مروی ہے، لیکن ان دونوں راویوں کی حدیثوں میں پوری مشابہت نہیں ہے، مسمعی کا بیان ہے کہ یزید کہتے ہیں میں تو صرف یہی جانتا ہوں کہ اس میں ہے کہ \"خضاب نہ لگائے\" اور ہارون نے اس میں اتنا اور اضافہ کیا ہے کہ: \"رنگا ہوا کپڑا نہ پہنے سوائے سفید سیاہ دھاری دار کپڑے کے\"۔","صحیح",{"u2":"سیدہ ام عطیہ رضی اللہ عنہا ا، نبی کریم صلی اللہ علیہ وسلم سے یہی (مذکورہ بالا) حدیث بیان کرتی ہیں مگر یہ روایت پوری طرح مذکورہ بالا رواۃ کی روایت کی مانند نہیں ہے (ابراہیم بن طہمان اور عبداللہ سہمی کی روایت کی طرح) مسمعی نے کہا: یزید نے بیان کیا کہ میرا خیال ہے کہ اس میں «ولا تختضب» بھی ہے (مہندی نہ لگائے) جبکہ ہارون نے اضافہ کیا کہ ” رنگین کپڑا نہ پہنے الا یہ کہ اس کی بنائی ہی رنگین دھاگوں سے ہو۔ “ (جیسے کہ یمنی دھاری دار چادریں ہوتی تھیں)۔"}],[2304,"ام المؤمنین ام سلمہ رضی اللہ عنہا کہتی ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"جس عورت کا شوہر انتقال کر جائے وہ نہ زرد اور گیروے رنگ کا کپڑا پہنے نہ زیور پہنے، نہ خضاب (مہندی وغیرہ) لگائے، اور نہ سرمہ لگائے ۱؎\"۔\n§وضاحت\n۱؎ : یہ تمام کام بناؤ سنگار کے ہیں، اس لئے عدت میں ان سے پرہیز ضروری ہے۔","صحیح",{"u2":"ام المؤمنین سیدہ ام سلمہ رضی اللہ عنہا ا سے روایت ہے کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا ” جس عورت کا شوہر فوت ہو جائے، وہ عصفر (زعفران) یا گیرو رنگ کے کپڑے نہ پہنے۔ نہ زیور استعمال کرے، نہ مہندی لگائے اور نہ سرمہ۔ “","f2":"یہ امور زینت کا حصہ ہیں اس لیے ایام عدت میں ان سے بچنا واجب ہے۔"}],[2305,"ام حکیم بنت اسید اپنی والدہ سے روایت کرتی ہیں کہ ان کے شوہر کا انتقال ہو گیا، ان کی آنکھوں میں تکلیف رہتی تھی تو وہ «جلاء»(سرمہ) لگا لیتیں تو اپنی ایک لونڈی کو انہوں نے ام المؤمنین ام سلمہ رضی اللہ عنہا کے پاس بھیجا تاکہ وہ «جلاء» کے سرمہ کے متعلق ان سے پوچھے، انہوں نے کہا: اس کا سرمہ نہ لگاؤ جب تک ایسی سخت ضرورت پیش نہ آ جائے جس کے بغیر چارہ نہ ہو اس صورت میں تم اسے رات میں لگاؤ، اور دن میں پونچھ لیا کرو، پھر ام سلمہ رضی اللہ عنہا نے اسی وقت یہ بھی بتایا کہ ابوسلمہ رضی اللہ عنہ کا جب انتقال ہو گیا تو رسول اللہ صلی اللہ علیہ وسلم میرے پاس تشریف لائے، اور میں نے اپنی آنکھ میں ایلوا لگا رکھا تھا، آپ صلی اللہ علیہ وسلم نے پوچھا: \"ام سلمہ یہ کیا ہے؟\" میں نے جواب دیا: اللہ کے رسول! یہ ایلوا ہے اور اس میں خوشبو نہیں ہے، فرمایا: \"یہ چہرے میں حسن پیدا کرتا ہے لہٰذا اسے رات ہی میں لگاؤ، اور دن میں ہٹا دو، اور خوشبو لگا کر کنگھی نہ کرو، اور نہ مہندی لگا کر، کیونکہ وہ خضاب ہے\" میں نے پوچھا: اللہ کے رسول! پھر کنگھی کس چیز سے کروں؟ آپ صلی اللہ علیہ وسلم نے فرمایا: \"بیری کے پتوں کو اپنے سر پر لپیٹ کر\"۔","ضعیف",{"u2":"ام حکیم بنت اسید اپنی والدہ سے روایت کرتی ہیں کہ ان کا شوہر فوت ہو گیا اور ان کی آنکھیں خراب رہتی تھیں اور انہوں نے (جلاء) سرمہ استعمال کرنا چاہا۔ احمد بن صالح نے کہا: صحیح روایت «كحل الجلاء» ہے۔ تو اس نے اپنی خادمہ کو سیدہ ام سلمہ رضی اللہ عنہا ا کے پاس بھیجا اور «كحل الجلاء» ” روشنی دینے والا سرمہ “ استعمال کرنے کے متعلق پوچھا۔ انہوں نے کہا: استعمال نہ کرے الا یہ کہ انتہائی مجبوری ہو تو رات کو استعمال کرے اور دن میں صاف کر دے۔ یہ خبر بتاتے ہوئے پھر سیدہ ام سلمہ رضی اللہ عنہا ا نے کہا: ابوسلمہ کی وفات کے موقع پر رسول اللہ صلی اللہ علیہ وسلم میرے ہاں تشریف لائے اور میں نے اپنی آنکھ پر ایلوا لگا رکھا تھا۔ آپ صلی اللہ علیہ وسلم نے فرمایا ” ام سلمہ! یہ کیا ہے؟ “ میں نے کہا: اے اللہ کے رسول! یہ ایلوا ہے اور اس میں کوئی خوشبو نہیں ہے۔ آپ صلی اللہ علیہ وسلم نے فرمایا ” بیشک یہ چہرے کو مزین کر دیتا ہے، لہٰذا صرف رات کو استعمال کرو اور دن میں اسے صاف کر دیا کرو۔ اور کسی خوشبو والی چیز کے ساتھ اور مہندی کے ساتھ کنگھی نہ کرو (سر نہ دھو) کیونکہ یہ خضاب ہے۔ “ میں نے پوچھا: اے اللہ کے رسول! تو پھر کس چیز سے میں کنگھی کیا کروں؟ آپ صلی اللہ علیہ وسلم نے فرمایا ” بیری (کے پتوں) سے، اسے اپنے سر پر چپڑ لیا کرو (بعد میں دھو ڈالا کرو)۔ “"}],[2306,"ابن شہاب زہری سے روایت ہے کہ مجھ سے عبیداللہ بن عبداللہ بن عتبہ نے بیان کیا کہ ان کے والد نے عمر بن عبداللہ بن ارقم زہری کو لکھا کہ وہ سبیعہ بنت حارث اسلمیہ رضی اللہ عنہا کے پاس جا کر ان کی حدیث معلوم کریں، نیز معلوم کریں کہ جب انہوں نے رسول اللہ صلی اللہ علیہ وسلم سے مسئلہ دریافت کیا تو آپ نے کیا ارشاد فرمایا؟ چنانچہ عمر بن عبداللہ نے عبداللہ بن عتبہ کو لکھا، وہ انہیں بتا رہے تھے کہ انہیں سبیعہ نے بتایا ہے کہ وہ سعد بن خولہ رضی اللہ عنہ کے نکاح میں تھیں (وہ بنی عامر بن لوی کے ایک فرد، اور بدری صحابی ہیں) حجۃ الوداع کے موقعہ پر جب وہ حاملہ تھیں تو ان کا انتقال ہو گیا، انتقال کے بعد انہوں نے بچہ جنا، جب نفاس سے پاک ہو گئیں تو نکاح کا پیغام دینے والوں کے لیے بناؤ سنگار کیا تو بنی عبدالدار کا ایک شخص ابوسنابل بن بعکک رضی اللہ عنہ ان کے پاس آئے اور کہنے لگے: میں تمہیں بنی سنوری ہوئی دیکھ رہا ہوں، شاید نکاح کرنا چاہتی ہو، اللہ کی قسم! تم چار مہینے دس دن (کی عدت) گزارے بغیر نکاح نہیں کر سکتی۔ سبیعہ رضی اللہ عنہا کا بیان ہے: جب انہوں نے مجھ سے اس طرح کی گفتگو کی تو میں شام کے وقت پہن اوڑھ کر رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوئی اور آپ سے اس کے متعلق دریافت کیا، آپ صلی اللہ علیہ وسلم نے مجھے مسئلہ بتایا اور فرمایا کہ بچہ جننے کے بعد ہی میں حلال ہو گئی اور آپ صلی اللہ علیہ وسلم نے مجھے حکم دیا کہ اگر میں چاہوں تو شادی کر سکتی ہوں۔ ابن شہاب کہتے ہیں: میرے خیال میں بچہ جننے کے بعد عورت کے نکاح کرنے میں کوئی حرج نہیں گرچہ وہ حالت نفاس ہی میں ہو البتہ پاک ہونے تک شوہر صحبت نہیں کرے گا ۱؎۔\n§وضاحت\n۱؎ : پہلے یہ آیت اتری تھی : «والذين يتوفون منكم ويذرون أزواجا يتربصن بأنفسهن أربعة أشهر وعشرا» یہ آیت سورہ بقرہ (آیت: ۲۳۴) کی ہے، اس میں حاملہ اور غیر حاملہ دونوں داخل تھیں ، پھر سورہ طلاق والی آیت نمبر (۴) «وأولات الأحمال أجلهن أن يضعن حملهن» نازل ہوئی تو حاملہ کی عدت وضع حمل (بچہ کی پیدائش) قرار پائی اور غیر حاملہ کی چار مہینہ دس دن پہلی آیت کے موافق برقرار رہی اکثر علماء کا یہی مذہب ہے اور بعض علماء کے نزدیک چونکہ دونوں آیتیں متعارض ہیں اس لئے دونوں میں سے جو مدت لمبی «أبعد الأجلين» ہو اسے اختیار کرے۔","صحیح",{"u2":"عبیداللہ بن عبداللہ بن عتبہ کا بیان ہے کہ اس کے والد نے عمر بن عبداللہ بن ارقم زہری کو خط لکھا اور اسے حکم دیا کہ سبیعہ بنت حارث اسلمیہ رضی اللہ عنہا ا کے پاس جائے اور اس سے اس کا قصہ دریافت کرے اور یہ کہ رسول اللہ صلی اللہ علیہ وسلم نے اسے کیا فرمایا تھا، جب اس نے رسول اللہ صلی اللہ علیہ وسلم سے مسئلہ پوچھا تھا؟ چنانچہ عمر بن عبداللہ نے، عبداللہ بن عتبہ کو لکھ بھیجا کہ سبیعہ نے بتایا کہ وہ سعد بن خولہ کی زوجیت میں تھی جو کہ قبیلہ بنی عامر بن لؤی میں سے تھے۔ غزوہ بدر میں شریک ہوئے تھے اور حجۃ الوداع کے موقع پر ان کی وفات ہوئی تھی اور ان دنوں وہ حمل سے تھی۔ ان کی وفات کے بعد چند ہی روز گزرے تھے کہ بچے کی ولادت ہو گئی۔ جب ایام نفاس سے پاک ہوئی تو نکاح کا پیغام لانے والوں کے لیے انہوں نے زیب و زینت شروع کر دی۔ چنانچہ بنو عبدالدار کا ایک شخص ابوسنابل بن بعکک اس کے پاس آیا اور اس سے کہا: کیا وجہ ہے تو نے زیب و زینت کر رکھی ہے، شاید تو نکاح کرنا چاہتی ہے؟ اللہ کی قسم! تو اس وقت تک نکاح نہیں کر سکتی جب تک چار ماہ دس دن نہ گزر جائیں۔ سبیعہ نے کہا: جب اس نے مجھے یہ کہا تو شام کو میں نے اپنے کپڑے لپیٹے اور رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہو گئی اور آپ صلی اللہ علیہ وسلم سے اس بارے میں دریافت کیا۔ آپ صلی اللہ علیہ وسلم نے مجھ سے فرمایا ” جب ولادت ہو گئی ہے تو، تو حلال ہے۔ “ اور آپ صلی اللہ علیہ وسلم نے مجھ سے فرمایا ” اگر میں چاہوں تو نکاح کر سکتی ہوں۔ “ ابن شہاب زہری کہتے ہیں ” وضع حمل کے بعد میں ایسی عورت کے نکاح میں کوئی حرج نہیں سمجھتا ہوں خواہ خون کے ایام ہی ہوں، الا یہ کہ شوہر طہارت سے پہلے اس کے قریب نہ ہو۔"}],[2307,"عبداللہ بن مسعود رضی اللہ عنہ کہتے ہیں کہ جو بھی چاہے مجھ سے اس بات پر لعان ۱؎ کر لے کہ چھوٹی سورۃ نساء (سورۃ الطلاق) چار مہینے دس دن والے حکم کے بعد نازل ہوئی ۲؎۔\n§وضاحت\n۱؎ : اس سے مراد مباہلہ ہے۔ ۲؎ : جو کہ سورہ البقرہ میں ہے ابن مسعود رضی اللہ عنہ کا مطلب یہ کہ ’’ عام متوفی عنہا زوجہا کے چار ماہ دس دن عدت گزارنے کا حکم سورہ بقرہ میں ہے ‘‘، اور ’’حاملہ متوفی عنہا زوجہا کی عدت صرف وضع حمل تک ہے ‘‘ کا تذکرہ سورہ طلاق کے اندر ہے جو کہ سورہ بقرہ کے بعد اتری ہے اس لئے یہ حکم خاص اس حکم عام کو خاص کرنے والا ہے۔","صحیح",{"u2":"سیدنا عبداللہ بن مسعود رضی اللہ عنہ فرماتے ہیں کہ جو چاہے میں اس سے مباہلہ کر سکتا ہوں کہ چھوٹی سورۃ نساء (سورۃ الطلاق) چار ماہ دس دن (کے سابقہ حکم) کے بعد ہی نازل ہوئی تھی۔ (یہ حکم سورۃ البقرہ کی آیت 234 میں وارد ہوا ہے)۔","f2":"1: سورۃ الطلاق میں ہے کہ (واولات الااحمال۔۔۔۔۔یضعن حملھن)(الطلاق:4) اور حاملہ عورتوں کی عدت یہ ہے کہ وضع حمل ہو جائے اور اس سورت کو سورۃالنساء القصر۔ (چھوٹی سورۃ النسا)اس لیے کہا کہ جہاں معروف بڑی سورۃنساء میں عورتوں کے احکام ومسائل بیان ہوئے ہیں وہاں اس سورت میں بھی انہی مسائل ذکر کیے گئے ہیں۔\n2:حضرت عبداللہ رضی اللہ کا یہ قول معروف فقہی اصول کی اساس ہے کہ کسی مسئلے میں جہاں کہیں دو ہدایات وارد ہوں ان میں سے قابل عمل وہی ہوتی ہے جو بعد میں نازل ہوئی ہو۔\n3:سورۃ البقرہ کی آیت کریمہ (والذین یتوفون منکم۔۔۔۔۔۔۔۔۔۔۔۔اشھرو عشر)(البقرہ 234)اور سورۃ الطلاق کی آیت میں تعارض نہیں ہے،بلکہ چار ماہ دس دن کی عدت ایسی عورتوں کے لئے جو حمل سے نہ ہوں اوراگر حمل ہو تو اس کی عدت وضع حمل ہے۔"}],[2308,"عمرو بن العاص رضی اللہ عنہ کہتے ہیں کہ (ہمارے نبی کریم صلی اللہ علیہ وسلم کی) سنت کو ہم پر گڈمڈ نہ کرو، (سنت یہ ہے کہ) جس کا شوہر فوت ہو جائے اس کی یعنی ام ولد ۱؎ کی عدت چار مہینے دس دن ہے۔\n§وضاحت\n۱؎ : ام ولد: ایسی لونڈی جس نے اپنے مالک سے بچہ جنا ہو۔","صحیح",{"u2":"سیدنا عمرو بن العاص رضی اللہ عنہ نے فرمایا کہ ہم پر آپ صلی اللہ علیہ وسلم کی سنت کو خلط ملط مت کرو۔ ابن مثنی نے کہا: ہمارے نبی کریم صلی اللہ علیہ وسلم کی سنت کو۔ (کہ) جس عورت کا خاوند فوت ہو جائے اس کی عدت چار ماہ دس دن ہے۔ یعنی ام ولد (ان کی مراد یہ تھی کہ عورت خواہ آزاد ہو یا ام ولد سب کے لیے حکم ایک ہی ہے)۔","f2":"1:وہ لونڈی جس سے اس کے مالک کی اولادبھی ہو،ام ولد کہلاتی ہے۔\n2: ام ولد کس کا آقافوت ہو جائے اس کی عدت میں اختلاف ہے۔ بعض کھے نزدیک اس کی عدت تین حیض اور بعض کے نزدیک ایک حیض ہے۔ لیکن جن کے نزدیک یہ روایت صحیح ہے،ان کے نزدیک اس کی عدت بھی چاہ مہینے دس کی ہی ہے۔واللہ اعلم)"}],[2309,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم سے اس شخص کے بارے میں مسئلہ دریافت کیا گیا جس نے اپنی بیوی کو تین طلاق دے دی، پھر اس عورت نے دوسرے شخص سے نکاح کر لیا اور وہ شخص اس کے پاس گیا لیکن جماع سے پہلے ہی اس نے اسے طلاق دے دی تو کیا وہ عورت پہلے شوہر کے لیے حلال ہو جائے گی؟ ۔ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"وہ پہلے شوہر کے لیے حلال نہیں ہو سکتی جب تک کہ وہ عورت دوسرے شوہر کی مٹھاس نہ چکھ لے اور وہ شوہر اس عورت کی مٹھاس نہ چکھ لے۱؎\"۔\n§وضاحت\n۱؎ : یعنی ہم بستری اور صحبت کے بعد طلاق واقع ہونے کی صورت میں نکاح جدید سے وہ پہلے شوہر کی بیوی بن سکتی ہے۔","صحیح",{"u2":"ام المؤمنین سیدہ عائشہ رضی اللہ عنہا ا نے کہا کہ رسول اللہ صلی اللہ علیہ وسلم سے پوچھا گیا کہ ایک شخص نے اپنی بیوی کو طلاق دے دی یعنی تین طلاقیں۔ پھر اس عورت نے کسی اور شخص سے نکاح کر لیا، وہ اس پر داخل ہوا مگر مباشرت سے قبل ہی اس کو طلاق دے دی، تو کیا یہ پہلے شوہر کے لیے حلال ہے؟ کہتی ہیں کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا ” یہ عورت پہلے کے لیے حلال نہیں حتیٰ کہ (عورت) کسی دوسرے (مرد) کی مٹھاس چکھ لے اور وہ مرد اس (عورت) کی مٹھاس چکھ لے۔ “","f2":"1؛ سورۃ البقرہ میں آیت 224 اور مابعد میں طلاق کے احکام بیان ہوئے ہیں۔آیت 230 میں ہے کہ پھراگر (تیسری بار)طلاق دی تو اب وہ اس کے لئے حلال نہیں ہے جب تک کسی اور خاوند سے نکاح نہ کرلے پھراگر وہ طلاق دے دے توان دونوں پر کوئی گناہ نہیں کہ پھر باہم مل جائیں بشرطیکہ انہیں یقین ہو وہ دونوں اللہ کی حدود کو قائم رکھیں گے۔\n3: یہ روایت بعض محقیقن کے نزدیک صحیح ہے اس لئے اس میں بیان کردہ بات صحیح روایات میں بھی بیان ہوئی ہے اس سے معلوم ہواکہ دوسری جگہ محض نکاح کر لینا ہی کافی نہیں ہے بلکہ دوسرے خاوند سے اس کا زن وشوہر والا تعلق قائم ہونا بھی ضروری ہے۔ اگر اس تعلق زوجیت کے بغیر ہی دوسراخاوند طلاق دے دے تو یہ عورت اپنے پہلے خاوند کے لئے حلال نہیں ہوگی اسی طرح جو لوگ چند روز اس کے لئے نیت سے نکاح کرتے ہیں تاکہ وہ عورت پہلے خاوند کے لئے حلال ہو جائے تو یہ مشروط نکاح،نکاح نہیں بلکہ بدکاری ہے۔ بنا بریں حلالہ کے نام سے محض رسمی عقد کر لینا اور اسی عارضی طور پر عورت کو کسی مرد کےحوالے کر دینا تا کہ عورت پہلے شوہر کے لئے حلال ہو جائے،حرام ہے،ایسانکاح صحیح ہے نہ رجوع۔ اس غرض سے نکاح کرنے والے کے لئے ایک بہت بڑی مثال دی گئی ہے کہ ایسا تو گویا مانگے کا سانڈ ہے (سنن ابی ابن ماجہ‘النکاح‘حدیث نمبر1936)۔"}],[2310,"عبداللہ بن مسعود رضی اللہ عنہ کہتے ہیں کہ میں نے عرض کیا: اللہ کے رسول! کون سا گناہ سب سے بڑا ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا: \"(سب سے بڑا گناہ یہ ہے کہ) تم اللہ کے ساتھ شریک ٹھہراؤ حالانکہ اسی نے تمہیں پیدا کیا ہے\"، میں نے پوچھا اس کے بعد کون ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا: \"تم اپنے بچے کو اس ڈر سے مار ڈالو کہ وہ تمہارے ساتھ کھائے گا\"، میں نے کہا پھر اس کے بعد؟ تو آپ صلی اللہ علیہ وسلم نے فرمایا: \"یہ کہ تم اپنے پڑوسی کی بیوی سے زنا کرو\"، نیز کہا: نبی اکرم صلی اللہ علیہ وسلم کے قول کی تصدیق کے طور پر یہ آیت نازل ہوئی «والذين لا يدعون مع اللہ إلها آخر ولا يقتلون النفس التي حرم اللہ إلا بالحق ولا يزنون الخ (سورۃ الفرقان: ۶۸) \"جو لوگ اللہ کے علاوہ کسی کو نہیں پکارتے اور ناحق اس نفس کو قتل نہیں کرتے جس کے قتل کو اللہ نے حرام قرار دیا ہے اور نہ زنا کرتے ہیں\"۔","صحیح",{"u2":"سیدنا عبداللہ بن مسعود رضی اللہ عنہ ا کہتے ہیں کہ میں نے کہا: اے اللہ کے رسول! کون سا گناہ سب سے بڑا ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا ” یہ کہ تو اللہ کے ساتھ اس کا شریک بنائے حالانکہ اس نے تجھے پیدا کیا ہے۔ “ کہتے ہیں: میں نے کہا: پھر کون سا؟ آپ صلی اللہ علیہ وسلم نے فرمایا ” یہ کہ تو اپنے بچے کو اس ڈر سے قتل کر دے کہ وہ تیرے ساتھ مل کر کھائے گا۔ “ کہتے ہیں (میں نے کہا) پھر کون سا؟ آپ صلی اللہ علیہ وسلم نے فرمایا ” یہ کہ تو اپنے ہمسائے کی بیوی سے بدکاری کرے۔ “ کہتے ہیں کہ اللہ عزوجل نے نبی کریم صلی اللہ علیہ وسلم کے فرمان کی تصدیق میں یہ آیت نازل فرمائی «والذين لا يدعون مع الله إلها آخر ولا يقتلون النفس التي حرم الله إلا بالحق ولا يزنون» ” (رحمن کے بندے وہی ہیں) جو اللہ کے ساتھ کسی اور کو نہیں پکارتے اور نہ اللہ کی حرام کردہ کسی جان کو قتل کرتے ہیں مگر حق کے ساتھ اور نہ بدکاری کرتے ہیں۔ “","f2":"1: سورۃ الاسراء میں ہے (ولا تقربو الزنی انہ کان ...وساء سبیلا)(بنی اسرائیل:32) زنا کےے قریب نہ جاو۔ بلاشبہ یہ بے حیائی کا کام اور بہت راستہ ہے۔\n2: لفظ تزانی میں ساز باز اور رضا مندی کا مفہوم پا یا جاتاہے جب رضا مندی سے اس عمل کو برائی اور بے حیائی ثابت ہے تو جبرواکراہ سے یہ کام اور بھی زیادہ برترین ہوگا۔ شادی شدہ کے لئے اس کی حدرجم (سنگساری)اور غیر شادی شدہ کے لئے سودرے اور ایک سال کے لئے دیس نکالا(جلاوطن)ہے۔"}],[2311,"ابوالزبیر کہتے ہیں کہ انہوں نے جابر بن عبداللہ رضی اللہ عنہما کو کہتے سنا کہ ایک انصاری شخص کی مسکینہ لونڈی آ کر کہنے لگی کہ میرا مالک مجھے بدکاری کے لیے مجبور کرتا ہے، تو یہ آیت نازل ہوئی «ولا تكرهوا فتياتكم على البغاء» (سورۃ النور: ۳۳) \"تمہاری جو لونڈیاں پاک دامن رہنا چاہتی ہیں انہیں دنیا کی زندگی کے فائدے کی غرض سے بدکاری پر مجبور نہ کرو\"۔","صحیح",{"u2":"سیدنا جابر بن عبداللہ رضی اللہ عنہ سے روایت ہے کہ مسیکہ ایک انصاری کی لونڈی تھی، وہ آئی اور کہا: میرا مالک مجھے بدکاری کے لیے مجبور کرتا ہے۔ چنانچہ اس سلسلے میں یہ آیت اتری «ولا تكرهوا فتياتكم على البغاء» ” اور اپنی لونڈیوں کو بدکاری کے لیے مجبور مت کرو۔ “"}],[2312,"سیلمان تیمی سے روایت ہے کہ آیت کریمہ: «ومن يكرههن فإن الله من بعد إكراههن غفور رحيم» (النور: ۳۳) \"اور جو انہیں مجبور کرے تو اللہ تعالی مجبور کرنے کی صورت میں بخشنے ولا رحم کرنے والا ہے\" کے متعلق سعید بن ابوالحسن نے کہا: اس کا مطلب یہ ہے کہ جنہیں زنا کے لیے مجبور کیا گیا، اللہ تعالی ان کو بخش دے گا۔","صحیح",{"u2":"معتمر اپنے والد (سلیمان تیمی) سے بیان کرتے ہیں کہ آیت کریمہ «ومن يكرههن فإن الله من بعد إكراههن غفور رحيم» کی تفسیر میں سعید بن ابی الحسن کہتے ہیں کہ اللہ تعالیٰ ” مجبور کردہ لونڈیوں کے لیے غفور رحیم ہے۔ “","f2":"یہ ایک تابعی قول ہے عبداللہ بن ابی رئیس المنافقین کے پاس کئی لونڈیاں تھیں ان میں سے ایک کانام مسیکہ تھا وہ ان سے بدکاری کراکے آمدنی حاصل کرتا تھا۔ ان لونڈیوں نے اسلام قبول کرلیا تو اس عمل شنیع سے انکار لرنے لگیں مگر وہ ان پر جبر کرتا تھا توا سی سلسلہ میں یہ آیت نازل ہوئی یعنی زنا ویسے ہی انتہائی قبیح اور بے حیائی کاکام ہے تواس کام کے لئے کسی مجبور کرنا اور بھی براہے البتہ جس پر زبردستی کی گئی ہو اس کے لئے اللہ تعالی کی طرف سے معافی ہے مگر جبر کرنے والا اپنے آپ کو کیسے بچا سکے گا؟"}],[2313,"عبداللہ بن عباس رضی اللہ عنہما سے روایت ہے کہ یہ آیت کریمہ «يا أيها الذين آمنوا كتب عليكم الصيام كما كتب على الذين من قبلكم» \"اے ایمان والو! تم پر روزے اسی طرح فرض کر دئیے گئے ہیں جس طرح تم سے پہلے لوگوں پر فرض کر دئیے گئے تھے\" (سورۃ البقرہ: ۱۸۳) نازل ہوئی تو نبی اکرم صلی اللہ علیہ وسلم کے زمانے میں عشاء پڑھتے ہی لوگوں پر کھانا، پینا اور عورتوں سے جماع کرنا حرام ہو جاتا، اور وہ آئندہ رات تک روزے سے رہتے، ایک شخص نے اپنے نفس سے خیانت کی، اس نے اپنی بیوی سے صحبت کر لی حالانکہ وہ عشاء پڑھ چکا تھا، اور اس نے روزہ نہیں توڑا تو اللہ تعالی نے باقی لوگوں کو آسانی اور رخصت دینی اور انہیں فائدہ پہنچانا چاہا تو فرمایا: «علم الله أنكم كنتم تختانون أنفسكم» \"اللہ کو خوب معلوم ہے کہ تم اپنے آپ سے خیانت کرتے تھے\" (سورۃ البقرہ: ۱۸۷) یہی وہ چیز تھی جس کا فائدہ اللہ نے لوگوں کو دیا اور جس کی انہیں رخصت اور آسانی دی۔","حسن صحیح",{"u2":"آیت کریمہ «يا أيها الذين آمنوا كتب عليكم الصيام ك كتب على الذين من قبلكم» ” اے ایمان والو! تم پر روزہ رکھنا فرض کیا گیا ہے جیسے کہ تم سے پہلے لوگوں پر فرض کیا گیا تھا۔ “ کی تفسیر میں سیدنا ابن عباس رضی اللہ عنہ سے مروی ہے کہ نبی کریم صلی اللہ علیہ وسلم کے دور میں لوگ جب عشاء کی نماز پڑھ لیتے تو ان پر کھانا پینا اور بیویاں حرام ہو جاتی تھیں اور وہ اگلی شام تک کے لیے روزہ دار ہو جاتے تھے۔ پھر (ایسے ہوا کہ) ایک آدمی اپنے نفس کی خیانت کر بیٹھا، یعنی اس نے اپنی بیوی سے ہمبستری کر لی جبکہ وہ عشاء کی نماز پڑھ چکا تھا، اور (سیر ہو کر) کھانا بھی نہیں کھایا تھا، تو اللہ تعالیٰ نے چاہا کہ اس عمل میں باقی لوگوں کے لیے آسانی، رخصت اور نفع پیدا فر دے، تو اللہ تعالیٰ نے فرمایا «علم الله أنكم كنتم تختانون أنفسكم» ” اللہ تعالیٰ خوب جانتا ہے کہ تم اپنے نفسوں کے ساتھ خیانت کرتے ہو۔ “ چنانچہ یہ فرمان اسی سلسلے میں ہے جس کے ذریعے سے اللہ تعالیٰ نے لوگوں کو نفع دیا ہے اور ان کیلئے رخصت اور آسانی فر دی ہے۔","f2":"اس حدیث کی رو سے پہلے یہ مسئلہ تھا کہ عشاء کی نماز کے بعد کھانا پینا اور بیوی سے مباشرت کرنا ممنوع تھا، لیکن ایک صحابی سے عشاء کی نماز پڑھ لینے کے بعد یہ کوتاہی ہو گئی کہ وہ بیوی کے ساتھ ہم بستری کر بیٹھا تو اس کے بعد اللہ تعالیٰ نے رخصت عنایت فرما دی۔ (مزید تفصیل اگلی حدیث کے فوائد میں دیکھیں۔)"}],[2314,"براء رضی اللہ عنہ کہتے ہیں کہ (ابتداء اسلام میں) آدمی جب روزہ رکھتا تھا تو سونے کے بعد آئندہ رات تک کھانا نہیں کھاتا تھا، صرمۃ بن قیس انصاری رضی اللہ عنہ کے ساتھ ایک بار ایسا ہوا کہ وہ روزے کی حالت میں اپنی بیوی کے پاس آئے اور پوچھا: کیا تیرے پاس کچھ(کھانا) ہے؟ وہ بولی: کچھ نہیں ہے لیکن جاتی ہوں ہو سکتا ہے ڈھونڈنے سے کچھ مل جائے، تو وہ چلی گئی لیکن حرمہ کو نیند آ گئی وہ آئی تو (دیکھ کر) کہنے لگی کہ اب تو تم (کھانے سے) محروم رہ گئے دوپہر کا وقت ہوا بھی نہیں کہ (بھوک کے مارے) ان پر غشی طاری ہو گئی اور وہ دن بھر اپنے زمین میں کام کرتے تھے، انہوں نے نبی اکرم صلی اللہ علیہ وسلم سے اس کا ذکر کیا تو یہ آیت «أحل لكم ليلة الصيام الرفث إلى نسائكم» \"روزے کی رات میں تمہارے لیے اپنی عورتوں سے جماع حلال کر دیا گیا ہے\" (سورۃ البقرہ: ۱۸۳) نازل ہوئی، اور آپ صلی اللہ علیہ وسلم نے اللہ تعالی کے قول «من الفجر» تک پوری آیت پڑھی۔","صحیح",{"u2":"سیدنا براء رضی اللہ عنہ بیان کرتے ہیں کہ آدمی جب روزہ رکھنا چاہتا اور سو جاتا تو پھر وہ اگلی شام تک کچھ نہ کھا سکتا تھا۔ سیدنا صرمہ بن قیس انصاری رضی اللہ عنہ اپنی زوجہ کے پاس آئے جبکہ انہوں نے روزہ رکھا ہوا تھا اور اس سے کہا: کیا تیرے پاس (کھانے کی) کوئی چیز ہے؟ اس نے کہا: نہیں مگر میں جاتی ہوں اور آپ کے لیے کچھ تلاش کر لاتی ہوں۔ وہ چلی گئی اور اس اثناء میں صرمہ کی آنکھ لگ گئی۔ جب وہ آئی (اور ان کو سوتے ہوئے پایا) تو کہنے لگی افسوس آپ کے خسارے پر! چنانچہ دوپہر نہ ہوئی کہ انہیں غشی آ گئی، اور وہ دن کو اپنی زمیں میں کام کیا کرتے تھے۔ تو نبی کریم صلی اللہ علیہ وسلم کو یہ واقعہ بتایا گیا، اس کے بعد یہ آیت کریمہ نازل ہوئی «أحل لكم ليلة الصيام الرفث إلى نسائكم» آپ صلی اللہ علیہ وسلم نے «من الفجر» تک قرآت کی۔ ” روزے کی رات میں تمہارے لیے اپنی بیویوں سے مباشرت حلال کی گئی ہے۔ وہ تمہارا لباس ہیں اور تم ان کا لباس ہو۔ اللہ کو معلوم ہے کہ تم اپنے نفسوں کے ساتھ خیانت کر بیٹھتے ہو، سو اس نے تم پر رجوع فرمایا اور تمہیں معاف کر دیا ہے۔ تم اب اپنی عورتوں سے مباشرت کر سکتے ہو اور طلب کرو وہ جو اللہ نے تمہارے لیے مقدر فرمایا ہے۔ اور کھاؤ پیو حتیٰ کہ فجر کے وقت صبح کی سفید دھاری سیاہ دھاری سے جدا نظر آنے لگے۔ “","f2":"(1)اس حدیث سے مذکورہ حدیث کے برعکس یہ بات ثابت ہوتی ہے کہ پہلے مسئلہ یہ تھا کہ سو جانے کے بعد، رات کو کھانا پینا اور بیوی سے ہم بستری کرنا ممنوع تھا۔ شارحین نے ان کے درمیان یہ تطبیق دی ہے کہ ان دونوں میں سے جو کام بھی ہو جاتا تھا، اس کے بعد اگلی رات تک اس کے لیے مذکورہ کام ممنو ع ہو جاتے تھے۔ اس کے بعد اللہ تعالیٰ نے غروب شمس سے لے کر صبح صادق تک مذکورہ کاموں کی اجازت دے دی، جس سے مسلمانوں کو بڑی رخصت اور سہولت حاصل ہو گئی۔ (2) امام ابوداود اس امر کے قائل ہیں کہ رمضان کے روزے براہ راست فرض کیے گئے تھے ان سے پہلے عاشور وغیرہ کے روزے فرض نہ تھے۔ واللہ اعلم"}],[2315,"سلمہ بن الاکوع رضی اللہ عنہ کہتی ہیں کہ جب یہ آیت «وعلى الذين يطيقونه فدية طعام مسكين» \"اور جو لوگ روزہ رکھنے کی طاقت رکھتے ہیں وہ ایک مسکین کا کھانا فدیہ دے دیں\" (سورۃ البقرہ: ۱۸۳) نازل ہوئی تو جو شخص ہم میں سے روزے نہیں رکھنا چاہتا وہ فدیہ ادا کر دیتا پھر اس کے بعد والی آیت نازل ہوئی تو اس نے اس حکم کو منسوخ کر دیا۔","صحیح",{"u2":"سیدنا سلمہ بن اکوع رضی اللہ عنہ کہتے ہیں کہ جب یہ آیت کریمہ نازل ہوئی ” اور جو روزہ رکھنے کی طاقت رکھتے ہوں وہ ایک مسکین کے کھانے کا فدیہ دیں۔ “ تو ہم میں سے جو چاہتا روزہ چھوڑ دیتا اور فدیہ دینا چاہتا تو فدیہ دے دیا کرتا تھا حتیٰ کہ اس کے بعد والی آیت اتری جس نے اس (رخصت) کو منسوخ کر دیا۔","f2":"بعد والی آیت سے مراد ہے: (فَمَن شَهِدَ مِنكُمُ ٱلشَّهْرَ‌ فَلْيَصُمْهُ) (البقرة: 185) یعنی جو اس مہینے میں حاضر ہو، وہ اس کے روزے رکھے۔"}],[2316,"عبداللہ بن عباس رضی اللہ عنہما سے روایت ہے کہ آیت کریمہ «وعلى الذين يطيقونه فدية طَعام مسكين» نازل ہوئی تو ہم میں سے جو شخص ایک مسکین کا کھانا فدیہ دینا چاہتا دے دیتا اور اس کا روزہ مکمل ہو جاتا، پھر اللہ تعالی نے فرمایا: «فمن تطوع خيرا فهو خير له وأن تصوموا خير لكم» (سورۃ البقرہ: ۱۸۴) \"پھر جو شخص نیکی میں سبقت کرے وہ اسی کے لیے بہتر ہے لیکن تمہارے حق میں بہتر کام روزہ رکھنا ہی ہے\"، پھر فرمایا: «فمن شهد منكم الشهر فليصمه ومن كان مريضا أو على سفر فعدة من أيام أخر» (سورۃ البقرہ: ۱۸۵) \"تم میں سے جو شخص رمضان کے مہینے کو پائے تو وہ اس کے روزے رکھے، ہاں جو بیمار ہو یا مسافر ہو وہ دوسرے دنوں میں یہ گنتی پوری کرے\"۔","حسن",{"u2":"عکرمہ سے منقول ہے کہ سیدنا ابن عباس رضی اللہ عنہ آیت کریمہ «وعلى الذين يطيقونه فدية طعام مسكين» کے سلسلے میں فرماتے ہیں کہ جو کوئی ایک مسکین کا فدیہ دینا چاہتا، دے دیتا تھا اور اس کا روزہ پورا اور کامل سمجھا جاتا تھا۔ پھر اللہ تعالیٰ نے فرمایا «فمن تطوع خيرا فهو خير له وأن تصوموا خير لكم» ” جو خوشی سے بھلائی کرے (مسکین کو کھانا کھلائے) تو یہ اس کے لیے بہتر ہے اور روزہ رکھنا تمہارے لیے بہتر ہے۔ “ اور فرمایا «من شهد منكم الشهر فليصمه ومن كان مريضا أو على سفر فعدة من أيام أخر» ” جو شخص اس مہینے میں حاضر ہو تو اسے چاہیئے کہ اس کے روزے رکھے۔ اور جو مریض ہو یا سفر پر ہو تو وہ دوسرے دنوں میں ان کی گنتی پوری کرے۔ “"}],[2317,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں اس آیت کا حکم حاملہ اور دودھ پلانے والی عورت کے حق میں باقی رکھا گیا ہے۔","صحیح",{"u2":"عکرمہ نے بیان کیا کہ سیدنا ابن عباس رضی اللہ عنہ فرماتے ہیں آیت کریمہ «وعلى الذين يطيقونه فدية طعام مسكين» حامہ اور دودھ پلانے والی کے حق میں محکم ہے۔ (منسوخ نہیں ہے)۔"}],[2318,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ اللہ تعالی کے فرمان: «وعلى الذين يطيقونه فدية طَعام مسكين» زیادہ بوڑھے مرد و عورت (جو کہ روزے رکھنے کی طاقت رکھتے ہیں) کے لیے رخصت ہے کہ روزے نہ رکھیں، بلکہ ہر دن کے بدلے ایک مسکین کو کھانا کھلا دیں، اور حاملہ نیز دودھ پلانے والی عورت بچے کے نقصان کا خوف کریں تو روزے نہ رکھیں، فدیہ دیں۔ ابوداؤد کہتے ہیں: یعنی مرضعہ اور حاملہ کو اپنے بچوں کے نقصان کا خوف ہو تو وہ بھی روزے نہ رکھیں اور ہر روزے کے بدلہ ایک مسکین کو کھانا کھلائیں۔","شاذ",{"u2":"سیدنا ابن عباس رضی اللہ عنہ سے مروی ہے کہ آیت کریمہ «وعلى الذين يطيقونه فدية طعام مسكين» کی تفسیر میں انہوں نے کہا کہ بڑی عمر کے بوڑھے مرد اور عورت کے لیے رخصت ہے کہ باوجود روزے کی طاقت کے افطار کر سکتے ہیں۔ وہ ہر دن کے بدلے ایک مسکین کو کھانا کھلا دیا کریں۔ اسی طرح حاملہ اور دودھ پلانے والی عورتوں کو جب اندیشہ ہو۔ (تو وہ بھی افطار کر سکتی ہیں۔) امام ابوداؤد رضی اللہ عنہ فرماتے ہیں: مقصد یہ ہے کہ جب انہیں اپنے بچے کے بارے میں (بیماری یا کمزوری وغیرہ کا) اندیشہ ہو تو افطار کر سکتی ہیں اور اس کے بدلے کھانا کھلا دیا کریں۔","f2":"حضرت ابن عباس رضی اللہ عنہ کی یہ روایت، جس طرح یہاں ابوداود میں آئی ہے، شاذ ہے، اسی لیے ہمارے فاضل محقق الشیخ زبیر علی زئی حفظہ اللہ نے بھی اسے ضعیف قرار دیا ہے۔ لیکن حضرت ابن عباس وغیرہ کی دیگر صحیح روایات سے یہ مسئلہ ثابت ہے جو اس میں بیان ہوا ہے۔ جس کا خلاصہ یہ ہے کہ آیت مذکورہ بالا عام لوگوں کے حق میں منسوخ ہے اور ان پر روزہ رکھنا فرض ہے۔ مگر بعض بوڑھے جو روزہ رکھنے کو تو رکھ لیں مگر اس کے اثرات مابعد کے متحمل نہ ہو سکتے ہوں اور انہیں ازحد مشقت ہوتی ہو تو ان کے لیے فدیہ دے کر روزہ چھوڑنے کی اجازت ہے۔ اور ایسے ہی حاملہ اور دودھ پلانے والی عورت کا مسئلہ ہے کہ اگر ان کے روزہ رکھنے سے رحم میں زیر پرورش یا دودھ پیتے بچے کی بابت اندیشہ ہو، تو ان کے لیے بھی فدیے کی رخصت ہے۔ گویا زیادہ بوڑھے مردو عورت کو ان کی اپنی ذاتی کمزوری کی بنا پر رخصت دی گئی ہے اور حاملہ و مُر ضِعَہ کو رخصت بچوں کے اندیشے کے پیش نظر دی گئی ہے۔ تاہم حاملہ اور مُرضِعَہ بعد میں قضا دیں یا نہ دیں؟ اس کی بابت اختلاف ہے۔ ایک رائے تو یہ ہے کہ ان کے لیے فدیہ ہی کافی ہے، بعد میں قضا نہیں۔ دوسرا موقف حافظ ابن حزم کا ہے جو انہوں نے المحلیٰ (مسئلہ نمبر 770) میں بیان کیا ہے۔ اور وہ یہ ہے کہ ان پر قضا ہے نہ فدیہ۔ تیسری رائے یہ ہے کہ فدیہ طعام کے علاوہ بعد میں وہ قضا بھی دیں۔ چوتھی رائے ہے کہ وہ مریض کے حکم میں ہیں، وہ روزہ چھوڑ دیں، انہیں فدیہ دینے کی ضرورت نہیں، اور بعد میں قضا دیں۔ فضیلة الشیخ مولانا محمد علی جانباز حفظہ اللہ نے اسی رائے کو ترجیح دی ہے۔ (انجاز الحاجة شرح سنن ابن ماجه:5/566) اور سعودی علماء کی بھی یہی رائے ہے۔ (فتاویٰ اسلامیہ اُردو: 2/203-205) حضرت ابن عباس کی اس موقوف روایت کی اسنادی بحث کے لیے دیکھئے۔ (ارواء الغلیل، حدیث:912)"}],[2319,"عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ رسول صلی اللہ علیہ وسلم نے فرمایا: \"ہم ان پڑھ لوگ ہیں نہ ہم لکھنا جانتے ہیں اور نہ حساب و کتاب، مہینہ ایسا، ایسا اور ایسا ہوتا ہے، (آپ صلی اللہ علیہ وسلم نے دونوں ہاتھوں کی انگلیوں سے بتایا)\"، راوی حدیث سلیمان نے تیسری بار میں اپنی انگلی بند کر لی، یعنی مہینہ انتیس اور تیس دن کا ہوتا ہے۔","صحیح",{"u2":"سیدنا ابن عمر رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” ہم اُمّی امت ہیں، ہم لکھنا نہیں جانتے اور نہ (دقیق) حساب کر سکتے ہیں۔ (آپ نے دونوں ہاتھوں کی دسوں انگلیاں پھیلا کر اشارے سے فرمایا) مہینہ ایسے ہوتا ہے اور ایسے ہوتا ہے اور ایسے ہوتا ہے۔ “ اور تیسری بار میں سلیمان بن حرب نے اپنی ایک انگلی بند کر لی۔ یعنی انتیس دن اور تیس دن۔","f2":"(1) }امة امية{ اُمی امت اس کلمہ کی توجیہات میں سے ایک توجیہ یہ ہے کہ یہ (اُم) ماں کی طرف منسوب ہے اور مراد ہے ایسے لوگ جو علم و معرفت کے مسائل میں مادری صفات پر قائم ہوں جسے ہم علم سے کورے سے تعبیر کر سکتے ہیں۔ اور عرب میں تعلیم و تعلم اسلام کی برکت ہی سے آیا ہے، اس سے پہلے ان میں یہ فنون گنتی کے لوگ جانتے تھے۔ اسی لیے اس کا ترجمہ ان پڑھ کر دیا جاتا ہے۔ (2) قمری مہینے کبھی انتیس دن کے ہوتے ہیں اور کبھی تیس دن کے۔ اٹھائیس یا اکتیس کے نہیں ہوتے۔ (3) ابوداود کی اس روایت میں اختصار ہے۔ دوسری روایات میں ہے کہ دوسری مرتبہ آپ نے ہاتھوں کی انگلیوں کے ساتھ تین مرتبہ اشارہ کیا۔ یعنی مہینہ کبھی 29 دن کا اور کبھی 30 دن کا ہوتا ہے۔"}],[2320,"عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"مہینہ انتیس دن کا (بھی) ہوتا ہے لہٰذا چاند دیکھے بغیر نہ روزہ رکھو، اور نہ ہی دیکھے بغیر روزے چھوڑو، اگر آسمان پر بادل ہوں تو تیس دن پورے کرو\"۔ راوی کا بیان ہے کہ جب شعبان کی انتیس تاریخ ہوتی تو ابن عمر رضی اللہ عنہما چاند دیکھتے اگر نظر آ جاتا تو ٹھیک اور اگر نظر نہ آتا اور بادل اور کوئی سیاہ ٹکڑا اس کے دیکھنے کی جگہ میں حائل نہ ہوتا تو دوسرے دن روزہ نہ رکھتے اور اگر بادل یا کوئی سیاہ ٹکڑا دیکھنے کی جگہ میں حائل ہو جاتا تو صائم ہو کر صبح کرتے۔ راوی کا یہ بھی بیان ہے کہ ابن عمر رضی اللہ عنہما لوگوں کے ساتھ ہی روزے رکھنا چھوڑتے تھے، اور اپنے حساب کا خیال نہیں کرتے تھے۔","صحیح",{"u2":"سیدنا ابن عمر رضی اللہ عنہ کا بیان ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” مہینہ انتیس دن کا (بھی) ہوتا ہے۔ سو چاند دیکھے بغیر نہ روزے شروع کرو اور نہ دیکھے بغیر ختم کرو۔ اگر بادل کے باعث نظر نہ آئے تو اس مہینے کے تیس دن کا اندازہ لگا لو۔ “ چنانچہ جب شعبان کہ انتیسویں تاریخ ہوتی تو سیدنا عبداللہ بن عمر رضی اللہ عنہ کے لیے چاند دیکھا جاتا۔ اگر نظر آ جاتا تو بہتر اور اگر دکھائی نہ دیتا اور نظر نہ آنے میں کوئی بادل یا غبار بھی حائل نہ ہوتا تو وہ روزہ نہ رکھتے۔ لیکن اگر فضا میں کوئی بادل یا غبار حائل ہوتا تو وہ روزہ رکھ لیتے۔ راوی نے بیان کیا کہ ابن عمر رضی اللہ عنہ لوگوں کے ساتھ ہی روزہ چھوڑتے اور حساب کے درپے نہ ہوتے۔","f2":"حضرت ابن عمر رضی اللہ عنہ بادل اور غبار وغیرہ جیسی رکاوٹ کے باعث چاند نظر نہ آنے پر روزہ رکھ لیا کرتے تھے ممکن ہے کہ اگلا دن رمضان کا ہو۔ اور وہ اس کو شک کا دن نہ سمجھتے تھے۔ وہ شدت احتیاط کے تحت ایسا کرتے اور اس میں وہ منفرد بھی ہیں، اس لیے راجح یہی ہے کہ ابر یا غبار کے باعث چاند نظر نہ آئے تو شعبان کے تیس دن پورے کئے جائیں گے۔ اس دن کا روزہ شک کا روزہ ہو گا جو کہ ممنوع ہے۔ علامہ البانی رحمة اللہ علیہ نے حضرت ابن عمر کا یہ عمل ضعیف لکھا ہے۔"}],[2321,"ایوب کہتے ہیں: عمر بن عبدالعزیز نے بصرہ والوں کو لکھا کہ ہمیں رسول اللہ صلی اللہ علیہ وسلم کے متعلق معلوم ہوا ہے۔ ۔ ۔، آگے اسی طرح ہے جیسے ابن عمر رضی اللہ عنہما کی اوپر والی مرفوع حدیث میں ہے البتہ اس میں اتنا اضافہ ہے: \"اچھا اندازہ یہ ہے کہ جب ہم شعبان کا چاند فلاں فلاں روز دیکھیں تو روزہ ان شاءاللہ فلاں فلاں دن کا ہو گا، ہاں اگر چاند اس سے پہلے ہی دیکھ لیں (تو چاند دیکھنے ہی سے روزہ رکھیں)\"۔","صحیح",{"u2":"سیدنا عمر بن عبدالعزیز نے اہل بصرہ کی طرف لکھا کہ ہمیں رسول اللہ صلی اللہ علیہ وسلم سے یہ حدیث پہنچی ہے جیسے کہ مذکورہ بالا ابن عمر رضی اللہ عنہ کی حدیث ہے۔ اس میں یہ اضافہ ہے ” بہترین اندازہ یہ ہے کہ اگر ہم نے شعبان کا چاند فلاں فلاں دن دیکھا تو روزہ انشاءاللہ فلاں دن کا ہوگا الا یہ کہ لوگ اس سے پہلے ہی چاند دیکھ لیں۔ “","f2":"اصل اعتبار اور اہمیت چاند دیکھنے کی ہے، محض حساب کی نہیں۔"}],[2322,"عبداللہ بن مسعود رضی اللہ عنہ کہتے ہیں کہ ہم نے نبی اکرم صلی اللہ علیہ وسلم کے ساتھ تیس دن کے روزے کے مقابلے میں انتیس دن کے روزے زیادہ رکھے ہیں۔","صحیح",{"u2":"سیدنا عبداللہ بن مسعود رضی اللہ عنہ سے روایت ہے، انہوں نے کہا کہ ہم نے نبی کریم صلی اللہ علیہ وسلم کے ساتھ (رمضان میں) انتیس انتیس روزے بہت زیادہ رکھے ہیں اور تیس تیس کم۔","f2":"(1)انتیس روزے مجموعی لحاظ سے اجر میں تیس ہی کی طرح ہوتے ہیں، کیونکہ اس عمل کی بنیاد اخلاص اور اطاعت پر ہے۔ (2) }لما صمنا{ میں ما موصولہ یا مصدریہ ہے۔ (عون المعبود)"}],[2323,"ابوبکرہ رضی اللہ عنہ نبی اکرم صلی اللہ علیہ وسلم سے روایت کرتے ہیں آپ نے فرمایا: \"عید کے دونوں مہینے رمضان اور ذی الحجہ کم نہیں ہوتے ۱؎\"۔\n§وضاحت\n۱؎ : یعنی دونوں ایک ہی سال میں انتیس انتیس دن کے نہیں ہوتے، ایک اگر انتیس ہے تو دوسرا تیس کا ہو گا، ایک مفہوم یہ بتایا جاتا ہے کہ ثواب کے اعتبار سے کم نہیں ہوتے اگر انتیس دن کے ہوں تب بھی پورے مہینے کا ثواب ملے گا۔","صحیح",{"u2":"جناب عبدالرحمٰن بن ابی بکرہ اپنے والد سے، وہ نبی کریم صلی اللہ علیہ وسلم سے بیان کرتے ہیں کہ آپ صلی اللہ علیہ وسلم نے فرمایا ” عید کے دونوں مہینے یعنی رمضان اور ذوالحجہ کم نہیں ہوتے ہیں۔ “","f2":"اس حدیث کی شرح میں کئی اقوال ہیں۔ افادات حافظ ابن قیم رحمة اللہ علیہ کا حاصل درج ذیل ہے۔ (1)یہ دونوں مہینے ایک ہی سال میں انتیس انتیس دن کے نہیں ہوتے۔ امام احمد کی رائے بھی یہی ہے۔ (2) یہ بات تغلیبی ہے یعنی بالعموم نقص میں جمع نہیں ہوتے۔ اگر کبھی ہو بھی جائیں تو وہ شاذ ہے۔ (3) علماء کی ایک جماعت کا خیال ہے کہ نبی صلی اللہ علیہ وسلم کا یہ فرمان اسی سال کے لیےتھا۔ (4) یہ دونوں مہینے اجروثواب میں کم نہیں ہوتے خواہ گنتی میں انتیس دن ہی کے ہوں۔ اللہ کے ہاں اجروثواب پورا ہوتا ہے۔ (5) اس قول سے مراد عشرہ ذی الحجہ کی فضیلت کا بیان ہے کہ ان دنوں کے اعمال کا ثواب رمضان کے برابر ہوتا ہے۔ البتہ ان دونوں میں تقابلی طور پر یوں کہا جاتا ہے کہ آخری عشرہ رمضان اور اول عشرہ ذی الحجہ میں عشرہ رمضان کی راتوں کو فضیلت ہے کیونکہ ان میں لیلة القدر ہے۔ اور نبی صلی اللہ علیہ وسلم ان راتوں میں عبادت کا جو اہتمام فرماتے تھے دیگر زمانے میں ایسے نہ ہوتا تھا۔ اور دنوں کے اعتبار سے عشرہ ذی الحجہ کے دن افضل ہیں کیونکہ حدیث میں قربانی والے دن کو اعظم الایام فرمایا گیا ہے۔ اور یوم عرفہ کی فضیلت بھی معلوم و معروف ہے۔ (6) چونکہ یہ مہینے اور دن اللہ کے محبوب ترین ایام ہیں اور ان میں کیے جانے والے اعمال بہت مبارک ہوتے ہیں۔ لہذا بطور ترغیب فرمایا گیا ہے کہ ان کی کمی بیشی کا خیال مت کرو بلکہ اعمال خیر میں سبقت کی کوشش کرو۔ اجر و ثواب میں ان دونوں مہینوں میں کوئی کمی نہیں ہوتی۔"}],[2324,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے حدیث بیان کی، اس میں ہے: \"تمہاری عید الفطر اس دن ہے جس دن تم افطار کرتے ہو ۱؎ اور عید الاضحی اس دن ہے جس دن تم قربانی کرتے ہو، پورا کا پورا میدان عرفہ ٹھہرنے کی جگہ ہے اور سارا میدان منی قربانی کرنے کی جگہ ہے نیز مکہ کی ساری گلیاں قربان گاہ ہیں، اور سارا مزدلفہ وقوف (ٹھہرنے) کی جگہ ہے\"۔\n§وضاحت\n۱؎ : اسی جملے کی باب سے مطابقت ہے ، مطلب یہ ہے کہ : جب سارے کے سارے لوگ تلاش و جستجو اور اجتہاد کے بعد کسی دن چاند کا فیصلہ کر لیں اور اسی حساب سے روزہ اور افطار اور قربانی کر لیں اور بعد میں چاند دوسرے دن کا ثابت ہوجائے تو یہ اجتماعی غلطی معاف ہے۔","صحیح",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ سے مروی ہے (یہ طویل حدیث کا ایک حصہ ہے) کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا ” عید الفطر اسی دن ہے جب تم افطار کرو اور عید قرباں اسی دن ہے جب تم قربانی کرو۔ سارا میدان عرفات وقوف کی جگہ ہے اور سارا منیٰ جائے قربانی ہے، مکہ کے تمام راستے قربانی کی جگہ ہیں اور سارا مزدلفہ وقوف کی جگہ ہے۔ “","f2":"اجتہادی امور میں خطا معاف ہے۔ عید یا حج کے موقع پر چاند نظر نہ آیا ہو اور لوگ مہینے کے تیس دن پورے کر لیں اور بعد میں پتہ چلے کہ چاند تو انتیس کا تھا تو ان پر روزے اور وقوف عرفات و قربانی کا کوئی عیب نہیں۔ ایسے ہی اگر کئی فساق اکٹھے ہو کر انتیس ہی کو چاند ہونے کا مشہود کر دیں اور مسلمان ان کے بھرے میں آ کر افطار کر لیں یا وقوف عرفات و قربانی ہو جائے تو اس میں عامة المسلمین پر کوئی عیب نہیں۔ ہمارے علم میں یہ بات آئی ہے کہ بعض بے دینوں نے توبہ کرنے کے بعد اظہار کیا کہ ہم چند لوگ مل کر چاند ہونے کا دعویٰ کر دیتے تھے، شہادتیں اور قسمیں بھی کھا لیتے تھے اور عید کروا دیتے تھے۔ العیاذباللہ۔ ایسی صورت میں ازالہ نا ممکن ہو تو خطا معاف ہے۔"}],[2325,"عبداللہ بن ابی قیس کہتے ہیں کہ میں نے ام المؤمنین عائشہ رضی اللہ عنہا کو کہتے سنا کہ رسول صلی اللہ علیہ وسلم ماہ شعبان کی تاریخوں کا جتنا خیال رکھتے کسی اور مہینے کی تاریخوں کا اتنا خیال نہ فرماتے، پھر رمضان کا چاند دیکھ کر روزے رکھتے، اگر وہ آپ پر مشتبہ ہو جاتا تو تیس دن پورے کرتے، پھر روزے رکھتے۔","صحیح",{"u2":"ام المؤمنین سیدہ عائشہ رضی اللہ عنہا ا بیان کرتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم شعبان کی تاریخوں کی اتنی نگہداشت رکھتے تھے کہ دوسرے مہینوں میں اتنی نگہداشت نہ رکھتے تھے۔ پھر چاند دیکھ کر رمضان کے روزے رکھنے شروع کرتے اگر کبھی (شعبان کی انتیس تاریخ کو) مطلع ابرآلود ہوتا، تو تیس دن پورے کرتے اور پھر روزے رکھنا شروع کرتے۔","f2":"غیر یقینی صورت حال میں روزہ رکھنا روا نہیں ہے۔ یہ شک کا دن شمار ہو گا، نیز استقبال کی نیت سے روزہ نہیں رکھنا چاہیے کیونکہ یہ ممنوع ہے۔"}],[2326,"حذیفہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"چاند دیکھے بغیر یا مہینے کی گنتی پوری کئے بغیر پہلے ہی روزے رکھنا شروع نہ کر دو، بلکہ چاند دیکھ کر یا گنتی پوری کر کے روزے رکھو\"۔","صحیح",{"u2":"سیدنا حذیفہ رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” مہینہ شروع ہونے سے پہلے روزے مت رکھو حتیٰ کہ چاند دیکھ لو یا (تیس کی) گنتی پوری کر لو، پھر روزے رکھتے جاؤ حتیٰ کہ چاند دیکھ لو یا (تیس کی) گنتی پوری کر لو۔ “ امام ابوداؤد رضی اللہ عنہ فرماتے ہیں کہ اس روایت کو سفیان وغیرہ نے منصور سے، انہوں نے ربعی سے، انہوں نے ایک صحابی سے بیان کیا ہے اور اس سند میں (صحابی کے نام) حذیفہ کی صراحت نہیں ہے۔"}],[2327,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"رمضان سے ایک یا دو دن پہلے ہی روزے رکھنے شروع نہ کر دو، ہاں اگر کسی کا کوئی معمول ہو تو رکھ سکتا ہے، اور بغیر چاند دیکھے روزے نہ رکھو، پھر روزے رکھتے جاؤ، (جب تک کہ شوال کا) چاند نہ دیکھ لو، اگر اس کے درمیان بدلی حائل ہو جائے تو تیس کی گنتی پوری کرو اس کے بعد ہی روزے رکھنا چھوڑو، اور مہینہ انتیس دن کا بھی ہوتا ہے\"۔ ابوداؤد کہتے ہیں: حاتم بن ابی صغیرہ، شعبہ اور حسن بن صالح نے سماک سے پہلی حدیث کے مفہوم کے ہم معنی روایت کیا ہے لیکن ان لوگوں نے «فأتموا العدة ثلاثين» کے بعد «ثم أفطروا» نہیں کہا ہے۔","صحیح",{"u2":"سیدنا ابن عباس رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” مہینہ (رمضان) شروع ہونے سے پہلے ایک دو دن کے روزے مت رکھو (استقبالی روزے مت رکھو) الا یہ کہ کوئی شخص اس دن کا روزہ رکھا کرتا ہو۔ چاند دیکھ کر روزے شروع کرو، پھر رکھتے جاؤ حتیٰ کہ (شوال کا) چاند دیکھ لو۔ اگر اس کے دکھائی دینے میں کوئی بادل (وغیرہ) حائل ہو تو تیس کی گنتی پوری کر لو اور پھر روزے موقوف کر دو۔ اور مہینہ انتیس دن کا (بھی) ہوتا ہے۔ “ امام ابوداؤد رضی اللہ عنہ نے کہا: اس روایت کو حاتم بن ابی صغیرہ، شعبہ اور حسن بن صالح نے سماک سے اسی (مذکورہ بالا) روایت کے ہم معنی بیان کیا ہے مگر ” روزے موقوف کر دو “ کا جملہ ان کی روایت میں نہیں ہے۔ امام ابوداؤد رضی اللہ عنہ نے کہا: حاتم بن ابی صغیرہ کا نسب یوں ہے۔ حاتم بن مسلم ابن ابی صغیرہ اور ابوصغیرہ حاتم کا سوتیلا باپ تھا۔","f2":"یہ روایت ضعیف ہے لیکن بعض کے نزدیک صحیح ہے، کیونکہ یہ باتیں صحیح روایات میں بیان ہوئی ہیں۔ رمضان شروع ہونے سے ایک دو دن پہلے اگر کوئی قضا یا نذر کا روزہ پورا کرنا چاہتا ہو یا اس کی عادت ہو کہ سوموار اور جمعرات کے روزے رکھتا ہو تو رکھ سکتا ہے، یہ استقبالی روزے شمار نہ ہوں گے، کیونکہ یہ اس کے دائمی اور مسلسل عمل کا حصہ ہیں۔"}],[2328,"عمران بن حصین رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے ایک شخص سے پوچھا: \"کیا تم نے شعبان کے کچھ روزے رکھے ہیں ۱؎؟\"، جواب دیا: نہیں، آپ صلی اللہ علیہ وسلم نے فرمایا: \"جب (رمضان کے) روزے رکھ چکو تو ایک روزہ اور رکھ لیا کرو\"، ان دونوں میں کسی ایک راوی کی روایت میں ہے: \"دو روزے رکھ لیا کرو\"۔\n§وضاحت\n۱؎ : مؤلف کے سوا ہر ایک کے یہاں «شهر» (مہینہ) کی بجائے «سرر» (آخر ماہ) کا لفظ ہے ، بلکہ خود مؤلف کے بعض نسخوں میں بھی یہی لفظ ہے، اور حدیث کا مطلب یہ ہے کہ : ’’ اس آدمی کی عادت تھی کہ ہر مہینہ کے اخیر میں روزہ رکھا کرتا تھا، مگر رمضان سے ایک دو دن برائے استقبال رمضان روزہ کی ممانعت ‘‘ سن کر اس نے اپنے معمول والا یہ روزہ نہیں رکھا، تو آپ صلی اللہ علیہ وسلم نے اس کی غلط فہمی دور کرنے کے لئے ایسا فرمایا، یعنی : رمضان سے ایک دو دن قبل روزہ رکھنے کا اگر کسی کا معمول ہو تو وہ رکھ سکتا ہے ، نیز اس سے یہ بھی ثابت ہوتا ہے کہ معمول کی عبادت اگر کسی سبب سے چھوٹ جائے تو اس کی قضا کر لینی چاہئے۔","صحیح",{"u2":"سیدنا عمران بن حصین رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے ایک شخص سے پوچھا ” کیا تو نے شعبان کے آخر میں کوئی روزہ رکھا ہے؟ “ اس نے کہا: نہیں۔ آپ صلی اللہ علیہ وسلم نے فرمایا ” جب (رمضان کے) روزے پورے کر لو تو ایک دن روزہ رکھ لینا۔ “ (ثابت یا سعید جریری دونوں میں سے کسی) ایک نے بیان کیا کہ ” دو دن۔ “","f2":"(1) یہ حدیث بظاہر گزشتہ حدیث سے متعارض ہے جس میں ہے کہ رمضان شروع ہونے سے پہلے ایک دو دن کے روزے مت رکھو۔ مگر ان میں جمع کی صورت یہ ہے کہ یہ رخصت اور تاکید اس شخص کے لیے ہے جس نے کسی روزے کی نذر مانی ہو یا وہ پہلے سے خاص دن کے روزے رکھنے کا عادی ہو تو اسے چاہیے کہ حسب معمول اپنے روزے رکھے۔ مگر کوئی سابقہ عادت یا نذر کے بغیر بطور نفل کے استقبالی روزہ رکھنا چاہیے تو اجازت نہیں ہے۔ (2) نبی صلی اللہ علیہ وسلم نے جس شخص کو رمضان کے بعد ایک یا دو روزے رکھنے کی تاکید فرمائی، وہ شخص مہینے کے آخر میں روزے رکھا کرتا تھا، لیکن اس نے شعبان کے آخر میں اس لیے روزے چھوڑ دیے تھے کہ کہیں استقبالِ رمضان کے ذیل میں نہ آ جائیں جو ممنوع ہیں۔ (3) لفظ (سَرَر) کے مختلف معانی مندرجہ ذیل روایت کے بعد مذکور ہیں۔"}],[2329,"ابوازہر مغیرہ بن فروہ کہتے ہیں کہ معاویہ رضی اللہ عنہ نے دیر مسحل پر (جو کہ حمص کے دروازے پر واقع ہے)، کھڑے ہو کر لوگوں سے کہا: لوگو! ہم نے چاند فلاں فلاں دن دیکھ لیا ہے اور میں سب سے پہلے روزہ رکھ رہا ہوں، جو شخص روزہ رکھنا چاہے رکھ لے، مالک بن ہبیرہ سبئی نے کھڑے ہو کر ان سے کہا: معاویہ! یہ بات آپ نے رسول صلی اللہ علیہ وسلم سے سن کر کہی ہے، یا آپ کی اپنی رائے ہے؟ جواب دیا: میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا ہے: \"رمضان کے مہینے کے روزے رکھو اور آخر شعبان کے\"۔","",{"u2":"ابوازہر مغیرہ بن فروہ سے روایت ہے کہ سیدنا معاویہ رضی اللہ عنہ دیر مسحل میں لوگوں کو خطبہ دینے کے لیے کھڑے ہوئے جو کہ باب حمص کے پاس ہے۔ انہوں نے کہا: لوگوں! ہم نے (شعبان کا) چاند فلاں فلاں دن دیکھا تھا، میں (چاند ہونے سے) پہلے روزے شروع کر رہا ہوں، جو ایسا کرنا چاہے کر لے۔ پھر مالک بن ہبیرہ السبی ان کے سامنے کھڑا ہوا اور کہا: اے معاویہ! اس سلسلے میں آپ نے رسول اللہ صلی اللہ علیہ وسلم سے کچھ سنا ہے یا یہ آپ کی اپنی رائے ہے؟ کہا: میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا ” مہینے میں روزے رکھا کرو اور اس کے آخر میں بھی۔ “ (دوسرا ترجمہ: رمضان کے روزے رکھو اور اس کے اول میں بھی۔ یعنی آخر شعبان میں۔)"}],[2330,"سلیمان بن عبدالرحمٰن نے اس حدیث کے سلسلہ میں بیان کیا ہے کہ ولید کہتے ہیں: میں نے ابوعمرو یعنی اوزاعی کو کہتے سنا ہے کہ «سرہ»کے معنی اوائل ماہ کے ہیں۔","شاذ مقطوع",{"u2":"جناب ابوعمرو اوزاعی بیان کرتے ہیں کہ «سره» کے معنی ” ابتدائے مہینہ “ ہیں۔"}],[2331,"ابومسہر کہتے ہیں سعید یعنی ابن عبدالعزیز کہتے ہیں «سره» کے معنی «أوله» کے ہیں۔ ابوداؤد کہتے ہیں: «سره» کے معنی کچھ لوگ «وسطه»کے بتاتے ہیں اور کچھ لوگ «آخره» کے۔","شاذ",{"u2":"جناب سعید بن عبدالعزیز بیان کرتے ہیں کہ «سره» کے معنی ” ابتدائے مہینہ “ ہیں۔ امام ابوداؤد رضی اللہ عنہ نے کہا: کچھ اہل لغت اس کا ترجمہ ” وسط “ اور کئی ” آخر مہینہ “ بھی کرتے ہیں۔","f2":"امام اوزاعی اور ابن عبدالعزیزی کے اقوال شاذ ہیں۔ (ضعیف سنن ابی داود) گویا سَرَر یا سر کے معنی وسط یا آخری ہی صحیح ہیں اور آخر سب سے زیادہ صحیح ہے۔ کیونکہ اس کے معنی پوشیدگی کے ہیں۔ اور چاند مہینے کے آخر میں ایک یا دو دن غائب (پوشیدہ) رہتا ہے۔ اس اعتبار سے اس کے معنی آخر راجح ہیں۔"}],[2332,"کریب کہتے ہیں کہ ام الفضل بنت حارث نے انہیں معاویہ رضی اللہ عنہ کے پاس شام بھیجا، میں نے (وہاں پہنچ کر) ان کی ضرورت پوری کی، میں ابھی شام ہی میں تھا کہ رمضان کا چاند نکل آیا، ہم نے جمعہ کی رات میں چاند دیکھا، پھر مہینے کے آخر میں مدینہ آ گیا تو ابن عباس رضی اللہ عنہما نے مجھ سے چاند کے متعلق پوچھا کہ تم نے چاند کب دیکھا؟ میں نے جواب دیا کہ جمعہ کی رات میں، فرمایا: تم نے خود دیکھا ہے؟ میں نے کہا: ہاں، اور لوگوں نے بھی دیکھا ہے، اور روزہ رکھا ہے، معاویہ نے بھی روزہ رکھا، ابن عباس رضی اللہ عنہما نے کہا: لیکن ہم نے سنیچر کی رات میں چاند دیکھا ہے لہٰذا ہم چاند نظر آنے تک روزہ رکھتے رہیں گے، یا تیس روزے پورے کریں گے، تو میں نے کہا کہ کیا معاویہ کی رؤیت اور ان کا روزہ کافی نہیں ہے؟ کہنے لگے: نہیں، اسی طرح رسول اللہ صلی اللہ علیہ وسلم نے ہمیں حکم دیا ہے۔","صحیح",{"u2":"جناب کریب کہتے ہیں کہ (سیدنا ابن عباس رضی اللہ عنہ کی والدہ) ام الفضل بنت حارث رضی اللہ عنہا ا نے مجھے شام میں سیدنا معاویہ رضی اللہ عنہ کے پاس بھیجا۔ چنانچہ میں شام آیا اور وہاں ان کا کام مکمل کیا، اور رمضان کا چاند نظر آ گیا جبکہ میں ابھی شام ہی میں تھا۔ ہم نے جمعہ کی رات کو چاند دیکھا۔ پھر مہینے کے آخر میں، میں مدینے واپس پہنچا تو سیدنا ابن عباس رضی اللہ عنہ نے مجھ سے حال احوال پوچھے اور چاند کا ذکر کیا کہ تم نے اسے کب دیکھا تھا؟ میں نے کہا: میں نے اسے جمعہ کی رات کو دیکھا تھا؟ انہوں نے کہا: کیا تم نے خود دیکھا تھا؟ میں نے کہا: ہاں، اور دوسرے لوگوں نے بھی دیکھا تھا اور پھر سب نے روزے رکھے اور معاویہ رضی اللہ عنہ نے بھی روزہ رکھا۔ انہوں نے کہا: مگر ہم نے اسے ہفتے کی رات کو دیکھا تھا اور ہم روزے رکھیں گے اور پورے تیس کریں گے (اپنی رؤیت کے مطابق) یا چاند دیکھ لیں۔ میں نے کہا: کیا آپ معاویہ رضی اللہ عنہ کے چاند دیکھنے اور روزے رکھنے پر کفایت نہیں کریں گے؟ انہوں نے کہا: نہیں، رسول اللہ صلی اللہ علیہ وسلم نے ہمیں ایسے ہی حکم دیا ہے۔","f2":"حضرت ابن عباس رضی اللہ عنہ کا مقصد یہ ہے کہ ہر علاقے والوں کے لیے ان کی اپنی رؤیت کا اعتبار ہے۔ امام شافعی رحمة اللہ علیہ اس میں مزید یوں فرماتے ہیں کہ اگر مختلف علاقوں کا مطلع ایک ہو تو ایک دوسرے کی رؤیت ان کے لیے معتبر ہو گی ورنہ نہیں۔ امام ابن تیمیہ رحمة اللہ علیہ کا بھی یہی مذہب ہے۔"}],[2333,"حسن بصری سے اس شخص کے بارے میں پوچھا گیا جو کسی شہر میں ہو اور اس نے دوشنبہ (پیر) کے دن کا روزہ رکھ لیا ہو اور دو آدمی اس بات کی گواہی دیں کہ انہوں نے اتوار کی رات چاند دیکھا ہے (اور اتوار کو روزہ رکھا ہے) تو انہوں نے کہا: وہ شخص اور اس شہر کے باشندے اس دن کا روزہ قضاء نہیں کریں گے، ہاں اگر معلوم ہو جائے کہ مسلم آبادی والے کسی شہر کے باشندوں نے سنیچر کا روزہ رکھا ہے تو انہیں بھی ایک روزے کی قضاء کرنی پڑے گی ۱؎۔\n§وضاحت\n۱؎ : یہ فتوی اس حدیث کے خلاف ہے جس میں ہے کہ : اللہ کے رسول صلی اللہ علیہ وسلم نے ایک آدمی کی گواہی پر ایک روزہ رکھنے کا حکم صادر فرمایا اور دو آمیوں کی گواہی پر عید کرنے کا حکم دیا ، یعنی: بات سچی گواہی پر منحصر ہے نہ کہ جم غفیر کے عمل پر۔","صحیح",{"u2":"حسن (بصری) سے مروی ہے کہ ایک شخص جو کسی شہر میں ہو اور اس نے سوموار کا روزہ رکھا ہو، پھر دو آدمی گواہی دیں کہ انہوں نے اتوار کی رات (ہفتے کی شام) کو چاند دیکھا ہے۔ تو حسن نے کہا: یہ آدمی اور اس کے شہر والے اس دن کا روزہ قضا نہ کریں الا یہ کہ انہیں بخوبی علم ہو کہ مسلمانوں کے شہروں میں سے کسی شہر والوں نے اتوار کا روزہ رکھا ہے، تب یہ اس کی قضاء کریں۔","f2":"سنن ابوداود کے بعض نسخوں میں حسن بصری کا یہ اثر نہیں ہے۔"}],[2334,"صلہ بن زفر کہتے ہیں کہ ہم اس دن میں جس دن کا روزہ مشکوک ہے عمار رضی اللہ عنہ کے پاس تھے، ان کے پاس ایک (بھنی ہوئی)بکری لائی گئی، تو لوگوں میں سے ایک آدمی (کھانے سے احتراز کرتے ہوئے) الگ ہٹ گیا اس پر عمار رضی اللہ عنہ نے کہا: جس نے ایسے (شک والے) دن کا روزہ رکھا اس نے ابوالقاسم صلی اللہ علیہ وسلم کی نافرمانی کی۔","صحیح",{"u2":"جناب صلہ بیان کرتے ہیں کہ ہم سیدنا عمار رضی اللہ عنہ کی خدمت میں حاضر تھے اور وہ دن مشکوک تھا (چاند ہونے کی خبر واضح نہ ہوئی تھی) تو بکری کا گوشت پیش کیا گیا۔ پس مجلس میں سے کچھ لوگ ایک طرف ہو گئے۔ سیدنا عمار رضی اللہ عنہ نے کہا: جس نے اس دن کا روزہ رکھا ہے اس نے ابوالقاسم صلی اللہ علیہ وسلم کی نافرمانی کی ہے۔","f2":"(1) شک کے دن سے مراد یہ ہے کہ نہ معلوم آج چاند ہوا ہے یا نہیں؟ (2) اس روایت کا مفہوم صحیح روایات سے ثابت ہے، اسی لیے بعض حضرات نے اس روایت کو صحیح کہا ہے۔"}],[2335,"ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"رمضان سے ایک دن یا دو دن پہلے روزہ نہ رکھو، ہاں اگر کوئی آدمی پہلے سے روزہ رکھتا آ رہا ہے تو وہ ان دنوں کا روزہ رکھے\"۔","صحیح",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ سے مروی ہے کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا ” رمضان سے ایک دو دن پہلے روزے مت رکھو مگر جو کوئی شخص کسی دن کا روزہ رکھتا رہا ہو تو وہ رکھ لے۔ “","f2":"(1) شعبان کو رمضان کے ساتھ ملانے کا مفہوم یہ ہے کہ شعبان میں روزے رکھے حتی کہ رمضان شروع ہو جائے۔ (2) شریعت کی حکمت یہ معلوم ہوتی ہے کہ عبادت اور عادت میں فرق کیا جانا چاہیے، اس لیے کہ اگر کسی نے یہ عادت بنائی ہو کہ وہ سوموار اور جمعرات کو مسنون روزے رکھتا ہو ی اتفاقا کوئی نذر مان لی یا کوئی قضا کا روزہ باقی ہو تو اس کے لیے رخصت ہے کہ رمضان شروع ہونے سے ایک دو دن پہلے روزہ رکھ لے۔"}],[2336,"ام المؤمنین ام سلمہ رضی اللہ عنہا سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم سال میں کسی مہینے کے مکمل روزے نہ رکھتے سوائے شعبان کے اسے رمضان سے ملا دیتے تھے ۱؎۔\n§وضاحت\n۱؎ : اور یہ صرف نبی اکرم صلی اللہ علیہ وسلم کے لئے خاص تھا، کیونکہ آپ صلی اللہ علیہ وسلم نے امت کو نصف شعبان کے بعد روزے سے منع فرمایا ہے، تاکہ رمضان کے لئے قوت حاصل ہو جائے۔","صحیح",{"u2":"ام المؤمنین سیدہ ام سلمہ رضی اللہ عنہا ا، نبی کریم صلی اللہ علیہ وسلم کے متعلق بیان کرتی ہیں کہ آپ صلی اللہ علیہ وسلم سال میں کسی مہینے کے پورے روزے نہ رکھتے تھے مگر شعبان میں، کہ اسے رمضان کے ساتھ ملا دیتے تھے۔","f2":"حضرت ام سلمہ رضی اللہ عنہا کا یہ بیان بطور مجاز ہے۔ جس کا مطلب کثرت ہے۔ جیسا کہ دیگر احادیث میں ہے کہ نبی صلی اللہ علیہ وسلم شعبان میں کثرت سے روزے رکھتے تھے۔ صحیح مسلم میں حضرت عائشہ رضی اللہ عنہا کی روایت ہے: (كان يصوم شعبان الا قليلا) (صحيح مسلم‘ الصيام‘ حديث:1156)"}],[2337,"عبدالعزیز بن محمد کہتے ہیں کہ عباد بن کثیر مدینہ آئے تو علاء کی مجلس کی طرف مڑے اور (جا کر) ان کا ہاتھ پکڑ کر انہیں کھڑا کیا پھر کہنے لگے: اے اللہ! یہ شخص اپنے والد سے اور وہ ابوہریرہ رضی اللہ عنہ سے روایت کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\"جب نصف شعبان ہو جائے تو روزے نہ رکھو\"، علاء نے کہا: اے اللہ! میرے والد نے یہ حدیث ابوہریرہ رضی اللہ عنہ کے واسطے سے مجھ سے بیان کی ہے اور انہوں نے نبی اکرم صلی اللہ علیہ وسلم سے روایت کی ہے۔ ابوداؤد کہتے ہیں: اسے ثوری، شبل بن علاء، ابو عمیس اور زہیر بن محمد نے علاء سے روایت کیا، نیز ابوداؤد نے کہا: عبدالرحمٰن (عبدالرحمٰن ابن مہدی) اس حدیث کو بیان نہیں کرتے تھے، میں نے احمد سے کہا: ایسا کیوں ہے؟ وہ بولے: کیونکہ انہیں یہ معلوم تھا کہ رسول اللہ صلی اللہ علیہ وسلم شعبان کو (روزہ رکھ کر) رمضان سے ملا دیتے تھے، نیز انہوں نے کہا: نبی اکرم صلی اللہ علیہ وسلم سے اس کے برخلاف مروی ہے۔ ابوداؤد کہتے ہیں: میرے نزدیک یہ اس کے خلاف نہیں ہے ۱؎ اسے علاء کے علاوہ کسی اور نے ان کے والد سے روایت نہیں کیا ہے۔\n§وضاحت\n۱؎ : اس لئے کہ وہ بات آپ صلی اللہ علیہ وسلم کے لئے خاص تھی ، اور یہ بات عام امت کے لئے ہے۔","صحیح",{"u2":"عباد بن کثیر مدینے آئے اور جناب علاء بن عبدالرحمٰن کی مجلس میں آ گئے۔ پس عباد نے علاء کا ہاتھ پکڑ کر انہیں کھڑا کر دیا پھر کہا: اے ا اللہ! یہ شخص اپنے باپ سے وہ سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” جب شعبان آدھا گزر جائے تو روزہ نہ رکھو۔ “ پھر علاء نے کہا: یا ا اللہ! میرے والد (عبدالرحمٰن) نے مجھے سیدنا ابوہریرہ رضی اللہ عنہ سے ‘ انہوں نے نبی کریم صلی اللہ علیہ وسلم سے یہی حدیث بیان کی۔ ¤ امام ابوداؤد رضی اللہ عنہ فرماتے ہیں کہ اس روایت کو ثوری ‘ سبل بن علاء ‘ ابوعمیس اور زبیر بن محمد بھی علاء سے بیان کرتے ہیں۔ ¤ امام ابوداؤد رضی اللہ عنہ کہتے ہیں عبدالرحمٰن (بن مہدی) یہ روایت بیان نہیں کیا کرتے تھے ‘ میں نے امام احمد سے پوچھا کیوں؟ تو انہوں نے کہا: کیونکہ ان کے پاس یہ حدیث تھی کہ ” نبی کریم صلی اللہ علیہ وسلم شعبان کو رمضان کے ساتھ ملا دیتے تھے۔ “ اور اس روایت میں اس کے خلاف مروی ہے۔ امام ابوداؤد رضی اللہ عنہ فرماتے ہیں میرے نزدیک اس میں کوئی مخالفت نہیں ہے۔ علاء کے علاوہ اسے اور کوئی روایت نہیں کرتا اور وہ بھی اپنے باپ سے روایت کرتا ہے۔","f2":"نصف شعبان کے بعد روزوں کی کراہت ایسے لوگوں کے لیے ہے جو ان دنوں کے روزوں کے عادی نہ ہوں۔ اگر عادت ہو تو رکھ لینے میں حرج نہیں، نیز نہی سے مقصد یہ ہے کہ رمضان میں کمزوری کا احساس نہ ہو۔"}],[2338,"ابو مالک اشجعی سے روایت ہے کہ ہم سے حسین بن حارث جدلی نے (جو جدیلہ قیس سے تعلق رکھتے ہیں) بیان کیا کہ امیر مکہ نے خطبہ دیا پھر کہا: رسول اللہ صلی اللہ علیہ وسلم نے ہم سے یہ عہد لیا کہ ہم چاند دیکھ کر حج ادا کریں، اگر ہم خود نہ دیکھ سکیں اور دو معتبر گواہ اس کی رویت کی گواہی دیں تو ان کی گواہی پر حج ادا کریں، میں نے حسین بن حارث سے پوچھا کہ امیر مکہ کون تھے؟ کہا کہ میں نہیں جانتا، اس کے بعد وہ پھر مجھ سے ملے اور کہنے لگے: وہ محمد بن حاطب کے بھائی حارث بن حاطب تھے پھر امیر نے کہا: تمہارے اندر ایک ایسے شخص موجود ہیں جو مجھ سے زیادہ اللہ اور اس کے رسول کی باتوں کو جانتے ہیں اور وہ اس حدیث کے گواہ ہیں، اور انہوں نے اپنے ہاتھ سے ایک شخص کی طرف اشارہ کیا۔ حسین کا بیان ہے کہ میں نے اپنے پاس بیٹھے ایک بزرگ سے دریافت کیا کہ یہ کون ہیں جن کی طرف امیر نے اشارہ کیا ہے؟ کہنے لگے: یہ عبداللہ بن عمر رضی اللہ عنہما ہیں اور امیر نے سچ ہی کہا ہے کہ وہ اللہ کو ان سے زیادہ جانتے ہیں، اس پر انہوں نے (ابن عمر رضی اللہ عنہما نے) کہا کہ ہمیں رسول اللہ صلی اللہ علیہ وسلم نے اسی کا حکم فرمایا ہے۔","صحیح",{"u2":"حسین بن حارث جدلی، قیس کے قبیلہ جدیلہ سے ہیں، بیان کرتے ہیں کہ امیر مکہ نے خطبہ دیا اور کہا: رسول اللہ صلی اللہ علیہ وسلم نے ہم سے عہد لیا کہ ہم چاند دیکھ کر حج کے ارکان ادا کریں۔ اگر ہم خود نہ دیکھ سکیں اور دو عادل گواہی دے دیں تو ہم ان کی گواہی پر حج کر لیں۔ (ابومالک کہتے ہیں) میں نے حسین بن حارث سے پوچھا امیر مکہ کون تھا؟ اس نے کہا مجھے معلوم نہیں۔ بعد میں وہ مجھے دوبارہ ملا تو بتایا کہ وہ (امیر) حارث بن حاطب تھے ‘ یعنی محمد بن حاطب کے بھائی۔ پھر امیر نے کہا: بلاشبہ تم میں وہ شخصیت موجود ہے جو ا اللہ اور اس کے رسول صلی اللہ علیہ وسلم کے متعلق مجھ سے زیادہ باخبر ہے ‘ اس بات کی شہادت اسی نے رسول اللہ صلی اللہ علیہ وسلم سے دی ہے اور اپنے ہاتھ سے ایک آدمی کی طرف اشارہ کیا۔ حسین نے بتایا، میں نے اپنے پہلو میں بیٹھے ہوئے ایک شخص سے پوچھا یہ آدمی کون ہے جس کی طرف امیر نے اشارہ کیا ہے؟ تو اس نے کہا: یہ سیدنا عبداللہ بن عمر رضی اللہ عنہ ہیں اور اس نے سچ کہا کہ یہ ا اللہ کے متعلق اس سے زیادہ جانتے تھے (احکام شریعت) تو سیدنا عبداللہ بن عمر رضی اللہ عنہ نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے ہمیں اسی بات کا حکم دیا ہے۔"}],[2339,"نبی اکرم صلی اللہ علیہ وسلم کے اصحاب میں سے ایک شخص سے روایت ہے، وہ کہتے ہیں رمضان کے آخری دن لوگوں میں (چاند کی رویت پر) اختلاف ہو گیا، تو دو اعرابی آئے اور انہوں نے رسول اللہ صلی اللہ علیہ وسلم کے سامنے اللہ کی قسم کھا کر گواہی دی کہ انہوں نے کل شام میں چاند دیکھا ہے، چنانچہ رسول اللہ صلی اللہ علیہ وسلم نے لوگوں کو افطار کرنے اور عید گاہ چلنے کا حکم دایا۔","صحیح",{"u2":"ربعی بن حراش ‘ اصحاب نبی کریم صلی اللہ علیہ وسلم میں سے کسی سے روایت کرتے ہیں کہ رمضان کے آخری دن کے متعلق لوگوں کا اختلاف ہو گیا۔ تو دو اعرابی آئے اور انہوں نے نبی کریم صلی اللہ علیہ وسلم کے سامنے ا اللہ کی گواہی دی (قسمیں اٹھائیں) کہ انہوں نے کل شام کو چاند دیکھا ہے۔ تو رسول اللہ صلی اللہ علیہ وسلم نے لوگوں کو حکم دیا کہ روزہ افطار کر لیں۔ ¤ اور خلف بن ہشام کی روایت میں مزید یہ ہے کہ آپ نے فرمایا ” اگلے دن صبح کو (عید پڑھنے کے لیے) عید گاہ جائیں۔ “","f2":"رمضان المبارک کا چاند ہو جانے کا یقین یا تو شعبان کے تیس دن پورے ہو جانے پر ہے یا لوگوں کی گواہی پر کہ انہوں نے چاند دیکھا ہے، خواہ کوئی ایک عادل مسلمان ہی ہے، جیسے کہ اگلے باب کی احادیث میں آ رہا ہے۔ اسی طرح انتہائے رمضان کے موقع پر بھی۔ تاہم عام فقہاد و عادل مسلمانوں کی رؤیت کو ضروری سمجھتے ہیں جبکہ ابوثور، ابوبکر بن منذر، اہل ظاہر اور امام حسن کی امام ابوحنیفہ رحمة اللہ علیہ سے ایک روایت میں ایک مسلمان کی رؤیت کو بھی حجت سمجھا گیا ہے۔ علامہ شوکانی رحمة اللہ علیہ کی ترجیح بھی یہی معلوم ہوتی ہے کہ روزے چھوڑنے کے موقع پر دو آدمیوں کی گواہی کسی معیاری دلیل سے ثابت نہیں۔ مالی معاملات ہی ایسے ہیں جہاں دو گواہ لازم ہوتے ہیں۔ مگر روزوں کے متعلق صریح حکم ہے کہ چاند دیکھ کررکھو اور چاند دیکھ کر افطار کرو۔ اور عبادت میں خبر واحد معتبر ہوتی ہے۔ (فقه السنة للسيد سابق‘ بم يثبت الشهر‘ ونيل الاوطار‘ باب ما يثبت به الصوم والفطر من الشهور) نیز عید کا چاند ہونے کی خبر اگر دیر سے ملے اور عید کے لیے جمع ہونا ممکن نہ ہو تو اگلے دن عید کی نماز پڑھ لی جائے۔"}],[2340,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم کے پاس ایک اعرابی آیا اور اس نے عرض کیا: میں نے چاند دیکھا ہے، (راوی حسن نے اپنی روایت میں کہا ہے یعنی رمضان کا) تو آپ صلی اللہ علیہ وسلم نے اس اعرابی سے پوچھا: \"کیا تو اس بات کی گواہی دیتا ہے کہ اللہ کے سوا کوئی معبود برحق نہیں؟\" اس نے جواب دیا: ہاں، پھر آپ صلی اللہ علیہ وسلم نے پوچھا: \"کیا اس بات کی بھی گواہی دیتا ہے کہ محمد اللہ کے رسول ہیں؟\" اس نے جواب دیا: ہاں، آپ صلی اللہ علیہ وسلم نے فرمایا: \"بلال! لوگوں میں اعلان کر دو کہ وہ کل روزہ رکھیں\"۔","ضعیف",{"u2":"سیدنا ابن عباس رضی اللہ عنہ بیان کرتے ہیں کہ ایک اعرابی نبی کریم صلی اللہ علیہ وسلم کی خدمت میں آیا اور کہا: میں نے چاند دیکھا ہے۔ حسن بن علی نے اپنی حدیث میں صراحت کرتے ہوئے کہا کہ مراد رمضان کا چاند۔ نبی کریم صلی اللہ علیہ وسلم نے فرمایا ” کیا تو «لا إله إلا الله» کی گواہی دیتا ہے؟ “ اس نے کہا: ہاں۔ آپ صلی اللہ علیہ وسلم نے پوچھا: کیا تو گواہی دیتا ہے کہ محمد اللہ کے رسول ہیں؟ اس نے کہا: ہاں۔ آپ صلی اللہ علیہ وسلم نے فرمایا ” بلال! لوگوں میں اعلان کر دو کہ صبح روزہ رکھیں۔ “"}],[2341,"عکرمہ کہتے ہیں کہ ایک بار لوگوں کو رمضان کے چاند (کی روئیت) سے متعلق شک ہوا اور انہوں نے یہ ارادہ کر لیا کہ نہ تو تراویح پڑھیں گے اور نہ روزے رکھیں گے، اتنے میں مقام حرہ سے ایک اعرابی آ گیا اور اس نے چاند دیکھنے کی گواہی دی چنانچہ اسے نبی اکرم صلی اللہ علیہ وسلم کی خدمت میں لے جایا گیا، آپ نے اس سے سوال کیا: \"کیا تو اس بات کی گواہی دیتا ہے کہ اللہ کے سوا کوئی معبود برحق نہیں، اور یہ کہ میں اللہ کا رسول ہیں؟\" اس نے کہا: ہاں، اور چاند دیکھنے کی گواہی بھی دی چنانچہ آپ صلی اللہ علیہ وسلم نے بلال رضی اللہ عنہ کو حکم دیا کہ وہ لوگوں میں منادی کر دیں کہ لوگ تراویح پڑھیں اور روزہ رکھیں۔ ابوداؤد کہتے ہیں: اسے ایک جماعت نے سماک سے اور انہوں نے عکرمہ سے مرسلاً روایت کیا ہے، اور سوائے حماد بن سلمہ کے کسی اور نے تراویح پڑھنے کا ذکر نہیں کیا ہے۔","ضعیف",{"u2":"عکرمہ بیان کرتے ہیں کہ صحابہ کرام رضی اللہ عنہم م کو ایک بار رمضان کے چاند میں شک ہو گیا۔ پس انہوں نے ارادہ کیا کہ نہ قیام کریں اور نہ روزہ رکھیں۔ تو حرہ کی طرف سے ایک اعرابی آیا۔ اس نے گواہی دی کہ اس نے چاند دیکھا ہے۔ اسے نبی کریم صلی اللہ علیہ وسلم کی خدمت میں پیش کیا گیا ‘ آپ نے فرمایا ” کیا تو «لا إله إلا الله محمد رسول الله» کی گواہی دیتا ہے؟ “ اس نے کہا: ہاں اور شہادت دی کہ اس نے چاند دیکھا ہے۔ تب آپ صلی اللہ علیہ وسلم نے بلال کو حکم دیا کہ لوگوں میں اعلان کر دو کہ رات کو قیام کریں اور (صبح کو) روزہ رکھیں۔ ¤ امام ابوداؤد رضی اللہ عنہ فرماتے ہیں کہ اس حدیث کو ایک جماعت نے بواسطہ سماک ‘ عکرمہ سے مرسل روایت کیا ہے۔ اور قیام کا ذکر حماد بن سلمہ کے علاوہ کسی نے نہیں کیا۔"}],[2342,"عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ لوگوں نے چاند دیکھنے کی کوشش کی (لیکن انہیں نظر نہ آیا) اور میں نے رسول اللہ صلی اللہ علیہ وسلم کو خبر دی کہ میں نے اسے دیکھا ہے، چنانچہ آپ نے خود بھی روزہ رکھا اور لوگوں کو بھی روزہ رکھنے کا حکم فرمایا۔","صحیح",{"u2":"سیدنا عبداللہ بن عمر رضی اللہ عنہ کا بیان ہے کہ لوگوں نے چاند دیکھنے کی کوشش کی۔ پس میں نے رسول اللہ صلی اللہ علیہ وسلم کو خبر دی کہ میں نے دیکھ لیا ہے۔ تو آپ صلی اللہ علیہ وسلم نے روزہ رکھا اور لوگوں کو روزہ رکھنے کو حکم فرمایا۔","f2":"جب کسی مسلمان پر کوئی واضح جرح ثابت نہ ہو تو اسے عادل شمار کیا جائے گا۔ اور رمضان کا چاند ہونے کے سلسلے میں کئی فقہا ایک عادل مسلمان کی گواہی کو کافی سمجھتے ہیں۔ اس حدیث سے بھی اس کی تائید ہوتی ہے۔ مذکورہ دونوں حدیثین (2340-2341) سندا ضعیف ہیں۔ تاہم اس صحیح حدیث میں بھی یہی بات بیان کی گئی ہے۔"}],[2343,"عمرو بن العاص رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"ہمارے اور اہل کتاب کے روزے میں سحری کھانے کا فرق ہے\"۔","صحیح",{"u2":"سیدنا عمرو بن العاص رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” ہمارے اور اہل کتاب کے روزے میں فرق ‘ سحری کے کھانے کا ہے۔ “","f2":"مسلمان کی زندگی کے تمام امور... عبادات و معاملات... نیت صالحہ پر مبنی ہونے چاہئیں۔ روزے میں صبح کا کھانا محض اس فکر سے نہیں کھانا چاہیے کہ سارا دن بھوک اور پیاس برداشت کرنی ہے۔ بلکہ اس نیت سے کھانا چاہیے کہ اللہ کی اطاعت اور رسول اللہ صلی اللہ علیہ وسلم کی سنت ہے، نیز اہل کتاب سے امتیاز بھی ہے۔ اور یہی شرح ہے اس معروف حدیث کی یعنی (انما الاعمال بالنيات) نیت صالحہ و طیبہ سے عمل کے اجر میں بہت اضافہ ہو جاتا ہے۔ اور شریعت کا اہم مطالبہ بھی ہے کہ مسلمان ملی طور پر دوسری امتون سے اپنی امتوں سے اپنی عبادات میں بھی منفرد ہوں اور عادات میں بھی۔"}],[2344,"عرباض بن ساریہ رضی اللہ عنہ کہتے ہیں کہ مجھے رسول اللہ صلی اللہ علیہ وسلم نے رمضان میں سحری کھانے کے لیے بلایا اور یوں کہا:\"بابرکت «غداء» پر آؤ\"۔","حسن لغیرہ",{"u2":"سیدنا عرباض بن ساریہ رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے مجھے رمضان میں سحری کے لیے بلایا اور فرمایا ” آؤ! مبارک کھانا «غداء» کھا لو۔ “","f2":"کھانا انسانی فطرت کا ایک لازمہ ہے مگر شریعت کی اتباع میں سحری کا کھانا مبارک کھانا ہوتا ہے۔ چونکہ نبی صلی اللہ علیہ وسلم ناطق وحی ہیں، اپنی مرضی سے کچھ نہیں کہتے، اس لیے اگر کسی کی طبیعت میں سحری کے لیے چاہت نہ بھی ہو تو ایک دو لقمے یا کجھور یا کسی مشروب کے چند گھونٹ ضرور لے لینے چاہئیں تاکہ اس برکت سے حصہ مل جائے۔"}],[2345,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"کھجور مومن کی کتنی اچھی سحری ہے\"۔","صحیح",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا ” کھجور مومن کی بہترین سحری ہے۔ “","f2":"کجھور سر تا پا ایک مبارک درخت ہے۔ اور اس کا پھل سحری اور افطاری میں استعمال کرنا مستحب ہے۔"}],[2346,"سوادہ قشیری کہتے ہیں کہ سمرہ بن جندب رضی اللہ عنہ خطبہ دے رہے تھے اور کہہ رہے تھے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\"تمہیں سحری کھانے سے بلال کی اذان ہرگز نہ روکے اور نہ آسمان کے کنارے کی سفیدی (صبح کاذب) ہی باز رکھے، جو اس طرح (لمبائی میں) ظاہر ہوتی ہے یہاں تک کہ وہ پھیل جائے\"۔","صحیح",{"u2":"سیدنا سمرہ بن جندب رضی اللہ عنہ نے خطبہ دیا اور بیان کیا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” بلال کی اذان تمہیں تمہاری سحری سے ہرگز نہ روکے اور نہ افق کی سفیدی (جو کہ سیدھی اوپر کو چڑھتی ہے) حتیٰ کہ اطراف میں پھیلنے لگے۔ “","f2":"فجر کی دو قسمیں ہیں: فجر کاذب اور فجر صادق۔ فجر کاذب میں سحری کھائی جاتی ہے اور فجر صادق شروع ہوتے ہی سحری کا وقت ختم ہو جاتا ہے۔ حضرت بلال رضی اللہ عنہ فجر کاذب میں لوگوں کو متنبہ کرنے کے لیے اذان دیا کرتے تھے۔ فجر کاذب میں پہلے سفیدی (روشنی) سیدھی آسمان کو اٹھتی ہے، پھر جلد ہی دوبارہ سفیدی نکل کر اِطراف افق میں پھیل جاتی ہے اور یہی فجر صادق ہوتی ہے۔"}],[2347,"عبداللہ بن مسعود رضی اللہ عنہ کہتے ہیں کہ رسول صلی اللہ علیہ وسلم نے فرمایا: \"تم میں سے کسی کو بلال کی اذان اس کی سحری سے ہرگز نہ روکے، کیونکہ وہ اذان یا ندا دیتے ہیں تاکہ تم میں قیام کرنے (تہجد پڑھنے) والا تہجد پڑھنا بند کر دے، اور سونے والا جاگ جائے، فجر کا وقت اس طرح نہیں ہے\"۔ مسدد کہتے ہیں: راوی یحیی نے اپنی دونوں ہتھیلیاں اکٹھی کر کے اور دونوں شہادت کی انگلیاں دراز کر کے اشارے سے سمجھایا یعنی اوپر کو چڑھنے والی روشنی صبح صادق نہیں بلکہ صبح کاذب ہے، یہاں تک اس طرح ہو جائے (یعنی روشنی لمبائی میں پھیل جائے) ۔","صحیح",{"u2":"سیدنا عبداللہ بن مسعود رضی اللہ عنہ کا بیان ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” بلال کی اذان تم میں سے کسی کو سحری کھانے سے ہرگز نہ روکے۔ بلاشبہ وہ اذان کہتا ہے، یا کہا، ندا دیتا ہے۔ تاکہ تمہارا نماز پڑھنے والا رک جائے (تہجد سے) اور سونے والا جاگ جائے۔ اور فجر (فجر صادق) وہ نہیں جو اس طرح سے ظاہر ہو۔ مسدد نے کہا: راوی حدیث یحییٰ نے اپنی دونوں ہتھیلیاں ملا کر ان کو اونچا کر کے دکھلایا (جو اونچی اور لمبی روشنی اول وقت ہوتی ہے وہ صبح نہیں) آپ نے فرمایا ” جب تک اس طرح ظاہر نہ ہو۔ “ اور یحییٰ نے اپنی شہادت کی دونوں انگلیاں اطراف میں پھیلا کر اشارے سے سمجھایا۔"}],[2348,"طلق رضی اللہ عنہ سے کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"کھاؤ پیو، اور اوپر کو چڑھنے والی روشنی تمہیں کھانے پینے سے قطعاً نہ روکے اس وقت تک کھاؤ، پیو جب تک کہ سرخی چوڑائی میں نہ پھیل جائے یعنی صبح صادق نہ ہو جائے\"۔","حسن صحیح",{"u2":"قیس بن طلق اپنے والد سے بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” (رات کو) کھاؤ اور پیو، اوپر چڑھنے والی سفیدی تمہیں اس سے نہ روکے، حتیٰ کہ افق کے اطراف میں سرخی پھیلنی شروع ہو جائے۔ “ امام ابوداؤد رضی اللہ عنہ فرماتے ہیں: اس روایت میں اہل یمامہ منفرد ہیں۔","f2":"صحیح بات یہ ہے کہ اطراف میں سفیدی پھیلنے لگے۔ تاہم بعض دفعہ موسم ابر آلود ہو، پھر سرخی سی بھی پھیلتی ہوئی نظر آتی ہے، لیکن عام حالات میں سفیدی ہی پھیلتی ہے، نہ کہ سرخی۔"}],[2349,"عدی بن حاتم رضی اللہ عنہ کہتے ہیں کہ جب آیت کریمہ «حتى يتبين لكم الخيط الأبيض من الخيط الأسود» \"یہاں تک کہ صبح کا سفید دھاگا سیاہ دھاگے سے ظاہر ہو جائے\" (سورۃ البقرہ: ۱۸۷) نازل ہوئی تو میں نے ایک سفید اور ایک کالی رسی لے کر اپنے تکیے کے نیچے (صبح صادق جاننے کی غرض سے) رکھ لی، میں دیکھتا رہا لیکن پتہ نہ چل سکا، میں نے اس کا ذکر رسول اللہ صلی اللہ علیہ وسلم سے کیا تو آپ ہنس پڑے اور کہنے لگے، \"تمہارا تکیہ تو بڑا لمبا چوڑا ہے، اس سے مراد رات اور دن ہے\"۔ عثمان کی روایت میں ہے: \"اس سے مراد رات کی سیاہی اور دن کی سفیدی ہے\"۔","صحیح",{"u2":"سیدنا عدی بن حاتم رضی اللہ عنہ کا بیان ہے کہ جب یہ آیت کریمہ نازل ہوئی «حتى يتبين لكم الخيط الأبيض من الخيط الأسود» ” (تم کھاتے پیتے رہو) یہاں تک کہ صبح کا سفید دھاگہ سیاہ دھاگے سے نمایاں ہو جائے۔ “ تو میں نے دو رسیاں لے لیں ‘ ایک سفید اور دوسری سیاہ اور انہیں اپنے تکیے کے نیچے رکھ لیا۔ میں انہیں دیکھتا رہا مگر وہ میرے لیے نمایاں اور واضح نہ ہوئیں۔ میں نے یہ بات رسول اللہ صلی اللہ علیہ وسلم سے ذکر کی تو آپ صلی اللہ علیہ وسلم ہنسے اور فرمایا ” تیرا تکیہ تو بہت لمبا چوڑا ہے۔ اس سے مراد تو رات اور دن ہے “ عثمان کے الفاظ یہ ہیں ” اس سے مراد تو رات کی سیاہی اور دن کی سفیدی ہے۔ “","f2":"اس سے معلوم ہوا کہ فہم قرآن کے لیے محج الفاظ کا ترجمہ یا لغوی مفہوم کافی نہیں بلکہ عربی ادب کی فصاحت و بلاغت کے ساتھ ساتھ شارع علیہ السلام کی تشریحات (احادیث) کو مدنظر رکھنا بھی ضروری ہے۔"}],[2350,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"تم میں سے کوئی جب صبح کی اذان سنے اور (کھانے پینے کا)برتن اس کے ہاتھ میں ہو تو اسے اپنی ضرورت پوری کئے بغیر نہ رکھے\"۔","حسن صحیح",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ نے بیان کیا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” تم میں سے جب کوئی اذان (فجر) سنے اور برتن اس کے ہاتھ میں ہو تو اسے رکھے نہیں بلکہ اپنی ضرورت پوری کر لے۔ “","f2":"سحری کا وقت تنگ ہو رہا ہو اور اذان فجر اپنے وقت صبح پر شروع ہو جائے تو اجازت ہے کہ انسان پانی پی لے اور دو چار لقمے لے لے، مگر چائے کی طرح کے مشروب کی چسکیاں لینا درست نہیں ہو گا۔"}],[2351,"عمر رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"جب ادھر سے رات آ جائے اور ادھر سے دن چلا جائے اور سورج غروب ہو جائے تو روزہ افطار کرنے کا وقت ہو گیا\"۔","صحیح",{"u2":"جناب عاصم اپنے والد سیدنا عمر رضی اللہ عنہ سے بیان کرتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا ” جب ادھر سے رات آ جائے (مشرق کی جانب سے) اور ادھر سے دن چلا جائے (مغرب سے)۔ “ مسدد نے مزید کہا: ” اور سورج غروب ہو جائے تو روزے دار کے لیے افطار کا وقت ہو گیا۔ “"}],[2352,"سلیمان شیبانی کہتے ہیں کہ میں نے عبداللہ بن ابی اوفی رضی اللہ عنہ کو کہتے سنا کہ ہم رسول اللہ صلی اللہ علیہ وسلم کے ساتھ چلے آپ روزے سے تھے، جب سورج غروب ہو گیا تو آپ صلی اللہ علیہ وسلم نے فرمایا: \"بلال! (سواری سے) اترو، اور ہمارے لیے ستو گھولو\"، بلال رضی اللہ عنہ نے کہا: اللہ کے رسول! اگر اور شام ہو جانے دیں تو بہتر ہے، آپ صلی اللہ علیہ وسلم نے فرمایا: \"اترو، اور ہمارے لیے ستو گھولو\"، بلال رضی اللہ عنہ نے پھر کہا: اللہ کے رسول! ابھی تو دن ہے، آپ صلی اللہ علیہ وسلم نے فرمایا: \"اترو، اور ہمارے لیے ستو گھولو\"، چنانچہ وہ اترے اور ستو گھولا، آپ صلی اللہ علیہ وسلم نے اسے نوش فرمایا پھر فرمایا: \"جب تم دیکھ لو کہ رات ادھر سے آ گئی تو روزے کے افطار کا وقت ہو گیا\"، اور آپ صلی اللہ علیہ وسلم نے اپنی انگلی سے مشرق کی جانب اشارہ فرمایا۔","صحیح",{"u2":"سیدنا عبداللہ بن ابی اوفی رضی اللہ عنہ بیان کرتے ہیں کہ (ایک سفر میں) ہم رسول اللہ صلی اللہ علیہ وسلم کے ساتھ گئے جبکہ آپ روزے سے تھے۔ جب سورج غروب ہو گیا تو آپ نے فرمایا ” اے بلال! اترو اور ہمارے لیے ستو گھولو۔ “ انہوں نے کہا: اے ا اللہ کے رسول! ذرا شام ہو لینے دیجئیے۔ آپ نے فرمایا ” اترو اور ہمارے لیے ستو گھولو۔ “ انہوں نے کہا: اے ا اللہ کے رسول! ابھی تو دن ہے۔ آپ نے فرمایا اترو اور ہمارے لیے ستو گھولو۔ “ چنانچہ بلال اترے ‘ ستو گھولا اور پھر آپ نے نوش کیا اور فرمایا ” جب دیکھو کہ ادھر سے رات ہو گئی ہے تو بلاشبہ روزے دار کے لیے افطار کا وقت ہو گیا۔ “ اور آپ صلی اللہ علیہ وسلم نے اپنی انگلی سے مشرق کی طرف اشارہ فرمایا۔","f2":"(1) سورج غروب ہوتے ہی افطار کا وقت ہو جاتا ہے۔ بعد از غروب انتظار یا احتیاط کے کوئی معنی نہیں۔ حضرت بلال رضی اللہ عنہ کا تعمیل ارشاد نبوی میں تردد فضا میں سفیدی وغیرہ کی وجہ سے تھا اور وہ سمجھ رہے تھے کہ سورج شاید کسی پہاڑ وغیرہ کی اوٹ میں ہے۔ حالانکہ فی الواقع سورج غروب ہو چکا تھا جیسا کہ راوی حدیث نے بیان کیا۔ (2) اس حدیث سے یہ استدلال بھی کیا گیا ہے کہ بعض اوقات ظاہر امور کی وضاحت کروالینے میں کوئی حرج نہیں ہوتا، تاکہ امکانی شبہے کا ازالہ ہو جائے۔ (3) نیز صاحب علم کو یاد دلانا کوئی معیوب بات نہیں نہ یہ سوء ادبی ہے۔"}],[2353,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"دین برابر غالب رہے گا جب تک کہ لوگ افطار میں جلدی کرتے رہیں گے، کیونکہ یہود و نصاری اس میں تاخیر کرتے ہیں\"۔","حسن",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ نبی کریم صلی اللہ علیہ وسلم سے نقل کرتے ہیں کہ آپ صلی اللہ علیہ وسلم نے فرمایا ” دین اس وقت تک غالب رہے گا جب تک لوگ افطار کرنے میں جلدی کرتے رہیں گے کیونکہ یہود و نصاریٰ تاخیر سے افطار کرتے ہیں۔ “","f2":"(1) اس فرمان میں افطار کے لیے کھانے پینے کی حرص کا بیان نہیں بلکہ یہ ترغیب و تشویق ہے کہ اللہ کے حکم کی تعمیل اور سنت رسول صلی اللہ علیہ وسلم پر عمل میں سبقت کی جائے۔ اور یہی بات دین کے غالب ہونے کی علامت ہے کہ مخالفین اسلام اور دین بیزار لوگوں کے مقابلے میں دین کے چھوٹے بڑے تمام احکام پر مِن و عَن عمل کر کے اپنے آپ کو نمایاں رکھا جائے۔ (2) افطار اور نماز مغرب میں تاخیر کرنا اور خوامخواہ وہم میں مبتلا ہونا کہ سورج شاید ابھی غروب نہیں ہوا، ابھی غروب نہیں ہوا، مکروہ ہے۔"}],[2354,"ابوعطیہ کہتے ہیں کہ میں اور مسروق دونوں ام المؤمنین عائشہ رضی اللہ عنہا کی خدمت میں حاضر ہوئے، ہم نے کہا: ام المؤمنین! محمد صلی اللہ علیہ وسلم کے اصحاب میں سے دو آدمی ہیں ان میں ایک افطار بھی جلدی کرتا ہے اور نماز بھی جلدی پڑھتا ہے، اور دوسرا ان دونوں چیزوں میں تاخیر کرتا ہے، (بتائیے ان میں کون درستگی پر ہے؟) ام المؤمنین عائشہ رضی اللہ عنہا نے پوچھا: ان دونوں میں افطار اور نماز میں جلدی کون کرتا ہے؟ ہم نے کہا: وہ عبداللہ ہیں، انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم ایسا ہی کرتے تھے۔","صحیح",{"u2":"جناب ابوعطیہ (مالک بن عامر) سے مروی ہے، کہتے ہیں کہ میں اور مسروق ام المؤمنین سیدہ عائشہ رضی اللہ عنہا ا کی خدمت میں حاضر ہوئے۔ ہم نے کہا: اے ام المؤمنین! رسول اللہ صلی اللہ علیہ وسلم کے اصحاب میں سے دو حضرات کا عمل کچھ اس طرح ہے کہ ان میں سے ایک افطار کرنے اور نماز (مغرب) پڑھنے میں جلدی کرتا ہے اور دوسرا افطار اور نماز میں (قدرے) تاخیر کرتا ہے۔ انہوں نے پوچھا افطار اور نماز میں جلدی کون کرتا ہے؟ ہم نے کہا: وہ عبداللہ (عبداللہ بن مسعود) رضی اللہ عنہ ہیں۔ انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم بھی ایسے ہی کیا کرتے تھے۔","f2":"(19 خیر القرون میں صحابہ کرام رضی اللہ عنھم کے عمل کو بھی رسول اللہ صلی اللہ علیہ وسلم کے قول و فعل کی کسوٹی پر جانچا جاتا تھا، کیونکہ حجت مطلقہ رسول اللہ صلی اللہ علیہ وسلم کی ذات مبارکہ ہے۔ (2) افطار اور نماز مغرب کی ادائیگی اول وقت میں کرنا مشروع و مسنون ہے۔ (3) قدرے تاخیر کرنے والے صحابی حضرت ابوموسیٰ اشعری رضی اللہ عنہ شاید احتیاط کے خیال سے تاخیر کرتے تھے، لیکن اب اوقات کے کیلنڈروں کے بعد احتیاط کے طور پر تاخیر کا کوئی جواز نہیں ہے۔"}],[2355,"سلمان بن عامر رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جب تم میں سے کوئی روزے سے ہو تو اسے کھجور ۱؎سے روزہ افطار کرنا چاہیئے اگر کھجور نہ پائے تو پانی سے کر لے اس لیے کہ وہ پاکیزہ چیز ہے\"۔\n§وضاحت\n۱؎ : اس سے نگاہ کو طاقت ملتی ہے اور روزے سے پیدا ہونے والی نقاہت دور ہوتی ہے۔","ضعیف",{"u2":"جناب سلمان بن عامر رضی اللہ عنہ (یہ رباب کے چچا ہیں) بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” جب تم میں سے کسی نے روزہ رکھا ہو تو چاہیئے کہ کھجور سے افطار کرے۔ اگر کھجور نہ پائے تو پانی سے افطار کرے ‘ بلاشبہ پانی پاک کرنے والا ہے۔ “","f2":"(1) یہ امر ارشاد و ترغیب ہے نہ کہ امر وجوب۔ اس لیے کسی بھی طعام و مشروب سے روزہ افطار کیا جا سکتا ہے۔ (2) مسلمانوں کو چاہیے کہ کجھور جیسے مبارک پھل کو اپنے دسترخوان کا جزو بنانے کا اہتمام کریں۔ یہ نعمت لذت و شیرینی آمیز پھل ہی نہیں، بلکہ طعام کا قائم مقام بھی ہے۔ تہذیب مغرب نے سیب کو بہت شہرت دی ہے جو یقینا اللہ کی عظیم پاکیزہ نعمت ہے مگر رسول اللہ صلی اللہ علیہ وسلم نے کجھور کو جو فضیلت دی ہے وہ کسی اور پھل کو حاصل نہیں، اسی لیے چاہیے کہ اس کی کاشت بھی بڑھائی جائے۔ (3) مسلمان جہاں کھانے پینے اور پہننے کی ظاہری سنتوں کا اہتمام کرتے ہیں، وہاں انہیں چاہیے کہ عقیدہ و عمل کے معنوی امور کا اس سے بڑھ کر اہتمام کریں۔ (34) اس حدیث کی اسنادی مباحث کے لیے دیکھئے، ارواء الغلیل، حدیث:922۔"}],[2356,"انس بن مالک رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نماز (مغرب) پڑھنے سے پہلے چند تازہ کھجوروں سے روزہ افطار کرتے تھے، اگر تازہ کھجوریں نہ ملتیں تو خشک کھجوروں سے افطار کر لیتے اور اگر خشک کھجوریں بھی نہ مل پاتیں تو چند گھونٹ پانی نوش فرما لیتے۔","حسن صحیح",{"u2":"سیدنا انس بن مالک رضی اللہ عنہ کا بیان ہے کہ رسول اللہ صلی اللہ علیہ وسلم نماز سے پہلے تازہ کھجوروں سے روزہ افطار فرماتے ‘ اگر تازہ کھجوریں نہ ہوتیں ‘ تو خشک کھجور تناول فر لیتے ‘ یہ بھی نہ ہوتیں ‘ تو پانی کے چند گھونٹ پی لیا کرتے تھے۔"}],[2357,"مروان بن سالم مقفع کہتے ہیں کہ میں نے عبداللہ بن عمر رضی اللہ عنہما کو دیکھا، وہ اپنی داڑھی کو مٹھی میں پکڑتے اور جو مٹھی سے زائد ہوتی اسے کاٹ دیتے، اور کہتے کہ رسول اللہ صلی اللہ علیہ وسلم جب افطار کرتے تو یہ دعا پڑھتے: «ذهب الظمأ وابتلت العروق وثبت الأجر إن شاء الله» \"پیاس ختم ہو گئی، رگیں تر ہو گئیں، اور اگر اللہ نے چاہا تو ثواب مل گیا\"۔","حسن",{"u2":"مروان بن سالم مقفع کہتے ہیں کہ میں نے سیدنا ابن عمر رضی اللہ عنہ کو دیکھا کہ وہ داڑھی کو اپنی مٹھی میں لیتے اور اس سے جو بڑھی ہوئی ہوتی اسے کاٹ ڈالتے۔ اور بیان کیا کہ رسول اللہ صلی اللہ علیہ وسلم جب روزہ افطار کرتے تو یہ دعا پڑھتے تھے «ذهب الظمأ وابتلت العروق وثبت الأجر إن شاء الله» ” پیاس بجھ گئی ‘ رگیں تر ہو گئیں اور ا اللہ نے چاہا تو اجر بھی ثابت ہو گیا۔ “","f2":"(1) رسول اللہ صلی اللہ علیہ وسلم کے عمل مبارک سے انسان کی زندگی کے تمام چھوٹے بڑے امور میں اللہ کا ذکر اور دعائیں منقول ہیں۔ ان کو اپنے عمل کا حصہ بنا لینے سے بندہ (ٱذْكُرُ‌وا۟ ٱللَّهَ ذِكْرً‌ۭا كَثِيرً‌ۭا) (الاحزاب: 41) اللہ کا بہت زیادہ ذکر کیا کرو۔ کا مِصداق بن جاتا ہے، لہذا خود ساختہ دعاؤں سے بچنا چاہیے۔ روزہ افطار کرنے کی دعائیں اس باب میں آ گئی ہیں۔ قبولیت کے اس وقت میں انسان اپنی تمام طرح کی حاجات اللہ کے حضور پیش کرے تو سعادت ہے۔ (2) حضرت عبداللہ بن عمر رضی اللہ عنہ کا قبضہ (مٹھی بھر) سے زائد داڑھی کا کاٹنا، رسول اللہ صلی اللہ علیہ وسلم کے قول و فعل سے مؤید نہیں۔ یہ ان کا اپنا ذاتی فعل ہے جو حدیث رسول کے مقابلے میں حجت نہیں۔ رسول اللہ صلی اللہ علیہ وسلم نے صرف (اعفاء اللحية) کا حکم نہیں دیا بلکہ اس کے ساتھ مخالفت مجوس کا حکم بھی دیا تھا۔ جبکہ اس وقت کے مجوسی داڑھیاں چھوٹی کراتے تھے ان میں منڈوانے کا رواج عام نہ تھا، جیسا کہ اس بات کو اکثر محدثین نے بیان کیا ہے۔ صاحب تحفة الاحوذی اس مسئلہ کی بابت لکھتے ہیں کہ بعض لوگ ابن عمر اور ابوہریرہ رضی اللہ عنھم کے آثار سے استدلال کرتے ہیں کہ قبضہ سے اوپر زائد داڑھی کاٹ دینی چاہیے یہ استدلال ضعیف اور کمزور ہے چونکہ رسول اللہ صلی اللہ علیہ وسلم سے نقل شدہ مرفوع احادیث ان کی نفی کرتی ہیں۔ ان میں مطلق چھوڑنے کا حکم ہے۔ پس صریح اور مرفوع احادیث کے مقابلے میں ان آثار اور اقوال دے دلیل اخذ کرنا صحیح نہیں۔ پس سلامتی والا طریقہ انہی لوگوں کا ہے جو کہتے ہیں کہ ظاہر احادیث پر عمل کرتے ہوئے داڑھی کو بالکل چھوڑ دینا چاہیے اور اس کے طول و عرض سے کچھ بال لینا برا فعل ہے۔ (تحفة الاحوذی:4/11) (2) اس میں روزہ افطار کرنے کی جو دعا منقول ہے، وہ صحیح ہے۔ اس کے مقابلے میں مشہور دعا (اللهم لك صمت...) سندا ضعیف ہے، جیسا کہ آگے آ رہا ہے۔"}],[2358,"معاذ بن زہرہ سے روایت ہے کہ انہیں یہ بات پہنچی ہے کہ نبی اکرم صلی اللہ علیہ وسلم جب روزہ افطار فرماتے تو یہ دعا پڑھتے: «اللهم لك صمت وعلى رزقك أفطرت» \"اے اللہ! میں نے تیری ہی خاطر روزہ رکھا اور تیرے ہی رزق سے افطار کیا\"۔","",{"u2":"جناب معاذ بن زہرہ (تابعی) سے مروی ہے کہ نبی کریم صلی اللہ علیہ وسلم افطار کے وقت یہ دعا پڑھتے تھے «اللهم لك صمت وعلى رزقك أفطرت» ” اے ا اللہ! میں نے تیرے لیے روزہ رکھا اور تیرے ہی رزق پر کھول رہا ہوں۔ “","f2":"یہ حدیث ضعیف ہے۔ اس لیے افطار کے وقت پہلی دعا (ذهب الظما...) پڑھی جائے۔"}],[2359,"اسماء بنت ابوبکر رضی اللہ عنہما کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم کے زمانے میں ماہ رمضان میں ایک دن ہم نے بدلی میں روزہ کھول لیا اس کے بعد سورج نمودار ہو گیا۔ راوی ابواسامہ کہتے ہیں کہ میں نے ہشام بن عروہ سے سوال کیا کہ پھر تو لوگوں کو روزے کی قضاء کا حکم دیا گیا ہو گا؟ کہنے لگے: کیا اس کے بغیر بھی چارہ ہے؟ ۔","صحیح",{"u2":"سیدہ اسماء بنت ابی بکر رضی اللہ عنہا ا کا بیان ہے کہ رسول اللہ صلی اللہ علیہ وسلم کے زمانے میں رمضان میں ہم نے ایک دن بادل کی وجہ سے روزہ کھول لیا ‘ پھر سورج نکل آیا۔ ابواسامہ کہتے ہیں کہ میں نے ہشام سے پوچھا: تو کیا انہیں قضاء دینے کا حکم دیا گیا تھا؟ کہا: بھلا اس سے کوئی چارہ بھی ہے؟","f2":"ایسے روزے کی قضا کی بابت علماء میں اختلاف ہے، تاہم جمہور علماء کے نزدیک ایسی صورت میں افطار کیے ہوئے روزے کی قضاء واجب ہے۔ (تفصیل کے لیے دیکھئے: فتح الباری: 4/255)"}],[2360,"عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے صوم وصال (مسلسل روزے رکھنے) سے منع فرمایا ہے، لوگوں نے کہا: اللہ کے رسول! آپ تو مسلسل روزے رکھتے ہیں؟ آپ صلی اللہ علیہ وسلم نے فرمایا: \"میں تمہاری طرح نہیں ہوں، مجھے تو کھلایا پلایا جاتا ہے\"۔","صحیح",{"u2":"سیدنا عبداللہ بن عمر رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے روزوں میں وصال کرنے سے منع فرمایا۔ صحابہ نے کہا: اے اللہ کے رسول! آپ تو وصال کرتے ہیں؟ آپ صلی اللہ علیہ وسلم نے فرمایا ” میں تمہاری طرح نہیں ہوں۔ بیشک مجھے کھلایا پلایا جاتا ہے۔ “","f2":"(1) بغیر افطار کیے کئی کئی روز مسلسل روزے رکھنا وصال کہلاتا ہے جو رسول اللہ صلی اللہ علیہ وسلم کی خصوصیت تھی، نبی صلی اللہ علیہ وسلم نے اپنی امت کو اس طرح روزہ رکھنے سے منع فرمایا ہے۔ (2) نبی صلی اللہ علیہ وسلم نے اپنی جو خصوصیت بیان فرمائی ہے اس میں امت میں سے کوئی بھی آپ کا شریک و سہیم نہیں ہے۔ جو زاہد اور صوفیا قسم کے لوگ بغیر افطار مسلسل روزے رکھتے ہیں، ان کا عمل رسول اللہ صلی اللہ علیہ وسلم کے ارشاد کے سراسر خلاف ہے۔"}],[2361,"ابو سعید خدری رضی اللہ عنہ کہتے ہیں کہ انہوں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا: \"تم صوم وصال نہ رکھو، اگر تم میں سے کوئی صوم وصال رکھنا چاہے تو سحری کے وقت تک رکھے\"۔ لوگوں نے کہا: آپ تو رکھتے ہیں؟ فرمایا: \"میں تمہاری طرح نہیں ہوں، کیونکہ مجھے کھلانے پلانے والا کھلاتا پلاتا رہتا ہے\"۔","صحیح",{"u2":"سیدنا ابو سعید خدری رضی اللہ عنہ سے منقول ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” تم لوگ (روزوں میں) وصال مت کرو، اور جو کوئی وصال کرنا چاہے، تو سحر تک کر لے۔ “ صحابہ نے کہا: آپ تو وصال کرتے ہیں؟ آپ صلی اللہ علیہ وسلم نے فرمایا ” میں تمہاری طرح نہیں ہوں، بلاشبہ ایک کھلانے والا ہے جو مجھے کھلاتا ہے اور پلانے والا ہے جو مجھے پلاتا ہے۔ “","f2":"بلاشبہ نبی صلی اللہ علیہ وسلم کو اللہ تعالیٰ ہی کھلانے پلانے والا ہے۔ اور وہ غذا یقینا روحانی ہو گی۔ اگر کوئی امتی وصال کرنا چاہتا ہے، تو سحر تک کر لے۔"}],[2362,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جو شخص (روزے کی حالت میں) جھوٹ بولنا، اور برے عمل کرنا نہ چھوڑے تو اللہ تعالی کو حاجت نہیں کہ وہ اپنا کھانا پینا چھوڑ دے\"۔","صحیح",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” جو شخص جھوٹ اور بے ہودہ بولنا اور جھوٹ پر عمل کرنا نہ چھوڑے، تو اللہ تعالیٰ کو اس کے کھانے پینے کے چھوڑ دینے کی ضرورت نہیں ہے۔ “ ¤ احمد بن یونس نے کہا: مجھے اس کی سند ابن ابی ذئب نے اور یہ حدیث اس آدمی نے سمجھائی جو اس کے پہلو میں بیٹھا ہوا تھا، جو غالباً اس کا بھائی تھا۔","f2":"اللہ تعالیٰ کو بنی آدم کے کسی عمل کی کوئی حاجت نہیں۔ اس کی اپنی احتیاج کے تحت ہی اسے شرعی امور کا پابند کیا گیا ہے۔ اس حدیث سے معلوم ہوا کہ انسان اپنی تمام تر گفتگو اور تمام کاموں میں اپنے آپ کو تمام محرکات سے دور رکھے۔ غیبت نہ کرے، جھوٹ نہ بولے، چغلی نہ کھائے، حرام چیزوں کو فروخت نہ کرے، جب پورا مہینہ آدمی ان چیزوں سے دور رہے تو امید ہے کہ اس کا نفس سال کے بقیہ مہینوں میں بھی ان چیزوں سے اللہ کے فضل و کرم سے محفوظ رہے گا۔ لیکن انتہائی افسوسناک امر یہ ہے کہ بہت سارے روزہ دار، رمضان اور غیر رمضان میں کوئی فرق نہیں کرتے، وہی جھوٹ، بے ہودہ گفتگو، دھوکہ وغیرہ اپنی عادت کے مطابق جارہ رہتا ہے۔ ان کے اوپر رمضان المبارک کا کوئی اثر نہیں ہوتا۔ بلاشبہ حدیث میں مذکورہ اعمال روزے کو نہیں توڑتے مگر اس کے اجروثواب میں کمی ضرور آجاتی ہے اور یہ بھی ممکن ہے کہ جب کثرت سے ان اعمال کی پروا نہ کی جائے تو روزے کا اجر ہی ضائع ہو جائے۔"}],[2363,"ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"روزہ (برائیوں سے بچنے کے لیے) ڈھال ہے، جب تم میں کوئی صائم (روزے سے ہو) تو فحش باتیں نہ کرے، اور نہ نادانی کرے، اگر کوئی آدمی اس سے جھگڑا کرے یا گالی گلوچ کرے تو اس سے کہہ دے کہ میں روزے سے ہوں، میں روزے سے ہوں\"۔","صحیح",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ کا بیان ہے کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا ” جب تم میں سے کوئی روزے سے ہو تو کسی قسم کی فحش بات یا جہالت کا کام نہ کرے۔ اگر کوئی دوسرا اس سے جھگڑے یا گالی گلوچ دے تو اسے چاہیئے کہ کہہ دے میں روزے سے ہوں، میں نے روزہ رکھا ہوا ہے۔ “","f2":"(1) فحش گوئی اور اعمال جہالت سے مسلمان کو ہر حال میں بچنا چاہیے مگر روزہ دار کو ان سے پرہیز کی بہت زیادہ تاکید ہے۔ چنانچہ زبانی طور پر اپنے مقابل کو بتا دے کہ میں روزے سے ہوں اور غلط طرز عمل کو مزید بڑھنے بڑھانے سے باز رہے۔ بعض علماء کہتے ہیں کہ وہ یہ بات اپنے دل میں کہے اور اپنے عمل سے ثابت کرے کہ وہ روزے سے ہے۔ لیکن یہ موقف ظاہر نص کے خلاف ہے۔ (2) اور روزے کی حالت میں اس ہدایت پر عمل کرنے ہی سے روزہ ڈھال ہو سکتا ہے۔"}],[2364,"عامر بن ربیعہ رضی اللہ عنہ کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو روزے کی حالت میں مسواک کرتے دیکھا، جسے میں نہ گن سکتا ہوں، نہ شمار کر سکتا ہوں۔","ضعیف",{"u2":"جناب عبیداللہ بن عامر بن ربیعہ اپنے والد (عامر بن ربیعہ) سے روایت کرتے ہیں، ان کا کہنا ہے کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو مسواک کرتے ہوئے دیکھا، حالانکہ آپ صلی اللہ علیہ وسلم روزے سے تھے۔ مسدد نے مزید یوں کہا: میں نے آپ صلی اللہ علیہ وسلم کو بےشمار دفعہ (مسواک کرتے) دیکھا۔","f2":"(1) روزہ رکھ کر مسواک کر لینے میں کوئی حرج نہیں۔ مسواک خواہ تازہ ہو یا خشک، ہر طرح سے جائز ہے۔ اور ظاہر ہے کہ تازہ مسواک کی رطوبت کو تھوکنا لازمی ہو گا جب کہ اس کے ذائقے کا منہ میں باقی رہ جانا معاف ہے۔ جہاں تک ٹوتھ پیسٹ کا استعمال کا سوال ہے، تع بعض علماء اسے روزے کی حالت میں مکروہ قرار دیتے ہیں۔ لیکن ایسا سمجھنا صحیح نہیں ہے، اس کا حکم بھی مسواک سے مختلف نہیں ہے۔ اگر برش کے استعمال کے دوران میں، مسواک کرتے ہوئے یا وضو کرتے ہوئے دانتوں سے معمولی مقدار میں خون نکل آئے تو اس سے روزہ نہیں ٹوٹتا۔ امام بخاری رحمة اللہ علیہ نے (باب سوال الرطب واليابس للصائم) کا عنوان قائم کر کے مندرجہ بالا روایت کو تعلیقا بیان فرمایا ہے۔ (2) دوسری حدیث جس میں ہے کہ روزے دار کے منہ کی بو اللہ تعالیٰ کے ہاں کستوری کی خوشبو سے بھی طیب ہوتی ہے۔ (صحيح البخاري‘ الصوم‘ حديث:1894‘ و صحيح مسلم‘ الصيام‘ حديث:1151) تو اس کا مفہوم منہ کو گندہ رکھنا نہیں بلکہ اس میں روزے دار کا اللہ کے ہاں محبوب ہونا بیان ہوا ہے اور یہ کہ اس کے معدہ کے خالی ہونے کی وجہ سے اس کے منہ میں جو نامناسب سی بو پیدا ہو جاتی ہے، وہ بھی اللہ کے ہاں پسندیدہ ہے۔ اور ہر حال اور کیفیت میں منہ کو صاف ستھرا رکھنا مطلوب ہے اور روزہ دار ہر حال میں اللہ کا محبوب ہے۔ (3) اس حدیث کی اسنادی بحث کے لیے دیکھئے: ارواء الغلیل، حدیث: 68۔"}],[2365,"ابوبکر بن عبدالرحمٰن ایک صحابی سے روایت کرتے ہیں، وہ کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو دیکھا آپ نے فتح مکہ کے سال اپنے سفر میں لوگوں کو روزہ توڑ دینے کا حکم دیا، اور فرمایا: \"اپنے دشمن (سے لڑنے) کے لیے طاقت حاصل کرو\" اور رسول اللہ صلی اللہ علیہ وسلم نے خود روزہ رکھا۔ ابوبکر کہتے ہیں: مجھ سے بیان کرنے والے نے کہا کہ میں نے مقام عرج میں رسول اللہ صلی اللہ علیہ وسلم کو اپنے سر پر پیاس سے یا گرمی کی وجہ سے پانی ڈالتے ہوئے دیکھا اور آپ صلی اللہ علیہ وسلم روزے سے تھے۔","صحیح",{"u2":"جناب ابوبکر بن عبدالرحمٰن کسی صحابی سے روایت کرتے ہیں کہ میں نے دیکھا، رسول اللہ صلی اللہ علیہ وسلم نے فتح مکہ کے سال اپنے سفر میں صحابہ کو روزہ افطار کرنے کا حکم دیا اور فرمایا ” دشمن کے مقابلے کے لیے قوت حاصل کرو۔ “ اور آپ صلی اللہ علیہ وسلم نے خود روزہ رکھا۔ ابوبکر نے کہا: مجھے حدیث بیان کرنے والے نے بتایا: تحقیق میں نے رسول اللہ صلی اللہ علیہ وسلم کو مقام عرج میں دیکھا آپ صلی اللہ علیہ وسلم روزے سے تھے اور پیاس یا گرمی کی وجہ سے اپنے سر پر پانی ڈال رہے تھے۔","f2":"(1) سفر یا جہاد میں روزہ افطار کرنا افضل ہے۔ (2) دوران سفر میں روزہ رکھا بھی جا سکتا ہے۔ (3) گرمی یا پیاس کی بے چینی میں اپنے سر یا جسم پر پانی ڈالنا، غسل کرنا یا گیلا کپڑا اوڑھنا مباح ہے۔ اور ایسے ہی ایرکنڈیشن سے فائدہ حاصل کرنا بھی جائز ہے۔"}],[2366,"لقیط بن صبرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"ناک میں پانی ڈالنے میں مبالغہ کرو سوائے اس کے کہ تم روزے سے ہو\"۔","صحیح",{"u2":"سیدنا لقیط بن صبرہ رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” (وضو کرتے ہوئے) ناک میں خوب پانی چڑھاؤ، سوائے اس کے کہ روزے سے ہو۔ “","f2":"روزے کی حالت میں ناک میں دوائی نہیں ڈالی جا سکتی لیکن گردوغبار یا آٹے وغیرہ کی دھول کا اندر چلے جانا معاف ہے۔ خوشبو سونگھنے میں بھی کوئی حرج نہیں۔ آنکھ اور کان میں دوا ڈالنا جائز ہے۔"}],[2367,"ثوبان رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"پچھنا لگانے اور لگوانے والے دونوں کا روزہ ٹوٹ گیا\"۔","صحیح",{"u2":"سیدنا ثوبان رضی اللہ عنہ، نبی کریم صلی اللہ علیہ وسلم سے بیان کرتے ہیں کہ آپ صلی اللہ علیہ وسلم نے فرمایا ” سینگی لگانے اور لگوانے والا روزہ کھولنے والا ہو گیا۔ “ ¤ شیبان نے اپنی حدیث میں کہا: مجھے ابوقلابہ نے خبر دی، اس کو ابو اسماء الرجی نے حدیث بیان کی کہ ثوبان مولیٰ رسول اللہ صلی اللہ علیہ وسلم نے اس کو خبر دی کہ اس نے رسول اللہ صلی اللہ علیہ وسلم سے سنا تھا۔","f2":"(1) اس باب کی احادیث کو اگلے باب کی احادیث کے ساتھ ملا کر پڑھا جائے تو مسئلہ واضح ہو جاتا ہے کہ اس باب کی احادیث یا تو منسوخ ہیں یا کراہت پر محمول ہیں۔ (2) شیبان کی سند میں اخبار و تحدیث کی صراحت ہے جبکہ ہشام کی سند میں عنعنہ ہے۔"}],[2368,"ابوقلابہ جرمی نے خبر دی ہے کہ شداد بن اوس رضی اللہ عنہ نبی اکرم صلی اللہ علیہ وسلم کے ساتھ چل رہے تھے کہ اسی دوران (آپ نے فرمایا)، آگے راوی نے اس سے پہلی والی حدیث کی طرح بیان کیا۔","صحیح",{"u2":"سیدنا شداد بن اوس رضی اللہ عنہ کا کہنا ہے کہ ایک بار میں نبی کریم صلی اللہ علیہ وسلم کے ساتھ جا رہا تھا اور مذکورہ بالا کی مانند ذکر کیا۔"}],[2369,"شداد بن اوس رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم بقیع میں ایک شخص کے پاس آئے جو کہ سینگی لگا رہا تھا، آپ میرا ہاتھ پکڑے ہوئے تھے، یہ رمضان کی اٹھارہ تاریخ کا واقعہ ہے، اور آپ صلی اللہ علیہ وسلم نے فرمایا: \"سینگی (پچھنا) لگانے والے اور لگوانے والے دونوں کا روزہ ٹوٹ گیا\"۔ ابوداؤد کہتے ہیں: خالد الحذاء نے ابوقلابہ سے ایوب کی سند سے اسی کے مثل روایت کیا ہے۔","صحیح",{"u2":"سیدنا شداد بن اوس رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم بقیع کے قریب ایک آدمی کے پاس سے گزرے اور وہ سینگی لگوا رہا تھا، جبکہ نبی کریم صلی اللہ علیہ وسلم میرا ہاتھ تھامے ہوئے تھے اور رمضان کی اٹھارہ تاریخ تھی، آپ صلی اللہ علیہ وسلم نے فرمایا ” سینگی لگانے اور لگوانے والا (دونوں) روزہ کھولنے والے ہو گئے۔ “ ¤ امام ابوداؤد رضی اللہ عنہ نے کہا: خالد الخداء نے (بھی) ابوقلابہ سے بسند ایوب روایت کیا ہے۔"}],[2370,"نبی اکرم صلی اللہ علیہ وسلم کے مولی ثوبان رضی اللہ عنہ سے روایت ہے کہ آپ صلی اللہ علیہ وسلم نے فرمایا: \"سینگی (پچھنا) لگانے والے اور لگوانے والے دونوں کا روزہ ٹوٹ گیا\"۔","صحیح",{"u2":"سیدنا ثوبان رضی اللہ عنہ، مولیٰ نبی کریم صلی اللہ علیہ وسلم نے خبر دی کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا ” سینگی لگانے والا اور لگوانے والا (دونوں) مفطر (روزہ کھولنے والے) ہو گئے۔ “"}],[2371,"ثوبان رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"سینگی (پچھنا) لگانے والے اور لگوانے والے دونوں کا روزہ ٹوٹ گیا\"۔ ابوداؤد کہتے ہیں: اسے ابن ثوبان نے اپنے والد سے اور انہوں نے مکحول سے اسی سند سے اسی کے مثل روایت کیا ہے۔","صحیح",{"u2":"سیدنا ثوبان رضی اللہ عنہ، نبی کریم صلی اللہ علیہ وسلم سے بیان کرتے ہیں کہ آپ صلی اللہ علیہ وسلم نے فرمایا ” سینگی لگانے والا اور لگوانے والا مفطر (روزہ کھولنے والے) ہو گئے۔ “ امام ابوداؤد رضی اللہ عنہ کہتے ہیں کہ ابن ثوبان نے بھی اپنے والد سے بسند مکحول اس کی مانند روایت کیا ہے۔","f2":"(افطر الحاجم والمحجوم) کے معنی میں امام احمد اور اسحاق بن راھویہ نے ظاہری معنی مراد لیے ہیں ان کا روزہ ٹوٹ جاتا ہے۔ اور کچھ دوسرے اہل علم یہ معنی کرتے ہیں کہ ان کا روزہ ٹوٹنے کے قریب ہو گیا۔ گویا اس میں زجر اور کراہت کا مفہوم ہے۔ واللہ اعلم، اس دوسرے معنی کی رُو سے اس باب کی روایات اور اگلے باب کی روایات، جن میں اس کا جواز ہے، کے درمیان تطبیق ہو جاتی ہے۔"}],[2372,"عبداللہ بن عباس رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے سینگی (پچھنا) لگوایا اور آپ روزے سے تھے۔ ابوداؤد کہتے ہیں: اسے وہیب بن خالد نے ایوب سے اسی سند سے اسی کے مثل روایت کیا ہے، اور جعفر بن ربیعہ اور ہشام بن حسان نے عکرمہ سے انہوں نے ابن عباس رضی اللہ عنہما سے اسی کے مثل روایت کیا ہے۔","صحیح",{"u2":"عکرمہ سیدنا ابن عباس رضی اللہ عنہ سے روایت کرتے ہیں کہ بلاشبہ رسول اللہ صلی اللہ علیہ وسلم نے روزے کی حالت میں سینگی لگوائی۔ ¤ امام ابوداؤد رضی اللہ عنہ نے کہا: اس روایت کو وہیب بن خالد نے ایوب سے اپنی سند سے اسی کے مثل روایت کیا ہے، نیز جعفر بن ربیعہ اور ہشام بن حسان، عکرمہ سے وہ سیدنا ابن عباس رضی اللہ عنہ سے اسی کے مثل روایت کرتے ہیں۔"}],[2373,"عبداللہ بن عباس رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے سینگی (پچھنا) لگوایا، آپ روزے سے تھے اور احرام باندھے ہوئے تھے ۱؎۔\n§وضاحت\n۱؎ : حالت احرام میں آپ صلی اللہ علیہ وسلم روزے سے ہوں ، یہ بات بعید از قیاس ہے ، یہی یزید بن ابی زیاد کے ضعیف ہونے کی دلیل ہے ، ہاں کبھی روزے کی حالت میں، اور کبھی احرام کی حالت میں بچھنا لگوانا آپ صلی اللہ علیہ وسلم سے ثابت ہے ، صحیح بخاری کے الفاظ ہیں «احتجم وهو صائم، واحتجم وهو محرم» (آپ صلی اللہ علیہ وسلم نے سینگی (پچھنا) لگوائی جبکہ آپ روزے سے تھے ، آپ صلی اللہ علیہ وسلم نے سینگی لگوائی جبکہ آپ محرم تھے)","ضعیف",{"u2":"مقسم، سیدنا ابن عباس رضی اللہ عنہ سے روایت کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے روزے اور احرام کی حالت میں سینگی لگوائی ہے۔","f2":"الفاظ حدیث محل نظر ہیں۔ تفصیل کے لیے دیکھئے: (ارواء الغلیل حدیث نمبر:932)"}],[2374,"عبدالرحمٰن بن ابی لیلی کہتے ہیں کہ مجھ سے نبی اکرم صلی اللہ علیہ وسلم کے اصحاب میں سے ایک شخص نے بیان کیا کہ رسول صلی اللہ علیہ وسلم نے (حالت روزے میں) سینگی لگوانے اور مسلسل روزے رکھنے سے منع فرمایا، لیکن اپنے اصحاب کی رعایت کرتے ہوئے اسے حرام قرار نہیں دیا، آپ سے کہا گیا: اللہ کے رسول! آپ تو بغیر کھائے پیئے سحر تک روزہ رکھتے ہیں؟ آپ صلی اللہ علیہ وسلم نے فرمایا: \"میں سحر تک روزے کو جاری رکھتا ہوں اور مجھے میرا رب کھلاتا پلاتا ہے\"۔","صحیح",{"u2":"جناب عبدالرحمٰن بن ابی لیلیٰ کہتے ہیں کہ مجھ سے ایک صحابی نے بیان کیا کہ رسول اللہ صلی اللہ علیہ وسلم نے صحابہ پر شفقت فرماتے ہوئے، انہیں سینگی لگوانے اور روزوں میں وصال کرنے سے منع کیا مگر آپ صلی اللہ علیہ وسلم نے ان دونوں کو حرام نہیں کیا۔ آپ صلی اللہ علیہ وسلم سے کہا گیا: اے اللہ کے رسول! آپ تو سحر تک وصال کرتے ہیں، آپ صلی اللہ علیہ وسلم نے فرمایا ” میں سحر تک وصال کرتا ہوں اور میرا رب مجھے کھلاتا پلاتا ہے۔ “","f2":"غالبا شواہد ہی کی بنیاد پر بعض حضرات نے اس حدیث کو صحیح بھی کہا ہے۔"}],[2375,"ثابت کہتے ہیں کہ انس رضی اللہ عنہ نے کہا: ہم روزے دار کو صرف مشقت کے پیش نظر سینگی (پچھنا) نہیں لگانے دیتے تھے۔","صحیح",{"u2":"سیدنا انس رضی اللہ عنہ کہتے ہیں کہ ہم روزے دار کو سینگی اس لیے نہیں لگوانے دیتے تھے کہ کہیں اسے مشقت نہ ہو۔","f2":"یعنی سینگی لگوانے سے روزہ نہیں ٹوٹتا، صرف اندیشہ ہوتا ہے کہ ضعف کی بنا پر اسے پریشانی ہو گی۔ لہذا کمزوری کا اندیشہ نہ ہو تو جائز ہے۔"}],[2376,"نبی اکرم صلی اللہ علیہ وسلم کے اصحاب میں سے ایک شخص سے روایت ہے، وہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جس نے قے کی اس کا روزہ نہیں ٹوٹتا، اور نہ اس شخص کا جس کو احتلام ہو گیا، اور نہ اس شخص کا جس نے پچھنا لگایا\"۔","ضعیف",{"u2":"ایک صحابی سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” جسے قے آ جائے یا (نیند میں) احتلام ہو جائے یا جو سینگی لگوائے، تو اس کا روزہ نہیں ٹوٹتا۔ “","f2":"یہ روایت معنی صحیح ہے، یعنی صحیح روایات سے اس میں بیان کردہ باتیں ثابت ہیں۔ تاہم قصدا قے کرنے سے روزہ ٹوٹ جاتا ہے اگر بغیر قصد کے قے آ جائے تو روزہ ٹوٹتا، اسی طرح جاگتے ہوئے منی کا انزال ہو جائے خواہ مشت زنی سے ہو یا بیوی سے جماع کرنے سے یا اس سے لپٹنے یا بوسلہ لینے کی وجہ سے تو بھی روزہ ٹوٹ جائے گا۔"}],[2377,"معبد بن ہوذہ رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے مشک ملا ہوا سرمہ سوتے وقت لگانے کا حکم دیا اور فرمایا:\"روزہ دار اس سے پرہیز کرے\"۔ ابوداؤد کہتے ہیں: مجھ سے یحیی بن معین نے کہا کہ یہ یعنی سرمہ والی حدیث منکر ہے۔","ضعیف",{"u2":"عبدالرحمٰن بن نعمان اپنے والد سے، وہ دادا سے، وہ نبی کریم صلی اللہ علیہ وسلم سے بیان کرتے ہیں کہ آپ صلی اللہ علیہ وسلم نے حکم دیا کہ سوتے وقت کستوری ملا سرمہ استعمال کیا جائے اور فرمایا ” روزہ دار اس سے پرہیز کرے۔ “ امام ابوداؤد رضی اللہ عنہ فرماتے ہیں کہ مجھے امام یحییٰ بن معین نے کہا: یہ سرمے والی حدیث منکر ہے۔"}],[2378,"عبیداللہ بن ابی بکر بن انس کہتے ہیں کہ انس بن مالک رضی اللہ عنہ سرمہ لگاتے تھے اور روزے سے ہوتے تھے۔","حسن موقوف",{"u2":"سیدنا انس بن مالک رضی اللہ عنہ کے متعلق روایت ہے کہ وہ روزے کی حالت میں سرمہ لگایا کرتے تھے۔"}],[2379,"اعمش کہتے ہیں کہ میں نے اپنے ساتھیوں میں سے کسی کو بھی روزے دار کے سرمہ لگانے کو ناپسند کرتے نہیں دیکھا اور ابراہیم نخعی روزے دار کو «صبر» (ایک قسم کا سرمہ ہے) کے سرمے کی اجازت دیتے تھے۔","حسن",{"u2":"جناب اعمش کہتے ہیں (یہ صغار تابعین میں سے ہیں) میں نے اپنے اہل علم دوستوں (فقہاء و محدثین) میں سے کسی کو نہیں پایا کہ روزے دار کے لیے سرمے کو مکروہ سمجھتے ہوں۔ اور ابراہیم نخعی اجازت دیتے تھے کہ روزے دار ایلوا کو بطور سرمہ استعمال کرے۔","f2":"روزے کی حالت میں آنکھ میں سرمہ لگانا یا دوا ڈال لینا جائز ہے۔"}],[2380,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جس کو قے ہو جائے اور وہ روزے سے ہو تو اس پر قضاء نہیں، ہاں اگر اس نے قصداً قے کی تو قضاء کرے\"۔ ابوداؤد کہتے ہیں: اسے حفص بن غیاث نے بھی ہشام سے اسی کے مثل روایت کیا ہے۔","صحیح",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” جس کسی کو قے آ جائے جبکہ وہ روزے سے ہو تو اس پر کوئی قضاء نہیں ہے، لیکن اگر وہ قصداً قے کرے تو قضاء دے۔ “ ¤ امام ابوداؤد رضی اللہ عنہ فرماتے ہیں کہ اس روایت کو حفص بن غیاث نے بھی ہشام سے اسی کے مثل روایت کیا ہے۔","f2":"یہ روایت معنی صحیح ہے، اسی لیے بعض حضرات نے اسے صحیح کہا ہے۔"}],[2381,"معدان بن طلحہ کا بیان ہے کہ ابوالدرداء رضی اللہ عنہ نے ان سے بیان کیا کہ رسول اللہ صلی اللہ علیہ وسلم کو قے ہوئی تو آپ نے روزہ توڑ ڈالا، اس کے بعد دمشق کی مسجد میں میری ملاقات ثوبان رضی اللہ عنہ سے ہوئی تو میں نے کہا کہ ابوالدرداء نے مجھ سے بیان کیا کہ رسول اللہ صلی اللہ علیہ وسلم کو قے ہو گئی تو آپ نے روزہ توڑ دیا اس پر ثوبان نے کہا: ابوالدرداء نے سچ کہا اور میں نے ہی (اس وقت)رسول اللہ صلی اللہ علیہ وسلم کے لیے وضو کا پانی ڈالا تھا۔","صحیح",{"u2":"سیدنا ابودرداء رضی اللہ عنہ نے بیان کیا کہ رسول اللہ صلی اللہ علیہ وسلم نے قے کی اور روزہ توڑ ڈالا۔ (معدان کہتے ہیں کہ) پھر سیدنا ثوبان مولیٰ رسول اللہ صلی اللہ علیہ وسلم سے دمشق کی مسجد میں میری ملاقات ہوئی تو میں نے ان سے کہا: سیدنا ابولدرداء رضی اللہ عنہ نے مجھے بتایا ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے قے کی اور روزہ توڑ ڈالا تھا۔ کہا کہ انہوں نے صحیح کہا ہے اور میں نے ہی آپ صلی اللہ علیہ وسلم کے لیے وضو کا پانی انڈیلا تھا۔","f2":"عمدا قے کرنے سے روزہ ٹوٹ جاتا ہے اور قضا لازم آتی ہے، بخلاف اس کے کہ ازخود قے آئے۔ خود بخود قے آنے سے نہ روزہ ٹوٹتا ہے، اور نہ قضا لازم آتی ہے۔"}],[2382,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم روزے کی حالت میں بوسہ لیتے اور چمٹ کر سوتے، لیکن آپ صلی اللہ علیہ وسلم اپنی خواہش پر سب سے زیادہ قابو رکھنے والے تھے۔","صحیح",{"u2":"ام المؤمنین سیدہ عائشہ رضی اللہ عنہا ا بیان کرتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم روزے کی حالت میں بوسہ لے لیا کرتے تھے اور روزے کی حالت میں بیوی کے ساتھ لیٹ بھی جاتے تھے، لیکن آپ صلی اللہ علیہ وسلم اپنے جذبات پر خوب ضبط رکھنے والے تھے۔"}],[2383,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم ماہ رمضان کے مہینے میں بوسہ لیتے (لے لیا کرتے) تھے۔","",{"u2":"ام المؤمنین سیدہ عائشہ رضی اللہ عنہا ا کا بیان ہے کہ نبی کریم صلی اللہ علیہ وسلم ماہ رمضان میں (بیویوں کا) بوسہ لے لیا کرتے تھے۔"}],[2384,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم میرا بوسہ لیتے اور آپ روزے سے ہوتے اور میں بھی روزے سے ہوتی۔","صحیح",{"u2":"ام المؤمنین سیدہ عائشہ رضی اللہ عنہا ا کا بیان ہے کہ رسول اللہ صلی اللہ علیہ وسلم میرا بوسہ لیا کرتے تھے جبکہ آپ روزے سے ہوتے اور میں بھی۔","f2":"(1) حضرت عائشہ رضی اللہ عنہا کی یہ بات صحیح احادیث میں بھی بیان ہوئی ہے، اسی لیے شیخ البانی رحمة اللہ علیہ نے اسے صحیح کہا ہے۔ میاں بیوی کے لیے روزے کی حالت میں بوس و کنار جائز ہے مگر لازمی ہے کہ اپنے جذبات پر ضبط رکھنے والے ہوں۔ اگر حد سے بڑھنے کا اندیشہ ہو تو اس عمل سے بچنا لازمی ہے۔ (2) حضرت عائشہ رضی اللہ عنہا کا اپنے ان مخفی امور کو ذکر کرنا شرعی ضرورت کی بنا پر ہے۔ اور نبی صلی اللہ علیہ وسلم کے کثرت ازدواج کی ایک حکمت یہ بھی رہی ہے کہ زوجین اور اندرون خانہ کی شرعی زندگی امت کے سامنے آئے اور ان کے لیے ہدایت اور اسوہ ثابت ہو۔ اگر یہ حقائق بیان نہ ہوتے تو دین کا بڑا حصہ ہم سے اوجھل رہتا اور بڑی آزمائش ہوتی۔"}],[2385,"جابر بن عبداللہ رضی اللہ عنہما کہتے ہیں کہ عمر بن خطاب رضی اللہ عنہ نے کہا: میں خوش ہوا تو میں نے بوسہ لیا اور میں روزے سے تھا، میں نے کہا: اللہ کے رسول! میں نے تو آج بہت بڑی حرکت کر ڈالی، روزے کی حالت میں بوسہ لیا، آپ صلی اللہ علیہ وسلم نے فرمایا: \"بھلا بتاؤ اگر تم روزے کی حالت میں پانی سے کلی کر لو (تو کیا ہوا)\"، میں نے کہا: اس میں تو کچھ حرج نہیں، آپ صلی اللہ علیہ وسلم نے فرمایا: \"تو بس کوئی بات نہیں\"۔","صحیح",{"u2":"سیدنا عمر بن خطاب رضی اللہ عنہ نے بیان کیا کہ میں نے خوشی میں آ کر (بیوی کا) بوسہ لے لیا جبکہ میں روزے سے تھا۔ پھر میں نے رسول اللہ صلی اللہ علیہ وسلم سے کہا: اے اللہ کے رسول! میں آج ایک بہت بڑا کام کر بیٹھا ہوں کہ روزے کی حالت میں بوسہ لے لیا ہے۔ آپ صلی اللہ علیہ وسلم نے فرمایا ” بھلا اگر تم روزے کی حالت میں کلی کر لو تو؟ “ عیسی بن حماد کی روایت میں ہے۔ میں نے کہا: کوئی حرج نہیں۔ آپ نے فرمایا ” تو اس میں بھی کوئی حرج نہیں۔ “"}],[2386,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم روزے کی حالت میں ان کا بوسہ لیتے اور ان کی زبان چوستے تھے۔ ابن اعرابی کہتے ہیں: یہ سند صحیح نہیں ہے۔","ضعیف",{"u2":"ام المؤمنین سیدہ عائشہ رضی اللہ عنہا ا سے مروی ہے کہ نبی کریم صلی اللہ علیہ وسلم ان کا بوسہ لے لیتے جبکہ وہ روزے سے ہوتے اور ان کی زبان چوستے۔ ¤ ابن الاعرابی کہتے ہیں کہ مجھے امام ابوداؤد رضی اللہ عنہ سے یہ بات پہنچی ہے کہ یہ سند صحیح نہیں ہے۔","f2":"یہ حدیث ضعیف ہے، اس لیے اس میں بیان کردہ بات (زبان کا چوسنا) صحیح نہیں ہے۔ البتہ روزے کی حالت میں بوسہ لینا ثابت ہے۔ روزہ دار اگر کسی غیر کا لعاب چوسے اور نگل لے تو روزہ ٹوٹ جاتا ہے۔"}],[2387,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ ایک شخص نے نبی اکرم صلی اللہ علیہ وسلم سے روزہ دار کے بیوی سے چمٹ کر سونے کے متعلق پوچھا، آپ نے اس کو اس کی اجازت دی، اور ایک دوسرا شخص آپ صلی اللہ علیہ وسلم کے پاس آیا اور اس نے بھی اسی سلسلہ میں آپ سے پوچھا تو اس کو منع کر دیا، جس کو آپ صلی اللہ علیہ وسلم نے اجازت دی تھی، وہ بوڑھا تھا اور جسے منع فرمایا تھا وہ جوان تھا۔","حسن صحیح",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ سے منقول ہے کہ ایک شخص نے نبی کریم صلی اللہ علیہ وسلم سے مسئلہ پوچھا کہ روزہ دار شخص بیوی کے ساتھ لیٹے یا نہ؟ آپ صلی اللہ علیہ وسلم نے اس کو اجازت دی۔ پھر دوسرا آیا اور اس نے بھی آپ صلی اللہ علیہ وسلم سے یہ مسئلہ پوچھا۔ آپ صلی اللہ علیہ وسلم نے اس کو منع فر دیا۔ دراصل آپ صلی اللہ علیہ وسلم نے جس کو اجازت دی، وہ بوڑھا تھا اور جس کو منع فرمایا، وہ جوان تھا۔","f2":"بوڑھے کے جذبات چونکہ قابل ضبط ہوتے ہیں اس لیے اس کو اجازت دے دی گئی مگر جو ان کے لئے ضبط مشکل ہوتا ہے، اس لیے اس کو اجازت نہیں دی۔ لہذا اگر کسی کو اندیشہ ہو کہ بوس و کنار سے بات جماع تک پہنچ جائے گی یا انزال ہو جائے گا تو دور رہے۔ اور اگر انزال ہو جائے تو قضا واجب ہو گی۔"}],[2388,"ام المؤمنین عائشہ اور ام سلمہ رضی اللہ عنہما کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم حالت جنابت میں صبح کرتے۔ عبداللہ اذرمی کی روایت میں ہے: ایسا رمضان میں احتلام سے نہیں بلکہ جماع سے ہوتا تھا، پھر آپ روزہ سے رہتے۔ ابوداؤد کہتے ہیں: کتنی کم تر ہے اس شخص کی بات جو یہ یعنی «يصبح جنبا في رمضان» کہتا ہے، حدیث تو (جو کہ بہت سے طرق سے مروی ہے) یہ ہے کہ نبی اکرم صلی اللہ علیہ وسلم جنبی ہو کر صبح کرتے تھے حالانکہ آپ روزے سے ہوتے ۱؎۔\n§وضاحت\n۱؎ : یعنی اس میں لفظ رمضان کا ذکر نہیں ہے۔","صحیح",{"u2":"امہات المؤمنین سیدہ عائشہ اور سیدہ ام سلمہ رضی اللہ عنہا ا سے مروی ہے، وہ بیان کرتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم صبح کو جنبی ہو کر اٹھتے، عبداللہ اذرمی نے اپنی روایت میں کہا کہ رمضان میں، جماع کی بنا پر نہ کہ احتلام سے اور پھر روزہ رکھ لیتے۔ ¤ امام ابوداؤد رضی اللہ عنہ کہتے ہیں کہ «صبح جنبا في رمضان» کا لفظ بہت کم راوی ذکر کرتے ہیں۔ (صحیح) حدیث کے لفظ یہ ہیں «أن النبي صلى الله عليه وسلم كان يصبح جنبا وهو صائم» ” نبی کریم صلی اللہ علیہ وسلم جنابت کی حالت میں صبح کرتے اور آپ روزہ رکھے ہوئے ہوتے۔“","f2":"فجر صادق کی ابتدائی ساعات میں انسان اگر جنابت کی حالت میں روزے کی ابتدا کرے تو کوئی حرج کی بات نہیں ہے کہ بروقت غسل کر کے نماز میں شریک ہو جائے مگر بلا عذر شرعی اپنی اس کیفیت کو طول دینا ناجائز اور روزے میں عیب ہے۔ مرد اور عورت دونوں کے لیے یہی مسئلہ ہے۔"}],[2389,"ام المؤمنین عائشہ رضی اللہ عنہا سے روایت ہے کہ ایک شخص نے رسول اللہ صلی اللہ علیہ وسلم سے دروازے پر کھڑے ہو کر کہا: اللہ کے رسول! میں جنابت کی حالت میں صبح کرتا ہوں اور روزہ رکھنا چاہتا ہوں؟ تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"میں بھی جنابت کی حالت میں صبح کرتا ہوں اور روزہ رکھنے کا ارادہ رکھتا ہوں پھر غسل کرتا ہوں اور روزہ رکھ لیتا ہوں\"، اس شخص نے کہا: اللہ کے رسول! آپ تو ہماری طرح نہیں ہیں، اللہ تعالی نے آپ کے اگلے اور پچھلے گناہ معاف کر رکھے ہیں، اس پر رسول اللہ صلی اللہ علیہ وسلم غصہ ہو گئے اور فرمایا: \"اللہ کی قسم! مجھے امید ہے کہ میں تم میں اللہ تعالی سے سب سے زیادہ ڈرنے والا ہوں، اور مجھے کیا کرنا ہے اس بات کو بھی تم سے زیادہ جانتا ہوں\"۔","صحیح",{"u2":"ام المؤمنین سیدہ عائشہ رضی اللہ عنہا ا سے مروی ہے کہ ایک شخص نے رسول اللہ صلی اللہ علیہ وسلم سے مسئلہ پوچھا جبکہ آپ صلی اللہ علیہ وسلم دروازے پر کھڑے تھے: اے اللہ کے رسول! میں بحالت جنابت صبح کرتا ہوں اور روزہ بھی رکھنا چاہتا ہوں۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” میں بھی (بعض اوقات) صبح کو جنابت کی حالت میں اٹھتا ہوں اور روزے کا ارادہ ہوتا ہے تو غسل کر لیتا ہوں اور روزہ رکھتا ہوں۔ “ وہ آدمی کہنے لگا: اے اللہ کے رسول! آپ تو ہماری مانند نہیں ہیں۔ اللہ عزوجل نے آپ کی اگلی پچھلی تمام تقصیرات معاف فرمائی ہوئی ہیں۔ اس پر آپ غضبناک ہو گئے اور فرمایا ” قسم اللہ کی! میں یقیناً تم میں سب سے زیادہ اللہ سے ڈرنے والا ہوں اور اتباع کے لائق اعمال سے بہت زیادہ آگاہ ہوں۔ “","f2":"اللہ کی انتہائی خشیت اور اس کے دین کی معرفت کا تقاضا بھرپور عمل اور کامل احتیاط ہے۔ پھر نبی صلی اللہ علیہ وسلم سے زیادہ احتیاط کون کر سکتا ہے؟ لہذا اعمال میں آپ ہی کی اقتدا واجب ہے۔ اور آپ ہی امت کے لیے نمونہ ہیں۔ سوائے ان امور کے جن میں آپ کا استثنا ثابت ہے۔"}],[2390,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ ایک شخص نبی اکرم صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوا اور کہنے لگا کہ میں ہلاک ہو گیا آپ صلی اللہ علیہ وسلم نے پوچھا: \"کیا بات ہے؟\" اس نے کہا: میں نے رمضان میں اپنی بیوی سے جماع کر لیا ہے، آپ صلی اللہ علیہ وسلم نے فرمایا: \"کیا تم ایک گردن آزاد کر سکتے ہو؟\" اس نے کہا: نہیں، فرمایا: \"دو مہینے مسلسل روزے رکھنے کی طاقت ہے؟\" کہا: نہیں، فرمایا: \"ساٹھ مسکینوں کو کھانا کھلا سکتے ہو؟\"، کہا: نہیں، فرمایا: \"بیٹھو\"، اتنے میں رسول اللہ صلی اللہ علیہ وسلم کے پاس کھجوروں کا ایک بڑا تھیلا آ گیا، آپ صلی اللہ علیہ وسلم نے اس سے فرمایا: \"انہیں صدقہ کر دو\"، کہنے لگا: اللہ کے رسول! مدینہ کی ان دونوں سیاہ پتھریلی پہاڑیوں کے بیچ ہم سے زیادہ محتاج کوئی گھرانہ ہے ہی نہیں، اس پر رسول صلی اللہ علیہ وسلم ہنسے یہاں تک کہ آپ کے سامنے کے دانت ظاہر ہو گئے اور فرمایا: \"اچھا تو انہیں ہی کھلا دو\"۔ مسدد کی روایت میں ایک دوسری جگہ «ثناياه» کی جگہ «أنيابه» ہے۔","صحیح",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ ایک شخص نبی کریم صلی اللہ علیہ وسلم کی خدمت میں آیا اور کہا: میں تو مارا گیا۔ آپ صلی اللہ علیہ وسلم نے پوچھا ” کیا ہوا؟ “ اس نے کہا: میں رمضان میں اپنی بیوی سے ہمبستر ہو بیٹھا ہوں۔ آپ صلی اللہ علیہ وسلم نے پوچھا ” کیا تو طاقت رکھتا ہے کہ ایک گردن آزاد کر سکے؟ “ اس نے کہا: نہیں۔ آپ صلی اللہ علیہ وسلم نے فرمایا ” کیا تو ہمت رکھتا ہے کہ دو ماہ متواتر روزے رکھے؟ “ اس نے کہا: نہیں۔ آپ صلی اللہ علیہ وسلم نے فرمایا ” کیا تجھے طاقت ہے کہ ساٹھ مسکینوں کو کھانا کھلا سکے؟ “ اس نے کہا: نہیں۔ آپ صلی اللہ علیہ وسلم نے فرمایا ” بیٹھ جاؤ۔ “ چنانچہ نبی کریم صلی اللہ علیہ وسلم کے پاس ایک ٹوکرا لایا گیا، اس میں کھجوریں تھیں۔ آپ صلی اللہ علیہ وسلم نے اس سے فرمایا ” ان کو صدقہ کر دہ۔ “ وہ کہنے لگا: اے اللہ کے رسول! مدینے کی دونوں پتھریلی زمینوں کے مابین ہم سے زیادہ اور کوئی فقیر نہیں ہے۔ رسول اللہ صلی اللہ علیہ وسلم ہنس پڑے حتیٰ کہ آپ کے اگلے دانت دکھائی دینے لگے۔ آپ صلی اللہ علیہ وسلم نے فرمایا ” گھر والوں ہی کو کھلا دو۔ “ ¤ مسدد نے اپنی روایت میں کہا کہ آپ کے نوکیلے دانت نظر آنے لگے۔"}],[2391,"اس سند سے بھی زہری سے اسی مفہوم کی حدیث مروی ہے اس میں زہری نے یہ الفاظ زائد کہے کہ یہ (کھجوریں اپنے اہل و عیال کو ہی کھلا دینے کا حکم) اسی شخص کے ساتھ خاص تھا اگر اب کوئی اس گناہ کا ارتکاب کرے تو اسے کفارہ ادا کئے بغیر چارہ نہیں۔ ابوداؤد کہتے ہیں: اسے لیث بن سعد، اوزاعی، منصور بن معتمر اور عراک بن مالک نے ابن عیینہ کی روایت کے ہم معنی روایت کیا ہے اور اوزاعی نے اس میں «واستغفر الله» \"اور اللہ سے بخشش طلب کر\" کا اضافہ کیا ہے۔","صحیح",{"u2":"جناب زہری نے یہ حدیث اسی مذکورہ معنی میں بیان کی اور مزید کہا کہ یہ اسی آدمی کے لیے رخصت تھی آج اگر کوئی یہ کام کر بیٹھے تو کفارے سے چارہ نہیں۔ ¤ امام ابوداؤد رضی اللہ عنہ نے کہا: اس روایت کو لیث بن سعد، اوزاعی، منصور بن معتمر اور عراک بن مالک نے سفیان بن عیینہ کی مانند بیان کیا۔ اوزاعی نے اپنی روایت میں یہ زیادہ کیا: ” اور اللہ سے استغفار بھی کر۔ “"}],[2392,"ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ ایک شخص نے رمضان میں روزہ توڑ دیا تو رسول اللہ صلی اللہ علیہ وسلم نے اسے ایک غلام آزاد کرنے، یا دو مہینے کا مسلسل روزے رکھنے، یا ساٹھ مسکینوں کو کھانا کھلانے کا حکم فرمایا، وہ شخص کہنے لگا کہ میں تو (ان میں سے) کچھ نہیں پاتا، آپ صلی اللہ علیہ وسلم نے اس سے فرمایا: \"بیٹھ جاؤ\"، اتنے میں رسول اللہ صلی اللہ علیہ وسلم کے پاس کھجوروں کا ایک تھیلا آ گیا، آپ صلی اللہ علیہ وسلم نے فرمایا: \"انہیں لے لو اور صدقہ کر دو\"، وہ کہنے لگا: اللہ کے رسول! مجھ سے زیادہ ضرورت مند تو کوئی ہے ہی نہیں، اس پر آپ صلی اللہ علیہ وسلم ہنس پڑے یہاں تک کہ آپ کے سامنے کے دانت نظر آنے لگے اور اس سے فرمایا: \"تم ہی اسے کھا جاؤ\"۔ ابوداؤد کہتے ہیں: اسے ابن جریج نے زہری سے مالک کی روایت کے الفاظ کے ساتھ روایت کیا ہے کہ ایک شخص نے روزہ توڑ دیا، اس میں ہے «أو تعتق رقبة أو تصوم شهرين أو تطعم ستين مسكينا» ۱؎۔\n§وضاحت\n۱؎ : یعنی غائب کے بجائے حاضر کے صیغے کے ساتھ اور بغیر «متتابعين» کے ہے۔","صحیح",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ سے مروی ہے کہ ایک آدمی نے رمضان میں روزہ توڑ لیا تو رسول اللہ صلی اللہ علیہ وسلم نے اسے حکم دیا کہ ایک گردن آزار کرے یا دو ماہ متواتر روزے رکھے یا ساٹھ مسکینوں کو کھانا کھلائے۔ اس نے کہا: میں (کسی کی بھی) طاقت نہیں رکھتا۔ تو رسول اللہ صلی اللہ علیہ وسلم نے اس سے فرمایا ” بیٹھ جاؤ۔ “ پھر آپ کے پاس ایک ٹوکرا لایا گیا، اس میں کھجوریں تھیں، آپ صلی اللہ علیہ وسلم نے فرمایا ” یہ لے جاؤ اور صدقہ کرو۔ “ وہ کہنے لگا: اے اللہ کے رسول! مجھ سے بڑھ کر اور کوئی محتاج نہیں ہے۔ تو آپ صلی اللہ علیہ وسلم ہنس پڑے حتیٰ کہ آپ کے نوکیلے دانت نظر آنے لگے اور اس سے فرمایا ” جاؤ کھا لو۔ “ ¤ امام ابوداؤد رضی اللہ عنہ فرماتے ہیں کہ ابن جریج نے زہری سے بالفاظ امام مالک روایت کیا اور کہا کہ ” ایک آدمی نے روزہ توڑ لیا۔ “ اور آپ نے اس سے فرمایا ” یا تو ایک گردن آزاد کرو یا دو ماہ روزے رکھو یا ساٹھ مسکینوں کو کھانا کھلاؤ۔ “","f2":"(1) رمضان کے دن میں جماع کرنے سے مندرجہ بالا تین کفارات میں سے ترتیب وار ایک لازم آتا ہے۔ یعنی اولا گردن آزاد کرنا، یہ نہ ہو سکے تو دو ماہ کے متواتر روزے رکھنا اور یہ بھی نہ ہو سکے تو ساٹھ مسکینوں کو کھانا کھلانا۔ اور استغفار سے کسی صورت غافل نہ ہو۔ اور جمہور علماء کا کہنا ہے کہ یہ کفارہ صرف جماع کی بنا پر آتا ہے نہ کہ کسی اور صورت میں روزہ توڑنے پر۔ جبکہ امام مالک اور امام ابوحنیفہ رحمة اللہ علیھم اور ان کے اصحاب کسی بھی صورت میں روزہ توڑنے پر مذکورہ کفارہ واجب کرتے ہیں۔ (2) یہ کفارہ ادا کرنے میں ترتیب کا لحاظ رکھا جائے کیونکہ رسول اللہ صلی اللہ علیہ وسلم نے پہلے کے عذر پر دوسرا اور پھر تیسرا کفارہ بتایا ہے۔ (3) مساکین کو کھانا کھلانے کی صورت میں ساٹھ کا عدد پورا کیا جائے، نہ کہ چند مساکین کو مختلف اوقات میں کھلا کر عدد پورا کرے۔ (4) اس واقعہ میں علماء کا اختلاف ہے۔ ایک جماعت کا رجحان ہے کہ مذکورہ صحابی کو فقر کی بنا پر کفارہ معاف فرما دیا تھا جبکہ دیگر کہتے ہیں کہ کفارہ کو وسعت پانے تک مؤخر کیا گیا تھا، بالکل معاف نہیں فرمایا تھا۔ واللہ اعلم"}],[2393,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ ایک شخص رسول اللہ صلی اللہ علیہ وسلم کے پاس حاضر ہوا اس نے رمضان میں روزہ توڑ دیا تھا، آگے اوپر والی حدیث کا ذکر ہے اس میں ہے: پھر آپ صلی اللہ علیہ وسلم کے پاس ایک بڑا تھیلا آیا جس میں پندرہ صاع کے بقدر کھجوریں تھیں، اور اس میں ہے کہ آپ صلی اللہ علیہ وسلم نے فرمایا: \"اسے تم اور تمہارے گھر والے کھاؤ، اور ایک دن کا روزہ رکھ لو، اور اللہ سے بخشش طلب کرو\"۔","صحیح",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ ایک شخص نبی کریم صلی اللہ علیہ وسلم کی خدمت میں آیا جس نے رمضان کے دن میں روزہ توڑ لیا تھا، اور مذکورہ بالا حدیث بیان کی۔ راوی نے کہا: پھر آپ صلی اللہ علیہ وسلم کے پاس ایک ٹوکرا لایا گیا، اس میں کھجور تھی تقریباً پندرہ صاع۔ اس روایت میں ہے۔ آپ صلی اللہ علیہ وسلم نے اس سے فرمایا ” تو اور تیرے گھر والے یہ کھا لیں اور تو ایک دن کا روزہ رکھ اور اللہ سے استغفار کر۔“","f2":"روزہ توڑنے پر قضا ادا کرنا واجب ہے۔ امام شافعی رحمة اللہ علیہ کا ایک قول ہے کہ اگر دو ماہ روزے رکھے تو قضا ادا کرنا نہیں ہے، لیکن گردن آزاد کرانے یا مساکین کو کھانا کھلانے کی صورت میں قضا ادا کرنا واجب ہے۔"}],[2394,"عباد بن عبداللہ بن زبیر کا بیان ہے کہ انہوں نے ام المؤمنین عائشہ رضی اللہ عنہا کو کہتے سنا کہ نبی اکرم صلی اللہ علیہ وسلم کے پاس ایک شخص رمضان میں مسجد کے اندر آیا اور کہنے لگا: اللہ کے رسول! میں تو بھسم ہو گیا، آپ صلی اللہ علیہ وسلم نے پوچھا کیا بات ہے؟ کہنے لگا: میں نے اپنی بیوی سے صحبت کر لی ہے، آپ صلی اللہ علیہ وسلم نے فرمایا: \"صدقہ کر دو\"، وہ کہنے لگا: اللہ کی قسم! میرے پاس صدقہ کرنے کے لیے کچھ بھی نہیں ہے، اور نہ میرے اندر استطاعت ہے، فرمایا: \"بیٹھ جاؤ\"، وہ بیٹھ گیا، اتنے میں ایک شخص غلے سے لدا ہوا گدھا ہانک کر لایا، آپ صلی اللہ علیہ وسلم نے فرمایا: \"ابھی بھسم ہونے والا کہاں ہے؟\" وہ شخص کھڑا ہو گیا، آپ صلی اللہ علیہ وسلم نے فرمایا: \"اسے صدقہ کر دو\"، بولا: اللہ کے رسول! کیا اپنے علاوہ کسی اور پر صدقہ کروں؟ اللہ کی قسم! ہم بھوکے ہیں، ہمارے پاس کچھ بھی نہیں، فرمایا: \"اسے تم ہی کھا لو\"۔","صحیح",{"u2":"ام المؤمنین سیدہ عائشہ رضی اللہ عنہا ا بیان کرتی ہیں کہ رمضان میں ایک شخص نبی کریم صلی اللہ علیہ وسلم کے پاس مسجد میں آیا اور کہا: اے اللہ کے رسول! میں تو جل گیا، نبی کریم صلی اللہ علیہ وسلم نے اس سے پوچھا ” کیا ہوا؟ “ اس نے کہا: میں نے اپنی بیوی سے جماع کر لیا ہے۔ آپ صلی اللہ علیہ وسلم نے فرمایا ” صدقہ کرو۔ “ کہنے لگا: اللہ کی قسم! میرے پاس کوئی چیز نہیں اور نہ میری یہ ہمت ہے۔ آپ صلی اللہ علیہ وسلم نے فرمایا ” بیٹھ جاؤ۔ “ وہ بیٹھ گیا۔ وہ اسی حالت میں تھا کہ ایک آدمی اپنا گدھا چلاتے ہوئے آیا، اس پر طعام تھا۔ تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” کہاں ہے وہ جو ابھی کہہ رہا تھا میں جل گیا؟ “ وہ کھڑا ہو گیا۔ آپ صلی اللہ علیہ وسلم نے فرمایا ” یہ صدقہ کر دو۔ “ کہنے لگا: اے اللہ کے رسول! کیا (اپنے علاوہ) دوسروں پر؟ قسم اللہ کی! ہم بھوکے ہیں، ہمارے پاس کچھ نہیں ہے۔ آپ صلی اللہ علیہ وسلم نے فرمایا ” (جاؤ) کھا لو۔ “","f2":"یہ دین و تقویٰ اور خشیت کا اثر تھا کہ یہ صحابی اس گناہ کو اپنے لیے جل جانے یا ہلاک ہونے سے تعبیر کر رہا تھا۔"}],[2395,"اس سند سے بھی ام المؤمنین عائشہ رضی اللہ عنہا سے یہی قصہ مروی ہے لیکن اس میں ہے کہ آپ صلی اللہ علیہ وسلم کے پاس ایک ایسا تھیلا لایا گیا جس میں بیس صاع کھجوریں تھیں۔","",{"u2":"عباد بن عبداللہ سیدہ عائشہ رضی اللہ عنہا ا سے اس قصے میں بیان کرتے ہیں کہ آپ صلی اللہ علیہ وسلم کے پاس ایک ٹوکرا لایا گیا اس میں بیس صاع (کھجور) تھی۔","f2":"گزشتہ حدیث: 2393 میں بیان کردہ مقدار پندرہ صاع ہی صحیح ہے۔"}],[2396,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جس نے رمضان میں بغیر کسی شرعی عذر کے ایک دن کا روزہ توڑ دیا تو اس کی قضاء زمانہ بھر کے روزے بھی نہیں کر سکیں گے\"۔","ضعیف",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” جو شخص رمضان میں روزہ توڑ دے، بغیر کسی رخصت کے جو اللہ نے دی ہے تو زمانہ بھر کے روزے بھی اس کی تلافی نہیں کر سکیں گے۔ “"}],[2397,"اس سند سے بھی ابوہریرہ رضی اللہ عنہ سے ابن کثیر اور سلیمان کی حدیث نمبر (۲۳۹۶) کے مثل مرفوعاً مروی ہے۔","ضعیف",{"u2":"عمارہ بن عمیر نے ابن مطؤس سے روایت کیا اور کہا کہ میں ابن مطؤس سے ملا تو اس نے مجھے اپنے والد سے، اس نے سیدنا ابوہریرہ رضی اللہ عنہ سے، انہوں نے نبی کریم صلی اللہ علیہ وسلم سے حدیث بیان کی جیسے کہ ابن کثیر اور سلیمان کی روایت (اوپر مذکور ہوئی) ہے۔ ¤ امام ابوداؤد رضی اللہ عنہ فرماتے ہیں کہ سفیان اور شعبہ کے شاگرد ان سے بیان کرنے میں مختلف ہیں۔ کچھ ” ابن مطؤس “ کہتے ہیں اور کچھ ” ابومطؤس۔ “","f2":"یہ روایت ضعیف ہے۔ اور اوپر حدیث:2392 کے فائدہ میں گزرا ہے کہ امام مالک اور امام ابوحنیفہ رحمة اللہ علیہ اور ان کے اصحاب کسی بھی صورت میں روزہ توڑ دینے پر کفارہ لازم گردانتے ہیں اور ان کا مستدل گزشتہ باب کی حدیث ہے، جبکہ دیگر ائمہ مذکورہ کفارہ کو صرف جماع سے خاص گردانتے ہیں۔ اور اصحاب الحدیث (محدثین) کا بھی یہی فتویٰ ہے۔"}],[2398,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم کی خدمت میں ایک شخص آیا اور اس نے عرض کیا: اللہ کے رسول! میں نے بھول کر کھا پی لیا، اور میں روزے سے تھا؟ تو آپ صلی اللہ علیہ وسلم نے فرمایا: \"تمہیں اللہ تعالی نے کھلایا پلایا\"۔","صحیح",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ سے منقول ہے کہ ایک آدمی نبی کریم صلی اللہ علیہ وسلم کی خدمت میں آیا اور کہا: اے اللہ کے رسول! میں نے روزہ رکھا ہوا تھا اور بھول کر کھا پی بیٹھا ہوں۔ آپ صلی اللہ علیہ وسلم نے فرمایا ” اللہ نے تمہیں کھلایا اور پلایا ہے۔ “","f2":"بھول کر کھا پی لے، تو معاف ہے۔ روزے میں کوئی فرق نہیں پڑتا، بغیر کسی شک و شبہ کے روزہ پورا کرنا چاہیے۔ اور یہ اللہ کا فضل و کرم ہے کہ اس کیفیت کو یوں تعبیر فرمایا کہ اللہ نے تمہیں کھلایا اور پلایا ہے۔"}],[2399,"ابوسلمہ بن عبدالرحمٰن سے روایت ہے کہ انہوں نے ام المؤمنین عائشہ رضی اللہ عنہا کو کہتے سنا: مجھ پر ماہ رمضان کی قضاء ہوتی تھی اور میں انہیں رکھ نہیں پاتی تھی یہاں تک کہ شعبان آ جاتا۔","صحیح",{"u2":"ام المؤمنین سیدہ عائشہ صدیقہ رضی اللہ عنہا ا بیان کرتی ہیں کہ مجھ پر رمضان کے روزے باقی ہوتے اور میں ان کی قضاء نہ کر پاتی تھی کہ شعبان آ جاتا۔","f2":"(1) رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں مشغولیت کے باعث انہیں موقع نہیں ملتا تھا کہ روزے رکھ سکیں حتی کہ شعبان آ جاتا اور اس میں رسول اللہ صلی اللہ علیہ وسلم کثرت سے روزے رکھتے تھے تو انہیں بھی قضا کرنے کا موقع مل جاتا تھا۔ (2) اس یقین پر کہ روزے کی قضا کرنے کا موقع مل جائے گا، تاخیر کرنا مباح ہے۔ (3) شوہر کی خدمت کا اہتمام کرنا بیوی کے فرائض میں شامل ہے۔ (4) اگر رمضان آ جائے اور قضا نہ کر سکے تو رمضان کے بعد قضا کرے۔ اس صورت میں کچھ صحابہ و تابعین وغیرہم کا قول ہے کہ قضا کرنے کے ساتھ ساتھ ہر دن کے بدلے ایک مسکین کو کھانا بھی کھلائے اور کچھ کہتے ہیں کہ سوائے قضا کرنے کے اور کچھ لازم نہیں ہے۔"}],[2400,"ام المؤمنین عائشہ رضی اللہ عنہا سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"جو شخص فوت ہو جائے اور اس کے ذمہ روزے ہوں تو اس کی جانب سے اس کا ولی روزے رکھے گا\"۔ ابوداؤد کہتے ہیں: یہ حکم نذر کے روزے کا ہے اور یہی احمد بن حنبل کا قول ہے۔","صحیح",{"u2":"ام المؤمنین سیدہ عائشہ صدیقہ رضی اللہ عنہا ا سے مروی ہے کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا ” جو کوئی فوت ہو جائے اور اس کے ذمے روزے رہتے ہوں تو اس کا ولی اس کی طرف سے روزے رکھے۔ “ ¤ امام ابوداؤد رضی اللہ عنہ نے کہا: یہ مسئلہ نذر کی صورت میں ہے اور امام احمد حنبل رضی اللہ عنہ کا بھی یہی قول ہے۔"}],[2401,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ جب آدمی رمضان میں بیمار ہو جائے پھر مر جائے اور روزے نہ رکھ سکے تو اس کی جانب سے کھانا کھلایا جائے گا اور اس پر قضاء نہیں ہو گی اور اگر اس نے نذر مانی تھی تو اس کا ولی اس کی جانب سے پورا کرے گا۔","صحیح",{"u2":"سیدنا ابن عباس رضی اللہ عنہ کا قول ہے کہ جب کوئی شخص رمضان میں بیمار ہوا اور پھر فوت ہو گیا اور روزے نہ رکھ سکا ہو تو اس کی طرف سے کھانا کھلا دیا جائے، اس پر قضاء نہیں ہے۔ اگر اس نے نذر مانی تھی تو اس کا ولی قضاء دے۔","f2":"(1) عام اصحاب الحدیث اس بات کے قائل ہیں کہ میت پر روزے باقی ہوں تو اس کا ولی روزے رکھے۔ (2) حضرت ابن عباس رضی اللہ عنہ اور بعض دیگر حجرات کا کہنا ہے کہ فرائض میں کوئی کسی کا نائب نہیں ہو سکتا۔ مریض نے اگر عمدا تقصیر نہیں کی اور وہ فوت ہو فیا تو ولی پر کچھ لازم نہیں صرف کھانا کھلا دے۔ لیکن نذر کا معاملہ اس لیے سخت ہے کہ اسے انسان نے از خود اپنے اوپر لازم کیا ہوتا ہے، اسی وجہ سے اسے اللہ کے قرض سے بھی تعبیر کیا گیا ہے۔"}],[2402,"ام المؤمنین عائشہ رضی اللہ عنہا سے روایت ہے کہ حمزہ اسلمی رضی اللہ عنہ نے نبی اکرم صلی اللہ علیہ وسلم سے سوال کیا: اللہ کے رسول! میں مسلسل روزے رکھتا ہوں تو کیا سفر میں بھی روزے رکھوں؟ آپ صلی اللہ علیہ وسلم نے فرمایا: \"چاہو تو رکھو اور چاہو تو نہ رکھو\"۔","صحیح",{"u2":"ام المؤمنین سیدہ عائشہ رضی اللہ عنہا ا سے مروی ہے کہ سیدنا حمزہ اسلمی رضی اللہ عنہ نے نبی کریم صلی اللہ علیہ وسلم سے سوال کیا: اے اللہ کے رسول! میں تسلسل سے روزے رکھا کرتا ہوں، تو کیا سفر میں روزہ رکھا کروں؟ آپ صلی اللہ علیہ وسلم نے فرمایا ” چاہو تو رکھ لو اور اگر چاہو تو افطار کر لو۔ “","f2":"جس سفر میں نماز قصر کرنا جائز ہے۔ اس میں مسافر کے لیے روزہ چھوڑنا بھی جائز ہے، خواہ سفر پیدل ہو یا سواری پر، اور سواری خواہ گاڑی ہو یا ہوائی جہاز وغیرہ، اور خواہ تھکاوٹ لاحق ہوتی ہو جس میں روزہ مشکل ہو یا تھکاوٹ لاحق نہ ہوتی ہو، خواہ سفر میں بھوک پیاس لگتی ہو یا نہ لگتی ہو۔ کیونکہ شریعت نے اس سفر میں نماز قصر کرنے اور روزہ چھوڑنے کی مطلقا اجازت دی ہے اور اس میں سواری کی نوعیت یا تھکاوٹ اور بھوک پیاس وغیرہ کی کوئی قید نہیں لگائی۔ صحابہ کرام رضی اللہ عنھم نے رمضان میں جہاد کے سلسلہ میں آپ کے ساتھ سفر کیا تو بعض نے روزہ رکھا اور بعض نے روزہ نہیں رکھا تھا۔اوراس کے بارے میں کسی نے بھی دوسرے پر کوئی اعتراض نہیں کیا تھا، البتہ اگر گرمی کی شدت، راستہ کی دشواری، دوری اور مسلسل سفر کی وجہ سے روزہ میں تکلیف ہو تو پھر مسافر کے لیے تاکید کے ساتھ حکم یہ ہے کہ وہ روزہ نہ رکھے، جیسا کہ حضرت انس رضی اللہ عنہ سے مروی ہے کہ ہم رسول اللہ صلی اللہ علیہ وسلم کے ساتھ ایک سفر میں تھے، ہم میں سے بعض لوگوں نے روزہ رکھا اور بعض نے روزہ نہیں رکھا، روزہ نہ رکھنے والے ہشاش بشاش تھے اور انہوں نے کام کیا جب کہ روزہ رکھنے والے کمزوور ہو گئے تھے اور وہ بعض کام نہ کر سکے، تو نبی کریم صلی اللہ علیہ وسلم نے فرمایا: آج تو روزہ نہ رکھنے والوں نے اجروثواب حاصل کر لیا۔ (صحيح البخاري‘ الجهاد‘ حديث: 2890‘ وصحيح مسلم‘ الصيام‘ حديث:119) کبھی کسی ہنگامی حالت کی وجہ سے یہ واجب بھی ہو جاتا ہے کہ سفر میں روزہ نہ رکھا جائے جیسا کہ حضرت ابوسعید خدری رضی اللہ عنہ سے مروی ہے کہ ہم نے رسول اللہ صلی اللہ علیہ وسلم کے ساتھ مکہ کی طرف سفر کیا اور جب ایک جگہ پڑاؤ ڈالا تو آپ نے فرمایا: تم اپنے دشمن کے بہت قریب ہو گئے ہو اور روزہ چھوڑ دینا تمہارے لیے باعث تقویت ہو گا۔ یہ ایک رخصت تھی اس لیے ہم میں سے کچھ لوگوں نے روزہ رکھا اور کچھ نے نہ رکھا، پھر ہم نے جب ایک دوسری منزل پر پڑاؤ ڈالا تو آپ نے فرمایا: تمہاری دشمن سے مڈبھیڑ ہونے والی ہے، روزہ نہ رکھنا تمہارے لیے باعث تقویت ہو گا۔ لہذا چھوڑ دو۔ (صحيح مسلم‘ الصيام‘ حديث:1120) چونکہ آپ کی طرف سے یہ ایک تاکیدی حکم تھا اس لیے ہم سب نے روزہ چھوڑ دیا، راوی حدیث کا بیان ہے کہ اس کے بعد ہم نے رسول اللہ صلی اللہ علیہ وسلم کے ساتھ سفر میں روزے رکھے بھی تھے۔ اسی طرح حضرت جابر رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے ایک سفر میں ایک آدمی کو دیکھا جس پر لوگ جمع ہوئے تھے اور اس پر سایہ کیا گیا تھا تو آپ نے فرمایا، کیا ماجرا ہے؟ لوگوں نے بتایا کہ یہ ایک روزے دار ہے تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: یہ کوئی نیکی نہیں ہے کہ تم سفر میں روزہ رکھو۔ (صحيح مسلم‘ الصيام‘ حديث: 1115) نیز آپ صلی اللہ علیہ وسلم فرمایا: اللہ تعالیٰ فرماتا ہے کہ اس کی عطا کردہ رخصتوں کو قبول کر لیا جائے جس طرح وہ اس بات کو ناپسند کرتا ہے کہ اس کی معصیت و نافرمانی کا ارتکاب کیا جائے۔ (مسند احمد:3/108) اگر روزہ رکھنے میں کوئی تکلیف نہ ہو اور کوئی روزہ رکھ لے تو اس میں کوئی حرج نہیں اور اگر تکلیف ہو تو پھر روزہ رکھنا مکروہ ہے۔"}],[2403,"حمزہ اسلمی رضی اللہ عنہ کہتے ہیں کہ میں نے پوچھا: اللہ کے رسول! میں سواریوں والا ہوں، انہیں لے جایا کرتا ہوں، ان پر سفر کرتا ہوں اور انہیں کرایہ پر بھی دیتا ہوں، اور بسا اوقات مجھے یہی مہینہ یعنی رمضان مل جاتا ہے اور میں جوان ہوں اپنے اندر روزہ رکھنے کی طاقت پاتا ہوں، میں یہ بھی سوچتا ہوں کہ روزہ مؤخر کرنے سے آسان یہ ہے کہ اسے رکھ لیا جائے، تاکہ بلاوجہ قرض نہ بنا رہے، اللہ کے رسول! میرے لیے روزہ رکھنے میں زیادہ ثواب ہے یا چھوڑ دینے میں؟ آپ صلی اللہ علیہ وسلم نے فرمایا: \"حمزہ! جیسا بھی تم چاہو\"۔","ضعیف",{"u2":"جناب حمزہ بن محمد حمزہ اسلمی بیان کرتے ہیں کہ اس کے والد نے اس کے دادا سے بیان کیا (کہ حمزہ اسلمی رضی اللہ عنہ نے) کہا: اے اللہ کے رسول! میں نے سواری کے جانور رکھے ہوئے ہیں۔ میرا کام انہی سے متعلق ہے، سفر میں رہتا ہوں، جانور کرائے پر چلاتا ہوں اور بسا اوقات یہ رمضان کا مہینہ بھی آ جاتا ہے اور میں اپنے اندر طاقت پاتا ہوں اور جوان ہوں۔ اے اللہ کے رسول! میں روزے مؤخر کرنے کی بجائے رکھ لینا زیادہ آسان سمجھتا ہوں، ورنہ میرے ذمے رہ جائیں گے تو اے اللہ کے رسول! مجھے روزہ رکھنے میں زیادہ اجر ہے یا افطار کرنے میں؟ آپ صلی اللہ علیہ وسلم نے فرمایا ” حمزہ! جو چاہو کر سکتے ہو۔ “","f2":"(1) یہ باب اور عنوان ابوداود کے اکثر نسخوں میں نہیں ہے۔ بہرحال اس کا مطلب بھی گزشتہ باب والا ہی ہے، یعنی وہ تاجر، جو اکثر سفر میں رہتا ہے، روزہ چھوڑ سکتا ہے، بعد میں ان کی قضا کر لے۔ (2) مسئلہ اسی طرح ہے جیسے کہ دیگر صحیح احادیث سے ثابت ہے۔"}],[2404,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم مدینہ سے مکہ کے لیے نکلے یہاں تک کہ مقام عسفان پر پہنچے، پھر آپ صلی اللہ علیہ وسلم نے (پانی وغیرہ کا) برتن منگایا اور اسے اپنے منہ سے لگایا تاکہ آپ اسے لوگوں کو دکھا دیں (کہ میں روزے سے نہیں ہوں) اور یہ رمضان میں ہوا، اسی لیے ابن عباس رضی اللہ عنہما کہتے تھے کہ نبی اکرم صلی اللہ علیہ وسلم نے روزہ بھی رکھا ہے اور افطار بھی کیا ہے، تو جو چاہے روزہ رکھے اور جو چاہے نہ رکھے۔","صحیح",{"u2":"سیدنا ابن عباس رضی اللہ عنہ بیان کرتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم مدینے سے مکہ کی طرف روانہ ہوئے حتیٰ کہ مقام غسفان پر پہنچ گئے، پھر آپ صلی اللہ علیہ وسلم نے برتن منگوایا اور اسے اپنے منہ کی طرف بلند کیا تاکہ لوگ آپ صلی اللہ علیہ وسلم کو دیکھ لیں (کہ آپ صلی اللہ علیہ وسلم افطار کر رہے ہیں) اور یہ رمضان کا واقعہ ہے۔ چنانچہ ابن عباس رضی اللہ عنہ فرمایا کرتے تھے کہ بلاشبہ نبی کریم صلی اللہ علیہ وسلم نے روزہ رکھا ہے اور چھوڑا بھی، سو جو چاہے رکھ لے اور جو چاہے افطار کر لے۔","f2":"(1) یہ واقعہ فتح مکہ کے سفر کا ہے۔ (2) اس حدیث سے معلوم ہوا کہ جس شخص نے سفر میں صبح کو روزے کی نیت کی ہو تو شرعی عذر سے کسی وقت اگر وہ افطار کرنا چاہے تو کر سکتا ہے۔"}],[2405,"انس رضی اللہ عنہ کہتے ہیں کہ ہم نے رسول اللہ صلی اللہ علیہ وسلم کے ہمراہ رمضان میں سفر کیا تو ہم میں سے بعض لوگوں نے روزہ رکھا اور بعض نے نہیں رکھا تو نہ تو روزہ توڑنے والوں نے، روزہ رکھنے والوں پر عیب لگایا، اور نہ روزہ رکھنے والوں نے روزہ توڑنے والوں پر عیب لگایا۔","صحیح",{"u2":"سیدنا انس رضی اللہ عنہ سے منقول ہے انہوں نے کہا کہ ہم نے رمضان میں رسول اللہ صلی اللہ علیہ وسلم کے ساتھ سفر کیا تو ہم میں سے کچھ نے روزہ رکھا اور کچھ نے نہ رکھا۔ چنانچہ روزے داروں نے چھوڑنے والوں پر یا چھوڑنے والوں نے روزے داروں پر کوئی عیب نہ لگایا۔"}],[2406,"قزعہ کہتے ہیں کہ میں ابو سعید خدری رضی اللہ عنہ کے پاس آیا اور وہ لوگوں کو فتوی دے رہے تھے، اور لوگ ان پر جھکے جا رہے تھے تو میں تنہائی میں ملاقات کی غرض سے انتظار کرتا رہا، جب وہ اکیلے رہ گئے تو میں نے سفر میں رمضان کے مہینے کے روزے کا حکم دریافت کیا، انہوں نے کہا: ہم فتح مکہ کے سال رمضان میں رسول اللہ صلی اللہ علیہ وسلم کے ہمراہ سفر پر نکلے، سفر میں اللہ کے رسول بھی روزے رکھتے تھے اور ہم بھی، یہاں تک کہ جب منزلیں طے کرتے ہوئے ایک پڑاؤ پر پہنچے تو آپ صلی اللہ علیہ وسلم نے فرمایا: \"اب تم دشمن کے بالکل قریب آ گئے ہو، روزہ چھوڑ دینا تمہیں زیادہ توانائی بخشے گا\"، چنانچہ دوسرے دن ہم میں سے کچھ لوگوں نے روزہ رکھا اور کچھ نے نہیں رکھا، پھر ہمارا سفر جاری رہا پھر ہم نے ایک جگہ قیام کیا تو آپ صلی اللہ علیہ وسلم نے فرمایا: \"صبح تم دشمن کے پاس ہو گے اور روزہ نہ رکھنا تمہارے لیے زیادہ قوت بخش ہے، لہٰذا روزہ چھوڑ دو\"، یہ رسول اللہ صلی اللہ علیہ وسلم کی طرف سے تاکید تھی۔ ابوسعید کہتے ہیں: پھر میں نے رسول اللہ صلی اللہ علیہ وسلم کے ساتھ اس سے پہلے بھی روزے رکھے اور اس کے بعد بھی۔","صحیح",{"u2":"قزعہ بیان کرتے ہیں کہ میں سیدنا ابو سعید خدری رضی اللہ عنہ کی خدمت میں حاضر ہوا جب کہ وہ لوگوں کے سوالوں کے جواب دے رہے تھے اور لوگ ان پر جھکے ہوئے تھے۔ میں نے بھیڑ کے چھٹ جانے کا انتظار کیا۔ جب وہ اکیلے ہو گئے تو میں نے ان سے سفر میں رمضان کے روزوں کے متعلق دریافت کیا تو انہوں نے کہا کہ فتح مکہ کے سال ہم نبی کریم صلی اللہ علیہ وسلم کے ساتھ روانہ ہوئے۔ آپ صلی اللہ علیہ وسلم نے روزے رکھے ‘ تو ہم بھی رکھتے رہے حتیٰ کہ ایک منزل پر پہنچے، تو آپ صلی اللہ علیہ وسلم نے فرمایا ” تم لوگ اب اپنے دشمن کے قریب آ گئے ہو اور افطار کرنا تمہارے لیے زیادہ قوت کا باعث ہے۔ “ تو ہم میں سے کچھ نے روزہ رکھا اور کچھ نے افطار کر لیا۔ پھر ہم چلے اور ایک منزل پر پڑاؤ کیا تو آپ صلی اللہ علیہ وسلم نے فرمایا ” تم لوگ صبح کو اپنے دشمن کے مقابل آنے والے ہو اور افطار کرنا تمہارے لیے زیادہ قوت کا باعث ہے، سو افطار کر لو۔ “ چنانچہ یہ حکم رسول اللہ صلی اللہ علیہ وسلم کی طرف سے تاکیدی تھا۔ ابوسعید رضی اللہ عنہ نے کہا: مجھے یاد ہے کہ میں نے نبی کریم صلی اللہ علیہ وسلم کے ساتھ اس سے پہلے روزے رکھے ہیں اور بعد میں بھی۔","f2":"(1) سفر میں روزے رکھنا یا نہ رکھنا ہر شخص کے احوال اور اس کی اپنی ترجیح پر مبنی ہے۔ (2) صحابہ کرام نبی صلی اللہ علیہ وسلم کے ارشادات کی حقیقت کو خوب سمجھتے تھے کہ کون سا ارشاد ترغیب محض ہے اور کون سا عزیمت۔ امر عزیمت میں نبی صلی اللہ علیہ وسلم کی مخالفت کسی بھی طرح روا نہیں۔ اسی لیے کہا جاتا ہے کہ استنباط و اجتہاد علمائے راسخین کا کام ہے۔ فتاویٰ کے لیے انہی کی طرف رجوع کرنا چاہیے جو فہم قرآن و سنت کا کامل ملکہ رکھتے ہوں۔"}],[2407,"جابر بن عبداللہ رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے ایک شخص کو دیکھا جس پر سایہ کیا جا رہا تھا اور اس پر بھیڑ لگی تھی تو آپ صلی اللہ علیہ وسلم نے فرمایا: \"سفر میں روزہ رکھنا کوئی نیکی کا کام نہیں\"۔","صحیح",{"u2":"سیدنا جابر بن عبداللہ رضی اللہ عنہ کا بیان ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے دیکھا ایک شخص کو سایہ کیا جا رہا ہے اور لوگ اس پر ازدحام کیے ہوئے ہیں۔ (روزے اور گرمی کے باعث وہ غش کھا گیا تھا) تو آپ صلی اللہ علیہ وسلم نے فرمایا ” سفر میں روزہ رکھنا کوئی نیکی کا کام نہیں ہے۔ “","f2":"جو شخص سفر میں روزے کی مشقت کا متحمل نہ ہو اور اسے روزے سے اذیت ہوتی ہو، تو اس کے لیے افطار کرنا واجح اور افضل ہے۔ ورنہ خود نبی صلی اللہ علیہ وسلم اور صحابہ کرام رضی اللہ عنھم سے روزہ رکھنا بھی ثابت ہے۔"}],[2408,"انس بن مالک ۱؎ رضی اللہ عنہ سے روایت ہے (جو بنی قشیر کے برادران بنی عبداللہ بن کعب کے ایک فرد ہیں) وہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم کے گھوڑ سوار دستے نے ہم پر حملہ کیا، میں اللہ کے رسول صلی اللہ علیہ وسلم کے پاس پہنچا، یا یوں کہا کہ میں رسول اللہ صلی اللہ علیہ وسلم کی طرف چلا، آپ کھانا تناول فرما رہے تھے، آپ صلی اللہ علیہ وسلم نے فرمایا: \"بیٹھو، اور ہمارے کھانے میں سے کچھ کھاؤ\"، میں نے کہا: میں روزے سے ہوں، آپ صلی اللہ علیہ وسلم نے فرمایا: \"اچھا بیٹھو، میں تمہیں نماز اور روزے کے بارے میں بتاتا ہوں: اللہ نے (سفر میں) نماز آدھی کر دی ہے، اور مسافر، دودھ پلانے والی، اور حاملہ عورت کو روزہ رکھنے کی رخصت دی ہے\"، قسم اللہ کی! آپ صلی اللہ علیہ وسلم نے دونوں کا ذکر کیا یا ان دونوں میں سے کسی ایک کا، مجھے رسول اللہ صلی اللہ علیہ وسلم کے کھانے میں سے نہ کھا پانے کا افسوس رہا۔\n§وضاحت\n۱؎ : یہ انس بن مالک رضی اللہ عنہ رسول اللہ صلی اللہ علیہ وسلم کے خادم خاص کے علاوہ ہیں۔","حسن صحیح",{"u2":"سیدنا انس بن مالک رضی اللہ عنہ (کعبی) سے روایت ہے اور یہ بنی عبداللہ بن کعب کے خاندان سے ہیں جو کہ بنی قشیر کے بھائی تھے۔ (انس بن مالک رضی اللہ عنہ جو نبی کریم صلی اللہ علیہ وسلم کے خادم تھے وہ خزرجی انصاری ہیں) (کہا) کہ رسول اللہ صلی اللہ علیہ وسلم کے سواروں نے ہم پر حملہ کر دیا تو میں رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں پہنچا اور (دیکھا کہ) آپ کچھ تناول فر رہے ہیں۔ آپ نے فرمایا ” آؤ! بیٹھو اور ہمارے اس طعام میں سے کچھ کھا لو۔ “ میں نے عرض کیا: میں روزے سے ہوں۔ آپ نے فرمایا ” بیٹھ جاؤ میں تمہیں نماز اور روزے کے متعلق بتاتا ہوں۔ ا اللہ نے مسافر سے آدھی نماز اور روزہ معاف فر دیا ہے اور دودھ پلانے والی اور حاملہ عورت سے بھی روزہ معاف کر دیا ہے۔ “ قسم ا اللہ کی! آپ نے ان دونوں کا ذکر فرمایا تھا یا کسی ایک کا۔ بیان کرتے ہیں کہ مجھے (بعد میں) بہت افسوس ہوا کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کے کھانے میں سے کیوں نہ کھایا۔ (کیونکہ آپ کے ساتھ مل کر کھانا سعادت اور باعث برکت تھا اور روزہ نفل محض۔)","f2":"مسافر، بچے کو دودھ پلانے والی اور حاملہ کے لیے رعایت ایک ہی سیاق میں ذکر ہوئی ہے مگر تفصیل میں فرق ہے کہ مسافر کو روزہ معاف ہے مگر قضا کرنا واجب ہے۔ اور مُرضِعَہ (دودھ پلانے والی) اور حاملہ کی بابت علماء کی چار آراء ہیں، جس کی مختصر تفصیل حدیث نمبر: 2318 کے فوائد میں گزری ہے۔ تاہم ان عورتوں کو ایام اقامت میں پوری نماز پڑھنی ہوتی ہے۔ شرعی عذر (حیض و نفاس) میں نماز بالکل معاف ہے اور اس کی کوئی قضا نہیں۔"}],[2409,"ابو الدرداء رضی اللہ عنہ کہتے ہیں کہ ہم رسول اللہ صلی اللہ علیہ وسلم کے ہمراہ کسی غزوے میں نکلے، گرمی اس قدر شدید تھی کہ شدت کی وجہ سے ہم میں سے ہر شخص اپنا ہاتھ یا اپنی ہتھیلی اپنے سر پر رکھ لیتا، اس موقعے پر رسول اللہ صلی اللہ علیہ وسلم اور عبداللہ بن رواحہ رضی اللہ عنہ کے علاوہ ہم میں سے کوئی بھی روزے سے نہ تھا۔","صحیح",{"u2":"سیدنا ابو الدرداء رضی اللہ عنہ سے مروی ہے کہ ہم ایک بار سخت گرمی میں رسول اللہ صلی اللہ علیہ وسلم کے ساتھ کسی غزوے کے لیے روانہ ہوئے۔ گرمی اتنی تھی کہ ہر ایک اپنا ہاتھ یا اپنی ہتھیلی اپنے سر پر رکھے ہوئے تھا۔ اور ہم میں سے رسول اللہ صلی اللہ علیہ وسلم اور عبداللہ بن رواحہ کے سوا اور کوئی روزے دار نہ تھا۔"}],[2410,"سلمہ بن محبق ہذلی رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جس کے پاس منزل پر ایسی سواری ہو جو اسے ایسی جگہ پہنچا سکے جہاں اسے راحت و آسودگی ملے تو وہ جہاں بھی رمضان کا مہینہ پا لے روزے رکھے\"۔","ضعیف",{"u2":"جناب سنان بن سلمہ بن محبق ہذلی اپنے والد سے بیان کرتے ہیں انہوں نے کہا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” جس کے پاس سواری ہو کہ (اسے آرام سے منزل پر پہنچا دے اور) پیٹ بھر کر کھانا وغیرہ مل جائے تو اسے چاہیئے کہ رمضان کے روزے رکھے ‘ جہاں بھی آ جائے۔ “"}],[2411,"سلمہ بن محبق رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"حالت سفر میں رمضان جسے پا لے …\"، پھر راوی نے اسی مفہوم کی حدیث ذکر کی۔","ضعیف",{"u2":"سیدنا سلمہ بن محبق رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” جسے رمضان آ پہنچے اور وہ سفر میں ہو تو۔“ اور مذکورہ بالا کے ہم معنی حدیث بیان کی۔","f2":"مذکورہ دونوں حدیثیں ضعیف ہیں۔ قرآن مجید میں صراحت ہے کہ سفر کے دوران میں روزہ نہ رکھنے کی رخصت ہے، بعد میں قضا دے۔"}],[2412,"عبید بن جبر کہتے ہیں کہ میں نبی اکرم صلی اللہ علیہ وسلم کے صحابی ابو بصرہ غفاری رضی اللہ عنہ کے ہمراہ رمضان میں ایک کشتی میں تھا جو فسطاط شہر کی تھی، کشتی پر بیٹھے ہی تھے کہ صبح کا کھانا آ گیا، (جعفر کی روایت میں ہے کہ) شہر کے گھروں سے ابھی آگے نہیں بڑھے تھے کہ انہوں نے دستر خوان منگوایا اور کہنے لگے: نزدیک آ جاؤ، میں نے کہا: کیا آپ (شہر کے) گھروں کو نہیں دیکھ رہے ہیں؟ (ابھی تو شہر بھی نہیں نکلا اور آپ کھانا کھا رہے ہیں) کہنے لگے: کیا تم رسول اللہ صلی اللہ علیہ وسلم کی سنت سے اعراض کرتے ہو؟ (جعفر کی روایت میں ہے) تو انہوں نے کھانا کھایا۔","صحیح",{"u2":"عبید بن جبر کہتے ہیں کہ میں صحابی رسول سیدنا ابو بصرہ غفاری رضی اللہ عنہ کے ہمراہ تھا۔ ہم ماہ رمضان میں فسطاط سے کشتی میں سوار ہوئے۔ جب لنگر اٹھا لیا گیا تو انہیں ان کا صبح کا کھانا پیش کیا گیا۔ جعفر بن مسافر نے اپنی روایت میں کہا۔ ابھی گھروں سے دور بھی نہ ہوئے تھے کہ انہوں نے اپنا دستر خواں طلب کیا اور کہا کہ قریب ہو جاؤ۔ میں (عبید) نے کہا: کیا آپ گھروں کو نہیں دیکھ رہے؟ جناب ابو بصرہ نے کہا: کیا تم سنت رسول اللہ صلی اللہ علیہ وسلم سے اغراض کرنا چاہتے ہو؟ جعفر نے بیان کیا، چنانچہ انہوں نے کھانا کھایا۔","f2":"سفر شروع ہوتے ہی افطار کر لینا جائز ہے۔ گھروں سے دور ہونا کوئی ضروری نہیں۔ حسن بصری رحمة اللہ علیہ کہتے ہیں کہ گھر ہی میں افطار کر سکتا ہے۔ اسحٰق بن راہویہ رحمة اللہ علیہ کہتے ہیں جب اپنا پاؤں رکاب میں رکھے تو افطار کر لے۔"}],[2413,"منصور کلبی سے روایت ہے کہ دحیہ بن خلیفہ کلبی رضی اللہ عنہ ایک بار رمضان میں دمشق کی کسی بستی سے اتنی دور نکلے جتنی دور فسطاط سے عقبہ بستی ہے اور وہ تین میل ہے، پھر انہوں نے اور ان کے ساتھ کے کچھ لوگوں نے تو روزہ توڑ دیا لیکن کچھ دوسرے لوگوں نے روزہ توڑنے کو ناپسند کیا، جب وہ اپنی بستی میں لوٹ کر آئے تو کہنے لگے: اللہ کی قسم! آج میں نے ایسا منظر دیکھا جس کا میں نے کبھی گمان بھی نہیں کیا تھا، لوگوں نے رسول اللہ صلی اللہ علیہ وسلم اور صحابہ کرام کے طریقے سے اعراض کیا، یہ بات وہ ان لوگوں کے متعلق کہہ رہے تھے، جنہوں نے سفر میں روزہ رکھا تھا، پھر انہوں نے اسی وقت دعا کی: اے اللہ! مجھے اپنی طرف اٹھا لے (یعنی اس پر آشوب دور میں زندہ رہنے سے موت اچھی ہے) ۔","ضعیف",{"u2":"منصور کلبی بیان کرتے ہیں کہ سیدنا دحیہ بن خلیفہ کلبی رضی اللہ عنہ ایک بار رمضان میں دمشق کی ایک بستی سے روانہ ہوئے اور اس قدر فاصلے پر گئے جو عقبہ سے فسطاط تک کے مابین ہے اور ان میں تین میل کا فاصلہ ہے۔ پھر انہوں نے افطار کر لیا اور ان کے ساتھ لوگوں نے بھی کر لیا جبکہ کچھ دوسروں نے افطار کرنے کو ناپسند کیا۔ پھر جب اپنی بستی میں واپس آئے تو کہا: قسم ا اللہ کی! میں نے آج ایک ایسی بات دیکھی ہے جس کا مجھے گمان بھی نہیں تھا کہ ایک قوم رسول اللہ صلی اللہ علیہ وسلم اور آپ کے اصحاب کی سنت سے اعراض کرے گی۔ وہ یہ بات ان لوگوں کے بارے میں کہہ رہے تھے جو روزے سے رہے (اور افطار نہ کیا) پھر اس موقع پر (دعا کرتے ہوئے) کہا: اے ا اللہ! مجھے اپنی طرف اٹھا لے۔"}],[2414,"نافع سے روایت ہے کہ ابن عمر رضی اللہ عنہما غابہ ۱؎ جاتے تو نہ تو روزہ توڑتے، اور نہ ہی نماز قصر کرتے۔\n§وضاحت\n۱؎ : غابہ ایک جگہ ہے جو مدینہ سے تھوڑی دور کے فاصلہ پر شام کے راستے میں پڑتا ہے۔","صحیح موقوف",{"u2":"جناب نافع رضی اللہ عنہ سے مروی ہے کہ سیدنا ابن عمر رضی اللہ عنہ غابہ کی طرف تشریف لے جاتے تو اس سفر میں نہ افطار کرتے اور نہ قصر۔","f2":"(غابه) مدینے سے شام کی طرف بالائی جانب ایک جگہ کا نام ہے جو تقریبا ایک برید (چار فرسخ/تقریبا 22 کلو میٹر) دور ہے۔ اتنی مسافت پر قصر جائز ہے اور افطار بھی جائز ہے، لیکن اگر کوئی شخص قصر کرتا ہے نہ افطار، تو یہ بھی جائز ہے۔ کیونکہ قصر و افطار فرض نہیں ہے، بلکہ ایک رخصت ہے، جس سے فائدہ اٹھانا افضل ہے، لیکن فرض وواجب بہرحال نہیں ہے۔"}],[2415,"ابوبکرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"تم میں سے کوئی یہ نہ کہے کہ میں نے پورے رمضان کے روزے رکھے، اور پورے رمضان کا قیام کیا\"۔ راوی حدیث کہتے ہیں: مجھے معلوم نہیں کہ آپ صلی اللہ علیہ وسلم کی یہ ممانعت خود اپنے آپ کو پاکباز و عبادت گزار ظاہر کرنے کی ممانعت کی بنا پر تھی، یا اس وجہ سے تھی کہ وہ لازمی طور پر کچھ نہ کچھ سویا ضرور ہو گا (اس طرح یہ غلط بیانی ہو جائے گی) ۔","ضعیف",{"u2":"سیدنا ابوبکرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” تم میں سے کوئی شخص ہرگز یوں نہ کہے کہ میں نے سارا رمضان روزے رکھے اور میں نے سارے رمضان کا قیام کیا۔ “ کہتے ہیں مجھے معلوم نہیں آپ نے نیکی کو نمایاں کرنا مکروہ جانا یا یہ بتانا چاہا کہ بندہ اس دوران میں لازمی طور پر سوتا بھی رہا ہے۔ (تو سارا رمضان صیام و قیام کیونکر ہو گیا؟)۔","f2":"قرآن مجید میں ہے: (فَلَا تُزَكُّوٓا۟ أَنفُسَكُمْ ۖ هُوَ أَعْلَمُ بِمَنِ ٱتَّقَىٰٓ) (النجم:32) اپنی نیکیاں اور خوبیاں مت بیان کرو، وہ (اللہ تعالیٰ) تقویٰ والوں کو خوب جانتا ہے۔ یہ حدیث ضعیف ہے۔ اس لیے اگر مقصود اپنی بڑائی کا اظہار اور اپنی پاکیزگی کا اعلان نہ ہو تو حکایت کے طور پر اس کا بیان جائز ہے۔"}],[2416,"ابو عبید کہتے ہیں کہ میں عمر رضی اللہ عنہ کے ساتھ عید میں حاضر ہوا، انہوں نے خطبے سے پہلے نماز پڑھائی پھر انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے ان دونوں دنوں میں روزہ رکھنے سے منع فرمایا ہے: عید الاضحی کے روزے سے تو اس لیے کہ تم اس میں اپنی قربانیوں کا گوشت کھاتے ہو، اور عید الفطر کے روزے سے اس لیے کہ تم اپنے روزوں سے فارغ ہوتے ہو۔","صحیح",{"u2":"ابو عبید کہتے ہیں کہ میں عید کے روز سیدنا عمر رضی اللہ عنہ کے ہاں حاضر تھا۔ آپ نے پہلے نماز پڑھائی پھر خطبہ دیا اور کہا: رسول اللہ صلی اللہ علیہ وسلم نے (عید کے) ان دو دنوں میں روزے سے منع فرمایا ہے۔ قربانی کے دن میں تم اپنی قربانیوں کے گوشت کھاتے ہو اور عید الفطر میں تم روزوں سے فارغ ہوتے ہو۔"}],[2417,"ابو سعید خدری رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے دو دنوں کے روزوں سے منع فرمایا: ایک عید الفطر کے دوسرے عید الاضحی کے، اسی طرح دو لباسوں سے منع فرمایا ایک صمّاء ۱؎ دوسرے ایک کپڑے میں احتباء ۲؎ کرنے سے (جس سے ستر کھلنے کا اندیشہ رہتا ہے) نیز دو وقتوں میں نماز پڑھنے سے منع فرمایا: ایک فجر کے بعد، دوسرے عصر کے بعد۔\n§وضاحت\n۱؎ : «صماء» کی صورت یہ ہے کہ آدمی پورے جسم پر کپڑا لپیٹ لے جس میں کوئی ایسا شگاف نہ ہو کہ ہاتھ باہر نکال سکے اور اپنے ہاتھ سے کوئی موذی چیز دفع کر سکے۔ ۲؎ : «احتباء» کی صورت یہ ہے کہ دونوں پاؤں کھڑا رکھے ، انہیں پیٹ سے ملائے رکھے، اور دونوں سرین پر بیٹھے اور کپڑے سے دونوں پاؤں اور پیٹ باندھ لے یا ہاتھوں سے حلقہ دے لے۔","صحیح",{"u2":"سیدنا ابو سعید خدری رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے دو دنوں کے روزوں سے منع فرمایا ہے ‘ یعنی عید الفطر اور عید الاضحی کے دنوں میں۔ اور دو طرح سے کپڑے لپیٹنے سے روکا ہے۔ ایک یوں کہ کوئی پوری طرح سے کپڑے میں ایسے لپٹ جائے کہ کوئی عضو بھی اس سے باہر نہ رہے۔ اور دوسری صورت یوں کہ اپنے اوپر کپڑا لپیٹ کر اس طرح بیٹھے کہ ایک جانب سے شرمگاہ کو ننگا کر دے۔ اور دو وقت میں نماز پڑھنے سے بھی منع فرمایا ہے یعنی نماز فجر اور نماز عصر کے بعد۔","f2":"(1) عید کے دنوں میں روزہ رکھنا حرام ہے۔ (2) نماز فجر اور عصر کے بعد نوافل پڑھنا ناجائز ہے، لیکن کوئی قضا نماز پڑھنی ہو یا کوئی سببی نماز ہو تو بعض کے نزدیک مباح ہے بشرطیکہ سورج نکلنے یا غروب ہونے والا نہ ہو۔"}],[2418,"ام ہانی رضی اللہ عنہا کے غلام ابو مرہ سے روایت ہے کہ وہ عبداللہ بن عمرو رضی اللہ عنہما کے ہمراہ ان کے والد عمرو بن العاص رضی اللہ عنہ کے پاس گئے تو انہوں نے دونوں کے لیے کھانا پیش کیا اور کہا کہ کھاؤ، تو عبداللہ بن عمرو رضی اللہ عنہما نے کہا: \"میں تو روزے سے ہوں\"، اس پر عمرو رضی اللہ عنہ نے کہا: کھاؤ کیونکہ رسول اللہ صلی اللہ علیہ وسلم ہمیں ان دنوں میں روزہ توڑ دینے کا حکم فرماتے اور روزہ رکھنے سے منع فرماتے تھے۔ مالک کا بیان ہے کہ یہ ایام تشریق کی بات ہے۔","صحیح",{"u2":"ابو مرہ مولیٰ ام ہانی سے روایت ہے کہ وہ سیدنا عبداللہ بن عمرو رضی اللہ عنہ کے ساتھ ان کے والد سیدنا عمرو بن العاص رضی اللہ عنہ کے ہاں گئے تو انہوں نے دونوں کو کھانا پیش کیا اور کہا کہ کھاؤ۔ عبداللہ نے کہا: میں روزے سے ہوں۔ تو عمرو نے کہا: کھاؤ، ان دنوں کے بارے میں رسول اللہ صلی اللہ علیہ وسلم ہمیں افطار کا حکم دیا کرتے تھے اور روزوں سے منع فرماتے تھے۔ جناب مالک نے کہا: اس سے مراد ایام تشریق ہیں۔","f2":"(1) ماہ ذوالحج کی دسویں تاریخ کے بعد گنارہ، بارہ اور تیرہ تاریخ کے دنوں کو ایام تشریق اور ایام منٰی کہا جاتا ہے۔ اور یہی (أَيَّامًا مَّعْدُودَ‌ٰتٍ) ہیں۔ تشریق کی وجہ تسمیہ یہ ہے کہ لوگ ان دنوں میں گوشت کے ٹکڑے کرتے اور دھوپ میں بکھیر کر سکھاتے تھے۔"}],[2419,"عقبہ بن عامر رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"یوم عرفہ یوم النحر اور ایام تشریق ہم اہل اسلام کی عید ہے، اور یہ کھانے پینے کے دن ہیں\"۔","صحیح",{"u2":"سیدنا عقبہ بن عامر رضی اللہ عنہ بیان کرتے ہیں کہ رسول ا اللہ صلی اللہ علیہ وسلم نے فرمایا ” یوم عرفہ (نویں ذوالحجہ) یوم نحر (دسویں ذوالحجہ ‘ قربانی کا دن) اور ایام تشریق ہم اہل اسلام کے عید کے ایام ہیں۔ یہ کھانے اور پینے کے دن ہیں۔ “","f2":"ایام تشریق اصلا، عید ہی کے ایام ہیں۔ ان میں عام نفلی روزہ رکھنا جائز نہیں۔ البتہ حج تمتع والا اگر قربانی کی استطاعت نہ رکھتا ہو تو اس پر دس روزے لازم آتے ہیں۔ تین دن ایام حج میں اور سات گھر واپس آ کر۔ چنانچہ اس کو رخصت ہے کہ ایام تشریق میں یہ روزے رکھ لے۔ سورہ بقرہ میں ہے: (فَمَن تَمَتَّعَ بِٱلْعُمْرَ‌ةِ إِلَى ٱلْحَجِّ فَمَا ٱسْتَيْسَرَ‌ مِنَ ٱلْهَدْىِ ۚ فَمَن لَّمْ يَجِدْ فَصِيَامُ ثَلَـٰثَةِ أَيَّامٍ فِى ٱلْحَجِّ وَسَبْعَةٍ إِذَا رَ‌جَعْتُمْ ۗ تِلْكَ عَشَرَ‌ةٌ كَامِلَةٌ) (البقرة: 196) البتہ اس میں یوم عرفہ کا جو ذکر ہے کہ اس دن بھی روزہ رکھنا صحیح نہیں ہے، تو یہ بات حاجیوں کے لیے ہے۔ ان کے لیے روزہ نہ رکھنا بہتر ہے، تاکہ وہ عرفات میں وقوف کی عبادت صحیح طریقے سے کر سکیں۔ لیکن غیر حاجیوں کے لیے یوم عرفہ (9ذوالحجہ) کے روزے کی یہی فضیلت ہے کہ ان کے لیے یہ دو سال کے گناہوں کا کفارہ ہے۔"}],[2420,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"تم میں کوئی جمعہ کو روزہ نہ رکھے سوائے اس کے کہ ایک دن پہلے یا بعد کو ملا کر رکھے\"۔","صحیح",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ سے مروی ہے کہ رسول ا اللہ صلی اللہ علیہ وسلم نے فرمایا ” تم میں سے کوئی شخص جمعے کا روزہ نہ رکھے مگر یہ کہ اس سے پہلے ایک دن روزہ رکھے یا ایک دن بعد۔ “","f2":"روزے کے لیے صرف جمعہ کے دن کو خاص کر لینا یا رات کے قیام و نوافل کے لیے جمعہ کی رات کو خاص اہتمام کرنا جائز نہیں۔ اس منع کی علت رسول اللہ صلی اللہ علیہ وسلم سے ثابت نہیں۔ سوائے اس کے کہ جمعہ کے دن کو عید کا دن کہا گیا ہے اور یہ خاص ذکر و عبادت کا دن ہے۔ حافظ ابن حجر رحمة اللہ علیہ نے فتح الباری میں اور پھر علامہ شوکانی رحمة اللہ علیہ نے نیل الاوطار (4/281) میں ان علل کا ذکر کیا ہے اور اشکالات بھی وارد کیے ہیں۔ کچھ لوگ جمعہ کی رات کو صلاة الرغائب پڑھتے ہیں جو صوفیوں کی ایجاد کردہ بدعت ہے۔ بعض اوقات جمعرات اور جمعہ یا ان راتوں کو درس و تبلیغ کا اہتمام کیا جاتا ہے تو اس میں ان شاءاللہ کوئی مضائقہ نہیں کیونکہ یہ مجالس معروف عبادت نہیں۔ یہ اعمال انتظام و سہولت کے پیش نظر ہوتے ہیں، جمعے کی خصوصیت سے نہیں۔ واللہ اعلم."}],[2421,"عبداللہ بن بسر سلمی مازنی رضی اللہ عنہما اپنی بہن مّاء رضی اللہ عنہا سے روایت کرتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"فرض روزے کے علاوہ کوئی روزہ سنیچر (ہفتے) کے دن نہ رکھو اگر تم میں سے کسی کو (اس دن کا نفلی روزہ توڑنے کے لیے) کچھ نہ ملے تو انگور کا چھلکہ یا درخت کی لکڑی ہی چبا لے\"۔ ابوداؤد کہتے ہیں: یہ منسوخ حدیث ہے ۱؎۔\n§وضاحت\n۱؎ : امام ترمذی فرماتے ہیں کہ یہ حدیث حسن ہے، اور اس میں کراہت کا مطلب یہ ہے کہ آدمی سنیچر کو روزہ کے لئے مخصوص کر دے، کیونکہ یہود اس دن کی تعظیم کرتے ہیں، اس تأویل کی صورت میں امام ابوداود کا اسے منسوخ کہنا درست نہیں ہے، اور کسی صورت میں اس حدیث میں اور اگلے باب کی حدیث ( اور اس دن کے صیام نبوی کی احادیث) میں کوئی تعارض نہیں باقی رہ جاتا، کہ روزہ رکھنے کی صورت میں اس دن کو مخصوص نہیں کیا گیا، ( ملاحظہ ہو: تہذیب السنن لابن القیم ۳؍ ۲۹۷- ۳۰۱، و زاد المعاد۱؍۲۳۷- ۲۳۸، وصحیح ابی داود ۷؍۱۸۰)","صحیح",{"u2":"جناب عبداللہ بن بسر سلمی کی ہمشیرہ صماء رضی اللہ عنہا ا سے مروی ہے کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا ” ہفتے کے دن کا روزہ نہ رکھو ‘ سوائے ان ایام کے جن میں تم پر یہ فرض ہوں۔ ہفتے کے دن اگر تمہیں انگور کی شاخ کا چھلکا میسر آئے یا کسی درخت کی لکڑی تو اسے ہی چبا لو۔ “ (اپنے آپ کو بے روزہ بنا لو۔) امام ابوداؤد رضی اللہ عنہ نے کہا: یہ حدیث منسوخ ہے۔ امام ابوداؤد رضی اللہ عنہ نے کہا: عبداللہ بن بسر ‘ حمصی ہیں اور یہ حدیث منسوخ ہے۔ اس کو سیدہ جویریہ کی حدیث نے (جو آگے آ رہی ہے) منسوخ کر دیا ہے۔","f2":"ہفتے کا دن یہودیوں کی عبادت کا دن ہے اور ہمیں ان کی مخالفت کا حکم ہے، لہذا آگے پیچھے کے دن ساتھ مل جائیں یا ملا لیے جائں تو کوئی حرج نہیں، مثلا ایام بیض، ایام عاشورا وغیرہ لیکن اگر قضا یا نذر کا روزہ ہو یا یوم عرفہ ہفتے کا دن میں پڑ رہا ہو یا کوئی صوم داود کا عامل ہو تو ہفتے کے دن کا روزہ مباح ہو گا۔ کیونکہ یہ تخصیص نہیں۔ امام ابوداود کا اس حدیث کو منسوخ کہنے سے مراد، بقول علامہ البانی رحمة اللہ علیہ، شاید ابن حبان اور حاکم کی یہ روایت ہو جناب کریب مولیٰ ابن عباس رضی اللہ عنہ کہتے ہیں کہ مجھ کو حضرت ابن عباس اور چند دیگر اصحاب رسول صلی اللہ علیہ وسلم نے ام المومنین ام سلمہ رضی اللہ عنہا کی خدمت میں بھیجا کہ ان سے پوچھ کر آؤں کہ رسول اللہ صلی اللہ علیہ وسلم زیادہ تر کن دنوں میں روزے رکھتے تھے۔ انہوں نے جواب دیا کہ ہفتے اور اتوار کو۔ میں یہ جواب لے کر ان حضرات کی خدمت میں پہنچا اور انہیں بتایا تو انہوں نے اس پر (تعجب آمیز) انکار کیا۔ اور پھر وہ سبھی ام المومنین کی خدمت میں چلے گئے اور ان سے کہا: ہم نے آپ سے یہ یہ پچھوایا تھا اور آپ نے یوں یوں جواب دیا ہے تو انہوں نے کہا کہ اس نے سچ کہا ہے۔ رسول اللہ صلی اللہ علیہ وسلم ہفتے اور اتوار کے دنوں میں اکثر روزہ رکھا کرتے تھے اور فرمایا کرتے تھے کہ یہ مشرکین کے عید کے دن ہیں اور میں ان کی مخالفت کرنا چاہتا ہوں۔ امام حاکم نے اس کی سند کو صحیح کہا ہے اور ذہبی نے بھی ان کی موافقت کی ہے مگر علامہ عبدالحق الاشبیلی رحمة اللہ علیہ نے الاحکام الوسطیٰ میں اس کی سند کو ضعیف کہا ہے اور علامہ البانی رحمة اللہ علیہ نے ابھی اسے ہی ترجیح دی ہے۔ (ارواء الغلیل، حدیث:960) الغرض حدیث صحیح اور محکم ہے منسوخ نہیں اور عنوان باب ہی سےسب اشکالات ختم ہو جاتے ہیں، یعنی اس دن کو خاص کرنا جائز نہیں، جمعے یا اتوار کا دن ساتھ ملا لینا ضروری ہے۔"}],[2422,"ام المؤمنین جویریہ بنت حارث رضی اللہ عنہا فرماتی ہیں کہ نبی اکرم صلی اللہ علیہ وسلم ان کے یہاں جمعہ کے دن تشریف لائے اور وہ روزے سے تھیں تو آپ صلی اللہ علیہ وسلم نے پوچھا: \"کیا تم نے کل بھی روزہ رکھا تھا؟\" کہا: نہیں، فرمایا: \"کل روزہ رکھنے کا ارادہ ہے؟\" بولیں: نہیں، تو آپ صلی اللہ علیہ وسلم نے فرمایا: \"پھر روزہ توڑ دو\"۔","صحیح",{"u2":"سیدہ جویریہ بنت حارث رضی اللہ عنہا ا سے مروی ہے کہ (ایک بار) نبی کریم صلی اللہ علیہ وسلم جمعہ کے دن ان کے ہاں تشریف لائے جبکہ یہ روزہ سے تھیں۔ آپ صلی اللہ علیہ وسلم نے دریافت فرمایا ” کیا تم نے کل (جمرات کو) روزہ رکھا تھا؟ کہنے لگیں کہ نہیں۔ فرمایا ” کیا کل (ہفتے) کو روزہ رکھو گی؟ “ کہنے لگیں کہ نہیں۔ فرمایا ” تو افطار کر دو۔ “","f2":"ہفتے کے دن کا روزہ رکھا جا سکتا ہے، مگر آگے پیچھے کا کوئی ایک دن ساتھ ملا کر۔ ایسے ہی جمعے کے متعلق گزر چکا ہے۔"}],[2423,"ابن شہاب زہری سے روایت ہے کہ ان کے سامنے جب سنیچر (ہفتے) کے دن روزے کی ممانعت کا تذکرہ آتا تو کہتے کہ یہ حمص والوں کی حدیث ہے ۱؎۔\n§وضاحت\n۱؎ : اس جملہ سے حدیث نمبر (۲۴۲۱) کی تضعیف مقصود ہے لیکن ،صحیح حدیث کی تضعیف کا یہ انداز بڑا عجیب و غریب ہے، بالخصوص امام زہری جیسے جلیل القدر امام سے، ائمۃ حدیث نے حدیث کی تصحیح فرمائی ہے ( ملاحظہ ہو: صحیح ابی داود ۷؍ ۱۷۹)","صحیح",{"u2":"امام ابن شہاب زہری کے متعلق آتا ہے کہ ان سے جب یہ ذکر کیا جاتا کہ ہفتے کے دن کا روزہ رکھنے سے منع کیا گیا ہے تو وہ کہتے: یہ حدیث حمصی ہے۔","f2":"مذکورہ بالا (حدیث:2421) عبداللہ بن بسر کی سند میں ثور بن یزید اور خالد بن معداد اہل حمص سے ہیں۔ اور اس جملے میں اس کے ضعف کی طرف اشارہ ہے، مگر علامہ البانی رحمة اللہ علیہ کی تحقیق قابل داد ہے، ارواء الغلیل (ج3،ص:124، حدیث:960) میں فرماتے ہیں: اس حدیث کی تین سندیں ہیں اور تینوں صحیح ہیں۔ ان کی روشنی میں اس پر یہ طعن اسراف ہے۔ ایسے ہی امام مالک کا (درج ذیل) قول کہ یہ جھوٹ ہے بعید از صواب ہے۔"}],[2424,"اوزاعی کہتے ہیں کہ میں برابر عبداللہ بن بسر رضی اللہ عنہما کی حدیث (یعنی سنیچر (ہفتے) کے روزے کی ممانعت والی حدیث) کو چھپاتا رہا یہاں تک کہ میں نے دیکھا کہ وہ لوگوں میں مشہور ہو گئی۔ ابوداؤد کہتے ہیں: مالک کہتے ہیں: یہ روایت جھوٹی ہے ۱؎۔\n§وضاحت\n۱؎ : امام مالک کا یہ قول مرفوض ہے۔","صحیح",{"u2":"امام اوزاعی نے کہا: میں ایک مدت تک اس روایت کو چھپائے رہا۔ یعنی مذکورہ بالا حدیث عبداللہ بن بسر جو کہ ہفتے کے دن روزہ رکھنے کے بارے میں ہے حتیٰ کہ میں نے دیکھا کہ مشہور ہو گئی ہے۔ امام ابوداؤد رضی اللہ عنہ نے کہا: امام مالک رضی اللہ عنہ نے اس کو ” جھوٹ “ کہا ہے۔","f2":"مذکورہ تفصیل سے واضح ہے کہ جمعے کے دن کی طرح صرف ہفتے کے دن بھی روزہ رکھنا ممنوع ہے۔ مگر یہ کہ اس کے ساتھ اتوار کا یا جمعہ کا روزہ ملا لیا جائے، پھر جمعے اور ہفتے کا روزہ جائز ہو گا۔ اسی طرح ان دونوں دنوں (جمعہ اور ہفتہ) میں فرضی روزہ، نذر کا روزہ، فوت شدہ روزوں کی قضا کا روزہ، کفارے کا روزہ، اس دن عرفہ یا عاشورا آ جائے تو ان کا روزہ، یہ سارے روزے رکھنے جائز ہوں گے۔"}],[2425,"ابوقتادہ رضی اللہ عنہ سے روایت ہے کہ ایک شخص رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوا اور اس نے عرض کیا: اللہ کے رسول! آپ روزہ کس طرح رکھتے ہیں؟ رسول اللہ صلی اللہ علیہ وسلم کو اس کے اس سوال پر غصہ آ گیا، عمر رضی اللہ عنہ نے جب یہ منظر دیکھا تو کہا: «رضينا بالله ربا وبالإسلام دينا وبمحمد نبيا نعوذ بالله من غضب الله ومن غضب رسوله» \"ہم اللہ کے رب ہونے، اسلام کے دین ہونے، اور محمد صلی اللہ علیہ وسلم کے نبی ہونے پر راضی و مطمئن ہیں ہم اللہ اور اس کے رسول کے غصے سے اللہ کی پناہ مانگتے ہیں\" عمر رضی اللہ عنہ یہ کلمات برابر دہراتے رہے یہاں تک کہ رسول اللہ صلی اللہ علیہ وسلم کا غصہ ٹھنڈا ہو گیا، پھر(عمر رضی اللہ عنہ نے) پوچھا: اللہ کے رسول! جو شخص ہمیشہ روزہ رکھتا ہے اس کا کیا حکم ہے؟ فرمایا: \"نہ اس نے روزہ ہی رکھا اور نہ افطار ہی کیا\"۔ پھر عرض کیا: اللہ کے رسول! جو شخص دو دن روزہ رکھتا ہے، اور ایک دن افطار کرتا ہے، اس کا کیا حکم ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا: \"اس کی کسی کے اندر طاقت ہے بھی؟\"۔ (پھر) انہوں نے عرض کیا: اللہ کے رسول! جو شخص ایک دن روزہ رکھتا ہے، اور ایک دن افطار کرتا ہے، اس کا کیا حکم ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا: \"یہ داود علیہ السلام کا روزہ ہے\"۔ پوچھا: اللہ کے رسول! اس شخص کا کیا حکم ہے جو ایک دن روزہ رکھتا ہے، اور دو دن افطار کرتا ہے، آپ صلی اللہ علیہ وسلم نے فرمایا: \"میری خواہش ہے کہ مجھے بھی اس کی طاقت ملے\" پھر آپ صلی اللہ علیہ وسلم نے فرمایا: \"ہر ماہ کے تین روزے اور رمضان کے روزے ہمیشہ روزہ رکھنے کے برابر ہیں، یوم عرفہ کے روزہ کے بارے میں میں اللہ سے امید کرتا ہوں کہ وہ گزشتہ ایک سال اور آئندہ ایک سال کے گناہوں کا کفارہ ہو جائے گا، اور اللہ سے یہ بھی امید کرتا ہوں کہ یوم عاشورہ (دس محرم الحرام) کا روزہ گزشتہ ایک سال کے گناہوں کا کفارہ ہو گا\"۔","صحیح",{"u2":"سیدنا ابوقتادہ رضی اللہ عنہ سے مروی ہے کہ ایک شخص نبی کریم صلی اللہ علیہ وسلم کی خدمت میں آیا اور کہا: اے ا اللہ کے رسول! آپ روزے کس طرح رکھتے ہیں؟ تو رسول اللہ صلی اللہ علیہ وسلم اس کی بات سے ناراض ہو گئے۔ جب سیدنا عمر رضی اللہ عنہ نے یہ صورت حال دیکھی تو بولے: ہم ا اللہ تعالیٰ کے رب ہونے ‘ اسلام کے دین ہونے اور محمد صلی اللہ علیہ وسلم کے نبی ہونے پر راضی ہیں ‘ ہم ا اللہ کی پناہ چاہتے ہیں کہ وہ ہم پر ناراض ہو یا اس کا رسول۔ اور سیدنا عمر رضی اللہ عنہ اپنی یہ بات مسلسل دہراتے رہے حتیٰ کہ نبی کریم صلی اللہ علیہ وسلم کا غصہ زائل ہو گیا۔ پھر (سیدنا عمر رضی اللہ عنہ نے) کہا: اے ا اللہ کے رسول! وہ آدمی کیسا ہے جو ہمیشہ ہی روزے سے رہتا ہو؟ آپ صلی اللہ علیہ وسلم نے فرمایا ” اس نے روزہ رکھا نہ افطار کیا۔ “ مسدد کے الفاظ تھے «لم يصم ولم يفطر أو صام ولا أفطر» یہ شک غیلان کو ہوا ہے۔ (سیدنا عمر رضی اللہ عنہ نے) کہا: اے ا اللہ کے رسول! وہ آدمی کیسا ہے جو دو دن روزہ رکھے اور ایک دن افطار کرے؟ آپ نے فرمایا ” کیا بھلا کسی کو اس کی طاقت بھی ہے؟ “ سیدنا عمر رضی اللہ عنہ نے کہا: اے ا اللہ کے رسول! اور وہ آدمی کیسا ہے جو ایک دن روزہ رکھے اور ایک دن افطار کرے؟ آپ نے فرمایا ” یہ سیدنا داود علیہ السلام کا روزہ ہے۔ “ انہوں نے کہا: اے ا اللہ کے رسول! اور وہ آدمی کیسا ہے جو ایک دن روزہ رکھے اور دو دن افطار کرے؟ آپ نے فرمایا ” میرا جی چاہتا ہے کہ مجھے اس کی طاقت دی جاتی۔ “ پھر رسول ا اللہ صلی اللہ علیہ وسلم نے فرمایا ” تین دن ہر مہینے میں اور رمضان سے رمضان تک، (ہر رمضان میں پورے روزے رکھنا) یہ صیام الدھر ہے۔ (سدا روزے سے رہنا ہے) اور عرفہ کا روزہ۔ میں ا اللہ سے امید رکھتا ہوں کہ وہ اسے ایک سال گزشتہ اور ایک سال آئندہ کا کفارہ بنا دے گا۔ اور عاشورہ محرم کا روزہ، میں ا اللہ سے امید رکھتا ہوں کہ وہ اسے گزشتہ ایک سال کا کفارہ بنا دے گا۔ “","f2":"(1) رسول اللہ صلی اللہ علیہ وسلم کا ناراض ہونا اس بنا پر تھا کہ اس نے اپنی ہمت اور طاقت سے زیادہ کا سوال کیا تھا۔ جبکہ اس سلسلے میں کوئی شخص آپ صلی اللہ علیہ وسلم کے ہم پلہ نہیں ہو سکتا۔ (2) صحابہ کرام رضی اللہ عنہ مزاج شناس رسول تھے، بالخصوص حضرت عمر رضی اللہ عنہ، وہ جانتے تھے کہ آپ کا غصہ کس طرح سے دور ہو سکتا ہے اور وہ تھا... ایک اللہ کی ربوبیت، محمد صلی اللہ علیہ وسلم کی رسالت و نبوت اور اسلام کے دین ہونے کا اقرار، بلکہ اس کے لیے دلی طور پر رضامندی کا اظہار کرنا۔ (3)بغیر کسی انقطاع کے مسلسل روزے رکھنے پر نبی صلی اللہ علیہ وسلم نے بطور وعید فرمایا کہ ایسے شخص کو نہ روزوں کا ثواب ملا اور نہ اس نے افطار کا لطف پایا، یعنی جائز نہیں ہے۔ دوسری صورت کہ دو دن روزہ رکھنا اور ایک دن افطار کرنا، یہ بھی ایک بھاری اور مشکل عمل ہے، تیسری صورت میں بھی مشقت ہے مگر اس سے بھی آسان ترین اور اجر میں کامل ہر مہینے میں تین روزے رکھنا مرغوب و مطلوب ہے۔ (4) عاشورا اگرچہ دسویں محرم کو کہتے ہیں مگر اس کے لیے بھی ایک دن پہلے یا بعد میں روزہ رکھنا چاہیے۔ (مزید تفصیل آگے احادیث:2442 و مابعد میں آ رہی ہے) (5) گذشتہ سال کا کفارہ اس معنی میں ہے کہ اس کی تقصیرات معاف کر دی جاتی ہیں اور آئندہ سال کا کفارہ اس معنی میں ہے کہ اللہ اسے گناہوں سے محفوظ رکھے گا یا اگر ہو جائیں تو معاف فرما دے گا۔ خیال رہے کہ اس قسم کی تمام ترغیبی و تشویقی احادیث اس امر سے مشروط ہیں کہ یہ اعمال صالحہ اللہ تعالیٰ کے ہان شرف قبولیت پا لیں، تبھی یہ اجر مرتب ہو گا... اور کسے خبر کہ اس کا عمل فی الواقع قبول ہو گیا ہے۔ اس لیے مومن اعمال خیر کر کے دھوکے میں نہیں آ سکتا۔ بلکہ قبولیت کی امید پر مزید اعمال صالحہ کے لیے محنت کرتا اور فکرمند رہتا ہے کہ کہیں اس کے اعمال رد ہی نہ کر دیے جائیں۔"}],[2426,"اس سند سے بھی ابوقتادہ رضی اللہ عنہ سے یہی حدیث مروی ہے لیکن اس میں یہ الفاظ زائد ہیں: کہا: اللہ کے رسول! دوشنبہ اور جمعرات کے روزے کے متعلق بتائیے، آپ صلی اللہ علیہ وسلم نے فرمایا: \"میں اسی دن پیدا ہوا اور اسی دن مجھ پر قرآن نازل کیا گیا\"۔","صحیح",{"u2":"سیدنا ابوقتادہ رضی اللہ عنہ سے اس روایت میں مروی ہے کہ (موسٰی بن اسماعیل نے) مزید کہا: اے ا اللہ کے رسول! سوموار اور جمعرات کے روزے کے بارے میں آپ کیا فرماتے ہیں؟ آپ صلی اللہ علیہ وسلم نے فرمایا ” اس روز میری ولادت ہوئی اور اسی میں مجھ پر قرآن نازل کیا گیا۔ “ (سوموار کے دن)۔","f2":"رسول اللہ صلی اللہ علیہ وسلم رحمة للعالمین ہیں، آپ کی ولادت با سعادت کا دن مبارک اور خوشی کا دن ہے مگر اس خوشی کے اظہار اور اللہ عزوجل کے شکر ادا کرنے کا مشروع و مسنون طریقہ یہی ہے کہ اس دن روزہ رکھا جائے... کجا یہ مبارک سنت اور کہاں اہل بدعت کی وہ مذموم ببدعت کہ جس کا سال بعد نہایت مسرفانہ انداز میں اہتمام کیا جاتا ہے۔\n}اللهم ارنا الحق حقا وارزقنا اتباعه وارنا الباطل باطلا وارزقنا اجتنابه{"}],[2427,"عبداللہ بن عمرو بن العاص رضی اللہ عنہما کہتے ہیں کہ میری ملاقات رسول اللہ صلی اللہ علیہ وسلم سے ہوئی تو آپ نے فرمایا: \"کیا مجھ سے یہ نہیں بیان کیا گیا ہے کہ تم کہتے ہو: میں ضرور رات میں قیام کروں گا اور دن میں روزہ رکھوں گا؟\" کہا: میرا خیال ہے اس پر انہوں نے کہا: ہاں، اللہ کے رسول! میں نے یہ بات کہی ہے، آپ صلی اللہ علیہ وسلم نے فرمایا: \"قیام اللیل کرو اور سوؤ بھی، روزہ رکھو اور کھاؤ پیو بھی، ہر مہینے تین دن روزے رکھو، یہ ہمیشہ روزے رکھنے کے برابر ہے\"۔ عبداللہ بن عمرو رضی اللہ عنہما کہتے ہیں: میں نے کہا: اللہ کے رسول! میں اپنے اندر اس سے زیادہ کی طاقت پاتا ہوں، آپ صلی اللہ علیہ وسلم نے فرمایا: \"تو ایک دن روزہ رکھو اور دو دن افطار کرو\" وہ کہتے ہیں: اس پر میں نے کہا: میرے اندر اس سے بھی زیادہ کی طاقت ہے، آپ صلی اللہ علیہ وسلم نے فرمایا: \"تو پھر ایک دن روزہ رکھو، اور ایک دن افطار کرو، یہ عمدہ روزہ ہے، اور داود علیہ السلام کا روزہ ہے\" میں نے کہا: مجھے اس سے بھی زیادہ کی طاقت ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اس سے افضل کوئی روزہ نہیں\"۔","صحیح",{"u2":"سیدنا عبداللہ بن عمرو بن العاص رضی اللہ عنہ کا بیان ہے کہ رسول اللہ صلی اللہ علیہ وسلم مجھ سے ملے اور فرمایا ” مجھے بتایا گیا ہے کہ تم کہتے ہو میں رات پھر قیام اور دن کو روزہ ہی رکھا کروں گا؟ “ میں نے کہا: ہاں اے اللہ کے رسول! میں نے ایسا کہا ہے۔ آپ صلی اللہ علیہ وسلم نے فرمایا ” (رات کو) قیام کرو اور آرام بھی کرو، روزے رکھو اور افطار بھی کرو (بلکہ) ہر مہینے میں تین روزے رکھا کرو، یہ صیام الدھر کی مانند ہو گے۔ “ (گویا زمانہ بھر روزے رکھے) میں نے کہا: اے اللہ کے رسول! میں اس سے زیادہ کی طاقت رکھتا ہوں۔ آپ صلی اللہ علیہ وسلم نے فرمایا ” ایک دن روزہ رکھا کر دو دن افطار کر لیا کرو۔ “ میں نے کہا: میں اس سے زیادہ کی طاقت رکھتا ہوں۔ فرمایا ” تو ایک دن روزہ رکھا کرو اور ایک دن افطار کر لیا کرو، یہ روزے رکھنے کی معتدل صورت ہے اور یہ صیام داود ہے۔ “ میں نے کہا:، میں اس سے زیادہ کی طاقت رکھتا ہوں۔ آپ صلی اللہ علیہ وسلم نے فرمایا ” اس سے بڑھ کر کچھ افضل نہیں۔ “","f2":"رسول اللہ صلی اللہ علیہ وسلم کی تعلیم و تلقین عمل میں انتہائی خفیف اور اجر میں بہت عظیم ہے مگر حضرت عبداللہ رضی اللہ عنہ کی طبیعت زیادہ کی حریص تھی اس لیے زیادہ کی اجازت طلب کرتے رہے مگر جب بڑھاپے میں کمزور ہو گئے تو کہا کرتے تھے: کاش میں نے رسول اللہ صلی اللہ علیہ وسلم کے فرمائے ہوئے تین دن قبول کر لیے ہوتے،وہ مجھے میرے اہل اور مال سے زیادہ محبوب تھے۔ (صحيح مسلم‘ الصيام‘ حديث:1159)"}],[2428,"مجیبہ باہلیہ اپنے والد یا چچا سے روایت کرتی ہیں کہ وہ رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوئے پھر چلے گئے اور ایک سال بعد دوبارہ آئے اس مدت میں ان کی حالت و ہیئت بدل گئی تھی، کہنے لگے: اللہ کے رسول! کیا آپ مجھے پہچانتے نہیں، آپ صلی اللہ علیہ وسلم نے پوچھا: \"کون ہو؟\" جواب دیا: میں باہلی ہوں جو کہ پہلے سال بھی حاضر ہوا تھا، آپ صلی اللہ علیہ وسلم نے کہا: \"تمہیں کیا ہو گیا؟ تمہاری تو اچھی خاصی حالت تھی؟\" جواب دیا: جب سے آپ کے پاس سے گیا ہوں رات کے علاوہ کھایا ہی نہیں ۱؎ آپ صلی اللہ علیہ وسلم نے فرمایا: \"اپنے آپ کو تم نے عذاب میں کیوں مبتلا کیا؟\" پھر فرمایا: \"صبر کے مہینہ (رمضان) کے روزے رکھو، اور ہر مہینہ ایک روزہ رکھو\" انہوں نے کہا: اور زیادہ کیجئے کیونکہ میرے اندر طاقت ہے، آپ صلی اللہ علیہ وسلم نے فرمایا: \"دو دن روزہ رکھو\"، انہوں نے کہا: اس سے زیادہ کی میرے اندر طاقت ہے، آپ صلی اللہ علیہ وسلم نے فرمایا: \"تین دن کے روزے رکھ لو\"، انہوں نے کہا: اور زیادہ کیجئے، آپ صلی اللہ علیہ وسلم نے فرمایا: \"حرمت والے مہینوں میں روزہ رکھو اور چھوڑ دو، حرمت والے مہینوں میں روزہ رکھو اور چھوڑ دو، حرمت والے مہینوں میں روزہ رکھو اور چھوڑ دو\"، آپ صلی اللہ علیہ وسلم نے اپنی تین انگلیوں سے اشارہ کیا، پہلے بند کیا پھر چھوڑ دیا ۲؎۔\n§وضاحت\n۱؎ : برابر روزے رکھ رہا ہوں۔ ۲؎ : یعنی تین دن روزے رکھو پھر تین دن نہ رکھو، پورے مہینوں میں اسی طرح کرتے رہو۔","ضعیف",{"u2":"سیدہ مجیبہ الباھلیہ رضی اللہ عنہا ا اپنے والد یا چچا سے روایت کرتی ہیں کہ وہ رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں آئے۔ پھر ایک سال کے بعد (دوبارہ) آئے تو اس کی حالت و کیفیت بدلی ہوئی تھی۔ انہوں نے کہا: اے اللہ کے رسول! کیا آپ نے مجھے پہچانا نہیں؟ آپ صلی اللہ علیہ وسلم نے فرمایا ” تم کون ہو؟ “ اس نے کہا:، میں وہی باہلی ہوں جو پچھلے سال آیا تھا۔ آپ صلی اللہ علیہ وسلم نے پوچھا “ تمہاری حالت اس طرح غیر کیوں ہو رہی ہے، حالانکہ تم اچھے بھلے تھے؟ “ کہنے لگا جب سے میں آپ کے پاس سے گیا ہوں میں نے یہ معمول بنا لیا ہے کہ بس رات ہی کو کھانا کھاتا ہوں۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” تم نے اپنے آپ کو عذاب میں کیوں ڈال رکھا ہے؟ “ پھر فرمایا ” ماہ صبر (رمضان) کے روزے رکھا کرو اور پھر ہر مہینے ایک روزہ۔ “ اس نے کہا: مجھے مزید کی اجازت دیجیئے، یقیناً میں طاقت رکھتا ہوں۔ آپ صلی اللہ علیہ وسلم نے فرمایا ” دو دن روزے رکھو۔ “ اس نے کہا: مجھے زیادہ کی اجازت دیجیئے، آپ صلی اللہ علیہ وسلم نے فرمایا ” تین دن رکھ لیا کرو۔ “ اس نے کہا:، میرے لیے زیادہ کیجئے۔ آپ صلی اللہ علیہ وسلم نے فرمایا ” حرمت کے مہینوں میں روزے رکھو اور چھوڑ دو، حرمت کے مہینوں میں روزے رکھو اور چھوڑ دو، حرمت کے مہینوں میں روزے رکھو اور چھوڑ دو۔ “ اور آپ صلی اللہ علیہ وسلم نے تین انگلیوں سے اشارہ فرمایا۔ پہلے ان کو بند کیا پھر کھول دیا۔","f2":"سال میں چار مہینے حرمت والے ہیں: ذوالقعدہ، ذوالحجہ، محرم اور رجب۔ قرآن مجید میں ہے: (إِنَّ عِدَّةَ ٱلشُّهُورِ‌ عِندَ ٱللَّهِ ٱثْنَا عَشَرَ‌ شَهْرً‌ۭا فِى كِتَـٰبِ ٱللَّهِ يَوْمَ خَلَقَ ٱلسَّمَـٰوَ‌ٰتِ وَٱلْأَرْ‌ضَ مِنْهَآ أَرْ‌بَعَةٌ حُرُ‌مٌ) (التوبة: 36) اللہ عزوجل کے ہاں مہینوں کی گنتی بارہ مہینے ہے اللہ کی کتاب میں، جب سے اس نے آسمانوں اور زمین کو پیدا کیا ہے۔ ان میں سے چار حرمت والے ہیں۔"}],[2429,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"ماہ رمضان کے روزوں کے بعد سب سے زیادہ فضیلت والے روزے محرم کے ہیں جو اللہ کا مہینہ ہے، اور فرض نماز کے بعد سب سے زیادہ فضیلت والی نماز رات کی نماز (تہجد) ہے\"۔","صحیح",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” سب سے افضل روزے ماہ رمضان کے بعد، اللہ کے مہینے محرم کے روزے ہیں، اور سب سے افضل نماز فرضوں کے بعد رات کی نماز ہے۔ “ قتیبہ بن سعید نے «شهر» کا لفظ استعمال نہیں کیا، بلکہ صرف «رمضان» کہا۔","f2":"محرم کے مہینے میں نفلی روزوں کی بڑی فضیلت ہے۔ علاوہ ازیں عاشورہ محرم اور اس کے ساتھ ایک دن اور ملا کر روزہ رکھنے کا مسئلہ ہے جس کی تفصیل آگے آ رہی ہے۔"}],[2430,"عثمان بن حکیم کہتے ہیں کہ میں نے سعید بن جبیر سے رجب کے روزوں کے بارے میں پوچھا تو انہوں نے کہا: ابن عباس رضی اللہ عنہما نے مجھے بتایا ہے کہ رسول اللہ صلی اللہ علیہ وسلم روزے رکھتے تو رکھتے چلے جاتے یہاں تک کہ ہم کہتے: افطار ہی نہیں کریں گے، اسی طرح جب روزے چھوڑتے تو چھوڑتے چلے جاتے یہاں تک کہ ہم کہتے: اب روزے رکھیں گے ہی نہیں۔\n§وضاحت\n۱؎ : یہ باب کئی نسخوں میں نہیں ہے، جب کہ مولانا وحیدالزماں کے نسخہ میں موجود ہے ، اور تبویب حدیث کے مطابق ہے، واللہ اعلم۔","صحیح",{"u2":"عثمان بن حکیم کہتے ہیں کہ میں نے سعید بن جبیر سے رجب کے روزے کے متعلق سوال کیا تو انہوں نے کہا: مجھے ابن عباس رضی اللہ عنہ نے خبر دی ہے کہ رسول اللہ صلی اللہ علیہ وسلم روزے رکھا کرتے تو ہم کہتے: اب نہیں چھوڑیں گے اور کبھی چھوڑ دیتے تو ہم کہتے: اب نہیں رکھیں گے۔","f2":"رجب، حرمت والے مہینوں میں سے ہے۔ اور اس حدیث کی روشنی میں کہا جا سکتا ہے کہ رسول اللہ صلی اللہ علیہ وسلم اس مہینے میں خوب روزے رکھتے تھے۔ یا یہ مراد ہے کہ دیگر مہینوں کی طرح کبھی رکھتے اور کبھی نہ رکھتے تھے۔ اس کا کوئی خاص حکم نہیں ہے۔ واللہ اعلم."}],[2431,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم کو مہینوں میں سب سے زیادہ محبوب یہ تھا کہ آپ شعبان میں روزے رکھیں، پھر اسے رمضان سے ملا دیں۔","صحیح",{"u2":"ام المؤمنین سیدہ عائشہ رضی اللہ عنہا ا بیان کرتی ہیں کہ روزے رکھنے کے لیے رسول اللہ صلی اللہ علیہ وسلم کو شعبان کا مہینہ سب سے زیادہ پسند تھا پھر آپ اسے (گویا) رمضان ہی سے ملا دیتے تھے۔","f2":"مختلف روایات کی روشنی میں حضرت عائشہ رضی اللہ عنہا کا یہ بیان یا تو مبالغہ پر مبنی ہے، یا یہ مقصد ہے کہ آپ صلی اللہ علیہ وسلم بعض اوقات روزے ابتدائے مہینہ میں رکھتے، کبھی درمیان مہینہ میں اور کبھی آخر مہینہ میں، یا یہ مقصد ہے کہ خال خال ہی کسی دن ناغہ کرتے تھے ورنہ عام ایام میں روزے ہی رکھتے تھے۔ ماہِ شعبان فضیلت والا مہینہ ہے۔ رسول اللہ صلی اللہ علیہ وسلم اس مہینے میں کثرت سے روزے رکھا کرتے تھے اور آپ صلی اللہ علیہ وسلم نے فرمایا کہ اس مہینے میں بندوں کے اعمال اللہ تعالیٰ کے ہاں پیش کیے جاتے ہیں اور میں چاہتا ہوں کہ جب میرے اعمال پیش کیے جائیں تو میں روزے سے ہوں۔ (سنن النسائي‘ الصيام‘ حديث:2359) اسی طرح شعبان کی پندرھویں رات کی فضیلت کی بابت ایک حدیث سندا صحیح ہے اس میں آپ نے فرمایا: اللہ تعالیٰ اس رات شرک کرنے اور بغض و کینہ رکھنے والے کے سوا تمام لوگوں کی مغفرت فرما دیتا ہے۔ (مجمع الزوائد‘ 8/65 وابن حبان‘ حديث:5665 والصحيحة‘ حديث:1144) روزے کی بابت آپ سے مروی ہے آپ شعبان کے مہینے کے کسی دن کو روزے کے ساتھ خاص نہیں کرتے تھے بلکہ اس ماہ میں اکثر روزے رکھا کرتے تھے، دوسری بات کہ پندرھویں رات کو اگر کوئی اس نیت سے عبادت کرتا ہے کہ اس رات اللہ تعالیٰ بندوں کی مغفرت فرماتا ہے، تو وہ ممکن حد تک ہر کسی کے حقوق کا لحاظ رکھتے ہوئے عبادت کر سکتا ہے لیکن اس رات میں چراغاں کرنا یا موم بتیاں جلانا یا اگلے دن کا روزہ رکھنا جائز نہیں ہے۔ واللہ اعلم."}],[2432,"مسلم قرشی رضی اللہ عنہ کہتے ہیں کہ میں نے نبی اکرم صلی اللہ علیہ وسلم سے پورے سال کے روزوں کے متعلق پوچھا، یا آپ سے سوال کیا گیا تو آپ صلی اللہ علیہ وسلم نے فرمایا: \"تم پر تمہارے اہل کا بھی حق ہے، لہٰذا رمضان اور اس کے بعد (والے ماہ میں) روزے رکھو، اور ہر بدھ اور جمعرات کا روزہ رکھو تو گویا تم نے پورے سال کا روزہ رکھا\"۔","صحیح مسلم بن عبیداللہ ہے اور یہ لین الحدیث ہیں، ان کے والد کا نام عبیداللہ بن مسلم اور یہ صحابی ہیں",{"u2":"عبیداللہ بن مسلم قرشی اپنے والد سے روایت کرتے ہیں، کہتے ہیں کہ صیام الدھر (ہمیشہ روزے رکھنے) کے متعلق میں نے نبی کریم صلی اللہ علیہ وسلم سے سوال کیا یا کسی اور نے پوچھا تو آپ صلی اللہ علیہ وسلم نے فرمایا ” بلاشبہ تمہارے گھر والوں کا تم پر حق ہے، رمضان میں روزے رکھو اور اس کے ساتھ والے مہینے میں (شوال میں) اور ہر بدھ اور جمعرات کو (بھی) تو اس طرح تم زمانہ بھر روزے رکھنے والے ہو گے۔ “ امام ابوداؤد رضی اللہ عنہ نے کہا (راوی حدیث عبیداللہ بن مسلم کے نام میں) زید بن حباب عکلی نے عبیداللہ بن موسیٰ کی تائید کی ہے اور ابونعیم نے مخالفت کی ہے۔ (بعض مسلم بن عبیداللہ کہتے ہیں اور کچھ نے مسلم بن عبداللہ کہا ہے۔)"}],[2433,"ابوایوب رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"جس نے رمضان کے روزے رکھے اور اس کے بعد چھ روزے شوال کے رکھے تو گویا اس نے پورے سال کے روزے رکھے\"۔","صحیح",{"u2":"نبی کریم صلی اللہ علیہ وسلم کے صحابی سیدنا ابوایوب رضی اللہ عنہ، نبی کریم صلی اللہ علیہ وسلم سے بیان کرتے ہیں کہ آپ صلی اللہ علیہ وسلم نے فرمایا ” جس نے رمضان کے روزے رکھے، پھر اس کے بعد شوال میں چھ روزے رکھے تو اس نے گویا زمانہ بھر روزے رکھے۔ “","f2":"(1) اس حدیث میں شش عیدی روزوں کی فضیلت و استحباب کا بیان ہے۔ اور جائز ہے کہ یہ عید کے بعد فورا مسلسل رکھ لیے جائیں یا اس مہینے میں متفق طور پر رکھے جائیں۔ (2) زمانہ بھر یعنی سال بھر کے روزون کا ثواب اس طرح واضح کیا جاتا ہے کہ حسب قاعدہ (مَن جَآءَ بِٱلْحَسَنَةِ فَلَهُۥ عَشْرُ‌ أَمْثَالِهَا) (الانعام:160) رمضان کے تیس اور شوال کے چھ دن کل چھتیس دن ہوئے اور دس گنا ثواب سے تین سو ساٹھ ہو گئے اور تقریبا یہی تعداد سال کے دنوں کی ہوتی ہے۔ واللہ اعلم."}],[2434,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم روزے رکھتے چلے جاتے یہاں تک کہ ہم کہنے لگتے کہ اب آپ روزے رکھنا نہیں چھوڑیں گے، پھر چھوڑتے چلے جاتے یہاں تک کہ ہم کہنے لگتے کہ اب آپ صلی اللہ علیہ وسلم روزے نہیں رکھیں گے، میں نے آپ صلی اللہ علیہ وسلم کو ماہ رمضان کے علاوہ کسی اور ماہ کے مکمل روزے رکھتے نہیں دیکھا، اور جتنے زیادہ روزے شعبان میں رکھتے اتنے روزے کسی اور ماہ میں رکھتے نہیں دیکھا۔","صحیح",{"u2":"ام المؤمنین سیدہ عائشہ رضی اللہ عنہا ا نے بیان کیا کہ رسول اللہ صلی اللہ علیہ وسلم روزے رکھنا شروع کر دیتے تو ہم سمجھتے کہ اب نہیں چھوڑیں گے اور جب چھوڑ دیتے تو ہم سمجھتے کہ اب نہیں رکھیں گے۔ میں نے نہیں دیکھا کہ رسول اللہ صلی اللہ علیہ وسلم نے رمضان کے علاوہ کسی مہینے کے پورے روزے رکھے ہوں اور آپ صلی اللہ علیہ وسلم شعبان کے علاوہ کسی اور مہینے میں زیادہ روزے نہ رکھتے تھے۔","f2":"نبی صلی اللہ علیہ وسلم نے روزے رکھنے کے لیے کوئی ایام یا تواریخ مخصوص نہیں کی تھیں، بلکہ حسب رغبت رکھتے تھے۔ تاہم سوموار اور جمعرات کے روزوں کا آپ خاص طور پر اہتمام فرماتے تھے، جیسا کہ اگلے باب میں آ رہا ہے۔"}],[2435,"ابوہریرہ رضی اللہ عنہ نبی اکرم صلی اللہ علیہ وسلم سے اسی مفہوم کی حدیث روایت کرتے ہیں اس میں اتنا اضافہ ہے: \"آپ شعبان کے اکثر دنوں میں روزے رکھتے تھے، سوائے چند دنوں کے بلکہ پورے شعبان میں روزے رکھتے تھے\"۔","حسن صحیح",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ، نبی کریم صلی اللہ علیہ وسلم کے متعلق بیان کرتے ہیں جیسے کہ مذکورہ بالا حدیث عائشہ میں گزرا ہے۔ اور اس میں اس قدر زیادہ ہے کہ آپ صلی اللہ علیہ وسلم شعبان میں بہت کم ناغہ فرماتے تھے بلکہ (گویا) سارا شعبان ہی روزے رکھتے تھے۔"}],[2436,"اسامہ بن زید رضی اللہ عنہما کے غلام کہتے ہیں کہ وہ اسامہ رضی اللہ عنہ کے ہمراہ وادی قری کی طرف ان کے مال (اونٹ) کی تلاش میں گئے (اسامہ کا معمول یہ تھا کہ) دوشنبہ (سوموار، پیر) اور جمعرات کا روزہ رکھتے تھے، اس پر ان کے غلام نے ان سے پوچھا: آپ دوشنبہ(سوموار، پیر) اور جمعرات کا روزہ کیوں رکھتے ہیں حالانکہ آپ بہت بوڑھے ہیں؟ کہنے لگے: نبی اکرم صلی اللہ علیہ وسلم دوشنبہ اور جمعرات کا روزہ رکھتے تھے، اور جب آپ سے ان کے بارے میں پوچھا گیا تو آپ صلی اللہ علیہ وسلم نے فرمایا: \"بندوں کے اعمال دوشنبہ اور جمعرات کو (بارگاہ الٰہی میں) پیش کئے جاتے ہیں\"۔","صحیح",{"u2":"سیدنا اسامہ بن زید رضی اللہ عنہ کے غلام نے بیان کیا کہ وہ سیدنا اسامہ رضی اللہ عنہ کے ساتھ ان کا مال لینے کے لیے وادی قریٰ کی طرف گیا۔ اسامہ رضی اللہ عنہ سوموار اور جمعرات کا روزہ رکھا کرتے تھے۔ غلام نے ان سے پوچھا: آپ سوموار اور جمعرات کا روزہ کیوں رکھتے ہیں، حالانکہ آپ بڑی عمر کے بوڑھے ہو گئے ہیں؟ تو انہوں نے کہا: نبی کریم صلی اللہ علیہ وسلم سوموار اور جمعرات کا روزہ رکھا کرتے تھے۔ آپ صلی اللہ علیہ وسلم سے اس کے متعلق پوچھا گیا تو آپ صلی اللہ علیہ وسلم نے فرمایا ” سوموار اور جمعرات کو بندوں کے اعمال (اللہ کے حضور) پیش کیے جاتے ہیں۔ “ امام ابوداؤد رضی اللہ عنہ فرماتے ہیں کہ ہشام دستوائی نے یحییٰ سے اور اس نے عمر بن ابی حکم سے اسی طرح روایت کیا ہے۔","f2":"اس کے ولاوہ صحیح مسلم وغیرہ کی ایک حدیث میں یوں ہے کہ رات کے عمل دن ہونے سے پہلے پہلے اور دن کے عمل رات ہونے سے پہلے پہلے اس کی طرف اٹھائے جاتے ہیں۔ (یا اس کے حضور پیش کیے جاتے ہیں۔) (صحيح مسلم‘ الايمان‘ حديث:179) الغرض ان احادیث میں رفع اعمال کے نظام کا بیان ہے جو بلاتاخٰر و تعطل اللہ عزوجل تک پہنچ رہے ہیں اور ان پیشوں میں نوعیت کا فرق ہو سکتا ہے، ایک روزانہ کی ہے اور دوسری ہفتہ وار جو سوموار اور جمعرات کو ہوتی ہے اور اسی طرح شعبان کے متعلق بھی آتا ہے، تو وہ پیشی سالانہ ہو سکتی ہے۔ واللہ اعلم."}],[2437,"ہنیدہ بن خالد کی بیوی سے روایت ہے کہ وہ نبی اکرم صلی اللہ علیہ وسلم کی کسی بیوی سے روایت کرتی ہیں، وہ کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم ذی الحجہ کے (شروع) کے نو دنوں کا روزہ رکھتے، اور یوم عاشورہ (دسویں محرم) کا روزہ رکھتے نیز ہر ماہ تین دن یعنی مہینے کے پہلے پیر (سوموار، دوشنبہ) اور جمعرات کا روزہ رکھتے ۱؎۔\n§وضاحت\n۱؎ : ابوداود کی اس روایت میں اسی طرح واحد کے لفظ کے ساتھ ہے مگر نسائی کی روایت (رقم ۲۳۷۴) میں تثنیہ «الخميسين»کے لفظ کے ساتھ ہے ، اور سیاق و سباق سے یہی متبادر ہوتا ہے کیونکہ اس کے بغیر تین دن کی تفصیل نہیں ہو پاتی۔","صحیح",{"u2":"امہات المؤمنین میں سے ایک کا بیان ہے کہ رسول اللہ صلی اللہ علیہ وسلم ذوالحجہ کے (پہلے) نو دن، عاشورہ محرم، ہر مہینے میں تین دن اور ہر مہینے کے پہلے سوموار اور جمعرات کو روزہ رکھا کرتے تھے۔"}],[2438,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"ان دنوں یعنی عشرہ ذی الحجہ کا نیک عمل اللہ تعالی کو تمام دنوں کے نیک اعمال سے زیادہ محبوب ہے\"، لوگوں نے عرض کیا: اللہ کے رسول! اللہ کی راہ میں جہاد بھی (اسے نہیں پا سکتا) ؟ آپ صلی اللہ علیہ وسلم نے فرمایا: \"جہاد بھی نہیں، مگر ایسا شخص جو اپنی جان و مال کے ساتھ نکلا اور لوٹا ہی نہیں\"۔","صحیح",{"u2":"سیدنا ابن عباس رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” اللہ تعالیٰ کو کوئی نیک عمل کسی دن میں اس قدر پسندیدہ نہیں ہے جتنا کہ ان دنوں میں پسندیدہ اور محبوب ہوتا ہے۔ “ یعنی ذوالحجہ کے پہلے عشرہ میں۔ صحابہ نے کہا: اے اللہ کے رسول! کیا جہاد فی سبیل اللہ بھی نہیں؟ آپ صلی اللہ علیہ وسلم نے فرمایا ” نہیں، جہاد فی سبیل اللہ بھی نہیں مگر جو کوئی شخص اپنی جان و مال لے کر نکلا ہو اور پھر کچھ واپس نہ لایا ہو۔ “","f2":"یہ احادیث دلیل ہیں کہ ذوالحجہ کے پہلے نو دنوں میں روزے رکھنے اور دیگر اعمال صالحہ کی انتہائی فضیلت ہے۔ رمضان کے آخری عشرہ اور عشرہ ذی الحجہ میں تقابلی طور پر علماء اس طرح بیان کرتے ہیں عشرہ رمضان کی راتیں افضل ہیں کیونکہ ان میں لیلة القدر آتی ہے اور عشرہ ذی الحجہ کے دن افضل ہیں۔"}],[2439,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو عشرہ ذی الحجہ ۱؎ میں کبھی روزے رکھتے ہوئے نہیں دیکھا۔\n§وضاحت\n۱؎ : اس سے مراد ذی الحجہ کے ابتدائی نو دن ہیں یہ حدیث ان روایات میں سے ہے جن کی تاویل کی جاتی ہے کیونکہ ان نو دنوں میں روزہ رکھنا مکروہ نہیں بلکہ مستحب ہے، خاص کر یوم عرفہ (حاجیوں کے میدان عرفات میں وقوف کے دن )کے روزے کی احادیث میں بڑی فضیلت آئی ہے، ہو سکتا ہے کہ نبی اکرم صلی اللہ علیہ وسلم کسی بیماری یا سفر کی وجہ سے کبھی روزہ نہ رکھا ہو نیز عائشہ رضی اللہ عنہا کے نہ دیکھنے سے یہ لازم نہیں آتا کہ آپ روزہ نہ رکھتے رہے ہوں۔","صحیح",{"u2":"ام المؤمنین سیدہ عائشہ رضی اللہ عنہا ا بیان کرتی ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو عشرہ ذی الحجہ میں کبھی بھی روزے سے نہیں دیکھا۔","f2":"عشرہ ذی الحجہ سے مراد ذوالحجہ کے پہلے نو دن ہیں۔ ان دنوں میں روزہ رکھنا بہت ہی مستحب ہے جیسے کہ اوپر کی احادیث میں آیا ہے اور حدیث:2437 میں آپ صلی اللہ علیہ وسلم کا عمل مذکور ہوا ہے اور حضرت عائشہ رضی اللہ عنہا کے اس بیان کا مفہوم یوں ہے کہ یا تو نبی صلی اللہ علیہ وسلم بعض عوارض کی بنا پر روزے نہیں رکھ سکے یا حضرت عائشہ رضی اللہ عنہا کو اتفاق نہیں ہوا کہ انہیں روزے سے دیکھیں۔"}],[2440,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے عرفات میں یوم عرفہ (نویں ذی الحجہ) کے روزے سے منع فرمایا۔\n§وضاحت\n۱؎ : یوم عرفہ (عرفہ کے دن) کا روزہ یعنی (۹) ذی الحجہ کے دن کا روزہ ، اور سعودی عرب کے ٹائم ٹیبل اور حج کے دن کے اعلان کے مطابق عرفات میں حجاج کے اجتماع کے دن کا روزہ ہے، اور یہ امیر حج کے اعلان کے مطابق مکہ مکرمہ میں اس دن ذی الحجۃ کی (۹) تاریخ ہو گی، اختلاف مطالع کی وجہ سے تاریخوں کے فرق میں عام مسلمان مکہ کی تاریخ کا خیال رکھیں۔","ضعیف",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ نے بیان کیا کہ رسول اللہ صلی اللہ علیہ وسلم نے منع فرمایا ہے کہ عرفہ کے روز عرفات میں روزہ رکھا جائے۔","f2":"(1) ذوالحجہ کی نویں تاریخ کو، جس دن وقوف عرفات ہوتا ہے، یوم عرفہ کہتے ہیں۔ (2) یہ حدیث ضعیف ہے۔ اس لیے اس سے ممانعت ثابت نہیں ہوتی۔ البتہ چونکہ حجاج کو عرفات کا وقوف اور اس اثنا میں دعا و مناجات میں مشغول رہنا ہوتا ہے اس لیے ان کے لیے یہ عمل روزے کی نسبت اولیٰ ہے۔ غیر حاجی کے لیے اس روزے کی فضیلت ثابت ہے جو پیچھے بیان ہو چکی ہے۔(حدیث:2425)"}],[2441,"ام الفضل بنت حارث رضی اللہ عنہا سے روایت ہے کہ ان کے پاس لوگ رسول صلی اللہ علیہ وسلم کے یوم عرفہ (نویں ذی الحجہ) کے روزے سے متعلق جھگڑنے لگے، کچھ لوگ کہہ رہے تھے کہ آپ صلی اللہ علیہ وسلم روزے سے ہیں اور کچھ کہہ رہے تھے کہ روزے سے نہیں ہیں چنانچہ میں نے دودھ کا ایک پیالہ آپ صلی اللہ علیہ وسلم کی خدمت میں بھیجا اس وقت آپ عرفہ میں اپنے اونٹ پر وقوف کئے ہوئے تھے تو آپ نے اسے نوش فرما لیا۔","صحیح",{"u2":"سیدہ ام فضل بنت حارث رضی اللہ عنہا ا سے مروی ہے کہ عرفہ کے روز ان کے ہاں کچھ لوگوں نے رسول اللہ صلی اللہ علیہ وسلم کے روزے کے بارے میں اختلاف کیا، کچھ نے کہا: آپ روزے سے ہیں اور کچھ نے کہا آپ روزے سے نہیں ہیں۔ چنانچہ میں نے آپ کی خدمت میں دودھ کا ایک پیالہ بھیج دیا، جب کہ آپ عرفہ کے میدان میں اپنے اونٹ پر سوار وقوف فرمائے ہوئے تھے، تو آپ نے وہ نوش فر لیا۔ (اور اس طرح معلوم ہو گیا کہ آپ نے روزہ نہیں رکھا ہے)۔"}],[2442,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ زمانہ جاہلیت میں قریش عاشورہ کا روزہ رکھتے تھے، اور رسول اللہ صلی اللہ علیہ وسلم بھی اس کا روزہ نبوت سے پہلے رکھتے تھے، پھر جب آپ صلی اللہ علیہ وسلم مدینہ آئے تو آپ نے اس کا روزہ رکھا، اور اس کے روزے کا حکم دیا، پھر جب رمضان کے روزے فرض ہوئے تو رمضان کے روزے ہی فرض رہے، اور عاشورہ کا روزہ چھوڑ دیا گیا اب اسے جو چاہے رکھے جو چاہے چھوڑ دے۔","صحیح",{"u2":"ام المؤمنین سیدہ عائشہ رضی اللہ عنہا ا بیان کرتی ہیں کہ عاشورا (دسویں محرم) کا دن ایسا تھا کہ اہل قریش اسلام سے پہلے اس کا روزہ رکھا کرتے تھے اور رسول اللہ صلی اللہ علیہ وسلم بھی نبوت سے پہلے یہ روزہ رکھتے تھے۔ جب رسول اللہ صلی اللہ علیہ وسلم مدینہ منورہ تشریف لائے تو آپ نے اس دن کا روزہ رکھا اور مسلمانوں کو بھی اس کا حکم دیا۔ پس جب رمضان فرض ہوا تو وہی فریضہ ہو گیا اور عاشورا چھوڑ دیا گیا، جو چاہتا رکھ لیتا اور جو چاہتا نہ رکھتا۔"}],[2443,"عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ زمانہ جاہلیت میں ہم عاشورہ کا روزہ رکھتے تھے، پھر جب رمضان کے روزوں فرضیت نازل ہوئی تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"یہ (یوم عاشوراء) اللہ کے دنوں میں سے ایک دن ہے لہٰذا جو روزہ رکھنا چاہے رکھے، اور جو نہ چاہے نہ رکھے\"۔","صحیح",{"u2":"سیدنا ابن عمر رضی اللہ عنہ کا بیان ہے کہ اسلام سے پہلے ہم دسویں محرم کو روزہ رکھا کرتے تھے۔ جب رمضان کا حکم نازل ہوا تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” یہ اللہ کے دنوں میں سے ایک دن ہے جو چاہے اس کا روزہ رکھ لے اور جو چاہے چھوڑ دے۔ “","f2":"دن تو سارے ہی اللہ کے ہیں، مگر جن ایام میں کوئی خاص واقعہ پیش آیا ہو اور دینی و شرعی اعتبار سے ان کی اہمیت ہو، تو انہیں (أَيَّامَ ٱللَّهِ) کہا گیا ہے۔"}],[2444,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ جب نبی اکرم صلی اللہ علیہ وسلم مدینہ تشریف لائے تو یہودیوں کو یوم عاشورہ کا روزہ رکھتے ہوئے پایا، اس کے متعلق جب ان سے دریافت کیا گیا تو انہوں نے بتایا کہ یہ وہ دن ہے جس میں اللہ تعالی نے موسی (وضاحت) کو فرعون پر فتح نصیب کی تھی، چنانچہ تعظیم کے طور پر ہم اس دن کا روزہ رکھتے ہیں، (یہ سن کر) رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\"ہم موسی علیہ السلام کے تم سے زیادہ حقدار ہیں\"، اور آپ صلی اللہ علیہ وسلم نے اس دن روزہ رکھنے کا حکم فرمایا۔","صحیح",{"u2":"سیدنا ابن عباس رضی اللہ عنہ سے مروی ہے کہ نبی کریم صلی اللہ علیہ وسلم جب مدینہ منورہ تشریف لائے تو دیکھا کہ یہود عاشورا کا روزہ رکھتے ہیں۔ ان سے اس کے بارے میں پوچھا گیا، تو انہوں نے کہا: یہ دن وہ ہے کہ جس میں اللہ تعالیٰ نے موسیٰ علیہ السلام کو فرعون پر غالب فرمایا تھا، اور ہم اس کی تعظیم میں روزہ رکھتے ہیں۔ تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” ہم تمہاری نسبت موسیٰ علیہ السلام سے زیادہ قریب ہیں “ اور اس دن کے روزے کا حکم ارشاد فرمایا۔"}],[2445,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ جس وقت رسول اللہ صلی اللہ علیہ وسلم نے عاشوراء کے دن کا روزہ رکھا اور ہمیں بھی اس کے روزہ رکھنے کا حکم فرمایا تو لوگوں نے عرض کیا: اللہ کے رسول! یہ ایسا دن ہے کہ یہود و نصاری اس دن کی تعظیم کرتے ہیں، یہ سن کر رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اگلے سال ہم نویں محرم کا بھی روزہ رکھیں گے\"، لیکن آئندہ سال نہیں آیا کہ آپ وفات فرما گئے ۱؎۔\n§وضاحت\n۱؎ : یہود کی مخالفت میں اس کے ساتھ نو کو بھی روزہ رکھنے کا عزم کیا تھا اور قولا اس کا حکم بھی دیا تھا، ویسے ایک دن پہلے بھی روزہ رہنے سے شکرانہ ادا ہو سکتا ہے۔","صحیح",{"u2":"سیدنا عبداللہ بن عباس رضی اللہ عنہ بیان کرتے ہیں کہ جب نبی کریم صلی اللہ علیہ وسلم نے عاشورا کا روزہ رکھا اور ہمیں بھی اس کا حکم دیا، تو صحابہ نے کہا: اے اللہ کے رسول! اس دن کی یہود و نصاریٰ تعظیم کرتے ہیں۔ تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” جب اگلا سال آئے گا تو ہم نویں تاریخ کا (بھی) روزہ رکھیں گے۔ “ مگر اگلا سال نہ آیا کہ رسول اللہ صلی اللہ علیہ وسلم کی وفات ہو گئی۔","f2":"(1) سلف و خلف کے جمہور علماء اس بات کے قائل ہیں کہ عاشورا سے مراد محرم کی دسویں تاریخ ہے، مگر حضرت ابن عباس رضی اللہ عنہ سے مروی ہے کہ اس سے مراد نویں محرم ہے۔ اور اس کی توجیہ یہ بیان کی جاتی ہے کہ اہل عرب کا ایک انداز یہ تھا کہ اونٹوں کو چراگاہ میں چرانے کے بعد پانی پلانے کے لیے لاتے تو جب انہوں نے ایک دن پانی پلانے کے بعد دو دن چرایا ہوتا اور اگلے دن آتے تو (وردنا اربعا) ہم چوتھے دن آئے یا چوتھے دن پانی پلایا، حالانکہ درحقیقت وہ تیسرا دن ہوتا۔ اسی طرح تین دن چرانے کے بعد اگلے دن لوٹتے تو کہتے (وردنا خمسا) ہم پانشویں دن آئے یا پانچوین دن پانی پلایا حالانکہ در حقیقت وہ چوتھا دن ہوتا۔ اسی انداز پر حضرت ابن عباس عاشورا کو نویں تاریخ بتاتے ہیں۔ (خطابی) مگر یہ توجیہ مرجوح ہے راجح مفہوم آگے آرہا ہے۔ (2) اس فرمان مبارک کا یہ مفہوم ہے کہ ہم نویں تاریخ کا بھی روزہ رکھیں گے۔ دیگر روایات کی روشنی میں یہی معنی درست ہے۔ مسند احمد میں حضرت ابن عباس رضی اللہ عنہ سے مرفوعا وارد ہے کہ نبی صلی اللہ علیہ وسلم نے فرمایا: یہودیوں کی مخالفت کرو، ان سے ایک دن پہلے یا ایک دن بعد روزہ رکھو۔ (مسند احمد:1/241) جناب عطاء حضرت ابن عباس رضی اللہ عنہ سے روایت کرتے ہیں کہ نویں اور دسویں کا روزہ رکھو اوریہود کی مخالفت کرو۔ (البيهقي:4/287) ان روایات سے معلوم ہوتا ہے کہ (پیش آمدہ روایت:2446 میں) حضرت ابن عباس رضی اللہ عنہ کا یہ کہنا کہ جب تم محرم کا چاند دیکھو تو شمار کرو جب نویں تاریخ آئے تو روزہ رکھو۔ اس سے مراد یہ نہیں کہ عاشورا نویں تاریخ کو کہتے ہیں، بلکہ ان کی مراد یہ ہے کہ دسویں سے پہلے نویں تاریخ کا روزہ بھی رکھو۔ (افادات امام ابن القیم رحمة اللہ علیہ)"}],[2446,"حکم بن الاعرج کہتے ہیں کہ میں ابن عباس رضی اللہ عنہما کی خدمت میں حاضر ہوا اس وقت وہ مسجد الحرام میں اپنی چادر کا تکیہ لگائے ہوئے تھے، میں نے عاشوراء کے روزے سے متعلق ان سے دریافت کیا تو انہوں نے کہا: جب تم محرم کا چاند دیکھو تو گنتے رہو اور نویں تاریخ آنے پر روزہ رکھو، میں نے پوچھا: محمد صلی اللہ علیہ وسلم بھی اسی طرح روزہ رکھتے تھے؟ تو انہوں نے کہا: (ہاں) محمد صلی اللہ علیہ وسلم بھی اسی طرح روزہ رکھتے تھے ۱؎۔\n§وضاحت\n۱؎ : پچھلی حدیث میں ہے ’’آئندہ سال آیا نہیں کہ آپ وفات پا گئے ‘‘ اور اس حدیث میں ہے، ’’محمد صلی اللہ علیہ وسلم بھی اسی طرح (نو محرم کا) روزہ رکھتے تھے ‘‘ بات صحیح یہی ہے کہ نو کے روزہ رکھنے کا آپ صلی اللہ علیہ وسلم کو موقع نہیں ملا، لیکن ابن عباس رضی اللہ عنہما نے اس بنا پر کہہ دیا کہ آپ صلی اللہ علیہ وسلم نے آئندہ سے روزہ رکھنے کا عزم ظاہر کیا تھا، نیز قولا اس کا حکم بھی دیا تھا۔","صحیح",{"u2":"حکم بن اعرج بیان کرتے ہیں کہ میں سیدنا ابن عباس رضی اللہ عنہ کی خدمت میں حاضر ہوا تو آپ مسجد الحرام میں اپنی چادر کا تکیا بنائے ہوئے تھے۔ میں نے ان سے عاشورائے محرم کے روزے کے متعلق پوچھا۔ آپ نے فرمایا جب تم محرم کا چاند دیکھو تو شمار کرو، جب نویں تاریخ ہو تو روزہ رکھو۔ میں نے کہا: کیا محمد صلی اللہ علیہ وسلم ایسے ہی روزہ رکھا کرتے تھے؟ انہوں نے کہا: محمد صلی اللہ علیہ وسلم ایسے ہی روزہ رکھا کرتے تھے۔","f2":"رسول اللہ صلی اللہ علیہ وسلم نے عملا تو نویں تاریخ کا روزہ نہیں رکھا مگر آپ کا عزم یہی تھا۔ اسی پر حضرت ابن عباس رضی اللہ عنہ نے کہہ دیا کہ محمد صلی اللہ علیہ وسلم ایسے ہی کیا کرتے تھے۔ اور مطلوب بھی یہی ہے کہ نویں دسویں یا دسویں گیارھویں کا روزہ رکھا جائے۔"}],[2447,"عبدالرحمٰن بن مسلمہ اپنے چچا سے روایت کرتے ہیں کہ قبیلہ اسلم کے لوگ نبی اکرم صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوئے، آپ نے پوچھا: \"کیا تم لوگوں نے اپنے اس دن کا روزہ رکھا ہے؟\" جواب دیا: نہیں، فرمایا: \"دن کا بقیہ حصہ بغیر کھائے پئے پورا کرو اور روزے کی قضاء کرو\"۔ ابوداؤد کہتے ہیں: یعنی عاشوراء کے دن۔","ضعیف",{"u2":"عبدالرحمٰن بن مسلمہ اپنے چچا سے روایت کرتے ہیں کہ قبیلہ اسلم کے لوگ نبی کریم صلی اللہ علیہ وسلم کی خدمت میں پہنچے تو آپ نے ان سے پوچھا ” کیا تم نے آج کا روزہ رکھا ہے؟ “ انہوں نے کہا: نہیں۔ آپ صلی اللہ علیہ وسلم نے فرمایا ” تو بقیہ دن کو بطور روزہ کے پورا کرو اور اس کی قضاء کرنا۔ “ امام ابوداؤد رضی اللہ عنہ نے کہا: اس سے مراد عاشورا کا دن تھا۔","f2":"یہ روایت ضعیف ہے۔ صحیح مسلم میں اس معنی کی حدیث موجود ہے مگر اس میں قضا کرنے کا ذکر نہیں ہے۔"}],[2448,"عبداللہ بن عمرو رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے مجھ سے فرمایا: \"اللہ تعالی کو سب سے زیادہ پسندیدہ روزے داود علیہ السلام کے روزے ہیں، اور پسندیدہ نماز بھی داود کی نماز ہے: وہ آدھی رات تک سوتے، اور تہائی رات تک قیام کرتے (تہجد پڑھتے)، پھر رات کا چھٹا حصہ سوتے، اور ایک دن روزہ نہ رکھتے، ایک دن رکھتے\"۔","صحیح",{"u2":"سیدنا عبداللہ بن عمرو رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے مجھ سے فرمایا ” اللہ تعالیٰ کے نزدیک سب سے زیادہ پسندیدہ روزے، سیدنا داود علیہ السلام کے ہیں، اور سب سے پسندیدہ نماز، اللہ تعالیٰ کے ہاں سیدنا داود علیہ السلام کی نماز ہے، وہ آدھی رات سوتے، پھر تہائی رات قیام کرتے اور پھر اس کا چھٹا حصہ سوتے تھے، اور وہ ایک دن افطار اور ایک دن روزہ رکھا کرتے تھے۔ “","f2":"رات کی نماز کی یہ کیفیت انتہائی مناسب ہے۔ اس میں اللہ کے حق کی ادائیگی کے ساتھ ساتھ حق نفس کا بھی لحاظ ہے۔ مثلا اگر رات کو آٹھ گھنٹے کی سمجھا جائے تو پہلے چار گھنٹے نیند ہوئی، پھر دو گھنٹے چالیس منٹ تہجد۔ بعد ازاں پھر ایک گھنٹہ بیس منٹ کے لیے نیند اور راحت ہے۔ ایسے ہی روزے میں ہے۔ اس فضیلت کے ساتھ ساتھ محمد رسول اللہ صلی اللہ علیہ وسلم کی تلقین و توجیہ افضل و اعلیٰ ہے۔"}],[2449,"قتادہ بن ملحان قیسی رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم ہمیں ایام بیض یعنی تیرھویں، چودھویں اور پندرھویں تاریخوں میں روزے رکھنے کا حکم فرماتے، اور فرماتے: \"یہ پورے سال روزے رکھنے کے مثل ہے\"۔","صحیح",{"u2":"ابن ملحان قیسی (عبدالملک بن قتادہ) اپنے والد (قتادہ بن ملحان رضی اللہ عنہ) سے بیان کرتے ہیں، وہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم ہم سے فرمایا کرتے تھے کہ ہم ایام بیض یعنی تیرہ، چودہ اور پندرہ تاریخ کے روزے رکھا کریں۔ آپ صلی اللہ علیہ وسلم نے فرمایا ” یہ روزے ایسے ہیں گویا سارے زمانے کے روزے۔ “","f2":"تیرہ، چودہ اور پندرہ تاریخ کے ایام کو ایام بیض (سفید راتوں کے دن) اس لحاظ سے کہا جاتا ہے کہ ان راتوں میں چاند تقریبا ساری رات چمکتا ہے۔ ان دنوں کے روزوں میں تفاؤل یہ ہے کہ جس طرح ان راتوں کا اندھیرا اجالے سے بدلا ہوا ہوتا ہے ایسے ہی اللہ عزوجل روزے دار کی سیاہ کاریوں کو سفیدی اور چمک سے بدل دے گا۔ اور نبی صلی اللہ علیہ وسلم کا یہ حکم ترغیب و تشویش کے معنی میں ہے۔"}],[2450,"عبداللہ بن مسعود رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم ہر مہینے کے شروع میں تین دن روزے رکھتے۔","حسن",{"u2":"سیدنا عبداللہ بن مسعود رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم ہر مہینے کی ابتداء میں تین دن روزے رکھا کرتے تھے۔","f2":"ایام بیض کی فضیلت ثابت ہے۔ اور نبی صلی اللہ علیہ وسلم بعض اوقات بلا تعیین و تخصیص تین روزے رکھا کرتے تھے تاکہ وجوب نہ سمجھا جائے۔ اس طرح بعض دفعہ آپ مہینے کی ابتدا میں تین روزے رکھتے۔ حضرت عبداللہ بن مسعود رضی اللہ عنہ کے علم میں آپ کے یہی ابتدائی دن آئے، چنانچہ انہوں نے اس کے مطابق بیان کر دیا۔ اور حضرت عائشہ رضی اللہ عنہا کے علم میں آپ کے ایام بیض کے روزے تھے جو آپ اکثر رکھا کرتے تھے تو حضرت عائشہ رضی اللہ عنہا نےاس کے مطابق بیان کر دیا۔ اس لیے ان دونوں کے درمیان کوئی منافات نہیں ہے۔"}],[2451,"ام المؤمنین حفصہ رضی اللہ عنہا کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم مہینے میں تین دن روزے رکھتے تھے یعنی (پہلے ہفتہ کے) دوشنبہ، جمعرات اور دوسرے ہفتے کے دوشنبہ کو۔","حسن",{"u2":"ام المؤمنین سیدہ حفصہ رضی اللہ عنہا ا بیان کرتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم مہینے میں تین روزے رکھا کرتے تھے۔ (پہلے) سوموار اور جمعرات کو اور اگلے ہفتے میں (دوسرے) سوموار کو۔ (اس طرح کل تین روزے ہو جاتے ہیں۔)"}],[2452,"ہنیدہ خزاعی اپنی والدہ سے روایت کرتی ہیں، وہ کہتی ہیں کہ میں ام المؤمنین ام سلمہ رضی اللہ عنہا کے پاس گئی اور ان سے روزے کے متعلق سوال کیا تو انہوں نے کہا: مجھے رسول اللہ صلی اللہ علیہ وسلم ہر مہینے تین دن روزے رکھنے کا حکم فرماتے تھے، ان میں سے پہلا دوشنبہ کا ہوتا اور جمعرات کا ۱؎۔\n§وضاحت\n۱؎ : نسائی میں اس روایت کے الفاظ ہیں ، «أَوَّلُ خَمِيْسٍ‘‘ ’’وَالاثْنَيْنِ وَالاثْنَيْنِ» یعنی: مہینے کا پہلا جمعرات اور دوشنبہ ، پھر دوسرا دوشنبہ ، بعض روایتوں میں تیسرا دن جمعرات ہے (حدیث نمبر: ۲۴۳۷) بعض روایتوں میں درمیان ماہ کے تین دنوں کا تذکرہ ہے ، اور اگلی حدیث کا خلاصہ یہ ہے کہ کوئی خاص دن متعین نہیں تھا، بس تین دن کا روزہ مقصود تھا، سب مختلف اوقات وحالات کے لحاظ سے تھا۔","منکر",{"u2":"ہنیدہ خزاعی اپنی والدہ سے بیان کرتے ہیں ‘ ان کا کہنا ہے کہ میں ام المؤمنین سیدہ ام سلمہ رضی اللہ عنہا ا کی خدمت میں حاضر ہوئی اور ان سے روزوں کے متعلق دریافت کیا تو انہوں نے کہا: رسول ا اللہ صلی اللہ علیہ وسلم مجھے ارشاد فرمایا کرتے تھے کہ میں ہر مہینے میں تین روزے رکھ لیا کروں۔ ان میں پہلا سوموار کا ہو اور (دوسرا) جمعرات کا۔"}],[2453,"معاذہ کہتی ہیں کہ میں نے ام المؤمنین عائشہ رضی اللہ عنہا سے سوال کیا کہ کیا رسول اللہ صلی اللہ علیہ وسلم ہر مہینے تین دن روزے رکھتے تھے؟ انہوں نے جواب دیا: ہاں، میں نے پوچھا: مہینے کے کون سے دنوں میں روزے رکھتے تھے؟ جواب دیا کہ آپ کو اس کی پروا نہیں ہوتی تھی کہ مہینہ کے کن دنوں میں رکھیں۔","صحیح",{"u2":"معاذہ (العدویہ) کہتی ہیں کہ میں نے ام المؤمنین سیدہ عائشہ رضی اللہ عنہا ا سے پوچھا کیا رسول ا اللہ صلی اللہ علیہ وسلم ہر مہینے میں تین روزے رکھا کرتے تھے؟ انہوں نے کہا: ہاں! میں نے کہا: مہینے کی کن تاریخوں یا دنوں میں روزے رکھا کرتے تھے؟ انہوں نے کہا: آپ صلی اللہ علیہ وسلم تاریخوں یا دنوں کی پروا نہ کرتے تھے۔ (کوئی خاص ایام مقرر نہ تھے جب چاہتے روزہ رکھ لیا کرتے۔)","f2":"گزشتہ ابواب میں اکیلے جمعے یا ہفتے کے دن کی تخصیص کی ممانعت کا بیان گزر چکا ہے، لہذا ان کا خیال رکھنا ہو گا۔"}],[2454,"ام المؤمنین حفصہ رضی اللہ عنہا سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جس نے فجر ہونے سے پہلے روزے کی نیت نہ کی اس کا روزہ نہیں ہو گا\"۔ ابوداؤد کہتے ہیں: اسے لیث اور اسحاق بن حازم نے عبداللہ بن ابی بکر سے اسی کے مثل (یعنی مرفوعاً)روایت کیا ہے، اور اسے معمر، زبیدی، ابن عیینہ اور یونس ایلی نے ام المؤمنین حفصہ رضی اللہ عنہا پر موقوف کیا ہے، یہ سارے لوگ زہری سے روایت کرتے ہیں۔","صحیح",{"u2":"ام المؤمنین سیدہ حفصہ رضی اللہ عنہا ا سے مروی ہے کہ رسول ا اللہ صلی اللہ علیہ وسلم نے فرمایا ” جس شخص نے فجر سے پہلے روزے کی نیت نہ کی تو اس کا روزہ درست نہ ہو گا۔ امام ابوداؤد رضی اللہ عنہ فرماتے ہیں کہ یہ روایت امام لیث اور اسحاق بن حازم نے بھی عبداللہ بن ابی بکر سے اسی کے مثل مرفوعاً روایت کی ہے اور معمر ‘ زبیدی ‘ ابن عیینہ اور یونس الایلی بواسطہ زہری، سیدہ حفصہ رضی اللہ عنہا ا سے موقوفاً روایت کرتے ہیں۔","f2":"فرض روزوں میں فجر سے پہلے نیت کر لینا ضروری ہے اور افضل یہ ہے کہ ہر ہر روزے کی نیت علیحدہ سے کی جائے مگر خیال رہے کہ نیت دل کے عزم و ارادہ کا نام ہے۔ ان عبادات میں نبی صلی اللہ علیہ وسلم سے یا ان کے بعد صحابہ کرام رضی اللہ عنھم سے لفظی نیت کا کوئی ثبوت نہیں ہے، لفظی نیت کا اہتمام بدعت ہے۔"}],[2455,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم جب میرے پاس تشریف لاتے تو پوچھتے: کیا تمہارے پاس کچھ کھانا ہے؟ جب میں کہتی: نہیں، تو فرماتے: \"میں روزے سے ہوں\"، ایک دن آپ صلی اللہ علیہ وسلم ہمارے پاس تشریف لائے، تو ہم نے کہا: اللہ کے رسول! ہمارے پاس ہدیے میں (کھجور، گھی اور پنیر سے بنا ہوا) ملیدہ آیا ہے، اور اسے ہم نے آپ کے لیے بچا رکھا ہے، تو آپ صلی اللہ علیہ وسلم نے فرمایا: \"لاؤ اسے حاضر کرو\"۔ طلحہ کہتے ہیں کہ آپ صلی اللہ علیہ وسلم نے روزے سے ہو کر صبح کی تھی لیکن روزہ توڑ دیا۔","حسن صحیح",{"u2":"ام المؤمنین سیدہ عائشہ رضی اللہ عنہا ا بیان کرتی ہیں کہ رسول ا اللہ صلی اللہ علیہ وسلم جب میرے ہاں تشریف لائے تو دریافت فرماتے ” کیا تمہارے ہاں کوئی کھانا ہے؟ “ جب ہم کہتے کہ نہیں ہے ‘ تو آپ صلی اللہ علیہ وسلم فرماتے ” میں روزہ رکھ لیتا ہوں۔ “ وکیع نے مزید بیان کیا کہ آپ صلی اللہ علیہ وسلم ایک دوسرے موقع پر ہمارے پاس تشریف لائے۔ ہم نے عرض کیا: اے ا اللہ کے رسول! ہمیں حیس (ایک خاص عربی طعام) کا ہدیہ بھیجا گیا ہے جو ہم نے آپ کے لیے سنبھال رکھا ہے۔ آپ نے فرمایا ” ادھر لے آؤ۔ “ طلحہ نے وضاحت کی کہ آپ نے صبح کو روزے کی نیت کی تھی مگر افطار کر لیا۔","f2":"نفلی روزے میں یہ رخصت ہے کہ اس کی نیت بعد از فجر بقول بعض زوال سے پہلے تک ہو سکتی ہے۔ ایسے ہی اگر کسی نے نفلی روزے کی نیت کر رکھی ہو تو کسی معقول عذر کی بنا پر افطار کر سکتا ہے۔ اس کی قضا کرنا ضروری نہیں۔"}],[2456,"ام ہانی رضی اللہ عنہا کہتی ہیں کہ فتح مکہ کا دن تھا، فاطمہ رضی اللہ عنہا آئیں اور رسول اللہ صلی اللہ علیہ وسلم کے بائیں جانب بیٹھ گئیں اور میں دائیں جانب بیٹھی، اس کے بعد لونڈی برتن میں کوئی پینے کی چیز لائی، اور آپ صلی اللہ علیہ وسلم کو پیش کیا، آپ نے اس میں سے نوش فرمایا، پھر مجھے دے دیا، میں نے بھی پیا، پھر میں نے پوچھا: اللہ کے رسول! میں تو روزے سے تھی، میں نے روزہ توڑ دیا ہے، آپ صلی اللہ علیہ وسلم نے فرمایا: \"کیا تم کسی روزے کی قضاء کر رہی تھیں؟\" جواب دیا نہیں، فرمایا: \"اگر نفلی روزہ تھا تو تجھے کوئی نقصان نہیں\" ۱؎۔\n§وضاحت\n۱؎ : ام المومنین حفصہ رضی اللہ عنہا کی پچھلی روایت سے فجر ہی سے نیت کا وجوب ثابت ہوتا ہے اور اس باب کی دونوں روایتوں سے عدم وجوب ! دونوں میں تطبیق یہ ہے کہ حفصہ کی روایت فرض روزے سے متعلق ہے، اور باب کی دونوں روایتیں نفلی روزے سے متعلق ہیں، سیاق سے یہ صاف ظاہر ہے۔","صحیح",{"u2":"سیدہ ام ہانی رضی اللہ عنہا ا بیان کرتی ہیں کہ فتح مکہ کے دن سیدہ فاطمہ رضی اللہ عنہا ا تشریف لائیں اور رسول ا اللہ صلی اللہ علیہ وسلم کی بائیں طرف بیٹھ گئیں اور ام ہانی رضی اللہ عنہا ا آپ کی دائیں طرف تھیں۔ بیان کرتی ہیں کہ خادمہ ایک برتن لے کر آئی ‘ اس میں مشروب تھا ‘ اس نے وہ نبی کریم صلی اللہ علیہ وسلم کو دیا تو آپ نے اس میں سے نوش فرمایا اور پھر ام ہانی کو دے دیا تو انہوں نے بھی اس سے پی لیا اور بولیں: اے ا اللہ کے رسول! میں نے روزہ رکھا ہوا تھا اور توڑ لیا ہے۔ آپ صلی اللہ علیہ وسلم نے پوچھا ” کیا یہ قضاء کا روزہ تھا؟ “ انہوں نے کہا: نہیں۔ آپ نے فرمایا ” اگر یہ نفلی تھا تو کوئی حرج نہیں۔ “"}],[2457,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ میرے اور ام المؤمنین حفصہ رضی اللہ عنہا کے لیے کچھ کھانا ہدیے میں آیا، ہم دونوں روزے سے تھیں، ہم نے روزہ توڑ دیا، اس کے بعد رسول اللہ صلی اللہ علیہ وسلم تشریف لائے ہم نے آپ سے دریافت کیا: اللہ کے رسول! ہمارے پاس ہدیہ آیا تھا ہمیں اس کے کھانے کی خواہش ہوئی تو روزہ توڑ دیا (یہ سن کر) آپ صلی اللہ علیہ وسلم نے فرمایا: \"روزہ توڑ دیا تو کوئی بات نہیں، دوسرے دن اس کے بدلے رکھ لینا\"۔","ضعیف",{"u2":"ام المؤمنین سیدہ عائشہ رضی اللہ عنہا ا سے روایت ہے ‘ وہ بیان کرتی ہیں کہ مجھے اور حفصہ رضی اللہ عنہا ا کو کوئی کھانا ہدیہ بھیجا گیا جبکہ ہم نے روزہ رکھا ہوا تھا ‘ پس ہم نے روزہ توڑ لیا۔ رسول ا اللہ صلی اللہ علیہ وسلم تشریف لائے اور ہم نے ان سے عرض کیا: اے ا اللہ کے رسول! ہمیں ہدیہ دیا گیا تھا اور ہمارا کھانے کو دل چاہا تو ہم نے روزہ افطار کر لیا۔ رسول ا اللہ صلی اللہ علیہ وسلم نے فرمایا ” کوئی حرج نہیں ‘ اس کی بجائے ایک روزہ رکھ لینا۔ “ ابوسعید بن الاعرابی کہتے ہیں کہ یہ روایت ثابت نہیں ہے۔","f2":"نفلی روزے کی قضا واجب نہیں ہے اگر رکھے تو مستحب ہے۔ تاہم اس طرح کہ عمل کو اپنی عادت نہیں بنانا چاہیے۔ مذکورہ روایت ضعیف ہے۔"}],[2458,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"شوہر کی موجودگی میں اس کی اجازت کے بغیر کوئی عورت روزہ نہ رکھے سوائے رمضان کے، اور بغیر اس کی اجازت کے اس کی موجودگی میں کسی کو گھر میں آنے کی اجازت نہ دے\"۔","صحیح",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول ا اللہ صلی اللہ علیہ وسلم نے فرمایا ” عورت کو روا نہیں کہ شوہر موجود ہو تو اس کی اجازت کے بغیر روزہ رکھے مگر یہ کہ رمضان کے روزے ہوں۔ اور ایسے ہی روا نہیں کہ شوہر موجود ہو تو اس کی اجازت کے بغیر کسی کو گھر میں آنے دے۔ “","f2":"روزے کی حالت میں زوجین کے مابین تعلقات زن و شو قائم نہیں ہو سکتے۔ علاوہ ازیں بھوک و پیاس کی وجہ سے طبیعت میں گرانی سی بھی آ اجتی ہے اور عین فطری بات ہے کہ شوہر بالعموم ایسی کیفیت گوارا نہیں کرتے اور اس کے نتائج نا مناسب ہو سکتےہیں۔ اس لیے شریعت نے ان کے تعلقات میں معمولی رخنہ آنے کی بھی اجازت نہیں دی اور عورت کو پابند کیا ہے کہ نفلی روزے کے لیے شوہر کی اجازت حاصل کرے۔ اور یہ بھی معلوم ہوا کہ بیوی کو شوہر کی تسکین کے لیے انتہائی حساس اور ذمہ دار ہونا چاہیے، یہ علائق محض نفسیاتی نہیں بلکہ شرعی بھی ہیں۔"}],[2459,"ابو سعید خدری رضی اللہ عنہ کہتے ہیں کہ ایک عورت رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوئی، ہم آپ کے پاس تھے، کہنے لگی: اللہ کے رسول! میرے شوہر صفوان بن معطل رضی اللہ عنہ جب نماز پڑھتی ہوں تو مجھے مارتے ہیں، اور روزہ رکھتی ہوں تو روزہ تڑوا دیتے ہیں، اور فجر سورج نکلنے سے پہلے نہیں پڑھتے۔ صفوان اس وقت آپ صلی اللہ علیہ وسلم کے پاس موجود تھے، تو آپ صلی اللہ علیہ وسلم نے ان سے ان باتوں کے متعلق پوچھا جو ان کی بیوی نے بیان کیا تو انہوں نے کہا: اللہ کے رسول! اس کا یہ الزام کہ نماز پڑھنے پر میں اسے مارتا ہوں تو بات یہ ہے کہ یہ دو دو سورتیں پڑھتی ہے جب کہ میں نے اسے (دو دو سورتیں پڑھنے سے) منع کر رکھا ہے، آپ صلی اللہ علیہ وسلم نے فرمایا: \"لوگ اگر ایک ہی سورت پڑھ لیں تب بھی کافی ہے\"۔ صفوان نے پھر کہا کہ اور اس کا یہ کہنا کہ میں اس سے روزہ افطار کرا دیتا ہوں تو یہ روزہ رکھتی چلی جاتی ہے، میں جوان آدمی ہوں صبر نہیں کر پاتا، تو رسول اللہ صلی اللہ علیہ وسلم نے اس دن فرمایا: \"کوئی عورت اپنے شوہر کی اجازت کے بغیر (نفل روزہ) نہ رکھے\"۔ رہی اس کی یہ بات کہ میں سورج نکلنے سے پہلے نماز نہیں پڑھتا تو ہم اس گھرانے سے تعلق رکھتے ہیں جس کے بارے میں سب جانتے ہیں کہ سورج نکلنے سے پہلے ہم اٹھ ہی نہیں پاتے، آپ صلی اللہ علیہ وسلم نے فرمایا: \"جب بھی جاگو نماز پڑھ لیا کرو ۱؎\"۔\n§وضاحت\n۱؎ : صفوان بن معطل رضی اللہ عنہ کے اس بیان سے یہ معلوم ہوا کہ گویا آپ شرعی طور پر اس بات میں معذور تھے ، اور یہ واقعہ کبھی کبھار کا ہی ہو سکتا ہے ، جس کو مسئلہ بنا کر ان کی بیوی نے عدالت نبوی میں پیش کیا۔ صحابی رسول کے بارے میں یہ سوچا بھی نہیں جا سکتا کہ «قصداً و عمداً» وہ نماز میں تساہلی کرے گا ، رات بھر کی محنت و مزدوری کے بعد آدمی تھک کر چور ہو جاتا ہے ، اور فطری طور پر آخری رات کی نیند سے خود سے یا جلدی بیدار ہونا مشکل مسئلہ ہے ، اگر کبھی ایسی معذوری ہو جائے تو بیداری کے بعد نماز ادا کر لی جائے ، ایک بات یہ بھی واضح رہے کہ صفوان اور ان کے خاندان کے لوگ گہری نیند اور تاخیر سے اٹھنے کی عادت میں مشہور تھے ، جیسا کہ زیر بحث حدیث میں صراحت ہے ، نیز مسند احمد میں صفوان کا قول ہے کہ : میں گہری نیند والا ہوں ، اور ایسے خاندان سے ہوں جو اپنی گہری نیند کے بارے میں مشہور ہیں ( ۳؍۸۴- ۸۵ )۔ نیز مسند احمد میں ہے کہ آپ نے رسول اللہ صلی اللہ علیہ وسلم سے سوال کیا تھا کہ کن وقتوں میں نماز مکروہ ہے ؟ تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \"فجر کے بعد نماز سے رک جاؤ حتی کہ سورج نکل آئے ، جب سورج نکل آئے تو نماز پڑھو ...\" ( ۵ ؍۳۱۲ ) ۔ چنانچہ غزوات میں اپنی اسی عادت کی بنا پر قافلہء مجاہدین میں سب سے بعد میں لوگوں کے گرے پڑے سامان سمیٹ کر قافلہ سے مل جاتے ( ملاحظہ ہو واقعہ إفک جو کہ غزوہ بنی مصطلق میں ہوا ) ۔ یہ بھی واضح رہے کہ فجر میں مسلسل غیر حاضری کا معاملہ رسول اللہ صلی اللہ علیہ وسلم اور صحابہ کرام رضی اللہ عنہم سے مخفی نہیں رہ سکتا ، بلکہ یہ حرکت تو منافقین سے سرزد ہوتی تھی ، اور صحابہ کرام کے بارے میں یا صفوان رضی اللہ عنہ کے بارے میں تاریخ خاموش ہے۔","صحیح",{"u2":"سیدنا ابوسعید رضی اللہ عنہ بیان کرتے ہیں کہ ایک خاتون نبی کریم صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوئی جبکہ ہم بھی آپ کے پاس ہی تھے۔ اس نے کہا: اے ا اللہ کے رسول! میرا شوہر صفوان بن معطل جب میں نماز پڑھتی ہوں تو مجھے مارتا ہے اور جب روزہ رکھتی ہوں تو تڑوا دیتا ہے اور خود فجر کی نماز سورج چڑھے پڑھتا ہے۔ صفوان بھی وہیں تھے۔ چنانچہ آپ نے ان سے جو کچھ عورت نے کہا: تھا اس کے بارے میں پوچھا تو انہوں نے کہا: اے ا اللہ کے رسول! اس کا یہ کہنا کہ جب میں نماز پڑھتی ہوں تو یہ مارتا ہے۔ یہ دراصل دو دو سورتیں پڑھتی ہے اور میں نے اس کو اس (لمبی) قرآت سے روکا ہے۔ آپ صلی اللہ علیہ وسلم نے فرمایا ” اگر ایک سورت کی قرآت ہو تو بھی لوگوں کو کافی ہے۔ “ اور اس کا یہ کہنا کہ یہ میرا روزہ تڑوا دیتا ہے تو اس کی حالت یہ ہے کہ یہ روزے ہی رکھے جاتی ہے اور میں جوان آدمی ہوں ‘ صبر نہیں کر سکتا تو رسول ا اللہ صلی اللہ علیہ وسلم نے اس روزہ فرمایا ” کوئی عورت اپنے شوہر کی اجازت کے بغیر روزہ نہ رکھے۔ “ اور اس کا یہ کہنا کہ میں سورج چڑھے نماز پڑھتا ہوں ‘ تو حقیقت یہ ہے کہ ہمارا گھرانا اس بات میں معروف ہے اور ہم لوگ سورج نکلنے سے پہلے اٹھ ہی نہیں سکتے۔ تو آپ صلی اللہ علیہ وسلم نے فرمایا ” جب جاگا کرو تو نماز پڑھ لیا کرو۔ “ امام ابوداؤد رضی اللہ عنہ کہتے ہیں کہ اس روایت کو حماد بن سلمہ نے حمید یا ثابت سے ‘ انہوں نے ابی المتوکل سے بیان کیا ہے۔","f2":"(1) رسول اللہ صلی اللہ علیہ وسلم کی تربیت و تزکیہ سے مردوں کے علاوہ خواتین بھی بہرہ ور تھیں اور ان میں آخرت کی رغبت اس قدر بڑھ گئی تھی کہ اس طرح کی شکایت سامنے آئی جو اس حدیث میں بیان ہوئی ہے۔ حیف ہے ان لوگوں پر جو اس طرح کی مقدس ہستیوں کے ایمان کو مشکوک گردانتے ہیں۔ (2) شوہر کو حق ہے کہ بلا تخصیص وقت اپنی بیوی سے تمتع کرے، گویا حقوق تمتع اس کی ملک ہیں، بیوی کسی طرح انکار نہیں کر سکتی الا یہ کہ عذر شرعی اور معقول ہو، بلکہ انکار پر مناسب سزا بھی مباح ہے۔ (3) بعد از فاتحہ مختصر قراءت سے بھی نماز کامل ہوتی ہے۔ (4) عورت کو اس قدر لمبی نماز نہیں پڑھنی چاہیے کہ شوہر اس کے انتظار میں پیچ و تاب کھاتا رہے۔ (5) بیوی کو نفلی روزے شوہر کی اجازت کے بغیر نہیں رکھنے چاہئیں۔ بعض اوقات یہ اجازت میلان طبع سے بھی سمجھی جا سکتی ہے۔ (6) جناب صفوان بن معطل رضی اللہ عنہ جلیل القدر صحابہ میں سے تھے۔ ان کا ذکر حضرت عائشہ رضی اللہ عنہا کے متعلق واقعہ افک میں بھی آتا ہے۔ ان کا سورج چڑھنے نماز پڑھنا تو واقعتا بعد از طلوع ہوتا تھا یا مراد ہے کہ بالکل آخری وقت میں پڑھتے تھے کہ سورج نکلنے والا ہوتا۔ اور اس کا سبب انہوں نے بیان کیا ہے کہ یہ گویا خاندانی عادت سی تھی کہ یہ لوگ نیند کے متوالے تھے اگر کوئی جگانے والا نہ ہوتا تو ازخود جاگ نہ سکتے تھے۔ ایک عذر یہ بھی بیان ہوا کہ یہ لوگ رات کو دیر تک پانی ڈھوتے تھے اور دیر سے سونے کی وجہ سے صبح بروقت جاگ نہ سکتے تھے۔ بہرحال اگر عذر معقول ہو تو شرعا قبول ہے کہ سونے والے پر مواخذہ نہیں، ایسی صورت میں جب جاگ آئے فورا نماز پڑھ لے۔ اس سے صبح دیر سے اٹھ کر نماز پڑھنے کے معمول کو جواز بنانے پر استدلال نہیں کیا جا سکتا، اس لیے حضرت صفوان رضی اللہ عنہ کو یہ اجازت تو نبی صلی اللہ علیہ وسلم نے دی تھی، جن کو اس قسم کی صورت حال میں بذریعہ وحی مطلع کر دیا جاتا تھا۔ اس لیے حضرت صفوان کا عذر تو معقول سمجھ لیا گیا، لیکن ہم اپنے تساہل کو بھی اسی طرح کا معقول عذر سمجھ لیں، تو اس میں کوئی معقولیت نہیں ہو گی۔"}],[2460,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جب تم میں سے کسی کو دعوت دی جائے تو اسے قبول کرنا چاہیئے، اگر روزے سے نہ ہو تو کھا لے، اور اگر روزے سے ہو تو اس کے حق میں دعا کر دے\"۔ ہشام کہتے ہیں: «صلاۃ» سے مراد دعا ہے۔","صحیح",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول ا اللہ صلی اللہ علیہ وسلم نے فرمایا ” جب تم میں سے کسی کو کھانے کی دعوت ملے تو چاہیئے کہ قبول کر لے ‘ اگر روزے سے نہ ہو تو کھانا کھا لے اور اگر روزہ رکھا ہوا تو (مجلس میں حاضر ہو اور صاحب طعام کے لیے) دعا کرے۔ “ ہشام بن حسان نے وضاحت کی کہ اس حدیث میں ” صلاتہ “ کے معنی دعا کرنا ہیں۔ امام ابوداؤد رضی اللہ عنہ کہتے ہیں کہ اس حدیث کو حفص بن غیاث نے بھی ہشام سے روایت کیا ہے۔","f2":"مسلمانوں کو موقع بموقع آپس میں دعوتوں کا اہتمام کرتے رہنا چاہیے، اس سے آپس کے تعلقات مضبوط ہوتے اور محبتیں بڑھتی ہیں۔ روزے دار بھی دعوت میں شریک ہو اور ان کے لیے دعا کرے۔ اگر روزہ نفلی ہو تو توڑنا جائز ہے۔"}],[2461,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جب تم میں سے کسی کو کھانے کی دعوت دی جائے اور وہ روزے سے ہو تو اسے کہنا چاہیئے کہ میں روزے سے ہوں\"۔","صحیح",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ کا بیان ہے کہ رسول ا اللہ صلی اللہ علیہ وسلم نے فرمایا ” جب تم میں سے کسی کو کھانے میں بلایا جائے اور اس نے روزہ رکھا ہوا ہو تو کہہ دے کہ میں روزے سے ہوں۔ “","f2":"کھانے کی دعوت میں شریک ہونا افضل ہے۔ تاہم اگر عذر کرے اور بتا دے کہ میں روزے سے ہوں تو بھی جائز ہے۔ یا یہ مفہوم بھی ہے کہ اہل مجلس کو اپنے روزے کی خبر دے تو کوئی عیب کی بات نہیں۔"}],[2462,"ام المؤمنین عائشہ رضی اللہ عنہا سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم رمضان کے آخری عشرہ میں اعتکاف فرماتے تھے، اور آپ صلی اللہ علیہ وسلم کا یہ معمول وفات تک رہا، پھر آپ کے بعد آپ کی بیویوں نے اعتکاف کیا۔","صحیح",{"u2":"ام المؤمنین سیدہ عائشہ رضی اللہ عنہا ا بیان کرتی ہیں کہ نبی کریم صلی اللہ علیہ وسلم رمضان مبارک کے آخری دہے میں اعتکاف کیا کرتے ہیں ‘ آخر حیات تک آپ کا یہ معمول رہا ‘ آپ کے بعد پھر آپ کی ازواج مطہرات بھی اعتکاف بیٹھا کرتی تھیں۔","f2":"(1) اعتکاف کے لغوی معنی ہیں: کسی چیز کے ساتھ پابند ہو جانا یا کہیں بند رہنا۔ اور شرعی اصطلاح میں: رب ذوالجلال کی عبادت کے لیے انسان کا اپنے آپ کو کسی مسجد میں پابند کر لینا، اعتکاف کہلاتا ہے۔ رسول اللہ صلی اللہ علیہ وسلم کے عمل سے اس کا مشروع، مسنون اور مستحب ہونا ثابت ہے۔ قرآن مجید میں بھی اس کا ذکر آیا ہے: (وَعَهِدْنَآ إِلَىٰٓ إِبْرَ‌ٰ‌هِـۧمَ وَإِسْمَـٰعِيلَ أَن طَهِّرَ‌ا بَيْتِىَ لِلطَّآئِفِينَ وَٱلْعَـٰكِفِينَ وَٱلرُّ‌كَّعِ ٱلسُّجُودِ) (البقرة: 125) ہم نے ابراہیم اور اسماعیل علیھم السلام کو حکم دیا کہ میرے گھر کو طواف کرنے والوں، اعتکاف کرنے والوں اور رکوع و سجدہ کرنے والوں کے لیے پاک رکھو۔ دوسری آیت میں فرمایا: (وَلَا تُبَـٰشِرُ‌وهُنَّ وَأَنتُمْ عَـٰكِفُونَ فِى ٱلْمَسَـٰجِدِ) (البقرہ:187) اور جب تک تم مساجد میں اعتکاف کیے ہوئے ہو، عورتوں سے ملاپ نہ کرو۔ بعض لوگ سمجھتے ہیں کہ بستی والوں میں سے کوئی نہ کوئی ضرور اعتکاف بیٹھے، یہ محض وہم ہے۔ اس کی کوئی شرعی اصلیت نہیں ہے۔ جب تک کوئی اپنے اوپر لازم نہ کرلے، یہ واجب نہیں ہوتا۔ (2) خواتین بھی اعتکاف کر سکتی ہین بشرطیکہ شوہر اجازت دے۔ اور عورت کے لیے بھی اعتکاف کی جگہ مسجد ہی ہے، نہ کہ گھر۔ تاہم یہ ضروری ہے کہ عورتوں کے لیے مسجد میں پردے اور حفاظت کا خاطر خواہ انتطام ہو۔ جس مسجد میں ایسا انتظام نہ ہو، وہاں عورتوں کا اعتکاف بیٹھنا بھی صحیح نہیں ہے۔ اسی طرح گھروں میں اعتکاف بیٹھنا بھی غیر صحیح ہے۔"}],[2463,"ابی بن کعب رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم رمضان کے آخری عشرے میں اعتکاف کیا کرتے تھے، ایک سال (کسی وجہ سے) اعتکاف نہیں کر سکے تو اگلے سال آپ صلی اللہ علیہ وسلم نے بیس رات کا اعتکاف کیا۔","صحیح",{"u2":"سیدنا ابی بن کعب رضی اللہ عنہ سے مروی ہے کہ نبی کریم صلی اللہ علیہ وسلم رمضان کا آخری عشرہ اعتکاف فرمایا کرتے تھے۔ ایک سال آپ صلی اللہ علیہ وسلم اعتکاف نہ بیٹھ سکے تو اگلے سال آپ صلی اللہ علیہ وسلم نے بیس رات تک اعتکاف فرمایا۔","f2":"نفل اعمال کی قضا واجب تو نہیں ہے مگر ادا کرنے میں بہت اجرو فضیلت ہے۔ بالخصوص نبی صلی اللہ علیہ وسلم اس کا اہتمام فرمایا کرتے تھے۔"}],[2464,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم جب اعتکاف کرنے کا ارادہ کرتے تو فجر پڑھ کر اعتکاف کی جگہ جاتے، ایک مرتبہ آپ صلی اللہ علیہ وسلم نے رمضان کے آخری عشرہ میں اعتکاف کرنے کا ارادہ فرمایا، تو خیمہ لگانے کا حکم دیا، خیمہ لگا دیا گیا، جب میں نے اسے دیکھا تو اپنے لیے بھی خیمہ لگانے کا حکم دیا، اسے بھی لگایا گیا، نیز میرے علاوہ دیگر ازواج مطہرات نے بھی خیمہ لگانے کا حکم دیا تو لگایا گیا، جب آپ صلی اللہ علیہ وسلم نے فجر پڑھی تو ان خیموں پر آپ کی نگاہ پڑی آپ نے پوچھا: یہ کیا ہیں؟ کیا تمہارا مقصد اس سے نیکی کا ہے؟ ۱؎، پھر آپ صلی اللہ علیہ وسلم نے اپنے نیز اپنی ازواج کے خیموں کے توڑ دینے کا حکم فرمایا، اور اعتکاف شوال کے پہلے عشرہ تک کے لیے مؤخر کر دیا۔ ابوداؤد کہتے ہیں: اسے ابن اسحاق اور اوزاعی نے یحیی بن سعید سے اسی طرح روایت کیا ہے اور اسے مالک نے بھی یحیی بن سعید سے روایت کیا ہے اس میں ہے آپ نے شوال کی بیس تاریخ کو اعتکاف کیا۔\n§وضاحت\n۱؎ : استفہام انکاری ہے یعنی اس کام سے تم سب کے پیش نظر نیکی نہیں ہے، غیرت کی وجہ سے یہ کام کر رہی ہو۔","صحیح",{"u2":"ام المؤمنین سیدہ عائشہ رضی اللہ عنہا ا سے منقول ہے کہ رسول ا اللہ صلی اللہ علیہ وسلم جب اعتکاف کا ارادہ فرماتے تو فجر کی نماز پڑھ کر اپنے حجرہ اعتکاف میں داخل ہو جاتے۔ ایک بار آپ صلی اللہ علیہ وسلم نے رمضان کے آخری دہے میں اعتکاف کا ارادہ فرمایا اور حجرہ بنانے کا حکم دیا تو وہ بنا دیا گیا جب میں نے یہ دیکھا تو میں نے کہہ دیا کہ میرا خیمہ بھی لگا دیا جائے۔ چنانچہ وہ لگا دیا گیا اور پھر دیگر ازواج نبی کریم صلی اللہ علیہ وسلم نے بھی (دیکھا دیکھی) خیمے لگانے کو کہا۔ چنانچہ وہ لگا دیے گئے۔ آپ صلی اللہ علیہ وسلم نے نماز فجر کے بعد خیموں کو دیکھا تو فرمایا ” یہ کیا ہے ‘ بھلا یہ نیکی کا قصد کر رہی ہیں؟ “ چنانچہ آپ صلی اللہ علیہ وسلم نے اپنے حجرے کے متعلق فرمایا اور اس کھول دیا گیا ‘ اس پر ازواج محترمات نے بھی اپنے اپنے خیمے کھلوا لیے۔ پھر آپ صلی اللہ علیہ وسلم نے اپنا یہ اعتکاف شوال کے پہلے عشرہ تک مؤخر فر دیا۔ امام ابوداؤد رضی اللہ عنہ نے کہا: اس حدیث کو ابن اسحاق اور اوزاعی نے یحییٰ بن سعید سے اسی طرح روایت کیا ہے جب کہ امام مالک رضی اللہ عنہ نے یحییٰ بن سعید سے روایت کیا تو کہا: آپ صلی اللہ علیہ وسلم نے شوال کے بیس دن اعتکاف کیا۔","f2":"(1) اعتکاف کے لیے حجرہ بنانا اس لیے مستحب ہے کہ معتکف اس جگہ میں دیگر لوگوں سے علیحدہ ہو کر نوافل، تلاوت قرآن کریم اور اذکار وغیرہ میں مشغول رہے۔ یہ لوگوں کے ساتھ بلا ضرورت اختلاط کرے، نہ دوسرے ہی اس کو مشغول کریں۔ (2) خواتین کو بھی مساجد میں اعتکاف کرنا چاہیے۔ گھروں میں اعتکاف کرنا خیرالقرون سے ثابت نہیں۔گھر میں مقام عبادت کو اصطلاحا مسجد نہیں کہا جا سکتا اور نہ اس پر معروف مسجد والے احکام ہی منطبق ہوتے ہیں۔ (3) اعمال میں خیر میں بنیادی طور پر اخلاص اور اللہ تعالیٰ ہی کی رضا مقصود ہونی چاہیے۔ ازواج مطہرات کے مذکورہ بالا عمل میں رشک کا پہلو غالب تھا جو اگرچہ عام افراد امت کے لیے تو محمود ہے مگر ازواج نبی صلی اللہ علیہ وسلم کا مقام ان سے بالا تر ہے۔اس لیے نبی صلی اللہ علیہ وسلم نے پسند نہیں فرمایا اور یہی معنی ہین اس معروف قول کے کہ (حسنات الابرار سيئات المقربين) یعنی عام صالحین کے عام صالح اعمال بعض اوقات مقرب لوگوں کے حق میں ریب اور تقصیر شمار کیے جاتے ہیں۔ (4) شوہر اگر راضی نہ ہو تو عورت کو اپنا اعتکاف ختم کر دینا چاہیے۔ (5) فوت شدہ یا توڑے گئے اعتکاف کی قضا دینا مستحب ہے، واجب نہیں۔ جیسے کہ ازواج مطہرات کے متعلق اس قسم کا کوئی بیان نہیں ہے کہ ان سے اس اعتکاف کی قضا کروائی گئی۔ (6) غیر رمضان میں اعتکاف کے دوران میں روزہ شرط نہیں ہے۔ (7) اعتکاف کا آغاز کب سے کرنا ہے؟ احادیث میں اس کی صراحت نہیں ہے۔ اس حدیث میں صرف یہ ہے کہ نبی صلی اللہ علیہ وسلم فجر کی نماز پڑھ کر حجرہ اعتکاف میں داخل ہوتے۔ دوسری روایات میں ہے کہ آپ رمضان کا آخری عشرہ اعتکاف فرماتے تھے۔ اس اعتبار سے اکثر علماء یہ کہتے ہین کہ معتکف 20 رمضان کو مغرب سے پہلے پہلے مسجد میں آ جائے، رات مسجد میں گزارے اور فجر کی نماز پڑھ کر حجرہ اعتکاف میں داخل ہو جائے۔ اس طرح کرنے سے اس کا رمضان کا آخری عشرہ اعتکاف کے ساتھ گزرے گا اور مذکورہ دونوں رواتیوں پر عمل ہو جائے گا۔ اس کے برعکس بعض لوگ کہتے ہیں کہ بیسیوں رمضان کو فجر کی نماز کے بعد اعتکاف کا آغاذ کیا جائے، کیونکہ حدیث میں آپ کے نمازِ فجر کے بعد حجرہ اعتکاف میں داخل ہونے کی صراحت ہے۔ لیکن اس طرح 30 رمضان ہونے کی صورت میں اعتکاف کے 11 دن بن جاتے ہیں جسے عشرہ قرار نہیں دیا جا سکتا، جب کہ نبی صلی اللہ علیہ وسلم کا عمل عشرہ اخیر کا اعتکاف کا منقول ہے اس لیے پہلے رائے ہی راجح اور صحیح ہے۔ واللہ اعلم."}],[2465,"عبداللہ بن عمر رضی اللہ عنہما سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم رمضان کے آخری عشرہ میں اعتکاف کرتے تھے۔ نافع کا بیان ہے کہ عبداللہ بن عمر نے مجھے مسجد کے اندر وہ جگہ دکھائی جس میں رسول اللہ صلی اللہ علیہ وسلم اعتکاف کیا کرتے تھے۔","صحیح",{"u2":"سیدنا عبداللہ بن عمر رضی اللہ عنہ سے مروی ہے کہ نبی کریم صلی اللہ علیہ وسلم رمضان کا آخری عشرہ اعتکاف فرمایا کرتے تھے۔ نافع کہتے ہیں کہ سیدنا عبداللہ رضی اللہ عنہ نے مجھے مسجد نبوی میں وہ جگہ دکھائی جہاں رسول ا اللہ صلی اللہ علیہ وسلم اعتکاف فرمایا کرتے تھے۔","f2":"اعتکاف کے لیے مسجد ہی مشروع و مسنون مقام ہے جیسے کہ قرآن مجید نے ذکر کیا ہے: (وَلَا تُبَـٰشِرُ‌وهُنَّ وَأَنتُمْ عَـٰكِفُونَ فِى ٱلْمَسَـٰجِدِ) (البقرة:187) اور جب تک تم مساجد میں اعتکاف کیے ہوئے ہو تو عورتوں سے ملاپ نہ کرو۔"}],[2466,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم ہر رمضان میں دس دن اعتکاف کرتے تھے، لیکن جس سال آپ کا انتقال ہوا اس سال آپ صلی اللہ علیہ وسلم نے بیس دن کا اعتکاف کیا۔","حسن صحیح",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم ہر رمضان کے آخری دس دن اعتکاف فرمایا کرتے تھے۔ چنانچہ جس سال آپ صلی اللہ علیہ وسلم کا وصال ہوا آپ نے بیس دن اعتکاف فرمایا۔","f2":"معلوم ہوا کہ وسط رمضان میں بھی اعتکاف ہو سکتا ہے۔ شاید نبی صلی اللہ علیہ وسلم کو قربِ اجل کا علم ہو گیا تھا اس لیے آپ عبادت میں بہت حریص ہو گئے تھے۔ اس رمضان میں جبرئیل امین علیہ السلام نے بھی آپ کے ساتھ قرآن مجید کا دو بار دَور کیا تھا۔"}],[2467,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم جب اعتکاف میں ہوتے تو (مسجد ہی سے) اپنا سر میرے قریب کر دیتے اور میں اس میں کنگھی کر دیتی اور آپ صلی اللہ علیہ وسلم گھر میں کسی انسانی ضرورت ہی کے پیش نظر داخل ہوتے تھے۔","صحیح",{"u2":"ام المؤمنین سیدہ عائشہ رضی اللہ عنہا ا بیان کرتی ہیں کہ رسول ا اللہ صلی اللہ علیہ وسلم اعتکاف کے دوران میں اپنا سر مبارک میری طرف جھکا دیتے اور میں اس میں کنگھی کر دیتی اور آپ صلی اللہ علیہ وسلم قضائے حاجت کے لیے ہی گھر میں تشریف لایا کرتے تھے۔","f2":"(1) اثنائے اعتکاف میں بیوی اپنے شوہر کی خڈمت کر سکتی ہے خواہ حائضہ بھی ہو۔ (صحيح البخاري‘ الاعتكاف‘ حديث:2031) مگر عمر کے لحاظ سے احتیاط لازم ہے۔ (2) روزے اور اعتکاف میں جسم و لباس کی نظافت کا اہتمام رکھنا چاہیے۔ (3) قضائے حاجت کے لیے انسان اپنے معتکف اور مسجد سے باہر یا اپنے گھر بھی جا سکتا ہے۔ ایسے ہی اگر کوئی خادم میسر نہ ہو تو کھانا کھانے کے لیے جانا بھی مباح ہو گا۔ (4) اس حدیث کی سند میں عن عروہ کے بعد عن عمرة بنت عبدالرحمن المزيد في متصل الاسانيد کی قسم سے ہے۔(بذل المجهود)"}],[2468,"اس سند سے بھی ام المؤمنین عائشہ رضی اللہ عنہا سے اسی طرح مرفوعاً مروی ہے۔","صحیح",{"u2":"ابن شہاب زہری بواسطہ عروہ اور عمرہ، سیدہ عائشہ رضی اللہ عنہا ا سے اور وہ نبی کریم صلی اللہ علیہ وسلم سے مذکورہ بالا حدیث کی مانند روایت کرتی ہیں۔ امام ابوداؤد رضی اللہ عنہ فرماتے ہیں اور ایسے ہی یونس نے بھی زہری سے روایت کیا ہے۔ اور کسی نے بھی «عروة، عن عمرة» کی سند میں مالک کی متابعت نہیں کی ہے۔ معمر اور زیاد بن سعد وغیرہ «الزهري، عن عروة، عن عائشة» کی سند سے روایت کرتے ہیں۔"}],[2469,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم مسجد کے اندر اعتکاف کی حالت میں ہوتے تو حجرے کے کسی جھروکے سے اپنا سر میری طرف کر دیتے میں آپ صلی اللہ علیہ وسلم کا سر دھو دیتی، کنگھی کر دیتی، اور میں حیض سے ہوتی تھی۔","صحیح",{"u2":"ام المؤمنین سیدہ عائشہ رضی اللہ عنہا ا سے روایت ہے کہ رسول ا اللہ صلی اللہ علیہ وسلم مسجد میں اعتکاف میں ہوتے ‘ آپ صلی اللہ علیہ وسلم حجرے میں سے اپنا سر میری طرف کر دیتے اور میں آپ صلی اللہ علیہ وسلم کا سر دھو دیتی۔ مسدد کے الفاظ ہیں: میں آپ کی کنگھی کر دیتی جبکہ میں حائضہ ہوتی۔"}],[2470,"ام المؤمنین صفیہ رضی اللہ عنہا کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم معتکف تھے تو میں رات میں ملاقات کی غرض سے آپ کی خدمت میں حاضر ہوئی، آپ صلی اللہ علیہ وسلم سے میں نے بات چیت کی، پھر میں کھڑی ہو کر چلنے لگی تو آپ صلی اللہ علیہ وسلم بھی مجھے واپس کرنے کے لیے کھڑے ہو گئے، (اس وقت ان کی رہائش اسامہ بن زید رضی اللہ عنہما کے مکان میں تھی) اتنے میں دو انصاری وہاں سے گزرے، وہ آپ کو دیکھ کر تیزی سے نکلنے لگے، نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"ٹھہرو، یہ صفیہ بنت حیی (میری بیوی)ہے (ایسا نہ ہو کہ تمہیں کوئی غلط فہمی ہو جائے)\"، وہ بولے: سبحان اللہ! اللہ کے رسول! (آپ کے متعلق ایسی بدگمانی ہو ہی نہیں سکتی)آپ صلی اللہ علیہ وسلم نے فرمایا: \"شیطان انسان کی رگوں میں خون کی طرح دوڑتا ہے، مجھے اندیشہ ہوا کہ کہیں وہ تمہارے دل میں کچھ(یا کہا: کوئی شر) نہ ڈال دے\"۔","صحیح",{"u2":"ام المؤمنین سیدہ صفیہ رضی اللہ عنہا ا کا بیان ہے کہ رسول اللہ صلی اللہ علیہ وسلم اعتکاف میں تھے اور میں رات کے وقت آپ صلی اللہ علیہ وسلم کی زیارت کے لیے حاضر ہوئی۔ میں آپ صلی اللہ علیہ وسلم سے باتیں کرتی رہی ‘ پھر میں واپس آنے کے لیے اٹھی تو آپ صلی اللہ علیہ وسلم بھی مجھے واپس چھوڑنے کے لیے کھڑے ہو گئے جبکہ میری رہائش سیدنا اسامہ بن زید رضی اللہ عنہ کے احاطے میں تھی۔ تو (ہمارے پاس سے) دو انصاری گزرے ‘ جب انہوں نے نبی کریم صلی اللہ علیہ وسلم کو دیکھا تو جلدی جلدی چلنے لگے ‘ نبی کریم صلی اللہ علیہ وسلم نے انہیں فرمایا ” رک جاؤ! یہ میرے ساتھ (میری اہلیہ) صفیہ بنت حیی ہے “ ان دونوں نے کہا: سبحان اللہ ‘ اے اللہ کے رسول! (آپ کو کسی قسم کی وضاحت کرنے کی ضرورت ہی نہیں) آپ نے فرمایا ” بلاشبہ شیطان انسان کے جسم میں ایسے چلتا ہے جیسے خون ‘ مجھے اندیشہ ہوا کہ کہیں وہ تمہارے دلوں میں کچھ ڈال نہ دے۔ “ یا فرمایا ” برائی نہ ڈال دے۔ “"}],[2471,"زہری سے اس سند سے بھی یہ حدیث مروی ہے جس میں ام المؤمنین صفیہ رضی اللہ عنہا کا بیان ہے کہ جب آپ صلی اللہ علیہ وسلم مسجد کے اس دروازے پر پہنچے جو ام المؤمنین ام سلمہ رضی اللہ عنہا کے دروازے کے پاس ہے تو ان کے قریب سے دو شخص گزرے، اور پھر اسی مفہوم کی حدیث بیان کی۔","صحیح",{"u2":"شعیب ‘ زہری سے ان کی سند سے یہ روایت بیان کرتے ہیں کہ (سیدہ صفیہ رضی اللہ عنہا ا بیان کرتی ہیں کہ) جب آپ مسجد کے دروازے کے قریب پہنچے جو کہ سیدہ ام سلمہ رضی اللہ عنہا ا کے گھر کے دروازے کے پاس تھا تو آپ کے پاس سے دو آدمی گزرے۔ اور مذکورہ بالا (حدیث) کے ہم معنٰی بیان کیا۔","f2":"(1) بیوی اور دیگر تعلق داروں کو معتکف ست ملاقات کرنے میں کوئی حرج نہیں۔ اور ظاہر ہے کہ یہ ملاقاتیں ایک حد تک ہونی چاہئیں اور اس اثنا میں ضروری گفتگو بھی ہو سکتی ہے۔ (2) حضرت صفیہ رضی اللہ عنہا کی نبی صلی اللہ علیہ وسلم سے حالت اعتکاف میں ملاقات کا یہ واقعہ صحیح بخاری (حدیث:2035) میں بھی ہے۔ اس میں صراحت ہے کہ حضرت صفیہ (زوجہ مطہرہ) کا گھر مسجد کے دروازے سے متصل ہی تھا، اس لیے رخصت کے وقت نبی صلی اللہ علیہ وسلم مسجد کے دروازے تک ان کے ساتھ معتکف سے باہر آئے۔ بنا بریں اس واقعے سے یہ استدلال کرنا صحیح نہیں ہے کہ معتکف بیوی کو گھر تک چھوڑنے کے لیے مسجد سے باہر جا سکتا ہے۔ ہاں حوائج ضروریہ کا انتظام مسجد کے اندر نہ ہو تو بات اور ہے۔ ان کے لیے باہر جانا مجبوری کے تحت جائز ہو گا۔ (3) انسان کو بالعموم اور حساس مناصب پر فائز شخصیات کے لیے بالخصوص ضروری ہے کہ اپنے آپ کو ہر طرح کے شبہات سے پاک رکھیں۔ اور کسی متوقع شبہ کا قبل از وقوع ازالہ کر دینا زیادہ بہتر ہوتا ہے۔"}],[2472,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ نبی اکرم صلی اللہ علیہ وسلم حالت اعتکاف میں مریض کے پاس سے عیادت کرتے ہوئے گزر جاتے جس طرح کے ہوتے اور ٹھہرتے نہیں بغیر ٹھہرتے اس کا حال پوچھتے۔","ضعیف",{"u2":"ام المؤمنین سیدہ عائشہ رضی اللہ عنہا ا سے مروی ہے کہ نبی کریم صلی اللہ علیہ وسلم ایام اعتکاف میں مریض کے پاس سے گزرتے اور اپنی راہ چلتے جاتے اور اس کا حال احوال پوچھتے مگر اس غرض سے اس کی طرف مڑتے نہ تھے۔ اور ابن عیسٰی نے کہا کہ عائشہ رضی اللہ عنہا ا نے کہا: نبی کریم صلی اللہ علیہ وسلم اعتکاف کی حالت میں مریض کی عیادت کر لیتے تھے۔"}],[2473,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ سنت یہ ہے کہ اعتکاف کرنے والا کسی مریض کی عیادت نہ کرے، نہ جنازے میں شریک ہو، نہ عورت کو چھوئے، اور نہ ہی اس سے مباشرت کرے، اور نہ کسی ضرورت سے نکلے سوائے ایسی ضرورت کے جس کے بغیر کوئی چارہ نہ ہو، اور بغیر روزے کے اعتکاف نہیں، اور جامع مسجد کے سوا کہیں اور اعتکاف نہیں۔ ابوداؤد کہتے ہیں: عبدالرحمٰن کے علاوہ دوسروں کی روایت میں «قالت السنة» کا لفظ نہیں ہے۔ ابوداؤد کہتے ہیں: انہوں نے اسے ام المؤمنین عائشہ رضی اللہ عنہا کا قول قرار دیا ہے۔","حسن صحیح",{"u2":"ام المؤمنین سیدہ عائشہ رضی اللہ عنہا ا نے فرمایا کہ معتکف کے لیے سنت یہ ہے کہ مریض کی عیادت کو نہ جائے ‘ جنازے میں شریک نہ ہو ‘ عورت سے مس نہ کرے اور نہ اس سے مباشرت (صحبت) کرے اور کسی انتہائی ضروری کام کے بغیر مسجد سے نہ نکلے۔ اور روزے کے بغیر اعتکاف نہیں اور مسجد جامع کے علاوہ کہیں اعتکاف نہیں۔ امام ابوداؤد رضی اللہ عنہ کہتے ہیں کہ عبدالرحمٰن بن اسحاق کے علاوہ کسی نے «السنة» کے لفظ نہیں کہے۔ اور انہوں نے اسے سیدہ عائشہ رضی اللہ عنہا ا کا قول قرار دیا ہے۔","f2":"اس باب کی مذکورہ دونوں روایات ضعیف ہیں۔ اس لیے اس میں بیان کردہ وہی باتیں صحیح ہیں جو دیگر صحیح روایات سے ثابت ہیں اور دیگر باتیں غیر صحیح ہیں۔"}],[2474,"عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ عمر رضی اللہ عنہ نے زمانہ جاہلیت میں اپنے اوپر کعبہ کے پاس ایک دن اور ایک رات کے اعتکاف کی نذر مانی تھی تو انہوں نے نبی اکرم صلی اللہ علیہ وسلم سے دریافت کیا تو آپ نے فرمایا: \"اعتکاف کرو اور روزہ رکھو\"۔","صحیح",{"u2":"سیدنا ابن عمر رضی اللہ عنہ روایت کرتے ہیں کہ سیدنا عمر رضی اللہ عنہ نے ایام جاہلیت میں یہ نذر مانی تھی کہ کعبہ میں ایک رات یا دن کا اعتکاف کروں گا۔ پس انہوں نے اس کے متعلق نبی کریم صلی اللہ علیہ وسلم سے دریافت کیا تو آپ صلی اللہ علیہ وسلم نے فرمایا ” اعتکاف کرو اور روزہ (بھی) رکھو۔ “","f2":"اس روایت میں دن کا ذکر اور روزہ بھی رکھو کا بیان صحیح نہیں ہے۔ کیونکہ یہ روایت صحیح بخاری میں ہے، اس میں دن کا اور روزہ رکھنے کے حکم کا ذکر نہیں ہے۔ (صحيح البخاري‘ الاعتكاف‘ حديث: 2033) بہرحال نیکی کے کام کی نذر خواہ جاہلیت کے دور میں مانی گئی ہو، پوری کرنی چاہیے۔"}],[2475,"اس سند سے بھی عبداللہ بن بدیل سے اسی طرح مروی ہے، اس میں ہے اسی دوران کہ وہ (عمر رضی اللہ عنہ) حالت اعتکاف میں تھے لوگوں نے \"الله أكبر\" کہا، تو پوچھا: عبداللہ! یہ کیا ہے؟ انہوں نے کہا کہ قبیلہ ہوازن والوں کے قیدیوں کو رسول اللہ صلی اللہ علیہ وسلم نے آزاد کر دیا ہے، کہا: یہ لونڈی بھی (تو انہیں میں سے ہے) ۱؎ چنانچہ انہوں نے اسے بھی ان کے ساتھ آزاد کر دیا۔\n§وضاحت\n۱؎ : مطلب یہ ہے کہ عمر رضی اللہ عنہ سے جب یہ سنا کہ رسول اللہ صلی اللہ علیہ وسلم نے ہوازن کے قیدیوں کو آزاد کر دیا ہے تو اپنے بیٹے عبداللہ رضی اللہ عنہ سے کہا کہ یہ لونڈی جو میرے پاس ہے وہ بھی تو انہیں قیدیوں میں سے ہے پھر تم اسے کیسے روکے ہوئے ہو۔","صحیح",{"u2":"عبداللہ بن بدیل نے (یہی روایت) اپنی سند سے اسی کی مانند روایت کی اس میں اضافہ ہے کہ سیدنا عمر رضی اللہ عنہ اعتکاف میں تھے کہ لوگوں کے یکایک تکبیر بلند کی۔ انہوں نے پوچھا: اے عبداللہ (ابن عمر)! یہ کہا ہے؟ انہوں نے بتایا کہ ہوازن کے قیدیوں کو رسول ا اللہ صلی اللہ علیہ وسلم نے آزاد کر دیا ہے۔ انہوں نے کہا: تو اس لونڈی کو بھی (جو سیدنا عمر رضی اللہ عنہ کے پاس تھی) ان کے ساتھ چھوڑ دو۔","f2":"اثنائے اعتکاف میں صدقہ و خیرات اور اس طرح کا مالی تصرف باعث اجر ہے۔"}],[2476,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ نبی اکرم صلی اللہ علیہ وسلم کے ساتھ آپ کی بیویوں میں سے کسی نے اعتکاف کیا وہ (خون میں) پیلا پن اور سرخی دیکھتیں (یعنی انہیں استحاضہ کا خون جاری رہتا) تو بسا اوقات ہم ان کے نیچے (خون کے لیے) بڑا برتن رکھ دیتے اور وہ حالت نماز میں ہوتیں۔","صحیح",{"u2":"ام المؤمنین سیدہ عائشہ رضی اللہ عنہا ا بیان کرتی ہیں کہ نبی کریم صلی اللہ علیہ وسلم کی ازواج سے ایک نے آپ صلی اللہ علیہ وسلم کے ساتھ اعتکاف کیا۔ اسے زردی مائل یا سرخ سا خون آتا تھا۔ (استحاضہ کی وجہ سے) تو ہم کبھی اس کے نیچے لگن بھی رکھ دیا کرتے تھے اور وہ نماز پڑھا کرتی تھیں۔","f2":"(1) استحاضہ کے ایام حکما پاکیزگی کے دن ہوتے ہیں اور ان میں نماز، روزہ اور اعتکاف وغیرہ سب امور صحیح ہیں مگر لازمی ہے کہ مسجد کو آلودہ ہونے سے بچایا جائے۔ (2) اس پر قیاس کرتے ہوئے دائم الحدث (جس کا وضو برقرار نہ رہتا ہو) کا بھی یہی حکم ہو گا۔ یعنی حدث کی حالت میں اس کے لیے نماز پڑھنا جائز ہو گا، اور وہ شخص بھی اسی حکم میں ہو گا جس کے زخم سے خون رس رہا ہو۔"}],[2477,"ابوسعید خدری رضی اللہ عنہ کہتے ہیں کہ ایک اعرابی (دیہاتی) نے نبی اکرم صلی اللہ علیہ وسلم سے ہجرت کے بارے میں پوچھا، آپ صلی اللہ علیہ وسلم نے فرمایا: \"تمہارے اوپر افسوس ہے! ۱؎ ہجرت کا معاملہ سخت ہے، کیا تمہارے پاس اونٹ ہیں؟\" اس نے کہا: ہاں ہیں، آپ صلی اللہ علیہ وسلم نے فرمایا: \"کیا تم ان کی زکاۃ دیتے ہو؟\" اس نے کہا: ہاں (دیتے ہیں)، آپ صلی اللہ علیہ وسلم نے فرمایا: \"پھر سمندروں کے اس پار رہ کر عمل کرو، اللہ تمہارے عمل سے کچھ بھی کم نہیں کرے گا ۲؎\"۔\n§وضاحت\n۱؎ : حدیث میں «ویحک ( تمہارے اوپر افسوس ہے!) کا لفظ کلمہ ترحم و توجع ہے اور اس شخص کے لئے استعمال کیا جاتا ہے جو کسی ایسی تباہی میں پھنس گیا ہو جس کا وہ مستحق نہ ہو۔ ۲؎ : مفہوم یہ ہے کہ تمہاری جیسی نیت ہے اس کے مطابق تمہیں ہجرت کا ثواب ملے گا تم خواہ کہیں بھی رہو، اس حدیث سے یہ بھی معلوم ہوا کہ ہجرت ان لوگوں پر واجب ہے جو اس کی طاقت رکھتے ہوں۔","صحیح",{"u2":"سیدنا ابو سعید خدری رضی اللہ عنہ سے روایت ہے کہایک دیہاتی نے نبی کریم صلی اللہ علیہ وسلم سے ہجرت کے متعلق دریافت کیا۔ (مدینہ منورہ میں سکونت کے لیے بیعت کرنی چاہی) آپ صلی اللہ علیہ وسلم نے فرمایا ” تم پر افسوس! ہجرت کا معاملہ انتہائی سخت ہے، کیا تمہارے پاس اونٹ ہیں؟ “ اس نے کہا: ہاں۔ آپ صلی اللہ علیہ وسلم نے پوچھا ” ان کی زکوٰۃ دیتے ہو؟ “ اس نے کہا: ہاں۔ آپ صلی اللہ علیہ وسلم نے فرمایا ” ان بستیوں کے پار عمل کیے جاؤ، اللہ تعالیٰ تمہارے عمل میں کوئی کمی نہیں کرے گا۔ “","f2":"1۔(ھجرۃ) لغت میں چھوڑدینے کو کہتے ہیں۔اوراصطلاحا یہ ہے کہ انسان اپنےدین اور ایمان کی حفاظت کی غرض سے دارلکفر۔دارلفساد۔اوردارالمعاصی۔کوچھوڑ کردارالسلام اور دارالصلاح کی سکونت اختیار کرلے۔اور ہجرت کی جان یہ ہے کہ انسان اللہ عزوجل کے منع کردہ امور سے باز رہے۔جیسا کہ حدیث میں اس کی صراحت ہے۔(صحیح البخاری۔الایمان حدیث 10)2۔ہجرت کے تقاضے انتہائی شدید ہیں۔یہ کوئی آسان عمل نہیں ہے۔3۔(البحار) کا لفظ عربی زبان میں بستیوں اور شہروں پر بھی بولاجاتا ہے۔4۔اعمال کی بنیاد ایمان اور اخلاص پرہے۔"}],[2478,"شریح کہتے ہیں کہ میں نے ام المؤمنین عائشہ رضی اللہ عنہا سے صحراء و بیابان (میں زندگی گزارنے) کے بارے میں پوچھا تو انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم ان ٹیلوں پر جایا کرتے تھے، آپ نے ایک بار صحراء میں جانے کا ارادہ کیا تو میرے پاس صدقہ کے اونٹوں میں سے ایک اونٹ بھیجا جس پر سواری نہیں ہوئی تھی، اور مجھ سے فرمایا: \"عائشہ! اس کے ساتھ نرمی کرنا کیونکہ جس چیز میں بھی نرمی ہوتی ہے وہ اسے عمدہ اور خوبصورت بنا دیتی ہے، اور جس چیز سے بھی نرمی چھین لی جائے تو وہ اسے عیب دار کر دیتی ہے\"۔","صحیح",{"u2":"مقدام بن شریح اپنے والد سے روایت کرتے ہیں کہ میں نے سیدہ عائشہ رضی اللہ عنہا ا سے پوچھا کہ بستی اور دیہات میں سکونت اختیار کرنا کیسا ہے؟ تو انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم (کبھی کبھار) ان ٹیلوں اور میدانوں کی طرف چلے جایا کرتے تھے۔ آپ صلی اللہ علیہ وسلم نے ایک بار باہر جانے کا ارادہ فرمایا اور میری طرف صدقہ کے اونٹوں میں سے ایک جوان اونٹنی بھیجی (کہ سواری کے دوران میں اس پر کچھ سختی کرنی پڑی) تو آپ صلی اللہ علیہ وسلم نے فرمایا ” عائشہ! نرم خوئی سے کام لو، نرمی جس چیز میں بھی آ جائے وہ مزین ہو جاتی ہے اور جس سے نکال لی جائے، وہ عیب دار ہو جاتی ہے۔“","f2":"1۔اس روایت کا پہلا حصہ (ھذہ التلاع)صحیح ثابت نہیں۔(علامہ البانی)تاہم تدبر فی الانفس کی نیت سے آدمی کس وقت عزلت وتنہائی اختیار کرلے تو مفید ہے۔جس کی صورت اعتکاف ہے۔نہ کہ صوفیاء کی سیاحت۔2۔جب حیوانات سے نرم خوئی ممدوح اور مطلوب ہے۔تو انسانوں سے یہ معاملہ اور بھی زیادہ باعث اجر وثواب ہے۔"}],[2479,"معاویہ رضی اللہ عنہ کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا: \"ہجرت ختم نہیں ہو گی یہاں تک کہ توبہ کا سلسلہ ختم ہو جائے، اور توبہ ختم نہیں ہو گی یہاں تک کہ سورج پچھم سے نکل آئے ۱؎\"۔\n§وضاحت\n۱؎ : اس لئے اگر ممکن ہو تو دارلکفر سے دارالاسلام کی طرف، اور دارالمعاصی سے دارالصلاح کی طرف ہجرت ہمیشہ بہتر ہے، ورنہ فی زمانہ کوئی بھی ملک دوسرے ملک کے شہری کو اپنے یہاں منتقل ہونے کی اجازت نہیں دیتا۔","صحیح",{"u2":"سیدنا معاویہ رضی اللہ عنہ سے مروی ہے، وہ کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو سنا، آپ صلی اللہ علیہ وسلم فرماتے تھے ” ہجرت ختم نہیں ہو سکتی، حتیٰ کہ توبہ منقطع ہو جائے، اور توبہ اس وقت تک منقطع نہیں ہو گی، حتیٰ کہ سورج مغرب سے طلوع ہو۔ “","f2":"سورج کا مٖغرب سے طلوع ہونا آثار قیامت کی بہت بڑی نشانی ہے۔اور اس وقت تک توبہ کرنے کا کھلا موقع ہے۔ اس طرح دین وایمان کی حفاظت کے لئے اگر انسان دارلکفر کوچھوڑے اور دارلسلام میں سکونت اختیار کرے تو اس کے مہاجر ہونے میں کوئی مانع نہیں ہے۔"}],[2480,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فتح (مکہ) کے دن فرمایا: \"اب (مکہ فتح ہو جانے کے بعد مکہ سے) ہجرت نہیں (کیونکہ مکہ خود دارالاسلام ہو گیا) لیکن جہاد اور (ہجرت کی) نیت باقی ہے، جب تمہیں جہاد کے لیے نکلنے کو کہا جائے تو نکل پڑو\"۔","صحیح",{"u2":"سیدنا ابن عباس رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فتح مکہ کے روز فرمایا ” (اب) ہجرت نہیں ہے، لیکن جہاد اور نیت باقی ہے، جب تمہیں جہاد کے لیے دعوت دی جائے تو نکل کھڑے ہو۔ “","f2":"چونکہ فتح مکہ سے پہلے جہاں آدمی رہ رہا تھا۔اسلام لانے کے بعد اسے وہاں سے مدینہ کو ہجرت کرنا واجب تھا۔اور مکہ ان تمام جگہوں کا مرکز تھا۔ فتح مکہ کے بعد وہ دارلاسلام بن گیا۔تو اس سے ہجرت کا کوئی معنی باقی نہ رہا۔مگر باقی دنیا میں جہاں کہیں احوال دگرگوں ہو ں تو اپنے اسلام اور ایمان کی حفاظت کےلئے نقل مکانی مطلوب وماجور ہے۔اور ایسے ہی جہاد بھی قیامت تک جاری ہے۔"}],[2481,"عامر شعبی کہتے ہیں کہ ایک آدمی عبداللہ بن عمرو رضی اللہ عنہما کے پاس آیا، ان کے پاس کچھ لوگ بیٹھے تھے یہاں تک کہ وہ بھی آ کر آپ کے پاس بیٹھ گیا اور کہنے لگا: مجھے کوئی ایسی بات بتائیے جو آپ نے رسول اللہ صلی اللہ علیہ وسلم سے سنی ہو، انہوں نے کہا: میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا: \"مسلمان وہ ہے جس کے ہاتھ اور زبان سے مسلمان محفوظ رہیں، اور مہاجر وہ ہے جو اللہ کی منع کردہ چیزوں کو چھوڑ دے\"۔","صحیح",{"u2":"عامر (شعبی) نے کہا: ایک شخص سیدنا عبداللہ بن عمرو رضی اللہ عنہ کے پاس آیا جب کہ ان کے پاس اور کچھ لوگ بھی موجود تھے، وہ بھی ان کے پاس بیٹھ گیا اور کہا: مجھے کوئی ایسی بات بتائیں جو آپ نے رسول اللہ صلی اللہ علیہ وسلم سے سنی ہو تو سیدنا عبداللہ بن عمرو رضی اللہ عنہ نے کہا: میں نے رسول اللہ صلی اللہ علیہ وسلم کو سنا، آپ صلی اللہ علیہ وسلم فرماتے تھے ” مسلمان وہ ہے جس کی زبان اور ہاتھ سے دوسرے مسلمان محفوظ ہوں اور مہاجر وہ ہے جو اللہ کے منع کیے ہوئے کاموں سے باز رہے۔ “","f2":"ایک باکردار مسلمان کے اوصاف کو اس حدیث میں جس مختصر اور جامع اندا ز میں پیش کیاگیا ہے۔وہ یقینا ً الہامی ہیں۔ہرمسلمان اپنے آپ کو اس آئینے میں جانچ کراندازہ لگا سکتا ہے کہ وہ کس درجے کا مسلمان ہے۔"}],[2482,"عبداللہ بن عمرو رضی اللہ عنہما کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا: \"عنقریب ہجرت کے بعد ہجرت ہو گی تو زمین والوں میں بہتر وہ لوگ ہوں گے جو ابراہیم علیہ السلام کی ہجرت گاہ (شام) کو لازم پکڑیں گے، اور زمین میں ان کے بدترین لوگ رہ جائیں گے، ان کی سر زمین انہیں باہر پھینک دے گی ۱؎ اور اللہ کی ذات ان سے گھن کرے گی اور آگ انہیں بندروں اور سوروں کے ساتھ اکٹھا کرے گی ۲؎\"۔\n§وضاحت\n۱؎ : یعنی وہ ایک ملک سے دوسرے ملک بھاگتے پھریں گے۔ ۲؎ : اس سے قیامت کے دن والا حشر مراد نہیں ہے نیز یہاں آگ سے مراد فتنے کی آگ ہے۔","حسن",{"u2":"سیدنا عبداللہ بن عمرو رضی اللہ عنہ سے روایت ہے، کہتے ہیں کہمیں نے رسول اللہ صلی اللہ علیہ وسلم کو سنا، آپ صلی اللہ علیہ وسلم فرماتے تھے ” ہجرت کے بعد ہجرت ہوتی رہے گی، زمین کے باسیوں میں سب سے بہتر وہ لوگ ہوں گے جو سیدنا ابراہیم علیہ السلام کے دار ہجرت کو اختیار کیے ہوں گے۔ اور (قرب قیامت کے وقت) برے لوگ ہی رہ جائیں گے۔ ان کی زمینیں انہیں نکال باہر پھینکیں گی، اللہ عزوجل بھی انہیں برا جانے گا اور آگ ان لوگوں کو بندروں اور خنزیروں کے ساتھ جمع کرے گی۔ “","f2":"جزیرۃ العرب کے شمال مغربی علاقہ کو شام سے تعبیر کیا جاتا ہے۔جس میں آج کل لبنان اردن فلسطین اور سوریا (شام) کی ریاستیں قائم ہیں۔ اس کی وجہ تسمیہ یہ ہے کہ یہ علاقہ قبلہ سے بایئں جانب واقع ہے۔یا بنو کنعان نے اس کی بایئں جانب کا رخ کیا تھا۔یا یہ کہ اس میں زمین کے طبقات مختلف ہیں۔اس میں سرخ سفید اور سیاہ ہر طرح کی زمین پائی جاتی ہے۔اور اس مفہوم کے لئے شامات کا لفظ استعمال کرتے ہیں۔(قاموس)"}],[2483,"عبداللہ بن حوالہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"عنقریب ایسا وقت آئے گا کہ تم الگ الگ ٹکڑیوں میں بٹ جاؤ گے، ایک ٹکڑی شام میں، ایک یمن میں اور ایک عراق میں\"۔ ابن حوالہ نے کہا: اللہ کے رسول! مجھے بتائیے اگر میں وہ زمانہ پاؤں تو کس ٹکڑی میں رہوں، آپ صلی اللہ علیہ وسلم نے فرمایا: \"اپنے اوپر شام کو لازم کر لو، کیونکہ شام کا ملک اللہ کی بہترین سر زمین ہے، اللہ اس ملک میں اپنے نیک بندوں کو جمع کرے گا، اگر شام میں نہ رہنا چاہو تو اپنے یمن کو لازم پکڑنا اور اپنے تالابوں سے پانی پلانا، کیونکہ اللہ نے مجھ سے شام اور اس کے باشندوں کی حفاظت کی ذمہ داری لی ہے ۱؎\"۔\n§وضاحت\n۱؎ : شام فتنوں سے محفوظ رہے گا اور وہاں کے رہنے والوں کو اللہ فتنہ کے ذریعہ ہلاک نہیں کرے گا۔","صحیح",{"u2":"سیدنا (عبداللہ) بن حوالہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” حالات اس طرح ہو جائیں گے کہ تم لوگ مختلف گروہوں اور لشکروں میں جمع ہو جاؤ گے، ایک لشکر شام میں ہو گا، ایک یمن میں اور ایک عراق میں۔ “ ابن حوالہ کہتے ہیں میں نے عرض کیا: اے اللہ کے رسول! میرے لیے منتخب فر دیجئیے، اگر یہ حالات پاؤں، تو کہاں سکونت اختیار کروں؟ آپ صلی اللہ علیہ وسلم نے فرمایا ” شام کو اختیار کر لینا، بلاشبہ یہ علاقہ اللہ عزوجل کا پسندیدہ ہے، اللہ تعالیٰ اپنے پسندیدہ بندوں کہ یہیں جمع فر دے گا لیکن اگر تم لوگ اس سے انکار کرو، تو پھر اپنے یمن کو اختیار کرنا اور اپنے تالابوں کا پانی پینا، بلاشبہ اللہ تعالیٰ نے مجھے شام اور اہل شام کے متعلق (فتنوں سے حفاظت کی) ضمانت دی ہے۔ “","f2":"علاقہ شام مبارک علاقوں میں سے ہے۔اللہ عزوجل نے بیت المقدس کے علاوہ اسے اپنی ظاہری باطنی خیرات وبرکات کا مرکز بنایا ہے علاقے کی زر خیزی وشادابی تو واضح ہے اور باطنی طور پر یہ علاقہ انبیاء کی سرزمین رہا ہے لوگ بالعموم فطری طور پر خیر چاہنے والے اور دین حق کے پیرو ہیں۔آخر میں حضرت عیسیٰ علیہ السلام کا نزول اسی علاقہ میں ہوگا۔اس وجہ سے اس علاقے کی طرف ہجرت کی ترغیب دی گئی ہے۔ہمیں جو سیاسی اور غیر سیاسی فتنے نظر آتے ہیں۔یہ سب وقتی چیز ہے۔اور اس سے کوئی بھی علاقہ خالی نہیں ہے۔جو ان شاء اللہ وقت آنے پرختم ہوجایئں گے۔"}],[2484,"عمران بن حصین رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"میری امت کا ایک گروہ ۱؎ ہمیشہ حق کے لیے لڑتا رہے گا اور ان لوگوں پر غالب رہے گا جو ان سے دشمنی کریں گے یہاں تک کہ ان کے آخری لوگ مسیح الدجال سے قتال کریں گے۲؎\"۔\n§وضاحت\n۱؎ : امام بخاری کہتے ہیں : اس سے مراد اہل علم ہیں، اور امام احمد بن حنبل کہتے ہیں: اس سے مراد اگر ’’ اہل الحدیث ‘‘ نہیں ہیں تو میں نہیں جانتا کہ کون لوگ ہیں۔ ۲؎ : اس سے مراد امام مہدی اور عیسی ہیں، اور ان دونوں کے متبعین ہیں عیسی علیہ السلام آسمان سے اترنے کے بعد دجال کو قتل کریں گے۔","صحیح",{"u2":"سیدنا عمران بن حصین رضی اللہ عنہ کا بیان ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” میری امت کا ایک گروہ ہمیشہ حق کے لیے قتال کرتا رہے گا اور وہ اپنے مقابل آنے والوں پر غالب رہیں گے حتیٰ کہ ان کا آخری گروہ مسیح دجال سے لڑائی کرے گا۔ “","f2":"اس گروہ سے مراد عقیدہ توحید وسنت کے حامل اور اتباع رسول صلی اللہ علیہ وسلم کے پابند لوگ ہیں۔ان کے نام مختلف زمانوں میں مختلف ہوسکتے ہیں۔ان کی پہچان ان کا عقیدہ وعمل اور کردار ہے۔"}],[2485,"ابو سعید خدری رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم سے پوچھا گیا: کون سا مومن سب سے زیادہ کامل ایمان والا ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا: \"وہ شخص جو اللہ کے راستے میں اپنی جان اور مال سے جہاد کرے، نیز وہ شخص جو کسی پہاڑ کی گھاٹی ۱؎ میں اللہ کی عبادت کرتا ہو، اور لوگ اس کے شر سے محفوظ ہوں\"۔\n§وضاحت\n۱؎ : یہ شرط نہیں ہے، اسے بطور مثال ذکر کیا گیا ہے کیونکہ عموماً گھاٹیوں میں تنہائی ہوتی ہے، اس سے گوشہ نشینی کی فضیلت ثابت ہوتی ہے کیونکہ آدمی بے کار باتوں اور لغو چیزوں سے محفوظ رہتا ہے لیکن یہ فتنہ کے زمانہ کے ساتھ خاص ہے، اور فتنہ نہ ہونے کی صورت میں جمہور کے نزدیک عام لوگوں سے اختلاط اور میل جول ہی زیادہ بہتر ہے۔","صحیح",{"u2":"سیدنا ابوسعید رضی اللہ عنہ بیان کرتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم سے سوال کیا گیا کہ مومنوں میں سے کون سا آدمی کامل ایمان والا ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا ” جو شخص اللہ کی راہ میں اپنی جان و مال سے جہاد کرتا ہو، اور وہ آدمی جو پہاڑ کی کسی گھاٹی میں اللہ کی عبادت میں مشغول ہو اور لوگوں کو اس کی برائی نہ پہنچتی ہو۔ “","f2":"جہاد کے بعد مجاہدے کی فضیلت ہے۔اور پہاڑ کی گھاٹی میں عبادت سے مقصود یہ ہے کہ آدمی دکھلاوے اور سنانے کی کیفیات سے بہت بعید ہو۔یا دوران جہاد میں اپنی زمہ داریاں ادا کرتے ہوئے عبادت بھی کرتا ہو یہ بیان ہے کہ جب معاشرے میں دین وایمان خطرے میں ہو او ر صحبت صالح میسر نہ ہو تو ان سے علیحدہ ہوجانے میں کوئی حرج نہیں۔"}],[2486,"ابوامامہ رضی اللہ عنہ کہتے ہیں کہ ایک شخص نے عرض کیا: اللہ کے رسول! مجھے سیاحت کی اجازت دے دیجئیے، نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"میری امت کی سیاحت اللہ کے راہ میں جہاد کرنا ہے\"۔","حسن",{"u2":"سیدنا ابوامامہ رضی اللہ عنہ سے مروی ہے کہ ایک شخص نے رسول اللہ صلی اللہ علیہ وسلم سے سوال کیا اور اجازت مانگی کہ مجھے سیاحت کی اجازت مرحمت فرمائیں، نبی کریم صلی اللہ علیہ وسلم نے فرمایا ” بلاشبہ میری امت کی سیاحت جہاد فی سبیل اللہ ہے۔ “","f2":"1۔سیروسیاحت کی عام عرفی مفہوم میں شریعت کے اندر کوئی حیثیت نہیں جیسے کے خوش حال بے فکرے لوگ کسی اہم مقصد کے بغیر ہی ملک ملک گھومتے پھرتے ہیں۔اس میں بالمعوم مال کا اسراف ہے۔اور وقت کا ضاع بھی۔شریعت اس کی اجازت نہیں دیتی۔جبکہ مسلمان کی پوری زندگی با مقصد اعمال میں بسر ہوتی ہے۔اسلام میں اس کا نعم البدل جہاد ہے۔اور قرآن مجید میں جوکئی مقامات (سِيرُوا فِي الْأَرْضِ) کا حکم ہے۔وہ علم اور تدبر فی الانفس۔والا فاق کی غرض سے ہے۔اس نیت سے سیاحت میں کوئی حرج نہیں۔اور جہاد کی سیاحت ان سب اغراض کی جامع ہے۔2۔صوفیاء کی سیاحت کا شریعت میں کوئی جواز نہیں سوائے اس کے کہ تعلیم وتعلم کی غرض سے ہو۔"}],[2487,"عبداللہ بن عمرو رضی اللہ عنہما سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"جہاد سے لوٹنا (ثواب میں) جہاد ہی کی طرح ہے۱؎\"۔\n§وضاحت\n۱؎ : جہاد سے لوٹنا ثواب میں جہاد ہی کی طرح اس لئے ہے کہ مجاہد جس وقت جہاد کے لئے نکلا تھا اس وقت اس کے لئے جو تیاری کی اس تیاری سے اسے اور اس کے اہل وعیال کو جو پریشانی لاحق ہوئی اب مجاہد کے لوٹنے سے وہ پریشانی ختم ہو جائے گی اور اپنے اہل و عیال میں واپس آجانے سے اسے جو طاقت و قوت حاصل ہوگی اس سے وہ اس لائق ہو جائے گا کہ دوبارہ جہاد کے لئے نکل سکے۔","صحیح",{"u2":"سیدنا عبداللہ بن عمرو رضی اللہ عنہ روایت کرتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا ” جہاد سے واپس لوٹنا (فضیلت اور ثواب میں) ایسے ہے جیسے جہاد کے لیے جانا۔“","f2":"مجاہد کے تمام اعمال ا س کے لئے اللہ تعالیٰ کے ہاں تقرب اور رفع درجات کا باعث ہوتے ہیں۔جہاد سے واپسی کے بعد مجاہد جہاد ہی کی تیاری کرتا۔مذید قوت وسائل فراہم کرتا او رہل خانہ کی خبر گیری کرتا ہے۔اس لئے اس کی واپسی بھی جہاد ہی کی طرح اجرو ثواب کی حامل ہے۔"}],[2488,"قیس بن شماس کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم کے پاس ایک عورت آئی جس کو ام خلاد کہا جاتا تھا وہ نقاب پوش تھی، وہ اپنے شہید بیٹے کے بارے میں پوچھ رہی تھی، ایک صحابی نے اس سے کہا: تو اپنے بیٹے کو پوچھنے چلی ہے اور نقاب پہنے ہوئی ہے؟ اس نے کہا: اگر میں اپنے لڑکے کی جانب سے مصیبت زدہ ہوں تو میری حیاء کو مصیبت نہیں لاحق ہوئی ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\"تیرے بیٹے کے لیے دو شہیدوں کا ثواب ہے\"، وہ کہنے لگی: ایسا کیوں؟ اللہ کے رسول! آپ صلی اللہ علیہ وسلم نے فرمایا: \"اس وجہ سے کہ اس کو اہل کتاب نے مارا ہے\"۔","ضعیف",{"u2":"جناب عبد الخبیر بن ثابت بن قیس بن شماس اپنے والد سے، وہ دادا سے روایت کرتے ہیں، انہوں نے کہا کہ ایک عورت نبی کریم صلی اللہ علیہ وسلم کی خدمت میں آئی جس کا نام ام خلاد تھا، اس نے نقاب ڈالا ہوا تھا، اپنے بیٹے کے بارے میں سوال کر رہی تھی جبکہ وہ (جہاد میں) مارا گیا تھا۔ اصحاب نبی کریم صلی اللہ علیہ وسلم میں سے کسی نے اس سے کہا: تم اپنے بیٹے کے بارے میں سوال کرنے آئی ہو اور نقاب ڈال رکھا ہے۔ (ایسی پریشانی میں پردے کا یہ اہتمام؟) اس نے کہا: اگر میرا بیٹا کھو گیا ہے تو میں نے اپنی حیاء تو نہیں کھوئی ہے۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” تیرے بیٹے کو دو شہیدوں کا ثواب ہے۔ “ اس نے پوچھا: یہ کیوں اے اللہ کے رسول؟ آپ صلی اللہ علیہ وسلم نے فرمایا ” کیونکہ اس کو اہل کتاب نے قتل کیا ہے۔ “","f2":"یہ حدیث واعظوں کی بدولت خاصی مشہور ہے۔لیکن ضعیف ہے۔اس لئے اس کا بیان کرنا درست نہیں ہے۔"}],[2489,"عبداللہ بن عمر و رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"سمندر کا سفر نہ کرے مگر حج کرنے والا، یا عمرہ کرنے والا، یا اللہ کے راستہ میں جہاد کرنے والا کیونکہ سمندر کے نیچے آگ ہے اور اس آگ کے نیچے سمندر ہے\"۔","ضعیف",{"u2":"سیدنا عبداللہ بن عمرو رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” حج، عمرہ یا جہاد فی سبیل اللہ کی غرض کے سوا سمندری سفر نہ کیا جائے، بلاشبہ سمندر کے نیچے آگ ہے اور آگ کے نیچے سمندر ہے۔ “","f2":"یہ روایت ازحد ضعیف ہے۔جبکہ آگے آنے والے باب کی احادیث صحیح ہیں۔"}],[2490,"انس بن مالک رضی اللہ عنہ کہتے ہیں کہ ام سلیم رضی اللہ عنہا کی بہن ام حرام بنت ملحان رضی اللہ عنہا نے مجھ سے بیان کیا کہ رسول اللہ صلی اللہ علیہ وسلم نے ان کے یہاں قیلولہ کیا، پھر بیدار ہوئے، آپ صلی اللہ علیہ وسلم ہنس رہے تھے، میں نے پوچھا: اللہ کے رسول! آپ کیوں ہنس رہے ہیں؟ فرمایا: \"میں نے اپنی امت میں سے چند لوگوں کو دیکھا جو اس سمندر کی پشت پر سوار ہیں جیسے بادشاہ تخت پر\"، میں نے کہا: اللہ کے رسول! دعا کیجئے، اللہ مجھ کو ان لوگوں میں سے کر دے، فرمایا: \"تو انہیں میں سے ہے\"۔ پھر آپ صلی اللہ علیہ وسلم سو گئے اور ہنستے ہوئے بیدار ہوئے، میں نے پوچھا: اللہ کے رسول! آپ کے ہنسنے کا سبب کیا ہے؟ آپ صلی اللہ علیہ وسلم نے وہی فرمایا جو پہلے فرمایا تھا، میں نے کہا: اللہ کے رسول! دعا کیجئے، اللہ مجھ کو ان لوگوں میں سے کر دے، آپ صلی اللہ علیہ وسلم نے فرمایا: \"تو پہلے لوگوں میں سے ہے\"۔ انس رضی اللہ عنہ کہتے ہیں: تو ان سے عبادہ بن صامت رضی اللہ عنہ نے شادی کی، پھر انہوں نے سمندر میں جہاد کیا توا نہیں بھی اپنے ساتھ لے گئے، جب لوٹے تو ایک خچر ان کی سواری کے لیے ان کے قریب لایا گیا، تو اس نے انہیں گرا دیا جس سے ان کی گردن ٹوٹ گئی اور وہ انتقال کر گئیں۔","صحیح",{"u2":"سیدنا انس بن مالک رضی اللہ عنہ سے روایت ہے کہ (میری خالہ) ام حرام بنت ملحان رضی اللہ عنہا ا نے بیان کیا اور یہ (انس رضی اللہ عنہ کی والدہ) ام سلیم رضی اللہ عنہا ا کی ہمشیرہ ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے (ایک بار) ان کے ہاں قیلولہ کیا۔ آپ صلی اللہ علیہ وسلم جب بیدار ہوئے تو ہنس رہے تھے۔ کہتی ہیں، میں نے پوچھا: اے اللہ کے رسول! آپ کس بات پر ہنس رہے ہیں؟ آپ صلی اللہ علیہ وسلم نے فرمایا ” میں نے دیکھا کہ (میری امت میں سے) ایک قوم کے لوگ (بڑی شان سے) سمندر میں سفر کر رہے ہیں جیسے کہ بادشاہ تختوں پر ہوں۔ “ کہتی ہیں، میں نے کہا: اے اللہ کے رسول! دعا فرمائیں کہ اللہ مجھے بھی ان میں کر دے۔ آپ صلی اللہ علیہ وسلم نے فرمایا ” تم بھی ان میں سے ہو۔ “ آپ صلی اللہ علیہ وسلم پھر سو گئے اور جب بیدار ہوئے تو پھر ہنس رہے تھے۔ میں نے کہا: اے اللہ کے رسول! آپ کس بات پر ہنس رہے ہیں؟ تو آپ صلی اللہ علیہ وسلم نے پہلے والی بات بتائی۔ میں نے کہا: اے اللہ کے رسول! اللہ سے دعا کیجئیے کہ وہ مجھے ان لوگوں میں سے بنا دے۔ آپ صلی اللہ علیہ وسلم نے فرمایا ” تم پہلے لوگوں میں ہو گی۔ “ انس بیان کرتے ہیں کہ بعد میں سیدنا عبادہ بن صامت رضی اللہ عنہ نے ان سے نکاح کر لیا اور جہاد کے لیے سمندر کے سفر پر گئے اور ان (ام حرام) کو بھی ساتھ لے گئے اور جب واپس لوٹے تو ایک خچر ان کے لیے لایا گیا کہ اس پر سوار ہوں تو اس نے ان کو گرا دیا، اس سے ان کی گردن ٹوٹ گئی اور وہ وفات پا گئیں۔","f2":"1۔یہ حدیث صریح اور واضح طور پردلائل نبوت میں سے ہے۔کیونکہ اس میں رسول اللہ صلی اللہ علیہ وسلم نے ایک ایسی بات کی خبر دی ہے جو آپ صلی اللہ علیہ وسلم کی وفات کے بعد وقوع پزیر ہوئی۔جس کو سوائے اللہ عزوجل کے کوئی او ر نہیں جان سکتا۔لہذا رسول اللہ صلی اللہ علیہ وسلم کو بذریعہ وحی اس کا علم ہوا۔یہ سن 28 ہجری حضرت عثمان رضی اللہ تعالیٰ عنہ کے دور خلافت کی بات ہے۔جبکہ حضرت معاویہ بن ابو سفیان رضی اللہ تعالیٰ عنہ اس جہادی سفر کے امیرتھے۔لہذا اس سے حضرت معاویہ رضی اللہ تعالیٰ عنہ کی فضیلت ومنقبت بھی ثابت ہوئی۔نیز ان صحابہ کرامرضوان اللہ عنہم اجمعین کی بھی جنہوں نے ان کی معیت میں یہ سمندری سفرکیاتھا۔یہ ایک جہادی سفر تھا۔3۔کسی خوش کن اور پسندیدہ بات پر ہنسنا جائز ہے۔"}],[2491,"انس بن مالک رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم قباء جاتے تو ام حرام بنت ملحان رضی اللہ عنہا کے پاس جاتے، یہ عبادہ بن صامت رضی اللہ عنہ کی زوجیت میں تھیں، ایک روز آپ صلی اللہ علیہ وسلم ان کے پاس آئے تو انہوں نے آپ کو کھانا کھلایا اور بیٹھ کر آپ صلی اللہ علیہ وسلم کے سر کی جوئیں نکالنے لگیں ۱؎، اور آگے راوی نے یہی حدیث بیان کی۔ ابوداؤد کہتے ہیں: بنت ملحان کا انتقال قبرص میں ہوا۔\n§وضاحت\n۱؎ : ام حرام بنت ملحان رضی اللہ عنہا یا تو آپ صلی اللہ علیہ وسلم کی رضاعی خالہ تھیں یا آپ کے والد یا دادا کی خالہ تھیں۔","صحیح",{"u2":"سیدنا انس بن مالک رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم جب قباء تشریف لے جاتے، تو ام حرام بنت ملحان رضی اللہ عنہا ا کے ہاں بھی جاتے اور وہ سیدنا عبادہ بن صامت رضی اللہ عنہ کی زوجیت میں تھیں۔ آپ ایک دن ان کے ہاں تشریف لے گئے تو انہوں نے آپ کو کھانا پیش کیا اور پھر بیٹھ کر آپ کے سر سے جوئیں تلاش کرنے لگیں۔ اور یہی مذکورہ حدیث بیان کی۔ امام ابوداؤد رضی اللہ عنہ کہتے ہیں، بنت ملحان کی وفات قبرص میں ہوئی تھی۔","f2":"1۔ام سلیم رضی اللہ عنہا اور ام حرام رضی اللہ عنہا نبی صلی اللہ علیہ وسلم کے محارم میں سے تھیں۔کچھ نے ان کو آپ صلی اللہ علیہ وسلم کی رضاعی خالہ بتایاہے۔اور کئی کہتے ہیں۔یہ آپ کے والد یا دادا کی خالہ تھیں۔2۔نبی کا خواب اور پیشن گویئاں سب وحی پر مبنی ہوتی ہیں۔3۔آپ صلی اللہ علیہ وسلم کے دوسرے خواب میں آپ کو کوئی دوسرے لوگ دکھائے گئے تھے۔اس لئے آپ صلی اللہ علیہ وسلم نے ام حرام سے فرمایا۔کہ تم پہلے لوگوں میں سے ہوگی۔4۔سفر جہاد میں موت جس کیفیت میں بھی آئے مبارک ہوتی ہے۔5۔اس میں یہ پیش گوئی تھی کہ یہ امت بر (خشکی)کے علاوہ بحر (سمندر) میں بھی جہاد کرے گی جوکہ ثابت ہے۔"}],[2492,"ام حرام رمیصاء ۱؎ رضی اللہ عنہا کہتی ہیں کہ نبی اکرم صلی اللہ علیہ وسلم سوئے پھر بیدار ہوئے، اور وہ اپنا سر دھو رہی تھیں تو آپ صلی اللہ علیہ وسلم ہنستے ہوئے بیدار ہوئے، انہوں نے کہا: اللہ کے رسول! کیا آپ میرے بال دیکھ کر ہنس رہے ہیں؟ آپ صلی اللہ علیہ وسلم نے فرمایا: \"نہیں\"، پھر انہوں نے یہی حدیث کچھ کمی بیشی کے ساتھ بیان کی۔ ابوداؤد کہتے ہیں: رمیصاء ام سلیم کی رضاعی بہن تھیں ۲؎۔\n§وضاحت\n۱؎ : ام سلیم رضی اللہ عنہا ام حرام بنت ملحان رضی اللہ عنہا کی بہن ہیں، سند میں اخت ام سلیم سے مراد ام حرام بنت ملحان رضی اللہ عنہا ہی ہیں، ام حرام رضی اللہ عنہا کو رمیصاء کہا جاتا تھا، اور امّ سلیم رضی اللہ عنہا کو غمیصاء۔ ۲؎ : ابوداود کا یہ قول صحیح نہیں ہے، وہ رضاعی نہیں بلکہ نسبی اور حقیقی بہن تھیں۔","صحیح",{"u2":"سیدہ ام سلیم رضی اللہ عنہا ا کی ہمشیرہ رمیصاء سے روایت ہے کہ نبی کریم صلی اللہ علیہ وسلم سو گئے، پھر جاگے جبکہ یہ اپنا سر دھو رہی تھیں، آپ صلی اللہ علیہ وسلم جاگے تو ہنس رہے تھے، اس نے کہا: اے اللہ کے رسول! کیا آپ صلی اللہ علیہ وسلم میرے سر پر ہنس رہے ہیں؟ آپ صلی اللہ علیہ وسلم نے فرمایا ” نہیں۔ “ اور پوری حدیث بیان کی جس میں کچھ کمی بیشی ہے۔ امام ابوداؤد رضی اللہ عنہ فرماتے ہیں رمیصاء ام سلیم رضی اللہ عنہا ا کی رضاعی بہن ہیں اور یہی ام حرام بنت ملحان ہیں۔"}],[2493,"ام حرام رضی اللہ عنہا سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"(جہاد یا حج کے لیے) سمندر میں سوار ہونے سے جس کا سر گھومے اور اسے قے آئے تو اس کے لیے ایک شہید کا ثواب ہے، اور جو ڈوب جائے تو اس کے لیے دو شہیدوں کا ثواب ہے\"۔","حسن",{"u2":"سیدہ ام حرام رضی اللہ عنہا ا، نبی کریم صلی اللہ علیہ وسلم سے روایت کرتی ہیں کہ آپ صلی اللہ علیہ وسلم نے فرمایا ” سمندر کے سفر میں جس کا سر چکرائے اور قے آ جائے تو اس کے لیے ایک شہید کا ثواب ہے اور جو ڈوب کر مر جائے اس کو دو شہیدوں کا ثواب ہے۔ “","f2":"اس سے مراد جہاد یا حج وعمرے کا سفر ہے۔دیگر سمندری سفر جو اطاعت کے سفر ہوں ان میں بھی اس فضیلت کی توقع کی جانی چاہیے۔"}],[2494,"ابوامامہ باہلی رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"تین قسم کے افراد ایسے ہیں جن کا ضامن اللہ تعالی ہے: ایک وہ جو اللہ کے راستے میں جہاد کے لیے نکلے، اللہ اس کا ضامن ہے یا اسے وفات دے کر جنت میں داخل کرے گا، یا اجر اور غنیمت کے ساتھ واپس لوٹائے گا، دوسرا وہ شخص جو مسجد کی طرف چلا، اللہ اس کا ضامن ہے یا اسے وفات دے کر جنت میں داخل کرے گا، یا اجر اور غنیمت کے ساتھ واپس لوٹائے گا، تیسرا وہ شخص جو اپنے گھر میں سلام کر کے داخل ہوا، اللہ اس کا بھی ضامن ہے\"۔","صحیح",{"u2":"سیدنا ابوامامہ باہلی رضی اللہ عنہ، رسول اللہ صلی اللہ علیہ وسلم سے بیان کرتے ہیں کہ آپ صلی اللہ علیہ وسلم نے فرمایا ” تین (قسم کے) آدمیوں کا اللہ عزوجل ضامن ہے۔ جو شخص اللہ کی راہ میں جہاد کے لیے نکلا تو اللہ اس کا ضامن ہے حتیٰ کہ (اگر) اس کی وفات ہو جائے تو اس کو جنت میں داخل کرے گا یا اجر و ثواب اور غنیمت کے ساتھ واپس لوٹائے گا، دوسرا وہ آدمی جو مسجد کی طرف گیا تو اللہ اس کا ضامن ہے حتیٰ کہ (اگر) اس کی وفات ہو جائے تو اس کو جنت میں داخل کرے گا یا اجر و ثواب اور غنیمت کے ساتھ لوٹائے گا، اور تیسرا وہ آدمی جو سلام (یا سلامتی) کے ساتھ اپنے گھر میں داخل ہوا تو اللہ عزوجل اس کا ضامن ہے۔“","f2":"گھر میں داخل ہونے والا السلام و علیکم کہے جیسے کہ فرمایا (فَإِذَا دَخَلْتُم بُيُوتًا فَسَلِّمُوا عَلَىٰ أَنفُسِكُمْ)(النور۔61) جب گھروں میں داخل ہو تو اپنے لوگوں پر سلام کہو دوسرا مفہوم یہ بھی ہے کہ دور فتن میں امن وسلامتی کی غرض سے لوگوں سے اختلاط کو کم کردے۔اورگھر میں رہے تو ایسا آدمی اللہ کی ضمانت میں ہوگا۔(خطابی)"}],[2495,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"کافر اور اس کو قتل کرنے والا مسلمان دونوں جہنم میں کبھی بھی اکٹھا نہ ہوں گے ۱؎\"۔\n§وضاحت\n۱؎ : یعنی اس کا یہ قتل کرنا اس کے گناہوں کا کفارہ بن جائے گا اور وہ سزا سے بچ جائے گا اور اگر اسے سزا ہوئی بھی تو وہ جہنم کے علاوہ کوئی اور سزا ہو گی مثلاً وہ اعراف میں قید کر دیا جائے گا اور جنت میں دخول اولی سے محروم کر دیا جائے گا۔","صحیح",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” کافر اور اس کا قاتل (مجاہد) آگ میں کبھی بھی اکٹھے نہیں ہو سکتے۔ “","f2":"جہاد مجاہد کے لئے تمام گناہوں کاکفارہ بن جاتا ہے۔اور وہ اس طرح جنت ک مستحق ہوجاتا ہے۔ الا یہ کہ اس کے ذمے کوئی حقوق العباد ہوں۔اگر یہ معاف نہ ہوئے اور کوئی عقاب ہوا بھی تو آگ کے بغیر ہوگا۔ مثلا اعراف وغیرہ میں روکا جائے گا۔(نووی) واللہ اعلم"}],[2496,"بریدہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"مجاہدین کی بیویوں کی حرمت جہاد سے بیٹھے رہنے والے لوگوں پر ایسی ہے جیسے ان کی ماؤں کی حرمت ہے، اور جو خانہ نشین مرد مجاہدین کے گھربار کی خدمت میں رہے، پھر ان کے اہل میں خیانت کرے تو قیامت کے دن ایسا شخص کھڑا کیا جائے گا اور مجاہد سے کہا جائے گا: اس شخص نے تیرے اہل و عیال میں تیری خیانت کی اب تو اس کی جتنی نیکیاں چاہے لے لے\"، اس کے بعد رسول اللہ صلی اللہ علیہ وسلم ہماری طرف متوجہ ہوئے اور فرمایا: \"پھر تم کیا سمجھتے ہو ۱؎؟\"ابوداؤد کہتے ہیں: قعنب ایک نیک آدمی تھے، ابن ابی لیلی نے قعنب کو قاضی بنانے کا ارادہ کیا تو انہوں نے اس سے انکار کیا، اور کہا کہ میں ایک درہم میں اپنی ضرورت پوری کرنا چاہتا ہوں کہ میں اس میں کسی آدمی کی مدد لے سکوں، پھر کہا: کون ہے جو اپنی ضرورت کے لیے کسی سے مدد نہیں لیتا، پھر عرض کیا: تم لوگ مجھے نکال دو یہاں تک کہ میں دیکھوں (کہ کیسے میری ضرورت پوری ہوتی ہے) تو انہیں نکال دیا گیا، پھر وہ (ایک مکان میں) چھپ گئے، سفیان کہتے ہیں: اسی دوران کہ وہ چھپے ہوئے تھے وہ مکان ان پر گر پڑا اور وہ مر گئے۔\n§وضاحت\n۱؎ : یعنی نیکیاں لینے والے کی رغبت اور زیادہ سے زیادہ نیکیاں سمیٹ لینے کی اس کی چاہت کا تم کیا اندازہ کر سکتے ہو ؟ مطلب یہ ہے کہ اس شخص کے پاس کوئی نیکی باقی ہی نہیں رہ جائے گی۔","صحیح",{"u2":"جناب (سلیمان) ابن بریدہ اپنے والد (بریدہ رضی اللہ عنہ) سے روایت کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” خانہ نشین لوگوں پر مجاہدین کی عورتوں کی عزت و حرمت ایسے (واجب اور لازم) ہے جیسے کہ ان کی اپنی مائیں ہوں، جو کوئی (جہاد سے) پیچھے رہے اور مجاہدین کے اہل میں خیانت (بدنظری یا خباثت) کا معاملہ کرے تو قیامت کے روز ایسے شخص کے لیے جھنڈا لگایا جائے گا اور (اسے اہل محشر میں رسوا کرتے ہوئے) مجاہد سے کہا جائے گا یہی شخص ہے جو تیرے پیچھے تیرے اہل میں برائی کرتا رہا، اس کی نیکیوں میں سے جو لینا چاہتا ہے، لے لے۔ “ پھر رسول اللہ صلی اللہ علیہ وسلم ہماری طرف متوجہ ہوئے اور فرمایا ” تو تمہارا کیا خیال ہے؟ “ (بھلا وہ کچھ چھوڑے گا، یعنی ہرگز نہیں، سبھی نیکیاں سمیٹ لے گا)۔ امام ابوداؤد رضی اللہ عنہ بیان کرتے ہیں کہ راوی حدیث قعنب ایک نیک آدمی تھے، ابن ابی لیلیٰ نے ان کو قاضی بنانا چاہا تو انہوں نے انکار کر دیا اور کہا کہ مجھے ایک درہم کی کوئی معمولی چیز بھی لینی ہوتی ہے تو دوسرے آدمی کی مدد لیتا ہوں (تو قضاء و عدالت کی ذمہ داریاں کیسے اٹھا سکتا ہوں؟) انہوں نے کہا: ہم میں سے کون ہے جسے دوسرے کی مدد کی ضرورت نہ پڑتی ہو؟ انہوں نے کہا: اب تو اجازت دیں میں کچھ سوچ لوں۔ چنانچہ اجازت دی گئی تو چھپ گئے۔ سفیان بیان کرتے ہیں کہ اسی کیفیت میں تھے کہ گھر کی چھت گر پڑی اور اس سے وفات پا گئے۔","f2":"مجاہدین جو جہاد وقتال میں مشغول ومصروف ہوں۔ان کے اہل وعیال کی جان مال اور آبرو کی حفاظت اور ان کی خدمت کرنا انتہائی اجر وثواب کا کام ہے۔اور ان میں خیانت وخباثت کا مظاہرہ ایسے ہے جیسے کوئی اپنی ماں کے ساتھ یہ معاملہ کرے۔اور اسی پر ان لوگوں کو قیاس کیا گیا ہے۔جودین اسلام کی دیگر فکری حدود مثلا تعلیم وتعلم کے سلسلے میں اپنے گھروں سے غائب ہوں۔تو ان کے اقرباء اور دیگر افراد معاشرہ پر لازم ہے۔کے ان کے اہل وعیال کے تحفظ وحرمت کا پوری طرح خیال ر کھیں جیسے کہ اپنی مائوں کا تحفظ کرتے ہیں۔"}],[2497,"عبداللہ بن عمرو رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"مجاہدین کی کوئی جماعت ایسی نہیں جو اللہ کی راہ میں لڑتی ہو پھر مال غنیمت حاصل کرتی ہو، مگر آخرت کا دو تہائی ثواب اسے پہلے ہی دنیا میں حاصل ہو جاتا ہے، اور ایک تہائی (آخرت کے لیے) باقی رہتا ہے، اور اگر اسے مال غنیمت نہیں ملا تو آخرت میں ان کے لیے مکمل ثواب ہو گا\"۔","صحیح",{"u2":"سیدنا عبداللہ بن عمرو رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” جو مجاہدین اللہ کی راہ میں جہاد کے لیے نکلتے ہیں اور غنیمت حاصل کر لیتے ہیں، وہ اپنے آخرت کے اجر میں سے دو تہائی جلد ہی (اس دنیا ہی میں) پا لیتے ہیں اور ایک تہائی ان کے لیے باقی رہ جاتا ہے اور اگر انہیں کوئی غنیمت نہ ملے تو ان کا کامل اجر (قیامت تک کے لیے) محفوظ ہو جاتا ہے۔ “","f2":"انسان جس قدر بھی نعمتیں اس دنیا میں استعمال کررہا ہے۔وہ اپنے آخرت کے حصے سے استعمال کررہا ہے۔یہی وجہ ہے کہ حضرت عبد الرحمٰن بن عوف رضی اللہ تعالیٰ عنہ کا کہنا تھا کہ ہمیں اس قدر جو دنیا دی گئی ہے۔تو ہمیں اندیشہ ہوتا ہے کہ کہیں ہماری نیکیوں کا بدلہ اس دنیا میں تو نہیں دے دیاگیا۔(صحیح البخاری۔الجنائز حدیث 1275)حضرت خباب رضی اللہ تعالیٰ عنہ کا بیان ہے کہ ہم میں سے کچھ کے پھل یہیں پک گئے ہیں۔اور وہ اب ان سے بہرہ ور ہورہے ہیں۔(صحیح البخاری الجنائز حدیث 1276)حضرت عمر رضی اللہ تعالیٰ عنہ نے اپنے لذید مطعومات ومشروبات کا ستعمال ترک کردیا تھا۔اور آخرت میں کفار سے بالخصوص کہا جائے گا۔\n(أَذْهَبْتُمْ طَيِّبَاتِكُمْ فِي حَيَاتِكُمُ الدُّنْيَا وَاسْتَمْتَعْتُم بِهَا فَالْيَوْمَ تُجْزَوْنَ عَذَابَ الْهُونِ بِمَا كُنتُمْ تَسْتَكْبِرُونَ فِي الْأَرْضِ بِغَيْرِ الْحَقِّ وَبِمَا كُنتُمْ تَفْسُقُونَ ﴿٢٠﴾)(الاحقاف۔20)\nتم دنیا کی زندگی میں اپنی لذتیں حاصل کرچکے اور ان سے فائدہ اٹھا چکے سو آج تم کو ذلت کا عذاب دیا جائےگا۔یہ اس کی سزا ہے کہ تم زمین میں ناحق غرور کیا کرتے تھے ااور بدکردار تھے"}],[2498,"معاذ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"(دوران جہاد) نماز، روزہ اور ذکر الٰہی (کا ثواب) جہاد میں خرچ کے ثواب پر سات سو گنا تک بڑھا دیا جاتا ہے\"۔","ضعیف",{"u2":"جناب سہل بن معاذ اپنے والد (معاذ بن انس رضی اللہ عنہ) سے روایت کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” اللہ کی راہ میں جہاد کے دوران میں نماز، روزے اور ذکر کا اجر، اللہ کی راہ میں خرچ کرنے کے مقابلے میں سات سو گنا تک بڑھا دیا جاتا ہے۔ “"}],[2499,"ابو مالک اشعری رضی اللہ عنہ کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا: \"جو شخص اللہ کی راہ میں نکلا پھر وہ مر گیا، یا مار ڈالا گیا تو وہ شہید ہے، یا اس کے گھوڑے یا اونٹ نے اسے روند دیا، یا کسی سانپ اور بچھو نے ڈنک مار دیا، یا اپنے بستر پہ، یا موت کے کسی بھی سبب سے جسے اللہ نے چاہا مر گیا، تو وہ شہید ہے، اور اس کے لیے جنت ہے\"۔","ضعیف",{"u2":"سیدنا ابو مالک اشعری رضی اللہ عنہ بیان کرتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو سنا، آپ صلی اللہ علیہ وسلم فرماتے تھے ” جو شخص جہاد کے لیے روانہ ہوا اور وفات پا گیا، یا قتل کر دیا گیا، تو وہ شہید ہے، یا اگر اس کو اس کے گھوڑے یا اونٹ نے گرا دیا ہو، یا کسی جانور نے کاٹا ہو، یا اپنے بستر ہی پر اسے موت آئی ہو، یا جس کسی کیفیت میں بھی اس کی وفات ہوئی ہو تو وہ شہید ہے اور بلاشبہ اس کے لیے جنت ہے۔ “"}],[2500,"فضالہ بن عبید رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"ہر میت کا عمل مرنے کے بعد ختم کر دیا جاتا ہے، سوائے سرحد کی پاسبانی اور حفاظت کرنے والے کے، اس کا عمل اس کے لیے قیامت تک بڑھتا رہے گا اور قبر کے فتنہ سے وہ مامون کر دیا جائے گا\"۔","صحیح",{"u2":"سیدنا فضالہ بن عبید رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” ہر مرنے والے کا عمل (اس کے مرنے پر) ختم ہو جاتا ہے، مگر مورچہ بند کہ اس کا عمل قیامت تک کے لیے بڑھتا رہتا ہے اور وہ قبر کے عذاب سے (یا منکر و نکیر کے سوال جواب) سے امن میں رہتا ہے۔ “","f2":"یہ فضیلت دشمن کے سامنے مورچہ بند ہونے کی ہے۔تو جو شخص کفار سے پنجہ آزمائی کرتا۔اور قتل ہوتا یا قتل کرتا ہو۔اس کے درجات اور بھی زیادہ ہوں گے۔قرآن مجید نے اس عمل کی ترغیب میں فرمایا ہے۔\n(يَا أَيُّهَا الَّذِينَ آمَنُوا اصْبِرُوا وَصَابِرُوا وَرَابِطُوا وَاتَّقُوا اللَّـهَ لَعَلَّكُمْ تُفْلِحُونَ ﴿٢٠٠﴾)(آل عمران۔200)\nاے ایمان والو! صبر کرو۔ثابت قدم رہو۔مورچوں پرجمے رہو۔اور اللہ سے ڈرتے رہو۔تاکہ کامیاب ہوجائو جہاد قتال سے ملتا جلتا کام مثلا مشکل حالات میں اشاعت توحید وسنت اوررد شرک وبدعت جو کہ درس وتدریس اور تحریروتقریر کے زریعے سے ہو اس کے متعلق بھی توقع کی جانی چاہیے۔کہ حسب نیت یہ بھی ایک عظیم رباط ومرابطہ ہے۔چنانچہ اساتذہ مبلغین اور مولفین قلعہ اسلام کی فکری حدود کے مورچہ بند ہیں جب تک ان کی باقیات"}],[2501,"سہل بن حنظلیہ رضی اللہ عنہ سے روایت ہے کہ لوگ رسول اللہ صلی اللہ علیہ وسلم کے ساتھ حنین کے دن چلے اور بہت ہی تیزی کے ساتھ چلے، یہاں تک کہ شام ہو گئی، میں نماز میں رسول اللہ صلی اللہ علیہ وسلم کے پاس حاضر ہوا اتنے میں ایک سوار نے آ کر کہا: اللہ کے رسول! میں آپ لوگوں کے آگے گیا، یہاں تک کہ فلاں فلاں پہاڑ پر چڑھا تو کیا دیکھتا ہوں کہ قبیلہ ہوازن کے لوگ سب کے سب اپنی عورتوں، چوپایوں اور بکریوں کے ساتھ بھاری تعداد میں مقام حنین میں جمع ہیں، یہ سن کر رسول اللہ صلی اللہ علیہ وسلم مسکرائے اور فرمایا: \"ان شاءاللہ یہ سب کل ہم مسلمانوں کا مال غنیمت ہوں گے\"، پھر فرمایا: \"رات میں ہماری پہرہ داری کون کرے گا؟\" انس بن ابومرثد غنوی رضی اللہ عنہ نے کہا: اللہ کے رسول! میں کروں گا، آپ صلی اللہ علیہ وسلم نے فرمایا: \"تو سوار ہو جاؤ\"، چنانچہ وہ اپنے گھوڑے پر سوار ہو کر رسول اللہ صلی اللہ علیہ وسلم کے پاس آئے تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اس گھاٹی میں جاؤ یہاں تک کہ اس کی بلندی پہ پہنچ جاؤ اور ایسا نہ ہو کہ ہم تمہاری وجہ سے آج کی رات دھوکہ کھا جائیں\"، جب ہم نے صبح کی تو رسول اللہ صلی اللہ علیہ وسلم اپنے مصلے پر آئے، آپ نے دو رکعتیں پڑھیں پھر فرمایا: \"تم نے اپنے سوار کو دیکھا؟\" لوگوں نے کہا: اللہ کے رسول! ہم نے اسے نہیں دیکھا، پھر نماز کے لیے اقامت کہی گئی تو رسول اللہ صلی اللہ علیہ وسلم نماز پڑھنے لگے لیکن دوران نماز کنکھیوں سے گھاٹی کی طرف دیکھ رہے تھے، یہاں تک کہ جب آپ صلی اللہ علیہ وسلم نماز پڑھ چکے اور سلام پھیرا تو فرمایا: \"خوش ہو جاؤ! تمہارا سوار آ گیا\"، ہم درختوں کے درمیان سے گھاٹی کی طرف دیکھنے لگے، یکایک وہی سوار رسول اللہ صلی اللہ علیہ وسلم کے پاس آ کر کھڑا ہو گیا اور سلام کیا اور کہنے لگا: میں گھاٹی کے بالائی حصہ پہ چلا گیا تھا جہاں رسول اللہ صلی اللہ علیہ وسلم نے مجھے حکم دیا تھا تو جب صبح کی تو میں نے دونوں گھاٹیوں پر چڑھ کر دیکھا تو کوئی بھی نہیں دکھائی پڑا تو رسول اللہ صلی اللہ علیہ وسلم نے ان سے فرمایا: \"کیا تم آج رات گھوڑے سے اترے تھے؟\"، انہوں نے کہا: نہیں، البتہ نماز پڑھنے کے لیے یا قضائے حاجت کے لیے اترا تھا، اس پر رسول اللہ صلی اللہ علیہ وسلم نے ان سے فرمایا: \"تم نے اپنے لیے جنت کو واجب کر لیا، اب اگر اس کے بعد تم عمل نہ کرو تو تمہیں کچھ نقصان نہ ہو گا۱؎\"۔\n§وضاحت\n۱؎ : یعنی تمہارے لئے تمہارا یہی عمل جنت میں داخل ہونے کے لئے کافی ہو گا۔","صحیح",{"u2":"سیدنا سہل بن حنظلیہ رضی اللہ عنہ بیان کرتے ہیں کہ (ہم) لوگ غزوہ حنین کے موقع پر رسول اللہ صلی اللہ علیہ وسلم کے ساتھ روانہ ہوئے اور بہت لمبی مسافت طے کی حتیٰ کہ پچھلا پہر ہو گیا۔ سو میں نماز کے وقت رسول اللہ صلی اللہ علیہ وسلم کے ہاں حاضر تھا کہ ایک گھوڑ سوار آیا اور کہا: اے اللہ کے رسول! میں آپ کے آگے آگے چلتا رہا حتیٰ کہ فلاں فلاں پہاڑ پر چڑھ گیا تو دیکھا کہ قبیلہ ہوازن کے سب لوگ اپنی عورتوں، چوپاؤں اور بکریوں سمیت حنین کی طرف جمع ہو رہے ہیں، رسول اللہ صلی اللہ علیہ وسلم نے تبسم فرمایا اور کہا: ” کل انشاءاللہ یہ سب مسلمانوں کی غنیمت ہو گا۔ “ پھر فرمایا ” آج رات کون ہمارا پہرہ دے گا؟ “ سیدنا انس بن ابی مرثد غنوی رضی اللہ عنہ نے کہا: میں، اے اللہ کے رسول! آپ نے فرمایا ” تو سوار ہو جاؤ۔ “ چنانچہ وہ اپنے گھوڑے پر سوار ہو گیا اور رسول اللہ صلی اللہ علیہ وسلم کے پاس آیا۔ آپ نے اس سے فرمایا ” اس گھاٹی کی طرف چلے جاؤ حتیٰ کہ اس کے اوپر چڑھ جاؤ اور ایسا نہ ہو کہ رات میں ہم تمہاری طرف سے دھوکہ کھا جائیں۔ “ جب صبح ہوئی تو رسول اللہ صلی اللہ علیہ وسلم اپنے مصلے پر تشریف لائے اور دو رکعتیں پڑھیں۔ پھر دریافت فرمایا ” کیا تم نے اپنے سوار کو دیکھا ہے؟ “ صحابہ نے کہا: نہیں، اے اللہ کے رسول! ہم نے اس کو نہیں دیکھا ہے۔ پھر نماز کے لیے تکبیر کہی گئی اور رسول اللہ صلی اللہ علیہ وسلم نماز پڑھانے لگے اور اس دوران میں آپ گھاٹی کی طرف بھی دیکھتے رہے حتیٰ کہ جب نماز مکمل کر لی اور سلام پھیر لیا تو فرمایا ” خوشخبری ہو، تمہارا سوار آ گیا ہے۔ “ پس ہم بھی درختوں میں سے گھاٹی کی طرف دیکھنے لگے، تو وہ سامنے آ گیا اور رسول اللہ صلی اللہ علیہ وسلم کے پاس آ کھڑا ہوا۔ اس نے سلام کیا اور کہا: میں (آپ کے ہاں سے) روانہ ہوا حتیٰ کہ اس گھاٹی کے اوپر چڑھ گیا جہاں اللہ کے رسول صلی اللہ علیہ وسلم نے مجھے حکم فرمایا تھا، جب صبح ہوئی تو میں نے دونوں گھاٹیوں میں دیکھا تو مجھے کوئی شخص نظر نہیں آیا۔ رسول اللہ صلی اللہ علیہ وسلم نے اس سے پوچھا: ” کیا تم رات کو (گھوڑے سے) اترے بھی تھے؟ “ اس نے کہا: نہیں، صرف نماز پڑھنے یا قضائے حاجت کے لیے ہی اترا ہوں۔ پس رسول اللہ صلی اللہ علیہ وسلم نے اس سے فرمایا: ” تم نے اپنے لیے لازم کر لی (جنت) تم اس کے بعد اور کوئی عمل نہ بھی کرو تو کوئی مؤاخذہ نہیں۔ “","f2":"1۔جہادی مہموں اوردیگر اہم مواقع پر پہرہ داری کا انتظام حسب ضرورت مشروع ومسنون بلکہ واجب ہے۔اور توکل کے خلاف نہیں۔2۔نماز کے دوران میں بلاوجہ التفات ممنوع ہے۔مگراہم ضرورت کے پیش نظر مباح ہے۔مگر خیال رہے کہ منہ پھیر کر نہ دیکھا جائے۔4۔صحابی رسول صلی اللہ علیہ وسلم نے فرمان رسول صلی اللہ علیہ وسلم کے ظاہر الفاظ پر اس شدت سے تعمیل کی کہ ساری رات گھوڑے کی پیٹھ پر گزار دی۔5۔نبی کریم صلی اللہ علیہ وسلم کا یہ فرمانا کہ تم اس کے بعد اور کوئی عمل نہ بھی کرو تو مواخذہ نہیں ان کے اس عمل کی قبولیت کی بشارت تھی۔اس سے یہ نہیں سمجھنا چاہیے کہ انہیں اعمال تکلیفہ سے آذادی کا پروانہ دے دیا گیا تھا۔بلکہ اس میں ان کی بخشش کی خوش خبری تھی۔جس کی بنا پر یہ لوگ اور بھی زیادہ متقی عامل اور محنت کش ہوجاتے تھے۔جیسے کہ خود رسول اللہ صلی اللہ علیہ وسلم نے اپنے بارے میں فرمایا تھا۔ کیا میں اللہ کا شکر گزار بندہ نہ بنوں (صحیح البخاری۔التھجد حدیث 1130۔وصحیح مسلم صفات المنافقین حدیث 2819)5۔جہاد میں پہرہ داری کے ایک آسان عمل کا یہ اجر ہے تو قتال معرکہ آرائی کے فضائل کس قدر زیادہ ہوں گے۔6۔مجاہدین معرکی طرح فکرو عمل کے میدان میں بھی علمائے حق پر لازم ہے۔کے دنیا میں پھیلنے والی اسلامی تحریکوں پر گہری نظر رکھیں۔جو کہ مسلمانوں اور ان کے معاشرے میں نقب لگانے میں کوئی دقیقہ فروگذاشت نہیں کرتیں۔اور ان کا جواب بھر پور علمی وفکری اسلوب میں دینا واجب ہے۔"}],[2502,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"جو شخص مر گیا اور اس نے نہ جہاد کیا اور نہ ہی کبھی اس کی نیت کی تو وہ نفاق کی قسموں میں سے ایک قسم پر مرا\"۔","صحیح",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا ” جو شخص اس حال میں مرا کہ اس نے جہاد نہیں کیا اور اپنے دل میں بھی جہاد کی نیت نہیں کی تو وہ نفاق کی ایک شاخ پر مرا۔ “","f2":"مخلص مسلمان ہر حال میں اسلام اور مسلمانوں کا غلبہ چاہتا ہے۔اوراس کے لئے کوشاں رہتا ہے۔جہاد کا شائق اور جہادی عمل کا موئد اور معاون ہوتا ہے۔اگر کسی میں ایسی کوئی کیفیت نہیں تو وہ نام ہی کا مسلمان ہے۔اور ایسے جذبات سے محرومی نفاق کا ایک حصہ اور بہت بڑی بد بختی ہے۔"}],[2503,"ابوامامہ رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"جس نے جہاد نہیں کیا یا کسی جہاد کرنے والے کے لیے سامان جہاد فراہم نہیں کیا یا کسی مجاہد کے اہل و عیال کی بھلائی کے ساتھ خبرگیری نہ کی تو اللہ اسے کسی سخت مصیبت سے دو چار کرے گا\"، یزید بن عبداللہ کی روایت میں «قبل يوم القيامة» \"قیامت سے پہلے\" کا اضافہ ہے۔","حسن",{"u2":"سیدنا ابوامامہ رضی اللہ عنہ سے منقول ہے کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا ” جس نے جہاد میں حصہ نہیں لیا، یا کسی مجاہد کو مادی تعاون نہیں دیا یا مجاہد کے روانہ ہو جانے کے بعد اس کے اہل و عیال کی بحسن و خوبی خبرگیری نہیں کی تو اللہ تعالیٰ اسے کسی مصیبت میں مبتلا کر دے گا۔ “ یزید بن عبداللہ نے اپنی روایت میں یوں بیان کیا: ” قیامت سے پہلے اسے کسی مصیبت میں مبتلا کر دے گا۔ “","f2":"امت مسلمہ کو جس ہزیمت کا سامنا ہے۔بلاشبہ وہ جہاد سے روگردانی اور کفارکے مقابلے میں بزدلی کا نتیجہ ہے۔اوراللہ عزوجل کی جانب سے قسم قسم کی آفات بھی اس کے مواخذے کی دلیل ہیں۔"}],[2504,"انس رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"مشرکوں سے اپنے اموال، اپنی جانوں اور زبانوں سے جہاد کرو\"۔","صحیح",{"u2":"سیدناانس رضی اللہ عنہ سے مروی ہے کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا ” مشرکین سے جہاد کرو اپنے مالوں کے ساتھ، اپنی جانوں کے ساتھ اور اپنی زبانوں کے ساتھ۔ “","f2":"مسلمانوں کے تمام طبقات کو اپنی اپنی ممکنہ صلاحیت کے ساتھ کفر کے مقابلے میں تیار رہنا واجب ہے۔جوان اپنی جانوں اور جوانی سے اغنیاء اپنے مالوں سے علماء دعوت وترغیب سے اور تردید کفر وشرک سے بزرگ عورتیں اور بچے اللہ کے حضوردعائوں سے اسلام۔مسلمانوں اور مجاہدین کے لئے مدد مانگیں۔اشعار کی صورت میں کفر وشرک ومشرکین کی مذمت اور ہجو بھی زبان سے جہاد میں شمار ہے۔الٖغرض جو مسلمان جہاد کے داعیہ سے خالی الذہن ہے اسے اپنے ایمان کی فکر کرنی چاہیے۔"}],[2505,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں «إلا تنفروا يعذبكم عذابا أليما» \"اگر تم جہاد کے لیے نہیں نکلو گے تو اللہ تمہیں عذاب دے گا\" (سورۃ التوبہ: ۳۹) اور «ما كان لأهل المدينة» سے «يعملون» \"مدینہ کے رہنے والوں کو اور جو دیہاتی ان کے گرد و پیش ہیں ان کو یہ زیبا نہ تھا کہ رسول اللہ صلی اللہ علیہ وسلم کو چھوڑ کر پیچھے رہ جائیں\" (سورۃ التوبہ: ۱۰) کو بعد والی آیت «وما كان المؤمنون لينفروا كافة» \"مناسب نہیں کہ مسلمان سب کے سب جہاد کے لیے نکل پڑیں\" (سورۃ التوبہ: ۱۲۲) نے منسوخ کر دیا ہے۔","حسن",{"u2":"سیدنا ابن عباس رضی اللہ عنہ سے مروی ہے کہ سورۃ التوبہ (کی آیت نمبر 39) ” اگر تم جہاد کے لیے نہ نکلو گے تو اللہ تعالیٰ تمہیں درد ناک عذاب سے دوچار کر دے گا “۔ اور (آیات 120 اور 121) ” اہل مدینہ اور ان کے اردگرد کے دیہاتیوں کو روا نہیں (کہ اللہ کے رسول سے پیچھے رہیں اور نہ یہ کہ اپنی جانوں کو رسول کی جان سے پیاری سمجھیں۔۔۔۔) ان آیات کو اس کے بعد والی آیت (نمبر 122) نے منسوخ کر دیا ہے۔ جس میں ہے ” اور مومنوں کو لائق نہیں کہ یہ سب کے سب جہاد کے لیے نکل کھڑے ہوں۔ (ایسا کیوں نہ ہوا کہ ہر جماعت میں سے ایک گروہ نکلتا تاکہ وہ باقی دین میں سمجھ حاصل کرتے اور جب یہ (جہاد سے) لوٹ کر آتے تو اپنی قوم کو بھی ڈراتے تاکہ وہ بھی متنبہ رہیں۔) “","f2":"1۔حضرت ابن عباس رضی اللہ تعالیٰ عنہ کی تفسیر کا مفہوم یہ ہے کہ ہرجہاد میں تمام مسلمانوں کا نکلنا منسوخ ہے جبکہ دیگر مفسرین کا کہنا یہ ہے کہ یہ آیات محکم ہیں۔اور جہاد میں احوال وظروف کا خیال ر کھنا چاہیے۔اور ایک جماعت کو دارالسلام میں بھی لازما رکنا چاہیے تاکہ مرکز بالکل خالی نہ رہ جائے۔2۔آیت نمبر 122 سے یہ مسئلہ بالکل واضح ہوتا ہے کہ جہاد میں عملا مشغول ہوکر تفقہ فی الدین حاصل ہوتا ہے۔وہ عام حالات میں حاصل نہیں ہوتا۔"}],[2506,"نجدہ بن نفیع کہتے ہیں کہ میں نے آیت کریمہ «إلا تنفروا يعذبكم عذابا أليما» \"اگر تم جہاد کے لیے نہیں نکلو گے تو اللہ تمہیں عذاب دے گا\" (سورۃ التوبہ: ۳۹) کے سلسلہ میں ابن عباس رضی اللہ عنہما سے پوچھا تو انہوں نے کہا: عذاب یہی تھا کہ بارش ان سے روک لی گئی (اور وہ مبتلائے قحط ہو گئے) ۔","ضعیف",{"u2":"نجدہ بن نفیع کہتے ہیں کہ میں نے سیدنا ابن عباس رضی اللہ عنہ سے سورۃ التوبہ (کی آیت 39) کی تفسیر پوچھی، جس میں ہے کہ ” اگر تم جہاد کے لیے نہ نکلو گے تو اللہ تمہیں درد ناک عذاب سے دوچار کر دے گا۔ “ انہوں نے فرمایا: ان سے بارش روک لی گئی اور یہی ان کا عذاب تھا۔"}],[2507,"زید بن ثابت رضی اللہ عنہ کہتے ہیں کہ میں رسول اللہ صلی اللہ علیہ وسلم کے پہلو میں تھا تو آپ کو سکینت نے ڈھانپ لیا (یعنی وحی اترنے لگی) (اسی دوران) رسول اللہ صلی اللہ علیہ وسلم کی ران میری ران پر پڑ گئی تو کوئی بھی چیز مجھے آپ کی ران سے زیادہ بوجھل محسوس نہیں ہوئی، پھر آپ صلی اللہ علیہ وسلم سے وحی کی کیفیت ختم ہوئی تو آپ نے فرمایا: \"لکھو\"، میں نے شانہ (کی ایک ہڈی) پر «لا يستوي القاعدون من المؤمنين والمجاهدون في سبيل الله» \"اپنی جانوں اور مالوں سے اللہ کی راہ میں جہاد کرنے والے مومن اور بغیر عذر کے بیٹھ رہنے والے مومن برابر نہیں\" (سورۃ النساء: ۹۵) آخر آیت تک لکھ لیا، عبداللہ بن ام مکتوم رضی اللہ عنہ (ایک نابینا شخص تھے) نے جب مجاہدین کی فضیلت سنی تو کھڑے ہو کر کہا: اللہ کے رسول! مومنوں میں سے جو جہاد کی طاقت نہیں رکھتا اس کا کیا حال ہے؟ جب انہوں نے اپنی بات پوری کر لی تو رسول اللہ صلی اللہ علیہ وسلم کو پھر سکینت نے ڈھانپ لیا (وحی اترنے لگی)، آپ صلی اللہ علیہ وسلم کی ران میری ران پر پڑی تو میں نے اس کا بھاری پن پھر دوسری بار محسوس کیا جس طرح پہلی بار محسوس کیا تھا، آپ صلی اللہ علیہ وسلم سے وحی کی جب کیفیت ختم ہوئی تو آپ نے فرمایا: \"زید! پڑھو\"، تو میں نے «لا يستوي القاعدون من المؤمنين» پوری آیت پڑھی، تو رسول اللہ صلی اللہ علیہ وسلم نے: «غير أولي الضرر» کا اضافہ فرمایا، زید کہتے ہیں: تو «غير أولي الضرر» کو اللہ نے الگ سے نازل کیا، میں نے اس کو اس کے ساتھ شامل کر دیا، اللہ کی قسم! گویا میں شانہ کے دراز کو دیکھ رہا ہوں جہاں میں نے اسے شامل کیا تھا۔","حسن صحیح",{"u2":"سیدنا زید بن ثابت رضی اللہ عنہ بیان کرتے ہیں کہ میں رسول اللہ صلی اللہ علیہ وسلم کے پہلو میں بیٹھا ہوا تھا کہ آپ صلی اللہ علیہ وسلم کو سکینت نے ڈھانپ لیا (وحی کا نزول شروع ہو گیا) اور رسول اللہ صلی اللہ علیہ وسلم کی ران میری ران پر آ گئی، مجھے آپ صلی اللہ علیہ وسلم کی ران سے جو بوجھ محسوس ہوا کسی اور چیز سے محسوس نہیں ہوا۔ جب آپ صلی اللہ علیہ وسلم سے یہ کیفیت دور ہوئی تو آپ صلی اللہ علیہ وسلم نے فرمایا ” لکھو۔ “ چنانچہ میں نے شانے کی ہڈی پر لکھا: «لا يستوي القاعدون ***» (آخر آیت تک) ” اللہ کی راہ میں جہاد کرنے والے مومنین اور بیٹھ رہنے والے برابر نہیں ہو سکتے۔۔۔ “ ابن ام مکتوم جو نابینا صحابی تھے انہوں نے جب مجاہدین کی یہ فضیلت سنی تو کھڑے ہوئے اور کہا: اے اللہ کے رسول! مومنین میں سے ایسے شخص کے بارے میں کیا ارشاد ہے جو جہاد کی استطاعت نہ رکھتا ہو؟ انہوں نے جب اپنی بات پوری کی تو رسول اللہ صلی اللہ علیہ وسلم کو سکینت نے ڈھانپ لیا اور آپ کی ران میری ران پر آ گئی، اور دوسری بار بھی میں نے اسی طرح کا بوجھ محسوس کیا جو پہلے محسوس کیا تھا۔ پھر جب آپ سے یہ کیفیت دور ہوئی تو آپ نے فرمایا ” اے زید! پڑھو۔ “ میں نے پڑھا: «لا يستوي القاعدون من المؤمنين» تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا «غير أولي الضرر» ” سوائے ان کے جنہیں کوئی عذر ہو۔ “ اور باقی آیت اسی طرح رہی۔ سیدنا زید رضی اللہ عنہ فرماتے ہیں کہ «غير أولي الضرر» کے لفظ اللہ نے علیحدہ سے نازل فرمائے اور میں نے ان کو ان کی جگہ پر لکھ دیا۔ قسم اس ذات کی جس کے ہاتھ میں میری جان ہے! گویا میں شانے کی ہڈی کے اس درز کو دیکھ رہا ہوں جہاں میں نے اس کو ملایا تھا۔","f2":"1۔مریض۔نابینا۔اپاہج۔یا دیگر شرعی عذر کی بنا ء پر اگر کوئی جہاد سے پیچھے رہ جائے۔تو مباح ہے لیکن جب نفیر عام کا حکم ہو تو بلا عذر پیچھے رہنا کسی طرح روا نہیں۔2۔نزول وحی کے وقت رسول اللہ صلی اللہ علیہ وسلم پر انتہائی بوجھ پڑتا تھا۔ حتیٰ کے سخت سردی میں بھی آپ صلی اللہ علیہ وسلم کو پسینہ آجاتا تھا۔اور اگر آپ اونٹنی پر ہوتے تو وہ بھی ٹک کرکھڑی ہوجاتی تھی۔اور چل نہ سکتی تھی۔3۔قرآن مجید جس قدر اترتا تھا نبی کریم صلی اللہ علیہ وسلم اس کی کتابت کروادیاکرتے تھے۔البتد ابتداء احادیث کے لکھنے کی عام اجازت نہ تھی۔سوائے چند ایک صحابہ کرامرضوان اللہ عنہم اجمعین کےزیادہ وثائق جو آپ نے بالخصوص لکھوائے۔"}],[2508,"انس بن مالک رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"تم مدینہ میں کچھ ایسے لوگوں کو چھوڑ کر آئے کہ تم کوئی قدم نہیں چلے یا کچھ خرچ نہیں کیا یا کوئی وادی طے نہیں کی مگر وہ تمہارے ساتھ رہے\"، صحابہ نے عرض کیا: اللہ کے رسول! وہ ہمارے ہمراہ کیسے ہو سکتے ہیں جب کہ وہ مدینہ میں ہیں؟ آپ صلی اللہ علیہ وسلم نے فرمایا: \"انہیں عذر نے روک رکھا ہے\"۔","صحیح",{"u2":"سیدنا انس بن مالک رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” بلاشبہ تم لوگ مدینے میں ایسے لوگوں کو چھوڑ آئے ہو کہ جو سفر بھی تم کرتے ہو یا کوئی خرچ کرتے ہو یا کوئی وادی طے کرتے ہو تو وہ (اجر و ثواب میں) تمہارے ساتھ ہوتے ہیں۔“ صحابہ نے کہا: اے اللہ کے رسول! وہ ہمارے ساتھ کس طرح ہوتے ہیں حالانکہ وہ مدینے میں ہیں؟ آپ صلی اللہ علیہ وسلم نے فرمایا ” ان کو عذر اور مجبوری نے روکے رکھا ہے۔ “","f2":"حسن نیت اور اخلاص کی بنا پر ایک معذور انسان بھی وہ درجات حاصل کرلیتا ہے۔جوایک مجاہد اور عامل حاصل کرتاہے۔"}],[2509,"زید بن خالد جہنی رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جس نے اللہ کے راستے میں جہاد کرنے والے کے لیے سامان جہاد فراہم کیا اس نے جہاد کیا اور جس نے مجاہد کے اہل و عیال کی اچھی طرح خبرگیری کی اس نے جہاد کیا\"۔","صحیح",{"u2":"سیدنا زید بن خالد جہنی رضی اللہ عنہ کا بیان ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” جس کسی نے مجاہد کو سامان جہاد دیا، تو بلاشبہ اس نے جہاد کیا، اور جو مجاہد کے اہل خانہ کی بحسن و خوبی خبرگیری کرتا رہا، تو بلاشبہ اس نے جہاد کیا۔ “"}],[2510,"ابو سعید خدری رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے بنو لحیان کی طرف ایک لشکر بھیجا اور فرمایا: \"ہر دو آدمی میں سے ایک آدمی نکل کھڑا ہو\"، اور پھر خانہ نشینوں سے فرمایا: \"تم میں جو کوئی مجاہد کے اہل و عیال اور مال کی اچھی طرح خبرگیری کرے گا تو اسے جہاد کے لیے نکلنے والے کا نصف ثواب ملے گا\"۔","صحیح",{"u2":"سیدنا ابو سعید خدری رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے بنولحیان کی جانب ایک مہم بھیجی اور فرمایا ” ہر دو آدمیوں میں سے ایک جہاد کے لیے چلا جائے (آدھے لوگ جہاد کے لیے جائیں اور آدھے رکے رہیں۔) “ پھر آپ صلی اللہ علیہ وسلم نے رکنے والوں سے فرمایا ” جو تم میں سے مجاہد کے گھر والوں کی عمدہ طور پر خبرگیری کرے گا اس کو جانے والے کا آدھا ثواب ہے۔ “","f2":"مذکورہ بالا حدیث سے یہ سمجھا گیا ہے کہ جو شخص مجاہد کے اہل خانہ کی عمدہ طور سے خبر گیری کرے تو ا س کو بھی مجاہد کی طرح پورا ثواب ملتاہے۔اور اس دوسری حدیث میں آدھے ثواب کا ذکر آیا ہے۔تو ان میں تطبیق اس طرح ہے۔ حافظ ابن حجر فرماتے ہیں۔اگر ان دونوں افراد کے مجموعی ثواب کو آدھا آدھا کیاجائے تو دونوں کےلئے برابر ہوجاتاہے۔ اور اس طرح تعارض نہیں رہتا۔مگر راقم مترجم کا خیال ہے۔کہ اگر پیچھے رہنے والے نے اس رکنے کے عمل کو ترجیح دی ہو تو اسے آدھا ثواب ملے گا۔ لیکن اگر یہ دونوں ہی قتال میں شریک ہونے کے شائق ہوں اورامیر کسی ایک کو قتال کے لئے منتخب کرے۔اور دوسرے کو اس کے اہل خانہ کی خدمت کا پابند کرے۔تو اس طرح یہ دونوں ہی ثواب میں برابر ہوں گے۔واللہ اعلم"}],[2511,"ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ انہوں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا: \"آدمی میں پائی جانے والی سب سے بری چیز انتہا کو پہنچی ہوئی بخیلی اور سخت بزدلی ہے\"۔","صحیح",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو سنا آپ صلی اللہ علیہ وسلم فرماتے تھے ” انسان میں دو وصف بہت برے ہوتے ہیں۔ ایک یہ کہ حریص و بخیل ہونے کے ساتھ ساتھ دل کا کچا ہو۔ دوسرا یہ کہ اتنا بزدل ہو کہ گویا دل ہی نکل جائے گا۔ “","f2":"کسی انسان میں حرص اور بخل دونوں کیفتیں جمع ہوں۔تو اس کو (شح) کہتے ہیں۔(ھلح)کی وضاحت قرآن کریم میں یوں آئی ہے۔\n(إِنَّ الْإِنسَانَ خُلِقَ هَلُوعًا ﴿١٩﴾ إِذَا مَسَّهُ الشَّرُّ جَزُوعًا ﴿٢٠﴾ وَإِذَا مَسَّهُ الْخَيْرُ مَنُوعًا)(المعارج۔19۔21)\nبے شک آدمی جی کا بنا ہے کچا۔جب پہنچے اس کو بُرائی تو بے صبر اور جب پہنچے اس کو بھلائی تو نادہند"}],[2512,"اسلم ابوعمران کہتے ہیں کہ ہم مدینہ سے جہاد کے لیے چلے، ہم قسطنطنیہ کا ارادہ کر رہے تھے، اور جماعت (اسلامی لشکر) کے سردار عبدالرحمٰن بن خالد بن ولید تھے، اور رومی شہر (قسطنطنیہ) کی دیواروں سے اپنی پیٹھ لگائے ہوئے تھے ۱؎، تو ہم میں سے ایک دشمن پر چڑھ دوڑا تو لوگوں نے کہا: رکو، رکو، اللہ کے علاوہ کوئی معبود برحق نہیں، یہ تو اپنی جان ہلاکت میں ڈال رہا ہے، ابوایوب رضی اللہ عنہ نے کہا: یہ آیت تو ہم انصار کی جماعت کے بارے میں اتری، جب اللہ نے اپنے نبی کی مدد کی اور اسلام کو غلبہ عطا کیا تو ہم نے اپنے دلوں میں کہا (اب جہاد کی کیا ضرورت ہے) آؤ اپنے مالوں میں رہیں اور اس کی دیکھ بھال کریں، تب اللہ نے یہ آیت نازل فرمائی «وأنفقوا في سبيل الله ولا تلقوا بأيديكم إلى التهلكة» \"اللہ کے راستے میں خرچ کرو اور اپنے آپ کو ہلاکت میں نہ ڈالو\" (سورۃ البقرہ: ۱۹۵)اپنے آپ کو ہلاکت میں ڈالنا یہ ہے کہ ہم اپنے مالوں میں مصروف رہیں، ان کی فکر کریں اور جہاد چھوڑ دیں۔ ابوعمران کہتے ہیں: ابوایوب انصاری رضی اللہ عنہ ہمیشہ اللہ کی راہ میں جہاد کرتے رہے یہاں تک کہ قسطنطنیہ میں دفن ہوئے۔\n§وضاحت\n۱؎ : یعنی وہ جنگ کے لئے پوری طرح سے تیار تھے اور مسلمانوں کے نکلنے کے انتظار میں تھے۔","صحیح",{"u2":"جناب اسلم‘ابو عمران بیان کرتے ہیں کہ ہم لوگ مدینہ منورہ سے جہاد کے لیے روانہ ہوئے، ہم قسطنطنیہ (استنبول) جانا چاہتے تھے اور جناب عبدالرحمٰن بن خالد بن ولید ہمارے امیر جماعت تھے۔ رومی لوگ اپنی پشت فصیل شہر کی طرف کیے ہمارے مدمقابل تھے۔ مسلمانوں میں سے ایک شخص نے دشمن پر ہلہ بول دیا تو لوگوں نے کہا: رکو، ٹھہرو! «لا إله إلا الله» یہ شخص اپنے آپ کو ہلاکت میں ڈالتا ہے تو سیدنا ابوایوب انصاری رضی اللہ عنہ نے فرمایا کہ یہ آیت ہم انصاریوں ہی کے بارے میں نازل ہوئی تھی۔ جب اللہ ذوالجلال نے اپنے نبی کریم صلی اللہ علیہ وسلم کی نصرت فرمائی اور اسلام کو غالب کر دیا تو ہم نے کہا: چلو اب ذرا اپنے اموال و جائیداد میں رک جائیں اور ان کو درست کر لیں، تو اللہ تعالیٰ نے یہ آیت نازل فرمائی: ” اور اللہ کی راہ میں خرچ کرو اور اپنے آپ کو ہلاکت میں نہ ڈالو۔ “ ہلاکت میں ڈالنا یہ تھا کہ ہم اپنے مالوں میں رک جائیں، ان کی اصلاح میں مشغول ہو جائیں اور جہاد چھوڑ دیں۔ ابو عمران نے کہا: چنانچہ ابوایوب انصاری رضی اللہ عنہ اللہ کی راہ میں جہاد کرتے رہے، حتیٰ کہ قسطنطنیہ (استنبول) ہی میں دفن ہوئے۔","f2":"1۔قرآن مجید کو صحیح احادیث میں وارد شان نزول کی روشنی میں سمجھنا چاہیے اس سے صرف نظر کرنا قطعاً صحیح نہیں ہے۔مگر ہر ہر آیت کا شان نزول ثابت نہیں ہے۔2۔مندرجہ بالا تفصیل سے واضح ہوتا ہے کہ مشاغل دنیا میں انہماک اور جہاد سے اعراض ہی باعث ہلاکت ہے خواہ افراد اس کے مرتکب ہوں یا قومیں۔"}],[2513,"عقبہ بن عامر رضی اللہ عنہ کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا: \"اللہ ایک تیر سے تین افراد کو جنت میں داخل کرتا ہے: ایک اس کے بنانے والے کو جو ثواب کے ارادہ سے بنائے، دوسرے اس کے چلانے والے کو، اور تیسرے اٹھا کر دینے والے کو، تم تیر اندازی کرو اور سواری کرو، اور تمہارا تیر اندازی کرنا، مجھے سواری کرنے سے زیادہ پسند ہے، لہو و لعب میں سے صرف تین طرح کا لہو و لعب جائز ہے: ایک آدمی کا اپنے گھوڑے کو ادب سکھانا، دوسرے اپنی بیوی کے ساتھ کھیل کود کرنا، تیسرے اپنے تیر کمان سے تیر اندازی کرنا اور جس نے تیر اندازی سیکھنے کے بعد اس سے بیزار ہو کر اسے چھوڑ دیا، تو یہ ایک نعمت ہے جسے اس نے چھوڑ دیا\"، یا راوی نے کہا: \"جس کی اس نے ناشکری کی\" ۱؎۔\n§وضاحت\n۱؎ : یہ روایت سنداً تو ضعیف ہے مگر عقبہ ہی سے صحیح مسلم (امارۃ: ۵۲) میں ایک روایت کے الفاظ یہ ہیں: ’’ جس نے تیر اندازی جاننے کے بعد اسے چھوڑ دیا وہ ہم میں سے نہیں ہے‘‘، یا فرمایا: ’’اس نے نافرمانی کی‘‘، نیز اس حدیث سے تیراندازی کی فضیلت ثابت ہوتی ہے، اس طرح زمانے کے جتنے سامان جنگ ہیں ان کا سیکھنا اور حاصل کرنا اور اس کے لئے سفر کرنا جہاد میں داخل ہے۔","ضعیف",{"u2":"سیدنا عقبہ بن عامر رضی اللہ عنہ بیان کرتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا، آپ صلی اللہ علیہ وسلم فرماتے تھے ” اللہ عزوجل ایک تیر کی وجہ سے تین آدمیوں کو جنت میں داخل کرتا ہے۔ ایک اس کا بنانے والا، جو اپنی اس صنعت میں اجر و ثواب کا امیدوار ہو۔ دوسرا، تیر مارنے والا (جہاد میں) اور تیسرا وہ جو اسے تیر پکڑانے والا ہو (جو اس کا معاون ہو) تیر اندازی اور گھوڑ سواری سیکھو، تاہم مجھے گھوڑ سواری کی نسبت تیر اندازی (نشانہ بازی) زیادہ پسند ہے۔ (شریعت میں) کھیل تین ہی ہیں: ایک یہ کہ انسان اپنے گھوڑے کو سدھائے۔ دوسرا، یہ کہ انسان اپنی بیوی سے کھیلے۔ تیسرا، یہ کہ انسان اپنے تیر کمان سے تیر پھینکنے کی مشق کرتا رہے۔ جو شخص تیر اندازی سیکھنے کے بعد اس سے بیزار ہو کر اسے چھوڑ دے تو اس نے بلاشبہ ایک نعمت کو چھوڑ دیا۔ “ یا یوں فرمایا ” اس نے اس نعمت کی ناشکری کی۔ “","f2":"شیخ البانی کے نذدیک یہ روایت ضعیف ہے۔البتہ ہمارے فاضل محقق نے اسے حسن قراردیا ہے۔جس کی وجہ سے حدیث میں مذکورہ اعمال کی اباحت اور فضیلت ثابت ہے۔لہذا اگر کسی تفریح کا پروگرام ہو و انہی مذکورہ بالا تفریحات میں سے کسی کو ترجیح دی جائے تاکہ جسمانی قوت اور تفریح کے ساتھ ساتھ عند اللہ اجر وثواب کا بھی مستحق ٹھہرے۔"}],[2514,"عقبہ بن عامر جہنی رضی اللہ عنہ سے روایت ہے کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو منبر پر فرماتے ہوئے سنا: آپ آیت کریمہ«وأعدوا لهم ما استطعتم من قوة» \"تم ان کے مقابلہ کے لیے اپنی طاقت بھر قوت کی تیاری کرو\" (سورۃ الأنفال: ۶۰) پڑھ رہے تھے اور فرما رہے تھے: \"سن لو، قوت تیر اندازی ہی ہے، سن لو قوت تیر اندازی ہی ہے، سن لو قوت تیر اندازی ہی ہے\"۔","صحیح",{"u2":"سیدنا عقبہ بن عامر جہنی رضی اللہ عنہ سے روایت ہے، وہ کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو برسر منبر یہ کہتے ہوئے سنا: (آپ نے سورۃ الانفال کی آیت 60 پڑھی) ” ان کفار کے مقابلے میں جس قدر ہو سکے قوت بہم پہنچاؤ۔ “ (اس کی تشریح میں آپ نے فرمایا) ” خبردار! تیر اندازی ہی قوت ہے۔ خبردار! تیر اندازی ہی قوت ہے۔ خبردار! تیر اندازی ہی قوت ہے۔ “","f2":"(رمی)کے معنی ہیں۔کسی چیز کو پھینک کر مارنا تیر اندزی کا یہ بیان بطور رمز کے ہے ورنہ مطلوب یہ ہے کہ بحیثیت مسلمان مسلمان کے لئے رائج الوقت اسلحہ کے استعمال کی تربیت حاصل کرنا ضروری ہے۔ اور چلا کرمارنے والے اسلحے ہی سب سے اہم ترین ہیں۔"}],[2515,"معاذ بن جبل رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جہاد دو طرح کے ہیں: رہا وہ شخص جس نے اللہ کی رضا مندی چاہی، امام کی اطاعت کی، اچھے سے اچھا مال خرچ کیا، ساتھی کے ساتھ نرمی اور محبت کی، اور جھگڑے فساد سے دور رہا تو اس کا سونا اور اس کا جاگنا سب باعث اجر ہے، اور جس نے اپنی بڑائی کے اظہار، دکھاوے اور شہرت طلبی کے لیے جہاد کیا، امام کی نافرمانی کی، اور زمین میں فساد مچایا تو (اسے ثواب کیا ملنا) وہ تو برابر برابر بھی نہیں لوٹا ۱؎\"۔\n§وضاحت\n۱؎ : یعنی ایسے جہاد میں اگر گناہ سے بچ جائے تو یہی غنیمت ہے، ثواب کا کیا ذکر۔","حسن",{"u2":"سیدنا معاذ بن جبل رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” جہاد دو قسم کا ہے: جس نے اللہ کی رضا چاہی، امام کی اطاعت کی، عمدہ مال خرچ کیا، اپنے شریک کار سے نرمی کا برتاؤ کیا اور فساد سے بچتا رہا، تو بلاشبہ ایسے مجاہد کا سونا اور جاگنا سبھی اجر و ثواب کا کام ہے لیکن جس نے فخر، دکھلاوے اور شہرت کی نیت رکھی، امام کی نافرمانی کی اور زمین میں فساد کیا تو بلاشبہ ایسا آدمی (ثواب تو کیا) برابری کے ساتھ بھی نہیں پلٹا (گناہ سے بچ آنا بھی مشکل ہے)۔ “"}],[2516,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ ایک شخص نے کہا: اللہ کے رسول! ایک شخص اللہ کی راہ میں جہاد کا ارادہ رکھتا ہے اور وہ دنیاوی مال و منال چاہتا ہے؟ تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اس کے لیے کوئی اجر و ثواب نہیں\"، لوگوں نے اسے بڑی بات سمجھی اور اس شخص سے کہا: رسول اللہ صلی اللہ علیہ وسلم سے پھر پوچھو، شاید تم انہیں نہ سمجھا سکے ہو، اس شخص نے کہا: اللہ کے رسول! ایک شخص اللہ کی راہ میں جہاد کا ارادہ رکھتا ہے اور وہ دنیاوی مال و اسباب چاہتا ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا: \"اس کے لیے کوئی اجر و ثواب نہیں\"، لوگوں نے اس شخص سے کہا: رسول اللہ صلی اللہ علیہ وسلم سے پھر پوچھو، اس نے آپ سے تیسری بار پوچھا، تو آپ صلی اللہ علیہ وسلم نے پھر اس سے فرمایا: \"اس کے لیے کوئی اجر و ثواب نہیں\"۔","حسن",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ سے مروی ہے کہ ایک شخص نے کہا: اے اللہ کے رسول! ایک انسان جہاد کے لیے نکلتا ہے مگر وہ دنیا کا مال چاہتا ہے؟ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” اس کے لیے کوئی اجر نہیں۔ “ لوگوں نے اس فرمان کو بہت گراں جانا، انہوں نے اس آدمی سے کہا: دوبارہ پوچھو، شاید تم اپنی بات واضح نہیں کر سکے ہو۔ اس نے کہا: اے اللہ کے رسول! ایک انسان جہاد فی سبیل اللہ کے لیے نکلتا ہے اور وہ دنیا کا مال چاہتا ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا ” اس کے لیے کوئی ثواب نہیں۔ “ لوگوں نے اس آدمی سے کہا: رسول اللہ صلی اللہ علیہ وسلم سے پھر پوچھو۔ اس نے آپ صلی اللہ علیہ وسلم سے تیسری بار پوچھا تو بھی آپ صلی اللہ علیہ وسلم نے اسے یہ فرمایا ” اس کو کوئی ثواب نہیں۔ “","f2":"اگر مجاہد کی نیت بنیادی طور پر ریا کاری اور حصول مال کی ہو تو اس کا سب عمل باطل ہے۔اس کے لئے کوئی اجر نہیں۔لیکن اگر اصل اور بنیادی نیت جہاد اور اللہ کا کلمہ بلند کرنا اور ا س کے ساتھ حصول مال جیسی نیت بھی خلط ملط ہوجائے تو اس سے اجر میں کمی آجاتی ہے۔عمل باطل نہیں ہوتا۔جیسے کہ سابقہ حدیث 2497 میں گزرا ہے۔کہ مجاہدین کو اگر غنیمت مل جائے تو اپنا وہ دو تہائی اجر اس دنیا میں ہی حاصل کرلیتے ہیں۔ورنہ ان کا سارا اجر محفوظ رہتا ہے۔امام احمد فرماتے ہیں کہ جہاد میں تاجر مزدور اور کرائے پر کام کرنے والے افراد کا اجر ان کی اپنی اپنی نیت کی مقدار پر ہوتا ہے نیت اور اخلاص کا معاملہ انتہائی مشکل اور توجہ طلب ہوتا ہے۔اس مسئلہ میں جامع العلوم والحکم (لابن رجب حنبلی) میں شرح حدیث۔انما الاعمال بالنیات بار بار پڑھنے کے لائق ہے۔"}],[2517,"ابوموسی رضی اللہ عنہ کہتے ہیں کہ ایک دیہاتی رسول اللہ صلی اللہ علیہ وسلم کے پاس آیا اور اس نے عرض کیا: کوئی شہرت کے لیے جہاد کرتا ہے کوئی جہاد کرتا ہے تاکہ اس کی تعریف کی جائے، کوئی اس لیے جہاد کرتا ہے تاکہ مال غنیمت پائے اور کوئی اس لیے جہاد کرتا ہے تاکہ اس مرتبہ کا اظہار ہو سکے، تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جس نے صرف اس لیے جہاد کیا تاکہ اللہ کا کلمہ سربلند رہے تو وہی اصل مجاہد ہے\"۔","صحیح",{"u2":"سیدنا ابوموسیٰ اشعری رضی اللہ عنہ سے منقول ہے کہ ایک دیہاتی رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں آیا اور کہا: ایک آدمی قتال کرتا ہے شہرت کے لیے، کوئی قتال کرتا ہے تعریف کے لیے اور کوئی غنیمت کے لیے اور کوئی مرتبہ (بہادری و شجاعت) دکھانے کے لیے؟ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” جو شخص اس غرض سے لڑے کہ اللہ کا کلمہ بلند ہو تو وہی اللہ کی راہ میں ہے۔ “"}],[2518,"عمرو کہتے ہیں کہ میں نے اپنے والد وائل سے ایک حدیث سنی جو مجھے پسند آئی، پھر راوی نے اسی مفہوم کی حدیث ذکر کی۔","صحیح",{"u2":"عمرو بن مرہ نے کہا کہ میں نے ابووائل سے حدیث سنی جو مجھے بہت پسند آئی۔ اور مذکورہ بالا حدیث کے ہم معنی بیان کیا۔","f2":"اگر مجاہد کی اصل نیت اللہ کا کلمہ بلند کرنا ہوتو دیگر اغراض سے اس کے اجر میں کمی آجاتی ہے امام بخاری نے اس حدیث کو اس عنوان کے تحت درج کیا ہے۔(باب من قاتل للمغنهم هل ينقص من اجره)(صحیح البخاری فرض الخمس باب 10) کیا جو شخص غنیمت کے لئے قتال کرے اس کا اجر کم ہو جاتا ہے۔"}],[2519,"عبداللہ بن عمرو رضی اللہ عنہما کہتے ہیں کہ انہوں نے کہا: اللہ کے رسول! مجھے جہاد اور غزوہ کے بارے میں بتائیے، آپ صلی اللہ علیہ وسلم نے فرمایا: \"اے عبداللہ بن عمرو! اگر تم صبر کے ساتھ ثواب کی نیت سے جہاد کرو گے تو اللہ تعالی تمہیں صابر اور محتسب (ثواب کی نیت رکھنے والا) بنا کر اٹھائے گا، اور اگر تم ریاکاری اور فخر کے اظہار کے لیے جہاد کرو گے تو اللہ تمہیں ریا کار اور فخر کرنے والا بنا کر اٹھائے گا، اے عبداللہ بن عمرو! تم جس حال میں بھی لڑو یا شہید ہو اللہ تمہیں اسی حال پر اٹھائے گا\"۔","ضعیف",{"u2":"سیدنا عبداللہ بن عمرو رضی اللہ عنہ سے مروی ہے کہ (میں نے کہا) اے اللہ کے رسول! مجھے جہاد اور غزوے کے متعلق ارشاد فرمائیں۔ آپ صلی اللہ علیہ وسلم نے فرمایا ” اے عبداللہ بن عمرو! اگر تم صبر کے ساتھ اور اجر کی نیت سے قتال کرو تو اللہ تعالیٰ تمہیں صبر کرنے والوں اور اجر کے طلب گاروں میں اٹھائے گا اور اگر تم دکھلاوے اور مال جمع کرنے کی غرض سے قتال کرو تو اللہ تعالیٰ تمہیں ریا کار اور مال جمع کرنے والوں میں اٹھائے گا، اے عبداللہ بن عمرو! جس حال (اور نیت) میں بھی تم نے لڑائی کی (جہاد کیا) یا تمہیں قتل کر دیا گیا تو اللہ تمہیں اسی حالت پر اٹھائے گا۔ “","f2":"ہرنیک کام کے لئے اخلاص اور حسن نیت ضروری ہے۔اس لئے جہاد وقتال ہویا دیگر اعمال حسنہ ہر مسلمان کو تمام اعمال میں اپنی نیت کا جائز ہ لیتے رہنا چاہیے۔اس روایت کوشیخ البانی نے ضعیف قرار دیا ہے۔"}],[2520,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جب تمہارے بھائی احد کے دن شہید کئے گئے تو اللہ نے ان کی روحوں کو سبز چڑیوں کے پیٹ میں رکھ دیا، جو جنت کی نہروں پر پھرتی ہیں، اس کے میوے کھاتی ہیں اور عرش کے سایہ میں معلق سونے کی قندیلوں میں بسیرا کرتی ہیں، جب ان روحوں نے اپنے کھانے، پینے اور سونے کی خوشی حاصل کر لی، تو وہ کہنے لگیں: کون ہے جو ہمارے بھائیوں کو ہمارے بارے میں یہ خبر پہنچا دے کہ ہم جنت میں زندہ ہیں اور روزی دیئے جاتے ہیں تاکہ وہ جہاد سے بے رغبتی نہ کریں اور لڑائی کے وقت سستی نہ کریں تو اللہ تعالی نے فرمایا: \"میں تمہاری جانب سے انہیں یہ خبر پہنچائوں گا\"، راوی کہتے ہیں: تو اللہ تعالی نے یہ آیت کریمہ «ولا تحسبن الذين قتلوا في سبيل الله أمواتا» \"جو اللہ کے راستے میں شہید کر دئیے گئے انہیں مردہ نہ سمجھو\" (سورۃ آل عمران: ۱۶۹) اخیر آیت تک نازل فرمائی۔","حسن",{"u2":"سیدنا ابن عباس رضی اللہ عنہ کا بیان ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” جب تمہارے بھائی احد میں شہید کر دیے گئے تو اللہ تعالیٰ نے ان کی روحوں کو سبز رنگ کے پرندوں میں کر دیا جو جنت کی نہروں پر آتے ہیں، وہاں کے پھل کھاتے ہیں اور پھر سونے کی قندیلوں میں لوٹ جاتے ہیں جو عرش کے سائے میں لٹک رہی ہیں۔ جب انہوں نے وہاں کے کھانے پینے اور آرام و راحت کے مزے دیکھے تو کہا: کون ہے جو ہمارا یہ پیغام ہمارے بھائیوں تک پہنچا دے کہ ہم جنت میں زندہ ہیں، ہمیں رزق دیا جاتا ہے تاکہ وہ جہاد سے بے رغبت نہ ہو جائیں اور لڑائی میں بزدلی نہ دکھائیں۔ چنانچہ اللہ تعالیٰ نے یہ آیت نازل فر دی: «ولا تحسبن الذين قتلوا في سبيل الله أمواتا» ” وہ لوگ جو اللہ کی راہ میں قتل ہوئے ان کے بارے میں یہ خیال ہرگز نہ کیجئیے کہ وہ مردہ ہیں بلکہ وہ زندہ ہیں اپنے رب کے پاس رزق دیے جاتے ہیں۔ “","f2":"شہدا کے اس اعزازواکرام میں مسلمانوں کو ترغیب وتشویق ہے کہ اللہ کا کلمہ بلند کرنے میں جان کی بازی لگانے سے دریغ نہ کریں۔2۔شہداء کی زندگی کو دنیا کی اس زندگی پر قیاس نہیں کیا جاسکتا۔بلکہ سورہ بقرہ میں صراحت ہے۔کہ ان کی زندگی کو تم لوگ نہیں سمجھ سکتے۔اور بعد از محشر انھیں نہایت اعزازو اکرام سے جنت میں داخل کیاجائے گا۔3۔محمد رسول اللہ صلی اللہ علیہ وسلم ان شہداء سے مراتب میں افضل واعلیٰ ہیں۔لہذا آپ کی برزخی زندگی کو بدرجہ اولیٰ نہیں سمجھا جا سکتا۔"}],[2521,"حسناء بنت معاویہ کے چچا رضی اللہ عنہ کہتے ہیں کہ میں نے نبی اکرم صلی اللہ علیہ وسلم سے پوچھا: جنت میں کون ہو گا؟ آپ نے فرمایا:\"نبی جنت میں ہوں گے، شہید جنت میں ہوں گے، (نابالغ) بچے اور زندہ درگور کئے گئے بچے جنت میں ہوں گے\"۔","صحیح",{"u2":"حسناء بنت معاویہ صریمیہ بیان کرتی ہیں کہ ہم سے ہمارے چچا (اسلم بن سلیم رضی اللہ عنہ) نے بیان کیا، انہوں نے کہا: میں نے نبی کریم صلی اللہ علیہ وسلم سے عرض کیا کہ جنت میں کون ہو گا؟ آپ صلی اللہ علیہ وسلم نے فرمایا ” نبی جنت میں ہوں گے، شہید جنت میں جائے گا، چھوٹا بچہ جنت میں جائے گا اور زندہ دفن کیا گیا بچہ جنت میں جائے گا۔ “","f2":"1۔ چھوٹے بچے جو نابالغی کی عمر میں فوت ہوگئے ہوں۔اس میں وہ بھی شامل ہیں جن کی پیدائش نامکمل رہی اور ساقط ہوگئے ہوں۔البتہ کافروں اور مشرکوں کے بچوں کے بارے میں سب سے زیادہ صحیح قول یہی ہے کہ جب کفار کے بچے سن تمیز سے پہلے فوت ہوجایئں۔اور ان کے والد کافر ہوں۔تو دنیا میں ان کا حکم کافروں کا ہوگا کہ انہیں غسل دیا جائے گا۔ نہ کفن دیا جائےگا نہ جنازہ پڑھا جائے گا۔اور نہ انہیں مسلمانوں کے ساتھ دفن کیا جائےگا۔کیونکہ وہ اپنے والدین کے ساتھ کافر ہی ہیں۔ باقی رہا آخرت میں ان کا حال تو یہ اللہ بہتر جانتا ہے کہ اگر وہ بڑے ہوتے تودنیا میں کس طرح کے عمل کرتے۔؟ صحیح حدیث میں ہے کہ رسول اللہ صلی اللہ علیہ وسلم سے جب مشرکوں کے بچوں کے بارے میں دریافت کیا گیا تو آپ صلی اللہ علیہ وسلم نے فرمایا! اللہ تعالیٰ زیادہ بہتر جانتا ہے۔کہ وہ کیا عمل کرنے والے تھے (صحیح البخاری القدر باب اللہ اعلم بما کانو عاملین حدیث 6597)\nبعض اہل علم کا قول ہےکہ ان کے بارے میں اللہ تعالیٰ کا علم قیامت کے دن ظاہر ہوگا۔ اور ان کا بھی اہل فترت کی طرح امتھان ہوگا۔ اگر انہوں نے اللہ کے حکم کی فرمانبرداری کی تو جنت میں داخل ہوں گے۔اوراگر نافرمانی کی تو جہنم رسید ہو ں گے۔صحیح احادیث سے ثابت ہے۔مثلا کفار اور مشرکین کے بچے ان کا بھی امتحان ہوگا۔کیونکہ ارشاد باری تعالیٰ ہے۔(وَمَا كُنَّا مُعَذِّبِينَ حَتَّىٰ نَبْعَثَ رَسُولًا)(بنی اسرائیل 17/15) اور جب تک ہم پیغمبر علیہ السلام نہ بھیجیں ہم عذاب نہیں دیا کرتے اہل فترت کے بارے میں سب سے زیادہ صحیح قول یہی ہے۔شیخ الاسلام امام ابن تیمیہ اور امام ابن قیم نے اسی کو اختیار کیا ہے۔(تفصیل کےلئے ملاحظہ ہو۔فتاویٰ ابن تیمیہ 24/372۔373)2۔عرب کے بعض قبائل عار کی بناء پراپنی بیٹیوں کودفن کردیتے تھے۔ اور یہ بھی آتا ہے کہ بعض فقر فاقہ کی صورت میں بیٹوں کے ساتھ بھی ایسے ہی کرتے تھے۔قرآن مجید نے اس کا ذکر یوں کیا ہے۔\n(وَإِذَا الْمَوْءُودَةُ سُئِلَتْ ﴿٨﴾ بِأَيِّ ذَنبٍ قُتِلَتْ)(التکویر۔8۔9) جب زندہ درگور کی گئی لڑکی سے پوچھا جائے گا۔کہ کس گناہ کی پاداش میں اسے قتل کیا گیا؟"}],[2522,"نمران بن عتبہ ذماری کہتے ہیں: ہم ام الدرداء رضی اللہ عنہا کے پاس گئے اور ہم یتیم تھے، انہوں نے کہا: خوش ہو جاؤ کیونکہ میں نے ابو الدرداء رضی اللہ عنہ کو کہتے ہوئے سنا ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"شہید کی شفاعت اس کے کنبے کے ستر افراد کے لیے قبول کی جائے گی\"۔ ابوداؤد کہتے ہیں: (ولید بن رباح کے بجائے) صحیح رباح بن ولید ہے۔","صحیح",{"u2":"جناب نمران بن عتبہ ذماری بیان کرتے ہیں کہ ہم ام الدرداء (صغر) کے ہاں گئے اور ہم یتیم تھے تو انہوں نے کہا: تمہیں بشارت ہو! میں نے (اپنے شوہر) ابوالدرداء رضی اللہ عنہ سے سنا، وہ کہتے تھے رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” شہید کی سفارش اپنے گھرانے کے ستر افراد کے حق میں قبول کی جائے گی۔ “ امام ابوداؤد رضی اللہ عنہ فرماتے ہیں کہ اس سند میں (ولید بن رباح الذماری صحیح نہیں بلکہ) رباح بن ولید صحیح ہے۔","f2":"یہ روایت شیخ البانی کے نزدیک صحیح ہے۔اس سفارش کا مستحق بننے کےلئے عقیدہ توحید سنت کاحامل ہونا انتہائی ضروری ہے۔کیونکہ مشرک کےلئے قطعا ً بخشش نہیں ہے۔اور جنت اس کے لئے حرام ہے۔فرمان باری تعالیٰ ہے۔\n(إِنَّ اللَّـهَ لَا يَغْفِرُ أَن يُشْرَكَ بِهِ وَيَغْفِرُ مَا دُونَ ذَٰلِكَ لِمَن يَشَاءُ ۚ)(النساء۔48) بلاشبہ اللہ تعالیٰ اس بات کو معاف نہیں فرمائے گا۔کہ اس کے ساتھ کسی کوشریک بنایا جائے علاوہ ازیں جسے چایے گا معاف فرمادے گا۔ اور دوسرے مقام پر فرمایا۔\n(اِنَّهُ مَن يُشْرِكْ بِاللَّـهِ فَقَدْ حَرَّمَ اللَّـهُ عَلَيْهِ الْجَنَّةَ وَمَأْوَاهُ النَّار)(المائدہ۔72)\nبلاشبہ جس نے اللہ کے ساتھ شرک کیا بلا شبہ اللہ نے اس پر جنت کو حرام کردیا ہے اور اس کا ٹھکانہ آگ ہے۔"}],[2523,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ جب نجاشی کا انتقال ہو گیا تو ہم کہا کرتے تھے کہ ان کی قبر پر ہمیشہ روشنی دکھائی دیتی ہے۔","ضعیف",{"u2":"ام المؤمنین سیدہ عائشہ رضی اللہ عنہا ا بیان کرتی ہیں کہ جب نجاشی رضی اللہ عنہ کی وفات ہوئی تو ہم لوگ کہا کرتے تھے کہ اس کی قبر پر نور دکھائی دیتا ہے۔ ابوسعید نے ہم سے کہا: احمد بن عبدالجبار نے ہمیں بیان کیا کہ ہم کو یزید بن بکیر نے ابن اسحاق سے اسی کی مانند روایت کیا۔","f2":"اس روایت کو ہمارے فاضل محقق نے حسن قرار دیا ہے۔لیکن شیخ البانی کے نزدیک ضعیف ہے۔"}],[2524,"عبید بن خالد سلمی رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے دو آدمیوں میں بھائی چارہ کرایا، ان میں سے ایک شہید کر دیا گیا اور دوسرے کا اس کے ایک ہفتہ کے بعد، یا اس کے لگ بھگ انتقال ہوا، ہم نے اس پر نماز جنازہ پڑھی تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"تم نے کیا کہا؟\" ہم نے جواب دیا: ہم نے اس کے حق میں دعا کی کہ: اللہ اسے بخش دے اور اس کو اس کے ساتھی سے ملا دے، تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اس کی نمازیں کہاں گئیں، جو اس نے اپنے ساتھی کے (قتل ہونے کے) بعد پڑھیں، اس کے روزے کدھر گئے جو اس نے اپنے ساتھی کے بعد رکھے، اس کے اعمال کدھر گئے جو اس نے اپنے ساتھی کے بعد کئے؟ ان دونوں کے درجوں میں ایسے ہی فرق ہے جیسے آسمان و زمین میں فرق ہے ۱؎\" شعبہ کو «صومه بعد صومه» اور «عمله بعد عمله» میں شک ہوا ہے۔\n§وضاحت\n۱؎ : ہو سکتا ہے کہ نبی اکرم صلی اللہ علیہ وسلم کو یہ بات معلوم ہو گئی ہو کہ بغیر شہادت کے ہی اس کا عمل اس کے اخلاص اور خشوع و خضوع کی زیادتی کے سبب شہید کے عمل کے برابر ہے، پھر اسے جو مزید عمل کا موقع ملا تو اس کی وجہ سے اس کا ثواب اس شہید کے ثواب سے فزوں ہو گیا کتنے شہداء ایسے ہیں جو صدیقین کے مقام و مرتبہ کو نہیں پاتے۔","صحیح",{"u2":"سیدنا عبید بن خالد سلمی رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے دو آدمیوں میں بھائی چارہ کرایا تھا۔ چنانچہ ایک (جہاد میں) قتل ہو گیا اور اس کا دوسرا ساتھی ایک ہفتہ بعد یا اس کے قریب فوت ہوا، ہم نے اس کا جنازہ پڑھا۔ رسول اللہ صلی اللہ علیہ وسلم نے پوچھا: ” تم نے (اس کے حق میں) کیا کہا ہے؟ “ ہم نے کہا: ہم نے اس کے لیے دعا کی اور کہا: اے اللہ! اس کو اپنے ساتھی کے ساتھ ملا دے۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” تو اس کی وہ نمازیں جو اس کے بعد پڑھتا رہا، وہ روزے جو اس کے بعد رکھتا رہا اور وہ عمل جو اس کے بعد کرتا رہا، کیا ہوئے؟ ان کے درمیان تو اتنا فاصلہ ہے جیسے کہ زمین و آسمان کے درمیان۔ “ شعبہ کو «في صومه» کے الفاظ میں شک ہوا ہے۔","f2":"زندگی انتہائی قیمتی متاع ہے۔ ہر لمحہ جو گزررہا ہے اس میں انسان یا تو اللہ کے ہاں اپنا مقام بلند کررہا ہے یا گرا رہا ہے۔شہید کا ایک مقام مرتبہ ہے۔مگربعض غیرشہداء اپنے اخلاص وتقویٰ اورکثرت عمل کی بناپر بلند مراتب حاصل کرلیں گے۔مثلا حضرت ابوبکر صدیق رضی اللہ تعالیٰ عنہ امت محمدیہ میں سب سے فائق ہیں۔اگرچہ شرف شہادت سے سرفراز نہیں ہوئے۔"}],[2525,"ابوایوب رضی اللہ عنہ سے روایت ہے کہ انہوں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا: \"عنقریب تم پر شہر کے شہر فتح کئے جائیں گے اور عنقریب ایک بھاری لشکر ہو گا اور اسی میں سے تم پر ٹکڑیاں متعین کی جائیں گی، تو تم میں سے جو شخص اس میں بغیر اجرت کے بھیجے جانے کو ناپسند کرے اور (جہاد میں جانے سے بچنے کے لیے) اپنی قوم سے علیحدہ ہو جائے، پھر قبیلوں کو تلاش کرتا پھرے اور اپنے آپ کو ان پر پیش کرے اور کہے کہ: کون مجھے بطور مزدور رکھے گا کہ میں اس کے لشکر میں کام کروں اور وہ میرا خرچ برداشت کرے؟ کون مجھے بطور مزدور رکھے گا کہ میں اس کے لشکر میں کام کروں اور وہ میرا خرچ برداشت کرے؟ خبردار وہ اپنے خون کے آخری قطرہ تک مزدور ہی رہے گا\"۔","ضعیف",{"u2":"سیدنا ابوایوب انصاری رضی اللہ عنہ سے روایت ہے کہ انہوں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا آپ صلی اللہ علیہ وسلم فرماتے تھے ” عنقریب تمہارے لیے بڑے بڑے شہر فتح کیے جائیں گے اور لشکر جمع کیے جائیں گے، ان کے کچھ حصے تمہارے ذمے آئیں گے (تمہارے مختلف قبیلوں اور علاقوں سے لوگ ان میں شامل کیے جائیں گے۔) تو (ایسے بھی ہو گا کہ) تم میں سے کوئی اس فوج میں بغیر اجرت کے شامل ہونا پسند نہیں کرے گا اور اپنی قوم میں سے نکل کھڑا ہو گا اور قبیلہ قبیلہ گھومتا پھرے گا، اپنے آپ کو ان پر پیش کرے گا اور کہے گا: کون ہے کہ فلاں لشکر میں، میں اس کی (طرف سے اجرت پر لڑتے ہوئے) کفایت کروں؟ کون ہے کہ فلاں لشکر میں، میں اس کی طرف سے (اجرت پر) کفایت کروں؟ خبردار! ایسا آدمی تو محض مزدور ہے خواہ اپنا آخری قطرہ خون بھی بہا دے۔“"}],[2526,"عبداللہ بن عمرو رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جہاد کرنے والے کو اس کے جہاد کا اجر ملے گا اور مجاہد کو تیار کرنے والے کو تیار کرنے اور غزوہ کرنے دونوں کا اجر ملے گا\"۔","صحیح",{"u2":"سیدنا عبداللہ بن عمرو رضی اللہ عنہ کا بیان ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” جہاد کرنے والے کو اپنا ثواب ملتا ہے اور جو کوئی کسی مجاہد کو تعاون دیتا ہے اسے اپنا ثواب ملتا ہے اور ساتھ ہی جہاد کرنے والے مجاہد کا بھی۔ ‘‘ (دگنا ثواب ملتا ہے۔)","f2":"یہ اور اس قسم کی احادیث جن میں جہاد قتال کے لئے مادی تعاون لینے کی رخصت ہے۔ان کا تعلق ان مخلصین مگر مفلوک الحال اور فقیر لوگوں سے ہے۔جو اسباب وزاد جہاد نہ ہونے کے باعث جہاد سے پیچھے رہیں۔ان کا جہاد بربنائے اخلاص وتقویٰ اعلائے کلمۃ اللہ کےلئے ہی ہوتاہے۔تو ایسے لوگوں سے تعاون کرنا باعث اجر وثواب ہے بلکہ تعاون دینے والوں کےلئے دوہرا جر ہے۔جیسے کہ حکومت کے تنخواہ دار فوجی اگر یہ اخلاص سے اعلائے کلمۃ اللہ کی خاطرلڑیں۔ تو اجر وغنیمت دونوں سے بہر ور ہوتے ہیں۔ورنہ وہی ہے جو ان کی نیت ہوئی اور اسی پر قیاس ہیں وہ علماء مدرسین اور خطباء وغیرہ جو شرعی علوم کی اشاعت میں مشغول ہیں۔اگر ان کی نیت صاف ہو تو فبھا ونعمت انھیں تنخواہیں اور وظیفے لینے جائز ہیں ورنہ انہیں انجام کی فکر کرنی چاہیے۔"}],[2527,"یعلی بن منیہ رضی اللہ عنہ کہتے ہیں رسول اللہ صلی اللہ علیہ وسلم نے غزوہ کا اعلان کیا اور میں بہت بوڑھا تھا میرے پاس کوئی خادم نہ تھا، تو میں نے ایک مزدور تلاش کیا جو میری خدمت کرے اور میں اس کے لیے اس کا حصہ جاری کروں، آخر میں نے ایک مزدور پا لیا، تو جب روانگی کا وقت ہوا تو وہ میرے پاس آیا اور کہنے لگا: میں نہیں جانتا کہ کتنے حصے ہوں گے اور میرے حصہ میں کیا آئے گا؟ لہٰذا میرے لیے کچھ مقرر کر دیجئیے خواہ حصہ ملے یا نہ ملے، لہٰذا میں نے اس کے لیے تین دینار مقرر کر دئیے، جب مال غنیمت آیا تو میں نے اس کا حصہ دینا چاہا، پھر خیال آیا کہ اس کے تو تین دینار مقرر ہوئے تھے، میں نبی اکرم صلی اللہ علیہ وسلم کے پاس آیا اور آپ سے اس کا معاملہ بیان کیا آپ صلی اللہ علیہ وسلم نے فرمایا: \"میں اس کے لیے اس کے اس غزوہ میں دنیا و آخرت میں کچھ نہیں پاتا سوائے ان تین دیناروں کے جو متعین ہوئے\"۔","صحیح",{"u2":"سیدنا یعلیٰ بن منیہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے جہاد کا اعلان فرمایا جبکہ میں بوڑھا آدمی تھا، میرا کوئی خادم بھی نہ تھا تو مجھے کسی ایسے ملازم کی تلاش ہوئی جو (جہاد میں) میری کفایت کرتا اور میں اس کو اس کا حصہ دیتا، چنانچہ مجھے ایک آدمی مل گیا۔ پھر جب کوچ کا وقت ہوا تو وہ میرے پاس آیا اور کہا۔ مجھے نہیں معلوم کہ (مال غنیمت میں) حصے کیا ہوں گے اور میرا حصہ کتنا ہو گا؟ پس آپ مجھے متعین طور پر بتا دیں وہ آئے نہ آئے (مجھے اس سے غرض نہیں۔) تو میں نے اس کے لیے تین دینار متعین کر دیے۔ پھر جب میں غنیمت لینے کے لیے حاضر ہوا اور چاہا کہ اس کا حصہ اسے دوں تو مجھے مقرر کردہ دیناروں کا خیال آیا۔ میں نبی کریم صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوا اور اس آدمی کا معاملہ آپ صلی اللہ علیہ وسلم کے سامنے پیش کیا۔ آپ صلی اللہ علیہ وسلم نے فرمایا۔ ’’ میں اس کے اس جہاد میں دنیا و آخرت میں سوائے ان دیناروں کے جو اس نے مقرر کر لیے اور کچھ نہیں پاتا۔ ‘‘","f2":"حسب ضرورت جہاد وغیرہ میں ملازم سے کام لینا جائز ہے۔مگر ایسے غلام اور ملازم کا اجر اس کی اپنی نیت پ موقوف ہے۔اگر اس کی نیت میں تقرب الی اللہ اور حصول رضا کا داعیہ موجود ہو تو اجر وغنیمت دونوں کا فائدہ حاصل ہو جاتاہے۔ ورنہ بہت بڑی محرومی ہے کہ د نیاکے مال کے سوا اسے کچھ نہیں ملے گا۔"}],[2528,"عبداللہ بن عمرو رضی اللہ عنہما سے روایت ہے کہ ایک آدمی نے رسول اللہ صلی اللہ علیہ وسلم کے پاس آ کر کہا: میں آپ سے ہجرت پر بیعت کرنے کے لیے آیا ہوں، اور میں نے اپنے ماں باپ کو روتے ہوئے چھوڑا ہے، آپ صلی اللہ علیہ وسلم نے فرمایا: \"ان کے پاس واپس جاؤ، اور انہیں ہنساؤ جیسا کہ رلایا ہے ۱؎\"۔\n§وضاحت\n۱؎ : علامہ خطابی کہتے ہیں کہ مجاہد اگر رضاکارانہ طور پر جہاد میں شریک ہونا چاہتا ہے تو ایسی صورت میں ماں باپ کی اجازت ضروری ہے، البتہ اگر جہاد میں شرکت اس کے لئے فرض ہے تو ماں باپ کی مرضی اور اجازت کی ضرورت نہیں، مذکورہ دونوں صورتوں میں ان کی اجازت یا عدم اجازت کا مسئلہ اس وقت اٹھتا ہے جب ماں باپ مسلم ہوں، اگر وہ دونوں کافر ہیں تو اجازت کی سرے سے ضرورت ہی نہیں۔","صحیح",{"u2":"سیدنا عبداللہ بن عمرو رضی اللہ عنہ سے روایت ہے کہ ایک آدمی رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوا اور کہا: میں آپ کے پاس ہجرت پر بیعت کے لیے حاضر ہوا ہوں اور اپنے ماں باپ کو روتے ہوئے چھوڑ کر آیا ہوں۔۔ آپ صلی اللہ علیہ وسلم نے فرمایا ’’ ان کے پاس جا اور انہیں ہنسا (اور خوش کر) جیسے کہ تو نے انہیں رلایا ہے۔ ‘‘","f2":"والدین مسلمان ہوں او ر جہاد فرض نہ ہو تو ان کی اجازت حاصل کرنا ضروری ہے۔کیونکہ دیگر مجاہدین اس کی کفایت کر سکتے ہیں۔ لیکن جب جہاد فرض ہو تو اجازت لینے کی قطعا ً کوئی ضرورت نہیں۔تاہم ایسے حالات میں کہ والدین باوجود مسلمان ہونے کے جہاد کی شرعی اہمیت و ضرورت سے آگاہ نہ ہوں۔یا آگاہ نہ ہونا چاہیں۔اور بذدلی کا شکار ہوں۔مادی خدمات کے لئے اولاد بھی موجود ہو اور پھر بھی اجازت نہ دیں تو پھر مسئلہ امیر جہاد کے سامنے پیش کیا جائےاور اس کی ہدایت پر عمل کیا جائے۔واللہ اعلم بالصواب"}],[2529,"عبداللہ بن عمرو رضی اللہ عنہما کہتے ہیں کہ ایک آدمی نبی اکرم صلی اللہ علیہ وسلم کے پاس آیا اور کہنے لگا: اللہ کے رسول! میں جہاد کروں؟ آپ صلی اللہ علیہ وسلم نے پوچھا: \"کیا تمہارے ماں باپ زندہ ہیں؟\" اس نے کہا: ہاں، آپ صلی اللہ علیہ وسلم نے فرمایا: \"انہیں دونوں میں جہاد کرو ۱؎\" ابوداؤد کہتے ہیں: یہ ابو العباس شاعر ہیں جن کا نام سائب بن فروخ ہے۔\n§وضاحت\n۱؎ : یعنی ان کی خدمت کرکے جہاد کا ثواب حاصل کرو۔","صحیح",{"u2":"سیدنا عبداللہ بن عمرو رضی اللہ عنہ سے روایت ہے کہ ایک شخص نبی کریم صلی اللہ علیہ وسلم کی خدمت میں آیا اور کہا: اے اللہ کے رسول! میں جہاد کرنا چاہتا ہوں۔ آپ صلی اللہ علیہ وسلم نے فرمایا ’’ کیا تیرے ماں باپ ہیں؟ ‘‘ اس نے کہا ہاں۔ آپ صلی اللہ علیہ وسلم نے فرمایا ’’ تو، تو انہی میں جہاد کر (ان کی خدمت کر، یہی تیرا جہاد ہے۔) “ امام ابوداؤد رضی اللہ عنہ فرماتے ہیں کہ سند حدیث میں راوی ابوالعباس یہ شاعر ہے اور اس کا نام سائب بن فروخ ہے۔","f2":"والدین کی خدمت مسلمان اولاد کا اہم ترین فریضہ ہے۔نفلی جہاد کے مقابلے میں ان کی خدمت کو اولیت حاصل ہے۔بالخصوص جب کہ ماں باپ اس کی خدمت کے محتاج ہوں۔"}],[2530,"ابو سعید خدری رضی اللہ عنہ کہتے ہیں کہ ایک آدمی رسول اللہ صلی اللہ علیہ وسلم کے پاس یمن سے ہجرت کر کے آیا، آپ نے اس سے فرمایا: \"کیا یمن میں تمہارا کوئی ہے؟\" اس نے کہا: ہاں، میرے ماں باپ ہیں، آپ صلی اللہ علیہ وسلم نے پوچھا: \"انہوں نے تمہیں اجازت دی ہے؟\" اس نے کہا: نہیں، آپ صلی اللہ علیہ وسلم نے فرمایا: \"ان کے پاس واپس جاؤ اور اجازت لو، اگر وہ اجازت دیں تو جہاد کرو ورنہ ان دونوں کی خدمت کرو\"۔","صحیح",{"u2":"سیدنا ابو سعید خدری رضی اللہ عنہ کا بیان ہے کہ ایک شخص یمن سے ہجرت کر کے رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں پہنچا۔ آپ صلی اللہ علیہ وسلم نے اس سے پوچھا۔ ’’ کیا یمن میں تیرا کوئی عزیز بھی ہے؟ ‘‘ اس نے کہا: میرے ماں باپ ہیں۔ آپ صلی اللہ علیہ وسلم نے پوچھا ’’ کیا انہوں نے تجھے اجازت دی ہے؟ ‘‘ اس نے کہا: نہیں۔ آپ صلی اللہ علیہ وسلم نے فرمایا ’’ ان کے پاس واپس جا اور ان سے اجازت طلب کر۔ اگر وہ اجازت دے دیں تو جہاد کر ورنہ ان کی خدمت کر۔ ‘‘","f2":"نفلی جہاد میں والدین کی اجازت ضروری ہے۔یہاں یہ امر بھی قابل ملاحظہ ہے۔ کہ اسلام نے خاندان اکائی اور ا سے مضبوط کرنے اور رکھنے کی ازحد تلقین کی ہے۔اس سے نیکی کو فروغ ملتا ہے اور بُرائی کے در بند ہوتے ہیں۔مگر مغربی تہذیب نے اس بنیادی اکائی اور وحدت کوتوڑنے کےلئے افراد کنبہ اور بالغ اولاد کو بالخصوص آذا د روی اور آذاد منشی کا جو سبق دیا ہے۔اس کے اثرات انتہائی زہریلے ہیں۔مغرب نے خود تو اس کا انجام دیکھ ہی لیا ہے۔اور اب اس کا ر خ مشرق اور بالخصوص اسلامی معاشروں کی طرف ہے۔"}],[2531,"انس رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم ام سلیم رضی اللہ عنہا کو اور انصار کی کچھ عورتوں کو جہاد میں لے جاتے تھے تاکہ وہ مجاہدین کو پانی پلائیں اور زخمیوں کا علاج کریں ۱؎۔\n§وضاحت\n۱؎ : اس حدیث سے معلوم ہوا کہ عورتوں کا جہاد میں شریک ہونا جائز ہے، حالانکہ بعض روایتوں سے پتہ چلتا ہے کہ جہاد پر نکلنے والی عورتوں کو آپ صلی اللہ علیہ وسلم نے واپس لوٹ جانے کا حکم دیا، اس کے دو اسباب بیان کئے جاتے ہیں : ۱- آپ کو دشمنوں کی قوت و ضعف کا صحیح اندازہ نہ ہو سکا اور خطرہ تھا کہ مسلمان دشمن سے مغلوب ہو جائیں گے اس لئے آپ نے انہیں واپس کر دیا۔ ۲- ممکن ہے یہ عورتیں نوجوان اور نئی عمر کی رہی ہوں جن سے میدان جہاد میں فتنہ کا خوف رہا ہو اس لئے آپ نے انہیں واپس کر دیا ہو، واللہ اعلم۔","صحیح",{"u2":"سیدنا انس رضی اللہ عنہ سے مروی ہے کہرسول اللہ صلی اللہ علیہ وسلم (میری والدہ) ام سلیم رضی اللہ عنہا ا اور انصار کی کچھ عورتوں کو جہاد میں ساتھ لے جایا کرتے تھے تاکہ وہ پانی پلائیں اور زخمیوں کی مرہم پٹی کریں۔","f2":"جہاد میں عورتوں سے مجاہدین کی خدمت کے کام لئے جاسکتے ہیں۔یہ امور باحجاب ہوکر ادا کیے جاسکتے ہیں۔لہذا یہ خدمات لینے کے لئے خواتین کی تعلیم وتربیت اور مشق بھی ضروری ہے۔شرعی تعلیمات کی ر وشنی میں اجنبی مردوں اور عورتوں کو بے حجاب کھلے اختلاط کی قطعاً اجازت نہیں دی جاسکتی۔بعض لوگ عہد نبوی صلی اللہ علیہ وسلم کے اس قسم کے بعض اکا دکا واقعات سے یہ کلیہ اور اصول اخذکرتے ہیں۔کہ مردو عورت کے درمیان کسی بھی معاملے میں فرق وامتیاز نہیں ہونا چاہیے۔بلکہ عورتوں کو زندگی کے ہر شعبے میں مردوں کے دوش بدوش حصہ لینا چاہیے۔لیکن ظاہر بات ہے کہ ان لوگوں کا یہ دعویٰ بھی یکسر غلط ہے۔اور استدلال بھی بے بنیاد بھلا چند عمر رسیدہ خواتین کو زخمیوں کی مرہم پٹی کرنے اور ان کو پانی پلانے جیسی معمولی خدمات کےلئے ان کو ساتھ لے جانے سے مردوزن کی مغربی مساوات اور ہر معاملے میں دوش بدوش کا اثبات کس طرح ممکن ہے؟"}],[2532,"انس بن مالک رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"تین باتیں ایمان کی اصل ہیں: ۱- جو لا الہٰ الا اللہ کہے اس (کے قتل اور ایذاء) سے رک جانا، اور کسی گناہ کے سبب اس کی تکفیر نہ کرنا، نہ اس کے کسی عمل سے اسلام سے اسے خارج کرنا۔ ۲- جہاد جاری رہے گا جس دن سے اللہ نے مجھے نبی بنا کر بھیجا ہے یہاں تک کہ میری امت کا آخری شخص دجال سے لڑے گا، کسی بھی ظالم کا ظلم، یا عادل کا عدل اسے باطل نہیں کر سکتا۔ ۳- تقدیر پر ایمان لانا\"۔","ضعیف",{"u2":"سیدنا انس بن مالک رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ’’ تین باتیں ایمان کی اصل ہیں۔ جس شخص نے «لا إله إلا الله» کا اقرار کیا اس کے درپے نہ ہو، اسے کسی گناہ کے بنا پر کافر نہ کہو اور نہ کسی عمل کی وجہ سے ایمان سے نکالو۔ اور جب سے اللہ نے مجھے مبعوث فرمایا ہے جہاد جاری ہے اور جاری رہے گا یہاں تک کہ اس امت کا آخری حصہ دجال سے قتال کرے گا، اس کو کسی ظالم کا ظلم یا عادل کا عدل باطل نہیں کر سکتا اور تقدیروں پر ایمان رکھنا۔"}],[2533,"ابوہریرہ رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جہاد تم پر ہر امیر کے ساتھ واجب ہے خواہ وہ نیک ہو، یا بد اور نماز ہر مسلمان کے پیچھے واجب ہے خواہ وہ نیک ہو یا بد، اگرچہ وہ کبائر کا ارتکاب کرئے، اور نماز (جنازہ) واجب ہے ہر مسلمان پر نیک ہو یا بد اگرچہ کبائر کا ارتکاب کرے\"۔","ضعیف",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ’’ تم پر ہر امیر کے ساتھ جہاد واجب ہے خواہ نیک ہو یا بد ‘ اور تم پر ہر مسلمان کے پیچھے نماز پڑھنا واجب ہے خواہ وہ نیک ہو یا بد ‘ اگرچہ کبائر کا مرتکب ہی کیوں نہ ہو ‘ اور تم پر واجب ہے کہ ہر مسلمان کی نماز (جنازہ) پڑھو خواہ کوئی نیک ہو یا بد ‘ اگرچہ کبائر کا مرتکب ہو۔ ‘‘","f2":"یہ دونوں روایات ضعیف ہیں۔ان میں کچھ باتیں صحیح ہیں۔جن کی تایئد دوسری صحیح روایات سے ہوتی ہے۔اور کچھ باتیں صحیح نہیں ہیں۔بہر حال یہ دونوں روایات مدار استدلال نہیں ہیں۔"}],[2534,"جابر بن عبداللہ رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے جہاد کا ارادہ کیا تو فرمایا: \"اے مہاجرین اور انصار کی جماعت! تمہارے بھائیوں میں سے کچھ لوگ ایسے ہیں جن کے پاس مال ہے نہ کنبہ، تو ہر ایک تم میں سے اپنے ساتھ دو یا تین آدمیوں کو شریک کر لے، تو ہم میں سے بعض کے پاس سواری نہیں ہوتی سوائے اس کے کہ وہ باری باری سوار ہوں\"، تو میں نے اپنے ساتھ دو یا تین آدمیوں کو لے لیا، میں بھی صرف باری سے اپنے اونٹ پر سوار ہوتا تھا، جیسے وہ ہوتے تھے۔","صحیح",{"u2":"سیدنا جابر بن عبداللہ رضی اللہ عنہ نے رسول اللہ صلی اللہ علیہ وسلم سے بیان کیا کہ آپ صلی اللہ علیہ وسلم نے جہاد کا ارادہ کیا اور فرمایا ’’ اے مہاجرو اور انصاریو! تمہارے کچھ بھائی ایسے بھی ہیں کہ ان کے پاس مال نہیں اور نہ ان کا کوئی خویش قبیلہ ہے تو تم میں سے ہر ایک کو چاہیئے کہ ان میں سے دو تین آدمیوں کو اپنے ساتھ ملا لے ‘ چنانچہ ہم میں سے جس کسی کے پاس سواری تھی وہ اپنے ساتھی کو باری سے سوار کرتا اور خود بھی باری سے سوار ہوتا تھا۔ ‘‘ سیدنا جابر رضی اللہ عنہ کہتے ہیں: میں نے بھی دو تین کو اپنے ساتھ ملا لیا تو مجھے اپنے ہی اونٹ پر باری سے سواری ملتی تھی جیسے کہ انہیں۔","f2":"صحابہ کرامرضوان اللہ عنہم اجمعین کا یہ ایثار ان کی آپس میں اللہ فی اللہ محبت کی دلیل تھی۔اس سے اللہ عزوجل نے اسلام اور مسلمانوں کودنیا ہی میں رفعت عنایت فرمادی تھی۔جبکہ جہاد میں دوسرے سے تعاون کرنے والا خود مجاہد جتنا ثواب پاتا ہے۔"}],[2535,"ضمرہ کا بیان ہے کہ ابن زغب ایادی نے ان سے بیان کیا کہ عبداللہ بن حوالہ ازدی رضی اللہ عنہ میرے پاس اترے، اور مجھ سے بیان کیا: رسول اللہ صلی اللہ علیہ وسلم نے ہمیں بھیجا ہے کہ ہم پیدل چل کر مال غنیمت حاصل کریں، تو ہم واپس لوٹے اور ہمیں کچھ بھی مال غنیمت نہ ملا، اور آپ صلی اللہ علیہ وسلم نے ہمارے چہروں پر پریشانی کے آثار دیکھے تو ہمارے درمیان کھڑے ہوئے اور فرمایا: \"اللہ! انہیں میرے سپرد نہ فرما کہ میں ان کی خبرگیری سے عاجز رہ جاؤں، اور انہیں ان کی ذات کے حوالہ (بھی) نہ کر کہ وہ اپنی خبرگیری خود کرنے سے عاجز آ جائیں، اور ان کو دوسروں کے حوالہ نہ کر کہ وہ خود کو ان پر ترجیح دیں\"، پھر آپ صلی اللہ علیہ وسلم نے اپنا ہاتھ میرے سر پر یا میری گدی پر رکھا اور فرمایا: \"اے ابن حوالہ! جب تم دیکھو کہ خلافت شام میں اتر چکی ہے، تو سمجھ لو کہ زلزلے، مصیبتیں اور بڑے بڑے واقعات (کے ظہور کا وقت) قریب آ گیا ہے، اور قیامت اس وقت لوگوں سے اتنی قریب ہو گی جتنا کہ میرا یہ ہاتھ تمہارے سر سے قریب ہے\"۔","صحیح",{"u2":"ابن زغب ایادی نے بیان کیا کہ سیدنا عبداللہ بن حوالہ ازدی رضی اللہ عنہ میرے مہمان بنے تو انہوں نے مجھ سے بیان کیا: رسول اللہ صلی اللہ علیہ وسلم نے ہم کو پیدل (جہاد کے لیے) روانہ فرمایا تاکہ کوئی غنیمت حاصل کر لائیں۔ پس ہم واپس آئے اور ہمیں کوئی غنیمت نہ ملی۔ آپ صلی اللہ علیہ وسلم نے مشقت اور غمی کے آثار ہمارے چہروں پر دیکھے تو کھڑے ہوئے اور (دعا کرتے ہوئے) فرمایا ’’ اے اللہ! انہیں میرے سپرد نہ کر دے کہ ان کی کفالت سے عاجز رہوں اور نہ انہیں ان کی اپنی جانوں کے سپرد کر دے کہ اپنی کفالت سے عاجز رہیں اور نہ انہیں لوگوں کے سپرد کر دینا کہ وہ اپنے آپ ہی کو ترجیح دینے لگیں۔ پھر آپ صلی اللہ علیہ وسلم نے اپنا ہاتھ مبارک میرے سر پر رکھا اور فرمایا ’’ اے ابن حوالہ! جب تم دیکھو کہ خلافت ارض مقدس (شام) تک پہنچ گئی ہے تو زلزلے آنے لگیں گے ‘ مصیبتیں ٹوٹیں گی۔ (علاوہ ازیں) اور بھی بڑی بڑی علامتیں ظاہر ہوں گی اور قیامت اس وقت لوگوں کے اس سے زیادہ قریب ہو گی جتنا کہ میرا ہاتھ تمہارے سر پر ہے۔ ‘‘ امام ابوداؤد رضی اللہ عنہ کہتے ہیں کہ عبداللہ بن حوالہ رضی اللہ عنہ کا تعلق حمص سے ہے۔","f2":"1۔جہاد میں اجر وثواب کے ساتھ ساتھ غنیمت کی توقع رکھنا کوئی معیوب نہیں۔ بشرط یہ کہ یہ نیت ہی اصل مقصود نہ ہو اتنا ضرور ہے کہ یہ غنیمت حاصل ہونے سے آخرت کے اجر میں کمی آجاتی ہے۔جیسے کہ (باب فی السریہ تخفق)حدیث 2497)میں گزرا ہے۔2۔اللہ تعالیٰ نے مال کو انسان کےلئے گزران کا ایک اہم سبب بنایا ہے جب کہ حقیقی کفیل خود اللہ عزوجل ہے۔اگر وہ اسباب مہیا نہ فرمائے۔اور ان میں برکت نہ دےتو کائنات کے تمام افراد اور اس کے کل اسباب پرکاہ ک حیثیت بھی نہیں رکھتے۔3۔مستقبل کے امور غیبہ کی خبریں نبی کریم صلی اللہ علیہ وسلم کی نبوت کی صداقت کی دلیل ہیں۔کہ فتح بیت المقدس کے بعد سے دنیا میں اور امت اسلامیہ میں مذکورہ بالاعلامات تواتر سے ظاہر ہورہی ہیں۔2۔قیامت ازحد قریب ہے۔لہذا ہر انسان کو اس کی فکر کرنی چاہیے۔"}],[2536,"عبداللہ بن مسعود رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"ہمارا رب اس شخص سے خوش ہوتا ہے ۱؎ جس نے اللہ کی راہ میں جہاد کیا، پھر اس کے ساتھی شکست کھا کر (میدان سے) بھاگ گئے اور وہ گناہ کے ڈر سے واپس آ گیا (اور لڑا) یہاں تک کہ وہ قتل کر دیا گیا، اس وقت اللہ تعالی اپنے فرشتوں سے فرماتا ہے: میرے بندے کو دیکھو میرے ثواب کی رغبت اور میرے عذاب کے ڈر سے لوٹ آیا یہاں تک کہ اس کا خون بہا گیا\"۔\n§وضاحت\n۱؎ : اس حدیث میں اللہ تعالی کے لئے صفت تعجب کی صراحت ہے، دوسری حدیث میں ضحک (ہنسنے) کی صفت کا تذکرہ ہے، یہ صفات اللہ تعالی کے لئے ثابت ہیں، ذات باری تعالی اور اس کی صفات کی کنہ و کیفیت کی جستجو میں پڑے بغیر تمام ثابت صفات باری تعالی پر ایمان لانا چاہئے، اور کسی مخلوق کی ذات وصفات سے اس کی تشبیہ وتمثیل وتکییف جائز نہیں ہے۔ «ليس كمثله شيء وهو السميع البصير» ’’اللہ کے ہم مثل کوئی چیز نہیں اور وہ ذات باری سمیع (سننے والا) اور بصیر (دیکھنے والا ہے)‘‘۔","حسن",{"u2":"سیدنا عبداللہ بن مسعود رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ’’ ہمارے رب تعالیٰ کو اس بندے پر بڑا تعجب آتا ہے جو اللہ کی راہ میں جہاد کے لیے نکلے ‘ اور اس کے ساتھی بھاگ نکلیں (مگر) اس بندے کو گناہ کا احساس ہو تو وہ (قتال کے لیے) واپس لوٹ آئے حتیٰ کے اس کا خون بہا دیا جائے ‘ تو اللہ تعالیٰ اپنے فرشتوں سے کہتا ہے۔ دیکھو میرے بندے کی طرف کہ میرے ہاں ثواب کی رغبت میں اور میری پکڑ کے ڈر سے واپس لوٹ آیا حتیٰ کے اس کا خون بہا دیا گیا۔ ‘‘","f2":"فوائد ومسائل:۔سورہ توبہ میں یہ مضمون تفصیل سے بیان ہوا ہے۔اللہ تعالیٰ کا فرمان ہے۔\n(إِنَّ اللَّـهَ اشْتَرَىٰ مِنَ الْمُؤْمِنِينَ أَنفُسَهُمْ وَأَمْوَالَهُم بِأَنَّ لَهُمُ الْجَنَّةَ ۚ يُقَاتِلُونَ فِي سَبِيلِ اللَّـهِ فَيَقْتُلُونَ وَيُقْتَلُونَ ۖ وَعْدًا عَلَيْهِ حَقًّا فِي التَّوْرَاةِ وَالْإِنجِيلِ وَالْقُرْآنِ)(التوبہ۔111)\nاللہ تعالیٰ نے مومنوں سے ان کی جانیں اور ان کے مال جنت کے عوض خرید لئے ہیں۔یہ لوگ اللہ کی راہ میں قتال کرتے ہیں تو مارتے ہیں۔اور مارے بھی جاتے ہیں۔یہ تورات انجیل اور قرآن میں بیان شدہ سچاوعدہ ہے۔ الغرض مسلمان کو اپنے تمام تر اعمال اور احوال میں اللہ تعالیٰ کے ہاں اجر وثواب کا امید وار اور اس کے عقاب سے ڈرتے رہنا چاہیے۔یہی اصل ایمان اور اس کی چوٹی ہے۔2۔ اللہ عزوجل کا تعجب کرنا اس طرح اس کی دیگر صفات کی کیفیت ہم جان سکتے ہیں۔نہ بیان کر سکتے ہیں اس لئے کہ اللہ تعالیٰ کا فرمان ہے۔\n(ۚ لَيْسَ كَمِثْلِهِ شَيْءٌ ۖ وَهُوَ السَّمِيعُ الْبَصِيرُ)(الشوریٰ۔11)\nاس کی مثل کوئی چیز نہیں اور وہ سننے والا اور دیکھنے والا ہے۔ بنا بریں یہ صفات الہیٰ ایسی ہیں۔ جیسے اس کی شان کے لائق ہیں۔ ہمیں ان پرایمان رکھنا ہے جیس وہ بیان ہوئیں ہیں۔ان کی کنہ اور حقیقت جاننے کے چکر میں پڑنے کی ضرورت نہیں۔کیونکہ وہ کوئی جان ہی نہیں سکتا۔"}],[2537,"ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ عمرو بن اقیش رضی اللہ عنہ کا جاہلیت میں کچھ سود (وصول کرنا) رہ گیا تھا انہوں نے اسے بغیر وصول کئے اسلام قبول کرنا اچھا نہ سمجھا، چنانچہ (جب وصول کر چکے تو) وہ احد کے دن آئے اور پوچھا: میرے چچازاد بھائی کہاں ہیں؟ لوگوں نے کہا: احد میں ہیں، کہا: فلاں کہاں ہے؟ لوگوں نے کہا: احد میں، کہا: فلاں کہاں ہے؟ لوگوں نے کہا: احد میں، پھر انہوں نے اپنی زرہ پہنی اور گھوڑے پر سوار ہوئے، پھر ان کی جانب چلے، جب مسلمانوں نے انہیں دیکھا تو کہا: عمرو ہم سے دور رہو، انہوں نے کہا: میں ایمان لا چکا ہوں، پھر وہ لڑے یہاں تک کہ زخمی ہو گئے اور اپنے خاندان میں زخم خوردہ اٹھا کر لائے گئے، ان کے پاس سعد بن معاذ رضی اللہ عنہ آئے اور ان کی بہن سے کہا: اپنے بھائی سے پوچھو: اپنی قوم کی غیرت یا ان کی خاطر غصہ سے لڑے یا اللہ کے واسطہ غضب ناک ہو کر، انہوں نے کہا: نہیں، بلکہ میں اللہ اور اس کے رسول کے واسطہ غضب ناک ہو کر لڑا، پھر ان کا انتقال ہو گیا اور وہ جنت میں داخل ہو گئے، حالانکہ انہوں نے اللہ کے لیے ایک نماز بھی نہیں پڑھی۔","حسن",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ عمرو بن اقیش نے لوگوں سے اسلام سے پہلے کا سود لینا تھا ‘ تو وہ اس کی وصول یابی تک اسلام سے دور رہا۔ آخر احد کے دن آیا اور پوچھا کہ میرے چچا زاد کہاں ہیں لوگوں نے کہا: احد میں ہیں ‘ پھر پوچھا کہ فلاں کہاں ہے؟ انہوں نے کہا: احد میں ہے۔ پھر پوچھا کہ فلاں کہا ہے؟ انہوں نے کہا: احد میں ہے۔ چنانچہ اس نے اپنے ہتھیار پہنے ‘ گھوڑے پر سوار ہوا اور ان لوگوں کی جانب چلا گیا۔ مسلمانوں نے جب اس کو دیکھا ‘ تو کہا: اے عمرو! ہم سے دور رہو۔ اس نے کہا۔ یقین کرو کہ میں ایمان لا چکا ہوں چنانچہ قتال کرنے لگا حتیٰ کہ زخمی ہو گیا۔ اسے اسی حالت میں اٹھا کر اس کے اہل میں لایا گیا پس سعد بن معاذ رضی اللہ عنہ اس کے پاس آئے اور اس کی بہن سے کہا اس سے پوچھو (کہ اس نے جنگ میں حصہ کیوں لیا ہے) اپنی قوم کی حمیت و حمایت میں ‘ یا ان کے لیے غصہ کی بنا پر ‘ یا اللہ کے لیے غصے کی وجہ سے؟ تو اس نے کہا: بلکہ میں اللہ اور اس کے رسول (صلی اللہ علیہ وسلم) کے لیے غصے کی وجہ سے (اس جنگ میں شریک ہوا ہوں) چنانچہ فوت ہو گیا اور جنت میں داخل ہوا اور اس نے اللہ کے لیے ایک بھی نماز نہیں پڑھی تھی۔","f2":"1۔اللہ اور اس کے رسول صلی اللہ علیہ وسلم کی حمیت اور حمایت میں اپنی جان وار دینا اور اسی کےلئے اپنی محبت اور غصے کے جذبات کا اظہار کرنا ایمان کامل کی علامت اور اللہ کے ہاں نجات کی ضمانت ہے۔2۔نماز اسلام کا بنیادی رکن ہے۔ مگر عمرو بن اقیش رضی اللہ تعالیٰ عنہ کو اس کے سیکھنے اور ادا کرنے کاموقع ہی نہیں ملا تو اس لئے معذور سمجھے گئے۔3۔وہ لوگ سمجھتے تھے کہ اسلام ایک عملی اور باضابطہ دین ہے۔اس میں اللہ اور اس کے رسول صلی اللہ علیہ وسلم کی مخالفت ومعصیت کا کوئی تصور نہیں اور نہ حرام کی گنجائش ہے۔اسی وجہ سے حضرت عمر و نے اپنے اسلام کو موخر کیا۔یہ ان کی سعادت تھی کہ اللہ عزوجل نے ان کو مہلت دی۔اور وہ اسلام اور پھر شہادت سے بہرہ ور ہوگئے۔4۔یہ واقعہ کسی شخص کو اپنا اسلام یا گنا ہ سے توبہ کو موخر کرنے کی دلیل نہیں بنایا جاسکتا۔نہ معلوم مطلب پورا ہونے تک زندگی کی مہلت بھی ملے گی یا نہیں۔یا کہیں نیت ہی نہ بدل جائے۔یا حالات سازگار نہ رہیں۔اور پھر اسلام یا توبہ سے محروم رہ گیا تو ہمیشہ کی محرومی کا سامنا ہوگا۔"}],[2538,"سلمہ بن الاکوع رضی اللہ عنہ کہتے ہیں کہ جب جنگ خیبر ہوئی تو میرے بھائی بڑی شدت سے لڑے، ان کی تلوار اچٹ کر ان کو لگ گئی جس نے ان کا خاتمہ کر دیا، صحابہ کرام رضی اللہ عنہم نے ان کے سلسلے میں باتیں کی اور ان کی شہادت کے بارے میں انہیں شک ہوا تو کہا کہ ایک آدمی جو اپنے ہتھیار سے مر گیا ہو (وہ کیسے شہید ہو سکتا ہے؟)، اس پر رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"وہ اللہ کے راستہ میں کوشش کرتے ہوئے مجاہد ہو کر مرا ہے\"۔ ابن شہاب زہری کہتے ہیں: پھر میں نے سلمہ بن الاکوع رضی اللہ عنہ کے ایک بیٹے سے پوچھا تو انہوں نے اپنے والد کے واسطہ سے اسی کے مثل بیان کیا، مگر اتنا کہا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"لوگوں نے جھوٹ کہا، وہ جہاد کرتے ہوئے مجاہد ہو کر مرا ہے، اسے دوہرا اجر ملے گا\"۔","صحیح",{"u2":"سیدنا سلمہ بن اکوع رضی اللہ عنہ بیان کرتے ہیں کہ خیبر کے موقع پر میرے بھائی (عامر بن اکوع) نے خوب قتال کیا اور (اللہ کا کرنا ایسا ہوا کہ) اس کی اپنی تلوار چٹ کر خود اس کو لگ گئی جس سے وہ قتل ہو گیا۔ اصحاب رسول صلی اللہ علیہ وسلم اس کے بارے میں باتیں کرنے لگے اور اس (کی شہادت) کے سلسلے میں انہوں نے شک کا اظہار کیا کہ ایک آدمی اپنے ہی ہتھیار سے مارا گیا ہے (تو کیونکر شہید سمجھا جائے گا؟) رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ’’ یہ جہاد کرتے ہوئے فوت ہوا اور مجاہد فوت ہوا ہے۔ ‘‘ ابن شہاب زہری کہتے ہیں کہ پھر میں نے سلمہ بن اکوع کے بیٹے سے دریافت کیا تو اس نے مجھے اپنے باپ کے حوالے سے اسی کی مانند بیان کیا مگر اس کے الفاظ یہ تھے۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ’’ غلط کہتے ہیں ‘ یہ جہاد کرتے ہوئے فوت ہوا ہے ‘ مجاہد فوت ہوا ہے اور اس کے لیے دگنا اجر ہے۔ ‘‘","f2":"اس مجاہد کے لئے دوہرے اجر کی خوشخبری ممکن ہے۔جہاد اور شہادت کی بنا پر ہو واللہ اعلم۔"}],[2539,"ابو سلام ایک صحابی سے روایت کرتے ہوئے کہتے ہیں کہ ہم نے جہینہ کے ایک قبیلہ پر شب خون مارا تو ایک مسلمان نے ایک آدمی کو مارنے کا قصد کیا، اس نے اسے تلوار سے مارا لیکن تلوار نے خطا کی اور اچٹ کر اسی کو لگ گئی، تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\"مسلمانوں کی جماعت! اپنے مسلمان بھائی کی خبر لو\"، لوگ تیزی سے اس کی طرف دوڑے، تو اسے مردہ پایا، چنانچہ رسول اللہ صلی اللہ علیہ وسلم نے اسے اسی کے کپڑوں اور زخموں میں لپیٹا، اس پر نماز جنازہ پڑھی اور اسے دفن کر دیا، لوگوں نے پوچھا: اللہ کے رسول! کیا وہ شہید ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا: \"ہاں اور میں اس کا گواہ ہوں\"۔","ضعیف",{"u2":"جناب ابو سلام، نبی کریم صلی اللہ علیہ وسلم کے ایک صحابی سے روایت کرتے ہیں ‘ انہوں نے بیان کیا کہ ہم نے جہینہ کے ایک قبیلے پر حملہ کیا۔ پس مسلمانوں میں سے ایک آدمی نے ان کے ایک آدمی پر وار کیا اور اسے مارنا چاہا مگر اس کا وار خطا گیا اور اس کی تلوار خود اسے ہی لگ گئی تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ’’ اے مسلمانو! تمہارا بھائی! (اس کی خبر لو)۔ ‘‘ لوگ بھاگ کر اس کی طرف گئے تو دیکھا کہ وہ فوت ہو چکا ہے ‘ رسول اللہ صلی اللہ علیہ وسلم نے اس کو اسی کے کپڑوں میں خون سمیت لپیٹ دیا ‘ اس کی نماز جنازہ پڑھی اور اسے دفن کر دیا۔ لوگوں نے پوچھا۔ اے اللہ کے رسول! کیا وہ شہید ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا ’’ ہاں اور میں اس کے لیے گواہ ہوں۔ ‘‘"}],[2540,"سہل بن سعد رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"دو (وقت کی) دعائیں رد نہیں کی جاتیں، یا کم ہی رد کی جاتی ہیں: ایک اذان کے بعد کی دعا، دوسرے لڑائی کے وقت کی، جب دونوں لشکر ایک دوسرے سے بھڑ جائیں\"۔ موسی کہتے ہیں: مجھ سے رزق بن سعید بن عبدالرحمٰن نے بیان کیا وہ ابوحازم سے روایت کرتے ہیں وہ سہل بن سعد رضی اللہ عنہ سے اور وہ نبی اکرم صلی اللہ علیہ وسلم سے آپ نے فرمایا: \"اور بارش کے وقت کی\"۔","صحیح",{"u2":"سیدنا سہل بن سعد رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ’’ دو وقت کی دعائیں رد نہیں کی جاتیں یا بہت کم رد کی جاتی ہیں۔ ایک اذان کے وقت اور دوسری جنگ کے وقت ‘ جب لوگ ایک دوسرے کے ساتھ بھڑ جاتے ہیں۔ ‘‘ موسیٰ (بن یعقوب) نے کہا: مجھے رزق بن سعید بن عبدالرحمٰن نے ابوحازم سے ‘ اس نے سہل بن سعد رضی اللہ عنہ سے اور انہوں نے نبی کریم صلی اللہ علیہ وسلم سے بیان کیا ’’ بارش کے وقت (بھی دعا رد نہیں کی جاتی)۔ ‘‘","f2":"اذان اور قتال دونوں عمل اللہ کا کلمہ بلند کرنے کے لئے ہیں۔لہذا ان اوقات م میں دعایئں قبول ہوتی ہیں۔ درج زیل حدیث میں جہاد میں معمولی وقت لگانے کی فضیلت کا زکر آرا ہے۔خیال رہے کہ بارش کے وقت کا جملہ صحیح سند سے ثابت نہیں ہے۔ (علامہ البانی)"}],[2541,"معاذ بن جبل رضی اللہ عنہ کہتے ہیں کہ انہوں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا: \"جس نے اللہ کے راستہ میں اونٹنی دوہنے والے کے دو بار چھاتی پکڑنے کے درمیان کے مختصر عرصہ کے بقدر بھی جہاد کیا اس کے لیے جنت واجب ہو گئی، اور جس شخص نے اللہ سے سچے دل کے ساتھ شہادت مانگی پھر اس کا انتقال ہو گیا، یا قتل کر دیا گیا تو اس کے لیے شہید کا اجر ہے، اور جو اللہ کی راہ میں زخمی ہوا یا کوئی چوٹ پہنچایا ۱؎ گیا تو وہ زخم قیامت کے دن اس سے زیادہ کامل شکل میں ہو کر آئے گا جتنا وہ تھا، اس کا رنگ زعفران کا اور بو مشک کی ہو گی اور جسے اللہ کے راستے میں پھنسیاں (دانے) نکل آئیں تو اس پر شہداء کی مہر لگی ہو گی\"۔\n§وضاحت\n۱؎ : «جرح» اور «نکبۃ» دونوں ایک معنی میں ہیں اور ایک قول کے مطابق «جرح» وہ زخم جو کافروں سے پہنچے، اور«نکبۃ» وہ ہے جو سواری سے گرنے اور اپنے ہی ہتھیار کے اچٹ کر لگنے کی وجہ سے ہو۔","صحیح",{"u2":"سیدنا معاذ بن جبل رضی اللہ عنہ سے روایت ہے کہ انہوں نے رسول اللہ صلی اللہ علیہ وسلم کو سنا آپ صلی اللہ علیہ وسلم فرماتے تھے ’’ اگر کسی نے اونٹنی کو دوبارہ دوہنے کے وقفہ کے برابر بھی قتال کیا تو اس کے لیے جنت واجب ہے ‘ اور جس نے اللہ سے سچے دل سے قتل فی سبیل اللہ کی دعا مانگی پھر فوت ہو گیا یا قتل کر دیا گیا تو اس کے لیے شہید کا ثواب ہے۔ ‘‘ ابن المصفی نے یہاں اضافہ کیا ’’ اور جسے (دشمن کی طرف سے) اللہ کی راہ میں کوئی زخم آ گیا یا کوئی چوٹ لگ گئی تو قیامت کے دن وہ زخم اسی طرح (تازہ) اور بڑا ہو گا جیسے کہ وہ تھا ‘ اس کے خون کا رنگ زعفران کا اور خوشبو کستوری کی ہو گی ‘ اور جسے اللہ کی راہ میں کوئی پھوڑا نکل آیا تو اس پر شہیدوں کے جیسی مہر ہو گی۔ ‘‘","f2":"1۔اونٹنی ایک بار دوہنے کے بعد چند منٹ کے لئے وقفہ دیاجا تا ہے۔اور پھردوبارہ دوہتے ہیں۔ اس درمیانی وقفے کو (فواق) سے تعبیر کیا جاتا ہے۔2۔اخلاص نیت کی وجہ سے انسان بہت بڑے درجات حاصل کرلیتا ہے۔ خواہ بالفعل عمل کر کے اس مقام تک نہ بھی پہنچ سکے۔"}],[2542,"عتبہ بن عبدسلمی رضی اللہ عنہ کہتے ہیں کہ انہوں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا: \"گھوڑوں کی پیشانی کے بال نہ کاٹو، اور نہ ایال یعنی گردن کے بال کاٹو، اور نہ دم کے بال کاٹو، اس لیے کہ ان کے دم ان کے لیے مورچھل ہیں، اور ان کے ایال(گردن کے بال) گرمی حاصل کرنے کے لیے ہیں اور ان کی پیشانی میں خیر بندھا ہوا ہے ۱؎\"۔\n§وضاحت\n۱؎ : اس کے رہنے میں برکت ہے، بہتری ہے اور زینت بھی ہے۔","صحیح",{"u2":"سیدنا عتبہ بن عبد سلمی رضی اللہ عنہ نے رسول اللہ صلی اللہ علیہ وسلم سے سنا، آپ صلی اللہ علیہ وسلم فر رہے تھے ’’ گھوڑوں کی پیشانیوں، گردنوں اور دموں کے بال نہ کاٹو، بلاشبہ ان کی دمیں ان کے پنکھے ہیں (کہ وہ ان سے مکھیوں وغیرہ کو دور کرتے ہیں) اور گردنوں کے بالوں سے یہ اپنی سردی دور کرتے ہیں اور پیشانیوں کے بالوں کے ساتھ خیر و برکت بندھی ہوئی ہے۔ ‘‘","f2":"جن معمولات کے مطابق شرعی ہدایات آجایئں وہ عام معمولات اور عادات سے نکل کر شرعی مسائل بن جاتے ہیں۔جن کی اہمیت واضح ہے۔ان میں سے ایک گھوڑوں کی تربیت کا یہ مسئلہ بھی ہے۔"}],[2543,"ابو وہب جشمی سے روایت ہے اور انہیں اللہ کے رسول صلی اللہ علیہ وسلم کی صحبت حاصل تھی، وہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"تم اپنے اوپر ہر چتکبرے سفید پیشانی اور سفید ہاتھ پاؤں کے یا سرخ سفید پیشانی اور سفید ہاتھ پاؤں کے یا کالے سفید پیشانی اور سفید ہاتھ پاؤں کے گھوڑے کو لازم پکڑو\"۔","حسن",{"u2":"سیدنا ابو وہب جشمی رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ’’ ایسے گھوڑے منتخب کیا کرو جو کمیت اور پانچ کلیان ہوں (رنگ سرخ سیاہ ہو مگر پیشانی اور چاروں پاؤں سفید ہوں) یا اشقر پانچ کلیان ہوں (رنگ سرخ ہو اور پیشانی اور چاروں پاؤں سفید ہوں) یا مشکی (سیاہ رنگ) اور پانچ کلیان ہوں۔ ‘‘","f2":"علامہ طیبی نے ان رنگوں میں ایک فرق یہ بھی لکھاہے کہ اشقر میں سرخی پر سیاحی غالب ہوتی ہے۔اور کمیت کی گردن اور دم کے بال سیاہ ہوتے ہیں۔\nفائدہ۔جب گھوڑوں کے اختیار وانتخاب کا معاملہ ہو تو مندرجہ بالا صفات کا خیال رکھنا مستحب ہے۔اس سے استدلال یہ بھی ہے کہ دیگر آلات جہاد حاصل کرتے وقت ان کے ظاہر ی محاسن اور عمدہ کارکردگی کو پیش نظر رکھنا چاہیے۔"}],[2544,"ابو وہب رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"تم اپنے اوپر ہر سرخ سفید پیشانی اور سفید ہاتھ پاؤں کے یا ہر چتکبرے سفید پیشانی کے گھوڑے لازم پکڑو ۱؎\"، پھر راوی نے اسی طرح ذکر کیا۔ محمد یعنی ابن مہاجر کہتے ہیں: میں نے عقیل سے پوچھا: سرخ رنگ کے گھوڑے کی فضیلت کیوں ہے؟ انہوں نے کہا: اس وجہ سے کہ نبی اکرم صلی اللہ علیہ وسلم نے ایک سریہ بھیجا تو سب سے پہلے جو شخص فتح کی بشارت لے کر آیا وہ سرخ گھوڑے پر سوار تھا۔\n§وضاحت\n۱؎ : «أشقر» سرخ گھوڑے کو کہتے ہیں، اور اس کی دم بھی سرخ ہوتی ہے، اور «كميت» کی دم اور بال سیاہ ہوتے ہیں۔","حسن",{"u2":"سیدنا ابو وہب رضی اللہ عنہ کا بیان ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ’’ گھوڑا ایسا منتخب کرو جو اشقر پانچ کلیان ہو (سرخ رنگ) یا کمیت سفید پیشانی۔ ‘‘ اور مذکورہ حدیث کی مانند ذکر کیا۔ محمد بن مہاجر کہتے ہیں: میں نے اپنے شیخ سے دریافت کیا کہ اشقر کو فضیلت کیوں ہے؟ تو انہوں نے کہا: کیونکہ نبی کریم صلی اللہ علیہ وسلم نے ایک مہم بھیجی تو جو شخص سب سے پہلے فتح کی خوشخبری لے کر آیا وہ اشقر گھوڑے پر سوار تھا۔"}],[2545,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"گھوڑے کی برکت سرخ رنگ کے گھوڑے میں ہے۱؎\"۔\n§وضاحت\n۱؎ : یعنی ان میں توالد و تناسل زیادہ ہوتا ہے۔","حسن",{"u2":"سیدنا ابن عباس رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ’’ گھوڑوں میں برکت ان کے سرخ رنگ والوں میں ہے۔ ‘‘","f2":"جب گھوڑوں کے اختیار وانتخاب کا معاملہ ہو تو مندرجہ بالا صفات کا خیال رکھنا مستحب ہے۔اس سے استدلال یہ بھی ہے کہ دیگر آلات جہاد حاصل کرتے وقت ان کے ظاہر ی محاسن اور عمدہ کارکردگی کو پیش نظر رکھنا چاہیے۔"}],[2546,"ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم گھوڑے کی مادہ کو بھی «فرس» کا نام دیتے تھے۔","صحیح",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم مادہ گھوڑی کو ’’ فرس ‘‘ کہا کرتے تھے۔","f2":"رسول اللہ صلی اللہ علیہ وسلم افصح العرب تھے۔اور آپ صلی اللہ علیہ وسلم کی زبان منتخب اور معیاری زبان تھی ایسے ہی واعیان دین کو لاز م ہے۔کہ اپنی اپنی زبان کے فصیح وبلیغ عالم بنیں۔اس طرح ان کا عمل دعوت دوچند ہوجائے گا۔غلط الفاظ اور بھدی گفتگو کرنے والے کی بات سنی جاتی ہے۔ نہ موثر ہوتی ہے۔"}],[2547,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم گھوڑے میں «شکال» کو ناپسند فرماتے تھے، اور «شکال» یہ ہے کہ گھوڑے کے دائیں پیر اور بائیں ہاتھ میں، یا دائیں ہاتھ اور بائیں پیر میں سفیدی ہو ۱؎۔ ابوداؤد کہتے ہیں: یعنی دائیں اور بائیں ایک دوسرے کے مخالف ہوں۔\n§وضاحت\n۱؎ : یہ روای نے «شکال» کی تفسیر کی ہے، اہل لغت کے نزدیک گھوڑوں میں «شکال» یہ ہے کہ اس کے تین پاؤں سفید ہوں، اور ایک باقی بدن کے ہم رنگ ہو یا اس کے برعکس ہو، یعنی ایک پاؤں سفید اور باقی تین پاؤں باقی بدن کے ہم رنگ ہیں۔","صحیح",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم شکال قسم کے گھوڑوں کو ناپسند فرماتے تھے۔ اور شکال سے مراد یہ ہے کہ اس کے دائیں پاؤں اور بائیں ہاتھ میں سفیدی ہو یا دائیں ہاتھ اور بائیں پاؤں میں سفیدی ہو۔ امام ابوداؤد رضی اللہ عنہ نے وضاحت کی کہ ہاتھ پاؤں میں سفیدی مخالف جاتی ہو۔","f2":"شکال کی یہ تفسیر مدرج ہے۔یعنی نبی کریم صلی اللہ علیہ وسلم کی بیان کردہ نہیں ہے۔ بلکہ راوی کی طرف سے ہے۔اسی لئے امام نووی رحمہ اللہ نے اس کی تفسیر میں مختلف اقوال نقل کئے ہیں۔کراہت کی بھی بعض توجہیات بیان کی گئی ہیں۔اصل حقیقت اللہ تعالیٰ ہی جانتا ہے۔(عون المعبود)"}],[2548,"سہل بن حنظلیہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم ایک ایسے اونٹ کے پاس سے گزرے جس کا پیٹ اس کی پشت سے مل گیا تھا، تو آپ صلی اللہ علیہ وسلم نے فرمایا: \"ان بے زبان چوپایوں کے سلسلے میں اللہ سے ڈرو، ان پر سواری بھلے طریقے سے کرو اور ان کو بھلے طریقے سے کھاؤ ۱؎\"۔\n§وضاحت\n۱؎ : یعنی انہیں اس وقت کھاؤ جب وہ کھانے کے لائق موٹے اور تندرست ہوں۔","صحیح",{"u2":"سیدنا سہل بن حنظلیہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم ایک اونٹ کے پاس سے گزرے جس کا پیٹ اس کی کمر سے لگ گیا تھا تو آپ صلی اللہ علیہ وسلم نے فرمایا ’’ ان بے زبان جانوروں کے بارے میں اللہ سے ڈرو، ان پر سواری کرو تو بھلے انداز میں اور کھلاؤ تو بھی عمدہ طرح سے۔ ‘‘","f2":"مومن(سی الملکۃ) نہیں ہوتا یعنی اپنی مملوکہ چیزوں سے بُرا سلوک نہیں کرتا۔"}],[2549,"عبداللہ بن جعفر رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے مجھے ایک دن اپنے پیچھے سوار کیا پھر مجھ سے چپکے سے ایک بات کہی جسے میں کسی سے بیان نہیں کروں گا، رسول اللہ صلی اللہ علیہ وسلم کو بشری ضرورت کے تحت چھپنے کے لیے دو جگہیں بہت ہی پسند تھیں، یا تو کوئی اونچا مقام، یا درختوں کا جھنڈ، ایک بار آپ صلی اللہ علیہ وسلم کسی انصاری کے باغ میں تشریف لے گئے تو سامنے ایک اونٹ نظر آیا جب اس نے نبی اکرم صلی اللہ علیہ وسلم کو دیکھا تو رونے لگا اور اس کی آنکھوں سے آنسو بہنے لگے، نبی اکرم صلی اللہ علیہ وسلم اس کے پاس آئے، اس کے سر پر ہاتھ پھیرا تو وہ خاموش ہو گیا، اس کے بعد پوچھا: \"یہ اونٹ کس کا ہے؟\" ایک انصاری جوان آیا، وہ کہنے لگا: اللہ کے رسول! میرا ہے، آپ صلی اللہ علیہ وسلم نے فرمایا: \"کیا تم ان جانوروں کے سلسلے میں جن کا اللہ نے تمہیں مالک بنایا ہے اللہ سے نہیں ڈرتے، اس اونٹ نے مجھ سے شکایت کی ہے کہ تو اس کو بھوکا مارتا اور تھکاتا ہے\"۔","صحیح",{"u2":"سیدنا عبداللہ بن جعفر رضی اللہ عنہ بیان کرتے ہیں کہ ایک دن رسول اللہ صلی اللہ علیہ وسلم نے مجھے اپنے ساتھ سواری پر پیچھے بٹھا لیا اور خاموشی سے مجھے ایک بات بتائی جو میں کسی کو بھی نہیں بتاؤں گا، اور رسول اللہ صلی اللہ علیہ وسلم کو قضائے حاجت کے لیے چھپنے کی دو جگہیں بہت زیادہ پسند تھیں۔ یا تو کوئی اونچی جگہ ہوتی، یا کوئی کھجوروں کا جھنڈ ہوتا۔ آپ ایک بار ایک انصاری کے باغ میں تشریف لے گئے تو وہاں ایک اونٹ تھا، جب اس نے نبی کریم صلی اللہ علیہ وسلم کو دیکھا تو رونی سی آواز نکالی اور اس کی آنکھوں سے آنسو بہنے لگے، نبی کریم صلی اللہ علیہ وسلم اس کے پاس آئے اور اس کے سر پر ہاتھ پھیرا تو وہ چپ ہو گیا۔ پھر آپ صلی اللہ علیہ وسلم نے پوچھا ’’ اس اونٹ کا مالک کون ہے؟ یہ کس کا اونٹ ہے؟ تو ایک انصاری جوان آیا اور کہا: اے اللہ کے رسول! یہ میرا ہے۔ آپ صلی اللہ علیہ وسلم نے فرمایا ’’ کیا تو اس جانور کے بارے میں اللہ سے نہیں ڈرتا جس کا اس نے تجھ کو مالک بنایا ہے ‘ اس نے مجھ سے شکایت کی ہے کہ تو اسے بھوکا رکھتا اور بہت تھکاتا ہے۔ ‘‘","f2":"1۔اونٹ کا نبی کریم صلی اللہ علیہ وسلم کو پہچان لینااور آپ کے سامنے مالک کا اپنے انداز میں شکوہ کرنا نبی کریم صلی اللہ علیہ وسلم کامعجزہ ہے۔2۔جانور سے اسی قدر کام لینا چاہیے۔ جو اس کی طاقت وہمت کے مطابق ہو۔زیادہ کام لینا اور پھر خدمت بھی نہ کرنا حرام ہے۔اورخادم کا معاملہ بھی اسی طرح ہے۔"}],[2550,"ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"ایک آدمی کسی راستہ پہ جا رہا تھا کہ اسی دوران اسے سخت پیاس لگی، (راستے میں) ایک کنواں ملا اس میں اتر کر اس نے پانی پیا، پھر باہر نکلا تو دیکھا کہ ایک کتا ہانپ رہا ہے اور پیاس کی شدت سے کیچڑ چاٹ رہا ہے، اس شخص نے دل میں کہا: اس کتے کا پیاس سے وہی حال ہے جو میرا حال تھا، چنانچہ وہ (پھر) کنویں میں اترا اور اپنے موزوں کو پانی سے بھرا، پھر منہ میں دبا کر اوپر چڑھا اور (کنویں سے نکل کر باہر آ کر) کتے کو پلایا تو اللہ تعالی نے اس کا یہ عمل قبول فرما لیا اور اسے بخش دیا\"، لوگوں نے کہا: اللہ کے رسول! کیا ہمارے لیے چوپایوں میں بھی ثواب ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا: \"ہر تر کلیجہ والے (جاندار) میں ثواب ہے\"۔","صحیح",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ’’ ایک آدمی کسی راستے میں جا رہا تھا کہ اسے بہت پیاس لگی ‘ اسے ایک کنواں ملا، وہ اس میں اترا، پانی پیا اور باہر نکلا تو اس نے ایک کتا دیکھا جو ہانپ رہا تھا اور پیاس کی وجہ سے گیلی مٹی چاٹ رہا تھا اس آدمی نے سوچا کہ اس کتے کو بھی پیاس نے ستایا ہے جیسے کہ مجھے ستایا تھا۔ پس وہ دوبارہ کنویں میں اترا، اپنے موزے کو پانی سے بھر کر اپنے منہ سے پکڑا اور اوپر چڑھ کر کتے کو پلایا، سو اللہ تعالیٰ نے اس کا یہ عمل قبول فر لیا اور اسے بخش دیا۔ ‘‘ صحابہ نے کہا: اے اللہ کے رسول! کیا ہمارے لیے جانوروں کی خدمت میں بھی ثواب ہے۔ آپ صلی اللہ علیہ وسلم نے فرمایا ’’ ہر گیلے جگر (جاندار) میں ثواب ہے۔ ‘‘","f2":"1۔لوگوں کے لئے سرائوں اور ان کے راستوں میں پانی کا انتظام کرنا بہت بڑی نیکی کا کام ہے۔2۔انسان مسلمان ہو یا کافر اس کے ساتھ اور ایسے ہی جاندار مخلوق کے ساتھ احسان کرنا۔بڑے اجر کی بات ہے۔البتہ واجب القتل اور موذی جانور اس احسان سے مستثنیٰ ہیں۔جیسے کہ خنزیر۔ سانپ ‘بچھو وغیرہ"}],[2551,"حمزہ ضبی کہتے ہیں کہ میں نے انس بن مالک رضی اللہ عنہ کو کہتے سنا کہ ہم کسی جگہ اترتے تو نماز نہ پڑھتے جب تک کہ ہم کجاؤں کو اونٹوں سے نیچے نہ اتار دیتے۔","صحیح",{"u2":"سیدنا انس بن مالک رضی اللہ عنہ نے بیان کیا کہ ہم جب کسی منزل پر اترتے تو اس وقت تک نماز نہ پڑھتے تھے جب تک کہ اونٹوں پر سے کجاوے نہ اتار لیتے۔","f2":"جس طرح انسان کو آرام اور راحت کی ضرورت ہوتی ہے۔اسی طرح حیوانات کا بھی خیال رکھناچاہیے۔اسی لئے بعض علماء یہ مستحب سمجھتے ہیں۔ کہ انسان جب کسی منزل پر اترے تو چاہیے کہ پہلے اپنے جانور کو چارہ ڈالے پھر خود کھانا کھائے۔یہ تعلیمات اسلام کے دین فطرت اورعالمی دین ہونے کی دلیل ہے۔"}],[2552,"ابوبشیر انصاری رضی اللہ عنہ کہتے ہیں کہ وہ رسول اللہ صلی اللہ علیہ وسلم کے ساتھ ایک سفر میں تھے تو رسول اللہ صلی اللہ علیہ وسلم نے ایک قاصد کے ذریعہ پیغام بھیجا، لوگ اپنی خواب گاہوں میں تھے: \"کسی اونٹ کی گردن میں کوئی تانت کا قلادہ باقی نہ رہے، اور نہ ہی کوئی اور قلادہ ہو مگر اسے کاٹ دیا جائے\"۔ مالک کہتے ہیں: میرا خیال ہے لوگ یہ گنڈا نظر بد سے بچنے کے لیے باندھتے تھے۔","صحیح",{"u2":"سیدنا ابوبشیر انصاری رضی اللہ عنہ کا بیان ہے کہ وہ ایک سفر میں رسول اللہ صلی اللہ علیہ وسلم کے ساتھ تھے۔ کہ رسول اللہ صلی اللہ علیہ وسلم نے ایک پیغامبر بھیجا، راوی حدیث عبداللہ بن ابی بکر کا کہنا ہے: میرا خیال ہے کہ شیخ نے بیان کیا: لوگ رات کی آرام گاہ میں تھے (آپ صلی اللہ علیہ وسلم نے کہلا بھیجا کہ) ” کسی اونٹ کے گلے میں کوئی تانت یا کوئی قلادہ باقی نہ چھوڑا جائے مگر اسے کاٹ ڈالا جائے۔ “ امام مالک رضی اللہ عنہ فرماتے ہیں: میرا خیال ہے ‘ بدنظری سے بچاؤ کے لیے یہ ڈالتے تھے۔","f2":"علامہ خطابی لکھتے ہیں کہ امام مالک کی وجہ یہ بتاتے ہیں کہ لوگ اسے نظر بدسے بچائو کےلئے بطور تعویذ ڈالتے تھے۔اور اسے ہی موثر سمجھتے تھے۔ کئی علماء کا خیال ہے کہ لوگ یہ ان کے گلوں میں گھنٹیاں باندھنے کے لئے ڈالتے تھے۔کچھ نے کہا کہ ایسا نہ ہو کہ دوڑتے بھاگتے ہوئے جانور کا گلا گھٹ جائے۔بہر حال وجہ کوئی بھی ہو تانت ڈالنے سے منع فرمایا گیا ہے۔اور اسی طرح دیگر جاہلانہ تعویز گنڈے بھی ڈالنا جائز نہیں۔"}],[2553,"ابو وہب جشمی رضی اللہ عنہ سے روایت ہے انہیں (اللہ کے رسول صلی اللہ علیہ وسلم کی) صحبت حاصل تھی - وہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"گھوڑوں کو سرحد کی حفاظت کے لیے تیار کرو، اور ان کی پیشانیوں اور پٹھوں پر ہاتھ پھیرا کرو، اور ان کی گردنوں میں قلادہ (پٹہ) پہناؤ، اور انہیں (نظر بد سے بچنے کے لیے) تانت کا قلادہ نہ پہنانا\"۔\n§وضاحت\n۱؎ : گھوڑے کو تیار کرنے سے یہ کنایہ ہے کہ ان کو جہاد کے لئے فربہ کرنا، اور ہاتھ پھیرنے سے مقصود ان کے جسم کو گردوغبار سے صاف کرنا اور ان کی فربہی معلوم کرنا ہے۔ زمانہ جاہلیت میں گھوڑے کی گردنوں میں کمان کے چلے باندھتے تھے تاکہ نظر بد نہ لگے، آپ صلی اللہ علیہ وسلم نے تنبیہ کے لئے اس سے منع فرمایا کہ اس سے گھوڑے کا گلا نہ گھٹ جائے، نیز یہ عمل تقدیر کو رد نہیں کر سکتا۔","حسن",{"u2":"صحابی رسول سیدنا ابو وہب جشمی رضی اللہ عنہ کا بیان ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” گھوڑوں کو باندھ کر رکھو (ان کی خوب دیکھ بھال کرو) ان کی پیشانیوں اور سرینوں پر ہاتھ پھیرا کرو۔ “ راوی کو شک ہے کہ آپ نے لفظ «أعجازها» کہا یا «أكفالها» اور گردنوں میں رسیاں باندھو مگر تانت کی رسی نہ ہو۔ “","f2":"گھوڑا محبت کرنے والا جانور ہے۔اور جہاد میں کام آنے کی وجہ سے محبوب ہے۔اس لئے اس کی خوب خدمت کرنی چاہیے۔اور انس ومحبت کا اظہار کرناچاہیے۔اس عمل سے جانورخوش ہوتاہے۔"}],[2554,"ام المؤمنین ام حبیبہ رضی اللہ عنہا نبی اکرم صلی اللہ علیہ وسلم سے روایت کرتی ہیں کہ آپ نے فرمایا: \"(رحمت کے) فرشتے ۱؎ اس جماعت کے ساتھ نہیں ہوتے جس کے ساتھ گھنٹی ہو\"۔\n§وضاحت\n۱؎ : اس سے مراد «حَفَظَه» کے علاوہ فرشتے ہیں کیونکہ «حَفَظَه» ہمیشہ ساتھ رہتے ہیں۔","صحیح",{"u2":"ام المؤمنین سیدہ ام حبیبہ رضی اللہ عنہا ا بیان کرتی ہیں کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا ” جس قافلہ اور جماعت میں گھنٹی ہو ‘ فرشتے اس کے ساتھ نہیں ہوتے۔ “"}],[2555,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"(رحمت کے فرشتے) اس جماعت کے ساتھ نہیں رہتے ہیں جس کے ساتھ کتا یا گھنٹی ہو\"۔","صحیح",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ سے منقول ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” فرشتے اس جماعت کے ساتھ نہیں چلتے جن کے ساتھ کتا ہو یا گھنٹی۔ “"}],[2556,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے گھنٹی کے بارے میں فرمایا: \"وہ شیطان کی بانسری ہے\"۔","صحیح",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ نے بیان کیا کہ رسول اللہ صلی اللہ علیہ وسلم نے گھنٹی کے متعلق فرمایا ” یہ شیطان کا باجا ہے۔ “","f2":"1۔جانوروں کے گلے میں گھنٹیاں اور گھنگرو قسم کی چیزیں باندھناجائز نہیں۔2۔موسیقی کے دوسرے آلات کی حرمت بھی احادیث سے ثابت ہے۔3۔ایسے ہی کتارکھنااگر محض اظہار ہیبت اور زینت کےلئے ہوتو ناجائز ہے۔حفاظت کی نیت سے ہو تو جائز ہے۔"}],[2557,"عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ گندگی کھانے والے جانور کی سواری سے منع کیا گیا ہے۔","صحیح",{"u2":"سیدنا ابن عمر رضی اللہ عنہ سے روایت ہے فرمایا کہ ایسے جانور پر سواری کرنے سے منع کیا گیا ہے جو گندگی کھاتا ہو۔"}],[2558,"عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے گندگی کھانے والے اونٹوں کی سواری کرنے سے منع فرمایا ہے۔","حسن صحیح",{"u2":"سیدنا ابن عمر رضی اللہ عنہ سے منقول ہے انہوں نے فرمایا کہ رسول اللہ صلی اللہ علیہ وسلم نے ایسے اونٹ کی سواری سے منع فرمایا جو گندگی کھاتا ہو۔","f2":"دیگر احادیث میں ایسے جانور کا دودھ پینے اور اس کا گوشت کھانے کی بھی ممانعت وارد ہے۔دیکھئے۔(سنن ابی دائود۔الاطعمۃ حدیث 3785)"}],[2559,"معاذ رضی اللہ عنہ کہتے ہیں کہ میں ایک گدھے پر رسول اللہ صلی اللہ علیہ وسلم کے پیچھے سوار تھا جس کو «عفیر» کہا جاتا تھا ۱؎۔\n§وضاحت\n۱؎ : پیچھے سواری پر کسی کو بٹھایا جا سکتا ہے بشرطیکہ جانور اس دوسرے سوار کا بوجھ برداشت کرنے کے قابل ہو، اسی طرح جانوروں کا نام بھی رکھا جا سکتا ہے، چنانچہ رسول اللہ صلی اللہ علیہ وسلم کے خچر کا نام «دلدل» اور گھوڑوں میں سے ایک کا نام «سکب»اور ایک کا «بحر» تھا۔","صحیح",{"u2":"سیدنا معاذ بن جبل رضی اللہ عنہ بیان کرتے ہیں کہ میں رسول اللہ صلی اللہ علیہ وسلم کے ساتھ ایک گدھے پر آپ صلی اللہ علیہ وسلم کے پیچھے بیٹھا ہوا تھا جسے ” عفیر “ کہا جاتا تھا۔","f2":"جانور کا نام رکھنا مباح ہے۔2۔بوقت ضرورت جانور پردو آدمی بھی سوار ہوسکتے ہیں۔3۔اگرکسی جانورپر دو آدمی سوار ہوجایئں تو یہ ظلم شمار نہیں ہوگا۔بشرط یہ کہ جانور صحت مند اور اس قدربوجھ اٹھا سکتا ہو۔"}],[2560,"سمرہ بن جندب رضی اللہ عنہ سے روایت ہے ، وہ حمد و صلاۃ کے بعد کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم ہمارے سواروں کو جب ہمیں دشمن سے گھبراہٹ ہوتی (تسلی دیتے ہوئے) «خیل اللہ» کہتے، اور ہمیں جماعت کو لازم پکڑنے اور صبر و سکون سے رہنے کا حکم دیتے، اور جب ہم قتال کر رہے ہوتے (تو بھی انہیں کلمات کے ذریعہ ہمارا حوصلہ بڑھاتے) ۔","ضعیف",{"u2":"سیدنا سمرہ بن جندب رضی اللہ عنہ سے روایت ہے کہ امابعد: نبی کریم صلی اللہ علیہ وسلم ہمارے سواروں کو، جب ہم گھبراتے تو «خيل الله» ” ا اللہ کے شہسوار بندو! “ کہہ کر پکارتے، اور رسول اللہ صلی اللہ علیہ وسلم ہمیں حکم دیتے تھے کہ جب خوف اور گھبراہٹ کی کیفیت ہو تو اکٹھے ہو جایا کریں “ صبر اور سکون سے کام لیں اور ایسے ہی قتال کے وقت کیا کریں۔"}],[2561,"عمران بن حصین رضی اللہ عنہما سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم ایک سفر میں تھے، آپ نے لعنت کی آواز سنی تو پوچھا:\"یہ کیا ہے؟\" لوگوں نے کہا: فلاں عورت ہے جو اپنی سواری پر لعنت کر رہی ہے، اس پر نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"اس اونٹنی سے کجاوہ اتار لو کیونکہ وہ ملعون ہے ۱؎\"، لوگوں نے اس پر سے (کجاوہ) اتار لیا۔ عمران رضی اللہ عنہ کہتے ہیں: گویا میں اسے دیکھ رہا ہوں، وہ ایک سیاہی مائل اونٹنی تھی۔\n§وضاحت\n۱؎ : علماء کا کہنا ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے ایسا اس لئے کیا تاکہ جانور کا مالک آئندہ کسی جانور پر لعنت نہ بھیجے، گویا آپ صلی اللہ علیہ وسلم کا یہ فرمان اس مالک کے لئے بطور سرزنش تھا۔","صحیح",{"u2":"سیدنا عمران بن حصین رضی اللہ عنہ سے منقول ہے کہ نبی کریم صلی اللہ علیہ وسلم ایک سفر میں تھے، پس آپ صلی اللہ علیہ وسلم نے (کسی سے) لعنت کرنے کی آواز سنی تو آپ صلی اللہ علیہ وسلم نے پوچھا: ” یہ کیا ہے؟ “ صحابہ نے کہا: فلاں عورت ہے جس نے اپنی سواری کو لعنت کی ہے۔ تو نبی کریم صلی اللہ علیہ وسلم نے فرمایا ” اس سے (کجاوہ اور سامان) اتار دو۔ بلاشبہ یہ اب ملعونہ ہے۔ “ چنانچہ صحابہ نے اس سے (سامان وغیرہ) اتار دیا۔ عمران کہتے ہیں: گویا میں اس کی طرف دیکھ رہا ہوں کہ وہ سیاہی مائل اونٹنی تھی۔","f2":"لعنت کے لغوی معنی ہیں۔اللہ کی پھنکار اور اس کی رحمت سے دوری اور انتہائی یہ بری خصلت ہے کہ انسان ایک چیز سے فائدہ بھی اٹھائے۔اور پھر اس کے متعلق لعنت کا لفظ بھی استعمال کرے۔نبی کریم صلی اللہ علیہ وسلم نے غالبا بطور زجر وتوبیخ کے اس جانور کو اس کے سوار سے آذاد کروادیا تھا۔تاکہ آئندہ ک ےلئے کوئی اس طرح سے نہ بولے لوگوں کا آپس میں یہ لفظ استعمال کرنا اور بھی قبیح ہے۔"}],[2562,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے جانوروں کو باہم لڑانے سے منع فرمایا ۱؎۔\n§وضاحت\n۱؎ : منع کرنے کی وجہ یہ ہے کہ اس عمل سے جانوروں کو تکلیف پہنے گی، اور تکان لاحق ہو گی جو بلا کسی فائدہ کے ہو گی۔","ضعیف",{"u2":"سیدنا ابن عباس رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے اس بات سے منع فرمایا ہے کہ جانوروں کو آپس میں لڑایا جائے۔","f2":"بہ اعتبار سند کے یہ روایت ضعیف ہے۔ مگر بلحاظ معنی بات ایسے ہی ہے۔کے یہ عمل کس طرح بھی شرفاء کے لائق نہیں ہے۔عوام کو بھی اس سے باز رکھنے کی کوشش کرنی چاہیے۔اور جب جانوروں کو لڑانے کی ممانعت ہے۔تو لوگوں کے درمیان لڑائی کروادینا تو اور بھی بدترین خصلت ہے۔"}],[2563,"انس بن مالک رضی اللہ عنہ کہتے ہیں کہ میں اپنے بھائی کی پیدائش پر اس کو نبی اکرم صلی اللہ علیہ وسلم کے پاس لے کر آیا تاکہ آپ اس کی تحنیک (گھٹی) ۱؎ فرما دیں، تو دیکھا کہ آپ صلی اللہ علیہ وسلم جانوروں کے ایک باڑہ میں بکریوں کو نشان (داغ) لگا رہے تھے۔ ہشام کہتے ہیں: میرا خیال ہے کہ انس رضی اللہ عنہ نے کہا: ان کے کانوں پر داغ لگا رہے تھے۔\n§وضاحت\n۱؎ : ’’تحنيك‘‘ یہ ہے کہ کھجور یا اسی جیسی کوئی میٹھی چیز منہ میں چبا کر بچے کے منہ میں رکھ دیا جائے تا کہ اس کی مٹھاس کا اثر بچے کے پیٹ میں پہنچ جائے، رسول اکرم صلی اللہ علیہ وسلم سے تحنیک کا مقصد برکت کا حصول تھا، اور چیز غیر نبی میں متحقق نہیں ہے اس لئے دوسروں سے تحنیک کرانے کا کوئی فائدہ نہیں نیز بزرگ شخصیات سے تحنیک کا تحنیک نبوی پر قیاس صحیح نہیں ہے۔","صحیح",{"u2":"سیدنا انس بن مالک رضی اللہ عنہ کا بیان ہے کہ میرے بھائی (عبداللہ بن ابی طلحہ) کی ولادت ہوئی تو میں اسے لے کر نبی کریم صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوا تاکہ آپ صلی اللہ علیہ وسلم اسے گھٹی دیں۔ میں نے آپ صلی اللہ علیہ وسلم کو بکریوں کے باڑے میں پایا، آپ صلی اللہ علیہ وسلم بکریوں کو نشان لگا رہے تھے۔ (شعبہ نے) کہا میرا خیال ہے، شیخ نے بیان کیا: آپ صلی اللہ علیہ وسلم ان کے کانوں پر نشان لگا رہے تھے۔","f2":"پہچان کے لئے جانوروں کو نشان لگانا جائز ہے۔اس مقصد کے لئے لوہا گرم کر کے ان کے جسم کو داغا جاتا تھا۔ لیکن اس پر داغ لگانا اور اسے مارنا جائز نہیں البتہ کان پر جائز ہے۔اس سے معلوم ہوا کہ کان چہرے کا حصہ نہیں ہیں۔"}],[2564,"جابر رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم کے پاس سے ایک گدھا گزرا جس کے چہرہ کو داغ دیا گیا تھا تو آپ صلی اللہ علیہ وسلم نے فرمایا: \"کیا تمہیں یہ بات نہیں پہنچی ہے کہ میں نے اس شخص پر لعنت کی ہے جو جانوروں کے چہرے کو داغ دے، یا ان کے چہرہ پہ مارے\"، پھر آپ صلی اللہ علیہ وسلم نے اس سے منع فرمایا۔","صحیح",{"u2":"سیدنا جابر رضی اللہ عنہ سے مروی ہے کہ نبی کریم صلی اللہ علیہ وسلم کے پاس سے ایک گدھا لے جایا گیا جس کے چہرے پر داغ دیا گیا تھا تو آپ صلی اللہ علیہ وسلم نے فرمایا ” کیا تمہیں یہ بات نہیں پہنچی کہ میں نے ایسے شخص پر لعنت کی ہے جو کسی جانور کو اس کے چہرے پر داغے یا اس کے منہ پر مارے؟ “ چنانچہ آپ صلی اللہ علیہ وسلم نے اس کام سے منع فر دیا۔","f2":"1۔چہرہ جسم کا قابل عزت حصہ ہے۔انسان کا ہویا حیوان کا چہرے پر مارنا ممنوع ہے۔نبی اکرم صلی اللہ علیہ وسلم کا لعنت کرنا اپنی مرضی سے نہ تھابلکہ الہام الہی کی بنیاد پر تھا-"}],[2565,"علی بن ابی طالب رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم کو ایک خچر ہدیہ میں دیا گیا تو آپ اس پر سوار ہوئے، علی رضی اللہ عنہ نے کہا: اگر ہم ان گدھوں سے گھوڑیوں کی جفتی کرائیں تو اسی طرح کے خچر پیدا ہوں گے (یہ سن کر) رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"ایسا وہ لوگ کرتے ہیں جو (شریعت کے احکام سے) واقف نہیں ہیں ۱؎\"۔\n§وضاحت\n۱؎ : مطلب یہ ہے کہ جو لوگ گھوڑوں کی منفعت سے واقف نہیں ہیں وہی ایسا کرتے ہیں۔","صحیح",{"u2":"سیدنا علی بن ابی طالب رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم کو ایک خچر ہدیہ دیا گیا تو آپ صلی اللہ علیہ وسلم اس پر سوار ہوئے۔ سیدنا علی رضی اللہ عنہ نے کہا: اگر ہم گدھوں کو گھوڑیوں پر چڑھائیں (تو ان کے اس جنسی عمل سے) ہمیں اس طرح کے خچر حاصل ہو جائیں گے۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” جاہل لوگ یہ کام کرتے ہیں۔ “","f2":"گدھے اور گھوڑی کے جنسی ملاپ سے پیدا ہونے والا جانور خچر کہلاتا ہے۔اللہ تبارک وتعالیٰ نے اپنے انعامات میں اس کا ذکر بھی کیاہے۔\n(وَالْخَيْلَ وَالْبِغَالَ وَالْحَمِيرَ لِتَرْكَبُوهَا وَزِينَةً ۚ وَيَخْلُقُ مَا لَا تَعْلَمُونَ)(النحل۔8) اللہ تعالیٰ نے گھوڑے خچر اور گدھے پیدا کئے۔تاکہ تم ان پرسواری کرو اور یہ تمہارے لئے زینت کا باعث بھی ہیں رسول اللہ صلی اللہ علیہ وسلم نے بھی خچر پرسواری کی ہے۔اگر خچر کا پیدا کرنا ناجائز ہوتا تو اسے انعامات الہیٰ میں شمار کیا جاتا نہ نبی کریم صلی اللہ علیہ وسلم اس پر سواری فرماتے۔اس لئے علماء نے اس حدیث کو جس میں گدھے گھوڑی کے ملاپ کو ناپسندیدہ قراردیا گیا ہے۔استحباب(بچنے کے پسندیدہ ہونے) پر محمول کیا ہے۔یعنی یہ پسندیدہ عمل نہیں ہے۔تاہم اس کا جواز ہے۔"}],[2566,"عبداللہ بن جعفر رضی اللہ عنہما کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم جب سفر سے آتے تو ہم لوگ آپ کے استقبال کے لیے جاتے، جو ہم میں سے پہلے پہنچتا اس کو آپ آگے بٹھا لیتے، چنانچہ (ایک بار) آپ صلی اللہ علیہ وسلم نے مجھے اپنے سامنے پایا تو مجھے اپنے آگے بٹھا لیا، پھر حسن یا حسین پہنچے تو انہیں اپنے پیچھے بٹھا لیا، پھر ہم مدینہ میں اسی طرح (سواری پر) بیٹھے ہوئے داخل ہوئے۔","صحیح",{"u2":"سیدنا عبداللہ بن جعفر رضی اللہ عنہ بیان کرتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم جب سفر سے تشریف لاتے تو ہمارے ساتھ آپ صلی اللہ علیہ وسلم کا استقبال کیا جاتا تو جس (بچے) کے ساتھ آپ صلی اللہ علیہ وسلم کا پہلے استقبال کیا جاتا آپ صلی اللہ علیہ وسلم اسے اپنے آگے بٹھا لیتے۔ چنانچہ میرے ساتھ آپ صلی اللہ علیہ وسلم کا استقبال کیا گیا تو آپ صلی اللہ علیہ وسلم نے مجھے اپنے آگے بٹھا لیا پھر سیدنا حسن رضی اللہ عنہ آئے حسین رضی اللہ عنہ تو آپ نے ان کو اپنے پیچھے بٹھا لیا ‘ پھر ہم مدینے میں داخل ہوئے تو اسی طرح تھے (کہ تینوں ایک سواری پر سوار تھے۔)","f2":"1۔اشراف اور معزز لوگوں کا شہر سے باہر نکل کر استقبال کرنا مباح ہے۔2۔رسول اللہ صلی اللہ علیہ وسلم بچوں سے محبت کرتے تھے۔اور انھیں عزت بھی دیتے تھے۔3۔جانورکی صحت اور طاقت کے لہاظ سے اس پر دو یا تین افراد کا سوار ہوجانا ظلم نہیں مباح ہے۔"}],[2567,"ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"اپنے جانوروں کی پیٹھ کو منبر بنانے سے بچو، کیونکہ اللہ نے ان جانوروں کو تمہارے تابع کر دیا ہے تاکہ وہ تمہیں ایک شہر سے دوسرے شہر پہنچائیں جہاں تم بڑی تکلیف اور مشقت سے پہنچ سکتے ہو، اور اللہ نے تمہارے لیے زمین بنائی ہے، تو اسی پر اپنی ضروریات کی تکمیل کیا کرو ۱؎\"۔\n§وضاحت\n۱؎ : سواری پر بلا ضرورت بیٹھنا اور بیٹھ کر اسے مارنا پیٹنا اور تکلیف پہنچانا صحیح نہیں ہے، البتہ اگر یہ بیٹھنا کسی مقصد کے حصول کے لئے ہے تو کوئی حرج نہیں کیونکہ رسول اللہ صلی اللہ علیہ وسلم کا حجۃ الوداع کے موقع پر سواری پر کھڑے ہو کر خطبہ دینا ثابت ہے۔","صحیح",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ سے مروی ہے کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا ” اپنے جانوروں کی پیٹھوں کو منبر بنانے سے بچو ‘ بلاشبہ اللہ عزوجل نے ان کو تمہارے تابع کیا ہے تاکہ تمہیں ایک شہر سے دوسرے شہر تک پہنچا دیں جہاں تم نفسوں کی مشقت کے بغیر پہنچ ہی نہیں سکتے تھے اور اس نے تمہارے لیے زمین بنائی ہے تو اپنی ضرورتیں اس پر پوری کیا کرو۔ “","f2":"رسول اللہ صلی اللہ علیہ وسلم نے حجۃ الوداع کا خطبہ اپنی اونٹنی پر ارشاد فرمایا تھا۔مگر یہ ایک وقتی ضرورت تھی۔"}],[2568,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"کچھ اونٹ ۱؎ شیطانوں کے ہوتے ہیں، اور کچھ گھر شیطانوں کے ہوتے ہیں، رہے شیطانوں کے اونٹ تو میں نے انہیں دیکھا ہے، تم میں سے کوئی شخص اپنے کوتل اونٹ کے ساتھ نکلتا ہے جسے اس نے کھلا پلا کر موٹا کر رکھا ہے (خود) اس پر سواری نہیں کرتا، اور اپنے بھائی کے پاس سے گزرتا ہے، دیکھتا ہے کہ وہ چلنے سے عاجز ہو گیا ہے اس کو سوار نہیں کرتا، اور رہے شیطانوں کے گھر تو میں نے انہیں نہیں دیکھا ہے\" ۲؎۔ سعید کہتے تھے: میں تو شیطانوں کا گھر انہیں ہودجوں کو سمجھتا ہوں جنہیں لوگ ریشم سے ڈھانپتے ہیں۔\n§وضاحت\n۱؎ : اس سے مراد ایسے اونٹ ہیں جو محض فخر و مباہات کے لئے رکھے گئے ہوں، ان سے کوئی دینی اور شرعی مصلحت نہ حاصل ہو رہی ہو۔ ۲؎ : یعنی ایسے گھر جو بلاضرورت محض نام ونمود کے لئے بنائے گئے ہوں۔","ضعیف",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” شیطانوں کے اونٹ ہوتے ہیں اور شیطانوں کے گھر بھی ‘ شیطانوں کے اونٹ میں نے دیکھے ہیں ‘ تم میں ایک اپنے ساتھ خوبصورت اونٹنیاں لے کر چلتا ہے انہیں خوب موٹا تازہ کیا ہوتا ہے خود کسی پر سوار نہیں ہوتا ‘ اپنے کسی بھائی کے پاس سے گزرتا ہے جو چلنے سے عاجز ہوا تھا، اسے بھی سوار نہیں کرتا اور شیطان کے گھر میں نے نہیں دیکھے ہیں۔ “ جناب سعید بن ابی ہند کہا کرتے تھے: میں سمجھتا ہوں کہ شیطان کے گھر یہ ہودے اور کجاوے ہیں جن کو لوگوں نے ریشمی کپڑوں سے ڈھانپا ہوتا ہے۔","f2":"یہ حدیث اگرچہ ضعیف ہے۔تاہم اس میں جو بات بیان کی گئی ہے۔وہ کافی حد تک صحیح ہے۔اور آجکل شیطان کے اونٹ کی جگہ نئے ماڈل کی متنوع گاڑیوں نے لے لی ہے۔جن کے مالکان بالعموم اصحاب ضرورت کا کوئی احساس نہیں رکھتے۔الا ما شاء اللہ۔اور شیطان کے گھر صحیح معنوں میں سینما ہال ہیں۔اور رنگینی وشباب فراہم کرنے والے بدقماش ہوٹل اور اقامت گاہیں۔بلکہ اب تو ٹی وی انٹر نیٹ۔کیبل۔اورڈش وغیرہ کی بدولت ہرگھر ی شیطان کا گھر بن گیا ہے۔انا للہ وانا الیہ راجعون۔"}],[2569,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"سرسبز علاقوں میں سفر کرو تو اونٹوں کو ان کا حق دو ۱؎ اور جب قحط والی زمین میں سفر کرو تو تیز چلو ۲؎، اور جب رات میں پڑاؤ ڈالنے کا ارادہ کرو تو راستے سے ہٹ کر پڑاؤ ڈالو ۳؎\"۔\n§وضاحت\n۱؎ : یعنی انہیں کچھ دیر چرنے کے لئے چھوڑ دو۔ ۲؎ : تاکہ قحط والی زمین جلدی سے طے کر لو اور سواری کو تکان لاحق ہونے سے پہلے اپنی منزل پر پہنچ جاؤ۔ ۳؎ : کیونکہ رات میں راستوں پر زہریلے جانور چلتے ہیں۔","صحیح",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ نے بیان کیا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” جب تم شاداب علاقوں میں سفر کرو تو اونٹوں کو ان کا حق دیا کرو (کہ وہ بھی کھا اور چر لیں) اور جب خشکی کے (دن یا علاقے ہوں) تو جلدی جلدی چلا کرو (تاکہ سواریوں کو اذیت نہ ہو) اور جب تم رات کو آرام کے لیے کہیں پڑاؤ کرو تو راستے سے ہٹ کر پڑاؤ کیا کرو۔ “","f2":"انسان جس طرح اللہ کی نعمتوں سے فائدہ اٹھاتا ہے۔اسی طرح اپنے زیر ملکیت حیوانات کو بھی یہ حق دینا لازمی ہے۔2۔نیز دوران سفر میں رات کو کہیں پڑائو کرنا پڑے تو ادب یہ ہے کہ راستے سے ہٹ کر اترنا چاہیے۔اس کی حکمت یہ بیان ہوئی ہے کہ راستے پر سانپ بچھو اور بعض اوقات درندے بھی ہوتے ہیں۔(سنن ابن ماجہ۔اطہارۃ۔وسننھا حدیث 329)"}],[2570,"جابر بن عبداللہ رضی اللہ عنہما نے بھی نبی اکرم صلی اللہ علیہ وسلم سے ایسی ہی روایت کی ہے، مگر اس میں آپ کے قول «فأعطوا الإبل حقها» کے بعد اتنا اضافہ ہے کہ منزلوں کے آگے نہ بڑھو (تاکہ جانور کو تکلیف نہ ہو) ۔","صحیح",{"u2":"سیدنا جابر بن عبداللہ رضی اللہ عنہ، نبی کریم صلی اللہ علیہ وسلم سے مذکورہ حدیث کے مثل بیان کرتے ہیں اس روایت میں «حقها» کے بعد یہ اضافہ ہے کہ ” (معروف) منازل (اور مسافت) سے تجاوز مت کیا کرو۔ “","f2":"کیونکہ اس سے سواریوں کی مشقت ہوتی ہے۔اورہمراہی بھی اذیت محسوس کرتے ہیں۔"}],[2571,"انس رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"رات کے آخری حصہ میں سفر کرنے کو لازم پکڑو، کیونکہ زمین رات کو لپیٹ دی جاتی ہے ۱؎\"۔\n§وضاحت\n۱؎ : یعنی رات میں مسافت زیادہ طے ہوتی ہے۔","صحیح",{"u2":"سیدنا انس رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” رات کے پہلے پہر (یا رات کو بھی) سفر کیا کرو ‘ بلاشبہ رات کے وقت زمین لپیٹ لی جاتی ہے۔","f2":"اور تجربہ کی بات ہے۔کہ رات کو سفر خوب طے ہوتا ہے۔علاوہ ازیں انتہائی گرم موسم میں مسافروں اور سواریوں کورات کے وقت قدرے آرام رہتا ہے۔مگر خیال رہے کہ شام ہوتے وقت قدرے توقف کرنا چاہیے۔ حتیٰ کہ خوب اندھیرا ہوجائے۔احادیث شریفہ میں اس بات کی صراحت آئی ہے۔(دیکھئے صحیح مسلم۔الاشربۃ حدیث 2013)"}],[2572,"بریدہ رضی اللہ عنہ کہتے ہیں رسول اللہ صلی اللہ علیہ وسلم چل رہے تھے کہ اسی دوران ایک آدمی آیا اور اس کے ساتھ ایک گدھا تھا، اس نے کہا: اللہ کے رسول سوار ہو جائیے اور وہ پیچھے سرک گیا، آپ صلی اللہ علیہ وسلم نے فرمایا: \"تم اپنی سواری پر آگے بیٹھنے کا مجھ سے زیادہ حقدار ہو، الا یہ کہ تم مجھے اس اگلے حصہ کا حقدار بنا دو\"، اس نے کہا: اللہ کے رسول! میں نے آپ کو اس کا حقدار بنا دیا، پھر رسول اللہ صلی اللہ علیہ وسلم اس پر سوار ہوئے۔","حسن صحیح",{"u2":"سیدنا بریدہ رضی اللہ عنہ بیان کرتے ہیں کہ ایک دفعہ رسول اللہ صلی اللہ علیہ وسلم تشریف لیے جا رہے تھے کہ ایک شخص آیا اور اس کے پاس گدھا تھا ‘ اس نے کہا: اے ا اللہ کے رسول! (آیئے) سوار ہو جائیے اور وہ خود پیچھے کو ہو گیا۔ تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” نہیں، تم اپنی سواری پر آگے بیٹھنے کے زیادہ حقدار ہو۔ سوائے اس کے کہ تم اپنا یہ حق مجھے دے دو۔ “ اس نے کہا: بیشک میں اپنا یہ حق آپ کو دیتا ہوں، سو آپ سوار ہو گئے۔","f2":"1۔کار۔جیپ۔اور دیگر سواریوں میں فرنٹ سیٹ کا بھی یہی حکم ہے۔2۔نبی کریم صلی اللہ علیہ وسلم ہر ہر موقع پر تعلیم وتربیت کو پیش نظر رکھتے اور یہ فریضہ سر انجام دیتے تھے۔"}],[2573,"عباد بن عبداللہ بن زبیر کہتے ہیں کہ میرے رضاعی والد نے جو بنی مرہ بن عوف میں سے تھے مجھ سے بیان کیا کہ وہ غزوہ موتہ کے غازیوں میں سے تھے، وہ کہتے ہیں: اللہ کی قسم! گویا کہ میں جعفر بن ابوطالب رضی اللہ عنہ کو دیکھ رہا ہوں جس وقت وہ اپنے سرخ گھوڑے سے کود پڑے اور اس کی کونچ کاٹ دی ۱؎، پھر دشمنوں سے لڑے یہاں تک کہ قتل کر دیئے گئے۔ ابوداؤد کہتے ہیں: یہ حدیث قوی نہیں ہے ۲؎۔\n§وضاحت\n۱؎ : کونچ وہ موٹا پٹھا جو آدمی کے ایڑی کے اوپر اور چوپایوں کے ٹخنے کے نیچے ہوتا ہے، گھوڑے کی کونچ اس لئے کاٹ دی گئیں تا کہ دشمن اس گھوڑے کے ذریعہ مسلمانوں پر حملہ نہ کر سکے، نیز اس حدیث سے معلوم ہوا کہ لڑائی میں سامان کے سلسلہ میں یہ اندیشہ ہو کہ دشمن کے ہاتھ میں آ کر اس کی تقویت کا سبب بنے گا تو اسے تلف کر ڈالنا درست ہے۔ ۲؎ : شاید مؤلف نے اس بنیاد پر اس حدیث کو غیر قوی قرار دیا ہے کہ عباد کے رضاعی باپ مبہم ہیں، لیکن یہ صحابی بھی ہو سکتے ہیں، اور یہی ظاہر ہے، اسی بنا پر البانی نے اس کو حسن قرار دیا ہے، (حسن اس لئے کہ ’’ابن اسحاق‘‘ درجہ حسن کے راوی ہیں)","حسن",{"u2":"عباد بن عبداللہ بن زبیر اپنے رضاعی باپ سے روایت کرتے ہیں جو کہ بنی مرہ میں سے تھے اور غزوہ موتہ میں شریک ہوئے تھے۔ کہتے ہیں: قسم ا اللہ کی! میں گویا سیدنا جعفر بن ابی طالب رضی اللہ عنہ کو دیکھ رہا ہوں کہ وہ اپنے سرخ گھوڑے سے اتر پڑے، اس کی کونچیں کاٹ ڈالیں ‘ پھر کافروں سے لڑتے رہے حتیٰ کہ خود قتل ہو گئے۔ امام ابوداؤد رضی اللہ عنہ فرماتے ہیں کہ یہ حدیث قوی نہیں ہے۔","f2":"جنگ میں اگر اندیشہ ہوکہ مجاہد مغلوب ہوجائے گا۔تو اپنی سواری یا دوسرے سامان کوتلف کردے تو جائز ہے۔تاکہ دشمن اس سے فائدہ نہ اٹھا سکے۔شیخ البانی نے اس روایت کو حسن قرار دیا ہے۔"}],[2574,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"مقابلہ میں بازی رکھنا جائز نہیں ۱؎ سوائے اونٹ یا گھوڑے کی دوڑ میں یا تیر چلانے میں\"۔\n§وضاحت\n۱؎ : حدیث میں «سبق» کا لفظ آیا ہے «سبق» اس پیسہ کو کہتے ہیں، جو گھوڑ دوڑ وغیرہ میں شرط کے طور پر رکھا جاتا ہے، لیکن یہ رقم خود گھوڑ دوڑ میں شرکت کرنے والوں کی طرف سے جیتنے والے کے لئے نہ ہو، بلکہ کسی تیسرے فریق کی طرف سے ہو، اگر خود گھوڑوں کی ریس (دوڑ) میں شرکت کرنے والوں کی جانب سے ہو گا تو یہ مقابلہ جُوا میں داخل ہو جائے گا۔","صحیح",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” مقابلہ صرف تین چیزوں میں جائز ہے اونٹ دوڑ ‘ گھوڑ دوڑ یا تیر اندازی۔ “","f2":"(السبق) ب کی جزم کے ساتھ مصدر ہے اور معنی ہیں آگے بڑھنا۔اور اگر ب پر زبر پڑھی جائی تو اس سے وہ مال اور انعا م مراد ہوتا ہے۔جو کسی مقابلہ پردیا جائے۔درج ذیل روایت میں یہ کلمہ ب پر زبر کے ساتھ پڑھا جاتا ہے۔\nفائدہ۔جہاد اور تعلیم وتربیت کے مختلف امور میں مقابلہ کرنا کرانا اسی پر قیاس ہے مگر ایسے تمام امور جن کا کوئی حاصل نہ ہو ان میں مقابلہ بازی ناجائز اور باطل ہے۔مثلا کبوتر اڑانا یا مرغ اور بٹیر لڑانا۔وغیرہ"}],[2575,"عبداللہ بن عمر رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے پھرتیلے چھریرے بدن والے گھوڑوں کے درمیان ۱؎حفیاء سے ثنیۃ الوداع تک مقابلہ کرایا، اور غیر چھریرے بدن والے گھوڑوں، کے درمیان ثنیۃ الوداع سے مسجد بنی زریق تک مقابلہ کرایا اور عبداللہ بن عمر رضی اللہ عنہما بھی مقابلہ کرنے والوں میں سے تھے۔\n§وضاحت\n۱؎ : گھوڑوں کے بدن کو چھریرا بنانے کے عمل کو تضمیر کہتے ہیں، اس کا طریقہ یہ ہے کہ انہیں خوب کھلا پلا کر موٹا اور تندرست کیا جائے، پھر آہستہ آہستہ ان کی خوراک کم کر دی جائے یہاں تک کہ وہ اپنی اصل خوراک پر آ جائیں، پھر ایک مکان میں بند کر کے ان پر گردنی ڈال دی جائے تا کہ انہیں گرمی اور پسینہ آ جائے جب پسینہ خشک ہو جاتا ہے تو وہ سبک، طاقتور اور تیز رو ہو جاتے ہیں۔","صحیح",{"u2":"سیدنا عبداللہ بن عمر رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے مضمر گھوڑوں میں مقابلہ کروایا اور ان کے لیے حفیاء سے ثنیۃ الوداع تک کا فاصلہ مقرر تھا ‘ اور غیر مضمر گھوڑوں میں مقابلہ کروایا تو ان کے لیے ثنیۃ الوداع سے مسجد بنی زریق تک کا فاصلہ مقرر تھا ‘ اور عبداللہ ان مقابلہ کرنے والوں میں شریک تھے اور کامیاب رہے تھے۔","f2":"1۔گھوڑوں کو پالتے ہوئے پہلے انہیں کھلا پلا کر خوب موٹا تازہ کیا جاتا ہے۔پھر ان کی خوراک میں بتدریج کمی کی جاتی ہے۔اور کسی مکان میں بند رکھا جاتا ہے۔اور ان پر کپڑا بھی ڈالتے ہیں۔اس سے ان کو پسینہ آتا ہے حتی ٰ کہ ان کی زائد چربی وغیرہ ختم ہوجاتی ہے۔اور اس طرح وہ بہت طاقت ور ہوجاتے ہیں۔ اور ان کا سانس بہت کم پھولتا ہے۔اس عمل کو اضما اورایسے گھوڑوں کو مضمر کہتے ہیں۔(پہلی میم پر پیش اور دوسری پر زبر کے ساتھ) 2۔حدیث شریف میں ہے کہ حفیاء سے ثنیۃ الوداع کے درمیان پانچ چھ میل کا فاصلہ تھا۔ اور ثنیۃ الوداع سے مسجد بنی زریق کے درمیان ایک میل کا (صحیح البخاری الجہاد والسیر حدیث 2868)"}],[2576,"عبداللہ بن عمر رضی اللہ عنہما سے روایت ہے کہ اللہ کے نبی اکرم صلی اللہ علیہ وسلم گھوڑ دوڑ کے لیے گھوڑوں (کو چھریرا) پھرتیلا بناتے تھے۔","صحیح",{"u2":"سیدنا عبداللہ بن عمر رضی اللہ عنہ سے منقول ہے کہ نبی کریم صلی اللہ علیہ وسلم گھوڑوں کو مضمر بنایا کرتے، جن میں مقابلے کرائے جاتے تھے۔"}],[2577,"عبداللہ بن عمر رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے گھوڑ دوڑ کا مقابلہ کرایا اور پانچویں برس میں داخل ہونے والے گھوڑوں کی منزل دور مقرر کی۔","صحیح",{"u2":"سیدنا ابن عمر رضی اللہ عنہ سے مروی ہے کہ نبی کریم صلی اللہ علیہ وسلم نے گھوڑ دوڑ کا مقابلہ کرایا تو جو گھوڑے پانچویں سال میں داخل ہو چکے تھے، ان کے لیے دوڑ کا فاصلہ زیادہ رکھا تھا۔","f2":"1۔امت میں جہاد کی روح باقی رکھئے اور جہاد کی تیاری کے لئے ان تربیتی امور کا اہتمام انتہائی ضروری اور واجب ہے۔2۔(انقرح) یہ فارح کی جمع ہے۔اس سے مراد ایسا گھوڑا ہے۔جوپانچویں سال میں داخل ہو چکا ہو۔"}],[2578,"ام المؤمنین عائشہ رضی اللہ عنہا سے روایت ہے کہ وہ نبی اکرم صلی اللہ علیہ وسلم کے ساتھ ایک سفر میں تھیں، کہتی ہیں کہ میں نے آپ صلی اللہ علیہ وسلم سے دوڑ کا مقابلہ کیا تو میں جیت گئی، پھر جب میرا بدن بھاری ہو گیا تو میں نے آپ سے (دوبارہ) مقابلہ کیا تو آپ جیت گئے، اس پر آپ صلی اللہ علیہ وسلم نے فرمایا: \"یہ جیت اس جیت کے بدلے ہے\"۔","صحیح",{"u2":"ام المؤمنین سیدہ عائشہ رضی اللہ عنہا ا بیان کرتی ہیں کہ میں ایک سفر میں نبی کریم صلی اللہ علیہ وسلم کے ساتھ تھی، میں نے آپ صلی اللہ علیہ وسلم کے ساتھ دوڑ میں مقابلہ کیا تو میں آپ صلی اللہ علیہ وسلم سے آگے بڑھ گئی۔ پھر جب میں بھاری ہو گئی تو آپ صلی اللہ علیہ وسلم مجھ سے بڑھ گئے۔ تو آپ صلی اللہ علیہ وسلم نے فرمایا ” یہ اس (پہلی دوڑ) کا بدلہ ہے۔ “","f2":"اس واقعہ میں یہ بیان ہے کہ گھر یلو زندگی میں نبی صلی اللہ علیہ وسلم کا انداز انتہائی ملائمت اور الفت بھرا ہوتا تھا۔نیز پیدل دوڑ کا مقابلہ بھی کیا کرایا جاسکتا ہے۔"}],[2579,"ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"جو شخص دو گھوڑوں کے درمیان ایک گھوڑا داخل کر دے اور گھوڑا ایسا ہو کہ اس کے آگے بڑھ جانے کا یقین نہ ہو تو وہ جوا نہیں، اور جو شخص ایک گھوڑے کو دو گھوڑوں کے درمیان داخل کرے اور وہ اس کے آگے بڑھ جانے کا یقین رکھتا ہو تو وہ جوا ہے\"۔","ضعیف",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا ” جس نے دو (مقابلہ کرنے والے) گھوڑوں میں (اپنا) گھوڑا داخل کیا اور اس کے جیت جانے کا یقین نہ ہو تو یہ جوا نہیں ہے، اور جس نے ان میں اپنا گھوڑا داخل کیا جبکہ اسے یقین ہو کہ یہ جیت جائے گا تو یہ جوا ہے۔ “","f2":"اس باب کی احادیث سمجھنے کے لئے چند امور معلوم ہونے چاہیں۔1۔اگر امیر المجاہدین یا کوئی اور شخص دو شہسواروں میں دوڑ وغیرہ کا مقابلہ کرائے اور جیتنے والے کو انعام واکرام دے تو جائز ہے۔2۔لیکن دوافراد (یا فریق)آپس میں یہ طے کر کے مقابلہ کریں کہ ہارنے والا جیتنے والے کو اس قدر انعام دے گا تو یہ جوا ہے۔اور ناجائز ہے۔3۔اگر ان دو مقابلہ کرنے والوں میں کوئی تیسرا فریق داخل ہوجائے جس کے جیتنے یا ہارنے کا کوئی یقین نہ ہو بلکہ ان کے ہم پلہ ہونے کی بناء پر کوئی بھی نتیجہ نکل سکتا ہو کہ اس کے جیت جانے پر وہ دونوں اس کو انعام دیں او ر ہار جانے پر اس پر کچھ بھی لازم نہ آتا ہو تو یہ صورت جائز ہے۔چونکہ اس کا ان دو میں داخل ہوجانا ان کے انعام لین دینے کو جائز بنادیتا ہے اس وجہ سے اسے محلل کہا جاتا ہے۔محلل یعنی(جوئے سے) حلال کرنے والا۔"}],[2580,"اس سند سے بھی زہری سے عباد والے طریق ہی سے اسی مفہوم کی حدیث مروی ہے ابوداؤد کہتے ہیں: اسے معمر، شعیب اور عقیل نے زہری سے اور زہری نے اہل علم کی ایک جماعت سے روایت کیا ہے اور یہ ہمارے نزدیک زیادہ صحیح ہے۔","ضعیف",{"u2":"سیدنا زہری رضی اللہ عنہ نے بہ سند عباد بن عوام بیان کیا اور مذکورہ بالا کے ہم معنی ذکر کیا۔ امام ابوداؤد رضی اللہ عنہ فرماتے ہیں: اس روایت کو معمر، شعیب اور عقیل نے بواسطہ زہری کئی علماء سے نقل کیا ہے اور یہ ہمارے نزدیک صحیح تر ہے۔"}],[2581,"عمران بن حصین رضی اللہ عنہما سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \" «جلب» اور «جنب» نہیں ہے\"۔ یحیی نے اپنی حدیث میں «في الرهان» (گھوڑ دوڑ کے مقابلہ میں) کا اضافہ کیا ہے۔","صحیح",{"u2":"سیدنا عمران بن حصین رضی اللہ عنہ کا بیان ہے کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا ” نہ «جلب» ہے اور نہ «جنب» “ یحییٰ بن حلف کی روایت میں صراحت ہے یعنی ” مقابلے میں۔ “","f2":"کتاب الذکواۃ میں بھی اس کا زکر آیا ہے۔اس کے لئے دیکھئے۔حدیث 1591) مگر یہاں مراد یہ ہے کہ گھوڑ دوڑ میں کوئی شخص اپنے گھوڑے کے ساتھ کسی اور شخص کو بھی دوڑائے جو اس کے گھوڑے کو ڈانٹتا جائے۔اور مقصد یہ ہوکہ اس کا گھوڑا آگے بڑھ کر جیت جائے اسے جلب کہتے ہیں۔اور جنب یہ ہے کہ دوڑ میں اپنے گھوڑے کے پہلو بہ پہلو ایک اورگھوڑا رکھے تاکہ جب دیکھے کہ پہلا گھوڑا تھک گیا ہے تو جلدی سے دوسرے تازہ دم گھوڑے پر سوار ہوکر مقابلہ جیتنے کی کوشش کرے۔یہ دونوں صورتیں ناجائز ہیں۔"}],[2582,"قتادہ رضی اللہ عنہ سے روایت ہے، انہوں نے کہا «جلب» اور «جنب» ۱؎ گھوڑ دوڑ کے مقابلہ میں ہوتا ہے۔\n§وضاحت\n۱؎ : گھوڑ دوڑ میں «جلب» یہ ہے کہ کسی کو اپنے گھوڑے کے پیچھے لگا لے کہ وہ گھوڑے کو ڈانٹتا رہے ، تاکہ وہ آگے بڑھ جائے ، اور «جنب» یہ ہے کہ اپنے گھوڑے کے پہلو میں ایک اور گھوڑا رکھے کہ جب سواری کا گھوڑا تھک جائے تو اس گھوڑے پر سوار ہو جائے ، اور زکاۃ میں «جلب» یہ ہے کہ زکاۃ لینے والا دور اترے اور زکاۃ دینے والے سے کہے کہ وہ اپنے مویشی میرے پاس لے آئیں ، اور «جنب» یہ ہے کہ دینے والے اپنی اصل جگہ سے مویشیوں کو دور لے کر چلے جائیں اور محصل سے یہ کہیں کہ وہ یہاں آ کر زکاۃ لے ، یہ دونوں چیزیں منع ہیں۔","صحیح",{"u2":"سیدنا قتادہ رضی اللہ عنہ بیان کرتے ہیں کہ «جلب» اور «جنب» مقابلہ بازی میں ہوتا ہے۔"}],[2583,"انس رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم کی تلوار کے قبضہ کی خول چاندی کی تھی۔","صحیح",{"u2":"سیدنا انس رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم کی تلوار کے قبضہ کی ٹوپی چاندی کی تھی۔","f2":"مجاہد کے لئے جائز ہے۔کہ اپنے اسلحے کو اس طرح سے مزین کرلے۔"}],[2584,"(حسن بصری کے بھائی) سعید بن ابوالحسن کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم کی تلوار کے دستہ کی خول چاندی کی تھی۔ قتادہ کہتے ہیں: میں نہیں جانتا کہ اس پر ان کی متابعت کسی اور شخص نے کی ہے۔","صحیح",{"u2":"سعید بن ابی الحسن رضی اللہ عنہ کی روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم کی تلوار کے قبضہ کی ٹوپی چاندی کی تھی۔ قتادہ کہتے ہیں: مجھے معلوم نہیں کہ کسی نے اس کی متابعت کی ہو۔"}],[2585,"اس سند سے انس بن مالک رضی اللہ عنہ سے سابقہ حدیث مروی ہے ابوداؤد کہتے ہیں: ان احادیث میں سب سے زیادہ قوی سعید بن ابوالحسن کی حدیث ہے اور باقی ضعیف ہیں۔","صحیح"],[2586,"جابر رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے ایک شخص کو حکم دیا جو مسجد میں تیر بانٹ رہا تھا کہ جب وہ ان تیروں کو لے کر نکلے تو ان کی پیکان پکڑے ہو۔","صحیح",{"u2":"سیدنا جابر رضی اللہ عنہ سے منقول ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے ایک شخص کو حکم دیا جو مسجد میں تیروں کو صدقہ تقسیم کرنے جا رہا تھا کہ وہ جب ان تیروں کو لے کر چلے تو پھلوں کی طرف سے پکڑے۔"}],[2587,"ابوموسی اشعری رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جب کوئی شخص ہماری مسجد یا ہمارے بازار سے گزرے اور اس کے پاس تیر ہو تو اس کی نوک کو پکڑ لے\" یا فرمایا: \"مٹھی میں دبائے رہے\"، یا یوں کہا کہ: \"اسے اپنی مٹھی سے دبائے رہے کہ کہیں ایسا نہ ہو کہ مسلمانوں میں سے کسی کو لگ جائے\"۔","صحیح",{"u2":"سیدنا ابوموسیٰ رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” جب تم میں سے کوئی ہماری مسجد یا بازار میں سے گزرے اور اس کے پاس تیر ہوں تو چاہیئے کہ انہیں ان کے پھلوں کی طرف سے پکڑ کر رکھے۔ “ یا فرمایا ” انہیں اپنی مٹھی سے پکڑے رہے “ یا فرمایا ” انہیں اپنی مٹھی سے پکڑے رہے کہ کہیں کسی مسلمان کو نہ لگ جائیں۔ “","f2":"1۔صدقہ صرف مال کا نہیں ہوتا۔ بلکہ ہر مفید چیز صدقہ کی جاسکتی ہے۔تیر یا جہاد میں کام آنے والا اسلحہ بھی بطور صدقہ تقسیم کیا جاسکتاہے۔2۔تیز دھاردار اور دیگر اسلحہ جات کی نقل وحمل میں انتہائی احتیاط کی ضرورت ہے۔ایسا نہ ہو کہ غفلت اور غلطی سے کسی مسلمان کو لگ جائے۔"}],[2588,"جابر رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے ننگی تلوار (کسی کو) تھمانے سے منع فرمایا ۱؎۔\n§وضاحت\n۱؎ : اسی طرح کوئی بھی ایسا ہتھیار لے کر راستہ میں یا مجمع میں چلنا جس سے نقصان پہنچنے کا خطرہ ہو ممنوع ہے۔","صحیح",{"u2":"سیدنا جابر رضی اللہ عنہ سے منقول ہے بیشک نبی کریم صلی اللہ علیہ وسلم نے منع فرمایا کہ تلوار کو اس کیفیت میں لیا دیا (لینا دینا) جائے کہ وہ ننگی ہو (میان میں نہ ہو)۔","f2":"کیونکہ اس طرح اندیشہ رہتا ہے کہ کسی کو لگ سکتی ہے یا چبھ سکتی ہے۔اس لئے احتیاط ضروری ہے۔"}],[2589,"سمرہ بن جندب رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے چمڑے کو دو انگلیوں کے درمیان رکھ کر کاٹنے سے منع فرمایا۔","حسن بصری مدلس ہیں اور روایت عنعنہ سے ہے",{"u2":"سیدنا سمرہ بن جندب رضی اللہ عنہ سے مروی ہے کہ بیشک رسول اللہ صلی اللہ علیہ وسلم نے منع فرمایا کہ چمڑے کے ٹکڑے کو دو انگلیوں کے درمیان رکھ کر کاٹا جائے۔","f2":"اس طرح اندیشہ رہتا ہے کہ چمڑا کٹنے کے بعد کہیں ہاتھ نہ زخمی ہوجائے۔لہذا چاہیے کہ کسی لکڑی یا پتھر وغیرہ پر رکھ کر احتیاط سے کاٹا جائے۔"}],[2590,"سائب بن یزید رضی اللہ عنہ ایک ایسے آدمی سے روایت کرتے ہیں جس کا انہوں نے نام لیا تھا کہ رسول اللہ صلی اللہ علیہ وسلم غزوہ احد کے دن دو زرہیں اوپر تلے پہنے شریک غزوہ ہوئے۔","صحیح",{"u2":"جناب سائب بن یزید رضی اللہ عنہ نے ایک شخص سے روایت کی اور اس کا نام بھی بتایا کہ رسول اللہ صلی اللہ علیہ وسلم نے احد کے دن اوپر تلے دو زرہیں پہنی ہوئی تھی۔","f2":"زندگی موت تو اللہ کے ہاتھ میں ہے۔مگر حفاظت کی غرض سے ہتھیارلینا اور زرہ وغیرہ پہننا مشروع ہے۔اور یہ توکل کے خلاف نہیں ہے۔"}],[2591,"محمد بن قاسم کے غلام یونس بن عبید کہتے ہیں کہ محمد بن قاسم نے مجھے براء بن عازب رضی اللہ عنہ کے پاس بھیجا کہ میں ان سے رسول اللہ صلی اللہ علیہ وسلم کے جھنڈے کے متعلق پوچھوں کہ وہ کیسا تھا، تو انہوں نے کہا: وہ سیاہ چوکور دھاری دار اونی کپڑے کا تھا۔","صحیح",{"u2":"سیدنا محمد بن قاسم رضی اللہ عنہ نے اپنے غلام کو سیدنا براء بن عازب رضی اللہ عنہ کی خدمت میں بھیجا کہ وہ ان سے رسول اللہ صلی اللہ علیہ وسلم کے علم (جھنڈے) کے متعلق پوچھ کر آئے کہ وہ کیسا تھا؟ تو انہوں نے بتایا کہ وہ کالے لکیر دار اونی کپڑے کا اور چوکور تھا۔","f2":"1۔(اللواء)پرچم اعظم کو اور (الرایۃ) اس کے زیلی جھنڈوں کو کہتے ہیں۔اور نبی کریم صلی اللہ علیہ وسلم کے لئے محشر میں (لواءالحمد)ہوگا۔2۔شیخ البانی کہتے ہیں۔ یہ روایت صحیح ہے البتہ (مربعۃ) چوکور کا لفظ صحیح نہیں ہے۔"}],[2592,"جابر رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم جس دن مکہ میں داخل ہوئے آپ کا پرچم سفید تھا۔","صحیح",{"u2":"سیدنا جابر رضی اللہ عنہ نے نبی کریم صلی اللہ علیہ وسلم کے متعلق بتایا کہ جس دن آپ صلی اللہ علیہ وسلم مکے میں داخل ہوئے، اس دن آپ صلی اللہ علیہ وسلم کا جھنڈا سفید رنگ کا تھا۔"}],[2593,"سماک اپنی قوم کے ایک آدمی سے روایت کرتے ہیں اور اس نے انہیں میں سے ایک دوسرے شخص سے روایت کیا، وہ کہتے ہیں میں نے رسول اللہ صلی اللہ علیہ وسلم کا پرچم زرد دیکھا۔","ضعیف",{"u2":"سیدنا سماک بن حرب اپنی قوم کے ایک آدمی سے اور وہ ایک دوسرے سے روایت کرتے ہیں انہوں نے کہا کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کا علم (جھنڈا) دیکھا جو زرد رنگ کا تھا۔","f2":"1۔جہاد میں جھنڈے کا اہتمام کرنا مستحب ہے۔2۔قرون اولیٰ میں جھندوں کا کوئی رنگ اورسائز مخصوص نہ ہوتا تھا۔ اور یہ زرد رنگ والی روایت ضعیف ہے۔3۔ جنگ میں اور دیگر اہم مواقع پر جھنڈے کو بلند اور نمایاں رکھنا بلاشبہ مطلوب ہے۔مگر یہ سب ایک نظم کے لئے ہوتا ہے۔اسے تقدس اوراحترام کا ایسا مفہوم دینا جو آجکل عام کردیا گیا ہے۔غیر شرعی ہے بلکہ شرک کی حدود کوچھوتاہے۔"}],[2594,"ابوالدرداء رضی اللہ عنہ کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا: \"میرے لیے ضعیف اور کمزور لوگوں کو ڈھونڈو، کیونکہ تم اپنے کمزوروں کی وجہ سے رزق دیئے جاتے اور مدد کئے جاتے ہو\"۔","صحیح",{"u2":"سیدنا ابو الدرداء رضی اللہ عنہ بیان کرتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا آپ صلی اللہ علیہ وسلم فرماتے تھے ” میرے لیے ضعفاء اور کمزور لوگوں کو تلاش کرو، تم لوگ اپنے کمزور لوگوں ہی کے ذریعے سے رزق دیے جاتے اور مدد کیے جاتے ہو۔ “ امام ابوداؤد رضی اللہ عنہ نے فرمایا کو راوی حدیث زید بن ارطاۃ، عدی بن ارطاۃ کے بھائی ہیں۔","f2":"ضعیف و بے کس اور نادارافراد اوردیگر مخلوق کی عبادت اور دعا میں اخلاص ہوتا ہے۔ وہ ریاکاری سے بالعموم بری ہوتے ہیں۔تو ان کی عبادت دعا اور بے کسی کی برکت سے اللہ عزو جل دوسروں پر بھی رحم فرمادیتا ہے۔"}],[2595,"سمرہ بن جندب رضی اللہ عنہ کہتے ہیں کہ مہاجرین کا شعار (کوڈ) ۱؎ \"عبداللہ\" اور انصار کا شعار \"عبدالرحمٰن\" تھا۔\n§وضاحت\n۱؎ : وہ خاص لفظ جس سے پہرے دار یا فوجی کو آپس میں ایک دوسرے کی شناخت کے لئے بتا دیا جاتا ہے کہ دوران جنگ اسے دھوکہ نہ دیا جا سکے، اسے ’’پردل‘‘ کہتے ہیں۔","ضعیف",{"u2":"سیدنا سمرہ بن جندب رضی اللہ عنہ نے بیان کیا کہ (ایک جنگ میں) مہاجرین کا شعار ” عبداللہ “ اور انصار کا ” عبدالرحمٰن “ تھا۔","f2":"اس کا فائدہ یہ ہوتا ہے کہ اندھیرے میں یا ذاتی تعارف نہ ہونے کی صورت میں اپنے افراد کو پہچاننے میں غلطی نہیں ہوتی۔اگر کوئی جاسوس وغیرہ ددر آئے تو اس کو پکڑنا بھی آسان رہتا ہے۔"}],[2596,"سلمہ بن الاکوع رضی اللہ عنہ کہتے ہیں کہ ہم نے ابوبکر رضی اللہ عنہ کے ساتھ نبی اکرم صلی اللہ علیہ وسلم کے زمانہ میں غزوہ کیا تو ہمارا شعار «أمت أمت» ۱؎ تھا۔\n§وضاحت\n۱؎ : اے مدد کرنے والے دشمن کو فنا کر۔","حسن صحیح",{"u2":"سیدنا ایاس بن سلمہ اپنے والد سے روایت کرتے ہیں کہ ہم نے رسول اللہ صلی اللہ علیہ وسلم کے زمانے میں سیدنا ابوبکر رضی اللہ عنہ کی معیت میں جہاد کیا تو ہمارا شعار تھا۔۔ «أمت أمت» (معنی ہے مار دے، مار دے اور اس میں کفار کی ہزیمت اور مسلمانوں کی فتح کا تفاؤل تھا)۔"}],[2597,"مہلب بن ابی صفرہ کہتے ہیں کہ مجھے اس شخص نے خبر دی ہے جس نے نبی اکرم صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا: \"اگر دشمن تمہارے اوپر شب خون ماریں تو تمہارا شعار (کوڈ) «حم لا ينصرون» ۱؎ ہونا چاہیئے\"۔\n§وضاحت\n۱؎ : اللہ کی قسم دشمنوں کو اللہ کی تائید و نصرت حاصل نہیں ہو گی بلکہ وہ مغلوب رہیں گے۔","صحیح",{"u2":"سیدنا مہلب بن ابی صفرہ کا کہنا ہے کہ مجھے اس شخص نے بیان کیا جس نے نبی کریم صلی اللہ علیہ وسلم سے سنا تھا آپ صلی اللہ علیہ وسلم نے فرمایا ” اگر تم پر رات کو حملہ ہو جائے تو تمہارا شعار «حم لا ينصرون» ہونا چاہیئے۔ “"}],[2598,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ اللہ کے رسول صلی اللہ علیہ وسلم جب سفر کرتے تو یہ دعا پڑھتے: «اللهم أنت الصاحب في السفر والخليفة في الأهل اللهم إني أعوذ بك من وعثاء السفر وكآبة المنقلب وسوء المنظر في الأهل والمال اللهم اطو لنا الأرض وهون علينا السفر» \"اے اللہ! تو (میرے) سفر کا رفیق اور گھر والوں کے لیے میرا قائم مقام ہے، اے اللہ! میں تجھ سے سفر کی پریشانیوں سے اور غمگین و ناکام ہو کر لوٹنے سے اور لوٹ کر اہل اور مال میں برے منظر (دیکھنے سے) سے پناہ مانگتا ہوں، اے اللہ! ہمارے لیے زمین کو لپیٹ دے اور ہم پر سفر آسان کر دے\"۔","حسن صحیح",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم جب سفر پر روانہ ہوتے تو یہ دعا پڑھتے تھے «اللهم أنت الصاحب في السفر والخليفة في الأهل، اللهم إني أعوذ بك من وعثاء السفر وكآبة المنقلب وسوء المنظر في الأهل والمال، اللهم اطو لنا الأرض وهون علينا السفر» ” اے ا اللہ! سفر میں تو ہی ہمارا رفیق اور اہل میں خلیفہ ہے۔ (ان کی حفاظت کرنے والا ہے) اے ا اللہ! سفر کی مشقت اور شدت سے میں تیری پناہ چاہتا ہوں اور اس بات سے کہ غم و اندوہ کے ساتھ واپس لوٹوں اور اپنے اہل اور مال میں کوئی برا منظر دیکھوں، اے ا اللہ! ہمارے لیے زمین کو لپیٹ دے اور سفر کو ہمارے لیے آسان فر دے۔ “","f2":"سفر مختلف مقاصد کے لئے ہوتا ہے۔مگر سب سے اہم اور مبارک سفر جہاد کا ہے۔"}],[2599,"علی ازدی کہتے ہیں کہ ابن عمر رضی اللہ عنہما نے انہیں سکھایا کہ رسول اللہ صلی اللہ علیہ وسلم سفر میں جانے کے لیے جب اپنے اونٹ پر سیدھے بیٹھ جاتے تو تین بار اللہ اکبر فرماتے، پھر یہ دعا پڑھتے: «{ سبحان الذي سخر لنا هذا وما كنا له مقرنين * وإنا إلى ربنا لمنقلبون } اللهم إني أسألك في سفرنا هذا البر والتقوى ومن العمل ما ترضى اللهم ہوں علينا سفرنا هذا اللهم اطو لنا البعد اللهم أنت الصاحب في السفر والخليفة في الأهل والمال» \"پاک ہے وہ اللہ جس نے اس (سواری) کو ہمارے تابع کر دیا جب کہ ہم اس کو قابو میں لانے والے نہیں تھے، اور ہمیں اپنے رب ہی کی طرف پلٹ کر جانا ہے، اے اللہ! میں اپنے اس سفر میں تجھ سے نیکی اور تقوی اور پسندیدہ اعمال کا سوال کرتا ہوں، اے اللہ! ہمارے اس سفر کو ہمارے لیے آسان فرما دے، اے اللہ! ہمارے لیے مسافت کو لپیٹ دے، اے اللہ! تو ہی رفیق سفر ہے، اور تو ہی اہل و عیال اور مال میں میرا قائم مقام ہے\"، اور جب سفر سے واپس لوٹتے تو مذکورہ دعا پڑھتے اور اس میں اتنا اضافہ کرتے: «آيبون تائبون عابدون لربنا حامدون» \"ہم امن و سلامتی کے ساتھ سفر سے لوٹنے والے، اپنے رب سے توبہ کرنے والے، اس کی عبادت اور حمد و ثنا کرنے والے ہیں\"، نبی اکرم صلی اللہ علیہ وسلم اور آپ کے لشکر کے لوگ جب چڑھائیوں پر چڑھتے تو \"اللہ اکبر\" کہتے، اور جب نیچے اترتے تو \"سبحان اللہ\" کہتے، پھر نماز بھی اسی قاعدہ پر رکھی گئی ۱؎۔\n§وضاحت\n۱؎ : چنانچہ رکوع میں «سبحان ربي العظيم» اور سجدہ میں «سبحان ربي الأعلى» اور اٹھتے وقت «الله أكبر» کہا جاتا ہے۔","صحیح",{"u2":"سیدنا عبداللہ بن عمر رضی اللہ عنہ نے جناب علی الازدی کو سفر کے آداب میں یہ سکھایا کہ رسول اللہ صلی اللہ علیہ وسلم جب کسی سفر کی غرض سے اپنے اونٹ پر بیٹھ جاتے تو تین دفعہ کہتے «الله اكبر» پھر کہتے «سبحان الذي سخر لنا هذا و كنا له مقرنين، وإنا إلى ربنا لمنقلبون، اللهم إني أسألك في سفرنا هذا البر والتقوى ومن العمل ترضى، اللهم هون علينا سفرنا هذا، اللهم اطو لنا البعد، اللهم أنت الصاحب في السفر والخليفة في الأهل والمال» ” پاک ہے وہ ذات جس نے اس سواری کو ہمارے تابع کیا، ہم (ازخود) اس کو اپنا تابع نہ بنا سکتے تھے اور بلاشبہ ہم اپنے رب کی طرف ہی لوٹ جانے والے ہیں۔ اے ا اللہ! میں تجھ سے اپنے اس سفر میں نیکی اور تقوی کا سوال کرتا ہوں اور ایسے عمل کی توفیق چاہتا ہوں جو تیرا پسندیدہ ہو، اے ا اللہ! ہمارے لیے ہمارا یہ سفر آسان فر دے اور مسافت کو ہمارے لیے لپیٹ دے، اے ا اللہ! سفر میں تو ہی رفیق اور اہل اور مال میں خلیفہ ہے۔ “ اور جب واپس تشریف لاتے تو یہ کلمات پڑھتے اور ان میں یہ اضافہ کرتے «آيبون تائبون عابدون لربنا حامدون» ” ہم واپس آنے والے ہیں، توبہ کرنے والے ہیں، اپنے رب کی عبادت کرنے والے اور اس کی حمد کرنے والے ہیں۔ “ نبی کریم صلی اللہ علیہ وسلم اور آپ کے لشکری جب کسی گھاٹی پر چڑھتے تو «الله اكبر» اور اگر کسی پستی میں اترتے تو «سبحان الله» کہتے اور نماز بھی اسی قاعدے پر ہے (کہ اٹھتے بیٹھتے تکبیر کہی جاتی ہے)۔","f2":"1۔توحید یہی ہے کہ انسان کسی بھی موقع پراپنے رب تعالیٰ کو بھولنے نہ پائے۔اللہ اور اس کے رسول صلی اللہ علیہ وسلم کی محبت اسی میں ہے۔ کہ ہر ہر عمل میں آپ صلی اللہ علیہ وسلم کی اقتداء کی جائے۔2۔حدیث کا جملہ (فوضعت الصلواۃ علیٰ ذلک) اور نماز بھی اسی قاعدے پر ہے۔ضعیف ہے۔(علامہ البانی)"}],[2600,"قزعہ کہتے ہیں کہ مجھ سے ابن عمر رضی اللہ عنہما نے کہا: آؤ میں تمہیں اسی طرح رخصت کروں جیسا کہ رسول اللہ صلی اللہ علیہ وسلم نے مجھے رخصت کیا تھا: «أستودع الله دينك وأمانتك وخواتيم عملك» \"میں تمہارے دین، تمہاری امانت اور تمہارے انجام کار کو اللہ کے سپرد کرتا ہوں\"۔","صحیح",{"u2":"سیدنا قزعہ کہتے ہیں کہ سیدنا عبداللہ بن عمر رضی اللہ عنہ نے مجھ سے کہا: ادھر آؤ! میں تمہیں الوداع کہوں، جیسے کہ مجھے رسول اللہ صلی اللہ علیہ وسلم نے الوداع کہا تھا: «أستودع الله دينك وأمانتك وخواتيم عملك» ” میں تیرے دین، تیری امانت اور تیرے عمل کے اختتام کو ا اللہ تعالیٰ کے حوالے کرتا ہوں۔ “"}],[2601,"عبداللہ خطمی رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم جب لشکر کو رخصت کرنے کا ارادہ کرتے تو فرماتے: «أستودع الله دينكم وأمانتكم وخواتيم أعمالكم» \"میں تمہارے دین، تمہاری امانت اور تمہارے انجام کار کو اللہ کے سپرد کرتا ہوں\"۔","صحیح",{"u2":"سیدنا عبداللہ خطمی رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم جب کسی لشکر کو الوداع کہنا چاہتے تو یوں فرماتے «أستودع الله دينكم وأمانتكم وخواتيم أعمالكم» ” میں تمہارا دین، تمہاری امانتیں اور تمہارے اعمال کا اختتام ا اللہ تعالیٰ کے سپرد کرتا ہوں۔ “","f2":"قابل توجہ مسئلہ ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے انسان کےلئے سب سے قیمتی سرمایہ اس کے دین کو قرار دیا ہے۔اوراسی طرح ان اعمال کو بھی (بالخصوص اختتامی اعمال کو)جن کے ساتھ وہ اپنے اللہ سے ملنے والاہے۔2۔حدیث میں ہے۔(ان الله اذا استودع شيئا حفظه)(الصحیحہ حدیث 2547) جب کسی چیز کو اللہ کے سپرد کردیاجاتاہے۔تو اللہ تعالیٰ اس کی حفاظت فرماتا ہے۔"}],[2602,"علی بن ربیعہ رضی اللہ عنہ کہتے ہیں کہ میں علی رضی اللہ عنہ کے پاس حاضر ہوا، آپ کے لیے ایک سواری لائی گئی تاکہ اس پر سوار ہوں، جب آپ نے اپنا پاؤں رکاب میں رکھا تو «بسم الله» کہا، پھر جب اس کی پشت پر ٹھیک سے بیٹھ گئے تو «الحمد الله» کہا، اور«سبحان الذي سخر لنا هذا وما كنا له مقرنين * وإنا إلى ربنا لمنقلبون» کہا، پھر تین مرتبہ «الحمد الله» کہا، پھر تین مرتبہ«الله اكبر» کہا، پھر «سبحانك إني ظلمت نفسي فاغفر لي فإنه لا يغفر الذنوب إلا أنت» کہا، پھر ہنسے، پوچھا گیا: امیر المؤمنین! آپ کیوں ہنس رہے ہیں؟ تو انہوں نے کہا: میں نے نبی اکرم صلی اللہ علیہ وسلم کو دیکھا کہ آپ نے ایسے ہی کیا جیسے کہ میں نے کیا پھر آپ ہنسے تو میں نے پوچھا: اللہ کے رسول! آپ کیوں ہیں ہنس رہے ہیں؟ آپ صلی اللہ علیہ وسلم نے فرمایا: \"تیرا رب اپنے بندے سے خوش ہوتا ہے جب وہ کہتا ہے: میرے گناہوں کو بخش دے وہ جانتا ہے کہ گناہوں کو میرے علاوہ کوئی نہیں بخش سکتا ہے\"۔","صحیح لغیرہ",{"u2":"جناب علی بن ربیعہ کہتے ہیں کہ میں سیدنا علی بن ابی طالب رضی اللہ عنہ کے ہاں حاضر تھا کہ سوار ہونے کے لیے آپ کے سامنے سواری لائی گئی۔ آپ نے جب اپنا پاؤں رکاب میں ڈال لیا تو کہا: «بسم الله» پھر جب ٹھیک طرح سے اس پر بیٹھ گئے تو کہا: «الحمد الله» پھر کہا: «سبحان الذي سخر لنا هذا و كنا له مقرنين، وإنا إلى ربنا لمنقلبون» ” پاک ہے وہ ذات جس نے اس کو ہمارے تابع کیا اور ہم از خود اس کو اپنا تابع نہ بنا سکتے تھے اور بلاشبہ ہم اپنے رب ہی کی طرف لوٹ جانے والے ہیں۔ “ پھر کہا: «الحمد الله» تین بار۔ پھر کہا: «الله اكبر» تین بار۔ پھر کہا: «سبحانك إني ظلمت نفسي فاغفر لي فإنه لا يغفر الذنوب إلا أنت» ” اے ا اللہ! تو پاک ہے میں نے اپنی جان پر ظلم کیا ہے تو مجھے معاف فر دے ‘ بلاشبہ تیرے سوا اور کوئی نہیں جو گناہوں کو بخش سکے۔ “ پھر آپ ہنسے۔ آپ سے کہا گیا: امیر المؤمنین! آپ کس بات پر ہنسے ہیں؟ فرمایا: میں نے رسول اللہ صلی اللہ علیہ وسلم کو دیکھا تھا کہ آپ صلی اللہ علیہ وسلم نے ایسے ہی کیا تھا جیسے کہ میں نے کیا ہے اور آپ صلی اللہ علیہ وسلم ہنسے (بھی) تھے ‘ تو میں نے آپ صلی اللہ علیہ وسلم سے دریافت کیا تھا: اے ا اللہ کے رسول! آپ کس بات پر ہنسے ہیں؟ آپ صلی اللہ علیہ وسلم نے فرمایا ” بلاشبہ تیرے رب کو اپنے بندے پر تعجب آتا ہے جب وہ کہتا ہے (الٰہی!) میرے گناہ بخش دے ‘ بندہ جانتا ہے کہ تیرے سوا گناہوں کو کوئی بخش نہیں سکتا۔ “","f2":"اسلام انسان کامذاج ایسا بنا دینا چاہتا ہے۔ کہ زندگی کا کوئی لمحہ بھی ایسا نہ گزرے جس سے وہ اپنے خالق ومالک سے غافل ہو۔چاہیے کہ ہر حال میں اللہ کی نعمتوں کا شکر ادا کیاجائے۔اور اسی طرح جسطرح رسول اللہ صلی اللہ علیہ وسلم نے کر کے دیکھایا ہے۔اسے بقدر امکان اختیار کیا جائے۔"}],[2603,"عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم جب سفر کرتے اور رات ہو جاتی تو فرماتے: «يا أرض ربي وربك الله أعوذ بالله من شرك وشر ما فيك وشر ما خلق فيك ومن شر ما يدب عليك وأعوذ بالله من أسد وأسود ومن الحية والعقرب ومن ساكن البلد ومن والد وما ولد» \"اے زمین! میرا اور تیرا رب اللہ ہے، میں اللہ کی پناہ چاہتا ہوں تیرے شر سے اور اس چیز کے شر سے جو تجھ میں ہے اور اس چیز کے شر سے جو تجھ میں پیدا کی گئی ہے اور اس چیز کے شر سے جو تجھ پر چلتی ہے اور اللہ کی پناہ چاہتا ہوں شیر اور کالے ناگ سے اور سانپ اور بچھو سے اور زمین پر رہنے والے (انسانوں اور جنوں) کے شر سے اور جننے والے کے شر اور جس چیز کو جسے اس نے جنا ہے اس کے شر سے\"۔","ضعیف",{"u2":"سیدنا عبداللہ بن عمر رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم جب سفر کرتے اور رات آ جاتی تو کہتے «يا أرض ربي وربك الله أعوذ بالله من شرك وشر فيك وشر خلق فيك ومن شر يدب عليك، وأعوذ بالله من أسد وأسود ومن الحية والعقرب ومن ساكن البلد ومن والد و ولد» ” اے زمین! میرا اور تیرا رب ا اللہ ہی ہے۔ میں ا اللہ کی پناہ چاہتا ہوں تیرے شر سے ‘ اور اس شر سے جو تیرے اندر ہے اور جو تیرے اندر پیدا کیا گیا ہے اور ہر اس چیز کے شر سے جو تجھ پر چلتی پھرتی ہے۔ میں ا اللہ کی پناہ چاہتا ہوں شیر سے ‘ کالے ناگ سے اور سانپ اور بچھو سے اور اس علاقے کے رہنے والوں کے شر سے ‘ اور جننے والے کے شر سے اور جس کو وہ جنے اس کے شر سے۔ “","f2":"اس علاقے کے رہنے والوں سے مراد جن ہیں۔اور کہا جاتا ہے کہ جننے والے سے مراد شیطان اور اس کی اولاد ہے۔مگر الفاظ اپنے عموم سے ہر جننے والے اورجنے گئے کوشامل ہیں۔"}],[2604,"جابر رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جب سورج ڈوب جائے تو اپنے جانوروں کو نہ چھوڑو یہاں تک کہ رات کی ابتدائی سیاہی چلی جائے، کیونکہ شیاطین سورج ڈوبنے کے بعد فساد مچاتے ہیں یہاں تک کہ رات کی ابتدائی سیاہی چلی جائے\" ۱؎۔ ابوداؤد کہتے ہیں: «فواشی» ہر شیٔ کا وہ حصہ ہے جو پھیل جائے۔\n§وضاحت\n۱؎ : اس حدیث سے معلوم ہوا کہ پہلے پیدل یا جانوروں کی سورای والے سفر میں مغرب کے وقت ٹھہر جانا چاہئے، پھر اندھیرا ہونے پر چلنا چاہئے۔","صحیح",{"u2":"سیدنا جابر رضی اللہ عنہ کا بیان ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” سورج غروب ہوتے ہی اپنے چوپایوں کو مت چھوڑو ‘ حتیٰ کہ رات کا اندھیرا خوب چھا جائے ‘ بلاشبہ جس وقت سورج غروب ہوتا ہے شیاطین فساد کرتے ہیں ‘ حتیٰ کہ رات کا اندھیرا چھا جائے۔ “ امام ابوداؤد رضی اللہ عنہ فرماتے ہیں کہ «الفواشي» سے مراد ہر قسم کی گھومنے پھرنے والی چیزیں ہیں۔","f2":"مستحب ہے کہ مغرب کے وقت سفرقدرے موقوف کرلیا جائے۔اور پھر اندھیرا چھانے پر باقی سفر کیا جائے۔"}],[2605,"کعب بن مالک رضی اللہ عنہ کہتے ہیں کہ بہت کم ایسا ہوتا کہ رسول اللہ صلی اللہ علیہ وسلم جمعرات کے علاوہ کسی اور دن سفر میں نکلیں(یعنی آپ اکثر جمعرات ہی کو نکلتے تھے) ۔","صحیح",{"u2":"سیدنا کعب بن مالک رضی اللہ عنہ سے مروی ہے انہوں نے کہا کہ بہت کم ایسے ہوتا کہ رسول اللہ صلی اللہ علیہ وسلم جمعرات کے علاوہ کسی اور دن سفر کے لیے نکلتے۔","f2":"دن سب اللہ کے ہیں مگر جمعرات کو اہمیت حاصل ہےکہ اس روز اللہ کے حضور اعمال پیش ہوتے ہیں۔"}],[2606,"صخر غامدی رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: «اللهم بارك لأمتي في بكورها» \"اے اللہ! میری امت کے لیے دن کے ابتدائی حصہ میں برکت دے\" اور جب بھی آپ صلی اللہ علیہ وسلم کوئی سریہ یا لشکر بھیجتے، تو دن کے ابتدائی حصہ میں بھیجتے۔ (عمارہ کہتے ہیں) صخر ایک تاجر آدمی تھے، وہ اپنی تجارت صبح سویرے شروع کرتے تھے تو وہ مالدار ہو گئے اور ان کا مال بہت ہو گیا۔ ابوداؤد کہتے ہیں: صخر سے مراد صخر بن وداعہ ہیں۔","صحیح",{"u2":"سیدنا صخر غامدی رضی اللہ عنہ بیان کرتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا ” اے ا اللہ! میری امت کے لیے ان کی صبحوں میں برکت ڈال دے۔ “ چنانچہ آپ صلی اللہ علیہ وسلم کو کوئی مہم یا لشکر روانہ کرنا ہوتا تو انہیں دن کے پہلے پہر روانہ فرماتے۔ اور سیدنا صخر رضی اللہ عنہ ایک تاجر صحابی تھے ‘ تو وہ اپنے کارندوں کو دن کے پہلے پہر روانہ کیا کرتے تھے ‘ چنانچہ وہ مالدار ہو گئے تھے اور ان کا مال خوب بڑھ گیا تھا۔ امام ابوداؤد رضی اللہ عنہ نے کہا: ان کا نام صخر بن وداعہ ہے۔"}],[2607,"عبداللہ بن عمرو رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"ایک سوار شیطان ہے اور دو سوار دو شیطان ہیں، اور تین سوار قافلہ ہیں\" ۱؎۔\n§وضاحت\n۱؎ : ایک سوار کو شیطان کہا گیا کیونکہ اکیلا مسافر جماعت نہیں قائم کر سکتا، اور بوقت مصیبت اس کا کوئی معاون و مددگار نہیں ہوتا، اور دو سوار شیطان اس لئے ہیں کہ جب ان میں سے ایک کسی مصیبت و آفت سے دوچار ہوتا ہے تو دوسرا اس کی خاطر اس طرح مضطرب و پریشان ہو جاتا ہے کہ اس کی پریشانی کو دیکھ کر شیطان بے حد خوش ہوتا ہے، اور اگر مسافر تعداد میں تین ہیں تو مذکورہ پریشانیوں سے محفوظ رہتے ہیں۔","حسن",{"u2":"سیدنا عمرو بن شعیب اپنے والد (شعیب) سے اور وہ (شعیب) اپنے دادا سے روایت کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” اکیلا سوار ایک شیطان ہے ‘ دو سوار دو شیطان ہیں اور تین سوار ایک قافلہ ہیں۔ “","f2":"۔انسان کااکیلے سفر کرنا بعض اوقات انتہائی خطرناک ہوسکتاہے۔بالفرض کوئی حادثہ پیش آجائے تو اسے سنبھالنے والا کوئی نہ ہوگا۔اور نہ کوئی خبر ہی ملے گی۔ اس طرح دو افراد کا معاملہ بہت کمزور ہے۔البتہ تین ہوں تو سب کو مکمل سہولت ہوگی۔باجماعت نماز پڑھیں گے۔ایک دوسرے کے انیس اور معاون ہوں گے۔2،۔موجودہ حالات میں بسوں گاڑیوں اورجہازوں میں اگرچہ ایک کثیرتعداد بطور قافلہ کے سفرکرتی ہے۔اور مذکورنہی سے انسان خارج ہوجاتاہے۔مگر انسان کو اپنے محب اور انیس رفیق سفر ہوں۔تو بہت ہی افضل ہے۔کیونکہ عام ہمراہی کئی طرح کے ہوتے ہیں۔بالخصوص اب جبکہ شروفساد بہت بڑھ گیا ہے۔اوردین وامانت میں کمی آتی جارہی ہے۔3۔یہ حدیث تنہا سفر کرنے کی قباحت پر صریح دلالت کرتی ہے۔اس لئے بعض اہل علم نے اس حدیث سے یہ استنباط کیا ہے۔کہ صوفی قسم کے لوگ تن تنہا تہذیب نفس اور مزعومہ چلہ کشی کے نام پرصحرائوں اور بے آباد علاقوں کے جو سفر اخیتار کرتے ہیں۔وہ بھی صریحا غلط اور مردود ہیں۔ایسے ہی وہ چلہ کشی جو آجکل بزرگ اور ولی اللہ بننے کے چکر میں کی جاتی ہے۔یہ بھی قرآن وحدیث کے منافی ہے۔ اس لئے ایسے تمام امور سے احتراز اور اجتناب ضروری ہے۔کیونکہ یہ چیزیں بدعت ہیں۔بدعت کے بارے میں رسول اللہ صلی اللہ علیہ وسلم کا واضح فرمان ہے۔کہ جس نے بھی دین اسلام میں کوئی نئی بات پیدا کی جو اس میں نہیں ہے وتو وہ مردود ہے۔ـ(صحیح البخاری۔الصلح حدیث 2697)"}],[2608,"ابو سعید خدری رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جب تین افراد کسی سفر میں ہوں تو ہوئے کہ اپنے میں سے کسی ایک کو امیر بنا لیں\"۔","حسن صحیح",{"u2":"سیدنا ابو سعید خدری رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” جب تین افراد سفر پر نکلیں تو چاہیئے کہ ایک کو اپنا امیر مقرر کر لیں۔ “"}],[2609,"ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جب تین افراد کسی سفر میں ہوں تو ان میں سے کسی کو امیر بنا لیں ۱؎\"، نافع کہتے ہیں: تو ہم نے ابوسلمہ سے کہا: آپ ہمارے امیر ہیں۔\n§وضاحت\n۱؎ : آپ صلی اللہ علیہ وسلم نے یہ حکم اس لئے دیا تا کہ ان میں آپس میں اجتماعیت برقرار رہے اور اختلاف کی نوبت نہ آئے اور ایسا جبھی ممکن ہے جب وہ کسی امیر کے تابع ہوں گے۔","حسن صحیح",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ سے منقول ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” جب تین افراد سفر میں ہوں تو چاہیئے کہ ایک کو اپنا امیر بنا لیں۔ “ نافع رضی اللہ عنہ (مولیٰ ابن عمر رضی اللہ عنہ) نے کہا: (یہ حدیث سننے کے بعد) ہم نے ابوسلمہ (بن عبدالرحمٰن بن عوف) سے کہا: آپ ہمارے امیر ہیں۔","f2":"1۔اس نظم سے امور سفر مرتب اور آسان ہوجاتے ہیں۔اورسب کو سہولت رہتی ہے۔نفسی نفسی کا عالم نہیں ہوتا۔نیز جب اس معمولی اجتماع میں امیر مقرر کرنے کی تاکید ہے۔توامارت عظمیٰ کی اہمیت اور بھی زیادہ ہوئی۔2۔قوم کو کسی بھی وقت امیر اور امارت کے بغیر نہیں رہنا چاہیے۔"}],[2610,"نافع سے روایت ہے کہ عبداللہ بن عمر رضی اللہ عنہما نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے قرآن کو دشمن کی سر زمین میں لے کر سفر کرنے سے منع فرمایا ہے، مالک کہتے ہیں: میرا خیال ہے اس واسطے منع کیا کہ کہیں ایسا نہ ہو کہ دشمن اسے پا لے ۱؎۔\n§وضاحت\n۱؎ : اور اس کی بے حرمتی کرے۔","صحیح مسلم میں آخری ٹکڑا اصلِ حدیث میں سے ہے نہ کہ قولِ مالک سے",{"u2":"سیدنا عبداللہ بن عمر رضی اللہ عنہ سے روایت ہے انہوں نے کہا کہ رسول اللہ صلی اللہ علیہ وسلم نے منع فرمایا ہے کہ انسان قرآن مجید لے کر دشمن کے علاقے میں جائے۔ امام مالک رضی اللہ عنہ فرماتے ہیں ‘ میرا خیال ہے اس نہی کی حکمت یہ ہے کہ کہیں یہ دشمن (کافر) کے ہاتھ نہ لگ جائے (اور وہ اس کی ہتک کرے۔)","f2":"جہاں بھی یہ اندیشہ ہو کہ قرآن کریم کی ہتک کی جائےگی۔اسے وہاں نہ لے جایاجائے۔لیکن اگر کافر قرآن سمجھنا چاہتا ہو۔ اور اسے اسلام کی دعوت دینا مقصود ہو تو اس غرض سے اس کو دینا جائز ہے۔جیسے کہ ہرقل کے نام خط لکھا گیا۔اور اس میں قرآن مجید کی آیت (آل عمران۔64) لکھی گئی تھی۔"}],[2611,"عبداللہ بن عباس رضی اللہ عنہما سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"بہتر ساتھی وہ ہیں جن کی تعداد چار ہو ۱؎، اور چھوٹی فوج میں بہتر فوج وہ ہے جس کی تعداد چار سو ہو، اور بڑی فوجوں میں بہتر وہ فوج ہے جس کی تعداد چار ہزار ہو، اور بارہ ہزار کی فوج قلت تعداد کی وجہ سے ہرگز مغلوب نہیں ہو گی ۲؎\"۔ ابوداؤد کہتے ہیں: صحیح یہ ہے کہ یہ مرسل ہے۔\n§وضاحت\n۱؎ : یعنی کم سے کم چار ہو کیونکہ ان میں سے اگر کبھی کوئی بیمار ہو اور وہ اپنے کسی ساتھی کو وصیت کرنا چاہے تو گواہی کے لئے ان میں سے دو باقی رہ جائیں، اس حدیث میں (بشرط صحت) مرتبہ أقل کا بیان ہے علماء نے لکھا ہے : چار سے پانچ بہتر ہیں بلکہ جس قدر زیادہ ہوں گے اتنا ہی خیر ہو گا۔ ۲؎ : بارہ ہزار کا لشکر اپنی قلت کے سبب ہرگز نہیں ہارے گا، اب اگر دوسری قومیں اس پر غالب آ گئیں تو اس ہار کا سبب قلت نہیں بلکہ لشکر کا عجب و غرور میں مبتلا ہونا یا اسی طرح کا کوئی اور دوسرا سبب ہو سکتا ہے۔","ضعیف",{"u2":"سیدنا ابن عباس رضی اللہ عنہ سے مروی ہے کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا ” بہترین رفقاء وہ ہیں جو چار کی تعداد میں ہوں اور بہترین دستہ وہ ہے جس میں چار سو شہسوار ہوں اور بہترین لشکر وہ ہے جو چار ہزار کی تعداد میں ہو اور بارہ ہزار قلت کی بنا پر ہرگز مغلوب نہیں ہو سکتے۔ “ امام ابوداؤد رضی اللہ عنہ فرماتے ہیں صحیح یہ ہے کہ یہ روایت مرسل ہے۔","f2":"تعداد جس قدر زیادہ ہوگی۔برکت اور فائدہ زیادہ ہوگا۔مسلمانوں کو بارہ ہزار کی تعداد اگر کہیں شکست کھائے گی۔تواس کا سبب قلت تعدادنہیں بلکہ کوئی اور سبب ہوگا۔مثلا عدم تقویٰ۔تکبر۔غرور اور بذدلی وغیرہ تاہم یہ روایت مرسل ہے جو محدثین کے نزدیک ضعیف ہوتی ہے۔"}],[2612,"بریدہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم جب کسی لشکر یا سریہ کا کسی کو امیر بنا کر بھیجتے تو اسے اپنے نفس کے بارے میں اللہ کے تقوی کی وصیت کرتے، اور جو مسلمان اس کے ساتھ ہوتے ان کے ساتھ بھلائی کرنے کا حکم دیتے، اور فرماتے: \"جب تم اپنے مشرک دشمنوں کا سامنا کرنا تو انہیں تین چیزوں کی دعوت دینا، ان تینوں میں سے جس چیز کو وہ مان لیں تم ان سے اسے مان لینا اور ان سے رک جانا، (سب سے پہلے) انہیں اسلام کی جانب بلانا، اگر تمہاری اس دعوت کو وہ لوگ تسلیم کر لیں تو تم اسے قبول کر لینا اور ان سے لڑائی کرنے سے رک جانا، پھر انہیں اپنے وطن سے مہاجرین کے وطن کی طرف ہجرت کرنے کا حکم دینا، اور انہیں یہ بتانا کہ اگر وہ ایسا کریں گے تو ان کے لیے وہی چیز ہو گی جو مہاجرین کے لیے ہو گی، اور ان کے وہی فرائض ہوں گے، جو مہاجرین کے ہیں، اور اگر وہ انکار کریں اور اپنے وطن ہی میں رہنا چاہیں تو انہیں بتانا کہ وہ دیہاتی مسلمانوں کی طرح ہوں گے، ان پر اللہ کا وہی حکم چلے گا جو عام مسلمانوں پر چلتا ہے، اور فے اور مال غنیمت میں ان کا کوئی حصہ نہ ہو گا، الا یہ کہ وہ مسلمانوں کے ساتھ جہاد کریں، اور اگر وہ اسلام لانے سے انکار کریں تو انہیں جزیہ کی ادائیگی کی دعوت دینا، اگر وہ لوگ جزیہ کی ادائیگی قبول کر لیں تو ان سے اسے قبول کر لینا اور جہاد کرنے سے رک جانا، اور اگر وہ جزیہ بھی دینے سے انکار کریں تو اللہ سے مدد طلب کرنا، اور ان سے جہاد کرنا، اور اگر تم کسی قلعہ والے کا محاصرہ کرنا اور وہ چاہیں کہ تم ان کو اللہ کے حکم پر اتارو، تو تم انہیں اللہ کے حکم پر مت اتارنا، اس لیے کہ تم نہیں جانتے ہو کہ اللہ ان کے سلسلے میں کیا فیصلہ کرے گا، لیکن ان کو اپنے حکم پر اتارنا، پھر اس کے بعد ان کے سلسلے میں تم جو چاہو فیصلہ کرنا\"۔ سفیان بن عیینہ کہتے ہیں: علقمہ کا کہنا ہے کہ میں نے یہ حدیث مقاتل بن حیان سے ذکر کی تو انہوں نے کہا: مجھ سے مسلم نے۔ ابوداؤد کہتے ہیں: وہ ابن ہیصم ہیں، بیان کیا انہوں نے نعمان بن مقرن رضی اللہ عنہ سے اور نعمان رضی اللہ عنہ نے نبی اکرم صلی اللہ علیہ وسلم سے سلیمان بن بریدہ کی حدیث کے مثل روایت کیا۔","صحیح",{"u2":"سیدنا سلیمان بن بریدہ اپنے والد سے بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم جب (کسی شخص کو) کسی دستے یا کسی بڑے لشکر کا امیر بنا کر روانہ کرتے تو اسے خود اپنی ذات میں ا اللہ کا تقویٰ اختیار کرنے اور اپنی معیت میں دوسرے مسلمانوں کے ساتھ بھلائی کرنے کی وصیت کرتے اور فرماتے ” جب تم اپنے مشرک دشمن کے مقابلے پر آؤ تو انہیں تین باتوں کی دعوت دو ‘ وہ جسے بھی اختیار کرنا چاہیں کر لیں اور پھر جو وہ اختیار کر لیں اسے قبول کر لینا اور اپنے ہاتھ کو ان سے روک لینا۔ (سب سے پہلے) انہیں اسلام کی دعوت دینا، اگر وہ اسے قبول کر لیں تو تم بھی ان سے قبول کر لو اور ان سے اپنے ہاتھ روک لو۔ پھر انہیں دعوت دو کہ وہ اپنا علاقہ چھوڑ کر دارلمہاجرین میں منتقل ہو جائیں اور انہیں بتاؤ کہ اگر انہوں نے یہ امر قبول کر لیا تو ان کو وہی حقوق حاصل ہوں گے جو مہاجرین کو حاصل ہیں اور ان پر وہ سب کچھ واجب ہو گا جو ان مہاجرین پر واجب ہے ‘ اگر وہ منتقل ہونا قبول نہ کریں اور اپنے علاقوں ہی میں رہنا چاہیں ‘ تو انہیں بتانا کہ وہ بدوی مسلمانوں کی طرح ہوں گے ‘ ان پر ا اللہ کا حکم اسی طرح نافذ ہو گا جیسے کہ دیگر مومنین پر نافذ ہوتا ہے ‘ (مال) فے اور غنیمت میں ان کا کوئی حصہ نہ ہو گا ‘ سوائے اس کے کہ مسلمانوں کے ساتھ جہاد میں شریک ہوں۔ (2) پس اگر وہ لوگ اسلام قبول کرنے سے انکاری ہوں تو انہیں کہنا کہ جزیہ دینا قبول کریں اگر وہ اس پر راضی ہو جائیں تو اسے قبول کر لینا اور اپنا ہاتھ ان سے روک لینا۔ (3) اگر وہ جزیہ دینے پر راضی نہ ہوں تو ا اللہ کی مدد طلب کرتے ہوئے ان سے قتال کرنا۔ اور جب تم کسی قلعے والوں کا محاصرہ کر لو اور پھر وہ تم سے یہ چاہیں کہ ان کو ہتھیار ڈالنے دو ‘ اس شرط پر کہ ان پر ا اللہ کا حکم نافذ ہو تو یہ بات قبول نہ کرنا کیونکہ تم نہیں جانتے کہ ان کے بارے میں ا اللہ کا فیصلہ کیا ہے ‘ لیکن انہیں اپنی شرطوں اور فیصلے کے مطابق ہتھیار ڈالنے کی اجازت دو اور پھر جو چاہو ان کے متعلق فیصلہ کرو۔ “ سفیان بن عیینہ کہتے ہیں کہ علقمہ نے کہا: میں نے یہ حدیث مقاتل بن حیان سے ذکر کی تو انہوں نے کہا: مجھے مسلم نے بیان کیا۔ امام ابوداؤد رضی اللہ عنہ نے کہا: اس (مسلم) سے مراد مسلم بن ہیصم ہے۔ اس نے نعمان بن مقرن رضی اللہ عنہ سے اور انہوں نے نبی کریم صلی اللہ علیہ وسلم سے بیان کیا جیسے کہ سیلمان بن بریدہ نے بیان کیا ہے۔","f2":"یہ حکم ابتدائے اسلام میں تھا۔اوراب بھی ان قوموںسے متعلق ہے۔ جن کو اسلام کی دعوت واضح طور سے نہ پہنچی ہو۔(صحیح البخاری۔العتق۔حدیث 2541 وصحیح مسلم الجہاد حدیث 1730 وسنن ابی دائود۔حدیث 2633)2۔دین اسلا م کی دوسرے دینوں سے آویزش صرف اور صرف اللہ کی مخلوق تک اس کا کلمہ پہنچانے اور غالب کرنے کے لئے ہے۔اس میں محض ملکوں کو فتح کرنا یا لوگوں کو اپنے تابع کرنا نہیں ہے۔3۔امیر مجاہدین(اور اس طرح دیگر مفتیان اور مجتہدین) کا فیصلہ بالعموم اللہ اور اس کے رسول صلی اللہ علیہ وسلم کے دیئے ہوئے اصولوں کے مطابق ہوتا ہے۔اس کے باوجود ان میں سے اس کے حق یا خطا ہونے کا احتمال رہتاہے۔(ان اجتہادی امور میں) عین یہی دعویٰ کرنا کہ یہی اللہ کا فیصلہ ہے۔بالکل غلط ہے۔جبکہ رسول اللہ صلی اللہ علیہ وسلم کی زبان سے صادر ہونے والے فیصلے اور احکام عین اللہ کے فیصلے ہوتے تھے۔ اور عین شریعت ہوتے تھے کیونکہ\n(وَمَا يَنطِقُ عَنِ الْهَوَىٰ ﴿٣﴾ إِنْ هُوَ إِلَّا وَحْيٌ يُوحَىٰ)(انجم۔3۔4)\nآپ اپنی خواہش نفس سے نہیں بولتے مگر جو اللہ کی وحی ہوتی ہے اور اجتہادی امور میں جہاں کہیں کوئی خطا ہوتی بھی تو فورا ً اس کی اصلاح ہوجاتی تھی نبی کریم صلی اللہ علیہ وسلم کے بعد کسی بھی امتی کو یہ مقام حاصل نہیں ہے۔"}],[2613,"بریدہ رضی اللہ عنہ روایت کرتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"اللہ کے نام سے اور اللہ کے راستے میں غزوہ کرو اور اس شخص سے جہاد کرو جو اللہ کا انکار کرے، غزوہ کرو، بدعہدی نہ کرو، خیانت نہ کرو، مثلہ نہ کرو، اور کسی بچہ کو قتل نہ کرو\"۔","صحیح",{"u2":"سیدنا سیلمان بن بریدہ اپنے والد سے بیان کرتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا ” ا اللہ کے نام سے اور ا اللہ کی راہ میں غزوہ کرو اور ا اللہ کا انکار کرنے والوں سے قتال کرو۔ غزوہ کرو غدر نہ کرو ‘ (غنیمت میں) خیانت نہ کرو ‘ مقتولین کے اعضا نہ کاٹو اور نہ کسی بچے کو قتل کرو۔ “"}],[2614,"انس بن مالک رضی اللہ عنہ کا بیان ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے (مجاہدین کو رخصت کرتے وقت) فرمایا: \"تم لوگ اللہ کے نام سے، اللہ کی تائید اور توفیق کے ساتھ، اللہ کے رسول کے دین پر جاؤ، اور بوڑھوں کو جو مرنے والے ہوں نہ مارنا، نہ بچوں کو، نہ چھوٹے لڑکوں کو، اور نہ ہی عورتوں کو، اور غنیمت میں خیانت نہ کرنا، اور غنیمت کے مال کو اکٹھا کر لینا، صلح کرنا اور نیکی کرنا، اللہ نیکی کرنے والوں کو پسند فرماتا ہے\"۔","ضعیف",{"u2":"سیدنا انس بن مالک رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” چلو ا اللہ کے نام سے ‘ ا اللہ کی مدد حاصل کرتے ہوئے اور رسول ا اللہ (صلی اللہ علیہ وسلم) کی ملت پر قائم رہتے ہوئے (اور اس کی دعوت دیتے ہوئے) کسی بڈھے کھوسٹ کو قتل نہ کرنا ‘ نہ کسی بچے یا نابالغ کو اور نہ کسی عورت کو۔ (غنیمت میں) خیانت سے باز رہنا ‘ غنائم کو جمع رکھنا اور اصلاح کا معاملہ کرنا ‘ نیکی اور احسان اپنانا ‘ بلاشبہ ا اللہ تعالیٰ احسان کرنے والوں سے محبت کرتا ہے۔ “","f2":"لڑائی میں کسی بوڑھے شخص کو قتل نہیں کرنا۔مگر ایسے بوڑھے جن کے بارے میں معلوم ہو کہ مصوبے اور پروگرام دیتے ہیں۔اور ایسی عورتیں جو جاسوسی وغیرہ کے معاملات میں ملوث ہوں۔ان کو قتل کرنا جائز ہوگا۔"}],[2615,"عبداللہ بن عمر رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے بنونضیر کے کھجوروں کے باغات جلا دیے اور درختوں کو کاٹ ڈالا (یہ مقام بویرہ میں تھا) تو اللہ نے یہ آیت کریمہ نازل فرمائی «ما قطعتم من لينة أو تركتموها» \"کھجور کے جو درخت تم نے کاٹ ڈالے، یا اپنی جڑوں پر انہیں قائم رہنے دیا، یہ سب اللہ کے حکم سے تھا\" (سورۃ الحشر: ۵) ۔","صحیح",{"u2":"سیدنا عبداللہ بن عمر رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے بویرہ مقام پر قبیلہ بنو نضیر کی کھجوریں جلائی تھیں اور کاٹی بھی تھیں ‘ اس پر ا اللہ تعالیٰ نے یہ آیت نازل فرمائی «قطعتم من لينة أو تركتموها» ” جو کھجوریں تم نے کاٹ ڈالیں یا جڑوں پر قائم رہنے دیں سو وہ ا اللہ کے حکم سے تھا ‘ اور تاکہ ا اللہ تعالیٰ فاسقوں کو رسوا کر دے۔ “","f2":"جنگی ضرورت اور مصلحت کے تحت آگ لگانا یا مکانات گرانا جائز ہے۔محض فساد پھیلانے کی نیت سے جائز نہیں۔"}],[2616,"عروہ کہتے ہیں کہ اسامہ رضی اللہ عنہ نے مجھ سے بیان کیا کہ رسول اللہ صلی اللہ علیہ وسلم نے انہیں وصیت کی تھی اور فرمایا تھا: \"ابنی ۱؎پر صبح سویرے حملہ کرو اور اسے جلا دو\"۔\n§وضاحت\n۱؎ : فلسطین میں رملہ اور عسقلان کے مابین ایک مقام کا نام ہے۔","ضعیف",{"u2":"سیدنا اسامہ رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے ان سے فرمایا تھا کہ ” ابنی “ کے علاقے پر صبح کے وقت چڑھائی کرنا اور اسے جلا دینا۔"}],[2617,"عبداللہ بن عمرو غزی کہتے ہیں کہ ابومسہر کے سامنے ابنی کا تذکرہ آیا تو میں نے ان کو کہتے ہوئے سنا: ہم جانتے ہیں یہ یُبنی ہے جو فلسطین میں ہے۔","",{"u2":"عبداللہ بن عمرو غزی کہتے ہیں کہ میں نے ابومسہر سے سنا ان سے ” ابنی “ کے متعلق پوچھا گیا تو انہوں نے کہا: ہم اس کے متعلق خوب جانتے ہیں کہ یہ فلسطین میں ” یبنا “ کے نام سے معروف جگہ ہے۔"}],[2618,"انس بن مالک رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے بسیسہ کو جاسوس بنا کر بھیجا تاکہ وہ دیکھیں کہ ابوسفیان کا قافلہ کیا کر رہا ہے۔","صحیح",{"u2":"سیدنا انس رضی اللہ عنہ کا بیان ہے کہ نبی کریم صلی اللہ علیہ وسلم نے (واقعہ بدر سے پہلے) بسیسہ کو بطور جاسوس روانہ فرمایا تھا کہ وہ دیکھے کہ ابوسفیان کا قافلہ کس مرحلے میں ہے؟","f2":"مسلمانوں میں ایک دوسرے کی جاسوسی کرنا حرام ہے۔الا یہ کہ امیر المومنین اصلاح احوال کےلئے ان کے بعض امور کی ٹوہ لگائےتو جائز ہے۔تاہم دشمن کے احوال کی خبر لینے کے لئے یہ عمل سیاستاً واجب ہے۔"}],[2619,"سمرہ بن جندب رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"جب تم میں سے کوئی کسی جانور کے پاس سے گزرے اور اس کا مالک موجود ہو تو اس سے اجازت لے، اگر وہ اجازت دیدے تو دودھ دوہ کر پی لے اور اگر اس کا مالک موجود نہ ہو تو تین بار اسے آواز دے، اگر وہ آواز کا جواب دے تو اس سے اجازت لے، ورنہ دودھ دوہے اور پی لے، لیکن ساتھ نہ لے جائے ۱؎\"۔\n§وضاحت\n۱؎ : یہ حکم اس پریشان حال اور مضطر و مجبور مسافر کے لئے ہے جسے کھانا نہ ملنے کی صورت میں اپنی جان کے ہلاک ہونے کا خطرہ لاحق ہو۔","صحیح",{"u2":"سیدنا سمرہ بن جندب رضی اللہ عنہ سے روایت ہے کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا ” جب تم میں سے کوئی (دوران سفر میں) جانوروں کے پاس سے گزرے اور ان میں ان کا مالک موجود ہو تو اس سے اجازت لے ‘ اگر وہ اجازت دیدے ‘ تو دودھ دوہ لے اور پی لے ‘ اگر مالک موجود نہ ہو تو تین بار آواز لگائے ‘ اگر وہ جواب دے تو اس سے اجازت طلب کرے ورنہ دودھ نکال لے اور پی لے مگر ساتھ نہ لے جائے۔ “","f2":"ان احادیث کی کتاب الجہاد میں بیان ہون کی وجہ یہ ہے کہ مجاہدین سفر میں ہوتے ہیں۔اور کھانا پینا ان کی لازمی ضرورت ہے۔اور اہل علاقہ یہ ضروریات مہیا کرنے کے پابند ہوتے ہیں۔2۔علامہ خطابی اس حدیث کی شرح میں فرماتے ہیں۔کہ یہ رخصت ایسے مسافر کےلئے ہے۔ جو اضطراری (مجبوری کی)کیفیت میں ہوکہ اگر وہ ن کھائےپئے تو ہلاکت کااندیشہ ہو جبکہ کچھ اصحاب الحدیث کہتے ہیں۔یہ ایسا مال ہے کہ نبی کریم صلی اللہ علیہ وسلم نے اس کا مالک بنایا ہے۔(جان بچانے کی حد تک اسے کھانے کی اجازت دی ہے۔)تو اس کے لئے مباح ہے۔اور اس پرکوئی قیمت لازم نہیں آتی۔مگراکثر فقہاء کا کہنا ہے کہ اس پرقیمت لازم ہوگی۔بشرط یہ کہ وہ قیمت دے سکتاہو۔کیونکہ نبی صلی اللہ علیہ وسلم نے فرمایا ہے۔ کسی مسلمان کی خوش دلی اوررضامندی کے بغیر اس کا مال لینا حلال نہیں ہے۔ (مسنداحمد۔72/5)تاہم اگر کسی علاقے کے عرف عام میں تھوڑے بہت کھانے پینے کی اجازت ہوتو وہاں اجازت کی ضرورت ہوگی۔نہ قیمت دینے کی۔عرف عام ہی اجازت کے مترادف ہوگا۔جیسا کہ آج سے پیشتر عام دیہاتوں میں یہ عرف عام تھا۔"}],[2620,"عباد بن شرحبیل رضی اللہ عنہ کہتے ہیں کہ مجھے قحط نے ستایا تو میں مدینہ کے باغات میں سے ایک باغ میں گیا اور کچھ بالیاں توڑیں، انہیں مل کر کھایا، اور (باقی) اپنے کپڑے میں باندھ لیا، اتنے میں اس کا مالک آ گیا، اس نے مجھے مارا اور میرا کپڑا چھین لیا، میں رسول اللہ صلی اللہ علیہ وسلم کے پاس آیا (اور آپ سے سارا ماجرا بتایا)، آپ صلی اللہ علیہ وسلم نے مالک سے فرمایا: \"تم نے اسے بتایا نہیں جب کہ وہ جاہل تھا اور نہ کھلایا ہی جب کہ وہ بھوکا تھا\"، اور آپ صلی اللہ علیہ وسلم نے اسے حکم دیا اس نے میرا کپڑا واپس کر دیا اور ایک وسق(ساٹھ صاع) یا نصف وسق (تیس صاع) غلہ مجھے دیا۔","صحیح",{"u2":"سیدنا عباد بن شرحبیل کا بیان ہے کہ مجھے قحط (اور بھوک) نے ستایا ‘ تو میں مدینہ کے ایک باغ میں چلا گیا اور وہاں سے میں نے ایک بالی لی ‘ اسے مسلا اور کھا لیا اور کچھ اپنے کپڑے میں بھی باندھ لے چلا ‘ پس باغ کا مالک آ گیا تو اس نے مجھے مارا اور میرا کپڑا بھی چھین لیا۔ میں رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں آ گیا تو آپ صلی اللہ علیہ وسلم نے اس سے فرمایا ” تو نے اسے سمجھایا نہیں جبکہ یہ نادان تھا اور نہ تو نے اس کو کھلایا جبکہ یہ بھوکا تھا۔ “ (لفظ «جائعا» بولا یا «ساغبا» معنی ایک ہی ہے) پھر آپ صلی اللہ علیہ وسلم نے اس کو حکم دیا ‘ تو اس نے میرا کپڑا واپس کر دیا اور مجھے ایک وسق یا آدھا وسق طعام بھی دیا۔"}],[2621,"ابوبشر رضی اللہ عنہ کہتے ہیں کہ میں نے عباد بن شرحبیل سے جو ہمیں میں سے قبیلہ بنو غبر کے ایک فرد تھے اسی مفہوم کی حدیث سنی۔","صحیح",{"u2":"ابوبشر روایت کرتے ہیں کہ میں نے عباد بن شرحبیل سے سنا جو ہمارے قبیلہ بنی غبر میں سے تھے۔ اور مذکورہ بالا حدیث کے ہم معنی روایت کی۔","f2":"1۔فی الواقع حاجت مند کواجازت ہے کہ بغیر اجازت کے باغ اور کھیت میں سے کھا پی لے مگر ساتھ لے جانا جائز نہیں۔2۔سزا دینے سے پہلے ضروری ہے۔کہ نادان کو سمجھایا جائے اور جاہل ایک حد تک معذور بھی ہوتا ہے۔3۔حسب حیثیت ضرورت مند کی ضرورت پوری کرنا مسلمان کا فریضہ ہے۔"}],[2622,"ابورافع بن عمرو غفاری کے چچا کہتے ہیں کہ میں کم سن تھا اور انصار کے کھجور کے درختوں پر ڈھیلے مارا کرتا تھا، لوگ مجھے (پکڑ کر) نبی اکرم صلی اللہ علیہ وسلم کے پاس لائے، آپ نے فرمایا: \"بچے! تم کھجور کے درختوں پر کیوں پتھر مارتے ہو؟\" میں نے عرض کیا:(کھجوریں) کھانے کی غرض سے، آپ صلی اللہ علیہ وسلم نے فرمایا: \"پتھر نہ مارا کرو، جو نیچے گرا ہو اسے کھا لیا کرو\"، پھر آپ صلی اللہ علیہ وسلم نے میرے سر پر ہاتھ پھیرا، اور میرے لیے دعا کی کہ اے اللہ اس کے پیٹ کو آسودہ کر دے۔","ضعیف",{"u2":"سیدنا رافع بن عمرو غفاری کا بیان ہے کہ میں لڑکپن میں انصاریوں کی کھجوروں کو (پتھر وغیرہ) مارا کرتا تھا تو مجھے نبی کریم صلی اللہ علیہ وسلم کی خدمت میں پیش کیا گیا۔ آپ صلی اللہ علیہ وسلم نے پوچھا ” اے لڑکے! تو کھجوروں کو کیوں مارتا ہے؟ میں نے کہا: پھل کھانے کے لیے۔ آپ صلی اللہ علیہ وسلم نے فرمایا ” مت مارا کر ‘ جو نیچے گری پڑی ہو کھا لیا کر۔ “ پھر آپ صلی اللہ علیہ وسلم نے میرے سر پر ہاتھ پھیرا اور دعا دی: ” اے ا اللہ! اس کے پیٹ کو سیر کر دے۔ “"}],[2623,"عبداللہ بن عمر رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"کوئی کسی کے جانور کو اس کی اجازت کے بغیر نہ دوہے، کیا تم میں سے کوئی اس بات کو پسند کرتا ہے کہ اس کے بالاخانہ میں آ کر اس کا گودام توڑ کر غلہ نکال لیا جائے؟ اسی طرح ان جانوروں کے تھن ان کے مالکوں کے گودام ہیں تو کوئی کسی کا جانور اس کی اجازت کے بغیر نہ دوہے\"۔","صحیح",{"u2":"سیدنا عبداللہ بن عمر رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” تم میں سے کوئی کسی کے جانور کا بغیر اجازت دودھ نہ نکالے ‘ کیا تم پسند کرتے ہو کہ کوئی اس کی کوٹھڑی (سٹور) کو توڑ کر اس کا ذخیرہ طعام نکال لے جائے؟ (ایسے ہی) جانوروں کے تھن اپنے مالکوں کے لیے دودھ جمع کرتے ہیں تو کوئی کسی کے جانور کا دودھ نہ نکالے مگر یہ کہ مالک کی اجازت ہو۔","f2":"1۔قیاس کرنا ایک معروف شرعی وفقہی قاعدہ ہے۔اور اشباء ونظائر پرایک دوسرے کا حکم لگتا ہے۔2۔بغیر شرعی عذر کے اگر کسی نے جانوروں کا اس قدر دودھ نکال لیا۔جس کی قیمت چوری کے نصاب کو پہنچتی ہو تو اس پر چوری کی حد لگے گی۔"}],[2624,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں آیت «يا أيها الذين آمنوا أطيعوا الله وأطيعوا الرسول وأولي الأمر منكم» \"اے ایمان والو! فرمانبرداری کرو اللہ تعالی کی اور فرمانبرداری کرو رسول (صلی اللہ علیہ وسلم) کی اور اپنے میں سے اختیار والوں کی\" (سورۃ النساء: ۵۹)عبداللہ (عبداللہ بن حذافہ) قیس بن عدی رضی اللہ عنہ کے بارے میں نازل ہوئی ہے جنہیں نبی اکرم صلی اللہ علیہ وسلم نے ایک سریہ میں بھیجا تھا۔","صحیح",{"u2":"ابن جریج رضی اللہ عنہ بیان کرتے ہیں کہ (آیت کریمہ) «يأيها الذين آمنوا أطيعوا الله وأطيعوا الرسول وأولي الأمر منكم» ” اے ایمان والو! ا اللہ کی اطاعت کرو ‘ رسول کی اطاعت کرو اور اپنے اولیٰ الامر کی۔ “ سیدنا عبداللہ بن قیس بن عدی رضی اللہ عنہ کے بارے میں نازل ہوئی تھی ‘ نبی کریم صلی اللہ علیہ وسلم نے ان کو ایک مہم میں بھیجا تھا۔ (ابن جریج کہتے ہیں) کہ مجھے یہ روایت یعلیٰ نے بواسطہ سعید بن جبیر سیدنا ابن عباس رضی اللہ عنہ سے بیان کی۔"}],[2625,"علی رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے ایک لشکر بھیجا، اور ایک آدمی ۱؎ کو اس کا امیر بنایا اور لشکر کو حکم دیا کہ اس کی بات سنیں، اور اس کی اطاعت کریں، اس آدمی نے آگ جلائی، اور لوگوں کو حکم دیا کہ وہ اس میں کود پڑیں، لوگوں نے اس میں کودنے سے انکار کیا اور کہا: ہم تو آگ ہی سے بھاگے ہیں اور کچھ لوگوں نے اس میں کود جانا چاہا، نبی اکرم صلی اللہ علیہ وسلم کو یہ خبر پہنچی تو آپ صلی اللہ علیہ وسلم نے فرمایا: \"اگر وہ اس میں داخل ہو گئے ہوتے تو ہمیشہ اسی میں رہتے\"، اور فرمایا: \"اللہ کی معصیت میں کسی کی اطاعت نہیں، اطاعت تو بس نیکی کے کام میں ہے ۲؎\"۔\n§وضاحت\n۱؎ : اس آدمی کا نام عبداللہ بن حذافہ سہمی تھا جن کا تذکرہ پچھلی حدیث میں ہے، بعض لوگ کہتے ہیں : ان کا نام ’’ علقمہ بن مجزر تھا ‘‘۔ ۲؎ : اس سے معلوم ہوا کہ اگر امیر شریعت کے خلاف حکم دے تو اس کی اطاعت نہ کی جائے۔","صحیح",{"u2":"سیدنا علی رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے ایک لشکر روانہ فرمایا اور ان پر ایک شخص (عبداللہ بن قیس رضی اللہ عنہ) کو امیر بنایا اور ان (لشکر والوں) کو حکم دیا کہ امیر کی بات سنیں اور اس کی اطاعت کریں ‘ تو اس نے آگ بھڑکائی اور انہیں حکم دیا کہ اس میں کود جائیں تو ایک قوم نے اس کی یہ بات ماننے سے انکار کر دیا اور کہنے لگے کہ ہم آگ ہی سے تو بھاگے ہیں (مسلمان ہوئے ہیں) اور کچھ دوسرے لوگوں نے آگ میں کود جانے کا ارادہ کیا۔ نبی کریم صلی اللہ علیہ وسلم کو یہ خبر پہنچی تو آپ صلی اللہ علیہ وسلم نے فرمایا ” اگر یہ اس میں داخل ہو جاتے تو پھر ہمیشہ اسی میں رہتے۔ “ اور فرمایا ” ا اللہ کی نافرمانی میں کوئی اطاعت نہیں ‘ اطاعت ہمیشہ نیکی کے کاموں میں ہے۔ “","f2":"جو شخص شریعت کی مخالفت میں حکام وقت کی اطاعت کرے۔وہ اللہ کا نا فرمان ہے۔ اور اللہ کے ہاں اس کا یہ عذر مقبول نہ ہوگا کہ حاکم کی اطاعت میں میں نے ایسے کیا تھا۔"}],[2626,"عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"مسلمان آدمی پر امیر کی بات ماننا اور سننا لازم ہے چاہے وہ پسند کرے یا ناپسند، جب تک کہ اسے کسی نافرمانی کا حکم نہ دیا جائے، لیکن جب اسے نافرمانی کا حکم دیا جائے تو نہ سننا ہے اور نہ ماننا ہے\"۔","صحیح",{"u2":"سیدنا عبداللہ بن عمر رضی اللہ عنہ کی روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” مسلمان پر واجب ہے کہ (تمام احکام) سنے اور مانے، خواہ اسے پسند آئیں یا ناپسند ہوں، جب تک اسے نافرمانی کا حکم نہ دیا جائے، جب معصیت کا حکم دیا جائے تو نہ سننا ہے اور نہ اطاعت ہے۔ “"}],[2627,"عقبہ بن مالک رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے ایک سریہ (دستہ) بھیجا، میں نے ان میں سے ایک شخص کو تلوار دی، جب وہ لوٹ کر آیا تو کہنے لگا: کاش آپ وہ دیکھتے جو رسول اللہ صلی اللہ علیہ وسلم نے ہم کو ملامت کی ہے، آپ نے فرمایا: \"کیا تم سے یہ نہیں ہو سکتا تھا کہ جب میں نے ایک شخص کو بھیجا اور وہ میرا حکم بجا نہیں لایا تو تم اس کے بدلے کسی ایسے شخص کو مقرر کر دیتے جو میرا حکم بجا لاتا\"۔","حسن",{"u2":"سیدنا عقبہ بن مالک رضی اللہ عنہ سے مروی ہے جو کہ بشر بن عاصم کی قوم سے تھے۔ انہوں نے بیان کیا کہ نبی کریم صلی اللہ علیہ وسلم نے ایک مہم بھیجی، تو میں نے ان میں سے ایک آدمی کو تلوار دی جب وہ واپس آیا تو اس نے کہا: کاش کہ آپ (وہ حالات) دیکھتے جن پر رسول اللہ صلی اللہ علیہ وسلم نے ہمیں ملامت کی۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” کیا تم اس بات سے عاجز تھے کہ جب میرے بھیجے ہوئے آدمی نے میرے احکام کی تنفیذ نہیں کی تو تم اس کی جگہ کسی اور کو مقرر کر لیتے جو میرے احکام کی تنفیذ کرتا؟ “","f2":"یہ حدیث حسن درجے کی ہے۔اور اس میں ہے کہ جب کوئی امیر یا حاکم شریعت کی تنفیذ نہ کرہاہو۔یا اس کی مخالفت کرتا ہو۔اور اس کو بدلنا ممکن ہو۔تو اس کو بدل کر دوسرا آدمی مقرر کرلیا جائے۔جو انہیں شریعت کے مطابق لے کر چلے۔"}],[2628,"ابوثعلبہ خشنی رضی اللہ عنہ کہتے ہیں کہ لوگ جب کسی جگہ اترتے، عمرو کی روایت میں ہے: رسول اللہ صلی اللہ علیہ وسلم جب کسی جگہ اترتے تو لوگ گھاٹیوں اور وادیوں میں بکھر جاتے، تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"تمہارا ان گھاٹیوں اور وادیوں میں بکھر جانا شیطان کی جانب سے ہے ۱؎\"، اس کے بعد رسول اللہ صلی اللہ علیہ وسلم کسی جگہ نہیں اترے مگر بعض بعض سے اس طرح سمٹ جاتا کہ یہ کہا جاتا کہ اگر ان پر کوئی کپڑا پھیلا دیا جاتا تو سب کو ڈھانپ لیتا۔\n§وضاحت\n۱؎ : کیونکہ شیطان کا مقصد یہ ہے کہ تم ایک دوسرے سے جدا رہو تا کہ تمہارا دشمن تم پر بہ آسانی حملہ کر سکے۔","صحیح",{"u2":"سیدنا ابوثعلبہ خشنی رضی اللہ عنہ بیان کرتے ہیں کہ مجاہدین جب کسی منزل پر پڑاؤ کرتے تھے، عمرو بن عثمان کے الفاظ ہیں۔ جب رسول اللہ صلی اللہ علیہ وسلم پڑاؤ کرتے تھے تو لوگ وادیوں اور گھاٹیوں میں بکھر جاتے تھے۔ پس رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” تمہارا ان وادیوں اور گھاٹیوں میں بکھر جانا شیطان کی طرف سے ہے۔ “ چنانچہ اس کے بعد جب بھی آپ صلی اللہ علیہ وسلم کسی منزل پر پڑاؤ کرتے تو صحابہ کرام رضی اللہ عنہم م ایک دوسرے کے بہت ہی قریب رہتے حتیٰ کہ کہا جاتا: اگر ان پر ایک ہی کپڑا تان دیا جائے تو سب پر آ جائے۔","f2":"مجاہدین اور مسافروں کو آپس میں قریب قریب رہنے میں ظاہری اور معنوی بہت فائدہے ہیں۔ مگر اتنا بی گھسڑ کر نہیں ہونا چاہیے۔کہ ایک دوسرے کو اذیت ہو۔جیسے کہ درج زیل حدیثں میں وار د ہے۔"}],[2629,"معاذ بن انس جھنی رضی اللہ عنہ کہتے ہیں کہ میں نے اللہ کے نبی کریم صلی اللہ علیہ وسلم کے ساتھ فلاں اور فلاں غزوہ کیا تو لوگوں نے پڑاؤ کی جگہ کو تنگ کر دیا اور راستے مسدود کر دیئے ۱؎ تو اللہ کے نبی کریم صلی اللہ علیہ وسلم نے ایک منادی کو بھیجا جو لوگوں میں اعلان کر دے کہ جس نے پڑاؤ کی جگہیں تنگ کر دیں، یا راستہ مسدود کر دیا تو اس کا جہاد نہیں ہے۔\n§وضاحت\n۱؎ : یعنی بلا ضرورت زیادہ جگہیں گھیر کر بیٹھ گئے اور دوسروں پر راستہ تنگ کر دیا۔","حسن",{"u2":"سیدنا معاذ بن انس جہنی رضی اللہ عنہ روایت کرتے ہیں کہ فلاں فلاں غزوے میں، میں اللہ کے نبی صلی اللہ علیہ وسلم کے ہمرکاب تھا تو لوگوں نے منزلوں پر پڑاؤ کرنے اور خیمے وغیرہ لگانے میں بہت تنگی کا مظاہرہ کیا کہ راستہ بھی نہ چھوڑا۔ تو نبی کریم صلی اللہ علیہ وسلم نے اپنا ایک منادی بھیجا جس نے لوگوں میں اعلان کیا: ” جو شخص خیمہ لگانے میں تنگی کرے یا راستہ کاٹے تو اس کا جہاد نہیں۔ “","f2":"1۔زندگی کے تمام معاملات میں اور اور اس کے رسول صلی اللہ علیہ وسلم کی ساتھ ساتھ عام مسلمانوں ہمجولیوں اور ساتھیوں کے ساتھ حسن سلوک کامعاملہ کرنا واجب ہے۔2۔واضح بنیادی امور سے صرف نظر کرنے کے باعث نیکی کے عظیم کام بھی بے وقعت ہوجاتے ہیں۔بالخصوص ر استے کا حق ادا نہ کرنا بہت بڑا جرم ہے۔"}],[2630,"معاذ بن انس رضی اللہ عنہ کہتے ہیں کہ ہم نے اللہ کے نبی کریم صلی اللہ علیہ وسلم کے ساتھ غزوہ کیا، پھر راوی نے اسی مفہوم کی حدیث بیان کی۔","حسن",{"u2":"سہل بن معاذ اپنے والد (سیدنا معاذ بن انس جہنی رضی اللہ عنہ) سے بیان کرتے ہیں انہوں نے کہا کہ ہم نے اللہ کے نبی صلی اللہ علیہ وسلم کے ساتھ غزوے میں شرکت کی۔ اور مذکورہ بالا حدیث کے ہم معنی بیان کیا۔"}],[2631,"عمر بن عبیداللہ بن معمر کے غلام اور ان کے کاتب (سکریٹری) سالم ابونضر کہتے ہیں کہ عبداللہ بن ابی اوفی رضی اللہ عنہ نے ان کو جب وہ خارجیوں کی طرف سے نکلے لکھا کہ رسول اللہ صلی اللہ علیہ وسلم نے ایک لڑائی میں جس میں دشمن سے سامنا تھا فرمایا: \"لوگو! دشمنوں سے مڈبھیڑ کی تمنا نہ کرو، اور اللہ تعالی سے عافیت طلب کرو، لیکن جب ان سے مڈبھیڑ ہو جائے تو صبر سے کام لو، اور جان لو کہ جنت تلواروں کے سائے تلے ہے\"، پھر فرمایا: \"اے اللہ! کتابوں کے نازل فرمانے والے، بادلوں کو چلانے والے، اور جتھوں کو شکست دینے والے، انہیں شکست دے، اور ہمیں ان پر غلبہ عطا فرما\"۔","صحیح",{"u2":"سیدنا عبداللہ بن ابی اوفی رضی اللہ عنہ نے سالم ابوالنضر کو لکھا، جبکہ وہ حروری لوگوں کی طرف نکلے تھے کہ رسول اللہ صلی اللہ علیہ وسلم نے اپنے ایک غزوے میں، جب وہ دشمن سے ٹکرائے تھے، فرمایا تھا: ” لوگو! دشمن سے ملنے کی تمنا مت کرو، اللہ تعالیٰ سے عافیت مانگو، مگر جب اس سے مڈبھیڑ ہو جائے تو پھر صبر و ثبات سے کام لو اور جان لو کہ جنت تلواروں کے سائے تلے ہے۔ “ پھر (یہ) دعا فرمائی: «اللهم منزل الكتاب ومجري السحاب وهازم الأحزاب اهزمهم وانصرنا عليهم» ” اے اللہ! کتاب کو نازل کرنے والے! بادلوں کو چلانے والے! لشکروں کو پسپا کرنے والے! انہیں پسپا کر دے اور ہمیں ان پر نصرت اور غلبہ عطا فر۔ “","f2":"1۔جنگ کوئی عام کھیل نہیں جب اس سے واسطہ پڑتا ہے۔تو حقیقت کھلتی ہے۔کہ انسان ایمان اور بہادری کے کس معیار پر ہے۔ اس لئے آرزو یہ ہونی چاہیے کہ یہ موقع ہی نہ آئےتو اچھا ہے۔مگر جب دوبدو ہونا لازمی ٹھہرے۔تواللہ پر توکل کرتے ہوئے اپنی قوت وبسالت کا بھر پور اظہار کرنا چاہیے۔شہادت کی تمنا بھی اسی طرح ہے۔کہ موقع آنے پر انسان سردھڑ کی بازی لگانے سے دریغ نہ کرے۔ مگر بے موقع یا بے مقصد جان دے دینا تو کوئی معنی نہیں رکھتا۔2۔ حروری خارجیوں کاایک نام ہے۔ کیونکہ یہ لوگ صفین سے واپس آئے۔توحضرت علی رضی اللہ تعالیٰ عنہ سے الگ ہوکر کوفہ سے باہر مضافات میں حرورا نام کے ایک مقام پرجمع ہوگئے۔اور یہی ان کا پہلا مرکز تھا۔ اس کی طرف نسبت سے یہ لوگ حروری کہلائے۔"}],[2632,"انس بن مالک رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم جب غزوہ کرتے تو فرماتے: «اللهم أنت عضدي ونصيري بك أحول وبك أصول وبك أقاتل» \"اے اللہ! تو ہی میرا بازو اور مددگار ہے، تیری ہی مدد سے میں چلتا پھرتا ہوں، اور تیری ہی مدد سے میں حملہ کرتا ہوں، اور تیری ہی مدد سے میں قتال کرتا ہوں\"۔","صحیح",{"u2":"سیدنا انس بن مالک رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم جب غزوے کے لیے تشریف لے جاتے تو یوں دعا فرماتے «اللهم أنت عضدي ونصيري بك أحول وبك أصول وبك أقاتل» ” اے اللہ! تو میرا بازو اور میرا مددگار ہے، تیری ہی مدد سے میں چلتا پھرتا اور حملہ کرتا ہوں اور لڑائی کرتا ہوں۔ “"}],[2633,"ابن عون کہتے ہیں کہ میں نے نافع کے پاس لڑائی کے وقت کفار و مشرکین کو اسلام کی دعوت دینے کے بارے میں پوچھنے کے لیے خط لکھا، تو انہوں نے مجھے لکھا: یہ شروع اسلام میں تھا (اس کے بعد) اللہ کے نبی کریم صلی اللہ علیہ وسلم نے قبیلہ بنو مصطلق پر حملہ کیا، وہ غفلت میں تھے، اور ان کے چوپائے پانی پی رہے تھے، آپ صلی اللہ علیہ وسلم نے ان میں سے جو لڑنے والے تھے انہیں قتل کیا، اور باقی کو گرفتار کر لیا ۱؎، اور جویریہ بنت الحارث ۲؎ کو آپ صلی اللہ علیہ وسلم نے اسی دن پایا، یہ بات مجھ سے عبداللہ بن عمر رضی اللہ عنہما نے بیان کی جو خود اس لشکر میں تھے۔ ابوداؤد کہتے ہیں: یہ ایک عمدہ حدیث ہے، اسے ابن عون نے نافع سے روایت کیا ہے اور اس میں ان کا کوئی شریک نہیں۔\n§وضاحت\n۱؎ : معلوم ہوا کہ جن کافروں اور مشرکوں تک اسلام کی دعوت ان پر حملہ سے پہلے پہنچ چکی ہو تو انہیں اسلام کی دعوت پیش کرنے سے پہلے ان سے قتال جائز ہے۔ ۲؎ : یہ نبی اکرم صلی اللہ علیہ وسلم کی ازواج مطہرات میں سے ہیں، ان کا انتقال ۵۰ ہجری میں ہوا۔","صحیح",{"u2":"ابن عون رضی اللہ عنہ کہتے ہیں کہ میں نے جناب نافع کو لکھ بھیجا اور ان سے یہ مسئلہ دریافت کیا کہ قتال کے موقع پر مشرکین کو دعوت دینا کیا حکم رکھتا ہے؟ تو انہوں نے مجھے لکھ بھیجا: بیشک یہ حکم ابتدائے اسلام میں تھا۔ (بعد ازاں) نبی کریم صلی اللہ علیہ وسلم نے قبیلہ بنو مصطلق پر حملہ کیا جبکہ وہ غافل تھے اور ان کے جانور پانی پی رہے تھے تو آپ نے ان کے لڑنے والوں کو قتل کیا اور باقیوں کو قید کر لیا۔ اسی موقع پر جویریہ بنت حارث آپ کے ہاتھ لگی تھیں۔ (بعد میں حرم نبوی میں داخل کی گئیں) نافع کہتے ہیں کہ مجھے یہ حدیث سیدنا عبداللہ بن عمر رضی اللہ عنہ نے بیان کی اور وہ اس لشکر میں شریک تھے۔ امام ابوداؤد رضی اللہ عنہ فرماتے ہیں، یہ حدیث عمدہ ہے۔ اسے ابن عون نے نافع سے بیان کیا ہے۔ ابن عون کا اس میں اور کوئی شریک نہیں۔","f2":"1۔جن لوگوں کو اسلام اور مسلمانوں کی دعوت پہنچ چکی ہو۔بوقت قتال ان کو دعوت دینا کوئی ضروری نہیں ہے۔اور جنہیں نہ پہنچی ہو تو انہیں دی جانی چاہیے۔2۔حضرت جویریہ رضی اللہ تعالیٰ عنہا کو رسول اللہ صلی اللہ علیہ وسلم نے آذاد کرکے اپنے حرم میں شامل کرلیا تھا۔"}],[2634,"انس رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم فجر کے وقت حملہ کرتے تھے اور غور سے (اذان) سننے کی کوشش کرتے تھے جب اذان سن لیتے تو رک جاتے، ورنہ حملہ کر دیتے ۱؎۔\n§وضاحت\n۱؎ : کیونکہ جب اذان کی آواز آتی تو معلوم ہو جاتا کہ یہ لوگ مسلمان ہیں، اور اگر اذان کی آواز نہیں آتی تو ان کا کافر ہو جانا یقینی ہو جاتا اس لئے آپ صلی اللہ علیہ وسلم ان پر حملہ کر دیتے، اور چونکہ ان تک اسلام کی دعوت پہنچ چکی تھی اس لئے بغیر دعوت دیئے حملہ کر دیتے تھے۔","صحیح",{"u2":"سیدنا انس رضی اللہ عنہ کا بیان ہے کہ نبی کریم صلی اللہ علیہ وسلم نماز فجر کے وقت شب خون مارا کرتے تھے۔ اور (اس سے پہلے) کان لگا کر سنتے، اگر اذان کی آواز سن لیتے تو باز رہتے ورنہ حملہ کر دیتے۔","f2":"اذان کاسنائی دینا اس بات کی علامت ہے۔کہ وہاں کے باشندے مسلمان ہیں۔اسلئے ان پر حملہ نہیں کیا جاتا تھا۔ اذان کی آواز کا نہ آنا اس بات کی علامت ہے کہ وہاں کے باشندے مسلمان نہیں ہیں۔لہذا ان پرحملہ کردیا جاتا تھا۔"}],[2635,"عصام مزنی رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے ہم کو ایک سریہ میں بھیجا اور فرمایا: \"جب تم کوئی مسجد دیکھنا، یا کسی مؤذن کو اذان دیتے ہوئے سننا تو کسی کو قتل نہ کرنا\"۔","ضعیف",{"u2":"سیدنا عصام مزنی رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے ہم کو ایک جہادی مہم میں روانہ کیا اور فرمایا ” جب تم کوئی مسجد دیکھو یا کسی مؤذن کو سنو تو پھر کسی کو قتل نہ کرنا۔ “"}],[2636,"جابر رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"لڑائی دھوکہ و فریب کا نام ہے ۱؎\"۔\n§وضاحت\n۱؎ : یعنی جنگ کے دوران کفار کو جہاں تک ممکن ہو دھوکہ دینا جائز ہے بشرطیکہ یہ دھوکہ ان سے کئے گئے کسی عہد و پیمان کے توڑنے کا سبب نہ بنے، تین مقامات جہاں کذب کا سہارا لیا جاسکتا ہے ان میں سے ایک جنگ کا مقام بھی ہے جیسا کہ صحیح حدیث سے ثابت ہے۔","صحیح",{"u2":"سیدنا جابر رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” جنگ چال کا نام ہے۔ “"}],[2637,"کعب بن مالک رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم جب کسی غزوہ کا ارادہ کرتے تو جس سمت جانا ہوتا اس کے علاوہ کا توریہ ۱؎ کرتے اور فرماتے: \"جنگ دھوکہ کا نام ہے\"۔ ابوداؤد کہتے ہیں: اسے معمر کے سوا کسی اور نے اس سند سے نہیں روایت کیا ہے، وہ اس سے آپ صلی اللہ علیہ وسلم کے قول «الحرب خدعة» کو مراد لے رہے ہیں، یہ لفظ صرف عمرو بن دینار کے واسطے سے جابر رضی اللہ عنہ سے مروی ہے یا معمر کے واسطے سے ہمام بن منبہ سے مروی ہے جسے وہ ابوہریرہ رضی اللہ عنہ سے روایت کرتے ہیں۔\n§وضاحت\n۱؎ : یعنی مشرق کی طرف نکلنا ہوتا تو مغرب کا اشارہ کرتے، اور شمال کی طرف نکلنا ہوتا تو جنوب کا اشارہ کرتے، اصل بات چھپا کر دوسری بات ظاہر کرنا، یہی توریہ ہے۔","صحیح",{"u2":"سیدنا کعب بن مالک رضی اللہ عنہ سے روایت ہے کہ نبی کریم صلی اللہ علیہ وسلم جب کسی طرف غزوے کا ارادہ فرماتے تو کسی اور جانب کا اشارہ کرتے۔ اور فرمایا کرتے ” جنگ چال کا نام ہے۔ “ امام ابوداؤد رضی اللہ عنہ فرماتے ہیں کہ «الحرب خدعة» کا لفظ اس روایت میں صرف معمر ہی نے اس سند سے بیان کیا ہے۔ جو درحقیقت «عمرو بن دينار، عن جابر» کی سند میں آیا ہے (جو اوپر ذکر ہوئی ہے) اور اسی طرح «معمر، عن همام بن منبه، عن أبي هريرة» کی سند میں بھی وارد ہے۔","f2":"جنگ میں صرف تیر وتفنگ ہی کام نہیں آتا۔بلکہ حکمت تدبیر اور چال سبھی امور کام دیتے ہیں۔تاہم یہ ضرور ہے کہ دشمن سے قبل از جنگ یا بعد از جنگ جو عہد معاہدہ ہوجائے اس میں دھوکا کرنا حرام ہے۔"}],[2638,"سلمہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے ہم پر ابوبکر صدیق رضی اللہ عنہ کو امیر بنا کر بھیجا، ہم نے مشرکین کے کچھ لوگوں سے جہاد کیا تو ہم نے ان پر شب خون مارا، ہم انہیں قتل کر رہے تھے، اور اس رات ہمارا شعار (کوڈ) «أمت أمت» ۱؎ تھا، اس رات میں نے اپنے ہاتھ سے سات گھروں کے مشرکوں کو قتل کیا ۲؎۔\n§وضاحت\n۱؎ : یعنی اے مدد کرنے والے دشمن کو فنا کر۔ ۲؎ : اس حدیث سے کافروں پر شب خون مارنے کا جواز ثابت ہوا اگر اسلام کی دعوت ان تک پہنچ چکی ہو۔","حسن",{"u2":"جناب ایاس بن سلمہ اپنے والد (سیدنا سلمہ بن اکوع رضی اللہ عنہ) سے روایت کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے سیدنا ابوبکر صدیق رضی اللہ عنہ کو ہمارا امیر بنایا، پھر ہم مشرکین سے جہاد کے لیے نکلے۔ ہم نے ان پر شب خون مارا۔ اس رات ہمارا شعار تھا «أمت أمت» سلمہ کہتے ہیں کہ اس رات میں نے اپنے ہاتھ سے سات گھروں کے مشرکین کو قتل کیا تھا۔","f2":"حسب ضرورت ومصلحت شب خون مارنے میں کوئی عیب نہیں۔اور نہ اسے معروف معنی میں دھوکا یا بزدلی سے تعبیر کیا جاسکتا ہے۔"}],[2639,"جابر بن عبداللہ رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم سفر میں ساقہ (لشکر کے پچھلے دستہ) کے ساتھ رہا کرتے تھے، آپ صلی اللہ علیہ وسلم کمزوروں کو ساتھ لیتے، انہیں اپنے پیچھے سواری پر بٹھا لیتے اور ان کے لیے دعا کرتے۔","صحیح",{"u2":"سیدنا جابر بن عبداللہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم دوران سفر میں پیچھے رہا کرتے تھے، ضعیفوں کی سواری ہانک لے جاتے اور انہیں اپنے پیچھے بٹھا لیتے اور ان کے لیے دعائیں کرتے۔","f2":"لشکر کا آخری اور پچھلا جتھہ جس میں بالعموم ضعیف بیمار اور مجروح (زخمی) لوگ ہوتے ہیں۔ ساقہ کہلاتا ہے۔"}],[2640,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"مجھے حکم دیا گیا ہے کہ میں لوگوں سے اس وقت تک قتال کروں جب تک کہ وہ «لا إله إلا الله» کی گواہی نہ دینے لگ جائیں، پھر جب وہ اس کلمہ کو کہہ دیں تو ان کے خون اور مال مجھ سے محفوظ ہو گئے، سوائے اس کے حق کے (یعنی اگر وہ کسی کا مال لیں یا خون کریں تو اس کے بدلہ میں ان کا مال لیا جائے گا اور ان کا خون کیا جائے گا) اور ان کا حساب اللہ پر ہو گا\"۔","صحیح متواتر",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” مجھے حکم دیا گیا ہے کہ مشرکوں سے قتال کروں حتیٰ کہ وہ «لا إله إلا الله» کا اقرار کر لیں، جب وہ اس کا اقرار کر لیں، تو انہوں نے مجھ سے اپنے خون اور مال محفوظ کر لیے، سوائے اس کے کہ اس اقرار (اسلام) کا کوئی حق ہو اور (دلی معاملات میں) ان کا حساب اللہ پر ہے۔“","f2":"1۔ اسلام بنی نوع انسان کے لئے امن سلامتی کا دین ہے۔اس کی دعوت اس کے علاوہ اور کچھ نہیں کے اس دنیا میں کائنات کے خالق ومالک کے سوا اور کسی کی عبادت نہ کرو۔اور نہ کرنے دی جائے۔اسی اصل بنیاد پرمنکرین سے حسب احوال وظروف قتال کا حکم ہے۔جس کی معلوم ومعروف شرطیں اور آداب ہیں جواس کتاب الجہاد اور کتب فقہ اسلامی میں محفوظ ہیں۔2۔اگر کوئی قوم اسلام قبول کرنے پر راضی نہ ہو تو اس کو اہل اسلام کی اطاعت قبول کرنی ہوگی۔اور جزیہ دینا ہوگا۔3۔اسلام میں اقرار توحید اور اقرار رسالت محمد رسول اللہ صلی اللہ علیہ وسلم کو مستلزم ہے۔ اس کے بغیر توحید کا اقرار قابل قبول نہیں جیسے کہ درج زیل حدیث میں آرہا ہے۔"}],[2641,"انس رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"مجھے حکم دیا گیا ہے کہ میں لوگوں سے اس وقت تک قتال کروں جب تک کہ وہ «لا إله إلا الله وأن محمدا عبده ورسوله» \"نہیں ہے کوئی معبود برحق سوائے اللہ کے اور محمد صلی اللہ علیہ وسلم اللہ کے بندے اور اس کے رسول ہیں\" کی گواہی دینے، ہمارے قبلہ کا استقبال کرنے، ہمارا ذبیحہ کھانے، اور ہماری نماز کی طرح نماز پڑھنے نہ لگ جائیں، تو جب وہ ایسا کرنے لگیں تو ان کے خون اور مال ہمارے اوپر حرام ہو گئے سوائے اس کے حق کے ساتھ اور ان کے وہ سارے حقوق ہوں گے جو مسلمانوں کے ہیں اور ان پر وہ سارے حقوق عائد ہوں گے جو مسلمانوں پر ہوتے ہیں\"۔","صحیح",{"u2":"سیدنا انس رضی اللہ عنہ سے روایت ہے رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” مجھے یہ حکم دیا گیا ہے کہ لوگوں سے قتال کروں حتیٰ کہ وہ گواہی دیں کہ اللہ کے سوا اور کوئی معبود نہیں اور محمد (صلی اللہ علیہ وسلم) اس کے بندے اور رسول ہیں، اور وہ ہمارے قبلے کی طرف رخ کریں، ہمارا ذبیحہ کھائیں اور ہماری طرح نماز پڑھیں، لوگ جب یہ سب کچھ کریں تو ان کے خون اور مال ہم پر حرام ہوں گے الا یہ کہ اس (کلمہ توحید و اسلام) کا کوئی حق ہو۔ ان کے حقوق وہی ہوں گے جو مسلمانوں کے ہیں اور ان کے فرائض بھی وہی ہوں گے جو مسلمانوں کے ہیں۔“","f2":"حق اسلام کا معنی یہ ہے کہ اگر کوئی مسلمان کسی دوسرے کو ناحق قتل کردے تو قصاص میں اسے قتل کیا جائے گا۔شادی شدہ ہوتے ہوئے بدکاری کرلے تو رجم ہوگا۔اور کسی کامال لوٹ لے تو بدلے میں مال دے گا وغیرہ۔"}],[2642,"انس بن مالک رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"مجھے حکم دیا گیا ہے کہ میں مشرکوں سے قتال کروں\"، پھر آگے اسی مفہوم کی حدیث ہے۔","صحیح",{"u2":"سیدنا انس بن مالک رضی اللہ عنہ سے روایت ہے رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” مجھے مشرکین سے قتال کا حکم دیا گیا ہے۔ “ اور مذکورہ بالا حدیث کے ہم معنی روایت کیا۔","f2":"مذکورہ بالا احادیث میں الناس (لوگوں) سے مراد مشرک لوگ ہیں۔یامفسد یعنی جو اللہ تعالیٰ کی نازل کردہ شریعت کے قائل وفاعل نہ ہوں۔2۔اہل اسلام اور اصحاب امن سے قتال کے کوئی معنی نہیں اسے کسی طور جہاد کا نام نہیں دیا جاسکتا۔"}],[2643,"اسامہ بن زید رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے ہمیں حرقات ۱؎ کی طرف ایک سریہ میں بھیجا، تو ان کافروں کو ہمارے آنے کا علم ہو گیا، چنانچہ وہ سب بھاگ کھڑے ہوئے، لیکن ہم نے ایک آدمی کو پکڑ لیا، جب ہم نے اسے گھیرے میں لے لیا تو«لا إله إلا الله» کہنے لگا (اس کے باوجود) ہم نے اسے مارا یہاں تک کہ اسے قتل کر دیا، پھر میں نے نبی اکرم صلی اللہ علیہ وسلم سے اس کا ذکر کیا تو آپ صلی اللہ علیہ وسلم نے فرمایا: \"قیامت کے دن «لا إله إلا الله» کے سامنے تیری مدد کون کرے گا؟\" میں نے کہا: اللہ کے رسول! اس نے یہ بات تلوار کے ڈر سے کہی تھی، آپ صلی اللہ علیہ وسلم نے فرمایا: \"تم نے اس کا دل پھاڑ کر دیکھ کیوں نہیں لیا کہ ۲؎ اس نے کلمہ تلوار کے ڈر سے پڑھا ہے یا (تلوار کے ڈر سے) نہیں (بلکہ اسلام کے لیے) ؟ قیامت کے دن «لا إله إلا الله»کے سامنے تیری مدد کون کرے گا؟\" آپ صلی اللہ علیہ وسلم برابر یہی بات فرماتے رہے، یہاں تک کہ میں نے سوچا کاش کہ میں آج ہی اسلام لایا ہوتا۔\n§وضاحت\n۱؎ : جہینہ کے چند قبائل کا نام ہے۔ ۲؎ : زبان سے کلمہ شہادت پڑھنے والے کا شمار مسلمانوں میں ہو گا، اس کے ساتھ دنیا میں وہی سلوک ہو گا جو کسی مسلم مومن کے ساتھ ہوتا ہے اس کے کلمہ پڑھنے کا سبب خواہ کچھ بھی ہو، کیونکہ کلمہ کا تعلق ظاہر سے ہے نہ کہ باطن سے اور باطن کا علم صرف اللہ کو ہے نبی اکرم صلی اللہ علیہ وسلم کے فرمان «أفلا شققت عن قلبه» کا یہی مفہوم ہے۔","صحیح",{"u2":"سیدنا اسامہ بن زید رضی اللہ عنہ کا بیان ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے ہم لوگوں کو ایک مہم میں حرقات (قبیلے) کی طرف روانہ فرمایا، انہوں نے ہماری خبر سن لی اور نکل بھاگے، ہم نے ایک آدمی کو جا لیا جب ہم نے اس کو گھیر لیا تو اس نے «لا إله إلا الله» کہہ دیا۔ ہم نے اس کو مارا حتیٰ کہ قتل کر دیا۔ میں نے یہ واقعہ نبی کریم صلی اللہ علیہ وسلم کے سامنے بیان کیا تو آپ صلی اللہ علیہ وسلم نے فرمایا ” قیامت کے دن «لا إله إلا الله» کے مقابلے میں تیرے لیے کون ہو گا؟ “ میں نے عرض کیا: اے اللہ کے رسول! اس نے یہ ہتھیار کے خوف سے کہا تھا۔ آپ صلی اللہ علیہ وسلم نے فرمایا ” بھلا تو نے اس کا دل کیوں نہ چیر لیا حتیٰ کہ تجھے معلوم ہو جاتا کہ اس نے اس وجہ سے کہا تھا یا کسی اور وجہ سے؟ قیامت کے دن تیرے لیے «لا إله إلا الله» کے مقابلے میں کون ہو گا؟ “ آپ صلی اللہ علیہ وسلم یہ کلمہ دہراتے رہے حتیٰ کہ میرا دل چاہا، کاش کہ میں آج ہی اسلام لایا ہوتا۔ (مجھ سے یہ گناہ عظیم سرزد نہ ہوا ہوتا۔)","f2":"1۔کافر جب بھی توحید ورسالت کا اقرار کرلے مقبول ہے۔اور اس کی جان ومال کا محفوظ ہونا واجب ہے۔3۔احکام شریعت کا اعتبارونفاذ ظاہر پر ہوتاہے۔دلوں کا معاملہ اللہ کے سپرد ہے۔3۔حضرت اسامہ رضی اللہ تعالیٰ عنہ کا یہ عمل ایک اجتہادی خطا تھی۔ اس لئے ان پرکوئی دیت لازم نہ کی گئی4۔کلمہ گو کا قتل کبیرہ گناہ ہے۔5۔شہادت توحید اللہ کے ہاںباعث نجات ہے۔"}],[2644,"مقداد بن اسود رضی اللہ عنہ کہتے ہیں کہ انہوں نے عرض کیا: اللہ کے رسول! مجھے بتائیے اگر کافروں میں کسی شخص سے میری مڈبھیڑ ہو جائے اور وہ مجھ سے قتال کرے اور میرا ایک ہاتھ تلوار سے کاٹ دے اس کے بعد درخت کی آڑ میں چھپ جائے اور کہے: میں نے اللہ کے لیے اسلام قبول کر لیا، تو کیا میں اسے اس کلمہ کے کہنے کے بعد قتل کروں؟ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"نہیں تم اسے قتل نہ کرو\"، میں نے کہا: اللہ کے رسول! اس نے میرا ہاتھ کاٹ دیا ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اسے قتل نہ کرو، کیونکہ اگر تم نے اسے قتل کر دیا تو قتل کرنے سے پہلے تمہارا جو مقام تھا وہ اس مقام میں آ جائے گا اور تم اس مقام میں پہنچ جاؤ گے جو اس کلمہ کے کہنے سے پہلے اس کا تھا\" ۱؎۔\n§وضاحت\n۱؎ : یعنی وہ معصوم الدم قرار پائے گا اور تمہیں بطور قصاص قتل کیا جائے گا۔","صحیح",{"u2":"سیدنا مقداد بن اسود رضی اللہ عنہ کہتے ہیں کہ میں نے کہا: اے اللہ کے رسول! میں اگر کسی کافر سے ٹکراؤں، وہ مجھ سے قتال کرے اور تلوار سے میرا ایک ہاتھ کاٹ ڈالے، پھر (میرے وار کرنے پر) کسی درخت کی اوٹ لے لے اور کہے: میں نے اللہ کے لیے اسلام قبول کیا۔ تو اے اللہ کے رسول! کیا میں اسے قتل کروں (یا نہ) جبکہ اس نے «لا إله إلا الله» کہہ دیا ہو؟ آپ صلی اللہ علیہ وسلم نے فرمایا ” اسے قتل مت کرو۔ “ میں نے عرض کیا: اے اللہ کے رسول! اس نے میرا ایک ہاتھ کاٹ ڈالا ہے۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” اسے قتل مت کرو، اگر تو نے اس کو قتل کر دیا تو وہ تیرے مقام پر ہو گا جہاں کہ تو اس کو قتل کرنے سے پہلے تھا۔ (معصوم الدم اور اس کا قتل حرام تھا۔) اور تو اس کی جگہ پر ہو گا جہاں کہ وہ یہ کلمہ کہنے سے پہلے تھا۔ “ (حلال الدم اور اس کا قتل کرنا حلال تھا۔)","f2":"1۔کوئی بھی زمہ داری لینے سے پہلے اس کے فرائض واجبات اور حقوق و آداب کا علم حاصل کرنا ضروری ہے۔جیسے کہ حضرت مقدار رضی اللہ تعالیٰ عنہ نے تفصیلات حاصل کیں۔2۔ہرمجاہد اسلام اورہر داعی کو اپنے میدان عمل میں انتہائی دانشمندی عم صبر اور اطاعت شریعت کا ثبوت دینا لازمی ہے۔3۔بلا سبب شرعی کسی مسلمان کا قتل کرنا جرم عظیم ہے۔ اور اس کی سزا جہنم ہے۔"}],[2645,"جریر بن عبداللہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے قبیلہ خثعم کی جانب ایک سریہ بھیجا تو ان کے کچھ لوگوں نے سجدہ کر کے بچنا چاہا پھر بھی لوگوں نے انہیں قتل کرنے میں جلد بازی کی، نبی اکرم صلی اللہ علیہ وسلم کو اس کی خبر پہنچی تو آپ نے ان کے لیے نصف دیت ۱؎ کا حکم دیا اور فرمایا: \"میں ہر اس مسلمان سے بری ہوں جو مشرکوں کے درمیان رہتا ہے\"، لوگوں نے پوچھا: اللہ کے رسول! کیوں؟ آپ صلی اللہ علیہ وسلم نے فرمایا: \"دونوں کی (یعنی اسلام اور کفر کی) آگ ایک ساتھ نہیں رہ سکتی\" ۲؎۔ ابوداؤد کہتے ہیں: اسے ہشیم، معمر، خالد واسطی اور ایک جماعت نے روایت کیا ہے اور ان لوگوں نے جریر کا ذکر نہیں کیا ہے ۳؎۔\n§وضاحت\n۱؎ : نصف دیت کا حکم دیا اور باقی نصف کفار کے ساتھ رہنے سے ساقط ہو گئی کیونکہ کافروں کے ساتھ رہ کر اپنی ذات کو انہوں نے جو فائدہ پہنچایا درحقیقت یہ ایک جرم تھا اور اسی جرم کی پاداش میں نصف دیت ساقط ہو گئی۔ ۲؎ : اس جملہ کی توجیہ میں تین اقوال وارد ہیں: ایک مفہوم یہ ہے کہ دونوں کا حکم یکساں نہیں ہو سکتا، دوسرا یہ کہ اللہ تعالی نے دارالاسلام کو دارالکفر سے علیحدہ کر دیا ہے لہٰذا مسلمانوں کے لئے یہ درست نہیں ہے کہ وہ کافروں کے ملک میں ان کے ساتھ رہے، تیسرا یہ کہ مسلمان مشرک کی خصوصیات اور علامتوں کو نہ اپنائے اور نہ ہی چال ڈھال اور شکل وصورت میں ان کے ساتھ تشبہ اختیار کرے۔ ۳؎ : یعنی : ان لوگوں نے اس حدیث کو«عن قیس عن النبی صلی اللہ علیہ وسلم» مرسلاً روایت کیا ہے، بخاری نے بھی مرسل ہی کو صحیح قرار دیا ہے مگر موصول کی متابعات صحیحہ موجود ہیں جیسا کہ البانی نے (ارواء الغلیل، حدیث نمبر: ۱۲۰۷ میں) ذکر کیا ہے۔","صحیح",{"u2":"سیدنا جریر بن عبداللہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے قبیلہ خشعم کی طرف ایک مہم روانہ فرمائی تو ان میں سے کچھ لوگوں نے سجدہ کر کے پناہ حاصل کرنی چاہی لیکن (مجاہدین نے ان کو) جلدی جلدی قتل کر ڈالا۔ نبی کریم صلی اللہ علیہ وسلم کو یہ خبر پہنچی تو آپ صلی اللہ علیہ وسلم نے ان کو آدھی دیت دینے کا حکم دیا۔ اور فرمایا ” میں ہر اس مسلمان سے بری ہوں جو مشرکین کے اندر مقیم ہو۔ “ انہوں نے پوچھا: اے اللہ کے رسول! کیوں؟ آپ صلی اللہ علیہ وسلم نے فرمایا ” یعنی دونوں کو ایک دوسرے کی آگ دکھائی نہ دے (آبادی اس قدر دور دور ہونی چاہیئے۔) امام ابوداؤد رضی اللہ عنہ فرماتے ہیں کہ اس حدیث کو ہشیم، معمر، خالد واسطی اور کئی لوگوں نے روایت کیا ہے اور انہوں نے جریر رضی اللہ عنہ کا واسطہ ذکر نہیں کیا۔","f2":"1۔یہ روایت ضعیف ہے مگر بعض آئمہ کے نزدیک صحیح ہے۔البتہ اس میں نصف دیت والا ٹکڑا صیح نہیں ہے۔2۔حدیث کا آخری جملہ (لاترايا ناراهما) کا لفظی ترجمہ یہ ہوسکتا ہے۔کہ ان دونوں یعنی مسلمانوں اور کافروں کی آگیں بھی نظر نہیں آنی چاہیں۔ علامہ خطابی نے اس کی توضیح میں تین قول لکھے ہیں۔(الف)مسلمان اور کافر برابر نہیں۔اور ان کا حکم ایک جیسا نہیں(ب)مسلمانوں کو کافروں سے اس حد تک دور رہنا چاہیے کہ آگ جلائی جائے تو نظر نہ آئے۔اس معنی سے استدلال کیا جاتا ہے کہ دارالحرب میں کسی اشد ضرورت کے پیش نظر چار د ن سے زیادہ اقامت نہ کی جائے (ج)یعنی اہل لغت یہ ترجمہ کرتے ہیں۔ کہ ان دونوں (مسلمان اور مشرک) میں کوئی مشابہت ومماثلت نہیں ہونی چاہیے۔ یہ معنی عرب کے اس اسلوب کلام سے ماخوذ ہے جس میں وہ بولتے (ما نار بعيرك) تیرے اونٹ کی علامت اوراس کا حال کیسا ہے؟ (نارھا تجارھا) اس کی اونچی کوہان پر دیا گیا داغ اس کے اصیل ہونے کی علامت ہے۔ 2۔جب کوئی شخص کسی طرح اپنے مسلمان ہونے کا اظہار کردے تو اس کا خون اور مال محفوظ ہوجاتا ہے۔4۔کسی مسلمان کے لئے حلال نہیں کے کفار کے ملک میں بالخصوص دارالحرب میں مستقل سکونت اختیار کرے۔5۔واجب ہے کہ مسلمان اپنے عقیدے اور عمل کے علاوہ عادات وثقافت میں بھی کفار سے نمایاں رہے اور ان کی مشابہت ومماثلت اخیتار نہ کرے۔"}],[2646,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ آیت کریمہ «إن يكن منكم عشرون صابرون يغلبوا مائتين» \"اگر تم میں سے بیس بھی صبر کرنے والے ہوں گے تو دو سو پر غالب رہیں گے\" (سورۃ الانفال: ۶۵) نازل ہوئی تو اللہ تعالی نے مسلمانوں پر یہ فرض کر دیا کہ ان میں کا ایک آدمی دس کافروں کے مقابلہ میں نہ بھاگے، تو یہ چیز ان پر شاق گزری، پھر تخفیف ہوئی اور اللہ نے فرمایا: «الآن خفف الله عنكم» \"اب اللہ نے تمہارا بوجھ ہلکا کر دیا ہے وہ خوب جانتا ہے کہ تم میں کمزوری ہے تو اگر تم میں سے ایک سو صبر کرنے والے ہوں گے تو وہ دو سو پر غالب رہیں گے\" (سورۃ الانفال: ۶۶) ۔ ابوتوبہ نے پوری آیت «يغلبوا مائتين» تک پڑھ کر سنایا اور کہا: جب اللہ نے ان سے تعداد میں تخفیف کر دی تو اس تخفیف کی مقدار میں صبر میں بھی کمی کر دی۔","صحیح",{"u2":"سیدنا ابن عباس رضی اللہ عنہ سے روایت ہے کہ جب یہ آیت کریمہ نازل ہوئی «إن يكن منكم عشرون صابرون يغلبوا مائتين» ” اگر تم میں بیس ہوئے صبر کرنے والے تو وہ دو سو پر غالب آ جائیں گے۔ “ تو مسلمانوں کو یہ امر بڑا بھاری محسوس ہوا کہ اللہ نے فرض کر دیا ہے کہ ایک آدمی دس کے مقابلے سے نہ بھاگے۔ پھر (یہ) تخفیف نازل ہوئی «الآن خفف الله عنكم» ” اب اللہ نے تم سے تخفیف کر دی اور اس نے جان لیا ہے کہ تم میں کمزوری ہے، سو اگر تم میں سو افراد ہوئے صابر و ثابت قدم تو وہ دو سو پر غالب ہوں گے۔ “ ابوتوبہ ربیع (راوی حدیث) نے یہ آیت کریمہ «يغلبوا مائتين» تک پڑھی۔ کہا کہ جب اللہ تعالیٰ نے گنتی میں تخفیف فر دی تو اس اعتبار سے صبر میں بھی کمی کر دی۔","f2":"اگر دشمن کی تعداد مسلمانوں سے دگنی ہو تو گھبرانا نہیں چاہیے بلکہ جم کر مقابلہ کرنا چاہیے۔اللہ تعالیٰ کی خاص مد د شامل حال ہوگی۔"}],[2647,"عبداللہ بن عمر رضی اللہ عنہما کا بیان ہے کہ وہ رسول اللہ صلی اللہ علیہ وسلم کے سرایا میں سے کسی سریہ میں تھے، وہ کہتے ہیں کہ لوگ تیزی کے ساتھ بھاگے، بھاگنے والوں میں میں بھی تھا، جب ہم رکے تو ہم نے آپس میں مشورہ کیا کہ اب کیا کریں؟ ہم کافروں کے مقابلہ سے بھاگ کھڑے ہوئے اور اللہ کے غضب کے مستحق قرار پائے، پھر ہم نے کہا: چلو ہم مدینہ چلیں اور وہاں ٹھہرے رہیں، (پھر جب دوسری بار جہاد ہو) تو چل نکلیں اور ہم کو کوئی دیکھنے نہ پائے، خیر ہم مدینہ گئے، وہاں ہم نے اپنے دل میں کہا: کاش! ہم اپنے آپ کو رسول اللہ صلی اللہ علیہ وسلم کے سامنے پیش کرتے تو زیادہ بہتر ہوتا، اگر ہماری توبہ قبول ہوئی تو ہم ٹھہرے رہیں گے ورنہ ہم چلے جائیں گے، ہم رسول اللہ صلی اللہ علیہ وسلم کے انتظار میں فجر سے پہلے بیٹھ گئے، جب آپ صلی اللہ علیہ وسلم نکلے تو ہم کھڑے ہوئے اور آپ کے پاس جا کر ہم نے عرض کیا: اللہ کے رسول! ہم بھاگے ہوئے لوگ ہیں، آپ ہماری طرف متوجہ ہوئے اور فرمایا: \"نہیں، بلکہ تم لوگ «عکارون» ہو (یعنی دوبارہ لڑائی میں واپس لوٹنے والے ہو)\"۔ عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں: (خوش ہو کر) ہم آپ کے نزدیک گئے اور آپ کا ہاتھ چوما تو آپ صلی اللہ علیہ وسلم نے فرمایا: \"میں مسلمانوں کی پناہ گاہ ہوں\"، (یعنی ان کا ملجا و ماوی ہوں میرے سوا وہ اور کہاں جائیں گے؟) ۔","ضعیف",{"u2":"سیدنا عبداللہ بن عمر رضی اللہ عنہ سے روایت ہے کہ وہ رسول اللہ صلی اللہ علیہ وسلم کی جانب سے بھیجی گئی ایک مہم میں شریک تھے۔ تو لوگ (مجاہدین) کے مقابلے سے بھاگ چلے اور میں بھی ان (بھاگنے والوں) میں شریک تھا۔ جب ہم علیحدہ ہوئے، تو ہم نے کہا: کیسے کریں، ہم تو جہاد سے بھاگ آئے ہیں اور (اللہ کا) غضب لے کر لوٹے ہیں؟ ہم نے کہا: ہم مدینے چلتے ہیں، وہاں ٹھہریں گے اور (کسی دوسری مہم میں) شریک ہو جائیں گے اور ہمیں کوئی نہیں دیکھے گا، سو جب ہم مدینے آئے تو ہم نے سوچا کیوں نہ اپنے آپ کو رسول اللہ صلی اللہ علیہ وسلم کے حضور پیش کر دیں، اگر توبہ قبول ہوئی تو (بہتر) ٹھہرے رہیں گے، ورنہ جہاد میں چلے جائیں گے۔ چنانچہ نماز فجر سے پہلے ہم رسول اللہ صلی اللہ علیہ وسلم کے انتظار میں بیٹھ گئے۔ جب آپ صلی اللہ علیہ وسلم باہر نکلے تو ہم آپ صلی اللہ علیہ وسلم کی طرف بڑھے اور کہا: ہم لوگ بھگوڑے ہیں۔ آپ صلی اللہ علیہ وسلم ہماری طرف متوجہ ہوئے اور فرمایا ” نہیں، تم دوبارہ لڑائی میں جانے والے ہو۔ “ چنانچہ ہم آپ صلی اللہ علیہ وسلم کے قریب ہوئے اور آپ صلی اللہ علیہ وسلم کے ہاتھ کو بوسہ دیا۔ آپ صلی اللہ علیہ وسلم نے فرمایا ” میں مسلمانوں کی جائے پناہ ہوں۔ “","f2":"امام ترمذی نے (العکار) کا ترجمہ یہ لکھا ہے۔جو شخص امام کی طرف بھاگ آئے۔تاکہ وہ اس کی مد د کرے۔محض لڑائی سے بھاگ جانا مراد نہیں ہے۔(جامع ترمذی۔الجہاد۔حدیث 1716)"}],[2648,"ابوسعید خدری رضی اللہ عنہ کہتے ہیں کہ «ومن يولهم يومئذ دبره» ۱؎ بدر کے دن نازل ہوئی۔\n§وضاحت\n۱؎ : پوری آیت اس طرح ہے «إلا متحرفا لقتال أو متحيزا إلى فئة فقد باء بغضب من الله» ( سورۃ الانفال : ۱۶ ) ’’ جو شخص لڑائی سے اپنی پیٹھ موڑے گا، مگر ہاں جو لڑائی کے لئے پینترا بدلتا ہو یا اپنی جماعت کی طرف پناہ لینے آتا ہو وہ مستثنی ہے باقی جو ایسا کر ے گا وہ اللہ کے غضب میں آ جائیگا ‘‘ ، حدیث میں مذکور ہے لوگوں نے خود کو اس آیت کا مصداق سمجھ لیا تھا تو اللہ کے رسول صلی اللہ علیہ وسلم نے ان کو مستثنی لوگوں میں سے قرار دیا۔","صحیح",{"u2":"سیدنا ابوسعید رضی اللہ عنہ سے مروی ہے کہ بدر کے دن یہ آیت نازل ہوئی تھی «ومن يولهم يومئذ دبره» ” جس نے اس دن، ان (کفار) سے پیٹھ پھیری سوائے اس حال کے کہ پینترا بدلتا ہو لڑائی میں، یا کسی جماعت کی پناہ لیتا ہو۔ “ (تو وہ مستثنیٰ ہے، ورنہ وہ اللہ کے غضب کے ساتھ لوٹا اور اس کا ٹھکانا دوزخ ہے اور یہ بہت برا ٹھکانا ہے)۔ «بسم الله الرحمن الرحيم» ہمیں خبر دی الامام الحافظ ابوبکر احمد بن علی بن ثابت خطیب بغدادی نے، کہا: الامام القاضی ابوعمرو قاسم بن جعفر بن عبدالواحد ہاشمی نے کہا: ہمیں خبر دی ابوعلی محمد بن احمد بن عمرو لؤلؤی نے، انہوں نے کہا: ہمیں بیان کیا ابوداؤد سلیمان بن اشعث سجستانی رضی اللہ عنہ نے ماہ محرم سن دو سو پچھتر ہجری میں، فرمایا۔","f2":"یہ سند سنن ابی دائود کے بعض نسخوں میں نہیں ہے۔ کیونکہ بظاہر اس کا محل کتاب کا آغاذ ہے۔بہرحال یہ امام ابو دائود کی سند ہے۔جوآغاز کے بجائے کتاب کے درمیان میں آگئی ہے۔"}],[2649,"خباب رضی اللہ عنہ کہتے ہیں کہ ہم رسول اللہ صلی اللہ علیہ وسلم کے پاس آئے اور آپ کعبہ کے سائے میں ایک چادر پر تکیہ لگائے ہوئے تھے، ہم نے آپ سے (کافروں کے غلبہ کی) شکایت کی اور کہا: کیا آپ ہمارے لیے اللہ سے مدد طلب نہیں کرتے؟ کیا آپ اللہ سے ہمارے لیے دعا نہیں کرتے؟ (یہ سن کر) آپ صلی اللہ علیہ وسلم بیٹھ گئے اور آپ کا چہرہ سرخ ہو گیا، اور فرمایا: \"تم سے پہلے آدمی کا یہ حال ہوتا کہ وہ ایمان کی وجہ سے پکڑا جاتا تھا، اس کے لیے زمین میں گڑھا کھودا جاتا تھا، اس کے سر کو آرے سے چیر کر دو ٹکڑے کر دیا جاتا تھا مگر یہ چیز اسے اس کے دین سے نہیں پھیرتی تھی، لوہے کی کنگھیوں سے اس کے ہڈی کے گوشت اور پٹھوں کو نوچا جاتا تھا لیکن یہ چیز اسے اس کے دین سے نہیں پھیرتی تھی، اللہ کی قسم! اللہ اس دین کو پورا کر کے رہے گا، یہاں تک کہ سوار صنعاء سے حضر موت تک جائے گا اور سوائے اللہ کے یا اپنی بکریوں کے سلسلہ میں بھیڑئے کے کسی اور سے نہیں ڈرے گا لیکن تم لوگ جلدی کر رہے ہو\"۔","صحیح",{"u2":"سیدنا خباب بن ارت رضی اللہ عنہ کہتے ہیں کہ ہم رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوئے جب کہ آپ صلی اللہ علیہ وسلم ایک چادر کو تکیہ بنائے کعبہ کے سائے میں لیٹے ہوئے تھے۔ ہم نے آپ صلی اللہ علیہ وسلم سے شکایت کی اور کہا: کیا آپ ہمارے لیے مدد نہیں مانگتے؟ کیا آپ ہمارے لیے اللہ سے دعا نہیں فرماتے؟ تو آپ صلی اللہ علیہ وسلم اٹھ بیٹھے، آپ صلی اللہ علیہ وسلم کا چہرہ سرخ ہو گیا اور فرمایا ” تم سے پہلے جو لوگ تھے ان میں سے کسی کو پکڑا جاتا اور اس کے لیے گڑھا کھودا جاتا، پھر آرا لایا جاتا اور اس کے سر پر رکھ کر اسے دو حصے کر دیا جاتا مگر یہ (عذاب بھی) اسے اس کے دین سے نہ پھیرتا تھا، اور (وہ کسی کے ساتھ یوں کرتے کہ) اس کی ہڈیوں تک گوشت اور پٹھوں میں لوہے کی کنگھیاں چلاتے، یہ کاروائی بھی اسے اس کے دین سے نہ پھیرتی تھی۔ اللہ کی قسم! اللہ عزوجل اپنا یہ دین پورا کر کے رہے گا حتیٰ کہ ایک سوار صنعاء اور حضر موت کے درمیان سفر کرے گا، اسے اللہ کے سوا کسی کا خوف نہ ہو گا (زیادہ سے زیادہ) بکریوں کے متعلق اندیشہ ہو گا کہ بھیڑیا نہ حملہ کر دے لیکن تم جلدی کر رہے ہو۔ “ (یعنی صبر و تحمل سے کام لو، اللہ مدد کرے گا۔)","f2":"مسلمان اگرکفار کے نڑغے میں ہوں۔اور اپنی جان بچانے کےلئے بظاہر کفریہ کلمات بول دیں۔تورخصت ہے۔قرآن مجید نے اس ضمن میں بیان کیا ہے۔(مَن كَفَرَ بِاللَّـهِ مِن بَعْدِ إِيمَانِهِ إِلَّا مَنْ أُكْرِهَ وَقَلْبُهُ مُطْمَئِنٌّ بِالْإِيمَانِ)(النحل۔106) جس نے ایمان لے آنے کے بعد اللہ کے ساتھ کفر کیا(تو اس پر اللہ کا غضب ہے۔)سوائے اس کے جسے مجبور کردیا گیا اور اس کا دل ایمان پر مطئمین رہا۔ سورہ آل عمران (آیت 28)میں ہے۔(إِلَّا أَن تَتَّقُوا مِنْهُمْ تُقَاةً ۗ) اگر تم کفار سے بچائو کی کوئی صورت بنالو تو (کوئی حرج نہیں)"}],[2650,"عبیداللہ بن ابی رافع جو علی بن ابی طالب رضی اللہ عنہ کے منشی تھے، کہتے ہیں: میں نے علی رضی اللہ عنہ کو کہتے ہوئے سنا کہ رسول اللہ صلی اللہ علیہ وسلم نے مجھے، زبیر اور مقداد تینوں کو بھیجا اور کہا: \"تم لوگ جاؤ یہاں تک کہ روضہ خاخ ۱؎ پہنچو، وہاں ایک عورت کجاوہ میں بیٹھی ہوئی اونٹ پر سوار ملے گی اس کے پاس ایک خط ہے تم اس سے اسے چھین لینا\"، تو ہم اپنے گھوڑے دوڑاتے ہوئے چلے یہاں تک کہ روضہ خاخ پہنچے اور دفعتاً اس عورت کو جا لیا، ہم نے اس سے کہا: خط لاؤ، اس نے کہا: میرے پاس کوئی خط نہیں ہے، میں نے کہا: خط نکالو ورنہ ہم تمہارے کپڑے اتار دیں گے، اس عورت نے وہ خط اپنی چوٹی سے نکال کر دیا، ہم اسے نبی اکرم صلی اللہ علیہ وسلم کے پاس لائے، وہ حاطب بن ابوبلتعہ رضی اللہ عنہ کی جانب سے کچھ مشرکوں کے نام تھا، وہ انہیں رسول اللہ صلی اللہ علیہ وسلم کے بعض امور سے آگاہ کر رہے تھے، آپ صلی اللہ علیہ وسلم نے پوچھا: \"حاطب یہ کیا ہے؟\" انہوں نے کہا: اللہ کے رسول! میرے سلسلے میں جلدی نہ کیجئے، میں تو ایسا شخص ہوں جو قریش میں آ کر شامل ہوا ہوں یعنی ان کا حلیف ہوں، خاص ان میں سے نہیں ہوں، اور جو لوگ قریش کی قوم سے ہیں وہاں ان کے قرابت دار ہیں، مشرکین اس قرابت کے سبب مکہ میں ان کے مال اور عیال کی نگہبانی کرتے ہیں، چونکہ میری ان سے قرابت نہیں تھی، میں نے چاہا کہ میں ان کے حق میں کوئی ایسا کام کر دوں جس کے سبب مشرکین مکہ میرے اہل و عیال کی نگہبانی کریں، قسم اللہ کی! میں نے یہ کام نہ کفر کے سبب کیا اور نہ ہی ارتداد کے سبب، یہ سن کر رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اس نے تم سے سچ کہا\"، اس پر عمر رضی اللہ عنہ بولے: مجھے چھوڑئیے، میں اس منافق کی گردن مار دوں، تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"یہ جنگ بدر میں شریک رہے ہیں، اور تمہیں کیا معلوم کہ اللہ نے اہل بدر کو جھانک کر نظر رحمت سے دیکھا، اور فرمایا: تم جو چاہو کرو میں تمہیں معاف کر چکا ہوں\"۔\n§وضاحت\n۱؎ : مدینہ سے بارہ میل کی دوری پر ایک مقام کا نام ہے۔","صحیح",{"u2":"عبیداللہ بن ابی رافع رضی اللہ عنہ سیدنا علی بن ابی طالب رضی اللہ عنہ کے کاتب تھے، انہوں نے کہا: میں نے سیدنا علی رضی اللہ عنہ سے سنا، وہ بیان کرتے تھے کہ رسول اللہ صلی اللہ علیہ وسلم نے مجھے، زبیر اور مقداد کو روانہ کیا اور فرمایا ” جاؤ حتیٰ کہ جب تم روضہ خاخ کے مقام پر پہنچو گے تو تمہیں ایک اونٹنی سوار عورت ملے گی اس کے پاس ایک خط ہے، وہ اس سے لے آؤ۔ “ چنانچہ ہم روانہ ہوئے ہمارے گھوڑے ہمیں بڑی تیزی سے لیے جا رہے تھے حتیٰ کہ ہم مقام روضہ پر پہنچ گئے، تو ہم نے وہاں ایک عورت پائی جو اپنی اونٹنی پر سوار تھی۔ ہم نے اس سے کہا: لاؤ خط دے دو۔ اس نے کہا: میرے پاس کوئی خط نہیں ہے۔ میں نے کہا: یا تو، تو خط نکالے گی یا ہم تیرے کپڑے اتار دیں گے۔ چنانچہ اس نے اپنی چٹیا میں سے خط نکال دیا، تو اسے لے کر ہم نبی کریم صلی اللہ علیہ وسلم کے پاس آ گئے۔ وہ حاطب بن ابی بلتعہ کی طرف سے مشرکین کو لکھا گیا تھا، اس میں ان کو رسول اللہ صلی اللہ علیہ وسلم کے بعض معاملات کے متعلق خبر دی گئی تھی۔ آپ صلی اللہ علیہ وسلم نے پوچھا ” حاطب! یہ کیا ہے؟ “ اس نے کہا: اے اللہ کے رسول! مجھ پر جلدی (میں فیصلہ) نہ کیجئیے، دراصل میں اہل قریش میں نو آباد تھا، خاص قبیلہ قریش سے میرا تعلق نہیں تھا جبکہ (مہاجرین) قریش کے وہاں مکہ میں دیگر تعلق دار موجود ہیں جو ان کے اہل و عیال کی حفاظت کرتے ہیں لہٰذا میں نے چاہا کہ مجھے ان کے ساتھ تعلق داری کا کوئی واسطہ حاصل نہیں ہے، تو میں ان پر ایک احسان کر دوں جس کی بنا پر وہ میرے قرابت داروں کا خیال رکھیں۔ اللہ کی قسم! اے اللہ کے رسول! مجھ میں کوئی کفر نہیں ہے اور نہ کوئی ارتداد ہے۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” سچ کہا ہے۔ “ سیدنا عمر رضی اللہ عنہ نے کہا: مجھے چھوڑیے میں اس منافق کی گردن اڑا دوں۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” یہ بدر میں شریک ہو چکا ہے اور تمہیں کیا خبر، شاید اللہ تعالیٰ نے اہل بدر پر نظر فرمائی ہو اور کہا ہے کہ جو چاہے کرو، تحقیق میں نے تمہیں بخش دیا ہے۔ “","f2":"1۔رسول اللہ صلی اللہ علیہ وسلم کا غیب کی خبریں دینا وحی کی بنا پر ہوتا تھا۔2۔مجاہد کو تلوار کا دھنی ہونے کے ساتھ ساتھ دیگر تدابیر سے بھی کام لیناچاہیے۔جیسے کہ حضرت علی رضی اللہ تعالیٰ عنہ نے دھمکی سے کام نکالا۔3۔صحابہ کرامرضوان اللہ عنہم اجمعین کی امانت قابل قدر ہے کہ انہوں نے اپنے طور پر خط پڑھنے کی کوشش نہیں کی۔5۔بعض صحابہ کرامرضوان اللہ عنہم اجمعین تمام تر رفعت شان کے باوجود بشری خطائوں سے مبرا نہ تھے اور ان سے ان کے عادل ہونے پر بھی کوئی اثر نہیں پڑا۔جیسے کہ حضرت حاطبرضی اللہ تعالیٰ عنہ 6۔جب کوئی شخص کسی ناجائز کام کا مرتکب ہوا ہو وہ اس کے جواز میں اپنے فہم (تاویل)کاسہارالے تو اس کا عذر ایک حد تک قبول کیا جائے گا۔بشرط یہ کہ اس کے فہم (تاویل)کی گنجائش نکلتی ہو۔7۔کوئی مسلمان ہوتے ہوئے اپنے مسلمانوں کے راز افشاں کرے۔اور ان کی جاسوسی کرے۔تو یہ حرام کام ہے۔اور انتہائی کبیرہ گناہ مگر اس کو قتل نہیں کیا جائے گا۔لیکن تعزیر ضرور ہوگی۔امام شافعی فرماتے ہیں۔کہ اگر کوئی مسلمان باوقار ہو اور مسلمانوں کو ضرر پہنچانے کی تہمت سے مہتم نہ ہو تو اس کو معاف بھی کیا جاسکتا ہے۔8۔کسی واضح عمل کی بنا پر اگر کوئی شخص کسی کو کفر یانفاق کی طرف منسوب کردے تو اس پرکوئی سزا نہیں۔جیسے کہ حضرت عمر رضی اللہ تعالیٰ عنہ نے کہا تھا۔9۔اہل بدر کو دیگر صحابہ رضوان اللہ عنہم اجمعین کے مقابلے میں ایک ممتاز مرتبہ حاصل تھا۔حضرت حاطبرضی اللہ تعالیٰ عنہ انہی میں سے تھے۔اور نفاق کی تہمت سے بری تھے۔2۔جوجی چاہے کرو۔کے یہ معنی ہرگز نہیں کہ وہ شرعی پابندیوں سے آذاد قرار دیئے گئے۔ بلکہ یہ ان کی مدح ثناء تھی۔ اور اللہ تعالیٰ کی طرفسے ضمانت تھی۔ کہ یہ لوگ اللہ کی خاص حفاظت میں ہیں۔ان میں سے کوئی ایسا کام مصادر نہ ہوگا۔ جوشریعت کے صریح منافی ہو۔واللہ اعلم۔"}],[2651,"اس سند سے بھی علی رضی اللہ عنہ سے یہی قصہ مروی ہے، اس میں ہے کہ حاطب بن ابی بلتعہ نے اہل مکہ کو لکھ بھیجا کہ محمد صلی اللہ علیہ وسلم تمہارے اوپر حملہ کرنے والے ہیں، اس روایت میں یہ بھی ہے کہ وہ عورت بولی: \"میرے پاس تو کوئی خط نہیں ہے\"، ہم نے اس کا اونٹ بٹھا کر دیکھا تو اس کے پاس ہمیں کوئی خط نہیں ملا، علی رضی اللہ عنہ نے کہا: قسم ہے اس ذات کی جس کی قسم کھائی جاتی ہے! میں تجھے قتل کر ڈالوں گا، ورنہ خط مجھے نکال کر دے، پھر پوری حدیث ذکر کی۔","صحیح",{"u2":"سیدنا ابوعبدالرحمٰن سلمی، سیدنا علی رضی اللہ عنہ سے یہ قصہ بیان کرتے ہیں کہ سیدنا حاطب رضی اللہ عنہ نے اہل مکہ کو لکھا تھا کہ محمد صلی اللہ علیہ وسلم تمہاری طرف رخ کرنے والے ہیں۔ اس روایت میں ہے کہ اس عورت نے کہا: میرے پاس خط نہیں ہے۔ تو ہم نے اس کی اونٹنی کو بٹھا لیا مگر ہمیں اس کے پاس کوئی خط نہ ملا سیدنا علی رضی اللہ عنہ بولے: قسم اس ذات کی جس کی قسم اٹھائی جاتی ہے! میں تجھے قتل کر ڈالوں گا، نہیں تو خط نکال دے۔ اور حدیث بیان کی۔"}],[2652,"فرات بن حیان رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے ان کے متعلق قتل کا حکم صادر فرمایا، یہ ابوسفیان کے جاسوس اور ایک انصاری کے حلیف تھے ۱؎، ان کا گزر حلقہ بنا کر بیٹھے ہوئے کچھ انصار کے پاس سے ہوا تو انہوں نے کہا کہ میں مسلمان ہوں، ایک انصاری نے کہا: اللہ کے رسول! یہ کہتا ہے کہ میں مسلمان ہوں، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"تم میں سے بعض لوگ ایسے ہیں کہ ہم انہیں ان کے ایمان کے سپرد کرتے ہیں، ان ہی میں سے فرات بن حیان بھی ہیں\"۔\n§وضاحت\n۱؎ : ایک انصاری کے حلیف ہونے کے باوجود رسول اللہ صلی اللہ علیہ وسلم نے فرات بن حیان کے متعلق قتل کا حکم صادر فرمایا، اس سے معلوم ہوا کہ ذمی جاسوس کو قتل کرنا صحیح ہے۔","صحیح",{"u2":"سیدنا فرات بن حیان رضی اللہ عنہ (اپنے متعلق) بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے اس کو قتل کرنے کا حکم دیا تھا جبکہ وہ ابوسفیان کی طرف سے جاسوس بن کر آیا تھا۔ یہ ایک انصاری کا حلیف بھی تھا۔ وہ انصاریوں کی ایک جماعت کے پاس سے گزرا اور کہا: بیشک میں مسلمان ہوں۔ تو ایک انصاری نے کہا: اے اللہ کے رسول! یہ کہتا ہے کہ میں مسلمان ہوں۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” تم میں کچھ لوگ ایسے ہیں کہ ہم ان کو ان کے ایمان کے سپرد کر دیتے ہیں، ان میں سے فرات بن حیان بھی ہے۔ “","f2":"مطلب یہ ہے کہ ہم ان کے اظہار ایمان کو نہیں جھٹلاتے بلکہ ان کے معاملے کو اللہ کے سپرد کردیتے ہیں۔اگر وہ مخلص ہوں گے تو عند اللہ معزز اور اس کے برعکس ہوں گے۔تو عند اللہ مجرم۔لیکن ہم اس کے ساتھ اس کے ظاہر کے مطابق معاملہ کریں گے۔اس سے یہ اصول معلوم ہوا کہ اسلامی مملکت عوام کے ظاہری حالات کے مطابق فیصلہ کرنے کی پابند ہے۔کیونکہ باطن کا علم تو صرف اللہ ہی کو ہے۔اور وہی قیامت کے دن اس کے مطابق فیصلہ فرمائے گا۔اسی لئے کہا جاتا ہے۔(نحن نحكم بالظواهر والله يتولي السرائر)ہم صرف ظاہری حالات پر حکم لگاسکتے ہیں۔ جبکہ پوشیدہ معاملات اللہ کے سپرد ہیں۔2۔کافر جاسوس کے قتل کردینے پراتفاق ہے۔مگر مسلمان کو قتل نہیں کرنا چاہیے۔خواہ منافق ہی ہو۔3۔باب میں ذمی جاسوس کا ذکر ہے۔جب کہ حدیث میں حضرت فرات کے ذمی ہونے کی صراحت نہیں ہے۔لیکن یہی روایت منتقی الاخیار میں مسند احمد کے حوالے سے ہے۔اس میں صراحت ہے کہ نبی کریم صلی اللہ علیہ وسلم نے ان کے قتل کا حکم دیا۔وکان ذمیاً اور وہ ذمی تھے۔ ان الفاظ سے باب کے ساتھ مناسبت بھی واضح ہوجاتی ہے۔اور ذمی جاسوس کے قتل کرنے جواز بھی (عون المعبود)4۔فرات بن حیان نے بعد میں اسلام قبول کرلیا۔اور بہت عمدہ مسلمان ثابت ہوئے۔ ہجرت کی اوررسول اللہ صلی اللہ علیہ وسلم کے حین حیات آپ کی معیت میں جہاد کرتے رہے۔بعد ازاں کوفہ میں سکونت اختیار کرلی تھی۔"}],[2653,"سلمہ بن الاکوع رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم کے پاس مشرکوں میں سے ایک جاسوس آیا، آپ سفر میں تھے، وہ آپ کے اصحاب کے پاس بیٹھا رہا، پھر چپکے سے فرار ہو گیا، نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"اس کو تلاش کر کے قتل کر ڈالو\"، سلمہ بن اکوع رضی اللہ عنہ کہتے ہیں: سب سے پہلے میں اس کے پاس پہنچا اور جا کر اسے قتل کر دیا اور اس کا مال لے لیا تو آپ صلی اللہ علیہ وسلم نے اسے بطور نفل (انعام) مجھے دیدیا۔","صحیح",{"u2":"سیدنا سلمہ بن اکوع رضی اللہ عنہ سے مروی ہے کہایک سفر میں مشرکین کا کوئی جاسوس نبی کریم صلی اللہ علیہ وسلم کے پاس آیا اور صحابہ کے ساتھ بیٹھا رہا، پھر خاموشی سے کھسک گیا تو نبی کریم صلی اللہ علیہ وسلم نے فرمایا ” اسے ڈھونڈو اور قتل کر ڈالو۔ “ سیدنا سلمہ نے کہا: میں نے دوسروں سے پہلے اس لو جا لیا اور قتل کر دیا اور اس کا سامان لے آیا۔ پس آپ صلی اللہ علیہ وسلم نے وہ سامان مجھے ہی بطور نفل (انعام) عنایت فر دیا۔"}],[2654,"سلمہ بن الاکوع رضی اللہ عنہ کہتے ہیں کہ میں رسول اللہ صلی اللہ علیہ وسلم کے ساتھ ہوازن کا غزوہ کیا، وہ کہتے ہیں: ہم چاشت کے وقت کھانا کھا رہے تھے، اور اکثر لوگ ہم میں سے پیدل تھے، ہمارے ساتھ کچھ ناتواں اور ضعیف بھی تھے کہ اسی دوران ایک شخص سرخ اونٹ پر سوار ہو کر آیا، اور اونٹ کی کمر سے ایک رسی نکال کر اس سے اپنے اونٹ کو باندھا، اور لوگوں کے ساتھ کھانا کھانے لگا، جب اس نے ہمارے کمزوروں اور سواریوں کی کمی کو دیکھا تو اپنے اونٹ کی طرف دوڑتا ہوا نکلا، اس کی رسی کھولی پھر اسے بٹھایا اور اس پر بیٹھا اور اسے ایڑ لگاتے ہوئے تیزی کے ساتھ چل پڑا (جب لوگوں کو معلوم ہوا کہ یہ جاسوس ہے) تو قبیلہ اسلم کے ایک شخص نے اپنی خاکستری اونٹنی پر سوار ہو کر اس کا پیچھا کیا اور یہ لوگوں کی سواریوں میں سب سے بہتر تھی، پھر میں آگے بڑھا یہاں تک کہ میں نے اسے پا لیا اور حال یہ تھا کہ اونٹنی کا سر اونٹ کے پٹھے کے پاس اور میں اونٹنی کے پٹھے پر تھا، پھر میں تیزی سے آگے بڑھتا گیا یہاں تک کہ میں اونٹ کے پٹھے کے پاس پہنچ گیا، پھر آگے بڑھ کر میں نے اونٹ کی نکیل پکڑ لی اور اسے بٹھایا، جب اونٹ نے اپنا گھٹنا زمین پر ٹیکا تو میں نے تلوار میان سے نکال کر اس کے سر پر ماری تو اس کا سر اڑ گیا، میں اس کا اونٹ مع ساز و سامان کے کھینچتے ہوئے لایا تو لوگوں کے ساتھ رسول اللہ صلی اللہ علیہ وسلم نے آ کر میرا استقبال کیا اور پوچھا: \"اس شخص کو کس نے مارا؟\" لوگوں نے بتایا: سلمہ بن اکوع نے، آپ صلی اللہ علیہ وسلم نے فرمایا: \"اس کا سارا سامان انہی کو ملے گا ۱؎\"۔\n§وضاحت\n۱؎ : اس حدیث سے معلوم ہوا کہ امن حاصل کرنے والے کافر کے متعلق اگر یہ معلوم ہو جائے کہ یہ جاسوس ہے تو اسے قتل کرنا جائز ہے۔","حسن",{"u2":"سیدنا ایاس بن سلمہ کہتے ہیں مجھ سے میرے والد (سیدنا سلمہ بن اکوع رضی اللہ عنہ) نے بیان کیا، کہا کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کے ساتھ قبیلہ ہوازن پر جہاد کیا۔ اتفاق سے ہم چاشت کے وقت کھانا کھا رہے تھے اور ہم میں اکثر مجاہدین پیدل تھے اور کچھ لوگ کمزور بھی تھے، اتنے میں ایک شخص آیا جو سرخ اونٹ پر سوار تھا، اس نے اونٹ کی کمر سے رسی نکالی، اس سے اس کو باندھا اور آ کر لوگوں کے ساتھ کھانے میں شریک ہو گیا۔ جب اس نے دیکھا کہ مجاہدین میں کمزور لوگ ہیں اور ان میں سواریوں کی بھی کمی ہے تو وہاں سے نکلا، بھاگتا ہوا اپنے اونٹ کے پاس پہنچا اور اسے کھولا، اس کو بٹھایا، خود اس پر بیٹھا اور پھر اسے دوڑاتے ہوئے چل دیا۔ (اس وقت ہم کو یقین ہو گیا کہ یہ جاسوس ہے) چنانچہ قبیلہ اسلم کا ایک شخص اپنی خاکستری اونٹنی پر اس کے تعاقب میں گیا، اور یہ اونٹنی ہماری سب سواریوں سے عمدہ سواری تھی۔ سلمہ کہتے ہیں: میں پیدل ہی بھاگتا ہوا اس کے پیچھے گیا اور اسے جا لیا جبکہ اونٹنی کا سر اونٹ کی ران کے پاس تھا اور میں اونٹنی کی پچھلی ٹانگوں کے ساتھ تھا۔ پھر میں آگے بڑھا حتیٰ کہ اونٹ کی پچھلی ٹانگوں کے پاس پہنچ گیا۔ میں اور آگے بڑھا حتیٰ کہ اونٹ کی نکیل پکڑ لی اور پھر اس کو بٹھا لیا۔ جب اس نے اپنا گھٹنا زمین پر رکھا تو میں نے اپنی تلوار نکالی اور اس سوار کے سر پر دے ماری تو وہ کٹ کر دور جا گرا، چنانچہ میں اس کا اونٹ اور جو اس پر تھا سب ہانک کر لے آیا۔ تو رسول اللہ صلی اللہ علیہ وسلم نے لوگوں سے آگے بڑھ کر میرا استقبال کیا اور پوچھا: ” اس آدمی کو کس نے قتل کیا ہے؟ “ صحابہ نے کہا: سلمہ بن اکوع نے، آپ صلی اللہ علیہ وسلم نے فرمایا ” اس کا سارا اسباب اسی کا ہے۔ “ (امام ابوداؤد رضی اللہ عنہ کے شیخ) ہارون نے کہا: اس روایت کے الفاظ ہاشم بن قاسم کے ہیں۔","f2":"1۔کافر جاسوس خواہ مستامن ہی ہو۔(اجازت لے کر مسلمانوں کے پاس لے کر آیا ہو)قتل کیا جاسکتا ہے۔کیونکہ وہ حربی کافروں میں شامل ہے۔2۔کافر مقتول کا خاص سامان اس کے قاتل مجاہد کو دیا جاتا ہے۔ اسے سلب کہتے ہیں۔3۔جہاد میں کامیابی کی بنیاد اللہ تعالیٰ کی نصرت اور تقویٰ ہے۔دیگر وسائل محض ظاہری اسباب ہوتے ہیں۔لیکن ان سے صرف نظر کرنا جائز نہیں۔4۔حضرت سلمہ بن اکوع رضی اللہ تعالیٰ عنہ نوعمر جوان تھے۔اورتیز دوڑنے میں نہایت ممتاز تھے۔اس لئے اونٹ سوار کو جا پکڑا۔"}],[2655,"نعمان بن مقرن رضی اللہ عنہ کہتے ہیں کہ میں رسول اللہ صلی اللہ علیہ وسلم کے ساتھ (لڑائی میں) شریک رہا آپ جب صبح کے وقت جنگ نہ کرتے تو قتال (لڑائی) میں دیر کرتے یہاں تک کہ آفتاب ڈھل جاتا، ہوا چلنے لگتی اور مدد نازل ہونے لگتی۔","صحیح",{"u2":"سیدنا نعمان بن مقرن رضی اللہ عنہ بیان کرتے ہیں کہ میں رسول اللہ صلی اللہ علیہ وسلم کے ہاں حاضر رہا ہوں، آپ صلی اللہ علیہ وسلم اگر دن کے ابتدائی حصے میں قتال نہ کرتے تو اس میں اتنی تاخیر فرماتے کہ سورج ڈھل جاتا، ہوائیں چلنے لگتیں اور نصرت نازل ہوتی۔","f2":"سورج ڈھلنے کا وقت اللہ کی طرف سے نزول نصرت کا وقت ہوتا ہے۔اس وقت میں قتال شروع کرنا مستحب ہے۔اس لئے ظہر کی نماز اول وقت میں پڑھنی مسنون ہے۔اورراحج ہے۔آپ صلی اللہ علیہ وسلم سے اسوقت چار رکعت نفل پڑھنا بھی وارد ہے۔"}],[2656,"قیس بن عباد رضی اللہ عنہ کہتے ہیں کہ صحابہ کرام رضی اللہ عنہم قتال کے وقت آواز ۱؎ ناپسند کرتے تھے۔\n§وضاحت\n۱؎ : دوران قتال آواز کرنے سے مراد مجاہدین کا آپس میں ایک دوسرے کو بآواز بلند نام لے کر پکارنا یا ایسے الفاظ سے پکارنا ہے جس سے وہ فخر و غرور میں مبتلا ہو جائیں، اسے صحابہ ناپسند کرتے تھے۔","صحیح",{"u2":"سیدنا قیس بن عباد رضی اللہ عنہ بیان کرتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم کے صحابہ قتال کے دوران میں آوازیں نکالنے کو ناپسند کرتے تھے۔","f2":"1۔یہ روایت ہمارے فاضل محقق کے نزدیک ضعیف ہے۔البتہ شیخ البانی اس کی بابت فرماتے ہیں۔کہ یہ روایت مرفوع نہیں موقوف صحیح ہے۔2۔دوران قتال بے معنی تکبر آمیز ڈینگیں مارنا اور اپنی بڑائی کا اظہار کرنا پسندیدہ نہیں ہے۔تاہم مسلمانوں کے حوصلے بڑھانے۔بلند رکھنے۔آگےبڑھنے کی دعوت دینے اورکفار کودہانے کےلئے حسب احوال کچھ کہناجائز اور مطلوب ہے۔خود رسول للہ صلی اللہ علیہ وسلم کا یہ رجز دوران قتال ہی کا ہے۔(انا النبي لا كذب انا ابن عبد المطلب) (صحیح البخاری الجہاد۔والسیر۔حدیث 3042)ایسے ہی حضرت سلمہ بن اکوع رضی اللہ تعالیٰ عنہ نے ایک بار اپنے مقابل سے کہا تھا۔یہ لو! اور میں اکوع کافرزند ہوں۔ (صحیح البخاری الجہاد۔والسیر۔حدیث3041) اور سب سے افضل عمل اللہ کا زکر ہے۔"}],[2657,"ابوبردہ رضی اللہ عنہ اپنے والد (ابوموسی اشعری رضی اللہ عنہ) سے اور وہ نبی اکرم صلی اللہ علیہ وسلم سے اسی کے مثل روایت کرتے ہیں۔","ضعیف",{"u2":"سیدنا ابوبردہ اپنے والد (سیدنا ابوموسیٰ اشعری رضی اللہ عنہ) سے وہ نبی کریم صلی اللہ علیہ وسلم سے اسی کی مثل روایت کرتے ہیں۔"}],[2658,"براء رضی اللہ عنہ کہتے ہیں کہ جب نبی اکرم صلی اللہ علیہ وسلم کی حنین کے دن مشرکوں سے مڈبھیڑ ہوئی تو وہ چھٹ گئے (یعنی شکست کھا کر ادھر ادھر بھاگ کھڑے ہوئے) اور آپ صلی اللہ علیہ وسلم اپنے خچر سے اتر کر پیدل چلنے لگے۔","صحیح",{"u2":"سیدنا براء رضی اللہ عنہ بیان کرتے ہیں کہ حنین کے دن جب نبی کریم صلی اللہ علیہ وسلم کا مشرکین کے ساتھ مقابلہ ہوا اور مسلمان آپ صلی اللہ علیہ وسلم کے پاس سے بھاگ گئے، تو آپ صلی اللہ علیہ وسلم اپنے خچر سے نیچے اتر کر پیدل ہو گئے۔","f2":"مجاہد دوران جہاد میں حسب احوال کوئی انداز بھی اختیار کرے روا ہے۔اور نبی صلی اللہ علیہ وسلم سب مسلمانوں سے بڑھ کر بہادردلیر اور عزم وثبات کے پیکرتھے۔"}],[2659,"جابر بن عتیک رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم فرماتے تھے: \"ایک غیرت وہ ہے جسے اللہ پسند کرتا ہے، اور دوسری غیرت وہ ہے جسے اللہ ناپسند کرتا ہے، رہی وہ غیرت جسے اللہ پسند کرتا ہے تو وہ شک کے مقامات میں غیرت کرنا ہے، رہی وہ غیرت جسے اللہ ناپسند کرتا ہے وہ شک کے علاوہ میں غیرت کرنا ہے، اور تکبر میں سے ایک وہ ہے جسے اللہ ناپسند کرتا ہے اور دوسرا وہ ہے جسے اللہ پسند کرتا ہے، پس وہ تکبر جسے اللہ پسند کرتا ہے وہ لڑائی کے دوران آدمی کا کافروں سے جہاد کرتے وقت تکبر کرنا اور اترانا ہے، اور صدقہ دیتے وقت اس کا خوشی سے اترانا ہے، اور وہ تکبر جسے اللہ ناپسند کرتا ہے وہ ظلم میں تکبر کرنا ہے\"، اور موسی کی روایت میں ہے: \"فخر و مباہات میں تکبر کرنا ہے\"۔","حسن",{"u2":"سیدنا جابر بن عتیک رضی اللہ عنہ سے مروی ہے کہ اللہ کے نبی صلی اللہ علیہ وسلم فرمایا کرتے تھے ” غیرت کے کچھ انداز اللہ تعالیٰ کو محبوب اور کچھ ناپسند ہیں، اللہ عزوجل کی پسندیدہ غیرت وہ ہے جو شبہ کی بنا پر ہو، مگر ایسی غیرت جو بغیر کسی شبہ کے ہو، اللہ تعالیٰ کو ناپسند ہے۔ اسی طرح بڑائی کا اظہار بھی کچھ ایسا ہے جو اللہ کو ناپسند ہے اور کچھ پسندیدہ ہے۔ پسندیدہ بڑائی کا اظہار وہ ہے جو قتال کے وقت مجاہد اپنے متعلق کرتا ہے یا صدقہ کرتے وقت ہو، اور بڑائی کا اظہار جو اللہ تعالیٰ کو ناپسند ہے وہ ہے جو ظلم اور تعدی میں ہو۔ “ موسیٰ بن اسمٰعیل (شیخ ابوداؤد رضی اللہ عنہ) نے (ناپسندیدہ بڑائی کے اظہار میں) ” نسب میں فخر “ کا بھی ذکر کیا۔","f2":"شبہ کی بنا پر غیرت اس طرح کا مثلا انسان کسی ایسے شخص کو دیکھے جو غیر محرم ہوتےہوئے اس کی بیوی یا بیٹی وغیر ہ کے ساتھ آزادانہ میل جول بڑھاتاہے۔اور ہنسی مذاق کرتاہے۔اس حال میں غیرت کا اظہار مطلوب اور اللہ کو محبوب ہے۔اور بغیر کسی شبہ کے غیرت مثلا کوئی کسی کی ماں یا بہن سے عقد شرعی کرنا چاہے تو اس پر غیرت کھانے کے کوئی معنی نہیں کیونکہ یہ عمل عین شریعت کا مطلوب ہے۔ بڑائی او ر تکبر کا اظہار کفار کے مقابلے میں مسلمانوں کی ہیبت بڑھانے کےلئے مطلوب و محبوب ہے۔یوں کہ انسان انتہائی اعتماد وثبات سے کفار پر حملہ آور ہوا اور اس کی چال ڈھال سے کسی کمزوری یا مرعوبیت کا ظہار نہ ہو۔اور صدقہ دینے میں بڑائی یہ ہے کہ خوش دلی سے دے۔اس عمل کو اللہ کا انعام سمجھے اور جو دے اسے کم سمجھے اور فقروفاقہ کا اندیشہ نہ رکھتا ہو۔"}],[2660,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے دس آدمیوں کو جاسوسی کے لیے بھیجا، اور ان کا امیر عاصم بن ثابت رضی اللہ عنہ کو بنایا، ان سے لڑنے کے لیے ہذیل کے تقریباً سو تیر انداز نکلے، جب عاصم رضی اللہ عنہ نے ان کے آنے کو محسوس کیا تو ان لوگوں نے ایک ٹیلے کی آڑ میں پناہ لی، کافروں نے ان سے کہا: اترو اور اپنے آپ کو سونپ دو، ہم تم سے عہد کرتے ہیں کہ تم میں سے کسی کو قتل نہ کریں گے، عاصم رضی اللہ عنہ نے کہا: رہی میری بات تو میں کافر کی امان میں اترنا پسند نہیں کرتا، اس پر کافروں نے انہیں تیروں سے مارا اور ان کے سات ساتھیوں کو قتل کر دیا جن میں عاصم رضی اللہ عنہ بھی تھے اور تین آدمی کافروں کے عہد اور اقرار پر اعتبار کر کے اتر آئے، ان میں ایک خبیب، دوسرے زید بن دثنہ، اور تیسرے ایک اور آدمی تھے رضی اللہ عنہم، جب یہ لوگ کفار کی گرفت میں آ گئے تو کفار نے اپنی کمانوں کے تانت کھول کر ان کو باندھا، تیسرے شخص نے کہا: اللہ کی قسم! یہ پہلی بدعہدی ہے، اللہ کی قسم! میں تمہارے ساتھ نہیں جاؤں گا، میرے لیے میرے ان ساتھیوں کی زندگی نمونہ ہے، کافروں نے ان کو کھینچا، انہوں نے ساتھ چلنے سے انکار کیا، تو انہیں قتل کر دیا، اور خبیب رضی اللہ عنہ ان کے ہاتھ میں قیدی ہی رہے، یہاں تک کہ انہوں نے خبیب کے بھی قتل کرنے کا ارادہ کر لیا، تو آپ نے زیر ناف کے بال مونڈنے کے لیے استرا مانگا ۱؎، پھر جب وہ انہیں قتل کرنے کے لیے لے کر چلے تو خبیب رضی اللہ عنہ نے ان سے کہا: مجھے چھوڑو میں دو رکعت نماز پڑھ لوں، پھر کہا: اللہ کی قسم! اگر تم یہ گمان نہ کرتے کہ مجھے مارے جانے کے خوف سے گھبراہٹ ہے تو میں اور دیر تک پڑھتا۔\n§وضاحت\n۱؎ : سولی دیتے وقت بے پردہ ہونے کا خطرہ تھا، اس لئے خبیب رضی اللہ عنہ نے استرا طلب کیا تا کہ زیر ناف صاف کر لیں۔","صحیح",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم نے دس افراد کو بطور جاسوس روانہ کیا اور ان پر سیدنا عاصم بن ثابت کو امیر مقرر کیا، تو قبیلہ ہذیل کے تقریباً ایک سو تیر انداز ان کے مقابلے میں آ گئے۔ جب عاصم رضی اللہ عنہ نے ان کو دیکھا تو یہ سب ایک ٹیلے کی اوٹ میں ہو گئے (مگر ان کافروں نے ان کو گھیر لیا) اور بولے: ہتھیار پھینک دو اور اپنے آپ کو ہمارے حوالے کر دو، ہم تم سے یہ عہد کرتے ہیں اور پختہ وعدہ ہے کہ تم میں سے کسی کو قتل نہ کریں گے۔ عاصم رضی اللہ عنہ نے کہا: میں کسی کافر کے عہد میں نہیں آتا۔ تو انہوں نے ان مجاہدین کو تیر مارے اور عاصم سمیت سات افراد کو قتل کر دیا، اور تین افراد نے ان کافروں کا عہد و میثاق قبول کر لیا۔ یہ تھے خبیب اور زید بن وثنہ اور ایک اور آدمی (اس کا نام عبداللہ بن طارق بلوی آیا ہے۔) جب ان کافروں نے ان کو پکڑ لیا تو انہوں نے ان کی کمانوں کی تانتیں کھولیں اور ان سے ان کو باندھ دیا۔ تیسرا آدمی کہنے لگا: یہ پہلا دھوکہ ہے، اللہ کی قسم! میں تمہارے ساتھ نہیں چلوں گا۔ میرے لیے میرے (قتل ہو جانے والے) ساتھی ہی نمونہ ہیں۔ انہوں نے اس کو گھسیٹا مگر اس نے ان کے ساتھ چلنے سے انکار کر دیا تو انہوں نے اس کو قتل کر دیا۔ (اور خبیب اور زید کو انہوں نے مکہ لے جا کر بیچ دیا۔ سیدنا خبیب کو حارث بن عامر کے بیٹوں نے خرید لیا) چنانچہ خبیب رضی اللہ عنہ (ان کے) قیدی ہو گئے حتیٰ کہ انہوں نے ان کو قتل کرنے کا فیصلہ کر لیا۔ (متعینہ تاریخ سے پہلے) خبیب نے ان سے استرا طلب کیا تاکہ زیر ناف بال صاف کر سکیں، جب وہ ان کو قتل کرنے کے لیے چلے، تو خبیب رضی اللہ عنہ نے کہا: مجھے مہلت دو میں دو رکعت ادا کر لوں۔ پھر کہا: قسم اللہ کی! اگر مجھے یہ شبہ نہ ہوتا کہ تم لوگ سمجھو گے کہ ڈر کے مارے نماز پڑھتا ہو تو میں اور زیادہ پڑھتا۔"}],[2661,"زہری سے روایت ہے کہ مجھے عمرو بن ابوسفیان بن اسید بن جاریہ ثقفی نے خبر دی (وہ بنو زہرہ کے حلیف اور ابوہریرہ رضی اللہ عنہ کے اصحاب میں سے تھے)، پھر راوی نے پوری حدیث ذکر کی۔","صحیح",{"u2":"ابن عوف کی سند ہے کہ زہری نے کہا: مجھے عمرو بن ابی سفیان بن اسید بن جاریہ ثقفی نے بیان کیا اور یہ بنی زہرہ کے حلیف اور سیدنا ابوہریرہ رضی اللہ عنہ کے شاگردوں میں سے تھے اور حدیث بیان کی۔","f2":"1۔کفار کی امان یا قید قبول نہ کرنا۔عزیمت اورقبول کر لینا رخصت ہے۔2۔جہاں تک ہوسکے۔نبی کریم صلی اللہ علیہ وسلم کی سنت کو ہاتھ سے نہیں جانے دینا چاہیے جیسے کہ خبیب بن عدی رضی اللہ تعالیٰ عنہ نے قبل از شہادت زیر ناف کی صفائی کا اہتمام کیا۔3۔نماز ہی وہ بہترین عمل ہے۔ جس کے زریعے سے بندہ اپنے رب کا قرب حاصل کرتاہے۔ااور قتل کیے جانے سے پہلے نماز پڑھنا سب سے پہلے جناب خبیب رضی اللہ تعالیٰ عنہ ہی نے شروع کیاہے۔4۔حضرت خبیب رضی اللہ تعالیٰ عنہ نے جنگ بدر میں حارث بن عامرکو قتل کیاتھا۔حارث کے بیٹوں نے حضرت خبیب کوشہید کرکے اپنی آتش انتقام کوبجھانے کا اہتمام کیا۔حالانکہ جنگ میں مدمقابل حریف کو قتل کرنا اورچیز ہے۔ لیکن حالت امن میں اس کا بدلہ لینا کسی بھی لہاظ سے صحیح نہیں ہے۔اور کوئی بھی مذہب اس کا قائل نہیں ہے۔"}],[2662,"براء رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے جنگ احد میں عبداللہ بن جبیر رضی اللہ عنہ کو تیر اندازوں کا امیر بنایا ان کی تعداد پچاس تھی اور فرمایا: \"اگر تم دیکھو کہ ہم کو پرندے اچک رہے ہیں پھر بھی اپنی اس جگہ سے نہ ہٹنا یہاں تک کہ میں تمہیں بلاؤں اور اگر تم دیکھو کہ ہم نے کافروں کو شکست دے دی ہے، انہیں روند ڈالا ہے، پھر بھی اس جگہ سے نہ ہٹنا، یہاں تک کہ میں تمہیں بلاؤں\"، پھر اللہ تعالی نے کافروں کو شکست دی اور اللہ کی قسم میں نے مشرکین کی عورتوں کو دیکھا کہ بھاگ کر پہاڑوں پر چڑھنے لگیں، عبداللہ بن جبیر کے ساتھی کہنے لگے: لوگو! غنیمت، غنیمت، تمہارے ساتھی غالب آ گئے تو اب تمہیں کس چیز کا انتظار ہے؟ اس پر عبداللہ بن جبیر رضی اللہ عنہ نے کہا: کیا تم وہ بات بھول گئے جو تم سے رسول اللہ صلی اللہ علیہ وسلم نے کہی ہے؟ تو ان لوگوں نے کہا: اللہ کی قسم! ہم ضرور مشرکین کے پاس جائیں گے اور مال غنیمت لوٹیں گے، چنانچہ وہ ہٹ گئے تو اللہ نے ان کے منہ پھیر دئیے اور وہ شکست کھا کر واپس آئے۔","صحیح",{"u2":"سیدنا براء بن عازب رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے احد والے دن تیر اندازوں کے جتھے پر سیدنا عبداللہ بن جبیر رضی اللہ عنہ کو امیر مقرر کیا، ان لوگوں کی تعداد پچاس تھی اور ان سے فرمایا تھا ” اگر تم دیکھو کہ پرندے ہمیں اچک رہے ہیں، تب بھی تم یہ جگہ نہ چھوڑنا حتیٰ کہ میں تمہیں کوئی پیغام بھیجوں۔ اور اگر تم دیکھو کہ ہم نے کافروں کو شکست دے دی ہے اور ہم ان کو روند رہے ہیں، تب بھی تم یہیں رہنا حتیٰ کہ میں تمہیں بلواؤں۔ “ بیان کرتے ہیں کہ اللہ تعالیٰ نے کافروں کو شکست سے دوچار کر دیا۔ قسم اللہ کی! میں نے دیکھا ان کی عورتیں (پناہ کے لیے) پہاڑ پر چڑھ رہی تھیں۔ تو عبداللہ بن جبیر کے (تیر انداز) ساتھیوں نے کہا: غنیمت! اے قوم غنیمت! تمہارے ساتھی غالب آ گئے ہیں، تم کیا دیکھ رہے ہو؟ عبداللہ بن جبیر نے کہا: کیا تم بھول گئے ہو کہ رسول اللہ صلی اللہ علیہ وسلم نے تم سے کیا فرمایا تھا۔ انہوں نے کہا: قسم اللہ کی! ہم تو لوگوں کے ساتھ مل کر غنیمت جمع کریں گے۔ چنانچہ وہ چلے آئے، تو ان کے منہ پھیر دیے گئے اور شکست سے دوچار ہوئے۔","f2":"1۔دشمن پر حملہ کرنے یا اپنے دفاع کےلئے مجاہدین کوکمین گاہ میں چھپنا یا چھپانا جائز اور نظم جہاد کا ایک اہم حصہ ہوتاہے۔2۔رسول اللہ صلی اللہ علیہ وسلم کے حکم کی پرواہ نہ کرنے اور مال کی حرص کا نتیجہ شکست کی صورت میں سامنے آیا۔جو اگرچہ عارضی تھی۔اس لئے واجب ہے کہ انسان فرامین رسول صلی اللہ علیہ وسلم کو ہرحال میں اولیت اور اولیت دے تاکہ دنیا اور آخرت کی ہزیمت سے محفوظ رہے۔3۔شرعی امیر کی اطاعت بھی واجب ہے۔ اورسپہ سالار کی منصوبہ بندی کے احکام بلا چون وچرا ماننے چاہیں۔"}],[2663,"ابواسید رضی اللہ عنہ کہتے ہیں کہ جب ہم نے بدر کے دن صف بندی کی تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جب کافر تمہارے قریب پہنچ جائیں ۱؎ تب تم انہیں نیزوں سے مارنا، اور اپنے تیر بچا کر رکھنا\"۔\n§وضاحت\n۱؎ : یعنی تیر کی زد میں آ جائیں۔","صحیح",{"u2":"سیدنا حمزہ بن ابی اسید اپنے والد (ابواسید مالک بن ربیعہ انصاری رضی اللہ عنہ) سے روایت کرتے ہیں انہوں نے کہا کہ جب ہم نے بدر میں صفیں بنا لیں تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” جب وہ تمہارے قریب ہوں (تمہاری زد میں آ جائیں) تو تیر مارنا اور اپنے تیروں کو محفوظ رکھنا۔ “ (بلا ضرورت تیر نہ چلانا، تاکہ تیر محفوظ رہیں)۔","f2":"دشمن کے مقابلے میں صف بندی عمدہ ہونی چاہیے۔اورخوب تاک کر نشانہ مارا جائے۔ تاکہ کوئی تیر گولی یا گولہ وغیرہ ضائع نہ ہو۔اور کسی بھی موقع پرمال کا ضائع کرنا جائز نہیں۔"}],[2664,"ابواسید ساعدی رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے بدر کے دن فرمایا: \"جب وہ (دشمن) تم سے قریب ہو جائیں تب تم انہیں تیروں سے مارنا، اور جب تک وہ تمہیں ڈھانپ نہ لیں ۱؎ تلوار نہ سونتنا\"۔\n§وضاحت\n۱؎ : یعنی تلوار کی مار پر نہ آجائیں۔","ضعیف",{"u2":"سیدنا مالک بن حمزہ ابی اسید الساعدی اپنے والد سے وہ دادا (ابواسید مالک بن ربیعہ انصاری رضی اللہ عنہ) سے روایت کرتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم نے بدر والے دن فرمایا ” جب وہ تمہارے قریب آ جائیں (اور تمہاری زد میں ہوں) تب ان پر تیر مارنا اور تلوار بھی اسی وقت سونتنا جب وہ تم پر چھا جائیں۔ “ (اور تلوار کی مار پر ہوں)۔"}],[2665,"علی رضی اللہ عنہ کہتے ہیں کہ عتبہ بن ربیعہ آگے آیا اور اس کے بعد اس کا بیٹا (ولید) اور اس کا بھائی اس کے پیچھے آئے، پھر عتبہ نے آواز دی: کون میرے مقابلے میں آئے گا؟ تو انصار کے کچھ جوانوں نے اس کا جواب دیا، اس نے پوچھا: تم کون ہو؟ انہوں نے اسے بتایا(کہ ہم انصار کے لوگ ہیں) اس نے (سن کر) کہا: ہمیں تمہاری ضرورت نہیں، ہم اپنے چچا زادوں کو (مقابلہ کے لیے) چاہتے ہیں، تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"حمزہ! تم کھڑے ہو، علی! تم کھڑے ہو، عبیدہ بن حارث! تم کھڑے ہو\"، تو حمزہ رضی اللہ عنہ عتبہ کی طرف بڑھے، اور میں شیبہ کی طرف بڑھا، اور عبیدہ اور ولید (آپس میں بھڑے تو دونوں) کو دو دو زخم لگے، دونوں میں سے ہر ایک نے دوسرے کو نڈھال کر دیا، پھر ہم ولید کی طرف مائل ہوئے اور اسے قتل کر دیا، اور عبیدہ کو اٹھا کر لے آئے۔","صحیح",{"u2":"سیدنا علی رضی اللہ عنہ بیان کرتے ہیں کہ (جنگ بدر میں) عتبہ بن ربیعہ سامنے آیا اور اس کے پیچھے اس کا بیٹا اور بھائی بھی آ گئے تو اس نے للکارا: کون ہے جو مقابلے میں آئے؟ اس پر انصاری جوان سامنے آئے۔ اس نے پوچھا: تم کون ہو؟ تو انہوں نے اس کو بتا دیا (کہ ہم انصاری جوان ہیں) اس نے کہا: ہمیں تم سے کوئی مطلب نہیں۔ ہم اپنے چچا زاد چاہتے ہیں۔ تو نبی کریم صلی اللہ علیہ وسلم نے فرمایا ” اٹھو، اے حمزہ! اٹھو، اے علی! اٹھو، اے عبیدہ بن حارث!) چنانچہ حمزہ رضی اللہ عنہ عتبہ کے مقابل ہوئے اور میں (علی) شیبہ کے سامنے آیا۔ عبیدہ اور ولید کے درمیان دو دو واروں کا مقابلہ ہوا اور ہر ایک کو ایک دوسرے سے چوٹیں لگیں (اور زخمی ہوئے) پھر ہم دونوں ولید پر چڑھ دوڑے اور اس کو قتل کر ڈالا اور عبید کو اٹھا لائے۔","f2":"جنگ میں مقابلے کے لئے للکارنا جائز ہے۔اس سے دشمن پر ہیبت چھا جاتی ہے۔"}],[2666,"عبداللہ بن مسعود رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"لوگوں میں سب سے بہتر قتل کرنے والے صاحب ایمان لوگ ہیں ۱؎\"۔\n§وضاحت\n۱؎ : یعنی وہ قتل اچھے طریقے سے کرتے ہیں زیادتی نہیں کرتے مثلاً مثلہ وغیرہ نہیں کرتے۔","ضعیف",{"u2":"سیدنا عبداللہ بن مسعود رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” قتل کرنے کے معاملے میں سب سے اچھے لوگ اہل ایمان ہوتے ہیں۔ “ (وہ مقتول کے ناک کان وغیرہ نہیں کاٹتے)۔"}],[2667,"ہیاج بن عمران برجمی سے روایت ہے کہ عمران (یعنی: ہیاج کے والد) کا ایک غلام بھاگ گیا تو انہوں نے اللہ کے لیے اپنے اوپر لازم کر لیا کہ اگر وہ اس پر قادر ہوئے تو ضرور بالضرور اس کا ہاتھ کاٹ دیں گے، پھر انہوں نے مجھے اس کے متعلق مسئلہ پوچھنے کے لیے بھیجا، میں نے سمرہ بن جندب رضی اللہ عنہ کے پاس آ کر ان سے پوچھا، تو انہوں نے کہا: نبی اکرم صلی اللہ علیہ وسلم ہمیں صدقہ پر ابھارتے تھے اور مثلہ ۱؎ سے روکتے تھے، پھر میں عمران بن حصین رضی اللہ عنہما کے پاس آیا اور ان سے (بھی) پوچھا: تو انہوں نے (بھی) کہا: رسول اللہ صلی اللہ علیہ وسلم ہمیں صدقہ پر ابھارتے تھے اور مثلہ سے روکتے تھے۔\n§وضاحت\n۱؎ : مقتول کے اعضاء کاٹ کر اس کی شکل و صورت کو بگاڑ دینے کو مثلہ کہا جاتا ہے، مثلہ کا عمل درست نہیں ہے البتہ اگر کسی کافر نے کسی مقتول مسلم کا مثلہ کیا ہے تو اس کے بدلہ میں اس کا مثلہ کیا جا سکتا ہے، جیسا کہ نبی اکرم صلی اللہ علیہ وسلم نے عرینیوں کے ساتھ کیا تھا، اسی طرح اگر کسی مسلمان نے کسی مسلمان کے ساتھ مثلہ کیا ہے تو بطور قصاص اس کے ساتھ بھی ویسا ہی کیا جا سکتا ہے۔","صحیح",{"u2":"سیدنا ہیاج بن عمران سے مروی ہے (کہتے ہیں) کہ (میرے والد) عمران کا ایک غلام بھاگ گیا تو اس نے اللہ کی قسم کھائی کہ اگر وہ میرے ہاتھ آ گیا تو اس کا ہاتھ کاٹ ڈالوں گا۔ پس اس نے مجھے (ہیاج کو) بھیجا کہ یہ مسئلہ پوچھوں۔ تو میں سیدنا سمرہ بن جندب رضی اللہ عنہ کے پاس آیا اور ان سے دریافت کیا، تو انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم ہمیں صدقہ دینے کی ترغیب دیا کرتے تھے اور (مقتول کا) مثلہ کرنے سے منع فرمایا کرتے تھے۔ میں پھر سیدنا عمران بن حصین رضی اللہ عنہ کے پاس آیا اور ان سے بھی دریافت کیا، تو انہوں نے بھی یہی کہا کہ رسول اللہ صلی اللہ علیہ وسلم ہمیں صدقہ دینے کی ترغیب دیا کرتے تھے اور مقتول کا مثلہ کرنے سے منع فرمایا کرتے تھے۔","f2":"مقتول کو قتل کرنے کے بعد اس کے اعضاء کاٹنا یا اس کی شکل بگاڑنا ناجائز ہے۔اورایسے ہی قتل سے پہلے بھی یہ عمل ناجائز ہے۔الایہ کہ قصاص کی کوئی صورت ہو۔جیسے قبیلہ عکل وعرینہ کے لوگوں کے ساتھ کیا گیا تھا۔"}],[2668,"عبداللہ بن عمر رضی اللہ عنہما سے روایت ہے کہ ایک عورت رسول اللہ صلی اللہ علیہ وسلم کے زمانہ میں کسی غزوہ میں مقتول پائی گئی تو رسول اللہ صلی اللہ علیہ وسلم نے عورتوں اور بچوں کے قتل پر نکیر فرمائی۔","صحیح",{"u2":"سیدنا عبداللہ بن عمر رضی اللہ عنہ سے روایت ہے کہ کسی غزوے میں دیکھا گیا کہ ایک عورت کو قتل کیا گیا ہے، تو رسول اللہ صلی اللہ علیہ وسلم نے عورتوں اور بچوں کے قتل کو بہت برا جانا۔"}],[2669,"رباح بن ربیع رضی اللہ عنہ کہتے ہیں کہ ہم ایک غزوہ میں رسول اللہ صلی اللہ علیہ وسلم کے ساتھ تھے، آپ نے دیکھا کہ لوگ کسی چیز کے پاس اکٹھا ہیں تو ایک آدمی کو بھیجا اور فرمایا: \"جاؤ، دیکھو یہ لوگ کس چیز کے پاس اکٹھا ہیں\"، وہ دیکھ کر آیا اور اس نے بتایا کہ لوگ ایک مقتول عورت کے پاس اکٹھا ہیں، آپ صلی اللہ علیہ وسلم نے فرمایا: \"یہ تو ایسی نہیں تھی کہ قتال کرے\" ۱؎، مقدمۃ الجیش (فوج کے اگلے حصہ) پر خالد بن ولید رضی اللہ عنہ مقرر تھے تو آپ صلی اللہ علیہ وسلم نے ایک شخص سے خالد بن ولید رضی اللہ عنہ کے پاس کہلا بھیجا کہ وہ ہرگز کسی عورت کو نہ ماریں اور نہ کسی مزدور کو ۲؎۔\n§وضاحت\n۱؎ : معلوم ہوا کہ عورت اگر لڑائی میں حصہ لیتی ہے اور لڑتی ہے تو اسے قتل کیا جائے گا بصورت دیگر اسے قتل نہیں کیا جائے گا۔ ۲؎ : یہاں مزدور سے مراد وہ مزدور ہے جو لڑتا نہ ہو صرف خدمت کے لئے ہو۔","حسن صحیح",{"u2":"سیدنا رباح بن ربیع بیان کرتے ہیں کہ ہم ایک غزوے میں رسول اللہ صلی اللہ علیہ وسلم کے ساتھ تھے، آپ صلی اللہ علیہ وسلم نے دیکھا کہ لوگ کسی چیز پر اکٹھے ہو رہے ہیں۔ آپ صلی اللہ علیہ وسلم نے ایک آدمی کو بھیجا کہ دیکھ کر آئے وہ کیوں جمع ہیں؟ وہ ہو کر آیا اور بتایا: ایک عورت قتل کی گئی ہے اور وہ اس پر جمع ہیں۔ پس آپ صلی اللہ علیہ وسلم نے فرمایا ” یہ تو لڑنے والی نہ تھی بیان کیا کہ اس فوج کے مقدمہ پر خالد بن ولید تھے۔ آپ صلی اللہ علیہ وسلم نے ایک شخص کو بھیجا کہ خالد سے کہہ دو ” کسی عورت یا کسی مزدور کو ہرگز قتل نہ کریں۔ “","f2":"1۔اگر عورت کا قتال میں کوئی عمل دخل نہ ہو تو اس کا قتل جائز نہیں۔لیکن اگر ثابت ہو کہ وہ کوئی کردار ادا کرتی ہے تو قتل کرنا جائز ہوگا۔ اور یہی حکم گھریلو قسم کے ملازمین اور بوڑھے لوگوں کا ہے۔2۔حدیث میں لفظ مقدمہ مذکور ہے۔لغت میں مقدمہ کسی بھی چیز کے اگلے حصے کو کہتےہیں۔تو یہاں سے اس سے مراد فوج کا ہر اول دستہ ہے جو آگے آگے چلتا ہے۔"}],[2670,"سمرہ بن جندب رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"مشرکین کے بوڑھوں ۱؎ کو (جو لڑنے کے قابل ہوں)قتل کرو، اور کم سنوں کو باقی رکھو\"۔","حسن بصری مدلس ہیں، اور عنعنہ سے روایت کئے ہوئے ہیں",{"u2":"سیدنا سمرہ بن جندب رضی اللہ عنہ روایت کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” مشرکین کے بوڑھوں کو قتل کرو اور نو عمروں (نابالغ بچوں) کو زندہ رہنے دو۔ “","f2":"شیوخ سے ایسے بوڑھے مراد ہیں۔جن کی جوانی ڈھل چکی ہو۔مگر لڑنے پر قادر ہوں۔یا جوانوں کو لڑنے پر ابھارتے ہوں۔"}],[2671,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ بنی قریظہ کی عورتوں میں سے کوئی بھی عورت نہیں قتل کی گئی سوائے ایک عورت کے جو میرے پاس بیٹھ کر اس طرح باتیں کر رہی تھی اور ہنس رہی تھی کہ اس کی پیٹھ اور پیٹ میں بل پڑ جا رہے تھے، اور رسول صلی اللہ علیہ وسلم ان کے مردوں کو تلوار سے قتل کر رہے تھے، یہاں تک کہ ایک پکارنے والے نے اس کا نام لے کر پکارا: فلاں عورت کہاں ہے؟ وہ بولی: میں ہوں، میں نے پوچھا: تجھ کو کیا ہوا کہ تیرا نام پکارا جا رہا ہے، وہ بولی: میں نے ایک نیا کام کیا ہے، عائشہ رضی اللہ عنہا کہتی ہیں: پھر وہ پکارنے والا اس عورت کو لے گیا اور اس کی گردن مار دی گئی، اور میں اس تعجب کو اب تک نہیں بھولی جو مجھے اس کے اس طرح ہنسنے پر ہو رہا تھا کہ اس کی پیٹھ اور پیٹ میں بل پڑ پڑ جا رہے تھے، حالانکہ اس کو معلوم ہو گیا تھا کہ وہ قتل کر دی جائے گی۱؎۔\n§وضاحت\n۱؎ : کہا جاتا ہے کہ اس عورت کا نیا کام یہ تھا کہ اس نے رسول اللہ صلی اللہ علیہ وسلم کو گالیاں دی تھیں، اسی سبب سے اسے قتل کیا گیا۔","حسن",{"u2":"ام المؤمنین سیدہ عائشہ رضی اللہ عنہا ا بیان کرتی ہیں کہ (یہودیوں کے قبیلہ) بنی قریظہ کی عورتوں میں سے صرف ایک عورت کو قتل کیا گیا تھا، وہ میرے پاس بیٹھی باتیں کر رہی تھی اور اتنا ہنستی تھی کہ اس کے پیٹ اور کمر میں بل پڑ جاتے تھے حالانکہ رسول اللہ صلی اللہ علیہ وسلم بازار میں اس کی قوم کے لوگوں کو قتل کیے جا رہے تھے۔ اچانک ایک پکارنے والے نے اس عورت کا نام پکارا کہ فلانی کہاں ہے؟ وہ کہنے لگی: میں ہوں۔ میں نے پوچھا تیرا کیا قصہ ہے؟ کہنے لگی میں نے ایک سازشی کام کیا ہے۔ چنانچہ وہ پکارنے والا اسے لے گیا اور پھر اس کی گردن مار دی گئی۔ سیدہ عائشہ رضی اللہ عنہا ا کہتی ہیں: میں اسے نہیں بھولی ہوں اور اس پر تعجب ہوتا ہے کہ اسے معلوم تھا کہ وہ قتل ہونے والی ہے مگر وہ ہنس ہنس کر لوٹ پوٹ ہو رہی تھی۔","f2":"علامہ خطابی فرماتے ہیں۔کہ اس عورت نے نبی کریم صلی اللہ علیہ وسلم کو گالی دی تھی۔اس وجہ سے اسے قتل کیا گیاتھا۔اور شاتم رسول صلی اللہ علیہ وسلم کی یہی سزا ہے۔"}],[2672,"صعب بن جثامہ رضی اللہ عنہ سے روایت ہے کہ انہوں نے نبی اکرم صلی اللہ علیہ وسلم سے مشرکین کے گھروں کے بارے میں پوچھا کہ اگر ان پر شب خون مارا جائے اور ان کے بچے اور بیوی زخمی ہوں (تو کیا حکم ہے؟)، تو نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"وہ بھی انہیں میں سے ہیں\" اور عمرو بن دینار کہتے تھے: \"وہ اپنے آباء ہی میں سے ہیں\"۔ زہری کہتے ہیں: پھر رسول اللہ صلی اللہ علیہ وسلم نے اس کے بعد عورتوں اور بچوں کے قتل سے منع فرما دیا۔","صحیح"],[2673,"حمزہ اسلمی رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے ان کو ایک سریہ کا امیر بنایا، میں اس سریہ میں نکلا، آپ صلی اللہ علیہ وسلم نے فرمایا: \"اگر فلاں کافر کو پانا تو اسے آگ میں جلا دینا\"، جب میں پیٹھ موڑ کر چلا تو آپ صلی اللہ علیہ وسلم نے مجھے پکارا، میں لوٹا تو آپ صلی اللہ علیہ وسلم نے فرمایا: \"اگر اس کو پانا تو مار ڈالنا، جلانا نہیں، کیونکہ آگ کا عذاب صرف آگ کے رب کو سزاوار ہے ۱؎\"۔\n§وضاحت\n۱؎ : البتہ آگ سے کافروں کے کھیتوں، باغوں اور بستیوں کو جلانا ثابت ہے۔","صحیح",{"u2":"محمد بن حمزہ اسلمی اپنے والد (حمزہ بن عمر اسلمی) سے روایت کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے ان کو ایک دستے کا امیر بنایا تھا۔ کہتے ہیں کہ جب میں روانہ ہوا تو آپ صلی اللہ علیہ وسلم نے فرمایا ” اگر تمہیں فلاں شخص مل جائے تو اس کو آگ سے جلا دینا۔ “ میں نے پیٹھ پھیری تو آپ صلی اللہ علیہ وسلم نے مجھے بلایا میں آپ صلی اللہ علیہ وسلم کے پاس واپس آیا تو آپ صلی اللہ علیہ وسلم نے فرمایا ” اگر تم فلاں کو پاؤ تو اسے قتل کر دینا، جلانا نہیں، بلاشبہ آگ سے عذاب، آگ کا رب ہی دے سکتا ہے۔“"}],[2674,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے ہم کو ایک جنگ میں بھیجا اور فرمایا: \"اگر تم فلاں اور فلاں کو پانا\"، پھر راوی نے اسی مفہوم کی حدیث ذکر کی۔","صحیح",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے ہم کو ایک مہم پر روانہ کیا اور فرمایا ” اگر تم فلاں فلاں کو پاؤ۔ “ اور مذکورہ بالا حدیث کے ہم معنی بیان کیا۔","f2":"کسی قیدی یا مجرم کو آگ سے جلانا ناجائز اور حرام ہے۔ البتہ جنگی مصالح کے پیش نظر قلعوںاور عمارتوں وغیرہ کو جلانے میں کوئی حرج نہیں۔اور یہی حکم گولہ بارود اور بمباری کا ہے۔اوراگراس کی ذد میں کوئی آجائے تو معاف ہے۔"}],[2675,"عبداللہ بن مسعود رضی اللہ عنہ کہتے ہیں کہ ہم رسول اللہ صلی اللہ علیہ وسلم کے ساتھ ایک سفر میں تھے کہ آپ اپنی ضرورت کے لیے گئے، ہم نے ایک چڑیا دیکھی جس کے ساتھ دو بچے تھے، ہم نے ان بچوں کو پکڑ لیا، وہ چڑیا آ کر زمین پر پر بچھانے لگی، اتنے میں نبی اکرم صلی اللہ علیہ وسلم آ گئے، اور (یہ دیکھ کر) فرمایا: \"اس چڑیا کا بچہ لے کر کس نے اسے بے قرار کیا ہے؟ اس کے بچے کو اسے واپس کرو\"، اور آپ نے چیونٹیوں کی ایک بستی کو دیکھا جسے ہم نے جلا دیا تھا تو پوچھا: \"اس کو کس نے جلایا ہے؟\" ہم لوگوں نے کہا: ہم نے، آپ صلی اللہ علیہ وسلم نے فرمایا: \"آگ سے عذاب دینا آگ کے مالک کے سوا کسی کو زیب نہیں دیتا\"۔","صحیح",{"u2":"سیدنا عبدالرحمٰن بن عبداللہ اپنے والد (سیدنا عبداللہ بن مسعود رضی اللہ عنہ) سے روایت کرتے ہیں کہ ایک سفر میں ہم رسول اللہ صلی اللہ علیہ وسلم کے ساتھ تھے۔ آپ صلی اللہ علیہ وسلم قضائے حاجت کے لیے گئے تو ہم نے ایک چڑیا دیکھی، اس کے ساتھ دو بچے بھی تھے، ہم نے اس کے دونوں بچے پکڑ لیے تو چڑیا آئی اور (بچوں کے اوپر اردگرد) منڈلانے لگی۔ نبی کریم صلی اللہ علیہ وسلم تشریف لائے اور فرمایا ” کس نے اس کو اس کے بچوں سے پریشان کیا ہے؟ اس کے بچوں کو چھوڑ دو۔ “ (ایک دوسرے موقع پر) آپ صلی اللہ علیہ وسلم نے دیکھا کہ چیونٹیوں کے بڑے بل کو ہم نے جلا ڈالا ہے؟ آپ صلی اللہ علیہ وسلم نے پوچھا ” اس کو کس نے جلایا ہے؟ “ ہم نے کہا: ہم نے جلایا ہے۔ آپ صلی اللہ علیہ وسلم نے فرمایا ” آگ کے رب کے سوا کسی کو روا نہیں کہ آگ سے عذاب دے۔ “","f2":"انسان تو انسان جانوروں کو بھی خواہ موذی ہی ہوں آگ سے جلاناجائز نہیں۔"}],[2676,"واثلہ بن اسقع رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے غزوہ تبوک کے سلسلہ میں منادی کرائی، میں اپنے اہل کے پاس گیا اور وہاں سے ہو کر آیا تو صحابہ کرام نکل چکے تھے، تو میں شہر میں پکار لگانے لگا کہ کوئی ایسا ہے جو ایک آدمی کو سوار کر لے، اور جو حصہ مال غنیمت سے ملے اسے لے لے، ایک بوڑھے انصاری بولے: اچھا ہم اس کا حصہ لے لیں گے، اور اس کو اپنے ساتھ بٹھا لیں گے، اور ساتھ کھانا کھلائیں گے، میں نے کہا: ہاں قبول ہے، انہوں نے کہا: ٹھیک ہے، اللہ کی برکت پر بھروسہ کر کے چلو، میں بہت ہی اچھے ساتھی کے ساتھ نکلا یہاں تک کہ اللہ نے ہمیں غنیمت کا مال دیا، میرے حصہ میں چند تیز رو اونٹنیاں آئیں، میں ان کو ہنکا کر اپنے ساتھی کے پاس لایا، وہ نکلے اور اپنے اونٹ کے پچھلے حصہ (حقیبہ) پر بیٹھے، پھر کہا: ان کی پیٹھ میری طرف کر کے ہانکو، پھر بولے: ان کا منہ میری طرف کر کے ہانکو، اس کے بعد کہا: تیری اونٹنیاں میرے نزدیک عمدہ ہیں، میں نے کہا: یہ تو آپ کا وہی مال ہے جس کی میں نے شرط رکھی تھی، انہوں نے کہا: میرے بھتیجے! تو اپنی اونٹنیاں لے لے، میرا ارادہ تیرا حصہ لینے کا نہ تھا۔","ضعیف",{"u2":"سیدنا واثلہ بن اسقع رضی اللہ عنہ کا بیان ہے کہ غزوہ تبوک کے موقع پر رسول اللہ صلی اللہ علیہ وسلم نے اعلان جہاد فرمایا تو میں اپنے گھر والوں کے پاس گیا ‘ واپس آیا تو رسول اللہ صلی اللہ علیہ وسلم کے صحابہ کا پہلا قافلہ روانہ ہو چکا تھا۔ میں مدینے میں گومنے لگا اور اعلان کرتا تھا کوئی ہے جو ایک آدمی کو اپنے ساتھ سوار کرا لے اور اس کی غنیمت کا حصہ پائے؟ تو ایک انصاری بوڑھے نے کہا: اس کی غنیمت کا حصہ ہمارا ہو گا اور ہم اسے باری سے اپنے ساتھ سوار کرائیں گے اور وہ کھانا بھی ہمارے ساتھ کھائے گا؟ میں نے کہا: بہت بہتر۔ اس نے کہا: تو چلیے ا اللہ تعالیٰ کی برکت کے ساتھ۔ چنانچہ میں ایک بہترین ساتھی کے ساتھ روانہ ہوا۔ حتیٰ کہ ا اللہ نے ہمیں مال غنیمت سے بہرہ ور فرمایا اور مجھے کچھ اونٹنیاں ملیں ‘ میں انہیں اپنے ساتھی کے پاس ہانک لایا، چنانچہ وہ اپنے اونٹ کے کجاوے پر پچھلے حصے پر بیٹھا اور مجھے کہا: انہیں چلاؤ کہ میں انہیں پیچھے کی طرف سے دیکھوں۔ پھر کہا: انہیں چلاؤ کہ میں انہیں آگے کی طرف سے دیکھوں۔ وہ بولا تمہاری اونٹنیاں بہت عمدہ ہیں۔ میں نے عرض کیا یہ تو آپ کی غنیمت ہیں جس کی میں آپ سے شرط کر چکا ہوں۔ اس نے کہا: بھتیجے! اپنی اونٹنیاں لے جاؤ ‘ ہم نے تیرے دوسرے حصے کا ارادہ کیا ہے۔ (اجر و ثواب میں حصے داری کا۔)","f2":"1۔اگر کوئی ٖغاذی اس طرح کا معاملہ کرے تو جائز ہے۔2۔اس میں صحابہ کرامرضوان اللہ عنہم اجمعین کے اس امتیازی وصف کے ایک نمونے کا ذکر ہے۔جو ان میں عام تھا۔وہ یہ کہ وہ دنیوی منفعت کے مقابلے میں اخروی اجر وثواب کو زیادہ اہمیت دیتے تھے۔"}],[2677,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا: \"ہمارا رب ایسے لوگوں سے خوش ہوتا ہے جو بیڑیوں میں جکڑ کر جنت میں لے جائے جاتے ہیں ۱؎\"۔\n§وضاحت\n۱؎ : مراد وہ لوگ ہیں جو قید ہو کر مسلمانوں کے ہاتھ میں آتے ہیں پھر اللہ انہیں اسلام کی توفیق دیتا ہے اور وہ اسلام قبول کرکے جنت کی راہ پر چل پڑتے ہیں یا وہ مسلمان قیدی مراد ہیں جو کفار کے ہاتھوں قید ہو کر انتقال کر جاتے ہیں پھر اللہ انہیں جنت میں داخل کرتا ہے۔","صحیح",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا ” ہمارے رب عزوجل کو ایسے لوگوں پر تعجب آتا ہے جو زنجیروں میں جکڑے جنت کی طرف لے جائے جائیں گے۔ “","f2":"یعنی کچھ لوگ بحالت کفر قید ہوجاتےہیں۔پھر ہدایت پاکرمسلمان ہوجاتے ہیں۔تو ان شاء اللہ جنت میں جایئں گے۔معلوم ہواکہ قیدی کو باندھ لیناجائز ہے۔اور یہ بھی کہا گیا ہے کہ جو مسلمان کفار کی قید میں وفات پاجایئں یا شہید کردیئے جایئں تو وہ اسی حالت میں اٹھا ئے جایئں گے۔"}],[2678,"جندب بن مکیث رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے عبداللہ بن غالب لیثی رضی اللہ عنہ کو ایک سریہ میں بھیجا، میں بھی انہیں میں تھا، اور آپ صلی اللہ علیہ وسلم نے ان کو حکم دیا کہ بنو الملوح پر کدید میں کئی طرف سے حملہ کریں، چنانچہ ہم لوگ نکلے جب کدید میں پہنچے تو ہم حارث بن برصاء لیثی سے ملے، ہم نے اسے پکڑ لیا، وہ کہنے لگا: میں تو مسلمان ہونے کے لیے آیا ہوں، میں تو رسول اللہ صلی اللہ علیہ وسلم ہی کی طرف جا رہا تھا، ہم نے کہا: اگر تو مسلمان ہے تو ایک دن ایک رات کا ہمارا باندھنا تمہیں نقصان نہیں پہنچائے گا اور اگر تم مسلمان نہیں ہو تو ہم تمہیں مضبوطی سے باندھیں گے، پھر ہم نے اس کو مضبوطی سے باندھ دیا۔","ضعیف",{"u2":"سیدنا جندب بن مکیث رضی اللہ عنہ کا بیان ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے عبداللہ بن غالب لیثی رضی اللہ عنہ کو ایک دستہ دے کر روانہ کیا ‘ میں ان لوگوں میں شامل تھا ‘ آپ صلی اللہ علیہ وسلم نے حکم دیا کہ مقام کدید میں بنی ملوح پر (ہر طرف سے) چڑھائی کرنا۔ چنانچہ ہم روانہ ہوئے حتیٰ کہ مقام کدید پر پہنچ گئے۔ ہم کو حارث بن برصاء لیثی ملا ‘ ہم نے اس کو پکڑ لیا۔ اس نے کہا: میں اسلام قبول کرنا چاہتا ہوں اور میں رسول اللہ صلی اللہ علیہ وسلم کے ہاں جانے کی نیت ہی سے نکلا ہوں۔ ہم نے اس سے کہا: اگر تو فی الواقع مسلمان ہے ‘ تو ہمارا تجھے ایک دن اور رات کے لیے باندھا لینا تیرے لیے کوئی نقصان دہ نہیں ہے۔ اور اگر تو ایسے نہ ہوا تو (تجھے باندھ کر) ہم تیری طرف سے بے فکر ہو جائیں گے۔ چنانچہ ہم نے اس کو رسی سے جکڑ لیا۔"}],[2679,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے کچھ سواروں کو نجد کی جانب بھیجا وہ قبیلہ بنی حنیفہ کے ثمامہ بن اثال نامی آدمی کو گرفتار کر کے لائے، وہ اہل یمامہ کے سردار تھے، ان کو مسجد کے ایک کھمبے سے باندھ دیا، رسول اللہ صلی اللہ علیہ وسلم ان کے پاس گئے اور پوچھا: \"ثمامہ! تمہارے پاس کیا ہے؟\" کہا: اے محمد! میرے پاس خیر ہے، اگر آپ مجھے قتل کریں گے تو ایک مستحق شخص کو قتل کریں گے، اور اگر احسان کریں گے، تو ایک قدرداں پر احسان کریں گے، اور اگر آپ مال چاہتے ہیں تو کہئے جتنا چاہیں گے دیا جائے گا، رسول اللہ صلی اللہ علیہ وسلم انہیں چھوڑ کر واپس آ گئے، یہاں تک کہ جب دوسرا دن ہوا تو پھر آپ صلی اللہ علیہ وسلم نے ان سے پوچھا: \"ثمامہ تمہارے پاس کیا ہے؟\" تو انہوں نے پھر اپنی وہی بات دہرائی، آپ صلی اللہ علیہ وسلم نے پھر انہیں یوں ہی چھوڑ دیا، پھر جب تیسرا دن ہوا تو پھر وہی بات ہوئی، پھر رسول اللہ صلی اللہ علیہ وسلم نے حکم دیا کہ ثمامہ کو آزاد کر دو، چنانچہ وہ مسجد کے قریب ایک باغ میں گئے، غسل کیا، پھر مسجد میں داخل ہوئے اور «أشهد أن لا إله إلا الله وأشهد أن محمدًا عبده ورسوله» پڑھ کر اسلام میں داخل ہو گئے، پھر راوی نے پوری حدیث بیان کیا۔ عیسی کہتے ہیں: مجھ سے لیث نے «ذَاْ دَمٍ» کے بجائے «ذَا ذِمٍّ» (یعنی ایک عزت دار کو قتل کرو گے) روایت کی ہے۔","صحیح",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے نجد کی طرف ایک جہادی دستہ روانہ فرمایا۔ وہ قبیلہ بنو حنیفہ کا ایک آدمی پکڑ لائے جس کا نام ثمامہ بن اثال تھا اور وہ اہل یمامہ کا سردار تھا۔ چنانچہ انہوں نے اسے مسجد کے ایک ستون کے ساتھ باندھ دیا تو رسول اللہ صلی اللہ علیہ وسلم اس کے پاس آئے اور پوچھا ثمامہ! تیرے پاس کیا ہے؟ (یا تیرا کیا خیال ہے؟) اس نے کہا: اے محمد! میرے پاس خیر ہے۔ اگر تم نے قتل کیا تو ایک خون والے کو قتل کرو گے۔ اور اگر احسان کرو گے تو ایک شکر گزار پر احسان کرو گے۔ اگر آپ کو مال کی ضرورت ہو تو کہیے جتنا چاہتے ہو ملے گا۔ رسول اللہ صلی اللہ علیہ وسلم نے اسے اسی حال پر رہنے دیا۔ اگلا دن ہوا تو آپ صلی اللہ علیہ وسلم نے اس سے پھر پوچھا: ثمامہ! تیرے پاس کیا ہے؟ (یا تیرا کیا خیال ہے؟) تو اس نے پہلے جیسی بات دہرائی۔ پس رسول اللہ صلی اللہ علیہ وسلم نے اسے اسی حال پر رہنے دیا۔ حتیٰ کہ اگلا دن ہوا تو بھی یہ مکالمہ ہوا۔ تب رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” ثمامہ کو آزاد کر دو۔ “ چنانچہ وہ چلا گیا اور مسجد کے قریب نخلستان میں پہنچا ‘ وہاں جا کر غسل کیا اور پھر مسجد میں واپس آ گیا اور کہنے لگا «أشهد أن لا إله إلا الله وأشهد أن محمدا عبده ورسوله» ” میں گواہی دیتا ہوں کہ ایک ا اللہ کے سوا کوئی معبود نہیں اور گواہی دیتا ہوں کہ محمد صلی اللہ علیہ وسلم اس کے بندے اور رسول ہیں “ اور دونوں نے پوری حدیث بیان کی۔ عیسی بن حماد نے کہا ہم کو لیث بن سعد نے خبر دی تو اس میں «إن تقتل تقتل ذا دم» کی بجائے «ذا ذم» کے لفظ بیان کیے۔ (اگر قتل کیا تو) ایک صاحب ذمہ اور احترام والے کو قتل کرو گے ‘ (مفہوم دونوں کا یہ ہے کہ میری قوم بدلہ لے گی)۔","f2":"1۔مصلحت کے تحت کافر کومسجد میں آنے یا باندھنے کی رخصت ہے۔2۔رسول اللہ صلی اللہ علیہ وسلم اور مسلمانوں کے حسن عبادات اور حسن عادات نے ایک جنگی قیدی کو بلاجبرواکراہ اسلام کا قیدی بنا لیا۔اور یہ دلیل ہے کہ اسلام تلوار کے زورسے نہیں پھیلاہے۔"}],[2680,"یحیی بن عبداللہ بن عبدالرحمٰن بن سعد بن زرارہ رضی اللہ عنہ کہتے ہیں کہ قیدیوں کو لایا گیا جس وقت انہیں لایا گیا، اور سودہ بنت زمعہ(ام المؤمنین رضی اللہ عنہا) آل عفراء یعنی عوف بن عفراء اور معوذ بن عفراء کے پاس اس جگہ تھیں جہاں ان کے اونٹ بٹھائے جاتے تھے، اور یہ معاملہ پردہ کا حکم اترنے سے پہلے کا ہے، سودہ رضی اللہ عنہا کہتی ہیں: قسم اللہ کی! میں انہیں کے پاس تھی، یکایک آئی تو کہا گیا یہ قیدی ہیں پکڑ کر لائے گئے ہیں، تو میں اپنے گھر واپس آئی اور رسول اللہ صلی اللہ علیہ وسلم گھر میں تھے اور ابویزید سہیل بن عمرو حجرے کے ایک کونے میں تھا، اس کے دونوں ہاتھ اس کی گردن سے ایک رسی سے بندھے ہوئے تھے، پھر راوی نے پوری حدیث بیان کی۔ ابوداؤد کہتے ہیں: انہیں دونوں (عوف و معوذ) نے ابوجہل بن ہشام کو قتل کیا، اور یہی دونوں اس کے آگے آئے حالانکہ اسے پہچانتے نہ تھے، یہ دونوں بدر کے دن مارے گئے۔","ضعیف",{"u2":"سیدنا یحییٰ بن عبداللہ بن عبدالرحمٰن بن سعد بن زرارہ سے روایت ہے کہ بدر کے قیدیوں کو جب لایا گیا تو ام المؤمنین سودہ بنت زمعہ رضی اللہ عنہا ا آل عفراء کے پاس یعنی عفراء کے صاحبزادوں عوف اور معوذ کے ہاں ٹھہری ہوئی تھیں ‘ جہاں کہ ان کے اونٹوں کا باڑا تھا۔ اور یہ امہات المؤمنین پر پردہ فرض ہونے سے پہلے کا واقعہ ہے۔ سودہ رضی اللہ عنہا بیان کرتی ہیں: ا اللہ کی قسم! میں ان لوگوں (آل عفراء) کے ہاں تھی جب میں (وہاں سے) آئی تو مجھے بتایا گیا کہ قیدی لائے گئے ہیں۔ میں اپنے گھر لوٹی ‘ تو رسول اللہ صلی اللہ علیہ وسلم وہاں تشریف فر تھے اور ابویزید سہیل بن عمرو بھی حجرے کے کونے میں پڑا تھا۔ ایک رسی سے اس کے ہاتھوں کو اس کی گردن کے ساتھ باندھ دیا گیا تھا۔ پھر باقی حدیث بیان کی۔ امام ابوداؤد رضی اللہ عنہ فرماتے ہیں کہ ان دونوں نے (عوف اور معوذ نے) ابوجہل بن ہشام کو قتل کیا تھا۔ یہ اس کی طرف بڑھے تھے مگر پہچانتے نہ تھے اور خود بدر کے روز شہید ہو گئے تھے۔","f2":"ابو جہل کے قتل میں عفراء کے دو صاحبزادوں معاذ اور معوذ کے علاوہ معاذ بن عمرو بن جموح اورعبد اللہ بن مسعود رضی اللہ تعالیٰ عنہ بھی شریک تھے۔امام ابو دائود اورابن سعد نے عوف بن عفراء کا نام بھی شامل کیاہے۔ حافظ ابن حجر نے ان روایات میں جمع وتطبیق دیتے ہوئے لکھا ہے۔ کہ معاذ بن عمرو بن جموح اور معاذ بن عفراء نے پہلے مل کر حملہ کیا پھر معو ذ بن عفراء نے بھی اس کو گھائل کیا۔اورآخر میں عبد اللہ بن مسعود رضی اللہ تعالیٰ عنہ نے اس کا سر قلم کیا۔(فتح الباری کتاب المغاذی۔باب قتل ابی جہل حدیث3964۔والرحیق المختوم)حضرت عبد اللہ بن مسعود رضی اللہ تعالیٰ عنہ کا تذکرہ حدیث 2709 میں آرہا ہے۔"}],[2681,"انس رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے صحابہ کرام کو بلایا، وہ سب بدر کی طرف چلے، اچانک قریش کے پانی والے اونٹ ملے ان میں بنی حجاج کا ایک کالا کلوٹا غلام تھا، صحابہ کرام نے اسے پکڑ لیا اور اس سے پوچھنے لگے کہ بتاؤ ابوسفیان کہاں ہے؟ وہ کہنے لگا: اللہ کی قسم! مجھے ابوسفیان کے سلسلہ میں کوئی علم نہیں، البتہ قریش کے لوگ آئے ہیں ان میں ابوجہل، عتبہ بن ربیعہ، شیبہ بن ربیعہ اور امیہ بن خلف بھی آئے ہوئے ہیں، جب اس نے یہ کہا تو صحابہ کرام اسے مارنے لگے، وہ بولا: مجھے چھوڑ دو، مجھے چھوڑ دو، میں تمہیں بتاتا ہوں، جب اس کو چھوڑا تو پھر وہ یہی بات کہنے لگا: اللہ کی قسم مجھے ابوسفیان کے سلسلہ میں کوئی علم نہیں البتہ قریش آئے ہیں ان میں ابوجہل، ربیعہ کے دونوں بیٹے عتبہ و شیبہ اور امیہ بن خلف بھی آئے ہوئے ہیں، (اس وقت) نبی اکرم صلی اللہ علیہ وسلم نماز پڑھ رہے تھے اور اسے سن رہے تھے، جب نماز سے فارغ ہوئے تو فرمایا: \"قسم ہے اس ذات کی جس کے ہاتھ میں میری جان ہے! جب وہ تم سے سچ کہتا ہے تو تم اسے مارتے ہو اور جب جھوٹ بولتا ہے تو چھوڑ دیتے ہو، (ابوسفیان تو شام کے قافلہ کے ساتھ مال لیے ہوئے آ رہا ہے) اور یہ قریش کے لوگ ہیں اس کو بچانے کے لیے آئے ہیں\"۔ انس رضی اللہ عنہ کہتے ہیں: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"کل یہاں فلاں کی لاش گرے گی\"، اور آپ صلی اللہ علیہ وسلم نے اپنا ہاتھ زمین پر رکھا، \"کل یہ فلاں کا مقتل ہو گا\" اور آپ صلی اللہ علیہ وسلم نے اپنا ہاتھ زمین پر رکھا، \"اور کل یہ فلاں کا مقتل ہو گا\" اور آپ صلی اللہ علیہ وسلم نے اپنا ہاتھ زمین پر رکھا۱؎۔ انس رضی اللہ عنہ کہتے ہیں: اس ذات کی قسم جس کے ہاتھ میں میری جان ہے! نبی اکرم صلی اللہ علیہ وسلم کے ہاتھ کی جگہ سے کوئی بھی آگے نہیں بڑھ سکا، پھر آپ صلی اللہ علیہ وسلم نے ان کے سلسلہ میں حکم دیا تو ان کے پاؤں پکڑ کر گھسیٹتے ہوئے انہیں بدر کے کنوئیں میں ڈال دیا گیا۔\n§وضاحت\n۱؎ : یہ رسول اکرم صلی اللہ علیہ وسلم کا معجزہ تھا، آپ نے پہلے ہی بتا دیا کہ یہاں فلاں مارا جائے گا، اور یہاں فلاں۔","صحیح",{"u2":"سیدنا انس رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے اپنے اصحاب کو بلایا اور پھر بدر کی طرف روانہ ہوئے۔ تو اچانک انہیں قریش کے اونٹ ملے جن پر وہ پانی ڈھوتے تھے، ان میں بنی حجاج کا کالے رنگ کا ایک غلام بھی تھا ‘ صحابہ نے اس کو پکڑ لیا اور اس سے تفتیش کرنے لگے کہ ابوسفیان کہاں ہے؟ اس نے کہا: ا اللہ کی قسم! مجھے اس کے معاملے کی کوئی خبر نہیں ‘ لیکن یہ اہل قریش آئے ہیں ‘ ان میں ابوجہل ‘ ربیعہ کے دونوں بیٹے عتبہ و شیبہ اور امیہ بن خلف بھی ہیں۔ جب وہ صحابہ کو یہ بات کہتا ‘ تو وہ اسے مارنے لگتے۔ پس وہ کہتا: مجھے چھوڑو، مجھے چھوڑو ‘ بتاتا ہوں۔ جب اسے چھوڑ دیتے ‘ تو کہتا: ا اللہ کی قسم! مجھے ابوسفیان کا کوئی علم نہیں ‘ لیکن یہ اہل قریش آئے ہیں ‘ ان میں ابوجہل ‘ ربیعہ کے دونوں بیٹے عتبہ و شیبہ اور امیہ بن خلف بھی ہیں۔ نبی کریم صلی اللہ علیہ وسلم نماز پڑھ رہے تھے اور یہ سب سن رہے تھے۔ جب آپ صلی اللہ علیہ وسلم نماز سے فارغ ہوئے تو فرمایا ” قسم اس ذات کی جس کے ہاتھ میں میری جان ہے! جب وہ تمہیں سچ کہتا ہے ‘ تو تم مارنے لگتے ہو اور جب جھوٹ بولتا ہے ‘ تو اسے چھوڑ دیتے ہو ‘ یہ قریش کے لوگ ابوسفیان ہی کو بچانے کے لیے آئے ہیں۔ “ سیدنا انس رضی اللہ عنہ نے بیان کیا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” کل یہ جگہ فلاں کا مقتل ہو گی۔ “ اور آپ صلی اللہ علیہ وسلم نے اپنا ہاتھ زمین پر رکھا۔ “ کل یہ جگہ فلاں کا مقتل ہو گی۔ “ اور آپ صلی اللہ علیہ وسلم نے اپنا ہاتھ زمین پر رکھا۔ “ کل یہ جگہ فلاں کا مقتل ہو گی۔ “ اور آپ صلی اللہ علیہ وسلم نے اپنا ہاتھ زمین پر رکھا۔ انس کہتے ہیں: قسم اس ذات کی جس کے ہاتھ میں میری جان ہے! ان نامزد لوگوں میں سے کوئی ایک بھی رسول اللہ صلی اللہ علیہ وسلم کے ہاتھ کی جگہ سے ادھر ادھر نہ ہوا۔ سو رسول اللہ صلی اللہ علیہ وسلم نے ان مقتولوں کے متعلق حکم دیا تو انہیں ٹانگوں سے پکڑ پکڑ اور گھسیٹ گھسیٹ کر بدر کے کنویں میں ڈال دیا گیا۔","f2":"1۔احوال مصالح کے پیش نظر قیدی کو مارنا پیٹنا اور اس طرح سے حقائق اگلوانا ایک مطلب اور جائز امر ہے۔2۔یہ حدیث اس بات پر بھی دلالت کرتی ہے۔کہ رسول اللہ صلی اللہ علیہ وسلم بسا اوقات کچھ خبریں وقوع پزیر ہونے سے پہلے ہی دے دیا کرتے تھے۔اور آپ صلی اللہ علیہ وسلم کو بزریعہ وحی اللہ تعالیٰ کی طرف سے ان امور کی اطلاع دی جاتی تھی۔قرآن مقدس میں ہے۔\n(وَمَا يَنطِقُ عَنِ الْهَوَىٰ ﴿٣﴾ إِنْ هُوَ إِلَّا وَحْيٌ يُوحَىٰ)(النجم۔3۔4)3۔اس حدیث میں حربی کافروں کے مقتولوں کا عدم احترام بھی ثابت ہوتا ہے۔واللہ اعلم"}],[2682,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ (کفر کے زمانہ میں) کوئی عورت ایسی ہوتی جس کا بچہ نہ جیتا (زندہ نہ رہتا) تو وہ نذر مانتی کہ اگر اس کا بچہ جئیے (زندہ رہے گا) گا تو وہ اس کو یہودی بنائے گی، جب بنی نضیر کو جلا وطن کرنے کا حکم ہوا تو ان میں چند لڑکے انصار کے بھی تھے، انصار نے کہا: ہم اپنے لڑکوں کو نہ چھوڑیں گے تو اللہ نے یہ آیت کریمہ نازل فرمائی «لا إكراه في الدين قد تبين الرشد من الغى» (سورۃ البقرہ: ۲۵۶) \"دین میں زبردستی نہیں ہدایت گمراہی سے واضح ہو چکی ہے\"۔ ابوداؤد کہتے ہیں: «مقلات» : اس عورت کو کہتے ہیں جس کا کوئی بچہ نہ جیتا ہو۔","صحیح",{"u2":"سیدنا ابن عباس رضی اللہ عنہ سے مروی ہے انہوں نے کہا کہ جب کوئی عورت ایسی ہوتی کہ اس کے بچے زندہ نہ رہتے ‘ تو وہ نذر مان لیا کرتی تھی کہ اگر اس کا بچہ زندہ رہا تو وہ اسے یہودی بنا ڈالے گی۔ سو جب بنو نضیر کو مدینے سے جلا وطن کیا گیا تو ان میں انصاریوں کے لڑکے بھی تھے۔ (جو اس قسم کی نذر کے تحت یہودی بنائے گئے تھے) انہوں نے کہا: ہم اپنے بچوں کو نہیں چھوڑیں گے (ان کے ساتھ نہیں جانے دیں گے) تو ا اللہ تعالیٰ نے یہ آیت نازل فرمائی «لا إكراه في الدين قد تبين الرشد من الغي» ” دین میں کوئی جبر و اکراہ نہیں۔ ہدایت ‘ گمراہی کے مقابلے میں واضح اور نمایاں ہو چکی ہے۔ “ امام ابوداؤد رضی اللہ عنہ فرماتے ہیں «المقلاة» وہ عورت ہوتی ہے جس کے بچے زندہ نہ رہتے ہوں۔","f2":"اسلام قبول کرنے کے سلسلے میں جبر واکراہ کے کوئی معنی نہیں ہیں۔جہاد کا حکم اور عمل اشاعت اسلام کی راہ میں حائل رکاوٹوں کو دور کرنے کےلئے ہے نہ کہ لوگوں کو اسلام پر مجبور کرنے کےلئے۔"}],[2683,"سعد رضی اللہ عنہ کہتے ہیں کہ جب مکہ فتح ہوا تو رسول اللہ صلی اللہ علیہ وسلم نے چار مردوں اور دو عورتوں کے سوا سب کو امان دے دی، انہوں نے ان کا اور ابن ابی السرح کا نام لیا، رہا ابن ابی سرح تو وہ عثمان بن عفان رضی اللہ عنہ کے پاس چھپ گیا، پھر رسول اللہ صلی اللہ علیہ وسلم نے جب لوگوں کو بیعت کے لیے بلایا تو عثمان نے اسے رسول اللہ صلی اللہ علیہ وسلم کے سامنے لا کھڑا کیا، اور کہا: اللہ کے نبی! عبداللہ سے بیعت لیجئے، آپ صلی اللہ علیہ وسلم نے اپنا سر اٹھایا اور اس کی جانب دیکھا، تین بار ایسا ہی کیا، ہر بار آپ انکار کرتے رہے، تین بار کے بعد پھر اس سے بیعت لے لی، پھر صحابہ کی طرف متوجہ ہوئے اور فرمایا: \"کیا تم میں کوئی بھی عقلمند آدمی نہیں تھا کہ جس وقت میں نے اپنا ہاتھ اس کی بیعت سے روک رکھا تھا، اٹھتا اور اسے قتل کر دیتا؟\" لوگوں نے عرض کیا: اللہ کے رسول! ہمیں آپ کے دل کا حال نہیں معلوم تھا، آپ نے ہمیں آنکھ سے اشارہ کیوں نہیں کر دیا؟ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"کسی نبی کے لیے یہ مناسب نہیں کہ وہ کنکھیوں سے اشارے کرے\"۔ ابوداؤد کہتے ہیں: عبداللہ عثمان کا رضاعی بھائی تھا اور ولید بن عقبہ عثمان کا اخیافی بھائی تھا، اس نے شراب پی تو عثمان رضی اللہ عنہ نے اس پر حد لگائی۔","صحیح",{"u2":"سیدنا سعد بن ابی وقاص رضی اللہ عنہ کا بیان ہے کہ فتح مکہ کے موقع پر رسول اللہ صلی اللہ علیہ وسلم نے چار مردوں اور دو عورتوں کے سوا تمام لوگوں کو امان دے دی تھی۔ راوی نے ان کے نام گنوائے۔ اور ابن ابی سرح بھی تھے۔ اور حدیث بیان کی۔ ابن ابی سرح سیدنا عثمان بن عفان رضی اللہ عنہ کے ہاں چھپ گئے تھے۔ رسول اللہ صلی اللہ علیہ وسلم نے جب لوگوں کو بیعت کے لیے بلایا ‘ تو عثمان رضی اللہ عنہ ان (ابن ابی سرح) کو لے آئے اور رسول اللہ صلی اللہ علیہ وسلم کے پاس کھڑا کر دیا اور عرض کیا: اے ا اللہ کے نبی! عبداللہ کی بیعت قبول فر لیجئیے۔ آپ صلی اللہ علیہ وسلم نے اپنا سر اٹھایا ‘ ان کی طرف دیکھا ‘ تین بار اس طرح ہوا ‘ آپ صلی اللہ علیہ وسلم نے ہر بار اس کا انکار فرمایا۔ تیسری بار کے بعد آپ صلی اللہ علیہ وسلم نے ان سے بیعت فر لی۔ پھر اپنے صحابہ کی طرف متوجہ ہوئے اور فرمایا ” تم میں کوئی سمجھدار آدمی نہ تھا ‘ جو اس کی طرف اٹھتا ‘ جب دیکھا کہ میں نے اس کی بیعت سے ہاتھ کھینچ لیا ہے تو اس کو قتل کر دیتا؟ “ انہوں نے کہا: اے ا اللہ کے رسول! ہمیں معلوم نہ تھا کہ آپ کے جی میں کیا ہے؟ آپ صلی اللہ علیہ وسلم اپنی آنکھ سے ہمیں اشارہ فر دیتے۔ آپ صلی اللہ علیہ وسلم نے فرمایا ” نبی کو لائق نہیں کہ اس کی آنکھ خائن ہو۔ “ امام ابوداؤد رضی اللہ عنہ فرماتے ہیں عبداللہ (عبداللہ بن ابی سرح) سیدنا عثمان رضی اللہ عنہ کے رضائی بھائی تھے۔ اور ولید بن عقبہ سیدنا عثمان رضی اللہ عنہ کے ماں کی طرف سے بھائی تھے۔ انہوں نے جب شراب پی تھی تو سیدنا عثمان رضی اللہ عنہ نے ان کو حد لگائی تھی۔","f2":"1۔چونکہ یہ لوگ جنگی مجرم تھے۔اور اسلام ہی کی شہرت ہی ان کے لئے اسلام کی دعوت تھی۔اس لئے ان کے بارے میں حکم تھا۔کہ جہاں ملیں ان کو قتل کردیا جائے۔خواہ کعبہ کے پردوں کے ساتھ ہی کیوں نہ چمٹے ہوئے ہوں۔اور یہ کئی افراد تھے۔عکرمہ بن ابی جہل۔عبد اللہ بن خطل۔مقیس بن صبابہ۔عبد اللہ بن سعد بن ابی سرح۔(ان کے علاوہ اور بھی کئی لوگ تھے) اور عورتوں میں ابن خطل۔ یا مقیس بن صبابہ کی لونڈیاں قریبہ اور فرتنی۔(علاوہ ازیں اور بھی عورتوں کے نام آتے ہیں)عبد اللہ بن خطل کو کعبہ کے پردوں کے ساتھ چمٹا ہوا پایاگیا۔ اور وہیں قتل کردیا گیا۔مقیس بن صبابہ کو لوگوں نے بازار میں جالیا۔اورقتل ہوا۔اور عکرمہ بھاگ کرکشتی میں سوار ہوگئے۔ اورقتل ہونے سے بچ گئے۔ پھر بعد میں حاضر خدمت ہوئے اور اسلام لے آئے۔جوقبول کرلیاگیا۔اوربڑے مخلص مسلمان ثابت ہوئے۔عبد اللہ بن ابی سرح کے متعلق آتا ہے۔ یہ یہ ابتداء میں ر سول اللہ صلی اللہ علیہ وسلم کے کاتب تھے۔ مگر مرتد ہوگئے۔ان پر شدت اور سختی کی وجہ یہی تھی۔بعد میں انہوں نے بھی دوبارہ اسلام قبول کرلیا گیا تھا۔عورتوں میں یہ لونڈیاں رسول اللہ صلی اللہ علیہ وسلم کی ہجو کیا (مذمت میں شعرپڑھا) کرتی تھیں۔قریبہ قتل کی گئی۔جب کہ فرتنی بھاگ نکلی اور بعدمیں اسلام قبول کیا۔2۔آنکھ سے چھپا اشارہ کرنا آنکھ کی خیانت مجرمانہ ہے۔ جو نبی کے کئے خصوصاً اور مومن کے لئے عموما درست نہیں۔(نیزدیکھئے سنن ابی دائود الجنائز حدیث 3194)"}],[2684,"سعید بن یربوع مخزومی رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فتح مکہ کے دن فرمایا: \"چار آدمیوں کو میں حرم اور حرم سے باہر کہیں بھی امان نہیں دیتا\"، پھر آپ صلی اللہ علیہ وسلم نے ان کے نام لیے، اور مقیس کی دو لونڈیوں کو، ایک ان میں سے قتل کی گئی، دوسری بھاگ گئی پھر وہ مسلمان ہو گئی۔","ضعیف",{"u2":"عمرو بن عثمان بن عبدالرحمٰن اپنے دادا سے، وہ اپنے والد سے (سعید بن بربوع مخزومی رضی اللہ عنہ سے) روایت کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فتح مکہ کے دن فرمایا تھا ” چار اشخاص کو میں حل یا حرم میں (حدود حرم میں یا اس سے باہر کہیں بھی) پناہ نہیں دیتا۔ “ چنانچہ ان کے نام گنوائے۔ اور دو لونڈیاں تھیں جو گانے بجانے کا کام کرتی تھیں اور مقیس کی ملکیت تھیں ایک کو قتل کر دیا گیا اور دوسری بھاگ نکلی اور بعد میں اسلام لے آئی۔ امام ابوداؤد رضی اللہ عنہ نے کہا: میں اس حدیث کی سند (اپنے شیخ) محمد بن علاء سے کماحقہ نہیں سمجھ سکا تھا۔"}],[2685,"انس بن مالک رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم مکہ میں فتح مکہ کے سال داخل ہوئے، آپ کے سر پر خود تھا، جب آپ صلی اللہ علیہ وسلم نے خود اتارا تو ایک شخص آیا اور کہنے لگا: ابن خطل کعبہ کے غلاف سے چمٹا ہوا ہے، آپ صلی اللہ علیہ وسلم نے فرمایا: \"اس کو قتل کر دو\" ۱؎۔ ابوداؤد کہتے ہیں: ابن خطل کا نام عبداللہ تھا اور اسے ابوبرزہ اسلمی نے قتل کیا۔\n§وضاحت\n۱؎ : رسول اللہ صلی اللہ علیہ وسلم نے ابن خطل کو ایک انصاری کے ساتھ کسی جہت میں زکاۃ وصول کرنے کے لئے بھیجا، انصاری کو اس وفد کا امیر بنایا، راستہ میں ابن خطل نے انصاری پر حملہ کرکے اسے قتل کردیا اور سارا مال و متاع لے کر فرار ہو گیا اور اسلام سے پھر گیا، اسی لئے رسول اللہ صلی اللہ علیہ وسلم نے اسے امان نہیں دی اور خون ناحق کا بدلہ لینے کے لئے اس کے قتل کا حکم صادر فرمایا۔","صحیح",{"u2":"سیدنا انس بن مالک رضی اللہ عنہ سے روایت ہے کہ فتح مکہ کے موقع پر رسول اللہ صلی اللہ علیہ وسلم مکہ میں داخل ہوئے ‘ تو آپ صلی اللہ علیہ وسلم کے سر پر خود تھی۔ جب آپ صلی اللہ علیہ وسلم نے اسے اتارا تو آپ صلی اللہ علیہ وسلم کے پاس ایک آدمی آیا اور بتایا کہ ابن خطل کعبہ کے پردوں کے ساتھ چمٹا ہوا ہے۔ آپ صلی اللہ علیہ وسلم نے فرمایا ” اس کو قتل کر ڈالو۔ “ امام ابوداؤد رضی اللہ عنہ فرماتے ہیں کہ ابن خطل کا نام عبداللہ تھا اور سیدنا ابوبرزہ اسلمی رضی اللہ عنہ نے اس کو قتل کیا تھا۔","f2":"1۔رسول اللہ صلی اللہ علیہ وسلم کا خود پہنے مکہ میں داخل ہونا دلیل ہے کہ حج عمرے کے علاوہ حسب احوال انسان بغیر حرام کے مکہ میں داخل ہوسکتاہے۔2۔ابن خطل پہلے مسلمان ہوگیا تھا۔ اس کو رسول اللہ صلی اللہ علیہ وسلم نے کسی کام سے بھیجا اور ایک انصاری کو بطور خادم اس کے ساتھ روانہ کیا۔اس سے کوئی تقصیر (غلطی) ہوئی تو اس نے اس انصاری کو قتل کرڈالا۔اور اس کا مال لوٹ لیا اور مرتد ہوگیا۔ سو اسی وجہ سے اس کو رسول اللہ صلی اللہ علیہ وسلم نے امان نہ دی۔اورقتل کرنے کا حکم دیا۔"}],[2686,"ابراہیم کہتے ہیں کہ ضحاک بن قیس نے مسروق کو عامل بنانا چاہا تو عمارہ بن عقبہ نے ان سے کہا: کیا آپ عثمان رضی اللہ عنہ کے قاتلوں میں سے ایک شخص کو عامل بنا رہے ہیں؟ تو مسروق نے ان سے کہا: مجھ سے عبداللہ بن مسعود رضی اللہ عنہ نے حدیث بیان کی اور وہ ہم میں حدیث (بیان کرنے) میں قابل اعتماد تھے کہ جب نبی اکرم صلی اللہ علیہ وسلم نے تیرے باپ (عقبہ ۱؎) کے قتل کا ارادہ کیا تو وہ کہنے لگا: میرے لڑکوں کی خبرگیری کون کرے گا؟ تو آپ صلی اللہ علیہ وسلم نے فرمایا: \"آگ ۲؎ پس میں تیرے لیے اسی چیز سے راضی ہوں جس چیز سے رسول اللہ صلی اللہ علیہ وسلم راضی ہوئے\"۔\n§وضاحت\n۱؎ : عقبہ بن ابی معیط یہی وہ بدقماش شخص ہے جس نے رسول اللہ صلی اللہ علیہ وسلم کے سر پر نماز کی حالت میں اوجھڑی ڈالی تھی۔ ۲؎ : رسول اللہ صلی اللہ علیہ وسلم نے عقبہ بن ابی معیط کے جواب میں ’’ آگ ‘‘ کہا، علماء اس کی دو وجہیں بیان کرتے ہیں : ۱- یہ بطور استہزاء ہے اور اشارہ ہے اس کی اولاد کے ضائع ہونے کی طرف۔ ۲- یا مفہوم ہے «لك النار» یعنی تیرے لئے آگ ہے، رہا بچوں کا معاملہ تو ان کا محافظ اللہ ہے۔","حسن صحیح",{"u2":"جناب ابراہیم نخعی رضی اللہ عنہ نے کہا ضحاک بن قیس نے ارادہ کیا کہ مسروق کو عامل بنائے۔ تو عمارہ بن عقبہ نے کہا: کیا تم ایسے آدمی کو عامل بنانا چاہتے ہو جو عثمان رضی اللہ عنہ کے قاتلوں میں سے باقی رہ گیا ہے؟ تو مسروق نے اس سے کہا: ہمیں سیدنا عبداللہ بن مسعود رضی اللہ عنہ نے بیان کیا اور وہ ہمارے نزدیک حدیث بیان کرنے میں معتبر تھے کہ نبی کریم صلی اللہ علیہ وسلم نے، جب تیرے باپ (عقبہ بن ابی معیط) کو قتل کرنے کا ارادہ کیا تو اس (عقبہ) نے کہا: میرے بچوں کا کفیل کون ہو گا؟ آپ نے فرمایا ” آگ “ سو میں بھی تیرے لیے وہی چیز پسند کرتا ہوں جسے تیرے لیے رسول اللہ صلی اللہ علیہ وسلم نے پسند کیا تھا۔","f2":"1۔عقبہ بن ابی معیط بڑا بدبخت انسان تھا۔ رسول اللہ صلی اللہ علیہ وسلم کی عداوت میں بہت بڑھ گیا تھا اور اسی نے رسول اللہ صلی اللہ علیہ وسلم پر دوران نماز میں اونٹ کی اوجھ ڈالی تھی۔اسے بدر سے واپسی پر راستے میں قتل کیا گیا۔اسے باندھ کر قتل کیا گیا تھا۔جیسا کہ فتح الباری میں صراحت ہے۔اور یہی بات اس باب میں محل استشہاد ہے۔(عون المعبود) اس کے ساتھ دو اور بھی تھے۔طعیمہ بن عدی۔اور نضر بن حارث۔2۔مجرم یا قیدی کو قتل کرنا ہو تو اس کا دورسے نشانہ لینے کی بجائے تلوار سے سر قلم کردیا جائے یا پھانسی دے دی جائے۔"}],[2687,"ابن تعلی کہتے ہیں کہ ہم نے عبدالرحمٰن بن خالد بن ولید کے ساتھ جہاد کیا تو ان کے سامنے عجمی کافروں میں سے چار طاقتور اور ہٹے کٹے کافر لائے گئے انہوں نے ان کے متعلق حکم دیا تو وہ باندھ کر قتل کر دیئے گئے۔ ابوداؤد کہتے ہیں: ہم سے سعید بن منصور کے سوا اور لوگوں نے ابن وہب سے یہی حدیث یوں روایت کی ہے کہ پکڑ کر نشانہ بنا کر تیروں سے مار ڈالے گئے، تو یہ خبر ابوایوب انصاری رضی اللہ عنہ کو پہنچی تو انہوں نے کہا: میں نے رسول اللہ صلی اللہ علیہ وسلم کو اس طرح مارنے سے منع کرتے ہوئے سنا ہے، اس ذات کی قسم جس کے ہاتھ میں میری جان ہے! اگر مرغی بھی ہو تو میں اس کو اس طرح روک کر نہ ماروں، یہ خبر عبدالرحمٰن بن خالد بن ولید کو پہنچی تو انہوں نے (اپنی اس غلطی کی تلافی کے لیے) چار غلام آزاد کئے۔","حسن",{"u2":"ابن تعلی (عبید ابن تعلی) کی روایت ہے کہ ہم نے عبدالرحمٰن بن خالد بن ولید کی معیت میں جہاد کیا۔ ان کے سامنے دشمن کافر کے چار افراد لائے گئے جو عجمی تھے اور بڑے طاقتور تھے۔ پس انہوں نے حکم دیا اور انہیں بندھے بندھے قتل کر دیا گیا۔ امام ابوداؤد رضی اللہ عنہ فرماتے ہیں کہ اس حدیث میں ابن وہب کے شاگرد سعید کے علاوہ دوسروں نے ہمیں یوں بیان کیا کہ ” ان کو تیر سے مارا گیا جبکہ وہ بندھے ہوئے تھے۔ “ سیدنا ابوایوب انصاری رضی اللہ عنہ کو یہ خبر پہنچی تو انہوں نے کہا: میں نے رسول اللہ صلی اللہ علیہ وسلم کو سنا ہے آپ صلی اللہ علیہ وسلم اس طرح قتل کرنے سے منع فرماتے تھے۔ (ابوایوب رضی اللہ عنہ نے کہا) قسم اس ذات کی جس کے ہاتھ میں میری جان ہے! اگر ایک مرغی بھی ہو تو اس کو باندھ کر نہ ماروں۔ جناب عبدالرحمٰن بن خالد کو یہ خبر پہنچی تو انہوں نے چار گردنیں آزاد کیں۔","f2":"یہ روایت ضعیف ہے۔اس لئے حجت نہیں۔ حربی کافروں کی ہرطرح سے حسب ضرورت واقتضاء قتل کیاجاسکتا ہے۔صرف مثلہ کرنا منع ہے۔"}],[2688,"انس رضی اللہ عنہ سے روایت ہے کہ مکہ والوں میں سے اسی آدمی جبل تنعیم سے نماز فجر کے وقت نبی اکرم صلی اللہ علیہ وسلم اور آپ کے صحابہ کو قتل کرنے کے لیے اترے تو رسول صلی اللہ علیہ وسلم نے انہیں کسی مزاحمت کے بغیر گرفتار کر لیا، پھر آپ صلی اللہ علیہ وسلم نے ان کو آزاد کر دیا تو اللہ نے یہ آیت نازل فرمائی: «وهو الذي كف أيديهم عنكم وأيديكم عنهم ببطن مكة» إلى آخر الآية (سورۃ الفتح: ۲۴) \"اللہ ہی نے ان کا ہاتھ تم سے اور تمہارا ہاتھ ان سے وادی مکہ میں روک دیا\"۔","صحیح",{"u2":"سیدنا انس بن مالک رضی اللہ عنہ کا بیان ہے کہ (سفر حدیبیہ میں) اہل مکہ کے اسی (80) آدمی فجر کی نماز کے وقت تنعیم کے پہاڑوں سے اترے کہ نبی کریم صلی اللہ علیہ وسلم اور آپ کے اصحاب کو قتل کر ڈالیں مگر رسول اللہ صلی اللہ علیہ وسلم نے ان کو پکڑ لیا اور انہوں نے بھی اپنے آپ کو ان کے حوالے کر دیا۔ رسول اللہ صلی اللہ علیہ وسلم نے بعد میں ان کو رہا کر دیا تو ا اللہ تعالیٰ نے یہ آیت نازل فرمائی «وهو الذي كف أيديهم عنكم وأيديكم عنهم ببطن مكة» ” (ا اللہ) وہ ذات ہے جس نے وادی مکہ میں ان کے ہاتھوں کو تم سے روکے رکھا اور تمہارے ہاتھوں کو ان سے روکے رکھا۔ “","f2":"اللہ تعالیٰ کا فرمان ہے۔\n(فَإِذَا لَقِيتُمُ الَّذِينَ كَفَرُوا فَضَرْبَ الرِّقَابِ حَتَّىٰ إِذَا أَثْخَنتُمُوهُمْ فَشُدُّوا الْوَثَاقَ فَإِمَّا مَنًّا بَعْدُ وَإِمَّا فِدَاءً حَتَّىٰ تَضَعَ الْحَرْبُ أَوْزَارَهَا)(محمد۔4)\nجب کافروں سے گھمسان کا رن پڑے۔تو ان کی گردنوں پروار کرو۔ جب ان کوخوب کاٹ چکو تو اب خوب مظبوط باندھ کر قید کرلو۔پھر اختیار ہے کہ خواہ احسان کر کے چھوڑدو یا فدیہ (عوض اور بدل) لے کر۔یہاں تک کہ لڑائی اپنے ہتھیار رکھ دے۔\nفائدہ۔یہ لوگ قریش کے پرجوش اور جنگ باز نوجوان تھے۔جو اپنے بڑوں کی رائے کے برخلاف مسلمانوں کے ساتھ صلح کے حق میں نہ تھے۔انہوں نے اپنے طور پر یہ خطرناک پروگرام بنایا جس اللہ تعالیٰ نے مٹی میں ملادیا۔ پھر رسول اللہ صلی اللہ علیہ وسلم نے فدیہ لئے بغیر بطور احسان کے ان کو رہا کردیا۔"}],[2689,"جبیر بن مطعم رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے بدر کے قیدیوں سے فرمایا: \"اگر مطعم بن عدی ۱؎ زندہ ہوتے اور ان ناپاک قیدیوں کے سلسلے میں مجھ سے سفارش کرتے تو میں ان کی خاطر انہیں چھوڑ دیتا\"۔\n§وضاحت\n۱؎ : رسول اللہ صلی اللہ علیہ وسلم اہل طائف سے پہنچنے والی ایذاء اور تکلیف سے بچنے کے لئے طائف سے لوٹتے وقت مطعم بن عدی کے یہاں پہنچے، تو انہوں نے مشرکین کو دفع کیا اور آپ صلی اللہ علیہ وسلم کو ان سے بچایا، اسی احسان کا بدلہ چکانے کے لئے آپ صلی اللہ علیہ وسلم نے بدر کے قیدیوں کے متعلق یہ فرمایا تھا کہ مطعم کی سفارش پر میں ان سب کو چھوڑ دیتا، یعنی فدیہ وغیرہ نہیں لیتا۔","صحیح",{"u2":"محمد بن جبیر بن مطعم اپنے والد سے بیان کرتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم نے بدر کے قیدیوں کے متعلق فرمایا ” اگر مطعم بن عدی زندہ ہوتا اور مجھ سے ان نجس بدبو داروں کے متعلق بات کرتا تو میں اس کی خاطر ان کو رہا کر دیتا۔ “","f2":"1۔مذکورہ آیت قرآنی اور احادیث سے ثابت ہوا کہ حسب مصلحت قیدی کو فدیہ لئے بغیر احسان کرتے ہوئے رہاکردیناجائز ہے۔2۔مطعم بن عدی کا رسول اللہ صلی اللہ علیہ وسلم یہ احسان تھا کہ طائف سے واپسی پر آپ صلی اللہ علیہ وسلم اس کی حمایت اور پناہ سے مکہ میں آئے تھے۔اور اس نے آپ صلی اللہ علیہ وسلم کادفاع بھی کیا تھا۔"}],[2690,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ مجھ سے عمر بن خطاب رضی اللہ عنہ نے بیان کیا کہ جب غزوہ بدر ہوا اور نبی اکرم صلی اللہ علیہ وسلم نے قیدیوں سے فدیہ لیا تو اللہ تعالی نے یہ آیت کریمہ نازل فرمائی: «ما كان لنبي أن يكون له أسرى حتى يثخن في الأرض» سے «مسكم فيما أخذتم» تک \"نبی کے لیے مناسب نہیں کہ ان کے قیدی باقی اور زندہ رہیں جب تک کہ زمین میں ان(کافروں کا) اچھی طرح خون نہ بہا لیں، تم دنیا کے مال و اسباب چاہتے ہو اور اللہ آخرت چاہتا ہے، اللہ بڑا غالب اور بڑی حکمت والا ہے، اگر پہلے ہی سے اللہ کی طرف سے بات لکھی ہوئی نہ ہوتی تو جو کچھ تم نے لیا ہے اس کے سبب سے تمہیں بڑی سزا پہنچتی\" (سورۃ الأنفال: ۶۷-۶۸) پھر اللہ نے ان کے لیے غنائم کو حلال کر دیا۔","حسن صحیح",{"u2":"سیدنا عمر بن خطاب رضی اللہ عنہ نے بیان کیا کہ جب بدر کا دن تھا اور نبی کریم صلی اللہ علیہ وسلم نے قیدیوں سے فدیہ لیا تو ا اللہ تعالیٰ نے یہ آیت نازل فرمائی «كان لنبي أن يكون له أسرى حتى يثخن في الأرض إلى قوله لمسكم في أخذتم» ” نبی کو مناسب نہیں کہ اس کے لیے قیدی ہوں یہاں تک کہ (دشمن کو) زمین میں اچھی طرح کچل لے ‘ تم دنیا کا مال چاہتے ہو اور ا اللہ آخرت چاہتا ہے ‘ اور ا اللہ غالب ہے حکمت والا ہے۔ اگر ا اللہ کا فیصلہ پہلے سے لکھا ہوا نہ ہوتا تو جو کچھ تم نے (فدیہ) لیا ہے اس پر تمہیں بڑا عذاب پہنچتا۔ “ پھر اللہ عزوجل نے ان کے لیے غنیمتوں کو حلال فر دیا۔ امام ابوداؤد رضی اللہ عنہ فرماتے ہیں میں نے امام احمد بن حنبل رضی اللہ عنہ سے سنا کہ ان سے ابونوح کا نام پوچھا گیا تو انہوں نے کہا: تم اس کے نام کا کیا کرو گے؟ اس کا نام قبیح سا ہے۔ امام ابوداؤد رضی اللہ عنہ فرماتے ہیں کہ اس کا نام ” قراد “ ہے (چیچڑی) اور صحیح یہ ہے کہ اس کا نام عبدالرحمٰن بن غزوان ہے۔","f2":"آیت قرآنی کا مطلب یہ ہے کہ تم نے کافرقیدیوں کوقتل کرنے کی بجائے۔جو فدیہ لیا ہے۔یہ فیصلہ غلط تھا۔تہمارے لئے بہتر یہ تھاکہ تم ان کو قتل کرتے۔تاکہ کفار کی قوت کم ہوتی۔ لیکن چونکہ اللہ کی تقدیر میں تہمارے لئے مال غنیمت کا حلال ہونالکھا ہوا تھا۔اس لئے اللہ نے تمھیں معاف کردیا۔اوراس کے بعد مسلمانوں کے لئے غنیمت کا مال حلال کردیا گیا۔ جب کہ پہلی امتوں کے لئے مال غنیمت حلال نہیں تھا۔"}],[2691,"عبداللہ بن عباس رضی اللہ عنہما سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے بدر کے دن جاہلیت کے لوگوں کا فدیہ فی آدمی چار سو مقرر کیا۔","صحیح",{"u2":"سیدنا ابن عباس رضی اللہ عنہ سے روایت ہے کہ نبی کریم صلی اللہ علیہ وسلم نے بدر کے موقع پر اہل جاہلیت (مشرک قیدیوں) کا فدیہ چار سو (درہم فی کس) مقرر کیا تھا۔","f2":"شیخ البانی فرماتے ہیں۔کہ یہ روایت صحیح ہے۔البتہ چار سو درہم کے الفاظ صحیح نہیں ہیں۔"}],[2692,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ جب اہل مکہ نے اپنے اپنے قیدیوں کے فدیے بھیجے تو اس وقت زینب رضی اللہ عنہا نے ابوالعاص رضی اللہ عنہ ۱؎ کے فدیہ میں کچھ مال بھیجا اور اس مال میں اپنا ایک ہار بھیجا جو خدیجہ رضی اللہ عنہا کا تھا، انہوں نے یہ ہار زینب کو ابوالعاص سے نکاح کے موقع پر رخصتی کے وقت دیا تھا، جب رسول اللہ صلی اللہ علیہ وسلم نے اس ہار کو دیکھا تو آپ پر سخت رقت طاری ہو گئی، آپ صلی اللہ علیہ وسلم نے فرمایا: \"اگر تم مناسب سمجھو تو ان کی خاطر و دلداری میں ان کا قیدی چھوڑ دو، اور ان کا مال انہیں لوٹا دو\"، لوگوں نے کہا: ٹھیک ہے، رسول اللہ صلی اللہ علیہ وسلم نے انہیں چھوڑتے وقت یہ عہد لے لیا کہ وہ زینب رضی اللہ عنہا کو میرے پاس آنے سے نہ روکیں گے، پھر رسول صلی اللہ علیہ وسلم نے زید بن حارثہ رضی اللہ عنہ اور انصار میں سے ایک شخص کو بھیجا، اور فرمایا: \"تم دونوں \"بطن یأجج\" میں رہنا یہاں تک کہ زینب تم دونوں کے پاس سے گزریں تو ان کو ساتھ لے کر آنا ۲؎\"۔\n§وضاحت\n۱؎ : زینب رضی اللہ عنہا رسول اکرم صلی اللہ علیہ وسلم کی بڑی صاحب زادی تھیں، اور ابو العاص رضی اللہ عنہ خدیجہ رضی اللہ عنہا کے بھانجے اور زینب کے شوہر تھے۔ ۲؎ : شاید یہ نامحرم کے ساتھ سفر کرنے کی ممانعت سے پہلے کا واقعہ ہو، زینب رضی اللہ عنہا کے مدینہ آجانے کے بعد ابو العاص رضی اللہ عنہ کفر کی حالت میں مکہ ہی میں مقیم رہے، پھر تجارت کے لئے شام گئے، وہاں سے لوٹتے وقت انھیں اسلام پیش کیا گیا، تو وہ مکہ واپس گئے اور وہ مال جس جس کا تھا اس کو واپس کیا اور سب کے سامنے کلمہ شہادت پڑھ کر مشرف بہ اسلام ہو گئے، پھر ہجرت کر کے مدینہ آگئے اور مسلمان ہو جانے پر رسول اکرم صلی اللہ علیہ وسلم نے زینب کو ان کی زوجیت میں لوٹا دیا تھا۔","حسن",{"u2":"ام المؤمنین سیدہ عائشہ رضی اللہ عنہا ا کا بیان ہے کہ جب اہل مکہ نے اپنے قیدیوں کے فدیے بھیجے تو سیدہ زینب رضی اللہ عنہا ا (نبی کریم صلی اللہ علیہ وسلم کی صاحبزادی) نے (اپنے شوہر) ابوالعاص کے فدیہ میں مال بھیجا ‘ اور وہ ہار پیش کیا جو ام المؤمنین سیدہ خدیجہ رضی اللہ عنہا ا نے ان کو ابوالعاص سے شادی کے وقت دیا تھا۔ اسے دیکھ کر رسول اللہ صلی اللہ علیہ وسلم پر شدید رقت طاری ہوئی اور فرمایا ” اگر تم مناسب سمجھو تو اس کے قیدی کو اس کے لیے ویسے ہی رہا کر دو اور اس کا ہار اسے واپس کر دو۔ “ صحابہ نے اسے بخوشی قبول کیا۔ چنانچہ رسول اللہ صلی اللہ علیہ وسلم نے ابوالعاص سے یہ عہد لیا کہ زینب رضی اللہ عنہا ا کو آپ کی طرف بھیج دے گا۔ پھر رسول اللہ صلی اللہ علیہ وسلم نے سیدنا زید بن حارثہ رضی اللہ عنہ اور ایک انصاری کو بھیجا اور انہیں کہا: ” تم وادی یاجج کے دامن میں رکنا حتیٰ کہ زینب تمہارے پاس آ جائے تو پھر اسے ساتھ لے کر آ جانا۔ “","f2":"1۔ حسب مصالح قیدی کو فدیہ لئے بغیر رہاکرنا بھی جائز ہے۔2۔حضرت زینب رضی اللہ تعالیٰ عنہا کا ابوالعاص کے ساتھ نکاح بعثت سے پہلے ہوا تھا۔ مگر ابو العاص نے صلح حدیبیہ کے ایام میں اسلام قبول کیا۔3۔وادی یا جج مکی سے آٹھ میل کے فاصلے پر واقع تھی۔4۔زینب رضی اللہ عنہا کے واقعے سے معلوم ہوتاہے کہ اشد ضرورت کی بنا پر عورت بغیر محرم کے سفر کرسکتی ہے۔ جبکہ عورت کا خاوند اور محرم کاکسی وجہ سے ساتھ جانا ممکن نہ ہو۔"}],[2693,"ابن شہاب زہری کہتے ہیں کہ عروہ بن زبیر نے ذکر کیا کہ انہیں مروان اور مسور بن مخرمہ رضی اللہ عنہ نے خبر دی کہ جس وقت رسول اللہ صلی اللہ علیہ وسلم کے پاس وفد ہوازن مسلمان ہو کر آیا اور اس نے آپ سے درخواست کی کہ آپ ان کے مال انہیں واپس لوٹا دیں، تو رسول اللہ صلی اللہ علیہ وسلم نے ان سے فرمایا: \"میرے ساتھ جو ہیں انہیں تم دیکھ رہے ہو، اور میرے نزدیک سب سے عمدہ بات سچی بات ہے تم یا تو قیدیوں (کی واپسی) اختیار کر لو یا مال\"، انہوں نے کہا: ہم اپنے قیدیوں کو اختیار کریں گے، نبی اکرم صلی اللہ علیہ وسلم کھڑے ہوئے، اللہ کی حمد و ثنا بیان کی اس کے بعد فرمایا: \"تمہارے یہ بھائی (شرک سے) توبہ کر کے آئے ہیں، میں چاہتا ہوں کہ ان کے قیدیوں کو واپس لوٹا دوں، لہٰذا تم میں سے جو شخص اپنی خوشی سے واپس لوٹا سکتا ہو تو وہ واپس لوٹا دے، اور جو شخص اپنا حصہ لینے پر مصر ہے تو پہلا مال غنیمت جو اللہ ہم کو دے ہم اس میں سے اس کا عوض دیں تو وہ ایسا ہی کر لے\"، لوگوں نے کہا: اللہ کے رسول! ہم نے انہیں بخوشی واپس لوٹا دیا، رسول اللہ صلی اللہ علیہ وسلم نے ان سے فرمایا: \"ہم نہیں جانتے کہ تم میں سے کس نے اجازت دی، اور کس نے نہیں دی؟ لہٰذا تم واپس جاؤ یہاں تک کہ تمہارے سردار معاملہ کی تفصیل ہمارے پاس لے کر آئیں\"، لوگ لوٹ گئے، اور ان سے ان کے سرداروں نے بات کی تو انہوں نے اپنے سرداروں کو بتایا کہ انہوں نے خوشی خوشی اجازت دی ہے۔","صحیح",{"u2":"مروان بن حکم اور مسور بن مخرمہ کا بیان ہے کہ ہوازن کے مسلمان لوگوں کا وفد رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں آیا تو انہوں نے درخواست کی کہ ہمارا مال واپس کر دیا جائے (جو کہ غزوہ حنین میں مسلمانوں کے قبضہ میں آیا ہے) رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” میرے ساتھ یہ لوگ ہیں جن کو تم دیکھ رہے ہو (مجاہدین) اور مجھے بات وہ پسند ہے جو سچی ہو ‘ تم لوگ دو میں سے ایک چیز اختیار کر لو، قیدی یا مال۔ “ انہوں نے کہا: ہم اپنے قیدیوں کو اختیار کرتے ہیں ‘ (انہیں رہا کر دیا جائے) تو رسول اللہ صلی اللہ علیہ وسلم خطبہ کے لیے کھڑے ہوئے ‘ اللہ عزوجل کی حمد و ثنا بیان کی پھر فرمایا ” تمہارے یہ بھائی تائب ہو کر آئے ہیں، میں نے یہ مناسب سمجھا ہے کہ ان کے قیدی ان کو واپس کر دوں ‘ تو تم میں سے بھی جو خوشی خوشی یہ کام کرنا چاہے کرے ‘ اور جو پسند کرے کہ (اس کے قیدی کے بدلے) اسے اس کا حصہ دیا جائے تو یہ ہمارے ذمے رہا اور پہلی پہلی غنیمت جو ا اللہ ہمیں دے گا اس میں سے ہم اس کا حق ادا کریں گے۔ “ لوگوں نے کہا: اے ا اللہ کے رسول! ہم ان کے لیے بخوشی یہ کام کرتے ہیں۔ آپ صلی اللہ علیہ وسلم نے فرمایا ” ہم پر یہ واضح نہیں ہے کہ تم میں سے کس نے اجازت دی ہے اور کس نے نہیں دی ‘ لہٰذا تم جاؤ حتیٰ کہ تمہارے نمائندے ہمیں آ کر تمہارا معاملہ بتائیں۔ “ چنانچہ وہ لوگ لوٹ گئے ‘ ان کے امیروں اور نمائندوں نے ان سے (کھل کر) بات کی ‘ تو ان نمائندوں نے آ کر بتایا کہ ہمارے لوگ خوشی سے انہیں (آزاد کرنے کی) اجازت دے رہے ہیں۔"}],[2694,"عبداللہ بن عمرو رضی اللہ عنہما اسی قصہ کی روایت میں کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"ان کی عورتوں اور بچوں کو واپس لوٹا دو، اور جو کوئی اس مال غنیمت سے اپنا حصہ باقی رکھنا چاہے تو ہم اس کو اس پہلے مال غنیمت سے جو اللہ ہمیں دے گا چھ اونٹ دیں گے\"، پھر آپ صلی اللہ علیہ وسلم ایک اونٹ کے قریب آئے اور اس کی کوہان سے ایک بال لیا پھر فرمایا: \"لوگو! میرے لیے اس مال غنیمت سے کچھ بھی حلال نہیں ہے\"، اور اپنی دونوں انگلیاں اٹھا کر کہا: \"یہاں تک کہ یہ (بال) بھی حلال نہیں سوائے خمس (پانچواں حصہ) کے، اور خمس بھی تمہارے ہی اوپر لوٹا دیا جاتا ہے، لہٰذا تم سوئی اور دھاگا بھی ادا کر دو\" (یعنی بیت المال میں جمع کر دو)، ایک شخص کھڑا ہو اس کے ہاتھ میں بالوں کا ایک گچھا تھا، اس نے کہا: میں نے اس کو پالان کے نیچے کی کملی درست کرنے کے لیے لیا تھا؟ اس پر رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"رہا میرا اور بنی عبدالمطلب کا حصہ تو وہ تمہارے لیے ہے\"، تو اس نے کہا: جب معاملہ اتنا اہم ہے تو مجھے اس کی کوئی ضرورت نہیں ہے، اور اس نے اسے (غنیمت کے مال میں) پھینک دیا ۱؎۔\n§وضاحت\n۱؎ : اس حدیث سے معلوم ہوا کہ غنیمت کے مال میں سے چوری کرنا گناہ عظیم ہے، جو کچھ ملے سب امام کے پاس جمع کر دیا جائے پھر وہ تقسیم کرے۔","حسن",{"u2":"سیدنا عمرو بن شعیب اپنے والد سے ‘ (شعیب) اپنے دادا سے اس واقعہ کے سلسلے میں بیان کرتے ہیں کہ پھر رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” ان لوگوں کی عورتیں اور بچے انہیں لوٹا دو اور جو کوئی بلا عوض واپس نہ کرنا چاہے تو ہمارا اس سے وعدہ ہے کہ پہلی پہلی غنیمت جو ا اللہ تعالیٰ ہمیں عنایت فرمائے گا اس میں سے چھ اونٹ اسے دیے جائیں گے۔ “ پھر آپ اپنے اونٹ کے قریب ہوئے اور اس کے کوہان سے کچھ بال لیے اور فرمایا ” لوگو! اس غنیمت میں سے میرے لیے خمس (پانچویں حصے) کے سوا کچھ نہیں ہے، اس قدر (بال) بھی نہیں۔ “ اور آپ نے اشارہ کرتے ہوئے اپنی انگلی بلند فرمائی۔ اور فرمایا ” یہ خمس بھی تم لوگوں ہی میں تقسیم ہو گا لہٰذا سوئی اور دھاگے تک واپس کر دو۔ “ چنانچہ ایک آدمی کھڑا ہوا ‘ اس کے ہاتھ میں بالوں کا ایک گچھا سا تھا وہ بولا: میں نے یہ بال لیے ہیں تاکہ پالان کے نیچے کی گدی درست کر لوں۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” جو میرا ذاتی حصہ ہے یا بنی عبدالمطلب کا ‘ وہ تم لے سکتے ہو (دوسروں کا نہیں)۔ “ اس نے کہا: اگر اس کا اتنا گناہ ہے جو میں دیکھ رہا ہوں تو مجھے اس کی کوئی ضرورت نہیں اور اس نے گچھا پھینک دیا۔","f2":"1۔مسلمانوں پرواجب ہے کہ اپنی انفرادی اور اجتماعی زندگی میں ہمیشہ سچی اورصاف بات کیا کریں۔2۔مسلمانوں کے قائد کو یہ بھی حق نہیں کہ ان کی ولی ر ضا مندی کے بغیر ان کے مال پرکوئی تصرف کرے۔3۔اگر اجتماعی مصلحت کے تحت کوئی تصرف کرتاہو تو اس کاعو ض ادا کرنالازمی ہے۔4۔حسب مصلحت قیدیوں کو فدیہ لئے بغیر آذاد کرناجائز ہے۔5۔قومی امانت میں معمولی خیانت بھی جرم عظیم ہے۔لہذا منصب داروں کو فکرکرنی چاہیے۔اور خبر دار رہناچاہیے۔6۔ہر قوم اور جماعت کو اجتماعی نظم قائم کرتے ہوئے اپنا امیر اور نمائندہ منتخب کرنا چاہیے جو اجتماعی امور میں ان کی نمائندگی کرے۔"}],[2695,"ابوطلحہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم جب کسی قوم پر غالب آتے تو میدان جنگ میں تین رات قیام کرتے۔ ابن مثنی کا بیان ہے: جب کسی قوم پر غالب آتے تو میدان جنگ میں جو ان کی سر زمین میں پڑتا تین رات قیام کرنا پسند فرماتے۔ ابوداؤد کہتے ہیں: کہ یحیی بن سعید اس حدیث میں طعن کرتے تھے کیونکہ یہ سعید (سعید ابن ابی عروبہ) کی پہلے کی حدیثوں میں سے نہیں ہے، اس لیے کہ ۱۴۵ ہجری میں ان کے حافظہ میں تغیر پیدا ہو گیا تھا، اور یہ حدیث بھی آخری عمر کی ہے۔ ابوداؤد کہتے ہیں: کہا جاتا ہے کہ وکیع نے ان سے ان کے زمانہ تغیر میں ہی حدیث حاصل کی ہے ۱؎۔\n§وضاحت\n۱؎ : بخاری اور مسلم نے سعید بن ابی عروبہ کی حدیث کو روح بن عبادہ کی روایت سے صحیحین میں داخل کیا ہے، یہ روایت بھی روح ہی کے واسطے سے ہے، اس لئے اس کی صحت میں کوئی کلام نہیں ہے، وکیع نے ابن ابی عروبہ سے اختلاط کے بعد روایت کی ہے یہ بات مسلَّم ہے، مگر یہاں اس کا کوئی عمل دخل نہیں یہ بات مؤلف نے برسبیل تذکرہ لکھ دی ہے۔","صحیح",{"u2":"سیدنا ابوطلحہ رضی اللہ عنہ سے منقول ہے کہ رسول اللہ صلی اللہ علیہ وسلم جب کسی قوم پر غالب آ جاتے تو (اس کے بعد) تین دن تک ان کے علاقے میں اقامت فرماتے۔ ابن مثنیٰ نے کہا: جب آپ صلی اللہ علیہ وسلم کسی قوم پر غالب آ جاتے تو پسند فرماتے کہ ان کے علاقے میں تین دن اقامت کریں۔ امام ابوداؤد رضی اللہ عنہ فرماتے ہیں محدث یحییٰ بن سعید اس حدیث پر اعتراض کیا کرتے تھے کہ یہ سعید (ابن ابی عروبہ) کی قدیم روایات میں سے نہیں ہے کیونکہ سن 45 ہجری میں ان کا حافظ بگڑ گیا تھا۔ اور انہوں نے یہ حدیث اس عارضے کے بعد ہی بیان کی ہے۔ امام ابوداؤد رضی اللہ عنہ فرماتے ہیں (کہا جاتا ہے کہ وکیع نے ان سے یہ حدیث حافظہ کی خرابی کے دنوں میں لی تھی)۔","f2":"حدیث صحیح ہے۔اور یہ صحیح بخاری میں بھی ہے۔(25۔30)یہی وجہ ہے کہ امام ابودائود کا یہ قول جو بریکٹوں کے درمیان ہے۔ابو دائود کے بعض نسخوں میں نہیں ہے۔اور اس کا نہ ہونا ہی زیادہ مناسب ہے۔"}],[2696,"علی رضی اللہ عنہ سے روایت ہے کہ انہوں نے ایک لونڈی اور اس کے بچے کے درمیان جدائی کرا دی تو رسول اللہ صلی اللہ علیہ وسلم نے اس سے منع فرمایا، اور بیع کو رد کر دیا۔ ابوداؤد کہتے ہیں: میمون نے علی رضی اللہ عنہ کو نہیں پایا ہے، میمون جنگ جماجم میں قتل کئے گئے، اور جماجم ۸۳ ہجری میں ہوئی ہے، نیز واقعہ حرہ (۶۳ ہجری) میں پیش آیا، اور ابن زبیر (۷۳ ہجری) میں قتل ہوئے۔","حسن",{"u2":"سیدنا علی رضی اللہ عنہ سے روایت ہے کہ انہوں نے ایک لونڈی اور اس کے بچے میں جدائی کر دی (اور انہیں علیحدہ علیحدہ بیچ دیا) تو نبی کریم صلی اللہ علیہ وسلم نے ان کو اس سے روک دیا اور ان کی یہ بیع واپس کرا دی۔ امام ابوداؤد رضی اللہ عنہ کہتے ہیں کہ میمون (میمون بن ابی شبیب) نے سیدنا علی رضی اللہ عنہ کو نہیں پایا۔ یہ سن 83 ہجری میں جماجم میں قتل کر دیے گئے تھے۔ امام ابوداؤد رضی اللہ عنہ فرماتے ہیں: واقعہ حرہ سن 63 ہجری میں ہوا تھا اور سیدنا (عبداللہ) ابن زبیر سن 73 ہجری میں قتل ہوئے تھے۔","f2":"یہ روایت یہاں اس سند کے ساتھ منقطع ہے۔جیسا کہ امام ابودائود نے تصریح کی ہے۔لیکن دوسرے شواہد کی بنا پر یہ روایت حسن ہے۔اس لئے یہ مسئلہ صحیح ہے۔کہ لونڈی اور اس کے بچے کو الگ الگ بیچنا صحیح نہیں ہے۔ اسی طرح ماں کو بھی تکلیف ہوگی۔اور بچہ بھی پریشان ہوگا۔"}],[2697,"سلمہ بن الاکوع رضی اللہ عنہ کہتے ہیں کہ ہم ابوبکر رضی اللہ عنہ کے ساتھ نکلے، رسول اللہ صلی اللہ علیہ وسلم نے ان کو ہمارا امیر بنایا تھا، ہم نے قبیلہ بنی فزارہ سے جنگ کی، ہم نے ان پر اچانک حملہ کیا، کچھ بچوں اور عورتوں کی گردنیں ہمیں نظر آئیں، تو میں نے ایک تیر چلائی، تیر ان کے اور پہاڑ کے درمیان جا گرا وہ سب کھڑے ہو گئے، پھر میں ان کو پکڑ کر ابوبکر رضی اللہ عنہ کے پاس لایا، ان میں فزارہ کی ایک عورت تھی، وہ کھال پہنے ہوئی تھی، اس کے ساتھ اس کی لڑکی تھی جو عرب کی حسین ترین لڑکیوں میں سے تھی، ابوبکر رضی اللہ عنہ نے مجھے اس کی بیٹی کو بطور انعام دے دیا، میں مدینہ آیا تو رسول اللہ صلی اللہ علیہ وسلم سے میری ملاقات ہوئی تو آپ نے فرمایا: \"سلمہ! اس عورت کو مجھے ہبہ کر دو\"، میں نے کہا: اللہ کی قسم وہ لڑکی مجھے پسند آئی ہے، اور میں نے ابھی تک اس کا کپڑا نہیں ہٹایا ہے، آپ خاموش ہو گئے، جب دوسرا دن ہوا تو رسول اللہ صلی اللہ علیہ وسلم پھر مجھے بازار میں ملے اور فرمایا: \"سلمہ! اس عورت کو مجھے ہبہ کر دو، قسم ہے اللہ کی\" ۱؎، میں نے کہا: اللہ کے رسول! اللہ کی قسم! میں نے ابھی تک اس کا کپڑا نہیں ہٹایا ہے، اور وہ آپ کے لیے ہے، پھر آپ صلی اللہ علیہ وسلم نے اسے مکہ والوں کے پاس بھیج دیا، اور اس کے بدلے میں ان کے پاس جو مسلمان قیدی تھے انہیں چھڑا لیا۔\n§وضاحت\n۱؎ : متن حدیث میں «لله أبوك» کے الفاظ ہیں یہ جملہ قسم کے حکم میں ہے۔","حسن",{"u2":"سیدنا ایاس بن سلمہ اپنے والد (سلمہ بن اکوع رضی اللہ عنہ) سے روایت کرتے ہیں، کہتے ہیں کہ ہم سیدنا ابوبکر رضی اللہ عنہ کے ساتھ (جہاد کے لیے) روانہ ہوئے۔ رسول اللہ صلی اللہ علیہ وسلم نے ان کو ہمارا امیر بنایا تھا ‘ ہم نے بنو فزارہ کے ساتھ جہاد کیا اور ہر طرف سے ان پر چڑھائی کی۔ میں نے لوگوں کی ایک جماعت دیکھی، ان میں بچے تھے اور عورتیں بھی۔ میں نے ایک تیر مارا جو ان کے اور پہاڑ کے درمیان جا گرا تو وہ اٹھ کھڑے ہوئے ‘ میں انہیں سیدنا ابوبکر رضی اللہ عنہ کے پاس لے آیا۔ ان میں فزارہ کی ایک عورت تھی جس نے ایک پرانی کھال اوڑھی ہوئی تھی اس کے ساتھ اس کی بیٹی بھی تھی جو عرب کی حسین ترین لڑکیوں میں سے تھی۔ سیدنا ابوبکر رضی اللہ عنہ نے وہ لڑکی بطور نفل غنیمت مجھے دے دی۔ میں مدینے آیا اور رسول اللہ صلی اللہ علیہ وسلم مجھے ملے اور فرمایا ” اے سلمہ! وہ عورت مجھے ہبہ کر دے۔ “ میں نے عرض کیا: قسم ا اللہ کی! وہ تو مجھے بہت پسند آئی ہے اور میں نے اس کا کپڑا بھی نہیں اٹھایا۔ پس آپ خاموش ہو رہے۔ جب اگلا دن ہوا ‘ رسول اللہ صلی اللہ علیہ وسلم مجھے بازار میں ملے اور فرمایا ” اے سلمہ! عورت مجھے ہبہ کر دے ‘ تیرے باپ کی بھلائی ہو۔ “ میں نے عرض کیا: اے ا اللہ کے رسول! میں نے اس کا کپڑا تک نہیں اٹھایا ‘ مگر وہ آپ کی ہوئی۔ چنانچہ آپ صلی اللہ علیہ وسلم نے اسے اہل مکہ کی طرف بھیج دیا جبکہ کچھ مسلمان قیدی ان کے قبضے میں تھے ‘ تو اس عورت کو بطور فدیہ کے ان کو دے دیا۔","f2":"1۔مجاہد کو اضافی انعامات (نفل غنیمت) خمس نکالنے سے پہلے دیئے جاتے ہیں۔2۔قیدی اگر بڑی عمر کے ہوں۔ تو قریبی رشتہ داروں میں بھی تفریق کیجاسکتی ہے۔3۔رسول اللہ صلی اللہ علیہ وسلم کسی مسلمان کا مال اس کی ولی رضا مندی کے بغیر لینا پسند نہ کرتے تھے۔3۔لونڈیوں سے مباشرت جائز ہے۔ خواہ مشرک ہی ہوں۔مگر استبراء (ایک حیض آنے) کے بعد 5۔جس طرح بھی بن پڑے۔مسلمان قیدیوں کو آذاد کرایاجائے۔"}],[2698,"عبداللہ بن عمر رضی اللہ عنہما سے روایت ہے کہ ان کا ایک غلام دشمنوں کی جانب بھاگ گیا پھر مسلمان دشمن پر غالب آ گئے تو رسول اللہ صلی اللہ علیہ وسلم نے یہ غلام عبداللہ بن عمر رضی اللہ عنہما کو واپس دے دیا، اسے مال غنیمت میں تقسیم نہیں کیا۔ ابوداؤد کہتے ہیں: دوسروں کی روایت میں ہے خالد بن ولید نے اسے انہیں لوٹا دیا۔","صحیح",{"u2":"سیدنا ابن عمر رضی اللہ عنہ سے روایت ہے کہ ان کا ایک غلام بھاگ کر دشمنوں کے پاس چلا گیا۔ پھر مسلمان ان لوگوں پر غالب آ گئے تو رسول اللہ صلی اللہ علیہ وسلم نے وہ غلام ابن عمر رضی اللہ عنہ کو واپس کر دیا اور (بطور غنیمت) تقسیم نہیں فرمایا۔ امام ابوداؤد رضی اللہ عنہ فرماتے ہیں (یحییٰ بن ابی زائدہ کے علاوہ) کسی دوسرے نے کہا کہ خالد بن ولید نے اسے واپس کیا تھا۔","f2":"یہ روایت صحیح نہیں ہے۔البتہ اگلی روایت صحیح ہے۔جس میں یہ ہے کہ یہ واقعہ نبی کریم صلی اللہ علیہ وسلم کی وفات کے بعد پیش آیا ہے۔ااورحضرت خالد بن ولید رضی اللہ تعالیٰ عنہ نے وہ غلام یا گھوڑا واپس کیا تھا۔"}],[2699,"عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ ان کا ایک گھوڑا بھاگ گیا، اور اسے دشمن نے پکڑ لیا پھر مسلمان دشمن پر غالب آ گئے تو رسول اللہ صلی اللہ علیہ وسلم کے زمانہ میں عبداللہ بن عمر رضی اللہ عنہما کو واپس لوٹا دیا گیا، اور ان کا ایک غلام بھاگ کر روم چلا گیا، پھر رومیوں پر مسلمان غالب آئے تو نبی اکرم صلی اللہ علیہ وسلم کے بعد خالد بن ولید رضی اللہ عنہ نے (بھی) انہیں غلام واپس لوٹا دیا۔","صحیح",{"u2":"(محمد بن سلیمان الانباری کی سند سے مروی ہے) سیدنا ابن عمر رضی اللہ عنہ بیان کرتے ہیں کہ ان کا ایک گھوڑا بھاگ گیا تو دشمن نے اسے پکڑ لیا۔ پھر مسلمان ان پر غالب آ گئے تو وہ گھوڑا رسول اللہ صلی اللہ علیہ وسلم کے زمانے میں ابن عمر رضی اللہ عنہ کو واپس دے دیا گیا۔ (ایک اور موقع پر) سیدنا ابن عمر رضی اللہ عنہ کا ایک غلام بھاگ گیا اور رومیوں کے علاقے میں چلا گیا۔ مسلمان ان پر غالب آئے سیدنا خالد بن ولید رضی اللہ عنہ نے یہ ان کو واپس کر دیا اور نبی کریم صلی اللہ علیہ وسلم کے بعد کا واقعہ ہے۔"}],[2700,"علی رضی اللہ عنہ کہتے ہیں کہ غزوہ حدیبیہ میں صلح سے پہلے کچھ غلام (بھاگ کر) رسول اللہ صلی اللہ علیہ وسلم کے پاس آ گئے، تو ان کے مالکوں نے آپ کو لکھا: اے محمد! اللہ کی قسم! یہ غلام تمہارے دین کے شوق میں تمہارے پاس نہیں آئے ہیں، یہ تو فقط غلامی کی قید سے بھاگ کر آئے ہیں، تو کچھ لوگوں نے کہا: اللہ کے رسول! ان لوگوں نے سچ کہا: انہیں مالکوں کے پاس واپس لوٹا دیا جائے تو آپ صلی اللہ علیہ وسلم غصہ ہو گئے ۱؎ اور فرمایا: \"قریش کے لوگو، میں تم کو باز آتے ہوئے نہیں دیکھتا ہوں یہاں تک کہ اللہ تمہارے اوپر اس شخص کو بھیجے جو اس پر ۲؎ تمہاری گردنیں مارے\"، اور آپ صلی اللہ علیہ وسلم نے انہیں واپس لوٹانے سے انکار کیا اور فرمایا: \"یہ اللہ عزوجل کے آزاد کئے ہوئے ہیں\"۔\n§وضاحت\n۱؎ : نبی اکرم صلی اللہ علیہ وسلم کی ناراضگی کی وجہ یہ تھی کہ انہوں نے شرع کے حکم پر ظن و تخمین کی بنیاد پر اعتراض کیا، اور مشرکین کے دعوے کی حمایت کی۔ ۲؎ : اس پر سے مراد جاہلی عصبیت اور بے جا قومی حمیت ہے۔","صحیح",{"u2":"سیدنا علی بن ابی طالب رضی اللہ عنہ سے روایت ہے کہ حدیبیہ کے روز صلح سے پہلے کچھ غلام بھاگ کر رسول اللہ صلی اللہ علیہ وسلم کے پاس آ گئے تو ان کے مالکوں نے آپ صلی اللہ علیہ وسلم کو لکھا: اے محمد! (صلی اللہ علیہ وسلم) قسم ا اللہ کی! یہ لوگ تمہارے دین کے شوق میں تمہارے پاس نہیں آئے ہیں ‘ بلکہ غلامی سے بھاگ کر آئے ہیں۔ صحابہ میں سے کچھ نے کہا: اے ا اللہ کے رسول! انہوں نے سچ کہا ہے ‘ آپ انہیں ان کو واپس لوٹا دیں تو رسول اللہ صلی اللہ علیہ وسلم غصے ہوئے اور فرمایا ” اے قریشیو! میں سمجھتا ہوں کہ تم لوگ اس وقت تک باز نہیں آؤ گے جب تک کہ ا اللہ تم پر کسی ایسے کو نہ بھیج دے جو تمہاری اس (ہٹ دھرمی) پر تمہاری گردنیں مار دے۔ “ اور آپ نے ان کو واپس کرنے سے انکار کر دیا اور فرمایا ” یہ اللہ عزوجل کے آزاد کردہ لوگ ہیں۔ “","f2":"جب ایک آمی دارالکفر سے نکل بھاگا۔تو اپنے طور پر آزاد ہوگیا۔پھر اسلام قبول کرلیا۔تو اب وہ آذاد ہے۔اس کا اسلام بھی قبول ہے۔اسے کفار کے پاس واپس بھیجنے کی کوئی وجہ نہیں ہے۔"}],[2701,"عبداللہ بن عمر رضی اللہ عنہما سے روایت ہے کہ ایک لشکر رسول اللہ صلی اللہ علیہ وسلم کے زمانہ میں (دوران جنگ) غلہ اور شہد غنیمت میں لایا تو اس میں سے خمس نہیں لیا گیا۔","صحیح",{"u2":"سیدنا ابن عمر رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم کے زمانے میں ایک لشکر کو غلہ اور شہد بطور غنیمت ملا، تو اس میں سے خمس نہیں لیا گیا تھا۔"}],[2702,"عبداللہ بن مغفل رضی اللہ عنہ کہتے ہیں کہ خیبر کے دن چربی کا ایک مشک لٹکایا گیا تو میں آیا اور اس سے چمٹ گیا، پھر میں نے کہا: آج میں اس میں سے کسی کو بھی کچھ نہیں دوں گا، پھر میں مڑا تو کیا دیکھتا ہوں کہ رسول اللہ صلی اللہ علیہ وسلم میری اس حرکت پر کھڑے مسکرا رہے ہیں۔","صحیح",{"u2":"سیدنا عبداللہ بن مغفل رضی اللہ عنہ کا بیان ہے کہ خیبر کے روز چربی سے بھرا ایک تھیلا اوپر سے لڑھکایا گیا۔ میں نے آگے بڑھ کر اسے جھپٹ لیا، پھر میں نے کہا: آج میں اس میں سے کسی کو کچھ نہیں دوں گا۔ میں نے گردن موڑی تو دیکھا کہ رسول اللہ صلی اللہ علیہ وسلم میری جانب (دیکھ کر) مسکرا رہے تھے۔","f2":"فقہائے حدیث بیان کرتے ہیں کہ مطعومات (کھانے پینے والی چیزوں) میں سے خمس نہیں نکالا جاتا۔اور مجاہدین کوحسب حاجت کھا پی لینے کی رخصت ہے۔البتہ بہت زیادہ مقدار میں حاصل ہونے والا غلہ بعد از استعمال بطور غنیمت تقسیم ہوگا۔2۔خمس کا مسئلہ آگے باب۔158 میں آرہا ہے۔3۔اہل کتاب کا ذبیحہ حلال ہے۔ اور انکی چربی بھی۔"}],[2703,"ابو لبید کہتے ہیں کہ ہم عبدالرحمٰن بن سمرہ رضی اللہ عنہ کے ساتھ کابل میں تھے وہاں لوگوں کو مال غنیمت ملا تو انہوں نے اسے لوٹ لیا، عبدالرحمٰن نے کھڑے ہو کر خطبہ دیا اور کہا: میں نے رسول اللہ صلی اللہ علیہ وسلم کو سنا کہ آپ لوٹنے سے منع فرماتے تھے، تو لوگوں نے جو کچھ لیا تھا واپس لوٹا دیا، پھر انہوں نے اسے ان میں تقسیم کر دیا۔","صحیح",{"u2":"ابو لبید بیان کرتے ہیں کہ ہم سیدنا عبدالرحمٰن بن سمرہ رضی اللہ عنہ کی معیت میں کابل میں تھے۔ لوگوں کو غنیمت ملی تو ہر ایک نے اسے لوٹ لیا۔ پس انہوں نے خطبہ دیا اور فرمایا میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا ہے کہ آپ صلی اللہ علیہ وسلم نے لوٹ سے منع کیا ہے۔ چنانچہ ان لوگوں نے جو کچھ لیا تھا سب واپس کر دیا۔ پھر عبدالرحمٰن رضی اللہ عنہ نے اسے ان میں تقسیم کر دیا۔","f2":"1۔یعنی جس طرح مردار کا گوشت حلال اور جائز نہیں۔یہی حکم لوٹ کے اس مال کا ہے۔ جو بلاااستحقاق لیاجائے۔2۔نبی کریم صلی اللہ علیہ وسلم نے انتہائی مشقت اور احتیاج کے حالات میں بھی دوسروں کا حق کھانے کی اجازت نہیں دی۔3۔مالی سزا دینا (تعزیر بالمال)جائز ہے۔4۔امام پر واجب ہے کہ اپنی رعیت میں عدل وانصاف کا ہر حال میں اہتمام کرے۔اس سے اللہ کی رحمت اترتی اور دشمن پر غلبہ ملتا ہے۔"}],[2704,"عبداللہ بن ابی اوفی رضی اللہ عنہ کہتے ہیں کہ میں نے پوچھا: کیا آپ لوگ رسول اللہ صلی اللہ علیہ وسلم کے زمانہ میں غلہ کا پانچواں حصہ نکالا کرتے تھے؟ انہوں نے کہا: ہمیں خیبر کے دن غلہ ملا تو آدمی آتا اور اس میں سے کھانے کی مقدار میں لے لیتا پھر واپس چلا جاتا۔","صحیح",{"u2":"محمد بن ابی مجالد نے سیدنا عبداللہ بن ابی اوفی رضی اللہ عنہ سے پوچھا: کیا آپ لوگ رسول اللہ صلی اللہ علیہ وسلم کے دور میں کھانے پینے کی اشیا میں سے خمس نکالا کرتے تھے؟ انہوں نے کہا: ہمیں خیبر کے روز غلہ ملا تو ضرورت مند آتا اور جس قدر اسے ضرورت ہوتی لے کر چلا جاتا۔"}],[2705,"ایک انصاری رضی اللہ عنہ کہتے ہیں کہ ہم رسول اللہ صلی اللہ علیہ وسلم کے ساتھ ایک سفر میں نکلے، لوگوں کو اس سفر میں بڑی احتیاج اور سخت پریشانی ہوئی پھر انہیں کچھ بکریاں ملیں، تو لوگوں نے انہیں لوٹ لیا، ہماری ہانڈیاں ابل رہی تھیں، اتنے میں نبی اکرم صلی اللہ علیہ وسلم اپنی کمان پر ٹیک لگائے ہوئے تشریف لائے، پھر آپ نے اپنے کمان سے ہماری ہانڈیاں الٹ دیں اور گوشت کو مٹی میں لت پت کرنے لگے، اور فرمایا: \"لوٹ کا مال مردار سے زیادہ حلال نہیں\"، یا فرمایا: \"مردار لوٹ کے مال سے زیادہ حلال نہیں\"، یہ شک ہناد راوی کی جانب سے ہے ۱؎۔\n§وضاحت\n۱؎ : چونکہ بکریاں غلے یا تیار کھانے کی چیزوں کی قبیل سے نہیں ہیں اس لئے ان کی لوٹ سے منع کیا گیا، جائز صرف غلہ یا تیار کھانے کی اشیاء میں سے بقدر ضرورت لینا ہے۔","صحیح",{"u2":"ایک انصاری صحابی نے کہا: ہم لوگ ایک سفر میں رسول اللہ صلی اللہ علیہ وسلم کے ساتھ روانہ ہوئے۔ لوگوں کو انتہائی احتیاج اور بڑی مشقت کا سامنا کرنا پڑا۔ انہیں بکریاں مل گئیں جو انہوں نے لوٹ لیں (اور تقسیم نہ کیں) ہمارے دیگچے ابل رہے تھے۔ (گوشت پک رہا تھا) کہ رسول اللہ صلی اللہ علیہ وسلم اپنی قوس کے سہارے چلتے ہوئے تشریف لائے اور ہمارے دیگچوں کو اپنی قوس سے الٹ دیا اور گوشت کو مٹی میں لتھیڑنے لگے اور فرمایا ” لوٹ کا مال مردار سے زیادہ حلال نہیں۔ “ یا یوں فرمایا ” مردار کا گوشت لوٹ کے مال سے زیادہ حلال نہیں۔ “ یہ شک ہناد کو ہوا ہے۔","f2":"بلا ضرورت شرعی مشترکہ غنیمت میں سے کچھ لینا ناجائز ہے۔ہاں اگرجہادی ضرورت کے پیش نظر اشد ضرورت ہو تو لے سکتاہے۔امیر سے اجازت لے اور اس کی کما حقہ حفاظت کرے۔اور ضرورت پوری ہونے پر بروقت واپس کردے۔ضائع کر کے واپس دیناجرم ہے۔ اور ملی امانتوں کا یہی حکم ہے۔"}],[2706,"بعض صحابہ کرام سے روایت ہے کہ ہم نبی اکرم صلی اللہ علیہ وسلم کے زمانہ میں غزوات میں گاجر کھاتے تھے، ہم اسے تقسیم نہیں کرتے تھے یہاں تک کہ ہم اپنے مکانوں کی طرف لوٹتے اور ہمارے برتن اس سے بھرے ہوتے تھے۔","ضعیف",{"u2":"اصحاب نبی کریم صلی اللہ علیہ وسلم میں سے ایک صحابی کا بیان ہے کہا کہ جہاد کے دوران میں ہم اونٹ ذبح کر کے کھاتے اور (باقاعدہ) تقسیم نہ کرتے حتیٰ کہ جب ہم واپس لوٹتے ہمارے تھیلے اس گوشت سے بھرے ہوئے ہوتے تھے۔"}],[2707,"عبدالرحمٰن بن غنم کہتے ہیں کہ ہم نے شرحبیل بن سمط کے ساتھ شہر قنسرین کا محاصرہ کیا، جب آپ نے اس شہر کو فتح کیا تو وہاں بکریاں اور گائیں ملیں تو ان میں سے کچھ تو ہم میں تقسیم کر دیں اور کچھ مال غنیمت میں شامل کر لیں، پھر میری ملاقات معاذ بن جبل رضی اللہ عنہ سے ہوئی، میں نے ان سے بیان کیا، تو آپ نے کہا: ہم نے رسول اللہ صلی اللہ علیہ وسلم کے ساتھ غزوہ خیبر کیا تو ہمیں اس میں بکریاں ملیں تو آپ صلی اللہ علیہ وسلم نے ایک حصہ ہم میں تقسیم کر دیا اور بقیہ حصہ مال غنیمت میں شامل کر دیا ۱؎۔\n§وضاحت\n۱؎ : گویا کھانے پینے کی چیزیں حسب ضرورت مجاہدین میں تقسیم کر دی جائیں گی اور بقیہ مال غنیمت میں شامل کر دیا جائے گا ان کا بیچنا صحیح نہیں ہو گا، یہی باب سے مطابقت ہے۔","حسن",{"u2":"سیدنا عبدالرحمٰن بن غنم رضی اللہ عنہ کا بیان ہے کہ ہم نے سیدنا شرجیل بن سمط رضی اللہ عنہ کی معیت میں قنسرین شہر کا محاصرہ کیا۔ جب انہوں نے اس کو فتح کر لیا تو وہاں سے انہیں بکریاں اور گائیں ملیں۔ انہوں نے ان میں سے ایک حصہ ہم میں تقسیم کر دیا اور باقی کو غنیمت میں جمع کر لیا۔ پھر میں (عبدالرحمٰن بن غنم) سیدنا معاذ بن جبل رضی اللہ عنہ سے ملا اور یہ سب بتایا، تو انہوں نے کہا: ہم نے رسول اللہ صلی اللہ علیہ وسلم کے ساتھ غزوہ خیبر میں شرکت کی، پس ہمیں بکریاں ملیں، تو رسول اللہ صلی اللہ علیہ وسلم نے کچھ کو ہم میں تقسیم کر دیا (کھانے کے لیے) اور باقی کو مال غنیمت میں شامل کر لیا۔","f2":"مطعومات سے جو استعمال ہوجائے اسے استعمال کرلیا جائے۔اور بقیہ کو بطور غنیمت جمع رکھا جائے تاکہ بعد میں خمس (پانچواں حصہ)نکال کر حصوں کے مطابق تقسیم کیاجاسکے۔اسے فروخت نہ کیاجائے ہاں ہر شخص اپنا حصہ وصول کرلینے کے بعد اس میں جو تصرف کرے۔اس کا حق ہے۔"}],[2708,"رویفع بن ثابت انصاری رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"جو شخص اللہ اور یوم آخرت پر ایمان رکھتا ہو تو وہ مسلمانوں کی غنیمت کے کسی جانور پر سوار نہ ہو کہ اسے جب دبلا کر ڈالے تو مال غنیمت میں واپس لوٹا دے، اور جو شخص اللہ اور یوم آخرت پر ایمان رکھتا ہو تو وہ مسلمانوں کی غنیمت سے کوئی کپڑا نہ پہنے کہ جب اسے پرانا کر دے تو اسے غنیمت کے مال میں واپس کر دے ۱؎\"۔\n§وضاحت\n۱؎ : حاصل یہ ہے کہ غنیمت کے مال میں کھانے کی چیزوں کے علاوہ کسی چیز کا استعمال بلا ضرورت درست نہیں۔","حسن صحیح",{"u2":"سیدنا رویفع بن ثابت انصاری رضی اللہ عنہ نے بیان کیا کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا ” جس شخص کا ا اللہ اور قیامت پر ایمان ہے، اسے روا نہیں کہ مسلمانوں کی غنیمت میں سے کسی جانور پر سواری کرتا رہے حتیٰ کہ جب اسے لاغر کر ڈالے تو اسے غنیمت میں واپس کر دے۔ اور جس کا ا اللہ اور قیامت پر ایمان ہے اسے جائز نہیں کہ مسلمانوں کی غنیمت میں سے کپڑا پہنے اور جب اسے بوسیدہ کر دے تو وہ اسے اس میں واپس کر دے۔ “","f2":"اللہ تعالیٰ نے مقررہ حقوق والی چیزوں میں بقدرحق لینا۔ اور عام جائز چیزوں میں ایک دوسرے کا لہاظ کرنے اور ہمدردی برتنے کا حکمدیا ہے۔ جبکہ لوٹ اور چھینا جھپٹی میں استحقاق کی بجائے زور بازو س کام لیاجاتا ہے۔اور کسی کو زیادہ اور کسی کو کم ملتا ہے۔ اور کئی محروم رہ جاتے ہیں۔اس لئے یہ طرز عمل جائز نہیں۔"}],[2709,"عبداللہ بن مسعود رضی اللہ عنہ کہتے ہیں کہ میں (غزوہ بدر میں) گزرا تو ابوجہل کو پڑا ہوا دیکھا، اس کا پاؤں زخمی تھا، میں نے کہا: اللہ کے دشمن! ابوجہل! آخر اللہ نے اس شخص کو جو اس کی رحمت سے دور تھا ذلیل کر ہی دیا، عبداللہ بن مسعود رضی اللہ عنہ کہتے ہیں کہ اس وقت میں اس سے ڈر نہیں رہا تھا، اس پر اس نے کہا: اس سے زیادہ تو کوئی بات نہیں ہوئی ہے کہ ایک شخص کو اس کی قوم نے مار ڈالا اور یہ کوئی عار کی بات نہیں، پھر میں نے اسے کند تلوار سے مارا لیکن وار کارگر نہ ہوا یہاں تک کہ اس کی تلوار اس کے ہاتھ سے گر پڑی، تو اسی کی تلوار سے میں نے اس کو (دوبارہ) مارا یہاں تک کہ وہ ٹھنڈا ہو گیا۔","صحیح",{"u2":"سیدنا ابوعبیدہ اپنے والد (سیدنا عبداللہ بن مسعود رضی اللہ عنہ) سے روایت کرتے ہیں کہ (غزوہ بدر میں) میں ابوجہل کے پاس سے گزرا۔ وہ گرا پڑا تھا اور اس کی ٹانگ پر ضرب لگی تھی۔ میں نے اس سے کہا: اے ا اللہ کے دشمن! اے ابوجہل! (بالآخر) ا اللہ نے (تجھ) کمینے کو ذلیل کر ہی دیا (ابن مسعود رضی اللہ عنہ) کہتے ہیں کہ مجھے اس وقت اس سے کوئی خوف نہ تھا۔ تو اس نے کہا: تعجب (اور حسرت) ہے اس آدمی پر کہ اس کی اپنی ہی قوم نے اسے قتل کر دیا تو میں نے اس کو اپنی تلوار سے مارا جو کند سی تھی اور اس نے کوئی فائدہ نہ دیا۔ (اسے قتل نہ کر سکی۔) لیکن اس کے ہاتھ سے اس کی تلوار گر گئی، تب میں نے اس سے اس کو مارا حتیٰ کہ ٹھنڈا ہو گیا۔","f2":"حضرت ابن مسعود رضی اللہ تعالیٰ عنہ نے کافر ہی کی تلوار سے فائدہ اٹھاتے ہوئے اسے قتل کیا۔اور یہ استفادہ تقسیم سے پہلے کیا گیا جو بالکل بجا تھا۔ابو جہل کا مختصر بیان پیچھے حدیث 680 میں دیکھیں۔"}],[2710,"زید بن خالد جہنی رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم کے ایک صحابی کا غزوہ خیبر کے دن انتقال ہو گیا، لوگوں نے اس کا ذکر رسول اللہ صلی اللہ علیہ وسلم سے کیا تو آپ نے فرمایا: \"اپنے ساتھی کی نماز جنازہ پڑھ لو\"، یہ سن کر لوگوں کے چہرے بدل گئے، تو آپ صلی اللہ علیہ وسلم نے فرمایا: \"تمہارے ساتھی نے جہاد میں خیانت کی ہے\"، پھر جب ہم نے اس کا سامان ڈھونڈا تو یہود کے مونگوں میں سے ہمیں چند مونگے ملے جس کی قیمت دو درہم کے برابر بھی نہ تھی۔","ضعیف",{"u2":"سیدنا زید بن خالد جہنی رضی اللہ عنہ کا بیان ہے کہ خیبر کے روز اصحاب نبی کریم صلی اللہ علیہ وسلم میں سے ایک شخص وفات پا گیا۔ لوگوں نے رسول اللہ صلی اللہ علیہ وسلم کو اس کی خبر دی تو آپ صلی اللہ علیہ وسلم نے فرمایا ” تم لوگ اپنے ساتھی کا جنازہ پڑھ لو۔ “ اس سے لوگوں کے چہرے فق ہو گئے۔ آپ صلی اللہ علیہ وسلم نے فرمایا ” تمہارے اس ساتھی نے ا اللہ کی راہ میں ہوتے ہوئے خیانت (یا چوری) کی ہے۔ “ ہم نے اس کے سامان کی تلاشی لی تو ہمیں اس میں ایسے مونگے ملے جو یہودی لوگ استعمال کرتے تھے (شاید ان کی عورتیں استعمال کرتی ہوں) ان کی قیمت دو درہم بھی نہ تھی۔"}],[2711,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ ہم رسول اللہ صلی اللہ علیہ وسلم کے ساتھ خیبر کے سال نکلے، تو ہمیں غنیمت میں نہ سونا ہاتھ آیا نہ چاندی، البتہ کپڑے اور مال و اسباب ملے، رسول اللہ صلی اللہ علیہ وسلم وادی القری کی جانب چلے اور آپ کو ایک کالا غلام ہدیہ میں دیا گیا تھا جس کا نام مدعم تھا، جب لوگ وادی القری میں پہنچے تو مدعم آپ صلی اللہ علیہ وسلم کے اونٹ کا پالان اتار رہا تھا، اتنے میں اس کو ایک تیر آ لگا اور وہ مر گیا، لوگوں نے کہا: اس کے لیے جنت کی مبارک بادی ہو، نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"ہرگز نہیں، قسم ہے اس ذات کی جس کے ہاتھ میں میری جان ہے! وہ چادر جو اس نے خیبر کی لڑائی میں غنیمت کے مال سے تقسیم سے قبل لی تھی اس پر آگ بن کر بھڑک رہی ہے\"، جب لوگوں نے یہ سنا تو ایک شخص ایک یا دو تسمے لے کر رسول اللہ صلی اللہ علیہ وسلم کے پاس آیا، تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"یہ آگ کا ایک تسمہ ہے\" یا فرمایا: \"آگ کے دو تسمے ہیں\"۔","صحیح",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ ہم خیبر کے سال رسول اللہ صلی اللہ علیہ وسلم کے ساتھ روانہ ہوئے تو ہمیں سونے چاندی کی بجائے عام کپڑے اور دیگر مال و متاع غنیمت میں حاصل ہوا۔ پھر آپ صلی اللہ علیہ وسلم وادی القریٰ کی طرف روانہ ہو گئے۔ آپ کو ایک غلام ہدیہ کیا گیا تھا جس کا نام مدعم تھا۔ جب ہم وادی القریٰ پہنچے اور مدعم رسول اللہ صلی اللہ علیہ وسلم کے اونٹ سے پالان اتار رہا تھا کہ اسے ایک تیر آن لگا جس سے وہ قتل ہو گیا۔ لوگوں نے کہا: اسے جنت مبارک ہو (کہ اسے دوران جہاد میں رسول اللہ صلی اللہ علیہ وسلم کی خدمت کرتے ہوئے موت آئی ہے) تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” ہرگز نہیں، قسم اس ذات کی جس کے ہاتھ میں میری جان ہے! بلاشبہ وہ چادر جو اس نے خیبر کے روز تقسیم سے پہلے غنیمت میں سے اٹھائی تھی وہ اس پر آگ بن کر بھڑک رہی ہے۔ “ لوگوں نے جب یہ سنا تو کوئی ایک تسمہ لے آیا تو کوئی دو تسمے اور رسول اللہ صلی اللہ علیہ وسلم کے حوالے کر دیے۔ پس رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” ایک تسمہ آگ کا تھا۔ “ یا فرمایا ” دو تسمے آگ کے تھے۔ “","f2":"ملی امانتوں کا معاملہ انتہائی سخت ہے۔ بلا اجازت امیر یا بلااستحقاق کوئی معمولی چیز بھی اٹھا لینا بہت بڑے عقاب کا باعث ہے۔"}],[2712,"عبداللہ بن عمرو رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم کو جب مال غنیمت حاصل ہوتا تو آپ بلال رضی اللہ عنہ کو حکم دیتے کہ وہ لوگوں میں اعلان کر دیں کہ لوگ اپنا مال غنیمت لے کر آئیں، پھر آپ صلی اللہ علیہ وسلم اس میں سے خمس (پانچواں حصہ)نکال کر باقی مجاہدین میں تقسیم کر دیتے، ایک شخص اس تقسیم کے بعد بال کی ایک لگام لے کر رسول اللہ صلی اللہ علیہ وسلم کے پاس آیا اور اس نے کہا: اللہ کے رسول! یہ بھی اسی مال غنیمت میں سے ہے جو ہمیں ملا تھا، آپ صلی اللہ علیہ وسلم نے فرمایا: \"کیا تم نے بلال رضی اللہ عنہ کو تین مرتبہ آواز لگاتے سنا ہے؟\" اس نے کہا: ہاں، آپ صلی اللہ علیہ وسلم نے فرمایا: \"پھر اسے لانے سے تمہیں کس چیز نے روکے رکھا؟\" تو اس نے آپ سے کچھ عذر بیان کیا، آپ صلی اللہ علیہ وسلم نے فرمایا: \"جاؤ لے جاؤ، قیامت کے دن لے کر آنا، میں تم سے اسے ہرگز قبول نہیں کروں گا\"۔","حسن",{"u2":"سیدنا عبداللہ بن عمرو رضی اللہ عنہ کا بیان ہے کہ رسول اللہ صلی اللہ علیہ وسلم کو جب غنیمت حاصل ہوتی تو بلال کو حکم دیتے اور وہ اعلان کرتے اور لوگ اپنی اپنی غنیمتیں لے آتے۔ پھر آپ اس میں سے خمس (پانچواں حصہ) نکالتے اور پھر تقسیم کر دیتے۔ ایک بار ایک آدمی اس اعلان اور تقسیم کے بعد بالوں سے بنی ہوئی ایک لگام لے آیا۔ اس نے کہا: اے ا اللہ کے رسول! یہ ہمیں غنیمت میں ملی تھی۔ آپ صلی اللہ علیہ وسلم نے اس سے پوچھا ” کیا تو نے بلال کو منادی کرتے سنا تھا؟ “ آپ صلی اللہ علیہ وسلم نے تین بار پوچھا۔ تو اس نے کہا: ہاں۔ آپ صلی اللہ علیہ وسلم نے کہا: ” تو (اس وقت) تجھے یہ لے آنے سے کیا رکاوٹ تھی؟ “ اس نے عذر معذرت کی مگر آپ صلی اللہ علیہ وسلم نے فرمایا ” اب اسے اپنے پاس رکھو، قیامت کے دن لے آنا، میں اسے تجھ سے ہرگز قبول نہیں کرتا۔ “","f2":"1۔عام معاملات میں نبی کریم صلی اللہ علیہ وسلم انتہائی نرم اور رقیق القلب تھے۔ مگر حدود اللہ اور حقوق العباد کے معاملے میں انتہائی سخت تھے۔2۔دنیا کی سزا جتنی بھی ہو آخرت کے عذاب کے مقابلے میں تھوڑی ہلکی اور ختم ہونے والی ہوتی ہے۔اورآخرت کا عذاب ناقابل بیان حد تک سخت ہے۔3۔نبی کریم صلی اللہ علیہ وسلم کا قول قبول کرنے سے انکارکرنے سے مقصد اس جرم کی شناعت وقباحت کو واضح کرنا تھا۔اس کا مطلب یہ نہیں تھا کہ اس کی توبہ غیر مقبول تھی یا اس مال کو اس کے مستحقین میں پہنچانا ناممکن تھا۔اور بعض نے اس کی توجیہ اس طرح کی ہے۔کہ اس مال غنیمت میں تمام مجاہدین کا حصہ تھا۔اور وہ سب متفرق ہوچکے تھے۔اس میں سے ہرایک کو اس کا حصہ پہنچانا نا ممکن تھا۔ اس لئے اس حصے کو اس کے پاس ہی رہنے دیاگیا تاکہ اس کا وبال اسی پر پڑے۔اور وہی اس کی سزا بھگتے۔اس میں بھی گویا وعید شدید کا پہلو ہے۔(عون)"}],[2713,"صالح بن محمد بن زائدہ کہتے ہیں کہ میں مسلمہ کے ساتھ روم کی سر زمین میں گیا تو وہاں ایک شخص لایا گیا جس نے مال غنیمت میں چوری کی تھی، انہوں نے سالم سے اس سلسلہ میں مسئلہ پوچھا تو سالم بن عبداللہ نے کہا: میں نے اپنے والد کو بیان کرتے ہوئے سنا وہ عمر بن خطاب رضی اللہ عنہ سے اور وہ نبی اکرم صلی اللہ علیہ وسلم سے روایت کر رہے تھے آپ نے فرمایا کہ جب تم کسی ایسے شخص کو پاؤ کہ جس نے مال غنیمت میں خیانت کی ہو تو اس کا سامان جلا دو، اور اسے مارو۔ راوی کہتے ہیں: ہمیں اس کے سامان میں ایک مصحف بھی ملا تو مسلمہ نے سالم سے اس کے متعلق پوچھا، انہوں نے کہا: اسے بیچ دو اور اس کی قیمت صدقہ کر دو۔","ضعیف",{"u2":"صالح بن محمد زائدہ کہتے ہیں کہ میں مسلمہ بن عبدالملک کی معیت میں رومی علاقے میں گیا تو ایک آدمی لایا گیا جس نے غنیمت میں خیانت کی تھی۔ انہوں نے سالم بن عبداللہ بن عمر سے اس کے متعلق پوچھا، تو انہوں نے کہا: میں نے اپنے والد سے سنا وہ سیدنا عمر بن خطاب رضی اللہ عنہ سے وہ نبی کریم صلی اللہ علیہ وسلم سے بیان کرتے تھے، آپ نے فرمایا ” جب تم کسی کو پاؤ کہ اس نے غنیمت میں خیانت کی ہو تو اس کا مال و اسباب جلا ڈالو اور اسے مارو۔ “ کہتے ہیں کہ پھر ہم نے اس کے سامان میں قرآن مجید کا ایک نسخہ پایا۔ مسلمہ نے اس کے بارے میں جناب سالم سے دریافت کیا تو انہوں نے کہا: اسے فروخت کرو اور اس کی قیمت صدقہ کر دو۔"}],[2714,"صالح بن محمد کہتے ہیں کہ ہم نے ولید بن ہشام کے ساتھ غزوہ کیا اور ہمارے ساتھ سالم بن عبداللہ بن عمر اور عمر بن عبدالعزیز بھی تھے، ایک شخص نے مال غنیمت سے ایک سامان چرا لیا تو ولید بن ہشام کے حکم سے اس کا سامان جلا دیا گیا، پھر وہ سب لوگوں میں پھرایا گیا اور اسے اس کا حصہ بھی نہیں دیا گیا۔ ابوداؤد کہتے ہیں: دونوں حدیثوں میں سے یہ حدیث زیادہ صحیح ہے، اسے کئی لوگوں نے روایت کیا ہے کہ ولید بن ہشام نے زیاد بن سعد کے ساز و سامان کو اس لیے جلوا دیا تھا کہ اس نے مال غنیمت میں خیانت کی تھی، اور اسے زد و کوب بھی کیا۔","ضعیف",{"u2":"صالح بن محمد کہتے ہیں کہ ہم نے ولید بن ہشام کی معیت میں جہاد کیا اور ہمارے ساتھ جناب سالم بن عبداللہ بن عمر اور عمر بن عبدالعزیز رضی اللہ عنہ بھی تھے۔ ایک شخص نے غنیمت میں کچھ خیانت کر لی۔ پس ولید نے اس کے اسباب کے متعلق حکم دیا تو اسے جلا دیا گیا، پھر اسے لشکر میں گھمایا گیا اور غنیمت کے حصے سے بھی اسے محروم کر دیا۔ امام ابوداؤد رضی اللہ عنہ فرماتے ہیں یہ (موقوف) روایت پہلی کی نسبت زیادہ صحیح ہے۔ کئی ایک نے روایت کیا ہے کہ ولید بن ہشام نے زیاد بن سعد کا اسباب جلا دیا تھا کیونکہ اس نے غنیمت میں خیانت کی تھی اور اسے مارا بھی تھا۔"}],[2715,"عبداللہ بن عمرو بن العاص رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم اور ابوبکر و عمر رضی اللہ عنہما نے خیانت کرنے والے کے سامان کو جلا دیا اور اسے مارا۔ ابوداؤد کہتے ہیں: علی بن بحر نے اس حدیث میں ولید سے اتنا اضافہ کیا ہے کہ اسے اس کا حصہ نہیں دیا، لیکن میں نے یہ زیادتی علی بن بحر سے نہیں سنی ہے۔ ابوداؤد کہتے ہیں: اسے ہم سے ولید بن عتبہ اور عبدالوہاب بن نجدہ نے بھی بیان کیا ہے ان دونوں نے کہا اسے ہم سے ولید (ولید بن مسلم) نے بیان کیا ہے انہوں نے زہیر بن محمد سے زہیر نے عمرو بن شعیب سے موقوفاً روایت کیا ہے اور عبدالوہاب بن نجدہ حوطی نے \"حصہ سے محروم کر دینے\" کا ذکر نہیں کیا ہے۔","ضعیف",{"u2":"عمرو بن شعیب اپنے والد سے وہ دادا سے روایت کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم، سیدنا ابوبکر رضی اللہ عنہ اور سیدنا عمر رضی اللہ عنہما نے غنیمت میں خیانت کرنے والے کا مال جلایا اور اسے مارا پیٹا۔ امام ابوداؤد رضی اللہ عنہ کہتے ہیں: علی بن بحر نے بواسطہ ولید مزید کہا ہے: انہوں نے اسے اس کے غنیمت کے حصے سے محروم رکھا مگر میں (ابوداؤد) نے اس سے یہ نہیں سنا ہے۔\nامام ابوداؤد رضی اللہ عنہ نے کہا: اور ہمیں یہ روایت ولید بن عتبہ اور عبدالوہاب بن نجدہ نے بسند ولید، زہیر بن محمد، عمرو بن شعیب کا اپنا قول بتایا۔ اور عبدالوہاب بن نجدہ حوطی نے غنیمت کا حصہ نہ دینے کا ذکر نہیں کیا۔"}],[2716,"سمرہ بن جندب رضی اللہ عنہ سے روایت ہے انہوں نے حمد و صلاۃ کے بعد کہا: رسول اللہ صلی اللہ علیہ وسلم فرماتے تھے: \"جو شخص غنیمت میں خیانت کرنے والے کی خیانت کو چھپائے تو وہ بھی اسی جیسا ہے\"۔","ضعیف",{"u2":"سیدنا سمرہ بن جندب رضی اللہ عنہ نے (خطبے میں بیان کیا) امابعد! اور رسول اللہ صلی اللہ علیہ وسلم فرمایا کرتے تھے ” جس نے غنیمت میں کسی خائن کی خیانت پر پردہ ڈالا تو وہ بھی اسی خائن کی طرح ہے۔ “","f2":"یہ حدیث گو ضعیف ہے۔لیکن معناً صحیح ہے۔یعنی یہ بات جو اس میں کہی گئی ہے۔وہ دوسرے دلائل کی رو سے صحیح ہے۔"}],[2717,"ابوقتادہ رضی اللہ عنہ کہتے ہیں کہ ہم رسول اللہ صلی اللہ علیہ وسلم کے ساتھ حنین کے سال نکلے، جب کافروں سے ہماری مڈبھیڑ ہوئی تو مسلمانوں میں بھگدڑ مچ گئی، میں نے مشرکین میں سے ایک شخص کو دیکھا کہ وہ ایک مسلمان پر چڑھا ہوا ہے، تو میں پلٹ پڑا یہاں تک کہ اس کے پیچھے سے اس کے پاس آیا اور میں نے تلوار سے اس کی گردن پر مارا تو وہ میرے اوپر آ پڑا، اور مجھے ایسا دبوچا کہ میں نے اس سے موت کی مہک محسوس کی، پھر اسے موت آ گئی اور اس نے مجھے چھوڑ دیا، پھر میں عمر بن خطاب رضی اللہ عنہ سے ملا اور ان سے پوچھا کہ لوگوں کا کیا حال ہے؟ انہوں نے کہا: وہی ہوا جو اللہ کا حکم تھا، پھر لوگ لوٹے اور رسول اللہ صلی اللہ علیہ وسلم بیٹھ گئے اور فرمایا: \"جس شخص نے کسی کافر کو قتل کیا ہو اور اس کے پاس گواہ ہو تو اس کا سامان اسی کو ملے گا ۱؎\"۔ ابوقتادہ رضی اللہ عنہ کہتے ہیں:(جب میں نے یہ سنا) تو میں اٹھ کھڑا ہوا، پھر میں نے سوچا میرے لیے کون گواہی دے گا یہی سوچ کر بیٹھ گیا، پھر آپ صلی اللہ علیہ وسلم نے دوسری بار فرمایا: \"جو شخص کسی کافر کو قتل کر دے اور اس کے پاس گواہ ہو تو اس کا سامان اسی کو ملے گا\"۔ ابوقتادہ رضی اللہ عنہ کہتے ہیں (جب میں نے یہ سنا) تو اٹھ کھڑا ہوا، پھر میں نے سوچا میرے لیے کون گواہی دے گا یہی سوچ کر بیٹھ گیا۔ پھر آپ صلی اللہ علیہ وسلم نے تیسری مرتبہ یہی بات کہی پھر میں اٹھ کھڑا ہوا، تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"ابوقتادہ کیا بات ہے؟\" میں نے آپ سے سارا معاملہ بیان کیا، تو قوم کے ایک آدمی نے کہا: اللہ کے رسول! یہ سچ کہہ رہے ہیں اور اس مقتول کا سامان میرے پاس ہے، آپ ان کو اس بات پر راضی کر لیجئے (کہ وہ مال مجھے دے دیں) اس پر ابوبکر صدیق رضی اللہ عنہ نے کہا: اللہ کی قسم! رسول اللہ صلی اللہ علیہ وسلم کبھی بھی ایسا نہ کریں گے کہ اللہ کے شیروں میں سے ایک شیر اللہ اور اس کے رسول کی طرف سے لڑے اور سامان تمہیں مل جائے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"وہ سچ کہہ رہے ہیں، تم اسے ابوقتادہ کو دے دو\"۔ ابوقتادہ رضی اللہ عنہ کہتے ہیں: اس نے مجھے دے دیا، تو میں نے زرہ بیچ دی اور اس سے میں نے ایک باغ قبیلہ بنو سلمہ میں خریدا، اور یہ پہلا مال تھا جو میں نے اسلام میں حاصل کیا۔\n§وضاحت\n۱؎ : جنگ حنین میں مسلمان تعداد میں زیادہ تھے، لیکن تعلي اور کثرت تعداد کے زعم کی وجہ سے انہیں شکست ہوئی، میدان جنگ سے لوگ بھاگ کھڑے ہوئے، رسول اکرم صلی اللہ علیہ وسلم اور چند جانثار صحابہ رہ گئے تھے، بھگدڑ سے یہی مراد ہے، بعد میں جنگ کا پانسہ پلٹا اور مسلمان فتح یاب ہوئے۔","صحیح",{"u2":"سیدنا ابوقتادہ رضی اللہ عنہ بیان کرتے ہیں کہ ہم رسول اللہ صلی اللہ علیہ وسلم کی معیت میں حنین کی طرف روانہ ہوئے۔ جب کفار کے مقابلے میں آئے، تو مسلمانوں میں بہت گڑبڑ مچی۔ میں نے ایک کافر کو دیکھا کہ وہ ایک مسلمان پر چڑھائی کر رہا تھا۔ میں گھوم کر اس کے پیچھے سے آیا اور اس کی گردن کے پاس تلوار ماری، تو وہ میری طرف آیا اور مجھے (پکڑ کر) اس قدر بھینچا کہ میں نے اس سے موت کی بو پائی۔ پھر اسے موت آ گئی اور اس نے مجھے چھوڑ دیا۔ میں سیدنا عمر بن خطاب رضی اللہ عنہ سے ملا اور ان سے کہا: لوگوں کو کیا ہو گیا ہے؟ (کہ بھاگ کھڑے ہوئے ہیں) انہوں نے کہا: بس یہ ا اللہ کا کرنا ہے۔ پھر لوگ لوٹ آئے۔ رسول اللہ صلی اللہ علیہ وسلم بیٹھے اور فرمایا ” جس نے کسی کو قتل کیا ہو اور اس کا گواہ بھی ہو تو اس مقتول کا اسباب اسی کا ہے۔ “ (ابوقتادہ) کہتے ہیں میں کھڑا ہوا اور کہا: کوئی ہے جو میری گواہی دے؟ پھر میں بیٹھ گیا۔ رسول اللہ صلی اللہ علیہ وسلم نے دوسری بار یہی بات فرمائی کہ ” جس نے کسی کو قتل کیا ہو اور اس کا گواہ بھی ہو تو اس کا اسباب اسی کا ہے۔ “ کہتے ہیں کہ میں پھر اٹھا اور کہا: میرے متعلق گواہی کون دیتا ہے؟ پھر میں بیٹھ گیا۔ آپ صلی اللہ علیہ وسلم نے تیسری بار فرمایا، تو میں کھڑا ہوا، پس رسول اللہ صلی اللہ علیہ وسلم نے دریافت فرمایا ” ابوقتادہ! کیا بات ہے؟ “ میں نے اپنا قصہ بیان کیا۔ تو جماعت میں سے ایک آدمی نے کہا: اے ا اللہ کے رسول! یہ سچ کہتا ہے اور اس مقتول کا اسباب میرے پاس ہے۔ آپ اسے اس کے بارے میں راضی فر دیجئیے۔ سیدنا ابوبکر صدیق رضی اللہ عنہ نے کہا: نہیں، قسم ا اللہ کی! (یہ نہیں ہو سکتا) کہ وہ (کافر) ا اللہ کے شیروں میں سے ایک شیر کا قصد کرے جو ا اللہ اور اس کے رسول کی طرف سے لڑ رہا ہو، اور آپ اس کا سلب (اسباب) تجھے دے دیں؟ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” (ابوبکر نے) سچ کہا: وہ اسباب اسے دے دو۔ “ ابوقتادہ بیان کرتے ہیں چنانچہ وہ اس نے مجھے دے دیا۔ پھر میں نے زرہ بیچی تو اس سے بنی سلمہ میں ایک باغ خریدا۔ اور وہ میری پہلی جائیداد تھی جو میں نے اسلام لانے کے بعد حاصل کی۔","f2":"جو مال مقتول کے پاس ہو۔اس کاقاتل ہی اس کاحق دار سمجھا جاتاہے۔اور اسے اصطلاحا ً سلب کہتے ہیں۔یعنی لباس سواری اوراسلحہ پیچھے اس کے ٹھکانے پر جوکچھ ہو وہ اس میں شامل اور شمار نہیں ہوتا۔اس کی نقدی اورزیورات جو مخفی ہوتے ہیں۔ان کے بارے میں اختلاف ہے۔(نیل الاوطار 305/7)"}],[2718,"انس بن مالک رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے اس دن یعنی حنین کے دن فرمایا: \"جس نے کسی کافر کو قتل کیا تو اس کے مال و اسباب اسی کے ہوں گے\"، چنانچہ اس دن ابوطلحہ رضی اللہ عنہ نے بیس آدمیوں کو قتل کیا اور ان کے مال و اسباب لے لیے، ابوطلحہ رضی اللہ عنہ ام سلیم رضی اللہ عنہا سے ملے تو دیکھا ان کے ہاتھ میں ایک خنجر تھا انہوں نے پوچھا: ام سلیم! تمہارے ساتھ یہ کیا ہے؟ انہوں نے کہا: اللہ کی قسم! میں نے یہ قصد کیا تھا کہ اگر ان میں سے کوئی میرے نزدیک آیا تو اس خنجر سے اس کا پیٹ پھاڑ ڈالوں گی، تو اس کی خبر ابوطلحہ رضی اللہ عنہ نے رسول اللہ صلی اللہ علیہ وسلم کو دی۔ ابوداؤد کہتے ہیں: یہ حدیث حسن ہے، اس حدیث سے ہم نے سمجھا ہے کہ خنجر کا استعمال جائز ہے، ان دنوں اہل عجم کے ہتھیار خنجر ہوتے تھے۔","صحیح",{"u2":"سیدنا انس بن مالک رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے حنین والے دن فرمایا تھا “ جس نے کسی کافر کو قتل کیا ہو تو اس کا سلب (اسباب) اسی قاتل کا ہے۔ “ چنانچہ ابوطلحہ رضی اللہ عنہ نے اسی دن بیس آدمیوں کو قتل کیا اور ان کا سلب بھی حاصل کیا۔ ابوطلحہ رضی اللہ عنہ (اپنی بیوی) ام سلیم سے ملے جبکہ ان کے (ام سلیم) کے پاس خنجر تھا، تو پوچھا اے ام سلیم! یہ تیرے پاس کیا ہے؟ کہنے لگیں: ا اللہ کی قسم! میرا ارادہ یہ ہے کہ ان کافروں میں سے کوئی میرے قریب آیا تو میں اس سے اس کا پیٹ چیر دوں گی۔ پھر ابوطلحہ نے یہ بات رسول اللہ صلی اللہ علیہ وسلم کو بھی بتائی۔ امام ابوداؤد رضی اللہ عنہ کہتے ہیں: یہ حدیث حسن ہے۔ امام ابوداؤد رضی اللہ عنہ نے کہا: اور اس حدیث کے بیان سے ہمارا مقصد خنجر کے متعلق بتانا ہے (کہ بطور اسلحہ اس کا استعمال جائز ہے) کہ ان دنوں عجمی لوگ ہی اسے استعمال کرتے تھے۔","f2":"1۔غزوہ حنین میں ابتدائی طور پر مسلمانوں کوکچھ ہزیمت ہوئی تھی مگر بعد میں انہوں نے اپنی قوت جمع کرلی۔اور اللہ تعالیٰ نے نصر ت فرمائی۔سورہ توبہ میں اس کا ذکر موجود ہے۔ (لَقَدْ نَصَرَكُمُ اللَّـهُ فِي مَوَاطِنَ كَثِيرَةٍ ۙ وَيَوْمَ حُنَيْنٍ ۙ إِذْ أَعْجَبَتْكُمْ كَثْرَتُكُمْ فَلَمْ تُغْنِ عَنكُمْ شَيْئًا وَضَاقَتْ عَلَيْكُمُ الْأَرْضُ بِمَا رَحُبَتْ ثُمَّ وَلَّيْتُم مُّدْبِرِينَ)(التوبہ۔25) بلاشبہ اللہ عزوجل بہت سے مقامات پر تمہاری مدد کرچکاہے۔اور (یاد کرو)حنین کے روز کو جب تم اپنی کثرت پر نازاں ہوئے مگر وہ تمہارے کچھ کام نہ آئی۔اور زمین باوجود فراخی کے تم پر تنگ ہوگئی تھی۔اور تم پیٹھ پھیر کر پیچھے ہٹ گئے تھے۔ 2۔مقتول کے پاس جو ذاتی استعمال کا مال ہو وہ اس کے قاتل مجاہد کا حق ہوتاہے۔خواہ کسی قدر ہو۔نیز ا س میں سے خمس بھی نہیں لیا جاتا۔3۔ہردور میں رائج الوقت اسلحۃ استعمال کرنا چاہیے۔3۔مسلمان عورتوں کو بھی د فاع کےلئے تیار رہنا چاہیے۔تاکہ حسب ضرورت وہ اپنا دفاع کرسکیں۔"}],[2719,"عوف بن مالک اشجعی رضی اللہ عنہ کہتے ہیں کہ میں زید بن حارثہ رضی اللہ عنہ کے ساتھ غزوہ موتہ میں نکلا تو اہل یمن میں سے ایک مددی میرے ساتھ ہو گیا، اس کے پاس ایک تلوار کے سوا کچھ نہ تھا، پھر ایک مسلمان نے کچھ اونٹ ذبح کئے تو مددی نے اس سے تھوڑی سی کھال مانگی، اس نے اسے دے دی، مددی نے اس کھال کو ڈھال کی شکل کا بنا لیا، ہم چلے تو رومی فوجیوں سے ملے، ان میں ایک شخص اپنے سرخ گھوڑے پر سوار تھا، اس پر ایک سنہری زین تھی، ہتھیار بھی سنہرا تھا، تو رومی مسلمانوں کے خلاف لڑنے کے لیے اکسانے لگا تو مددی اس سوار کی تاک میں ایک چٹان کی آڑ میں بیٹھ گیا، وہ رومی ادھر سے گزرا تو مددی نے اس کے گھوڑے کے پاؤں کاٹ ڈالے، وہ گر پڑا، اور مددی اس پر چڑھ بیٹھا اور اسے قتل کر کے گھوڑا اور ہتھیار لے لیا، پھر جب اللہ عزوجل نے مسلمانوں کو فتح دی تو خالد بن ولید رضی اللہ عنہ نے مددی کے پاس کسی کو بھیجا اور سامان میں سے کچھ لے لیا۔ عوف رضی اللہ عنہ کہتے ہیں: تو میں خالد رضی اللہ عنہ کے پاس آیا اور میں نے کہا: خالد! کیا تم نہیں جانتے ہو کہ رسول اللہ صلی اللہ علیہ وسلم نے قاتل کے لیے سلب کا فیصلہ کیا ہے؟ خالد رضی اللہ عنہ نے کہا: کیوں نہیں، میں جانتا ہوں لیکن میں نے اسے زیادہ سمجھا، تو میں نے کہا: تم یہ سامان اس کو دے دو، ورنہ میں رسول اللہ صلی اللہ علیہ وسلم سے اس معاملہ کو ذکر کروں گا، لیکن خالد رضی اللہ عنہ نے لوٹانے سے انکار کیا۔ عوف رضی اللہ عنہ کہتے ہیں: ہم لوگ رسول اللہ صلی اللہ علیہ وسلم کے پاس اکٹھا ہوئے تو میں نے آپ سے مددی کا واقعہ اور خالد رضی اللہ عنہ کی سلوک بیان کیا، تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"خالد! تم نے جو یہ کام کیا ہے اس پر تمہیں کس چیز نے آمادہ کیا؟\"خالد نے کہا: اللہ کے رسول! میں نے اسے زیادہ جانا، تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"خالد! تم نے جو کچھ لیا تھا واپس لوٹا دو\"۔ عوف رضی اللہ عنہ کہتے ہیں میں نے کہا: خالد! کیا میں نے جو وعدہ کیا تھا اسے پورا نہ کیا؟ تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"وہ کیا ہے؟\" عوف رضی اللہ عنہ کہتے ہیں: میں نے اسے آپ سے بتایا۔ عوف کہتے ہیں: تو رسول اللہ صلی اللہ علیہ وسلم غصہ ہو گئے، اور فرمایا: \"خالد! واپس نہ دو، کیا تم لوگ چاہتے ہو کہ میرے امیروں کو چھوڑ دو کہ وہ جو اچھا کام کریں اس سے تم نفع اٹھاؤ اور بری بات ان پر ڈال دیا کرو\"۔","صحیح",{"u2":"سیدنا عوف بن مالک اشجعی رضی اللہ عنہ بیان کرتے ہیں کہ میں سیدنا زید بن حارثہ رضی اللہ عنہ کے ساتھ غزوہ موتہ میں روانہ ہوا۔ اہل یمن سے جو کمک ہمیں ملی ان میں سے ایک شخص میرے ساتھ ہو لیا۔ اس کے پاس سوائے ایک تلوار کے اور کچھ نہ تھا۔ مسلمانوں کے ایک آدمی نے اونٹ ذبح کیا، تو اس آدمی نے ذبح کرنے والے سے کھال کا ایک حصہ مانگا جو اس نے اس کو دے دیا۔ پس اس نے اس کو ڈھال کی طرح بنا لیا اور پھر ہم چلتے رہے۔ ہمیں رومی جماعتوں کا مقابلہ کرنا پڑا۔ ان میں ایک آدمی اپنے سرخ گھوڑے پر سوار تھا جس کی زین اور ہتھیار سنہری تھے۔ وہ رومی مسلمانوں پر بڑے سخت حملے کر رہا تھا۔ تو یمن کی کمک والا یہ آدمی ایک چٹان کی اوٹ میں اس رومی کی تاک میں بیٹھ گیا۔ جب وہ اس کے پاس سے گزرا تو اس یمنی نے اس کے گھوڑے کی ٹانگیں کاٹ ڈالیں تو وہ (رومی) گر پڑا اور یہ (یمنی) خود اس آدمی پر چڑھ بیٹھا اور اسے قتل کر دیا اور اس کا گھوڑا اور اسلحہ لے لیا۔ اور جب اللہ عزوجل نے مسلمانوں کو فتح دی تو سیدنا خالد بن ولید رضی اللہ عنہ نے اس یمنی کو بلوایا اور اس کے اسباب میں سے کچھ لے لیا۔ سیدنا عوف رضی اللہ عنہ کہتے ہیں کہ میں ان کے پاس گیا اور کہا: اے خالد! کیا آپ کو معلوم نہیں کہ رسول اللہ صلی اللہ علیہ وسلم کا فیصلہ ہے کہ سلب قاتل کا ہوتا ہے؟ انہوں نے کہا: ہاں۔ لیکن میں اسے بہت زیادہ سمجھتا ہوں۔ میں نے کہا: یا تو آپ اسے واپس کر دیں ورنہ میں آپ کی یہ بات رسول اللہ صلی اللہ علیہ وسلم کو بتاؤں گا، مگر انہوں نے اس کو واپس کرنے سے انکار کر دیا۔ سیدنا عوف رضی اللہ عنہ کہتے ہیں پھر ہم رسول اللہ صلی اللہ علیہ وسلم کے ہاں جمع ہوئے، تو میں نے آپ صلی اللہ علیہ وسلم سے اس یمنی کا قصہ بیان کیا اور وہ بھی جو خالد رضی اللہ عنہ نے کیا تھا۔ تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” خالد! اس کی کیا وجہ تھی جو تم نے کیا؟ “ انہوں نے کہا: اے ا اللہ کے رسول! میں نے اس سلب کو بہت زیادہ سمجھا تھا۔ آپ صلی اللہ علیہ وسلم نے فرمایا ” تم نے جو کچھ اس سے لیا وہ اس کو واپس کر دو۔ “ عوف کہتے ہیں میں نے خالد سے کہا: خالد! لو اب میں نے جو بات کہی تھی پوری کر دی؟ رسول اللہ صلی اللہ علیہ وسلم نے پوچھا “ وہ کیا بات تھی؟ “ میں نے انہیں بتا دی، تو رسول ا اللہ صلی اللہ علیہ وسلم غصے ہو گئے اور فرمایا ” خالد! وہ مت واپس کرو، کیا تم لوگ میری خاطر میرے امراء سے کوئی رعایت نہیں کر سکتے؟ (یہ کیسے ہو سکتا ہے کہ) ان کے معاملات کی عمدگی اور بھلائی تو تمہارے لیے ہو اور اس کی خرابی کے وہ ہی ذمہ دار ہوں۔ “"}],[2720,"اس سند سے بھی عوف بن مالک اشجعی رضی اللہ عنہ سے اسی طرح مروی ہے۔","صحیح",{"u2":"عبدالرحمٰن بن جبیر بن نفیر اپنے والد سے، وہ سیدنا عوف بن مالک اشجعی رضی اللہ عنہ سے اس حدیث کی مانند روایت کرتے ہیں۔","f2":"انتظامی معاملات میں امیر مجتہد کو کسی قدرتصرف کا حق حاصل ہوتاہے۔اور لوگوں کومناسب نہیں کہ حکام وامراء کوہرمعاملے میں تنقید کی سان پر چڑھائے رکھیں۔"}],[2721,"عوف بن مالک اشجعی اور خالد بن ولید رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے سلب کا فیصلہ قاتل کے لیے کیا، اور سلب سے خمس نہیں نکالا۔","صحیح",{"u2":"سیدنا عوف بن مالک اشجعی اور خالد بن ولید رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے سلب کے متعلق فیصلہ فرمایا کہ یہ قاتل کا حق ہے اور اس میں سے خمس نہیں نکالا۔"}],[2722,"عبداللہ بن مسعود رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے مجھے بدر کے دن ابوجہل کی تلوار بطور نفل دی اور انہوں نے ہی اسے قتل کیا تھا ۱؎۔\n§وضاحت\n۱؎ : چونکہ عبداللہ بن مسعود رضی اللہ عنہ ہی نے ابوجہل کے سر کو اس کے جسم سے (جب اس میں جان باقی تھی) جدا کیا تھا اسی لئے اس کی تلوار آپ نے انہی کو دی، ورنہ اس کے قاتل اصلاً معاذ بن عمرو بن جموح اور معاذ بن عفراء رضی اللہ عنہما ہیں۔","ضعیف",{"u2":"سیدنا عبداللہ بن مسعود رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے بدر کے روز مجھے ابوجہل کی تلوار عنایت فرمائی۔ اس کا کام انہوں نے ہی تمام کیا تھا۔","f2":"ابو جہل کو عفراء کے بیٹوں معاذ اور معوذ اور معاذ بن عمرو بن جموح نے ذخمی کیا تھا۔اور حضرت ابن مسعود رضی اللہ تعالیٰ عنہ نے اس کی گردن کاٹی تھی۔(دیکھیے سابقہ حدیث 2680)"}],[2723,"ابوہریرہ رضی اللہ عنہ سعید بن عاص رضی اللہ عنہ سے بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے ابان بن سعید بن عاص رضی اللہ عنہما کو مدینہ سے نجد کی طرف ایک سریہ کا سردار بنا کر بھیجا تو ابان بن سعید رضی اللہ عنہ اور ان کے ساتھی رسول اللہ صلی اللہ علیہ وسلم کے پاس اس وقت آئے جب کہ آپ خیبر فتح کر چکے تھے، ان کے گھوڑوں کے زین کھجور کی چھال کے تھے، تو ابان نے کہا: اللہ کے رسول! ہمارے لیے بھی حصہ لگائیے، ابوہریرہ رضی اللہ عنہ کہتے: ہیں اس پر میں نے کہا: اللہ کے رسول! ان کے لیے حصہ نہ لگائیے، ابان نے کہا: تو ایسی باتیں کرتا ہے اے وبر! جو ابھی ہمارے پاس ضال پہاڑ کی چوٹی سے اتر کے آ رہا ہے تو نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"ابان تم بیٹھ جاؤ\"، اور رسول اللہ صلی اللہ علیہ وسلم نے ان کا حصہ نہیں لگایا۔","صحیح",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ، سیدنا سعید بن عاص رضی اللہ عنہ سے بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے ابان بن سعید بن عاص کو مدینہ منورہ سے نجد کی جانب ایک جہادی مہم پر روانہ کیا۔ پس ابان بن سعید اور اس کے ساتھی رسول اللہ صلی اللہ علیہ وسلم کے پاس خیبر میں پہنچے جبکہ آپ صلی اللہ علیہ وسلم نے خیبر کو فتح کر لیا تھا۔ ابان بن سعید اور ان کے ساتھیوں کے گھوڑے تنگ (زین کسنے کے چوڑے تسمے، یا لگام) کھجور کی چھال کے تھے۔ تو ابان نے کہا: اے ا اللہ کے رسول! ہمیں بھی عنایت فرمائیے۔ سیدنا ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ میں نے کہا: اے ا اللہ کے رسول! انہیں مت دیجئیے۔ ابان بولے «أنت بها يا وبر»! تم یہ کہہ رہے ہو اور (کہاں سے) ہمارے پاس ضال (پہاڑ) کی چوٹی سے اتر آئے ہو؟ نبی کریم صلی اللہ علیہ وسلم نے فرمایا ” ابان بیٹھ جاؤ۔ “ اور رسول اللہ صلی اللہ علیہ وسلم نے ان کو غنیمت میں سے کچھ نہ دیا۔"}],[2724,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ میں مدینہ اس وقت آیا جب خیبر فتح ہوا، رسول اللہ صلی اللہ علیہ وسلم خیبر میں تھے، میں نے آپ صلی اللہ علیہ وسلم سے درخواست کی کہ مجھے بھی حصہ دیجئیے ۱؎ تو سعید بن عاص رضی اللہ عنہ کے لڑکوں میں سے کسی نے کہا: اللہ کے رسول! اسے حصہ نہ دیجئیے، تو میں نے کہا: ابن قوقل کا قاتل یہی ہے، تو سعید بن عاص رضی اللہ عنہ نے کہا: تعجب ہے ایک وبر پر جو ہمارے پاس ضال کی چوٹی سے اتر کر آیا ہے مجھے ایک مسلمان کے قتل پر عار دلاتا ہے جسے اللہ نے میرے ہاتھوں عزت دی اور اس کے ہاتھ سے مجھ کو ذلیل نہیں کیا ۲؎۔ ابوداؤد کہتے ہیں: یہ لوگ نو یا دس افراد تھے جن میں سے چھ شہید کر دیئے گئے اور باقی واپس آئے۔\n§وضاحت\n۱؎ : اس سے پہلی والی حدیث میں ہے کہ ابان رضی اللہ عنہ نے رسول اللہ صلی اللہ علیہ وسلم سے درخواست کی تھی کہ آپ ان کے لئے حصہ لگائیں اور اس حدیث سے معلوم ہوتا ہے کہ ابوہریرہ رضی اللہ عنہ نے اپنے لئے حصہ لگانے کی درخواست کی تھی دونوں حدیثوں میں بظاہر تعارض ہے صحیح یہ ہے کہ دونوں ہی نے رسول اللہ صلی اللہ علیہ وسلم سے اپنے لئے حصہ لگانے کی درخواست کی تھی، اور اپنے اپنے نظریہ کے مطابق دوسرے کو نہ دینے کا مشورہ دیا تھا، ابان رضی اللہ عنہ کو اس لئے کہ ابن قوقل رضی اللہ عنہ کو قتل کر دیا تھا، اور ابوہریرہ رضی اللہ عنہ کو اس لئے کہ ابھی مسلمان ہوئے تھے۔ ۲؎ : انہوں نے ابن قوقل رضی اللہ عنہ کو اس وقت قتل کیا تھا جب وہ کافر تھے، ابن قوقل کو اس قتل کی وجہ سے شہادت کی عزت ملی، اس وقت ابن قوقل رضی اللہ عنہ نے اگر ابان بن سعید کو قتل کر دیا ہوتا تو وہ جہنم میں ڈالے جاتے اور ذلیل ہوتے، لیکن اللہ نے ایمان کی دولت دے کر انہیں اس ذلت سے بچا دیا۔","صحیح",{"u2":"سیدنا ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ میں مدینے پہنچا جب کہ رسول اللہ صلی اللہ علیہ وسلم خیبر میں تھے، جس وقت کہ آپ نے اسے فتح کیا تھا۔ میں نے درخواست کی کہ آپ مجھے بھی عنایت فرمائیں۔ تو سعید بن عاص کے بچوں میں سے کسی نے کہا: اے ا اللہ کے رسول! اسے مت دیجئیے۔ میں نے کہا: یہ ابن قوقل رضی اللہ عنہ کا قاتل ہے۔ تو سعید بن عاص رضی اللہ عنہ نے کہا: «يا عجبا لوبر» ضال (پہاڑ) کہ چوٹی سے ہمارے پاس اتر آیا ہے اور مجھے ایک مسلمان کے قتل پر عار دلاتا ہے جس کو اللہ عزوجل نے میرے ہاتھوں عزت بخشی (اسے شہادت نصیب ہوئی) اور مجھے اس کے ہاتھوں ذلیل نہیں کیا۔ امام ابوداؤد رضی اللہ عنہ فرماتے ہیں: یہ لوگ تقریباً دس آدمی تھے۔ ان میں سے چھ شہید ہو گئے اور باقی واپس لوٹ آئے۔","f2":"1.۔جولوگ معرکے میں کسی طرح شریک نہ ہوں۔ ان کا غنیمت میں باقاعدہ حصہ نہیں ہوتا۔البتہ امام ابو حنیفہ فرماتے ہیں۔کہ جولوگ غنیمت جمع کرلئے جانے کے بعد لشکراسلام سے جا ملیں اور غنیمت تقسیم نہ ہوئی ہو تو انھیں بھی اس میں سے حصہ ملے گا۔2۔ابن قوقل(نعمان بن قوقلرضی اللہ تعالیٰ عنہ)انصاری صحابی تھے۔ جو غزوہ احد میں ابان بن سعید کے ہاتھوں شہید ہوئے تھے۔ جب کہ ابان حدیبیہ کے بعد مسلمان ہوئے ہیں۔او رغزوہ خیبر حدیبیہ کے بعد ہواہے۔3۔پہلی روایت میں ہے کہ ابان بن سعید نے غنیمت کا مطالبہ کیاتھا۔توابو ہریرہرضی اللہ تعالیٰ عنہ نے انکارکیا تھا۔اوردوسری میں ہے کہ ابو ہریرہرضی اللہ تعالیٰ عنہ نے سوال کیا تو ابان نے انکار کیا۔حافظ منذری نے بحوالہ ابو بکر الخطیب رضی اللہ تعالیٰ عنہ دوسری روایت کو راحج کہاہے۔"}],[2725,"ابوموسی اشعری رضی اللہ عنہ کہتے ہیں کہ ہم (حبشہ سے) آئے اور رسول اللہ صلی اللہ علیہ وسلم سے فتح خیبر کے موقع پر ملے، آپ صلی اللہ علیہ وسلم نے (مال غنیمت سے) ہمارے لیے حصہ لگایا، یا ہمیں اس میں سے دیا، اور جو فتح خیبر میں موجود نہیں تھے انہیں کچھ بھی نہیں دیا سوائے ان کے جو آپ کے ساتھ حاضر اور خیبر کی فتح میں شریک تھے، البتہ ہماری کشتی والوں کو یعنی جعفر رضی اللہ عنہ اور ان کے ساتھیوں کو ان سب کے ساتھ حصہ دیا ۱؎۔\n§وضاحت\n۱؎ : ابوموسی اشعری رضی اللہ عنہ اور ان کے ساتھیوں کو مال غنیمت میں سے آپ نے جو حصہ دیا اس کے سلسلہ میں کئی اقوال ہیں : (۱) یہ حصہ آپ نے خمس سے دیا تھا، (۲) یہ لوگ تقسیم سے پہلے پہنچے تھے اس لئے انہیں منجملہ مال غنیمت سے دیا گیا، (۳) لشکر کی رضامندی سے ایسا کیا گیا (واللہ اعلم )۔","صحیح",{"u2":"سیدنا ابوموسیٰ اشعری رضی اللہ عنہ بیان کرتے ہیں کہ ہم لوگ (حبشہ سے) واپس آئے (اور خیبر پہنچے) جبکہ رسول اللہ صلی اللہ علیہ وسلم نے خیبر کو فتح کر لیا تھا تو آپ صلی اللہ علیہ وسلم نے ہم لوگوں کو بھی حصہ دیا یا کہا کہ آپ صلی اللہ علیہ وسلم نے ہمیں بھی اس میں سے کچھ دیا۔ حالانکہ آپ صلی اللہ علیہ وسلم نے فتح خیبر سے غائب رہنے والوں میں سے کسی کو بھی کچھ نہ دیا تھا۔ صرف انہی لوگوں کو دیا جو آپ صلی اللہ علیہ وسلم کے ساتھ حاضر تھے مگر ہم لوگ جو کشتی میں سوار ہو کر آئے تھے۔ سیدنا جعفر رضی اللہ عنہ اور ان کے ساتھیوں کو دیگر مجاہدین کے ساتھ حصہ دیا۔","f2":"یہ عطیہ تو خمس میں سے دیا گیا تھا۔جس کے نبی کریم صلی اللہ علیہ وسلم خود متصرف تھے۔یا دیگر مجاہدین کی رضا مندی سے غنیمت میں دیا گیا تھا تاکہ ان مہاجرین کی دلجوئی ہو۔واللہ اعلم (خطابی)"}],[2726,"عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم کھڑے ہوئے یعنی بدر کے دن اور فرمایا: \"بیشک عثمان اللہ اور اس کے رسول کی ضرورت سے رہ گئے ہیں ۱؎ اور میں ان کی طرف سے بیعت کرتا ہوں\"، پھر رسول اللہ صلی اللہ علیہ وسلم نے ان کے لیے حصہ مقرر کیا اور ان کے علاوہ کسی بھی غیر موجود شخص کو نہیں دیا۔\n§وضاحت\n۱؎ : عثمان رضی اللہ عنہ بدر میں شریک نہیں ہو سکے، کیونکہ آپ کی اہلیہ رقیہ رضی اللہ عنہا جو رسول اللہ صلی اللہ علیہ وسلم کی صاحبزادی ہیں ان ایام میں سخت بیمار تھیں اسی وجہ سے ان کی دیکھ ریکھ کے لئے انہیں رکنا پڑ گیا تھا۔","صحیح",{"u2":"سیدنا عبداللہ بن عمر رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم بدر والے دن کھڑے ہوئے اور فرمایا ” عثمان رضی اللہ عنہ، اللہ کے کام سے اور رسول اللہ کے کام سے گئے ہیں اور میں ان کی بیعت لے رہا ہوں۔ “ پھر آپ صلی اللہ علیہ وسلم نے غنیمت میں سے ان کا حصہ نکالا، اور ان کے سوا غائب رہنے والوں میں سے کسی کو کچھ نہیں دیا۔","f2":"بد رکے موقع پررسول اللہ صلی اللہ علیہ وسلم کی صاحبزادی حضرت عثمان رضی اللہ تعالیٰ عنہ کی ذوجہ محترمہ رقیہ رضی اللہ عنہا بیمار تھیں۔رسول اللہ صلی اللہ علیہ وسلم نے خود انھیں حضرت رقیہ کی خدمت وتمارداری کے لئے پابندفرمایا تھا۔ اور پھر وہ اس بیماری میں وفات پاگئیں تھیں۔اسی بنیاد پر انہیں غنیمت میں حصہ دیا گیا تھا۔البتہ اس میں بعیت والی بات رواوی کا وہم ہے۔ کیونکہ نبی کریم صلی اللہ علیہ وسلم نے حضرت عثمان رضی اللہ تعالیٰ عنہ کی طرف سے بعیت حدیبیہ کے موقع پرلی تھی۔یہاں راوی کو وہم ہوا ہے۔ اور اس نے اسے بدر کے واقعے میں بیان کردیا ہے۔ اس واقعے سے ثابت ہوا کہ جو شخص مجاہدین کی کوئی ذمہ داری ادا کرنے کی وجہ سے قتال میں شریک نہ ہوا اسے بھی غنیمت میں سے حصہ دیا جائے گا۔"}],[2727,"یزید بن ہرمز کہتے ہیں کہ نجدہ ۱؎ نے ابن عباس رضی اللہ عنہما کو خط لکھا وہ ان سے فلاں فلاں چیزوں کے بارے میں پوچھ رہے تھے اور بہت سی چیزوں کا ذکر کیا اور غلام کے بارے میں کہ (اگر جہاد میں جائے) تو کیا غنیمت میں اس کو حصہ ملے گا؟ اور کیا عورتیں نبی اکرم صلی اللہ علیہ وسلم کے ساتھ جہاد میں جاتی تھیں؟ کیا انہیں حصہ ملتا تھا؟ تو ابن عباس رضی اللہ عنہما نے کہا: اگر مجھے اس بات کا ڈر نہ ہوتا کہ وہ احمقانہ حرکت کرے گا تو میں اس کو جواب نہ لکھتا (پھر انہوں نے اسے لکھا:) رہے غلام تو انہیں بطور انعام کچھ دے دیا جاتا تھا، (اور ان کا حصہ نہیں لگتا تھا) اور رہیں عورتیں تو وہ زخمیوں کا علاج کرتیں اور پانی پلاتی تھیں۔\n§وضاحت\n۱؎ : یعنی: نجدہ حروری جو خوارج کا سردار تھا۔","صحیح",{"u2":"یزید بن ہرمز نے بیان کیا کہ نجدہ (حروری، جو کہ خوارج کا سردار تھا) نے سیدنا ابن عباس رضی اللہ عنہ کو کئی سوالات لکھ کر بھیجے۔ ان میں سے ایک یہ تھا کہ کیا غلام کا غنیمت میں کوئی حصہ ہوتا ہے؟ اور عورتوں کے متعلق پوچھا کہ کیا وہ نبی کریم صلی اللہ علیہ وسلم کے ساتھ جہاد میں جایا کرتی تھیں؟ اور کیا غنیمت میں ان کا کوئی حصہ ہے یا نہیں؟ سیدنا ابن عباس رضی اللہ عنہ نے فرمایا: اگر مجھے یہ اندیشہ نہ ہوتا کہ یہ کوئی حماقت کرے گا تو میں اسے جواب نہ دیتا۔ (آپ نے لکھا کہ) غلام کو انعام دیا جاتا تھا، اور عورتیں زخمیوں کا علاج معالجہ کیا کرتی تھیں اور پانی پلایا کرتی تھیں۔"}],[2728,"یزید بن ہرمز کہتے ہیں کہ نجدہ حروری نے ابن عباس رضی اللہ عنہما کو لکھا، وہ عورتوں کے متعلق آپ سے پوچھ رہا تھا کہ کیا وہ رسول اللہ صلی اللہ علیہ وسلم کے ساتھ جنگ میں جایا کرتی تھیں؟ اور کیا آپ ان کے لیے حصہ متعین کرتے تھے؟ عبداللہ بن عباس رضی اللہ عنہما کا خط میں نے ہی نجدہ کو لکھا کہ وہ رسول اللہ صلی اللہ علیہ وسلم کے ساتھ جنگ میں حاضر ہوتی تھیں، رہی ان کے لیے حصہ کی بات تو ان کا کوئی حصہ مقرر نہیں ہوتا تھا البتہ انہیں کچھ دے دیا جاتا تھا۔","صحیح",{"u2":"یزید بن ہرمز نے بیان کیا کہ نجدہ حروری نے سیدنا ابن عباس رضی اللہ عنہ کو لکھا اور پوچھا کہ کیا عورتیں رسول اللہ صلی اللہ علیہ وسلم کے ساتھ جہاد میں جایا کرتیں تھیں؟ اور کیا آپ صلی اللہ علیہ وسلم انہیں غنیمت میں سے کوئی حصہ عنایت فرماتے تھے؟ یزید بن ہرمز کہتے ہیں۔ سیدنا ابن عباس رضی اللہ عنہ کا جواب نجدہ کی طرف میں نے تحریر کیا تھا کہ عورتیں رسول اللہ صلی اللہ علیہ وسلم کے ساتھ جنگ میں شریک ہوتیں تھیں اور یہ کہ انہیں غنیمت میں کوئی حصہ دیا جائے۔ یہ نہیں ہوتا تھا، تاہم انہیں عطیہ و انعام ضرور دیا جاتا تھا۔","f2":"1۔عورتوں اور دیگر خدمت کاروں کئے لئے غنیمت میں باقاعدہ حصہ نہیں ہے۔ مگر ان کی خدمت کی مساسبت سے معقول انعام واکرام ضرور دیا جائئے۔2۔اس سے یہ بات واضح ہوئی کہ عورتوں نے ایک فوجی اور مجاہدین کی حیثیت سے شرکت نہیں کی تھی۔ اگرایسا ہوتا تو انہیں غنیمت میں سے پورا حصہ دیا جاتا۔ان کی حیثیت خدمت گار کی سی تھی۔اور بھی پس پردہ رہ کر 3۔اس سے زندگی کے ہر شعبے میں مرد وزن کی مغربی مساوات کا ہرگز اثبات نہیں ہوتا جیساکہ بعض مغرب زدہ حضرات کرتے ہیں۔"}],[2729,"حشرج بن زیاد اپنی دادی (ام زیاد اشجعیہ) سے روایت کرتے ہیں کہ وہ رسول اللہ صلی اللہ علیہ وسلم کے ساتھ خیبر کی جنگ میں نکلیں، یہ چھ عورتوں میں سے چھٹی تھیں، جب رسول اللہ صلی اللہ علیہ وسلم کو یہ بات پہنچی تو آپ نے ہمیں بلا بھیجا، ہم آئے تو ہم نے آپ کو ناراض دیکھا، آپ صلی اللہ علیہ وسلم نے پوچھا: \"تم کس کے ساتھ نکلیں؟ اور کس کے حکم سے نکلیں؟\" ہم نے کہا: اللہ کے رسول! ہم نکل کر بالوں کو بٹ رہی ہیں، اس سے اللہ کی راہ میں مدد پہنچائیں گے، ہمارے پاس زخمیوں کی دوا ہے، اور ہم مجاہدین کو تیر دیں گے، اور ستو گھول کر پلائیں گے، آپ صلی اللہ علیہ وسلم نے فرمایا: \"اچھا چلو\" یہاں تک کہ جب خیبر فتح ہوا تو آپ صلی اللہ علیہ وسلم نے ہمیں بھی ویسے ہی حصہ دیا جیسے کہ مردوں کو دیا، حشرج بن زیاد کہتے ہیں: میں نے ان سے پوچھا: دادی! وہ حصہ کیا تھا؟ تو وہ کہنے لگیں: کچھ کھجوریں تھیں ۱؎۔\n§وضاحت\n۱؎ : یہ ضعیف روایت ہے اس سے استدلال درست نہیں ہے، کیونکہ صحیح روایت کے مطابق جہاد میں شریک ہونے والی عورتوں کا مال غنیمت میں کوئی متعین حصہ نہیں ہے البتہ انہیں ایسے ہی کچھ دے دیا جاتا ہے۔","ضعیف",{"u2":"سیدنا حشرج بن زیاد اپنی دادی (ام زیاد اشجعیہ رضی اللہ عنہ ا) سے روایت کرتے ہیں کہ وہ رسول اللہ صلی اللہ علیہ وسلم کے ساتھ غزوہ خیبر میں شریک ہوئی تھیں اور وہ چھ میں سے چھٹی عورت تھی، کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم کو خبر ہوئی تو آپ صلی اللہ علیہ وسلم نے ہمیں بلوا بھیجا۔ ہم حاضر خدمت ہوئیں تو ہم نے آپ صلی اللہ علیہ وسلم کو غصے میں دیکھا۔ فرمایا ” تم کس کے ساتھ اور کس کی اجازت سے آئی ہو؟ “ ہم نے کہا: اے اللہ کے رسول! ہم آئی ہیں بال بٹتی ہیں، اور اس سے جہاد میں مدد کرتی ہیں، ہمارے پاس زخمیوں کے لیے دوا دارو بھی ہے، ہم تیر اکٹھے کر کے دیتی ہیں اور ستو پلاتی ہیں۔ تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” جاؤ۔ “ (کوئی بات نہیں) حتیٰ کہ جب اللہ نے آپ صلی اللہ علیہ وسلم کے لیے خیبر فتح کر دیا تو آپ صلی اللہ علیہ وسلم نے ہمیں بھی حصہ عنایت فرمایا جیسے کہ مردوں کو دیا تھا۔ میں نے پوچھا دادی اماں! وہ کیا تھا؟ کہا: کھجور۔"}],[2730,"محمد بن زیاد کہتے ہیں کہ مجھ سے عمیر مولی آبی اللحم نے بیان کیا وہ کہتے ہیں کہ میں جنگ خیبر میں اپنے مالکوں کے ساتھ گیا، انہوں نے میرے سلسلے میں رسول اللہ صلی اللہ علیہ وسلم سے گفتگو کی تو آپ نے مجھے (ہتھیار پہننے اور مجاہدین کے ساتھ رہنے کا) حکم دیا، چنانچہ میرے گلے میں ایک تلوار لٹکائی گئی تو میں اسے (اپنی کم سنی اور کوتاہ قامتی کی وجہ سے زمین پر) گھسیٹ رہا تھا، پھر آپ صلی اللہ علیہ وسلم کو بتایا گیا کہ میں غلام ہوں تو آپ نے مجھے گھر کے سامانوں میں سے کچھ سامان دیئے جانے کا حکم دیا۔ ابوداؤد کہتے ہیں: اس کا مطلب یہ ہے کہ آپ صلی اللہ علیہ وسلم نے ان کے لیے حصہ مقرر نہیں کیا، ابوداؤد کہتے ہیں: انہوں (آبی اللحم) نے اپنے اوپر گوشت حرام کر لیا تھا، اسی وجہ سے ان کا نام آبی اللحم رکھ دیا گیا۔","صحیح",{"u2":"سیدنا عمیر رضی اللہ عنہ جو کہ سیدنا آبی اللحم رضی اللہ عنہ کے غلام تھے، بیان کرتے ہیں کہ میں اپنے مالکوں کے ساتھ غزوہ خیبر میں حاضر ہوا تو انہوں نے میرے متعلق رسول اللہ صلی اللہ علیہ وسلم سے بات کی، تو آپ صلی اللہ علیہ وسلم نے میرے متعلق حکم دیا، میری گردن میں ایک تلوار لٹکا دی گئی، میں اسے گھسیٹنے لگا۔ پھر آپ صلی اللہ علیہ وسلم کو بتایا گیا کہ یہ غلام ہے تو آپ صلی اللہ علیہ وسلم نے میرے متعلق فرمایا اور مجھے گھر کے اسباب میں سے کچھ بطور انعام دیا گیا۔ امام ابوداؤد رضی اللہ عنہ فرماتے ہیں: اس کے معنی یہ ہیں کہ آپ نے غنیمت میں سے حصہ نہیں دیا تھا۔ امام ابوداؤد رضی اللہ عنہ نے کہا ہے: ابو عبید نے بیان کیا کہ راوی حدیث (آبی اللحم) کی وجہ تسمیہ یہ ہے کہ انہوں نے گوشت کو اپنے لیے حرام کر لیا تھا اس لیے انہیں ” آبی اللحم “ کہا جاتا تھا (گوشت سے انکار کرنے والا)۔","f2":"ان کا اصل نام عب اللہ بن عبد الملک بن عبد اللہ بن غفار ہے۔(الاصابہ)"}],[2731,"جابر رضی اللہ عنہ کہتے ہیں کہ میں بدر کے دن (پانی کم ہونے کی وجہ سے) صحابہ کے لیے چلو سے پانی کا ڈول بھر رہا تھا۔","صحیح",{"u2":"سیدنا جابر (بن عبداللہ رضی اللہ عنہ) کا بیان ہے کہ میں بدر کے روز اپنے اصحاب کے لیے کنویں سے پانی بھرتا رہا تھا۔ (کنویں میں اتر کر ہاتھوں سے ڈول بھرتا تھا کیونکہ نیچے پانی کم تھا)۔","f2":"غالبا انہیں اسی خدمت پر انعام دیا گیا۔واللہ اعلم۔"}],[2732,"ام المؤمنین عائشہ رضی اللہ عنہا سے روایت ہے کہ مشرکوں میں سے ایک شخص نبی اکرم صلی اللہ علیہ وسلم سے آ کر ملا تاکہ آپ کے ساتھ مل کر لڑائی کرے تو آپ صلی اللہ علیہ وسلم نے فرمایا: \"لوٹ جاؤ، ہم کسی مشرک سے مدد نہیں لیتے\"۔","صحیح",{"u2":"ام المؤمنین سیدہ عائشہ رضی اللہ عنہا ا بیان کرتی ہیں کہ مشرکین میں سے ایک آدمی نبی کریم صلی اللہ علیہ وسلم سے ملا، تاکہ آپ صلی اللہ علیہ وسلم کے ساتھ مل کر (مشرکین سے) قتال کرے۔ آپ صلی اللہ علیہ وسلم نے فرمایا ” واپس چلے جاؤ۔ “ (یہ الفاظ یحییٰ بن معین کے ہیں۔ اس کے بعد مسدد اور یحییٰ دونوں باتفاق کہتے ہیں کہ) رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” ہم مشرکین سے مدد نہیں لیتے۔ “","f2":"جب مشرکین سے مدد نہیں لی جاتی تو غنیمت میں ان کاحصہ ہی بے معنی ہے۔اور اسلامی سیاست کا بنیادی قاعدہ و اصول یہی ہے کہ مشرکین سے مدد نہ لی جائے۔مگر حصب احوال ومصالح اگر کہیں اضطراری کیفیت ہو تو بمقابلہ کفار مدد لی جاسکتی ہے۔ مسلمانوں کے خلاف نہیں جیسا کہ سفر ہجرت میں رسول اللہ صلی اللہ علیہ وسلم اور حضرت ابو بکر صدیق رضی اللہ تعالیٰ عنہ نے عبد اللہ بن اریقط لیثی۔کی رہنمائی میں اپنا سفر مکمل فرمایا تھا۔ یہ مشرک تھا مگر قابل اعتماد تھا۔ایسی کوئی صورت ہو تو انعام وغیرہ دیا جاسکتا ہے۔واللہ اعلم دیکھئے۔(نیل الاوطار باب ماجاء فی الاستعانۃ بالمشرکین۔254/7)"}],[2733,"عبداللہ بن عمر رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے آدمی اور اس کے گھوڑے کو تین حصہ دیا: ایک حصہ اس کا اور دو حصہ اس کے گھوڑے کا۔","صحیح",{"u2":"سیدنا عبداللہ بن عمر رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے مجاہد اور اس کے گھوڑے کے لیے تین حصے مقرر فرمائے تھے۔ ایک حصہ مجاہد کا اور دو حصے اس کے گھوڑے کے۔","f2":"جہاد میں پیدل جہاد کرنے والے کے مقابلے میں گھوڑ سوار کی کارگردگی عموما بہت زیادہ ہوتی ہے۔اس لئے غنیمت میں گھوڑے کا بھی حصہ رکھا گیا ہے۔فی زمانہ ٹینکوں لڑاکا طیاروں اور دیگر سواریوں کا بھی یہی حکم ہوگا۔"}],[2734,"ابو عمرہ کے والد عبدالرحمٰن بن ابی عمرہ انصاری رضی اللہ عنہ کہتے ہیں کہ ہم چار آدمی رسول اللہ صلی اللہ علیہ وسلم کے پاس آئے اور ہمارے ساتھ ایک گھوڑا تھا، تو آپ نے ہم میں سے ہر آدمی کو ایک ایک حصہ دیا، اور گھوڑے کو دو حصے دئیے۔","صحیح",{"u2":"سیدنا ابو عمرہ اپنے والد سے بیان کرتے ہیں کہ ہم رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوئے ہم چار آدمی تھے اور ہمارے پاس گھوڑا تھا تو آپ صلی اللہ علیہ وسلم نے ہم میں سے ہر ایک کو ایک ایک حصہ اور گھوڑے کو دو حصے عنایت فرمائے۔"}],[2735,"اس سند سے بھی ابو عمرہ سے اسی حدیث کے ہم معنی مروی ہے مگر اس میں یہ ہے کہ ہم تین آدمی تھے اور اس میں یہ اضافہ ہے کہ سوار کو تین حصے ملے تھے۔","صحیح",{"u2":"(جناب مسدد کی سند سے ہے کہ) ابو عمرہ نے مذکورہ بالا حدیث کے ہم معنی بیان کیا مگر اس روایت میں ہے کہ ہم تین اشخاص آئے اور آپ نے گھوڑ سوار کو تین حصے عنایت فرمائے۔"}],[2736,"مجمع بن جاریہ انصاری رضی اللہ عنہ سے روایت ہے اور وہ ان قاریوں میں سے ایک تھے جو قرآت قرآن میں ماہر تھے، وہ کہتے ہیں: ہم صلح حدیبیہ میں رسول اللہ صلی اللہ علیہ وسلم کے ساتھ تھے، جب ہم وہاں سے واپس لوٹے تو لوگ اپنی سواریوں کو حرکت دے رہے تھے، بعض نے بعض سے کہا: لوگوں کو کیا ہو گیا ہے؟ لوگوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم کی طرف وحی کی گئی ہے تو ہم بھی لوگوں کے ساتھ (اپنی سواریوں) کو دوڑاتے اور ایڑ لگاتے ہوئے نکلے، ہم نے نبی اکرم صلی اللہ علیہ وسلم کو اپنی سواری پر کراع الغمیم ۱؎کے پاس کھڑا پایا جب سب لوگ آپ کے پاس جمع ہو گئے تو آپ صلی اللہ علیہ وسلم نے «إنا فتحنا لك فتحا مبينا» پڑھی، تو ایک شخص نے عرض کیا: اللہ کے رسول! کیا یہی فتح ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا: \"ہاں، قسم اس ذات کی جس کے ہاتھ میں میری جان ہے، یہی فتح ہے\"، پھر خیبر کی جنگ میں جو مال آیا وہ صلح حدیبیہ کے لوگوں پر تقسیم ہوا، رسول اللہ صلی اللہ علیہ وسلم نے اس مال کے اٹھارہ حصے کئے اور لشکر کے لوگ سب ایک ہزار پانچ سو تھے جن میں تین سو سوار تھے، آپ صلی اللہ علیہ وسلم نے سواروں کو دو حصے دئیے اور پیدل والوں کو ایک حصہ۔ ابوداؤد کہتے ہیں: ابومعاویہ کی حدیث (نمبر ۲۷۳۳) زیادہ صحیح ہے اور اسی پر عمل ہے، اور میرا خیال ہے مجمع کی حدیث میں وہم ہوا ہے انہوں نے کہا ہے: تین سو سوار تھے حالانکہ دو سو سوار تھے ۲؎۔\n§وضاحت\n۱؎ : مکہ اور مدینہ کے درمیان ایک جگہ کا نام ہے۔ ۲؎ : گویا لشکر کی صحیح تعداد چودہ سو تھی جن میں دو سو سوار تھے، سواروں کو تین تین حصے دئے گئے اور پیدل والوں کو ایک حصہ۔","ضعیف",{"u2":"سیدنا مجمع بن جاریہ انصاری رضی اللہ عنہ سے روایت ہے اور یہ ایسے قاری تھے جنہوں نے پورا قرآن پڑھا تھا، (حفظ کیا تھا) وہ بیان کرتے ہیں کی ہم حدیبیہ میں رسول اللہ صلی اللہ علیہ وسلم کے ساتھ حاضر تھے۔ جب ہم وہاں سے واپس ہونے لگے تو دیکھا کہ لوگ اپنے اونٹوں کو تیز بھگا رہے ہیں، لوگوں نے ایک دوسرے سے پوچھا: کیا بات ہے؟ انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم پر وحی نازل ہوئی ہے، تو ہم بھی لوگوں کے ساتھ اونٹ دوڑاتے ہوئے نکلے۔ ہم نے کراع الغمیم مقام پر دیکھا کہ نبی کریم صلی اللہ علیہ وسلم اپنی سواری پر رکے ہوئے ہیں۔ جب لوگ آپ صلی اللہ علیہ وسلم کے پاس جمع ہو گئے تو آپ صلی اللہ علیہ وسلم نے سورۃ الفتح کی آیات تلاوت فرمائیں «إنا فتحنا لك فتحا مبينا» ” بلاشبہ ہم نے آپ کو واضح فتح دی ہے۔ “ ایک شخص نے پوچھا: اے اللہ کے رسول! کیا یہ فتح ہے؟ فرمایا ” ہاں، اس ذات کی قسم جس کے ہاتھ میں محمد (صلی اللہ علیہ وسلم) کی جان ہے! بلاشبہ یہ فتح ہے۔ “ چنانچہ (بعد میں) خیبر کی غنیمتیں اہل حدیبیہ ہی پر تقسیم کی گئیں۔ آپ صلی اللہ علیہ وسلم نے ان کے اٹھارہ حصے بنائے اور لشکر والوں کی تعداد پندرہ سو تھی جن میں تین سو گھوڑ سوار تھے۔ پس آپ صلی اللہ علیہ وسلم نے گھوڑ سوار کو دو حصے اور پیدل کو ایک حصہ عنایت فرمایا۔ امام ابوداؤد رضی اللہ عنہ فرماتے ہیں: ابومعاویہ کی حدیث زیادہ صحیح ہے اور اسی پر عمل ہے۔ (حدیث 2733) اور مجمع کی روایت ہیں وہم ہے کہ یہ گھوڑ سوار تین سو بتاتے ہیں حالانکہ وہ دو سو تھے۔","f2":"غنائم خیبر کے اٹھارہ حصے یوں بنتے ہیں۔ کہ اگر مجاہدین کی تعدادپندرہ سو اور ان میں گھوڑ سوار تین سو ہوں۔اور ہر گھوڑے کا ایک حصہ شمار کیا جائے۔ تو یہ کل تعداد اٹھارہ سو ہوئی۔ چنانچہ ہر ایک حصہ ایک سو کے لئے ہوا اور گھوڑے کے لئے بھی ایک ہی حصہ دیاگیا۔مگر یہ بات صحیح تر روایات کے خلاف ہے۔ اس اعتبار سے یہ حدیث ضعیف ہے۔جیسا کہ امام ابو دائود نے کہا ہے کہ۔صحیح یہ ہے کہ مجاہدین کی تعداد چودہ سو اور ان میں گھوڑ سواردوسوتھے۔گھوڑے کے لئے دو حصے تھے۔ اس طرح کل حصے جن میں یہ غنیمتیں تقسیم ہوئیں۔اٹھارہ سو بنے۔ہر ایک سو کےلئے ایک حصہ تھا۔اورکل حصے اٹھارہ بنائے گئے۔"}],[2737,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے بدر کے دن فرمایا: \"جس نے ایسا ایسا کیا اس کو بطور انعام اتنا اتنا ملے گا\"، جوان لوگ آگے بڑھے اور بوڑھے جھنڈوں سے چمٹے رہے اس سے ہٹے نہیں، جب اللہ نے مسلمانوں کو فتح دی تو بوڑھوں نے کہا: ہم تمہارے مددگار اور پشت پناہ تھے اگر تم کو شکست ہوتی تو تم ہماری ہی طرف پلٹتے، تو یہ نہیں ہو سکتا کہ یہ غنیمت کا مال تم ہی اڑا لو، اور ہم یوں ہی رہ جائیں، جوانوں نے اسے تسلیم نہیں کیا اور کہا: رسول اللہ صلی اللہ علیہ وسلم نے اسے ہم کو دیا ہے، تب اللہ نے یہ آیت کریمہ «يسألونك عن الأنفال قل الأنفال لله» \"یہ لوگ آپ سے غنیمتوں کا حکم دریافت کرتے ہیں آپ فرما دیجئیے کہ یہ غنیمتیں اللہ کی ہیں اور رسول کی سو تم اللہ سے ڈرو اور اپنے باہمی تعلقات کی اصلاح کرو اور اللہ اور اس کے رسول کی اطاعت کرو اگر تم ایمان والے ہو، بس ایمان والے تو ایسے ہوتے ہیں کہ جب اللہ تعالی کا ذکر آتا ہے تو ان کے قلوب ڈر جاتے ہیں اور جب اللہ کی آیتیں ان کو پڑھ کر سنائی جاتی ہیں تو وہ آیتیں ان کے ایمان کو اور زیادہ کر دیتی ہیں اور وہ لوگ اپنے رب پر توکل کرتے ہیں جو کہ نماز کی پابندی کرتے ہیں اور ہم نے ان کو جو کچھ دیا ہے وہ اس میں سے خرچ کرتے ہیں سچے ایمان والے یہ لوگ ہیں ان کے لیے بڑے درجے ہیں ان کے رب کے پاس اور مغفرت اور عزت کی روزی ہے جیسا کہ آپ کے رب نے آپ کے گھر سے حق کے ساتھ آپ کو روانہ کیا اور مسلمانوں کی ایک جماعت اس کو گراں سمجھتی تھی\" (سورۃ الانفال: ۱-۵) سے «كما أخرجك ربك من بيتك بالحق وإن فريقا من المؤمنين لكارهون» تک نازل فرمائی، پھر ان کے لیے یہی بہتر ہوا، اسی طرح تم سب میری اطاعت کرو، کیونکہ میں اس کے انجام کار کو تم سے زیادہ جانتا ہوں۔\n§وضاحت\n۱؎ : امام اپنے اختیار سے مجاہدین کو غنیمت سے مقررہ حصہ کے سوا بطور تشجیع و ہمت افزائی جو کچھ دیتا ہے اسے نفل کہا جاتا ہے۔","صحیح",{"u2":"سیدنا ابن عباس رضی اللہ عنہ نے بیان کیا کہ رسول اللہ صلی اللہ علیہ وسلم نے بدر کے دن فرمایا ” جس نے ایسے ایسے کیا سے اتنا اتنا انعام (نفل) ملے گا۔ “ چنانچہ نوجوان آگے بڑھے اور بڑی عمر کو لوگ نشانات (یا جھنڈوں) کے پاس رکے رہے۔ جب اللہ تعالیٰ نے ان کو فتح دی تو بزرگوں نے کہا: ہم تمہارا سہارا تھے اگر تمہیں شکست ہوتی تو تم لوگ ہمارے ہی پاس لوٹ کے آتے، ساری غنیمت تم ہی نہ سمیٹ لے جاؤ کہ ہمیں کچھ نہ ملے مگر جوانوں نے انکار کیا اور کہنے لگے: یہ تو وہ چیز ہے جو رسول اللہ صلی اللہ علیہ وسلم نے ہمارے لیے مخصوص فرمائی ہے۔ تب اللہ تعالیٰ نے سورۃ الانفال کی آیات نازل فرمائیں «يسألونك عن الأنفال قل الأنفال لله والرسول» سے لے کر «وإن فريقا من المؤمنين لكارهون» چنانچہ یہ سب ان کے لیے بہتر ہوا اور ایسے فرمایا کہ میری اطاعت کرو، بیشک اس کے انجام کو میں تم سے بہتر جانتا ہوں۔","f2":"1۔سورہ انفال کی ابتدائی پانچ آیتوں کا ترجمہ یہ ہے یہ لوگ آپ صلی اللہ علیہ وسلم سے غنیمتوں کے بارے میں سوال کرتے ہیں۔کہہ دیجئے کہ غنائم کا مالک اللہ ہے۔اور اس کارسول صلی اللہ علیہ وسلم۔سو تم اللہ کا تقویٰ اختیار کرو۔ اور آپس میں صلح سے رہو۔اللہ اور اس کے رسول صلی اللہ علیہ وسلم کی اطاعت کرو۔اگر تم (واقعی) مومن ہو۔ایمان والے تو وہ ہیں جب اللہ کا نام آئے۔ تو ان کے دل ڈر جاتے ہیں۔اور جب ان پر اس کی آیات پڑھی جاتی ہیں۔ تو ان کا ایمان بڑھ جاتا ہے۔ اور وہ اپنے رب پربھروسہ رکھتے ہیں۔ وہ جو نماز قائم کرتے ہیں۔اور جو ہم نے ان کو دیاہے خرچ کرتے ہیں۔یہی لوگ سچے ایمان دار ہیں۔ان کے لئے اپنے رب کے پاس درجات ہیں۔اور مغفرت اورعزت کی روزی ہے۔ جسا کہ آپ کو آپ کے رب نے آپ کوگھر سے حق کے ساتھ نکالا جب کہ مومنوں میں سے ایک جماعت راضی نہ تھی۔ 2۔جہاداور دیگر اعمال خیر میں لوگوں کوشوق دلانے ان کی حوصلہ افزائی اور مزید سبقت کےلئے انعامات دینا مسنون ومستحب ہے۔مگر ان پرواجب ہے کہ اپنی نیتوں کومحض دنیاکےمال ومتاع تک محدود نہ رکھیں۔"}],[2738,"اس سند سے بھی ابن عباس رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے غزوہ بدر کے دن فرمایا: \"جو شخص کسی کافر کو مارے تو اس کے لیے اتنا اور اتنا (انعام) ہے، اور جو کسی کافر کو قید کرے اس کے لیے اتنا اور اتنا (انعام) ہے\"، پھر آگے اسی حدیث کی طرح بیان کیا، اور خالد کی (یعنی: پچھلی حدیث) زیادہ کامل ہے۔","صحیح",{"u2":"سیدنا ابن عباس رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے بدر کے دن فرمایا ” جس نے کسی کو قتل کیا تو اس کے لیے اتنا اتنا انعام ہے اور جو کسی کو پکڑ کر قید کر لے تو اس کے لیے اتنا اتنا ہے۔ “ پھر مذکورہ بالا حدیث کی مانند بیان کیا اور خالد کی حدیث زیادہ کامل ہے۔"}],[2739,"اس سند بھی سے داود سے یہی حدیث اسی طریق سے مروی ہے اس میں ہے: \"رسول اللہ صلی اللہ علیہ وسلم نے اسے برابر برابر تقسیم کیا\"، اور خالد کی حدیث (نمبر ۲۷۳۷) کامل ہے۔","صحیح",{"u2":"(ہارون بن محمد بن بکار کی سند سے مروی ہے) اور داود بن ابی ہند نے یہ حدیث اپنی سند سے روایت کی ہے، انہوں نے کہا کہ رسول اللہ صلی اللہ علیہ وسلم نے غنیمت کو برابر برابر تقسیم کیا۔ اور خالد کی روایت زیادہ کامل ہے۔ (مذکورہ بالا حدیث 2737)۔"}],[2740,"سعد رضی اللہ عنہ کہتے ہیں کہ میں غزوہ بدر کے دن نبی اکرم صلی اللہ علیہ وسلم کے پاس ایک تلوار لے کر آیا اور عرض کیا: اللہ کے رسول! آج اللہ نے میرے سینے کو دشمنوں سے شفاء دی، لہٰذا آپ مجھے یہ تلوار دے دیجئیے، آپ صلی اللہ علیہ وسلم نے فرمایا: \"یہ تلوار نہ تو میری ہے نہ تمہاری\" یہ سن کر میں چلا اور کہتا جاتا تھا: یہ تلوار آج ایسے شخص کو ملے گی جس نے مجھ جیسا کارنامہ انجام نہیں دیا ہے، اسی دوران مجھے قاصد بلانے کے لیے آیا، اور کہا چلو، میں نے سوچا شاید میرے اس بات کے کہنے کی وجہ سے میرے سلسلے میں کچھ وحی نازل ہوئی ہے، چنانچہ میں آیا تو نبی اکرم صلی اللہ علیہ وسلم نے مجھ سے فرمایا: \"تم نے یہ تلوار مانگی جب کہ یہ تلوار نہ تو میری ہے نہ تمہاری، اب اسے اللہ نے مجھے عطا کر دیا ہے، لہٰذا (اب) یہ تمہاری ہے\" پھر آپ صلی اللہ علیہ وسلم نے یہ آیت کریمہ پوری پڑھی«يسألونك عن الأنفال قل الأنفال لله والرسول» ۔ ابوداؤد کہتے ہیں: عبداللہ بن مسعود رضی اللہ عنہ کی قرأت «يسألونك عن النفل» ہے۔","حسن صحیح",{"u2":"سیدنا مصعب بن سعد اپنے والد (سیدنا سعد بن ابی وقاص رضی اللہ عنہ) سے روایت کرتے ہیں انہوں نے بیان کیا کہ بدر کے روز میں ایک تلوار لے کر رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوا اور عرض کیا: اے اللہ کے رسول! اللہ تعالیٰ نے آج دشمن کے مقابلے میں میرا سینہ ٹھنڈا کر دیا ہے، تو آپ یہ تلوار مجھے عنایت فر دیجئیے۔ آپ صلی اللہ علیہ وسلم نے فرمایا ” یہ تلوار نہ میری ہے اور نہ تیری۔ “ چنانچہ میں چلا اور میں کہہ رہا تھا: یہ آج اس آدمی کو دے دی جائے گی جس نے میرے جیسی بہادری نہیں دکھائی ہو گی۔ میں اسی کیفیت میں تھا کہ ایک بلانے والا میرے پاس آیا اور کہا کہ (رسول اللہ صلی اللہ علیہ وسلم کے ہاں) پہنچو۔ میں نے گمان کیا کہ میں نے جو بول بولے ہیں ان کی بنا پر میرے بارے میں کوئی وحی نازل ہوئی ہو گی۔ چنانچہ میں آیا تو نبی کریم صلی اللہ علیہ وسلم نے مجھ سے فرمایا ” تو نے مجھ سے یہ تلوار مانگی تھی، حالانکہ یہ نہ میری ہے نہ تیری اور (اب) اللہ عزوجل نے اسے مجھے دے دیا ہے، سو (اب) یہ تیری ہے۔ “ پھر آپ صلی اللہ علیہ وسلم نے سورۃ الانفال کی یہ آیت تلاوت فرمائی۔) «يسألونك عن الأنفال قل الأنفال لله والرسول» آخر آیت تک۔ امام ابوداؤد رضی اللہ عنہ فرماتے ہیں سیدنا ابن مسعود رضی اللہ عنہ کی قرآت میں ہے۔ «يسألونك النفل» (بغیر عن کے اور مفرد صیغہ کے ساتھ)۔","f2":"معروف قراءت میں (يَسْأَلُونَكَ عَنِ الْأَنفَالِ) کے معنی ہیں۔ لوگ آپ سے غنیمتوں کا حکم پوچھتے ہیں۔ اور حضرت ابن مسعود رضی اللہ تعالیٰ عنہ کی قراءت (يسالونك النفل)کا ترجمہ ہے۔ لوگ آپ صلی اللہ علیہ وسلم سے نفل کا سوال کرتے ہیں۔(مزیداضافی انعام کا)"}],[2741,"عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے ہمیں نجد کی جانب ایک لشکر میں بھیجا اور اس لشکر کا ایک دستہ دشمن سے مقابلہ کے لیے بھیجا گیا، پھر لشکر کے لوگوں کو بارہ بارہ اونٹ ملے اور دستہ کے لوگوں کو ایک ایک اونٹ بطور انعام زیادہ ملا تو ان کے حصہ میں تیرہ تیرہ اونٹ آئے۔","صحیح",{"u2":"سیدنا عبداللہ بن عمر رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے ہمیں ایک لشکر میں نجد کی طرف روانہ کیا اور اس میں سے ایک دستہ دشمن کے مقابلے میں گیا۔ چنانچہ لشکر والوں کو بارہ بارہ اونٹ ملے لیکن اس دستے میں شریک مجاہدوں کو ایک ایک اونٹ مزید دیا گیا، اس طرح ان کا حصہ تیرہ تیرہ اونٹ ہو گیا۔","f2":"لشکر میں سے کوئی دستہ جب کوئی خاص کاروائی کرے۔تو اس کی مناسبت سے اسے اضافی انعام دینا مستحب ہے۔جب کہ عام غنیمت میں سبھی شریک ہوں گے۔"}],[2742,"ولید بن مسلم کہتے ہیں: میں نے ابن مبارک سے یہی حدیث بیان کی، میں نے کہا اور اسی طرح ہم سے ابن ابی فروہ نے نافع کے واسطہ سے بیان کیا ہے تو ابن مبارک نے کہا: جن کا نام تم نے لیا ہے وہ مالک کے برابر نہیں ہو سکتے اسی طرح یا اس جیسی بات انہوں نے کہی، اس سے وہ امام مالک بن انس کو مراد لے رہے تھے۔","صحیح",{"u2":"ولید بن عتبہ دمشقی کہتے ہیں کہ ولید بن مسلم نے کہا: میں نے ابن مبارک سے یہ حدیث بیان کی۔ میں نے کہا: ہمیں ابن ابی فروہ نے بھی نافع سے یہ روایت بیان کی ہے۔ ابن مبارک نے کہا: یہ لوگ، جن کا تم نے نام لیا ہے، مالک بن انس کے برابر نہیں ہو سکتے۔ (امام مالک رضی اللہ عنہ کی روایت راجح ہے)۔"}],[2743,"اس سند سے بھی ابن عمر رضی اللہ عنہما سے روایت ہے، وہ کہتے ہیں رسول اللہ صلی اللہ علیہ وسلم نے ایک سریہ ۱؎ نجد کی جانب بھیجا، میں بھی اس کے ساتھ نکلا، ہمیں بہت سے اونٹ ملے، تو ہمارے دستہ کے سردار نے ایک ایک اونٹ ہم میں سے ہر شخص کو بطور انعام دیا، پھر ہم رسول اللہ صلی اللہ علیہ وسلم کے پاس آئے، آپ نے ہمارے غنیمت کے مال کو ہم میں تقسیم کیا، تو ہر ایک کو ہم میں سے خمس کے بعد بارہ بارہ اونٹ ملے، اور وہ اونٹ جو ہمارے سردار نے دیا تھا، آپ صلی اللہ علیہ وسلم نے اس کو حساب میں شمار نہ کیا، اور نہ ہی آپ نے اس سردار کے عمل پر طعن کیا، تو ہم میں سے ہر ایک کو اس کے نفل سمیت تیرہ تیرہ اونٹ ملے۔\n§وضاحت\n۱؎ : سریہ ایسی فوجی کاروائی جس میں رسول صلی اللہ علیہ وسلم نے شرکت نہیں فرمائی، اور غزوہ ایسی جنگ جس میں آپ نے شرکت فرمائی۔","صحیح",{"u2":"سیدنا ابن عمر رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے ایک دستہ نجد کی جانب روانہ کیا، میں بھی ان کے ساتھ تھا۔ ہمیں بہت سے جانور ہاتھ آئے تو ہمارے امیر نے ہم میں سے ہر ہر شخص کو ایک ایک اونٹ بطور نفل دیا۔ پھر ہم رسول اللہ صلی اللہ علیہ وسلم کے پاس پہنچے اور آپ صلی اللہ علیہ وسلم نے ہم میں ہماری غنیمتیں تقسیم کیں تو ہم میں سے ہر ہر شخص کو خمس نکالنے کے بعد بارہ بارہ اونٹ ملے اور ہمارے امیر نے جو ہمیں دیا تھا اس کا رسول اللہ صلی اللہ علیہ وسلم نے کوئی محاسبہ نہ فرمایا اور نہ اس کی کاروائی پر کوئی عیب لگایا، اس طرح ہمیں نفل سمیت تیرہ تیرہ اونٹ ملے۔"}],[2744,"اس سند سے بھی عبداللہ بن عمر رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے نجد کی طرف ایک سریہ بھیجا جس میں عبداللہ بن عمر رضی اللہ عنہما بھی تھے، ان لوگوں کو غنیمت میں بہت سے اونٹ ملے، ان میں سے ہر ایک کے حصہ میں بارہ بارہ اونٹ آئے، اور ایک ایک اونٹ انہیں بطور نفل (انعام) دئیے گئے۔ ابن موہب کی روایت میں یہ اضافہ ہے: تو رسول اللہ صلی اللہ علیہ وسلم نے اس تقسیم کو بدلا نہیں۔","صحیح",{"u2":"سیدنا عبداللہ بن عمر رضی اللہ عنہ کا بیان ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے ایک دستہ نجد کی طرف روانہ فرمایا جس میں عبداللہ بن عمر رضی اللہ عنہ بھی شامل تھے۔ تو ان لوگوں کو بہت بڑی تعداد میں اونٹ حاصل ہوئے۔ چنانچہ لشکر کے مجاہدین کا حصہ بارہ بارہ اونٹ ہوا اور ایک ایک اونٹ بطور نفل مزید دیے گئے۔ ابن موہب نے مزید کہا کہ (امیر کی تقسیم میں) رسول اللہ صلی اللہ علیہ وسلم نے کوئی تبدیلی نہ فرمائی۔"}],[2745,"اس سند سے بھی عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے ہمیں ایک سریہ میں بھیجا، تو ہمارے حصہ میں بارہ بارہ اونٹ آئے، اور ایک ایک اونٹ رسول اللہ صلی اللہ علیہ وسلم نے ہمیں بطور انعام دیا۔ ابوداؤد کہتے ہیں: اسے برد بن سنان نے نافع سے عبیداللہ کی حدیث کے ہم مثل روایت کیا ہے اور اسے ایوب نے بھی نافع سے اسی کے مثل روایت کیا، مگر اس میں یہ ہے کہ ہمیں ایک ایک اونٹ بطور نفل دئیے گئے اور انہوں نے نبی اکرم صلی اللہ علیہ وسلم کا ذکر نہیں کیا ہے۔","صحیح",{"u2":"سیدنا عبداللہ بن عمر رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے ہمیں ایک دستے میں روانہ کیا تو ہمارے حصے میں بارہ بارہ اونٹ آئے۔ اور رسول اللہ صلی اللہ علیہ وسلم نے ہمیں ایک ایک اونٹ مزید بطور نفل عنایت فرمایا۔ امام ابوداؤد رضی اللہ عنہ فرماتے ہیں: اس روایت کو برد بن سنان نے بواسطہ نافع، عبیداللہ کی حدیث کی مانند روایت کیا ہے۔ اور ایوب نے بھی نافع سے اسی طرح روایت کیا ہے مگر اس روایت میں ہے کہ &rdquo; ہمیں ایک ایک اونٹ بطور نفل دیا گیا۔ &ldquo; اس میں نبی کریم صلی اللہ علیہ وسلم کا ذکر نہیں ہے۔","f2":"مذکورہالا احادیث میں جمع وتطبیق یہی ہے۔کہ امیر نے جو انعام دیا۔رسول اللہ صلی اللہ علیہ وسلم نے اس کی توثیق فرمائی۔جس کو براہ راست رسول اللہ صلی اللہ علیہ وسلم کی طرف منسوب کردیا گیا جو صحیح ہے۔"}],[2746,"عبداللہ بن عمر رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم جن سریوں کو بھیجتے انہیں عام لشکر کی تقسیم کے علاوہ بطور نفل خاص طور سے کچھ دیتے تھے اور خمس ان تمام میں واجب ہوتا ۱؎۔\n§وضاحت\n۱؎ : یعنی پہلے پورے مال میں سے خمس نکالتے پھر انعام کچھ دینا ہوتا دیتے پھر باقی عام لشکر میں برابر تقسیم کرتے۔","صحیح",{"u2":"سیدنا عبداللہ بن عمر رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم (بڑے لشکر میں سے) جب چھوٹے دستوں کو بھیجتے تو ان لوگوں کو عام لشکر میں تقسیم ہونے والی غنیمت کے علاوہ خاص نفل (اضافی انعام) بھی دیا کرتے تھے۔ اور خمس مجموعی غنیمت میں سے نکالنا واجب ہے۔"}],[2747,"عبداللہ بن عمرو رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم بدر کے دن تین سو پندرہ افراد کے ہم راہ نکلے تو آپ نے یہ دعا فرمائی: «اللهم إنهم حفاة فاحملهم اللهم إنهم عراة فاكسهم اللهم إنهم جياع فأشبعهم» \"اے اللہ! یہ لوگ پیدل ہیں تو ان کو سوار کر دے، اے اللہ! یہ لوگ ننگے ہیں ان کو کپڑا دیدے، اے اللہ! یہ لوگ بھوکے ہیں ان کو آسودہ کر دے\"، پھر اللہ نے بدر کے دن انہیں فتح دی، جب وہ لوٹے تو کوئی بھی آدمی ان میں سے ایسا نہ تھا جو ایک یا دو اونٹ لے کر نہ آیا ہو، اور ان کے پاس کپڑے بھی ہو گئے اور وہ آسودہ بھی ہو گئے۔","حسن",{"u2":"سیدنا عبداللہ بن عمرو رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم بدر کے روز تین سو پندرہ اشخاص کو لے کر روانہ ہوئے۔ آپ صلی اللہ علیہ وسلم نے دعا فرمائی ” اے اللہ! یہ لوگ پیدل ہیں، انہیں سواریاں دے، اے اللہ! یہ لوگ بے لباس ہیں، انہیں لباس عنایت فر، اے اللہ! بھوکے ہیں انہیں سیر فر۔ “ چنانچہ اللہ تعالیٰ نے آپ صلی اللہ علیہ وسلم کو بدر میں فتح عنایت فرمائی۔ پس جب یہ لوگ واپس ہوئے تو ان میں سے ہر ایک کے پاس ایک ایک یا دو دو اونٹ تھے، انہیں کپڑے بھی ملے اور طعام سے بھی سیر ہوئے۔"}],[2748,"حبیب بن مسلمہ فہری رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم (مال غنیمت میں سے) خمس (پانچواں حصہ) نکالنے کے بعد ثلث (ایک تہائی) بطور نفل (انعام) دیتے تھے ۱؎۔\n§وضاحت\n۱؎ : یعنی پہلے کل مال میں سے خمس (پانچواں حصہ) نکال لیتے پھر باقی میں سے ایک تہائی انعام میں دیتے اور دو تہائی بانٹ دیتے۔","صحیح",{"u2":"سیدنا خبیب بن مسلمہ فہری رضی اللہ عنہ نے بیان کیا کہ رسول اللہ صلی اللہ علیہ وسلم (غنیمت میں سے) پانچواں حصہ نکالنے کے بعد تیسرا حصہ نفل یعنی اضافی انعام کے طور پر تقسیم فرمایا کرتے تھے۔","f2":"کفار سے مقابلے میں حاصل ہونے والے مال واسباب کو غنیمت کہا جاتا ہے۔اس میں سے پانچواں حصہ اللہ کے نام کاہوتا ہے۔جسے عربی میں خمس کہتےہیں۔رسول اللہ صلی اللہ علیہ وسلم یہ حصہ اپنے صوابدید پر پانچ جگہ خرچ کرسکتےتھے۔اس مسئلے کا زکر دسویں پارے کی ابتداء میں ہواہے۔\n(وَاعْلَمُوا أَنَّمَا غَنِمْتُم مِّن شَيْءٍ فَأَنَّ لِلَّـهِ خُمُسَهُ وَلِلرَّسُولِ وَلِذِي الْقُرْبَىٰ وَالْيَتَامَىٰ وَالْمَسَاكِينِ وَابْنِ السَّبِيلِ)(الانفال۔41)\nیہ جان لو کہ تمھیں جو کچھ بھی غنیمت میں ملے اس سے پانچواں حصہ اللہ کا ہے۔اور رسول صلی اللہ علیہ وسلم کا ہے۔اور قرابت داروں یتیموں اور مسکینوں اور مسافروں کاہے۔ بقیہ غنیمت کو مجاہدین میں تقسیم کیاجاتاہے۔پیدل کو ایک حصہ اور سوار کو مذید دو حصے ملتے ہیں۔اور کافروں سے بغیرلڑے بھڑے حاصل ہونے والے مال کو فے تعبیر کیاجاتاہے۔اور ا س کا مصرف بھی تقریبا یہی ہے۔(دیکھئے۔سورۃ الحشر آیات۔6وما بعد)"}],[2749,"حبیب بن مسلمہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم خمس نکالنے کے بعد ربع (ایک چوتھائی) بطور نفل دیتے تھے (ابتداء جہاد میں) اور جب جہاد سے لوٹ آتے (اور پھر ان میں سے کوئی گروہ کفار سے لڑتا) تو خمس نکالنے کے بعد ایک تہائی بطور نفل دیتے۔","صحیح",{"u2":"سیدنا حبیب بن مسلمہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم خمس نکالنے کے بعد شروع میں (پہلی مرتبہ) چوتھا حصہ بطور نفل (اضافی انعام) دیا کرتے تھے۔ اور غزوے سے لوٹتے وقت (دوبارہ لشکر کشی میں) تیسرا حصہ دیا کرتے تھے خمس نکال لینے کے بعد۔","f2":"مذکورہ حدیث میں (اذا قفل) اور اگلی روایت میں (فی الرحمۃ)(لوٹتے وقت) کے معنی یہ ہیں کہ جب لشکر ایک بار دشمن پر حملہ کرچکا ہوتا۔۔۔بعد ازاں دوبارہ اس پرحملہ کرتا۔۔۔اس کا مطلب امام خطابی کے نزدیک یہ ہے۔کہ جب لشکر کسی علاقے میں جہاد کےلئے جاتا۔ تو اس میں سے کوئی ایک گروہ بڑے لشکر سے الگ ہوکر کسی محدود جنگ کےلئےجاتا تو نبی کریم صلی اللہ علیہ وسلم اس گروہ میں شامل افراد کو چوتھا حصہ بطور نفل دیتے۔جب کے بڑے لشکر کے لوگوں کواس کے تین چوتھائی میں حصہ دیتے۔اور اگر واپسی میں اس طرح کا کوئی چھوٹا گروہ بڑے لشکر سے الگ ہوکر کسی جگہ کےلئے معرکہ آرائی کے لئے جاتا تو واپسی پر جب کہ گھر کا شوق دید بے قراری میں بدل چکا ہوتا۔ علاوہ ازیں دشمن بھی زیادہ چوکس او ر مستعد ہوجاتا ہے۔چونکہ زیادہ پرمشقت اورزیادہ صبرآزما ہوتا۔تو نبی کریم صلی اللہ علیہ وسلم اس گروہ کوتیسرا حصہ دیتے۔واللہ اعلم۔(خظابی۔نیل الاوطار)"}],[2750,"مکحول کہتے ہیں میں مصر میں قبیلہ بنو ہذیل کی ایک عورت کا غلام تھا، اس نے مجھے آزاد کر دیا، تو میں مصر سے اس وقت تک نہیں نکلا جب تک کہ اپنے خیال کے مطابق جتنا علم وہاں تھا اسے حاصل نہ کر لیا، پھر میں حجاز آیا تو وہاں سے بھی اس وقت تک نہیں نکلا جب تک کہ جتنا علم وہاں تھا اپنے خیال کے مطابق حاصل نہیں کر لیا، پھر عراق آیا تو وہاں سے بھی اس وقت تک نہیں نکلا جب تک کہ اپنے خیال کے مطابق جتنا علم وہاں تھا اسے حاصل نہ کر لیا، پھر میں شام آیا تو اسے بھی اچھی طرح چھان مارا، ہر شخص سے میں نفل کا حال پوچھتا تھا، میں نے کسی کو نہیں پایا جو اس سلسلہ میں کوئی حدیث بیان کرے، یہاں تک کہ میں ایک شیخ سے ملا جن کا نام زیاد بن جاریہ تمیمی تھا، میں نے ان سے پوچھا: کیا آپ نے نفل کے بارے میں کچھ سنا ہے؟ کہا: ہاں! میں نے حبیب بن مسلمہ فہری رضی اللہ عنہ کو کہتے سنا ہے کہ میں رسول اللہ صلی اللہ علیہ وسلم کے ساتھ حاضر تھا آپ صلی اللہ علیہ وسلم نے ابتداء میں ایک چوتھائی بطور نفل دیا اور لوٹ آنے کے بعد (پھر حملہ کرنے پر) ۱؎ ایک تہائی بطور نفل دیا۔\n§وضاحت\n۱؎ : اس لئے کہ لوٹ آنے کے بعد پھر لڑنے کے لئے جانا سخت اور دشوار عمل ہے کیونکہ دشمن چوکنا اور محتاط ہو جاتا ہے۔","صحیح",{"u2":"سیدنا مکحول (شامی رضی اللہ عنہ) بیان کرتے ہیں کہ میں مصر میں بنی ہذیل کی ایک عورت کا غلام تھا۔ اس نے مجھے آزاد کر دیا۔ پھر میں وہاں (مصر) سے اس وقت تک نہیں نکلا جب تک کہ اپنی دانست کے مطابق وہاں کے علماء سے تمام کا تمام علم حاصل نہیں کر لیا۔ پھر میں حجاز آیا اور ہاں سے اس وقت تک نہیں نکلا جب تک کہ اپنی دانست کے مطابق وہاں کا تمام علم جمع نہیں کر لیا۔ پھر عراق آیا اور وہاں سے اس وقت تک نہیں نکلا جب تک کہ اپنی دانست کے مطابق وہاں کا تمام علم جمع نہیں کر لیا۔ پھر میں شام آیا اور اس (کے علماء) کو خوب کریدا اور ہر ایک سے میں غنیمت میں نفل (اضافی انعام) کے متعلق سوال کرتا رہا تو مجھے کوئی نہ ملا جو مجھے اس بارے میں کچھ بتاتا۔ بالآخر میں ایک شیخ سے ملا جس کا نام زیاد بن جاریہ تمیمی تھا، میں نے اس سے پوچھا: کیا آپ نے نفل کے متعلق کچھ سنا ہے؟ اس نے کہا: ہاں! میں نے حبیب بن مسلمہ فہری رضی اللہ عنہ کو بیان کرتے ہوئے سنا ہے، فر رہے تھے: میں نبی کریم صلی اللہ علیہ وسلم کے ہاں حاضر تھا کہ آپ نے شروع جہاد میں چوتھا حصہ اور لوٹتے وقت (دوسری بار حملہ کرنے کی صورت میں) تیسرا حصہ بطور نفل (اضافی انعام) عنایت فرمایا تھا۔","f2":"1۔یہ احادیث اسی امر پرمحمول ہیں۔کہ غنیمت میں سے پہلے اللہ اور اس کے رسول صلی اللہ علیہ وسلم کا حصہ (خمس) نکال لیا گیا تھا۔تب غنیمت تقیسم ہوئی۔اور اضافی انعامات بھی دیئے گئے۔2۔جناب مکحول شامی معروف اور ثقہ تابعین میں سے ہیں۔ علم دین کی برکت سے اللہ عزوجل نے انہیں غلامی کی پستی سے نکال کر امت مسلمہ کی امامت کا بلند مقام عطا فرمایا۔"}],[2751,"عبداللہ بن عمرو رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"مسلمانوں کے خون برابر ہیں ۱؎ ان میں سے ادنی شخص بھی کسی کو امان دے سکتا ہے، اور سب کو اس کی امان قبول کرنی ہو گی، اسی طرح دور مقام کا مسلمان پناہ دے سکتا ہے (گرچہ اس سے نزدیک والا موجود ہو) اور وہ اپنے مخالفوں کے لیے ایک ہاتھ کی طرح ہیں ۲؎ جس کی سواریاں زور آور اور تیز رو ہوں وہ (غنیمت کے مال میں) اس کے برابر ہو گا جس کی سواریاں کمزور ہیں، اور لشکر میں سے کوئی سریہ نکل کر مال غنیمت حاصل کرے تو لشکر کے باقی لوگوں کو بھی اس میں شریک کرے، کسی مسلمان کو کافر کے بدلے قتل نہ کیا جائے اور نہ ہی کسی ذمی کو\"۔ ابن اسحاق نے «القود» ۳؎ اور«التكافؤ» کا ذکر نہیں کیا ہے۔\n§وضاحت\n۱؎ : یعنی شریف اور رذیل کے درمیان کوئی فرق نہیں کیا جائے گا۔ ۲؎ : یعنی مسلمان آپس میں بھائی بھائی ہوں گے ایک دوسرے کی مدد کریں گے اور سب مل کر غیروں کا مقابلہ کریں گے۔ ۳؎ : اس سے مراد «لا يقتل مؤمن بكافر» کا جملہ ہے۔","حسن صحیح",{"u2":"سیدنا عمرو بن شعیب اپنے والد سے وہ (شعیب) اپنے دادا سے روایت کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ” سب مسلمانوں کے خون آپس میں برابر ہیں۔ (حدود کے نفاذ میں معزز اور غیر معزز کا کوئی فرق نہیں) ان میں سے جو بھی کسی کافر کو امان دیدے تو ان کا ادنیٰ فرد بھی اس کا پاس رکھے (جیسے کہ اعلیٰ رکھتے ہیں) اور ان میں کا دور والا بھی امان دے سکتا ہے (جیسے کہ مرکز میں رہنے والا) تمام مسلمان کفار کے مقابلے میں ایک ہاتھ ہیں ‘ ان کا تنومند اور قوی رفتار اپنے ضعیف اور سست رفتار کو بھی ساتھ ملائے اور چھوٹے دستے میں جانے والا بڑے لشکر میں رہ جانے والوں کو بھی شریک سمجھے ‘ کسی مومن کو کافر کے بدلے میں یا کسی عہد والے کو جب تک کہ اس کا عہد باقی ہو قتل کرنا روا نہیں۔ “ ابن اسحٰق نے اپنی روایت میں قصاص اور خون برابر ہونے کا ذکر نہیں کیا۔","f2":"یہ اس صورت میں ہے۔کہ جہاد میں نکلتے ہوئے بڑے لشکر میں سے کسی دستے کو علیحدہ کرکے کسی خاص مہم پر بھیجاجائے۔لیکن اگر مرکز ہی سے کسی چھوٹے دستے کو روانہ کیاگیا ہواور بڑے لشکر سے علیحدہ نہ کیا گیا ہو تو اس میں دوسروں کا حصہ نہ ہوگا۔"}]]);
